const POST_TEXT_MAX = 2000;

// --- Lazy script loading -------------------------------------------------
// Heavy third-party libraries used by ONE screen each (the article editor, the
// dev dashboard chart, the contact form) plus the 220KB emoji table used to
// live in index.html's <head> as blocking <script> tags. That meant ~1MB of JS
// had to download and parse before the app could paint, on every launch, for
// features most sessions never open. They're fetched here on first use instead.
//
// NOTE: this deliberately does nothing to caching -- these are plain <script>
// tags, so the service worker and the HTTP cache handle them exactly as they
// did when they were in the <head>. The only change is WHEN they're requested.
const _loadedScripts = {};
function loadScriptOnce(src) {
    // One promise per URL, cached: concurrent callers share a single request,
    // and a library is never fetched or evaluated twice.
    if (_loadedScripts[src]) return _loadedScripts[src];

    _loadedScripts[src] = new Promise((resolve, reject) => {
        const el = document.createElement('script');
        el.src = src;
        el.async = true;
        // Matches the referrerpolicy the TinyMCE tag carried in the <head>; its
        // CDN checks the referrer against the API key's allowed domains.
        el.referrerPolicy = 'origin';
        el.onload = () => resolve();
        el.onerror = () => {
            // Drop the rejected promise so a later attempt can retry rather
            // than replaying the failure forever (e.g. a dropped connection).
            delete _loadedScripts[src];
            reject(new Error('Failed to load ' + src));
        };
        document.head.appendChild(el);
    });
    return _loadedScripts[src];
}

