// When the optimistic bubble was drawn, and how long its entry animation runs.
// Built bubble elements, keyed by message id, for the thread named by
// dmNodeCacheOwner. Lets a re-render move existing nodes instead of rebuilding
// every one of them; see the signature check in renderChatMessages().
const dmNodeCache = new Map();
let dmNodeCacheOwner = null;

// MSG_FLY_IN_MS must match the `msg-fly-in` duration in style.css.
let lastOptimisticRenderAt = 0;
const MSG_FLY_IN_MS = 350;

// When each message's fly-in started, keyed `${scope}:${id}`. Both renderers
// rebuild or move bubbles on almost any event, and a rebuild inside those 350ms
// used to drop the class and snap the bubble into place -- so a message could
// lose its pop to whatever happened to render next. With the start time kept
// here, a rebuilt bubble resumes the animation where it was (negative delay)
// instead.
const messageEntryStartedAt = new Map();

function applyEntryAnimation(el, key, start) {
    const now = performance.now();
    let started = messageEntryStartedAt.get(key);
    if (start && started === undefined) {
        started = now;
        messageEntryStartedAt.set(key, started);
    }
    if (started === undefined) {
        el.classList.remove('animate-entry');
        return;
    }
    const elapsed = now - started;
    if (elapsed >= MSG_FLY_IN_MS) {
        messageEntryStartedAt.delete(key);
        el.classList.remove('animate-entry');
        el.style.animationDelay = '';
        return;
    }
    el.style.animationDelay = `${-elapsed}ms`;
    el.classList.add('animate-entry');
}

// An image or sticker has no height until it decodes, so its fly-in played on an
// empty box and the picture just appeared once the pop was over. Hold the bubble
// invisible until the picture is ready and start the pop from there -- capped,
// so a slow image still arrives. A rebuild while waiting waits again (by then
// the picture is usually cached, so it goes straight away).
const messageEntryWaitingForMedia = new Set();
const MEDIA_ENTRY_WAIT_MS = 1200;

function holdEntryForMedia(el, key) {
    if (!el.classList.contains('animate-entry')) return;
    const img = el.querySelector('img.chat-media');
    if (!img || (img.complete && img.naturalWidth)) {
        messageEntryWaitingForMedia.delete(key);
        return;
    }
    const started = messageEntryStartedAt.get(key);
    const fresh = started !== undefined && performance.now() - started < 50;
    if (!fresh && !messageEntryWaitingForMedia.has(key)) return; // already visibly mid-flight

    messageEntryWaitingForMedia.add(key);
    el.classList.remove('animate-entry');
    el.classList.add('entry-waiting');

    let done = false;
    const go = (settled) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        // A newer copy of this bubble may have taken over; only the live one counts.
        if (!el.isConnected) return;
        messageEntryWaitingForMedia.delete(key);
        // The picture has its real height now, so do what a text message does on
        // arrival: pop in AND slide the thread up to it. Flag the image so the
        // media re-pin and the renderer's after-image scroll -- both listening to
        // this same load, after us -- don't snap the thread over the slide. On the
        // timeout path the picture is still coming, so they stay in charge.
        if (settled) img.dataset.entryHandled = '1';
        messageEntryStartedAt.set(key, performance.now());
        el.classList.remove('entry-waiting');
        el.style.animationDelay = '';
        void el.offsetWidth; // restart the animation from its first frame
        el.classList.add('animate-entry');
        slideThreadToNewest(key.startsWith('dm:') ? 'dm' : 'lounge');
    };
    const timer = setTimeout(() => go(false), MEDIA_ENTRY_WAIT_MS);
    img.addEventListener('load', () => go(true), { once: true });
    img.addEventListener('error', () => go(true), { once: true });
}

// The same smooth follow-the-conversation scroll the renderers do for a new
// message, for one whose height only arrived with its picture.
function slideThreadToNewest(scope) {
    const dm = scope === 'dm';
    const body = document.getElementById(dm ? 'chat-body' : 'lounge-body');
    if (!body || !(dm ? dmStickToBottom : loungeStickToBottom)) return;
    if (dm) {
        lastDmAutoScrollAt = Date.now();
        beginProgrammaticDmScroll();
    } else {
        lastLoungeAutoScrollAt = Date.now();
        beginProgrammaticLoungeScroll();
    }
    body.scrollTo({ top: body.scrollHeight, behavior: 'smooth' });
    syncInstagramGradients(dm ? 'chat-body' : 'lounge-body');
}

// The optimistic bubble's temp id gives way to the server's id mid-animation.
function transferEntryAnimation(scope, fromId, toId) {
    const started = messageEntryStartedAt.get(`${scope}:${fromId}`);
    if (started !== undefined) messageEntryStartedAt.set(`${scope}:${toId}`, started);
    // Still waiting for its picture: the rebuilt bubble keeps waiting too.
    if (messageEntryWaitingForMedia.delete(`${scope}:${fromId}`)) {
        messageEntryWaitingForMedia.add(`${scope}:${toId}`);
    }
}

// The first message of a thread always flies in, whichever render draws it.
// "First" means the thread was on screen empty (for a moment -- not the empty
// frame while its history is still loading) and now holds exactly one message.
const threadRenderCounts = {};

function isFirstMessageOfThread(scope, key, count) {
    const prev = threadRenderCounts[scope];
    const now = performance.now();
    const sameThread = !!prev && prev.key === key;
    threadRenderCounts[scope] = {
        key,
        count,
        emptySince: count === 0 ? (sameThread && prev.count === 0 ? prev.emptySince : now) : null
    };
    return sameThread && prev.count === 0 && count === 1 && now - prev.emptySince >= 500;
}

// ---------------------------------------------------------------------------
// "Is the thread following new messages?" -- an INTENT, not a measurement.
// ---------------------------------------------------------------------------
// Every render used to answer this by reading chatBody.scrollTop at the instant
// a message arrived. That read is wrong whenever the view is already moving:
// the previous message's fly-in scrolls with behavior:'smooth', which takes a
// few hundred milliseconds, and for that whole window scrollTop is nowhere near
// the bottom. So a second message landing during it was judged "user has
// scrolled up", rendered with preserveScroll, and -- worse -- the restore that
// preserveScroll performs CANCELS the running smooth scroll and pins the view
// mid-history. From then on every further message read as "scrolled up" too, so
// they piled up below the fold with nothing on screen changing, until something
// finally scrolled and dumped the lot at once.
//
// A desktop rebuilds and scrolls inside a frame or two, so the window barely
// exists; a phone is slow enough to lose the race constantly, and its images lay
// out after the scroll, which shortens scrollHeight-vs-scrollTop even further.
// That is why this only ever showed up on mobile.
//
// The fix is to stop measuring. The user is following the conversation until
// THEY scroll away from the bottom, and scrolls we perform ourselves don't count.
let dmStickToBottom = true;
// Our own scrolls fire scroll events all the way down; ignore those, or a smooth
// scroll would unstick the thread halfway through its own animation.
let dmProgrammaticScrollUntil = 0;
// Generous on purpose: sub-pixel scroll positions, safe-area insets and an image
// that finishes laying out after the scroll all leave a phone a handful of pixels
// short of a bottom it is visually sitting on.
const DM_BOTTOM_THRESHOLD = 120;
// Long enough to cover a smooth scroll plus the render that follows it.
const DM_PROGRAMMATIC_SCROLL_MS = 800;
// When we last moved the thread ourselves, so a burst of messages can be told from
// a single one and scrolled instantly rather than animated.
let lastDmAutoScrollAt = 0;

function isNearBottom(el, threshold = DM_BOTTOM_THRESHOLD) {
    if (!el) return true;
    return el.scrollTop + el.clientHeight >= el.scrollHeight - threshold;
}

// Called by the chat body's scroll handler. Only a scroll the USER made is
// allowed to change whether we follow the conversation.
function noteDmScroll(chatBody) {
    // Remembered for resumeDmThread(), programmatic scrolls included: where the
    // thread sits is what matters, not who put it there. Skipped while hidden,
    // where the box reads 0 and would erase the real position.
    if (chatBody.offsetParent !== null) {
        dmThreadMemory.fromBottom =
            chatBody.scrollHeight - chatBody.clientHeight - chatBody.scrollTop;
    }
    if (Date.now() < dmProgrammaticScrollUntil) return;
    dmStickToBottom = isNearBottom(chatBody);
}

// --- Coming back to an open DM ----------------------------------------------
// Tapping a post card in a DM (or a profile, a link, anything) leaves Messages,
// and coming back used to run renderActiveChat() from scratch: skeleton, fresh
// fetch of the last 80 messages, straight to the bottom. Whatever you had
// scrolled up to read -- including history loaded past those 80 -- was gone.
//
// The thread's DOM never went anywhere, though; the page was only hidden. So
// when it is provably still current, it is kept as is and put back where it
// was. "Provably" = it is this recipient's thread (`thread`, stamped when a
// render finishes), nothing from them arrived while away (the socket files that
// as unread instead of drawing it), and the socket never dropped.
//
// fromBottom rather than scrollTop: a message you sent from elsewhere can grow
// the thread while away, and the bottom is where the reading position anchors.
const dmThreadMemory = { thread: null, leftOpen: null, leftCount: 0, fromBottom: null };

function canResumeDmThread(recipient) {
    if (!recipient || dmThreadMemory.leftOpen !== recipient) return false;
    if (dmThreadMemory.thread !== recipient || dmThreadMemory.fromBottom == null) return false;
    if (unreadSenders.has(recipient)) return false;
    if (!socket || !socket.connected || missedEventsWhileDisconnected) return false;
    const chatBody = document.getElementById('chat-body');
    return !!(chatBody && chatBody.querySelector('.chat-message'));
}

// The parts of renderActiveChat() that are about being on screen, without the
// ones that rebuild the thread.
function resumeDmThread(recipient) {
    const container = document.querySelector('.messages-container');
    if (container) container.classList.add('mobile-chat-active');
    clearKeyboardViewportLock();
    clearKeyboardViewport();
    clearPushNotifications(`dm-${recipient}`);
    setActiveView('dm', recipient);
    renderChatList();

    // Something joined the thread's history while it was hidden -- a message
    // you sent from another device lands in messageHistory without being drawn.
    // Redrawn from memory (bubbles are cached, no fetch); the scroll below then
    // puts you back where you were.
    if ((messageHistory[recipient] || []).length !== dmThreadMemory.leftCount) {
        renderChatMessages(true); // preserve: no smooth scroll to fight the restore
    }

    const fromBottom = dmThreadMemory.fromBottom;
    // After a paint: a scrollTop set while the page is still display:none, or
    // mid-slide before layout, is silently dropped.
    requestAnimationFrame(() => {
        const chatBody = document.getElementById('chat-body');
        if (!chatBody || currentChatRecipient !== recipient) return;
        beginProgrammaticDmScroll();
        chatBody.scrollTop = Math.max(0,
            chatBody.scrollHeight - chatBody.clientHeight - fromBottom);
        dmStickToBottom = isNearBottom(chatBody);
        syncInstagramGradients('chat-body');
    });
}

// Mark the next stretch of scroll events as ours, so noteDmScroll ignores them.
function beginProgrammaticDmScroll() {
    dmProgrammaticScrollUntil = Date.now() + DM_PROGRAMMATIC_SCROLL_MS;
}

// The lounge renderer had the identical defect -- it measured scrollTop the moment a
// message arrived, so anything landing during the previous message's smooth scroll
// read as "scrolled up" and the channel pinned itself mid-history. Its threshold was
// 50px rather than 10px, which is why lounges limped along instead of failing
// outright, but the failure mode is the same one.
//
// Kept as a parallel set rather than folded together with the DM state: the DM path
// is verified working, and generalising it would mean re-touching every line of it.
let loungeStickToBottom = true;
let loungeProgrammaticScrollUntil = 0;
let lastLoungeAutoScrollAt = 0;

function noteLoungeScroll(loungeBody) {
    if (Date.now() < loungeProgrammaticScrollUntil) return;
    loungeStickToBottom = isNearBottom(loungeBody);
}

function beginProgrammaticLoungeScroll() {
    loungeProgrammaticScrollUntil = Date.now() + DM_PROGRAMMATIC_SCROLL_MS;
}

// ---------------------------------------------------------------------------
// Re-pin a scroller once its images have taken up their real height.
// ---------------------------------------------------------------------------
// A chat bubble's media reserves no space: `img.chat-media` is written with no
// width/height attributes and has no CSS box, so an image the browser has not
// decoded yet is ZERO pixels tall. Anything that scrolls to the bottom therefore
// measures a scrollHeight that is short by the height of every undecoded image
// in the thread, lands there, and then watches those images pop in and shove the
// newest message back below the fold.
//
// Opening a conversation whose recent messages include a photo or a sticker is
// the case that shows it, because that is exactly when none of them are in the
// browser's cache. The renderer already waited on ONE image -- the one attached
// to the very last message -- which is why "photo, then a reply about it" (the
// ordinary way people send a picture) still landed short: the image sat one
// message above the one being waited for.
//
// So: watch every image that has not settled, and go back to the bottom as each
// one does. `stillWanted` is re-checked at every re-pin, and this only ever
// re-asserts a decision its caller already made -- it never makes one of its
// own, so a scroll position chosen by some other branch is never overridden.
function repinOnMediaSettle(container, stillWanted, repin) {
    if (!container) return;

    container.querySelectorAll('img').forEach(img => {
        // Already decoded, or reused from the node cache with its bytes still in
        // hand: it is contributing its true height right now, nothing to wait for.
        if (img.complete) return;
        // One listener per element no matter how many renders it survives.
        if (img.dataset.settleWatched) return;
        img.dataset.settleWatched = '1';

        const settled = () => {
            delete img.dataset.settleWatched;
            // Its message's entry already slid the thread here (holdEntryForMedia);
            // an instant re-pin now would cut that slide off.
            if (img.dataset.entryHandled) return;
            if (stillWanted()) repin();
        };
        // A broken image settles too -- it stops being a pending height change.
        img.addEventListener('load', settled, { once: true });
        img.addEventListener('error', settled, { once: true });
    });
}

