/**
 * Start-of-year dates. One row per school that has users; the date box is a
 * plain MM-DD text field so there is no year to get wrong, and clearing it
 * puts that school back on the September 1 default.
 */
function loadSchoolYearStarts() {
    const box = document.getElementById('admin-school-year-list');
    if (!box) return;
    box.textContent = 'Loading schools...';

    fetch(`${API_BASE_URL}/api/admin/school-year-starts`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json())
    .then(data => {
        if (!data.schools) {
            box.textContent = data.error || 'Could not load schools.';
            return;
        }
        if (!data.schools.length) {
            box.textContent = 'No schools yet.';
            return;
        }
        box.innerHTML = '';
        data.schools.forEach(s => {
            const row = document.createElement('div');
            row.className = 'input-group';
            row.style.marginBottom = '8px';

            const name = document.createElement('span');
            name.textContent = s.school;
            name.style.flex = '1';

            const input = document.createElement('input');
            input.type = 'text';
            input.value = s.start_date;
            input.placeholder = 'MM-DD';
            input.maxLength = 5;
            input.style.maxWidth = '90px';
            if (s.is_default) input.style.opacity = '0.6';

            const save = document.createElement('button');
            save.className = 'admin-btn-primary';
            save.textContent = 'Save';
            save.onclick = () => saveSchoolYearStart(s.school, input.value, save);

            row.append(name, input, save);
            box.appendChild(row);
        });
    })
    .catch(() => { box.textContent = 'Could not load schools.'; });
}

function saveSchoolYearStart(school, startDate, button) {
    button.disabled = true;
    button.textContent = 'Saving...';

    fetch(`${API_BASE_URL}/api/admin/school-year-start`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ school: school, start_date: startDate })
    })
    .then(r => r.json())
    .then(d => {
        showToast(d.ok ? `${school}: grades now roll over on ${d.start_date}` : (d.error || 'Failed'),
                  d.ok ? 'success' : 'error');
        if (d.ok) loadSchoolYearStarts();
    })
    .catch(() => showToast('Failed to save', 'error'))
    .finally(() => { button.disabled = false; button.textContent = 'Save'; });
}

function adminRunMigrations(button) {
    button.disabled = true;
    button.textContent = 'Running...';
    const outputConsole = document.getElementById('admin-migrations-output');
    outputConsole.textContent = 'Attempting to apply database migrations...';

    fetch(`${API_BASE_URL}/api/admin/updatedb`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        outputConsole.textContent = data.message || data.error;
    })
    .catch(error => {
        outputConsole.textContent = `Error: Failed to communicate with the server. ${error}`;
    })
    .finally(() => {
        button.disabled = false;
        button.textContent = 'Run Migrations';
    });
}

function adminManageUser(button) {
    const username = document.getElementById('admin-user-manage-input').value.trim();
    const action = document.getElementById('admin-user-action-select').value;
    
    if (!username) {
        showToast('Please enter a username.', 'error');
        return;
    }

    let endpoint = '';
    let method = 'POST';
    let body = {};

    // --- EXISTING LOGIC ---
    if (action.startsWith('op-')) {
        endpoint = `/api/user/${username}/rank`;
        body = { rank: action.split('-')[1] };
    } else if (action === 'ban') {
        endpoint = `/api/user/${username}/ban`;
        const reason = prompt('Enter ban reason (optional):');
        body = { reason: reason || '' };
    } else if (action === 'unban') {
        endpoint = `/api/user/${username}/unban`;
        
    // --- NEW LOGIC START ---
    } else if (action === 'reset_pass') {
        // Just confirm, don't ask for a password
        if(!confirm(`Reset password for @${username}? A random password will be emailed to them.`)) return;
        
        endpoint = `/api/admin/user/${username}/reset-password`;
        body = {}; // No body needed
    }
    // --- NEW LOGIC END ---

    button.disabled = true;
    button.textContent = 'Executing...';

    fetch(`${API_BASE_URL}${endpoint}`, {
        method: method,
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(body)
    })
    .then(r => r.json())
    .then(d => {
        showToast(d.message || d.error, d.ok ? 'success' : 'error');
    })
    .finally(() => {
        button.disabled = false;
        button.textContent = 'Execute';
    });
}

function adminDeleteUser(button) {
    const username = document.getElementById('admin-delete-user-input').value.trim();
    if (!username) {
        showToast('Please enter a username to delete.', 'error');
        return;
    }

    showConfirmationModal({
        title: 'Delete User Account?',
        text: `@${username} will be locked out immediately and permanently erased in 180 days. Their data is retained until then, and unbanning the account within that window restores it. After 180 days it cannot be recovered.`,
        onConfirm: () => {
            button.disabled = true;
            button.textContent = 'Deleting...';

            fetch(`${API_BASE_URL}/api/admin/user/${username}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${apiToken}` }
            })
            .then(r => r.json())
            .then(d => {
                showToast(d.message || d.error, d.ok ? 'success' : 'error');
                if (d.ok) document.getElementById('admin-delete-user-input').value = '';
            })
            .finally(() => {
                button.disabled = false;
                button.textContent = 'Delete User';
            });
        }
    });
}

function fetchAndRenderTrending() {
    const container = document.getElementById('trending-now-list');
    
    // Add timestamp to prevent caching
    fetch(`${API_BASE_URL}/api/trending?limit=7&t=${Date.now()}`, { 
        headers: { 'Authorization': `Bearer ${apiToken}` } 
    })
    .then(response => {
        if (!response.ok) throw new Error('Network response was not ok');
        return response.json();
    })
    .then(items => {
        container.innerHTML = '';
        if (!items || items.length === 0) {
            // The server now scores every eligible circuit and lounge, so an empty
            // response means the platform genuinely has none yet -- offer the way
            // out rather than the old dead-end "nothing is trending".
            container.innerHTML = `<p style="padding-left: 15px; color: #888;">
                Nothing here yet. <a href="#" onclick="event.preventDefault(); navigateTo('/lounges/new')">Start a lounge</a>.</p>`;
            return;
        }

        items.forEach(item => {
            const isCircuit = item.type === 'circuit';

            // The card itself is a 150px circle with room for ~10 characters, so
            // the reason line goes in a caption underneath rather than being
            // truncated into meaninglessness inside it.
            const wrap = document.createElement('div');
            wrap.className = 'trending-item';

            const card = document.createElement('div');
            card.className = 'circuit-card';

            wrap.onclick = isCircuit
                ? () => navigateTo(`/circuits/${item.code}`)
                // The server filters unlisted lounges, so whatever arrives is showable.
                : () => navigateToLounge(item.id);

            // A lounge with no cover of its own still gets its built-in one.
            const cover = isCircuit ? item.coverImage
                : loungeCoverUrl({ id: item.id, cover_image: item.coverImage });
            if (cover) {
                card.style.backgroundImage = `url("${cover}")`;
            } else {
                card.classList.add('no-image');
            }

            card.innerHTML = isCircuit
                ? `<h4>${truncate(item.title, 10)}</h4>
                   <p>${truncate(item.hostSchool, 10)}</p>`
                : `<h4>${truncate(item.name, 10)}</h4>
                   <p>${truncate(item.description, 15)}</p>`;

            // Who is in there, as faces. A row of avatars reads at a glance where
            // a sentence has to be parsed -- and a whole row of sentences under a
            // whole row of circles is a wall of text, not an invitation.
            const faces = item.faces || [];
            if (faces.length) {
                const pile = document.createElement('div');
                pile.className = 'trending-faces';
                faces.slice(0, 4).forEach(src => {
                    const f = document.createElement('span');
                    f.className = 'trending-face';
                    f.style.backgroundImage = `url(${src})`;
                    pile.appendChild(f);
                });
                // Only the overflow gets a number, so the common case stays wordless.
                const extra = (item.participants || 0) - faces.slice(0, 4).length;
                if (extra > 0) {
                    const more = document.createElement('span');
                    more.className = 'trending-face trending-face-more';
                    more.textContent = `+${extra}`;
                    pile.appendChild(more);
                }
                card.appendChild(pile);
            } else if (item.is_new) {
                // Nothing has happened here yet, so there are no faces to show. One
                // small badge instead of a sentence explaining the silence.
                const badge = document.createElement('span');
                badge.className = 'trending-badge';
                badge.textContent = 'New';
                card.appendChild(badge);
            }

            // The full sentence survives as the tooltip: available on hover, not
            // occupying the layout.
            if (item.reason) wrap.title = item.reason;

            wrap.appendChild(card);
            container.appendChild(wrap);
        });
    })
    .catch(error => {
        console.error("Error fetching trending:", error);
        if(container.innerHTML === '') {
            container.innerHTML = '<p style="padding-left: 15px; color: #888;">Check back later.</p>';
        }
    });
}

function toggleMessageOptions(event, messageId, type, isAuthor, authorId) {
    event.stopPropagation();
    
    const menu = document.getElementById('global-message-options-dropdown');
    if (!menu) return;

    // If clicking the same button while menu is open, just close it
    if (!menu.classList.contains('hidden') && menu.dataset.activeMessageId === String(messageId)) {
        menu.classList.add('hidden');
        return;
    }

    // --- Build Content ---
    let menuHtml = '';
    // Check permissions
    // Note: Ensure currentUserLoungeRole and profileData are available here
    const isMod = (currentUserLoungeRole === 'owner' || currentUserLoungeRole === 'moderator' || hasPerm('content.message.delete'));
    
    menuHtml += `<a onclick="copyMessageText(${messageId}, '${type}')"><i class="fas fa-copy" style="margin-right:8px;"></i>Copy Text</a>`;

    if (type === 'dm') {
        if (isAuthor) {
            menuHtml += `<a onclick="showEditMessageUI(${messageId}, '${type}')"><i class="fas fa-edit" style="margin-right:8px;"></i>Edit</a>`;
            menuHtml += `<hr class="message-options-divider">`;
            menuHtml += `<a class="danger" onclick="handleDeleteMessage(${messageId}, '${type}')"><i class="fas fa-trash" style="margin-right:8px;"></i>Delete</a>`;
        }
    } else if (type === 'lounge') {
        if (isAuthor) {
            menuHtml += `<a onclick="showEditMessageUI(${messageId}, '${type}')"><i class="fas fa-edit" style="margin-right:8px;"></i>Edit</a>`;
        }
        // Admins/Mods can delete anyone's message
        if (isAuthor || isMod) {
            menuHtml += `<hr class="message-options-divider">`;
            menuHtml += `<a class="danger" onclick="handleDeleteMessage(${messageId}, '${type}')"><i class="fas fa-trash" style="margin-right:8px;"></i>Delete</a>`;
        }
    }
    
    // Add Report Button for everyone else's posts
    if (!isAuthor) {
        menuHtml += `<hr class="message-options-divider">`;
        // We pass arguments to showReportPage directly
        menuHtml += `<a onclick="navigateTo('/report?type=post&id=${messageId}&author=${authorId || 'unknown'}')"><i class="fas fa-flag" style="margin-right:8px;"></i>Report</a>`;
    }

    menu.innerHTML = menuHtml;
    menu.dataset.activeMessageId = messageId; // Track which message this belongs to

    // --- Positioning Logic ---
    const buttonRect = event.currentTarget.getBoundingClientRect();
    
    // Reset visibility to calculate size
    menu.style.visibility = 'hidden';
    menu.classList.remove('hidden');
    
    const menuWidth = 160; // Fixed width from CSS
    const menuHeight = menu.offsetHeight || 100; // Estimate if 0
    const screenMargin = 10;

    // Calculate Top
    let top = buttonRect.bottom + window.scrollY + 5;
    // Flip up if at bottom of screen
    if (buttonRect.bottom + menuHeight > window.innerHeight) {
        top = buttonRect.top + window.scrollY - menuHeight - 5;
    }

    // Calculate Left
    let left = buttonRect.left + window.scrollX - menuWidth + buttonRect.width;
    // Prevent going off left edge
    if (left < screenMargin) left = screenMargin;

    // Apply
    menu.style.top = `${top}px`;
    menu.style.left = `${left}px`;
    menu.style.visibility = 'visible';
}

function syncInstagramGradients(containerId) {
    const container = document.getElementById(containerId);
    if (!container) return;

    const bubbles = container.querySelectorAll('.chat-message.sent p');
    if (!bubbles.length) return;

    const containerHeight = container.clientHeight;
    // A hidden/unlaid-out pane measures 0, which would bake in a collapsed
    // gradient that survives until the next scroll. Leave the CSS alone.
    if (!containerHeight) return;

    // This runs on every scroll frame, so it has to touch layout exactly once.
    // Reading each bubble's position and writing its style in the same pass meant
    // every write dirtied style for the next read, forcing a synchronous layout per
    // bubble -- ~80 of them per frame on a loaded chat. A mouse wheel scrolls in
    // coarse jumps and mostly got away with it; a touchpad streams events every
    // frame, so the reflows never let up and the scroll crawled.
    //
    // So: read everything, then write everything.
    const containerTop = container.getBoundingClientRect().top;
    const tops = new Array(bubbles.length);
    const bottoms = new Array(bubbles.length);
    for (let i = 0; i < bubbles.length; i++) {
        const rect = bubbles[i].getBoundingClientRect();
        tops[i] = rect.top - containerTop;
        bottoms[i] = rect.bottom - containerTop;
    }

    // Bubbles well outside the visible box can't be seen, and scrolling is what
    // brings them in -- the frame that does so re-runs this and positions them
    // before they reach the edge. Skipping them keeps a long backlog off the
    // per-frame bill.
    //
    // "Outside" is judged on BOTH edges. Judging on the top alone skipped any
    // message taller than the screen as soon as its top scrolled a screen's height
    // away -- while the rest of it was still on screen, frozen on a stale position.
    const margin = containerHeight;
    const size = `100% ${containerHeight}px`;
    for (let i = 0; i < bubbles.length; i++) {
        const top = tops[i];
        if (bottoms[i] < -margin || top > containerHeight + margin) continue;
        bubbles[i].style.backgroundSize = size;
        // The gradient is pinned to the container, so it moves up by exactly as much
        // as the bubble sits below the container's top. Written as a signed number:
        // the old `-${top}px` produced "--340px" once a bubble's top scrolled above
        // the container, which is invalid, so the browser silently kept whatever
        // position the bubble had last -- the big-message glitch.
        bubbles[i].style.backgroundPosition = `0px ${-top}px`;
    }
}

function openCircuitDetailsModal() {
    const menu = document.getElementById('circuit-menu-dropdown');
    if (menu) menu.classList.add('hidden');

    if (!currentCircuitDetails) return;

    const modal = document.getElementById('circuit-details-modal');
    const body = document.getElementById('circuit-details-body');

    // This is now much simpler because the backend does the work for us.
    const viewsToday = currentCircuitDetails.daily_views || 0;

    body.innerHTML = `
        <p><strong>Title:</strong> ${currentCircuitDetails.title}</p>
        <p><strong>Affiliation:</strong> ${currentCircuitDetails.hostSchool}</p>
        <p><strong>Code:</strong> ${currentCircuitDetails.code}</p>
        <p><strong>Daily Views:</strong> ${viewsToday}</p>
    `;
    modal.classList.remove('hidden');
}

function closeCircuitDetailsModal() {
    document.getElementById('circuit-details-modal').classList.add('hidden');
}

// --- APEX search history -------------------------------------------------------
// Deliberately our own rather than the browser's: the native type="search"/autofill
// dropdown is shared across every site you've ever typed into, so it surfaces junk
// that has nothing to do with APEX. This records only what was searched here.
//
// Stored in localStorage -- it survives restarts (sessionStorage would not), needs no
// server round trip, and is keyed per account so two people sharing a device never
// see each other's searches.
const SEARCH_HISTORY_MAX = 10;

function searchHistoryKey() {
    const who = (profileData && profileData.me && profileData.me.username) || 'guest';
    return `apex_search_history_${who}`;
}

function getSearchHistory() {
    try {
        const list = JSON.parse(localStorage.getItem(searchHistoryKey()) || '[]');
        return Array.isArray(list) ? list.filter(q => typeof q === 'string' && q.trim()) : [];
    } catch (e) {
        return []; // corrupt or unavailable storage must never break search
    }
}

function saveSearchHistory(list) {
    try {
        localStorage.setItem(searchHistoryKey(), JSON.stringify(list.slice(0, SEARCH_HISTORY_MAX)));
    } catch (e) {
        // Private mode / quota full. History is a convenience, not worth throwing over.
    }
}

function recordSearch(query) {
    const q = (query || '').trim();
    if (!q) return;
    // Case-insensitive de-dupe, most recent first.
    const rest = getSearchHistory().filter(item => item.toLowerCase() !== q.toLowerCase());
    saveSearchHistory([q, ...rest]);
}

function removeSearchHistoryItem(query) {
    saveSearchHistory(getSearchHistory().filter(item => item !== query));
}

function clearSearchHistory() {
    try { localStorage.removeItem(searchHistoryKey()); } catch (e) { /* nothing to clear */ }
}

// --- The search bar's dropdown ---
let apexSearchActiveIndex = -1;

function apexSearchPanel(wrap) {
    return wrap ? wrap.querySelector('.apex-search-panel') : null;
}

function closeApexSearchPanel(wrap) {
    const panel = apexSearchPanel(wrap);
    if (!panel) return;
    panel.hidden = true;
    panel.innerHTML = '';
    wrap.classList.remove('is-open');
    apexSearchActiveIndex = -1;
}

function setApexSearchActive(wrap, index) {
    const nodes = [...wrap.querySelectorAll('.apex-search-item')];
    if (!nodes.length) return;
    apexSearchActiveIndex = ((index % nodes.length) + nodes.length) % nodes.length; // wraps
    nodes.forEach((n, i) => n.classList.toggle('is-active', i === apexSearchActiveIndex));
    nodes[apexSearchActiveIndex].scrollIntoView({ block: 'nearest' });
}

function renderApexSearchPanel(wrap) {
    const panel = apexSearchPanel(wrap);
    const input = wrap ? wrap.querySelector('.apex-search-input') : null;
    if (!panel || !input) return;

    const typed = input.value.trim().toLowerCase();
    // Typing narrows the history, so the bar doubles as a "search what I searched".
    const items = typed
        ? getSearchHistory().filter(q => q.toLowerCase().includes(typed))
        : getSearchHistory();

    // Whatever is typed also goes off to ask which tags it could become. That
    // answer arrives later and paints itself into this panel; asking for it
    // here rather than from the keystroke handler means every route that
    // re-renders the panel (focus, clear, removing a history row) keeps the
    // tag group in step instead of dropping it.
    requestApexTagSuggestions(wrap, typed);

    // An empty history is no longer an empty panel: the tags being fetched may
    // be the only thing in it, so it stays open with nothing but a head while
    // that lands, and closes for real if nothing arrives.
    const tags = apexTagState(wrap).tags;
    if (!items.length && !tags.length) {
        closeApexSearchPanel(wrap);
        return;
    }

    panel.innerHTML = items.length ? `
        <div class="apex-search-panel-head">
            <span>Recent searches</span>
            <button type="button" class="apex-search-clear-all">Clear all</button>
        </div>
        <ul class="apex-search-list">
            ${items.map((q, i) => `
                <li class="apex-search-item" role="option" data-index="${i}">
                    <i class="fas fa-history apex-search-item-icon"></i>
                    <span class="apex-search-item-text">${escapeMentionText(q)}</span>
                    <button type="button" class="apex-search-item-remove" aria-label="Remove">&times;</button>
                </li>`).join('')}
        </ul>` : '';

    panel.hidden = false;
    wrap.classList.add('is-open');
    apexSearchActiveIndex = -1;

    // Re-paint the tags we already have, since the innerHTML above just wiped
    // them. Nothing is re-fetched: this is the cached answer for what is typed.
    paintApexTagSuggestions(wrap);

    const clearAll = panel.querySelector('.apex-search-clear-all');
    if (clearAll) clearAll.addEventListener('mousedown', (e) => {
        e.preventDefault();
        clearSearchHistory();
        closeApexSearchPanel(wrap);
        input.focus();
    });

    panel.querySelectorAll('.apex-search-item').forEach(li => {
        // Index into the array rather than stuffing the query into a data attribute,
        // so a query containing quotes can't break the markup.
        const q = items[Number(li.dataset.index)];

        // mousedown, not click: the input's blur would tear the panel down before a
        // click ever landed.
        li.addEventListener('mousedown', (e) => {
            if (e.target.closest('.apex-search-item-remove')) return;
            e.preventDefault();
            input.value = q;
            closeApexSearchPanel(wrap);
            handleSearch(q);
            input.blur();
        });

        const remove = li.querySelector('.apex-search-item-remove');
        if (remove) remove.addEventListener('mousedown', (e) => {
            e.preventDefault();
            e.stopPropagation();
            removeSearchHistoryItem(q);
            renderApexSearchPanel(wrap); // re-render in place, keeping focus
            input.focus();
        });
    });
}


// --- Tag suggestions in the search bar ---------------------------------------
// The half-typed '#' is the moment a tag is worth offering: it is the one part
// of search whose vocabulary the users wrote, so nobody can be expected to
// remember whether the club tags its photos #bakesale or #bake_sale. Each row
// carries the tag's post count, which is what makes the choice between two
// spellings of the same idea obvious.
//
// Rows are `.apex-search-item` like a history row, so the arrow keys and Enter
// already handle them -- Enter reads the row's text, which is "#bakesale", and
// handleSearch sends a whole tag straight to its page.
const APEX_TAG_SUGGEST_DEBOUNCE_MS = 200;

function apexTagState(wrap) {
    if (!wrap._apexTags) wrap._apexTags = { query: null, tags: [], timer: null, seq: 0 };
    return wrap._apexTags;
}

function requestApexTagSuggestions(wrap, typed) {
    const state = apexTagState(wrap);
    const query = (typed || '').replace(/^#+/, '');

    // Already answered. Re-rendering the panel must not re-ask.
    if (state.query === query) return;

    // An empty box is not a question. Suggestions there would be a top-tags
    // chart nobody asked for, in front of the recent searches they did.
    if (!query) {
        state.query = query;
        state.tags = [];
        clearTimeout(state.timer);
        return;
    }

    clearTimeout(state.timer);
    state.timer = setTimeout(() => {
        const seq = ++state.seq;
        fetch(`${API_BASE_URL}/api/tags/suggest?q=${encodeURIComponent(query)}&limit=6`,
              { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => r.json())
        .then(body => {
            // A later keystroke has already asked a newer question.
            if (seq !== state.seq) return;
            state.query = query;
            state.tags = (body && body.tags) || [];
            // Only while the box still says what was asked about, so a stale
            // answer cannot appear under something else that was typed since.
            const input = wrap.querySelector('.apex-search-input');
            const still = input && input.value.trim().toLowerCase().replace(/^#+/, '');
            if (still === query && document.activeElement === input) {
                if (apexSearchPanel(wrap).hidden) renderApexSearchPanel(wrap);
                else paintApexTagSuggestions(wrap);
            }
        })
        .catch(() => { /* suggestions are a convenience; the box still works */ });
    }, APEX_TAG_SUGGEST_DEBOUNCE_MS);
}

// Draws the cached tags into an already-open panel, above the recent searches:
// a tag is a more specific answer than "you looked this up before".
function paintApexTagSuggestions(wrap) {
    const panel = apexSearchPanel(wrap);
    if (!panel || panel.hidden) return;

    const existing = panel.querySelector('.apex-search-taggroup');
    if (existing) existing.remove();

    const tags = apexTagState(wrap).tags;
    if (!tags.length) return;

    const group = document.createElement('div');
    group.className = 'apex-search-taggroup';
    group.innerHTML = `
        <div class="apex-search-panel-head"><span>Tags</span></div>
        <ul class="apex-search-list"></ul>`;
    const list = group.querySelector('.apex-search-list');

    tags.forEach(row => {
        const li = document.createElement('li');
        li.className = 'apex-search-item';
        li.setAttribute('role', 'option');
        li.innerHTML = `
            <i class="fas fa-hashtag apex-search-item-icon"></i>
            <span class="apex-search-item-text"></span>
            <span class="apex-search-item-count"></span>`;
        // textContent: the tag is user-written, even though its characters are
        // already restricted to letters, digits and underscore.
        li.querySelector('.apex-search-item-text').textContent = `#${row.tag}`;
        li.querySelector('.apex-search-item-count').textContent =
            row.count === 1 ? '1 post' : `${row.count} posts`;

        // mousedown, for the same reason the history rows use it: the input's
        // blur tears the panel down before a click could ever land.
        li.addEventListener('mousedown', (e) => {
            e.preventDefault();
            const input = wrap.querySelector('.apex-search-input');
            closeApexSearchPanel(wrap);
            if (input) input.blur();
            openHashtag(null, row.tag);
        });
        list.appendChild(li);
    });

    panel.insertBefore(group, panel.firstChild);
}

// The search bars and the terminal prompt are <textarea rows="1"> rather than text
// inputs: Chrome offers saved credentials and cards on any text input while a password
// field exists in the document, and ours does permanently (the login form is never
// removed), so the autofill bar kept rising over the keyboard. Textareas aren't
// autofill targets -- which is exactly why the DM and Lounge composers never show it.
//
// Their Enter handlers already preventDefault(), so the only route to a newline is a
// multi-line paste. Flatten those, so .value stays single-line like the inputs these
// replaced and nothing downstream has to care which element it is reading.
function enforceSingleLineTextareas() {
    document.querySelectorAll('textarea[data-single-line]').forEach(field => {
        field.addEventListener('input', () => {
            if (!/[\r\n]/.test(field.value)) return;
            field.value = field.value.replace(/[\r\n]+/g, ' ');
            field.setSelectionRange(field.value.length, field.value.length);
        });
    });
}

// Owns both search bars: icon click, clear button, history dropdown, and Enter.
// (Previously Enter was bound in two places plus an inline onkeyup on the desktop
// input, so a desktop search fired handleSearch twice.)
function initializeApexSearch() {
    ['desktop-search-wrap', 'mobile-search-wrap', 'results-search-wrap'].forEach(wrapId => {
        const wrap = document.getElementById(wrapId);
        if (!wrap) return;

        const input = wrap.querySelector('.apex-search-input');
        const icon = wrap.querySelector('.apex-search-icon');
        const clearBtn = wrap.querySelector('.apex-search-clear');
        if (!input) return;

        const syncClearButton = () => wrap.classList.toggle('has-text', !!input.value);

        const runSearch = (q) => {
            const query = (q === undefined ? input.value : q).trim();
            if (!query) { input.focus(); return; }
            closeApexSearchPanel(wrap);
            handleSearch(query);
            input.blur();
        };

        if (icon) icon.addEventListener('click', () => runSearch());

        if (clearBtn) clearBtn.addEventListener('mousedown', (e) => {
            e.preventDefault(); // keep focus in the field
            input.value = '';
            syncClearButton();
            renderApexSearchPanel(wrap);
            syncSuggestedVisibility();
            input.focus();
        });

        input.addEventListener('focus', () => { syncClearButton(); renderApexSearchPanel(wrap); });
        input.addEventListener('input', () => {
            syncClearButton();
            renderApexSearchPanel(wrap);
            syncSuggestedVisibility();
        });
        input.addEventListener('blur', () => setTimeout(() => closeApexSearchPanel(wrap), 120));

        input.addEventListener('keydown', (event) => {
            if (event.isComposing || event.keyCode === 229) return; // mid-CJK composition

            const panel = apexSearchPanel(wrap);
            const open = panel && !panel.hidden;
            const items = [...wrap.querySelectorAll('.apex-search-item')];

            if (event.key === 'ArrowDown' && open && items.length) {
                event.preventDefault();
                setApexSearchActive(wrap, apexSearchActiveIndex + 1);
            } else if (event.key === 'ArrowUp' && open && items.length) {
                event.preventDefault();
                setApexSearchActive(wrap, apexSearchActiveIndex - 1);
            } else if (event.key === 'Escape') {
                closeApexSearchPanel(wrap);
            } else if (event.key === 'Enter') {
                event.preventDefault();
                const picked = open && apexSearchActiveIndex >= 0 && items[apexSearchActiveIndex];
                runSearch(picked ? picked.querySelector('.apex-search-item-text').textContent : undefined);
            }
        });

        syncClearButton();
    });
}

function handleSearch(query, fromRouting = false) {
    if (!query.trim()) return;

    // Typing a whole tag into the search box is not a search, it is a
    // destination -- so it goes straight to the tag's page instead of making
    // someone read a results screen whose first row is the thing they typed.
    // Only for a leading '#': a bare word still searches everything, and the
    // tag section of the results is where it offers the topic.
    if (query.trim().startsWith('#')) {
        const tag = normalizeHashtag(query);
        if (tag) {
            // Same rule as below: only a deliberate search is remembered. Back
            // and forward through an old ?search=%23tag link must not keep
            // reshuffling the history list.
            if (!fromRouting) recordSearch(query.trim());
            navigateTo(`/tags/${encodeURIComponent(tag)}`);
            return;
        }
    }
    if (!fromRouting) {
        // Only deliberate searches are remembered -- not back/forward navigation,
        // which would otherwise keep reshuffling the list.
        recordSearch(query);

        const newUrl = new URL(window.location);
        newUrl.pathname = '/'; // Standardize the path to root (apexsns.com?search=...)
        newUrl.searchParams.set('search', query.trim());
        
        // pushState changes the URL bar without refreshing the page!
        history.pushState(null, '', newUrl.toString());
        previousPath = window.location.pathname;
    }

    const resultsContainer = document.getElementById('search-results-container');
    const queryDisplay = document.getElementById('search-query-display');

    showPage('search-results-page');
    queryDisplay.textContent = `Results for "${query}"`;
    
    // Safely update the inputs if they exist, preventing the crash!
    // Setting .value fires no 'input' event, so the clear button's visibility has to
    // be reconciled by hand.
    const desktopInput = document.getElementById('desktop-search-input');
    if (desktopInput) {
        desktopInput.value = query;
        desktopInput.closest('.apex-search')?.classList.toggle('has-text', !!query);
    }

    const mobileInput = document.getElementById('mobile-search-input');
    if (mobileInput) {
        mobileInput.value = query;
        mobileInput.closest('.apex-search')?.classList.toggle('has-text', !!query);
    }

    const resultsInput = document.getElementById('results-search-input');
    if (resultsInput) {
        resultsInput.value = query;
        resultsInput.closest('.apex-search')?.classList.toggle('has-text', !!query);
    }

    fetch(`${API_BASE_URL}/api/search?q=${encodeURIComponent(query)}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        if (data.error) {
            resultsContainer.innerHTML = `<p style="color: red; text-align:center;">Error: ${data.error}</p>`;
        } else {
            renderSearchResults(data, query);
        }
    })
    .catch(error => {
        console.error('Search failed:', error);
        resultsContainer.innerHTML = '<p style="color: red; text-align:center;">Could not perform search.</p>';
    });
}

// The array the magnified modal pages through when a post is opened from the
// results page. Module-level for the same reason the circuit and profile lists
// are: postListForGrid has to be able to find it from the card that was tapped.
let searchPostsList = [];

function renderSearchResults(data, query) {
    const container = document.getElementById('search-results-container');
    container.innerHTML = '';
    searchPostsList = [];
    let contentFound = false;

    // --- Render Tags ---
    // First, because a tag is the most specific thing a query can turn out to
    // be: "festival" matching six people and a club is a guess, and #festival
    // having forty posts under it is an answer.
    if (data.tags && data.tags.length > 0) {
        contentFound = true;
        const section = document.createElement('div');
        section.className = 'content-section';
        section.innerHTML = '<h3>Tags</h3><div class="hashtag-chips"></div>';
        const chips = section.querySelector('.hashtag-chips');
        data.tags.forEach(row => chips.appendChild(buildHashtagChip(row.tag, row.count)));
        container.appendChild(section);
    }

    // --- Render Users ---
    if (data.users && data.users.length > 0) {
        contentFound = true;
        const section = document.createElement('div');
        section.className = 'content-section';
        let html = '<h3>Users</h3><div class="all-profiles-grid">';
        data.users.forEach(user => {
            if (!profileData[user.username]) {
                profileData[user.username] = { name: user.fullName, profilePicUrl: user.profile_pic, ...user };
            }
            html += `
                <div class="profile-grid-card" onclick="navigateTo('/users/${user.username}')">
                    <div class="profile-pic" data-user-pic-id="${user.username}"></div>
                    <p class="profile-card-name"><span class="profile-card-name-text">${user.fullName}</span>${rankIconFor(user.username, user.rank)}</p>
                    <p class="profile-card-username">@${user.username}</p>
                </div>`;
            setTimeout(() => updateProfilePictures(user.username), 0);
        });
        html += '</div>';
        section.innerHTML = html;
        container.appendChild(section);
    }

    // --- Render Circuits ---
    if (data.circuits && data.circuits.length > 0) {
        contentFound = true;
        const section = document.createElement('div');
        section.className = 'content-section';
        section.innerHTML = '<h3>Circuits</h3><div class="circuit-grid"></div>';
        const grid = section.querySelector('.circuit-grid');

        data.circuits.forEach(c => {
            const card = document.createElement('div');
            card.className = 'circuit-card';
            card.onclick = () => navigateTo(`/circuits/${c.code}`);
            
            // Safely grab the image and apply it natively
            const coverUrl = c.coverImage || c.cover_image;
            if (coverUrl) {
                card.style.backgroundImage = `url(${coverUrl})`;
            } else {
                card.classList.add('no-image');
            }
            
            card.innerHTML = `<h4>${c.title}</h4><p>${c.hostSchool || c.host_school || ''}</p>`;
            grid.appendChild(card);
        });
        container.appendChild(section);
    }

    // --- Render Lounges ---
    if (data.lounges && data.lounges.length > 0) {
        contentFound = true;
        const section = document.createElement('div');
        section.className = 'content-section';
        section.innerHTML = '<h3>Lounges</h3><div class="circuit-grid"></div>';
        const grid = section.querySelector('.circuit-grid');

        data.lounges.forEach(l => {
            const card = document.createElement('div');
            card.className = 'circuit-card';
            card.onclick = () => navigateToLounge(l.id);
            
            // Safely grab the image and apply it natively
            const coverUrl = loungeCoverUrl(l);
            if (coverUrl) {
                card.style.backgroundImage = `url(${coverUrl})`;
            } else {
                card.classList.add('no-image');
            }
            
            card.innerHTML = `<h4>${l.name}</h4><p>${truncate(l.description, 15)}</p>`;
            grid.appendChild(card);
        });
        container.appendChild(section);
    }

    // --- NEW: Render Articles ---
    if (data.articles && data.articles.length > 0) {
        contentFound = true;
        const section = document.createElement('div');
        section.className = 'content-section';
        let html = '<h3>Articles</h3><div class="article-grid">'; // Use article-grid
        data.articles.forEach(a => {
            // Use the 'card' HTML structure from the explore page
            html += `
            <div class="card">
                <div class="card__img">
                    <span class="card__span">${a.schoolTag}</span>
                </div>
                <div class="card-int">
                    <p class="card-int__title">${a.title}</p>
                    <div class="card-meta">
                        <span class="author">by ${a.author}</span>
                    </div>
                    <button class="card-int__button" onclick="showArticle(${a.id})">Show</button>
                </div>
            </div>`;
        });
        html += '</div>';
        section.innerHTML = html;
        container.appendChild(section);
    }

    // --- Render Posts ---
    // Last, because a post is the longest thing to read past. The server has
    // always sent these; nothing rendered them, so searching for a phrase
    // somebody wrote in a post found it and then threw it away.
    if (data.posts && data.posts.length > 0) {
        contentFound = true;
        const section = document.createElement('div');
        section.className = 'content-section';
        section.innerHTML = '<h3>Posts</h3><div id="search-posts-grid" class="circuit-posts-grid"></div>';
        container.appendChild(section);

        const grid = section.querySelector('#search-posts-grid');
        // Same delegated handler as every other post grid, so a result behaves
        // like a post rather than like a search row.
        grid.addEventListener('click', handleGridClick);
        attachGridLongPress(grid);
        masonryReset(grid);
        masonryAppend(grid, data.posts.map(post => {
            const index = searchPostsList.push(post) - 1;
            return buildProfilePostCard(post, index);
        }));
        verifyMentions();
    }

    // --- No Results ---
    if (!contentFound) {
        container.innerHTML = `<p style="text-align: center; color: #888;">No results found for "${query}".</p>`;
        // A dead end is the worst place to leave someone. The same explained
        // suggestions the empty mobile search box shows go underneath, so there
        // is somewhere to go that isn't the Back button.
        renderNoResultsTrendingTags(container);
        renderNoResultsSuggestions(container);
    }
}

// Builds a "Suggested for you" block underneath the no-results line. Same markup
// and same rows as the mobile search block (#search-suggested-block), just built
// on demand rather than living in the HTML -- it only ever exists on a search
// that found nothing, and is thrown away with the container on the next search.
// A search that found nothing is the other moment trending tags earn their
// place: they are somewhere to go that is not the Back button, and unlike the
// suggested people they are a second attempt at the thing that was being looked
// for rather than a change of subject.
function renderNoResultsTrendingTags(container) {
    const block = document.createElement('aside');
    block.className = 'suggested-block hashtag-trending-block search-empty-trending';
    block.innerHTML = `
        <div class="suggested-header">
            <span class="suggested-label">Trending tags</span>
        </div>
        <div class="hashtag-chips"></div>
    `;
    renderTrendingTagChips(block.querySelector('.hashtag-chips')).then(count => {
        // The results may have been replaced by a newer search while this was
        // in flight; appending then would drop tags onto somebody else's hits.
        if (!count || !container.isConnected || container.querySelector('.content-section')) return;
        container.appendChild(block);
    });
}

function renderNoResultsSuggestions(container) {
    const blocked = (typeof blockedUsers !== 'undefined' && blockedUsers.size)
        ? Array.from(blockedUsers).join(',') : '';
    const url = `${API_BASE_URL}/api/users/suggested?limit=8`
        + (blocked ? `&exclude=${encodeURIComponent(blocked)}` : '');

    fetch(url, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(r => r.json())
    .then(users => {
        if (!Array.isArray(users) || users.length === 0) return;
        // The results may have been replaced by a newer search while this was in
        // flight; appending then would drop suggestions onto someone else's hits.
        if (!container.isConnected || container.querySelector('.content-section')) return;

        const block = document.createElement('aside');
        block.className = 'suggested-block search-empty-suggested';
        block.innerHTML = `
            <div class="suggested-header">
                <span class="suggested-label">Suggested for you</span>
                <a href="#" class="suggested-seeall">See all</a>
            </div>
            <div class="suggested-list"></div>
        `;
        block.querySelector('.suggested-seeall').onclick = (e) => {
            e.preventDefault();
            navigateTo('/profiles');
        };

        container.appendChild(block);
        renderSuggestedUsers(users, block.querySelector('.suggested-list'));
    })
    .catch(error => console.error("Error fetching suggested users:", error));
}

