// ---------------------------------------------------------------------------
// Composer height keeper
// ---------------------------------------------------------------------------
// Everything under the thread -- the composer bar, and the image and poll trays
// stacked on it -- is part of the page, not an overlay: when it gets taller the
// conversation should move up to make room, and move back down when it shrinks.
//
// The thread is flex-grow, so a taller composer does shorten it. But a scroll
// container keeps its scrollTop when it is shortened from the bottom, so the
// newest lines simply ran out of view under the bar. autoResizeTextarea()
// corrected for the textarea's own growth, and nothing corrected for the rest: a
// reply bar appearing, the image tray, the send button's line. With the keyboard
// up it was worse, because the only other thing that re-pins the thread is the
// keyboard opening -- which is why a reply only pushed the thread after backing
// out of the keyboard and bringing it back.
//
// So watch the things that actually change height and move the thread by exactly
// that much, both ways. Keyed on their summed border-box height, which the
// keyboard slide never touches (it translates, and pads the thread's TOP), so the
// keyboard machinery and this cannot double up on each other.
let composerKeeperActive = false;
let composerKeeperQuietUntil = 0;

function initComposerHeightKeeper() {
    if (typeof ResizeObserver === 'undefined') return;

    const setups = [
        { thread: '#chat-body', parts: ['.active-chat-pane > .chat-input', '#dm-image-preview-container', '#poll-attachment-dm'] },
        { thread: '#lounge-body', parts: ['#lounge-input', '#lounge-image-preview-container', '#poll-attachment-lounge'] },
    ];

    setups.forEach(({ thread, parts }) => {
        const threadEl = document.querySelector(thread);
        const partEls = parts.map(sel => document.querySelector(sel)).filter(Boolean);
        if (!threadEl || !partEls.length) return;

        const total = () => partEls.reduce((sum, el) => sum + el.getBoundingClientRect().height, 0);
        let last = null;

        const observer = new ResizeObserver(() => {
            const now = total();
            const prev = last;
            last = now;

            // The thread runs underneath the composer and its trays (see the
            // "scrolls behind the pill" rule in style.css), padded at the bottom by
            // their height so the newest message still stops just above the bar.
            // Published before the scroll below, and flushed with a read, so the
            // scroll range that correction works against already includes it.
            if (now > 0) {
                threadEl.style.setProperty('--composer-h', `${now}px`);
                void threadEl.scrollHeight;
            }

            // First reading, or a page that is not on screen (every part 0 tall).
            if (prev === null || now === 0 || prev === 0) return;
            const delta = now - prev;
            if (Math.abs(delta) < 0.5) return;
            if (performance.now() < composerKeeperQuietUntil) return;

            // Instant, not the thread's CSS smooth-scroll: this is a correction
            // that has to land in the same frame as the layout change it cancels.
            // Shrinking: the thread grows, and a thread at the bottom has already
            // been pulled back by exactly that much -- the browser clamps scrollTop
            // during the layout, before this runs. Adding the delta on top would
            // pull it back twice. Only a thread scrolled up into history, which the
            // clamp never touches, needs moving.
            if (delta < 0) {
                const max = threadEl.scrollHeight - threadEl.clientHeight;
                if (threadEl.scrollTop >= max - 1) return;
            }
            threadEl.scrollTo({ top: threadEl.scrollTop + delta, behavior: 'instant' });
        });
        partEls.forEach(el => observer.observe(el));
        composerKeeperActive = true;
    });
}

// options.immediate  -- resize synchronously instead of on the next frame. Use it
//   when the caller is about to scroll the thread itself (sending): a deferred
//   resize lands a frame later, mid-animation, and its scroll fixup below CANCELS
//   the running smooth scroll. That is what made multi-line sends snap back or
//   skip their fly-in entirely, while one-liners -- where the composer height
//   never changed, so the fixup was skipped -- animated fine.
// options.adjustScroll -- keep the thread pinned while the composer grows/shrinks.
//   Off for the same reason: the send path's own scroll is authoritative.
function autoResizeTextarea(event, options = {}) {
    const textarea = event.target;
    const { immediate = false, adjustScroll = true } = options;
    // The send path collapses the composer and then smooth-scrolls the thread
    // itself. Tell the composer height keeper to stand aside for that, or its
    // correction would land mid-animation and cancel it.
    if (!adjustScroll) composerKeeperQuietUntil = performance.now() + 600;

    // 1. Determine the EXACT chat body based on which input is being used
    let chatBody = null;
    if (textarea.id === 'main-chat-input-field') {
        chatBody = document.getElementById('chat-body');
    } else if (textarea.id === 'lounge-input-field') {
        chatBody = document.getElementById('lounge-body');
    }

    const resize = () => {
        // 2. Measure height and scroll state BEFORE resize
        const oldHeight = textarea.offsetHeight;

        // Check if user is already snapped to the bottom (20px buffer)
        const isAtBottom = chatBody ? (chatBody.scrollTop + chatBody.clientHeight >= chatBody.scrollHeight - 20) : false;

        // 3. Perform Resize
        // Measuring means collapsing the field to 'auto' for a moment, and reading
        // scrollHeight lays that collapse out for real: the composer shrinks, the
        // thread grows, and a thread at the bottom has its scrollTop clamped down by
        // every line the field had beyond the first. The composer height keeper then
        // sees only the net change (+1 line) and adds it to the already-clamped
        // position -- so from the third line on, the thread stayed put instead of
        // moving up. 1 -> 2 lines was fine only because a one-line field has nothing
        // to collapse. Put the thread back where it was once the real height is set.
        const threadTopBefore = chatBody ? chatBody.scrollTop : 0;
        textarea.style.height = 'auto';
        // A hidden / not-yet-laid-out textarea reports scrollHeight 0. Baking that
        // in as height:0px leaves the bar collapsed ("thin") even after its page is
        // shown -- e.g. editing a DM then opening a lounge. Bail while off-screen and
        // clear any stale inline height so the CSS default governs until it's visible.
        if (textarea.scrollHeight === 0) {
            textarea.style.height = '';
            return;
        }
        if (textarea.scrollHeight > 120) {
            textarea.style.overflowY = 'auto';
        } else {
            textarea.style.overflowY = 'hidden';
        }
        textarea.style.height = (textarea.scrollHeight) + 'px';
        // Same task as the collapse, so nothing was painted in between. Setting
        // scrollTop lays out the final height first, so the old position is valid.
        if (chatBody && chatBody.scrollTop !== threadTopBefore) {
            chatBody.scrollTop = threadTopBefore;
        }

        // 4. Measure height AFTER resize
        const newHeight = textarea.offsetHeight;
        const difference = newHeight - oldHeight;

        // 5. Adjust Scroll -- only where the composer height keeper isn't running,
        // which now owns this for every composer change, not just the textarea's.
        // Doing it here as well would push the thread twice.
        if (adjustScroll && chatBody && difference !== 0 && !composerKeeperActive) {
            if (isAtBottom) {
                // If they were at the bottom, force them to stay strictly at the bottom
                chatBody.scrollTop = chatBody.scrollHeight;
            } else {
                // If they scrolled up to read history, nudge the scroll by the exact pixel difference
                chatBody.scrollTop += difference;
            }
        }
    };

    // Typing normally still waits a frame: the browser has to lay the new character
    // out before scrollHeight means anything. A programmatic clear has no such
    // pending work -- reading scrollHeight forces the layout we need on the spot.
    if (immediate) {
        resize();
    } else {
        requestAnimationFrame(resize);
    }
}

let emojiRenderQueue = [];
let emojiRenderTarget = null;

// Category order + nav icons, mirroring how Google's picker groups emojis. "recent"
// is first and is populated from the user's history (localStorage). The keys match
// the `category` field baked into EMOJI_LIST (see the generator / _enrich script).
const EMOJI_CATEGORIES = [
    { key: 'recent',     label: 'Recently Used',     faIcon: 'fa-clock-rotate-left' },
    { key: 'smileys',    label: 'Smileys & Emotion', faIcon: 'fa-face-smile' },
    { key: 'people',     label: 'People & Body',     faIcon: 'fa-user' },
    { key: 'nature',     label: 'Animals & Nature',  faIcon: 'fa-paw' },
    { key: 'food',       label: 'Food & Drink',      faIcon: 'fa-burger' },
    { key: 'travel',     label: 'Travel & Places',   faIcon: 'fa-plane' },
    { key: 'activities', label: 'Activities',        faIcon: 'fa-futbol' },
    { key: 'objects',    label: 'Objects',           faIcon: 'fa-lightbulb' },
    { key: 'symbols',    label: 'Symbols',           faIcon: 'fa-icons' },
    { key: 'flags',      label: 'Flags',             faIcon: 'fa-flag' },
];

const RECENT_EMOJI_KEY = 'apex_recent_emojis';
const RECENT_EMOJI_MAX = 32;

function getRecentEmojis() {
    try { return JSON.parse(localStorage.getItem(RECENT_EMOJI_KEY) || '[]'); }
    catch (e) { return []; }
}
function pushRecentEmoji(char) {
    try {
        const list = getRecentEmojis().filter(c => c !== char);
        list.unshift(char);
        localStorage.setItem(RECENT_EMOJI_KEY, JSON.stringify(list.slice(0, RECENT_EMOJI_MAX)));
    } catch (e) { /* private mode / quota -- recents are a convenience */ }
}

// Binds the emoji button WITHOUT paying for the emoji table or building the
// grid. The 220KB EMOJI_LIST and the ~1900-node grid are only worth their cost
// once the user actually opens the picker, which most sessions never do.
// On first click: fetch the table, run the real setup (which rebinds this
// button), then hand the click straight through so the panel opens on that same
// tap -- no second press needed.
function setupEmojiPanelLazy(panelId, inputId, triggerBtnId) {
    const triggerBtn = document.getElementById(triggerBtnId);
    if (!triggerBtn) return;
    if (!document.getElementById(panelId) || !document.getElementById(inputId)) return;

    // Already built by preloadEmojiPanels(): the real toggle is in place, and
    // re-binding the lazy one over it would throw that work away.
    if (document.getElementById(panelId).dataset.emojiReady) return;

    let loading = false;
    triggerBtn.onclick = (e) => {
        e.stopPropagation();
        if (loading) return;              // ignore double-taps while fetching
        loading = true;
        loadScriptOnce(EMOJILIST_SRC).then(() => {
            buildEmojiPanelOnce(panelId, inputId, triggerBtnId);
            // setupEmojiPanel has now replaced triggerBtn.onclick with the real
            // toggle; invoke it so this tap opens the panel.
            triggerBtn.onclick(e);
        }).catch(() => {
            loading = false;              // let the user try again
            showToast('Could not load emojis. Check your connection.', 'error');
        });
    };
}

// setupEmojiPanel() rebuilds the grid and re-binds its listeners every time it
// runs, so the preload and a first tap racing each other must not both do it.
function buildEmojiPanelOnce(panelId, inputId, triggerBtnId) {
    const panel = document.getElementById(panelId);
    if (!panel || panel.dataset.emojiReady) return;
    setupEmojiPanel(panelId, inputId, triggerBtnId);
    if (typeof EMOJI_LIST !== 'undefined') panel.dataset.emojiReady = '1';
}

// The emoji table is ~11k lines and three grids of every emoji are a lot of
// DOM, which is why none of it is in the boot path. But waiting for the first
// tap made that tap the slow one. So it is done in the background instead:
// only after the page has fully loaded (never competing with the loader or the
// first screen for the network), and then one panel per idle slot, so building
// the grids never lands as one long freeze while someone is scrolling.
const EMOJI_PRELOAD_PANELS = [
    ['emoji-panel', 'main-chat-input-field', 'emoji-btn'],
    ['lounge-emoji-panel', 'lounge-input-field', 'lounge-emoji-btn'],
    ['notice-emoji-panel', 'notice-comment-input', 'notice-emoji-btn'],
];
let emojiPreloadScheduled = false;

function preloadEmojiPanels() {
    if (emojiPreloadScheduled) return;
    emojiPreloadScheduled = true;

    const idle = (fn) => (window.requestIdleCallback
        ? requestIdleCallback(fn, { timeout: 4000 })
        : setTimeout(fn, 300));

    const start = () => idle(() => {
        loadScriptOnce(EMOJILIST_SRC).then(() => {
            const queue = EMOJI_PRELOAD_PANELS.slice();
            const next = () => {
                const spec = queue.shift();
                if (!spec) return;
                buildEmojiPanelOnce(...spec);
                idle(next);
            };
            idle(next);
        }).catch(() => {
            // Offline or flaky: the lazy path still loads it on the first tap.
            emojiPreloadScheduled = false;
        });
    });

    if (document.readyState === 'complete') start();
    else window.addEventListener('load', start, { once: true });
}

function setupEmojiPanel(panelId, inputId, triggerBtnId) {
    const panel = document.getElementById(panelId);
    const input = document.getElementById(inputId);
    const triggerBtn = document.getElementById(triggerBtnId);

    if (!panel || !input || !triggerBtn) return;
    if (typeof EMOJI_LIST === 'undefined') return;

    // Bucket the flat list into categories once. Order within a bucket is preserved.
    const byCat = {};
    for (const item of EMOJI_LIST) {
        const cat = item.category || 'symbols';
        (byCat[cat] = byCat[cat] || []).push(item);
    }

    const esc = (s) => (s || 'emoji').replace(/"/g, '');
    const gridHtml = (items) => items.map(it =>
        `<span class="emoji-item" data-char="${it.char}" title="${esc(it.name)}">${it.char}</span>`
    ).join('');

    // Nav bar: one button per non-empty category (recent always listed; hidden later
    // when empty).
    const navHtml = EMOJI_CATEGORIES
        .filter(c => c.key === 'recent' || (byCat[c.key] && byCat[c.key].length))
        .map(c => `<button type="button" class="emoji-nav-btn" data-nav="${c.key}" title="${c.label}"><i class="fas ${c.faIcon}"></i></button>`)
        .join('');

    // Sections: recent (filled dynamically) + one per category (static).
    let sectionsHtml = `<div class="emoji-section" data-cat="recent"><div class="emoji-section-header">Recently Used</div><div class="emoji-cat-grid" data-grid="recent"></div></div>`;
    for (const c of EMOJI_CATEGORIES) {
        if (c.key === 'recent') continue;
        const items = byCat[c.key];
        if (!items || !items.length) continue;
        sectionsHtml += `<div class="emoji-section" data-cat="${c.key}"><div class="emoji-section-header">${c.label}</div><div class="emoji-cat-grid">${gridHtml(items)}</div></div>`;
    }

    panel.innerHTML = `
        <div class="emoji-search-container">
            <input type="search" class="emoji-search-input" placeholder="Search emojis..."
                   autocomplete="off" spellcheck="false" autocorrect="off"
                   data-lpignore="true" data-form-type="other" onclick="event.stopPropagation()">
        </div>
        <div class="emoji-nav">${navHtml}</div>
        <div class="emoji-scroll">
            ${sectionsHtml}
            <div class="emoji-section emoji-search-results hidden" data-cat="search">
                <div class="emoji-section-header">Search Results</div>
                <div class="emoji-cat-grid" data-grid="search"></div>
            </div>
        </div>`;

    const searchInput  = panel.querySelector('.emoji-search-input');
    const nav          = panel.querySelector('.emoji-nav');
    const scroll       = panel.querySelector('.emoji-scroll');
    const recentSection= panel.querySelector('.emoji-section[data-cat="recent"]');
    const recentGrid   = panel.querySelector('[data-grid="recent"]');
    const recentNavBtn = nav.querySelector('[data-nav="recent"]');
    const searchSection= panel.querySelector('.emoji-search-results');
    const searchGrid   = panel.querySelector('[data-grid="search"]');
    const catSections  = [...scroll.querySelectorAll('.emoji-section:not(.emoji-search-results)')];

    const renderRecent = () => {
        const recents = getRecentEmojis();
        if (!recents.length) {
            recentSection.classList.add('hidden');
            recentNavBtn && recentNavBtn.classList.add('hidden');
            recentGrid.innerHTML = '';
            return;
        }
        recentSection.classList.remove('hidden');
        recentNavBtn && recentNavBtn.classList.remove('hidden');
        recentGrid.innerHTML = recents.map(ch => `<span class="emoji-item" data-char="${ch}" title="emoji">${ch}</span>`).join('');
    };

    const insertEmoji = (char) => {
        input.value += char;
        // Guarded focus, never a bare input.focus(). A plain focus fires focusin, and
        // the focusin handler closes any open composer panel -- so picking one emoji
        // shut the picker you were picking from. Skipped outright on a finger, where
        // handing focus back would raise the keyboard over the panel as well -- but
        // NOT on an iPad with a keyboard attached, where nothing rises. See
        // shouldAutoFocus().
        if (shouldAutoFocus()) focusKeepingComposerPanel(input);
        if (typeof autoResizeTextarea === 'function') autoResizeTextarea({ target: input });
        // Storage only -- the grid is deliberately NOT re-rendered here. Reshuffling
        // "Recently Used" under the cursor moves the emoji you just tapped out from
        // under you. The panel picks up the new order the next time it opens.
        pushRecentEmoji(char);
    };

    // One delegated click handler covers every section (recent, categories, search).
    scroll.addEventListener('click', (e) => {
        const item = e.target.closest('.emoji-item');
        if (!item) return;
        e.stopPropagation();
        insertEmoji(item.dataset.char);
    });

    // Search: flat filtered results, category sections + nav hidden while active.
    searchInput.oninput = (e) => {
        const q = e.target.value.toLowerCase().trim();
        if (!q) {
            searchSection.classList.add('hidden');
            catSections.forEach(s => s.classList.remove('hidden'));
            nav.classList.remove('hidden');
            // No renderRecent() -- clearing the search box must not reorder the
            // recents grid mid-session either. It refreshes on next open.
            updateActiveNav();
            return;
        }
        const filtered = EMOJI_LIST.filter(it =>
            (it.name || '').toLowerCase().includes(q) || (it.keywords || '').toLowerCase().includes(q)
        ).slice(0, 300);
        searchGrid.innerHTML = filtered.length
            ? gridHtml(filtered)
            : '<p style="grid-column:1/-1;color:#999;font-size:0.9em;text-align:center;padding:14px;">No emojis found.</p>';
        catSections.forEach(s => s.classList.add('hidden'));
        searchSection.classList.remove('hidden');
        nav.classList.add('hidden');
        scroll.scrollTop = 0;
    };

    // Nav button -> smooth-scroll to that section.
    nav.addEventListener('click', (e) => {
        const btn = e.target.closest('.emoji-nav-btn');
        if (!btn) return;
        e.stopPropagation();
        const target = scroll.querySelector(`.emoji-section[data-cat="${btn.dataset.nav}"]`);
        if (target) scroll.scrollTo({ top: target.offsetTop, behavior: 'smooth' });
    });

    // Highlight the nav button for the section currently at the top.
    const updateActiveNav = () => {
        const visible = catSections.filter(s => !s.classList.contains('hidden'));
        let current = visible[0];
        for (const s of visible) {
            if (s.offsetTop - 12 <= scroll.scrollTop) current = s;
        }
        if (!current) return;
        const cat = current.dataset.cat;
        nav.querySelectorAll('.emoji-nav-btn').forEach(b => b.classList.toggle('active', b.dataset.nav === cat));
    };
    scroll.addEventListener('scroll', () => requestAnimationFrame(updateActiveNav));

    // Toggle visibility.
    triggerBtn.onclick = (e) => {
        e.stopPropagation();
        const isHidden = panel.classList.contains('hidden');
        document.querySelectorAll('.emoji-panel').forEach(hideComposerPanelEl);
        // Stickers and emoji share one slot, so opening either has to close the other.
        // The sticker panel already closes this one; this is the other half of that.
        document.querySelectorAll('.sticker-popup').forEach(hideComposerPanelEl);
        if (isHidden) {
            panel.classList.remove('hidden');
            searchInput.value = '';
            searchSection.classList.add('hidden');
            catSections.forEach(s => s.classList.remove('hidden'));
            nav.classList.remove('hidden');
            renderRecent();
            scroll.scrollTop = 0;
            updateActiveNav();
            // Never on a touch screen. Focusing this search box raises the on-screen
            // keyboard directly over the panel it was opened to show -- the panel asks
            // for the slot and then the keyboard takes it straight back. The sticker
            // panel has always declined this; the emoji panel never did.
            // shouldAutoFocus(), not the pointer: with a hardware keyboard attached
            // there is no keyboard to take the slot back.
            if (shouldAutoFocus()) setTimeout(() => searchInput.focus(), 50);
            showComposerPanel(panel);
        } else {
            syncComposerPanelInset();
        }
    };

    renderRecent();
}
// Call this inside your window.onload or initializeEventListeners
function initializeAllEmojiPickers() {
    // Setup DM Picker
    setupEmojiPanelLazy('emoji-panel', 'main-chat-input-field', 'emoji-btn');

    // Setup Lounge Picker
    setupEmojiPanelLazy('lounge-emoji-panel', 'lounge-input-field', 'lounge-emoji-btn');

    // Setup the notice comment box
    setupEmojiPanelLazy('notice-emoji-panel', 'notice-comment-input', 'notice-emoji-btn');
}

function scrollToMessage(messageId, type) {
    // 1. Find the element
    const element = document.getElementById(`message-${type}-${messageId}`);
    if (!element) {
        showToast('Original message not found (it may be too old).', 'error');
        return;
    }

    // 2. Scroll to it
    // We use 'center' to ensure it's clearly visible, not at the very top/bottom
    element.scrollIntoView({ behavior: 'smooth', block: 'center' });

    // 3. Highlight it
    element.classList.add('highlighted');

    // 4. Remove the highlight after the animation finishes
    setTimeout(() => {
        element.classList.remove('highlighted');
    }, 4000); // 1.5 seconds
}

// The group a channel being created will land in -- set when the modal is opened
// from a group's header, null from the main "+".
let createChannelGroupId = null;

function showCreateChannelModal(groupId = null) {
    createChannelGroupId = groupId;
    document.getElementById('create-channel-modal').classList.remove('hidden');
    // Warm the member list now rather than when the Private radio is ticked, so
    // the picker is populated the moment it appears instead of flashing empty.
    fetchLoungeMembers().then(() => {
        if (currentChannelPickerSelection) renderChannelMemberPicker();
    });
}

function closeCreateChannelModal() {
    document.getElementById('create-channel-modal').classList.add('hidden');
    document.getElementById('new-channel-name').value = '';
    // Reset the type too, or the next channel silently inherits the last pick.
    const chatRadio = document.querySelector('input[name="channel-kind"][value="chat"]');
    if (chatRadio) chatRadio.checked = true;
    const publicRadio = document.querySelector('input[name="channel-permission"][value="public"]');
    if (publicRadio) publicRadio.checked = true;
    // Same reasoning for the allow-list: carrying last time's committee into the
    // next channel is the kind of default that silently grants access.
    currentChannelPickerSelection = null;
    const filter = document.getElementById('channel-members-filter');
    if (filter) filter.value = '';
    onChannelKindChange();
    onChannelPermissionChange();
}


// --- Channel member picker ----------------------------------------------------
// Shared by the create dialog and the visibility editor. Holds usernames, not
// ids, because that is what the API takes and what the rows are keyed on.
// null means "the picker is not in use"; a Set means it is.
let currentChannelPickerSelection = null;

function onChannelPermissionChange() {
    const level = document.querySelector('input[name="channel-permission"]:checked')?.value;
    const picker = document.getElementById('channel-members-picker');
    if (!picker) return;

    const on = level === 'restricted';
    picker.classList.toggle('hidden', !on);
    if (!on) {
        currentChannelPickerSelection = null;
        return;
    }
    if (!currentChannelPickerSelection) currentChannelPickerSelection = new Set();
    fetchLoungeMembers().then(() => renderChannelMemberPicker());
}

function renderChannelMemberPicker(listId = 'channel-members-list',
                                   filterId = 'channel-members-filter') {
    const list = document.getElementById(listId);
    if (!list || !currentChannelPickerSelection) return;

    const filter = (document.getElementById(filterId)?.value || '')
        .trim().toLowerCase();
    const members = (loungeMembersCache || []).filter(m => {
        if (!filter) return true;
        return (m.username || '').toLowerCase().includes(filter) ||
               (m.fullName || '').toLowerCase().includes(filter);
    });

    list.innerHTML = '';
    if (!members.length) {
        const empty = document.createElement('li');
        empty.className = 'channel-picker-empty';
        empty.textContent = filter ? 'No members match that.' : 'No members to add yet.';
        list.appendChild(empty);
        return;
    }

    members.forEach(m => {
        const li = document.createElement('li');
        li.className = 'channel-picker-row';

        const box = document.createElement('input');
        box.type = 'checkbox';
        box.checked = currentChannelPickerSelection.has(m.username);
        // The current user is always in a channel they are setting up -- the
        // server adds them regardless, so showing the box unticked would be a lie
        // about what is going to happen.
        const isSelf = !!(profileData.me && m.username === profileData.me.username);
        if (isSelf) {
            box.checked = true;
            box.disabled = true;
        }
        box.onchange = () => {
            if (box.checked) currentChannelPickerSelection.add(m.username);
            else currentChannelPickerSelection.delete(m.username);
        };

        const label = document.createElement('span');
        label.className = 'channel-picker-name';
        label.textContent = m.fullName || m.username;
        appendRankIcon(label, m.username, m.rank);

        const handle = document.createElement('span');
        handle.className = 'channel-picker-handle';
        handle.textContent = '@' + m.username + (isSelf ? ' (you)' : '');

        li.appendChild(box);
        li.appendChild(label);
        li.appendChild(handle);
        li.onclick = (e) => { if (e.target !== box && !box.disabled) box.click(); };
        list.appendChild(li);
    });
}

function channelPickerUsernames() {
    return currentChannelPickerSelection ? Array.from(currentChannelPickerSelection) : [];
}


// --- Channel privacy editor ---------------------------------------------------
// Owner only. Kept out of the rename dialog on purpose: renaming a channel is
// routine housekeeping a moderator does, and changing who can read it is not.
let channelPrivacyTarget = null; // { id, name }

function openChannelPrivacyModal(channelId, channelName) {
    document.querySelectorAll('.context-menu').forEach(m => m.remove());
    channelPrivacyTarget = { id: channelId, name: channelName };
    currentChannelPickerSelection = new Set();

    const titleEl = document.getElementById('channel-privacy-title');
    if (titleEl) titleEl.textContent = `Who can see #${channelName}`;
    const filter = document.getElementById('cp-members-filter');
    if (filter) filter.value = '';

    document.getElementById('channel-privacy-modal').classList.remove('hidden');
    pushModalHistory('channel-privacy-modal', closeChannelPrivacyModal);

    // Load the channel's CURRENT setting and allow-list before drawing anything,
    // so the dialog opens showing what is true rather than a default the owner
    // then has to undo.
    Promise.all([
        fetch(`${API_BASE_URL}/api/lounge/channel/${channelId}/access`, {
            headers: { 'Authorization': `Bearer ${apiToken}` }
        }).then(r => r.ok ? r.json() : { permission_level: 'public', members: [] }),
        fetchLoungeMembers(),
    ]).then(([access]) => {
        if (!channelPrivacyTarget || channelPrivacyTarget.id !== channelId) return;
        const level = access.permission_level || 'public';
        const radio = document.querySelector(`input[name="cp-permission"][value="${level}"]`);
        if (radio) radio.checked = true;
        (access.members || []).forEach(m => currentChannelPickerSelection.add(m.username));
        onChannelPrivacyChange();
    })
    .catch(() => showToast('Could not load the channel settings.', 'error'));
}

// --- Where a board appears (its ties) ---------------------------------------
// Only boards reach this: a chat channel is what boards are tied TO, never the
// tied thing. Nothing ticked means the whole lounge, which is both the default
// and what every board was before ties existed -- so the dialog's empty state is
// a real answer rather than an unfinished one.
let channelTiesTarget = null;       // { id, name }
let channelTieOptions = [];         // the chat channels that may be tied to
let channelTieSelection = null;     // Set of chosen channel ids

function openChannelTiesModal(channelId, channelName) {
    document.querySelectorAll('.context-menu').forEach(m => m.remove());
    channelTiesTarget = { id: channelId, name: channelName };
    channelTieOptions = [];
    channelTieSelection = new Set();

    document.getElementById('channel-ties-title').textContent = `Where #${channelName} appears`;
    document.getElementById('ct-filter').value = '';
    document.getElementById('ct-list').innerHTML = '';
    document.getElementById('ct-summary').textContent = '';
    document.getElementById('channel-ties-modal').classList.remove('hidden');
    pushModalHistory('channel-ties-modal', closeChannelTiesModal);

    // Load what is true before drawing, so the dialog never opens showing a
    // default the mod then has to undo.
    fetch(`${API_BASE_URL}/api/lounge/channel/${channelId}/ties`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (!ok) throw new Error(body.error || 'Could not load this board.');
        // Another board was opened while this was in flight.
        if (!channelTiesTarget || channelTiesTarget.id !== channelId) return;
        channelTieOptions = body.options || [];
        channelTieSelection = new Set((body.tied_to || []).map(Number));
        renderChannelTiePicker();
    })
    .catch(err => {
        showToast(err.message || 'Could not load this board.', 'error');
        closeChannelTiesModal();
    });
}

function closeChannelTiesModal() {
    const modal = document.getElementById('channel-ties-modal');
    if (!modal || modal.classList.contains('hidden')) return;
    modal.classList.add('hidden');
    popModalHistory('channel-ties-modal');
    channelTiesTarget = null;
    channelTieOptions = [];
    channelTieSelection = null;
}

function renderChannelTiePicker() {
    const list = document.getElementById('ct-list');
    if (!list || !channelTieSelection) return;

    const q = (document.getElementById('ct-filter').value || '').trim().toLowerCase();
    const rows = channelTieOptions.filter(c => !q || (c.name || '').toLowerCase().includes(q));

    list.innerHTML = '';
    if (!channelTieOptions.length) {
        const li = document.createElement('li');
        li.className = 'channel-picker-hint';
        li.textContent = 'This lounge has no chat channels to tie to yet.';
        list.appendChild(li);
    }

    rows.forEach(c => {
        const li = document.createElement('li');
        li.className = 'channel-picker-row';

        const box = document.createElement('input');
        box.type = 'checkbox';
        box.checked = channelTieSelection.has(Number(c.id));
        box.onchange = () => {
            if (box.checked) channelTieSelection.add(Number(c.id));
            else channelTieSelection.delete(Number(c.id));
            updateChannelTieSummary();
        };

        const name = document.createElement('span');
        name.className = 'channel-picker-name';
        // textContent: a channel name is member-authored.
        name.textContent = `# ${c.name}`;

        li.append(box, name);

        // A private channel narrows the board to its own members, which is the
        // one consequence of tying that is not obvious from the tick alone.
        const lockClass = CHANNEL_LOCK_ICONS[c.permission_level];
        if (lockClass) {
            const lock = document.createElement('i');
            lock.className = lockClass;
            lock.style.cssText = 'margin-left: auto; color: #888; font-size: 0.8em;';
            lock.title = CHANNEL_LOCK_TITLES[c.permission_level] || '';
            li.appendChild(lock);
        }

        li.onclick = (event) => {
            if (event.target !== box) { box.checked = !box.checked; box.onchange(); }
        };
        list.appendChild(li);
    });

    updateChannelTieSummary();
}

// Says out loud what the current ticks mean, because "none ticked" and "all
// ticked" look similar in a list and mean very different things. It is phrased
// in terms of PEOPLE, not places: a tie has never moved this board, and saying
// "listed in #x" would promise a sidebar change that does not happen.
function updateChannelTieSummary() {
    const out = document.getElementById('ct-summary');
    if (!out || !channelTieSelection) return;
    const n = channelTieSelection.size;
    if (!n) {
        out.textContent = 'Open to the whole lounge — everyone who can open this lounge sees it.';
        return;
    }
    const names = channelTieOptions
        .filter(c => channelTieSelection.has(Number(c.id)))
        .map(c => '#' + c.name);
    out.textContent = `Visible only to people who can see ${names.join(' or ')}.`;
}

function handleSaveChannelTies(button) {
    if (!channelTiesTarget || !channelTieSelection) return;
    const channelId = channelTiesTarget.id;
    const ids = Array.from(channelTieSelection).map(Number);

    button.disabled = true;
    fetch(`${API_BASE_URL}/api/lounge/channel/${channelId}/ties`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ channel_ids: ids })
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (!ok || !body.ok) throw new Error(body.error || 'Could not save.');
        closeChannelTiesModal();
        showToast(ids.length ? 'Board tied.' : 'Board is now lounge-wide.', 'success');
        // The server broadcasts this to the lounge as well; doing it here too
        // means the mod who made the change sees it without waiting on a socket.
        reloadLoungeChannels(currentLoungeId);
    })
    .catch(err => showToast(err.message || 'Could not save.', 'error'))
    .finally(() => { button.disabled = false; });
}

// Re-fetch and re-draw the sidebar's channel list. The tie editor and the
// lounge_channels_changed socket event both need this, and neither can patch
// the list in place: a tie change can remove a board the member may no longer
// open at all, which only the server can decide.
function reloadLoungeChannels(loungeId) {
    if (!loungeId) return;
    fetch(`${API_BASE_URL}/api/lounge/${loungeId}/channels`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json())
    .then(data => {
        if (String(loungeId) !== String(currentLoungeId)) return;
        if (!data || !Array.isArray(data.channels)) return;
        renderLoungeChannels(data.channels, data.channel_groups);
        highlightSidebarChannel(currentLoungeChannelId);
    })
    .catch(() => { /* the sidebar keeps what it had */ });
}

function closeChannelPrivacyModal() {
    document.getElementById('channel-privacy-modal').classList.add('hidden');
    popModalHistory('channel-privacy-modal');
    channelPrivacyTarget = null;
    currentChannelPickerSelection = null;
}

function onChannelPrivacyChange() {
    const level = document.querySelector('input[name="cp-permission"]:checked')?.value;
    const picker = document.getElementById('cp-members-picker');
    if (!picker) return;
    const on = level === 'restricted';
    picker.classList.toggle('hidden', !on);
    if (on) {
        if (!currentChannelPickerSelection) currentChannelPickerSelection = new Set();
        renderChannelMemberPicker('cp-members-list', 'cp-members-filter');
    }
}

function handleSaveChannelPrivacy(button) {
    if (!channelPrivacyTarget) return;
    const level = document.querySelector('input[name="cp-permission"]:checked')?.value;
    if (!level) return;

    const members = level === 'restricted' ? channelPickerUsernames() : [];
    // The server adds the caller anyway, so an empty list is not the disaster it
    // looks like -- but it almost always means the owner did not realise they had
    // to choose anybody, and a channel of one is worth a question.
    if (level === 'restricted' && members.length === 0) {
        showToast('Pick at least one other person, or this channel will only be yours.', 'error');
        return;
    }

    if (button) button.disabled = true;
    fetch(`${API_BASE_URL}/api/lounge/channel/${channelPrivacyTarget.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        // The name is required by the endpoint and unchanged here; sending the
        // current one keeps this a visibility-only edit.
        body: JSON.stringify({
            name: channelPrivacyTarget.name,
            permission_level: level,
            members: members,
        })
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status !== 200 || !body.ok) {
            showToast(body.error || 'Could not update the channel.', 'error');
            return;
        }
        closeChannelPrivacyModal();
        showToast('Channel visibility updated.', 'success');
        // Reload the lounge: a channel that just became restricted may have to
        // disappear from the sidebar of everyone looking at it, this session
        // included.
        showLounge(currentLoungeId, document.getElementById('lounge-header-title').textContent);
    })
    .catch(() => showToast('Could not update the channel.', 'error'))
    .finally(() => { if (button) button.disabled = false; });
}

// The Create Channel dialog is the second way into project tools, alongside the
// switch in Lounge Settings. Both set the same flag server-side; this only warns
// that picking one of these types will flip it.
function onChannelKindChange() {
    const kind = document.querySelector('input[name="channel-kind"]:checked')?.value || 'chat';
    const hint = document.getElementById('channel-kind-hint');
    if (hint) hint.classList.toggle('hidden', kind === 'chat');
}

function handleCreateChannel() {
    // Format to lowercase and replace spaces with hyphens
    const name = document.getElementById('new-channel-name').value.trim().toLowerCase().replace(/\s+/g, '-');
    const permission = document.querySelector('input[name="channel-permission"]:checked').value;
    const kind = document.querySelector('input[name="channel-kind"]:checked')?.value || 'chat';

    if (!name) {
        showToast('Please enter a channel name.', 'error');
        return;
    }

    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/channels`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({
            name: name,
            permission_level: permission,
            kind: kind,
            // Only meaningful for 'restricted'; the server ignores it otherwise.
            members: permission === 'restricted' ? channelPickerUsernames() : undefined,
            // Chat channels only; the server ignores it for a board.
            group_id: createChannelGroupId ?? undefined,
        })
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 201) {
            closeCreateChannelModal();
            // Refresh the entire lounge view to show the new channel
            showLounge(currentLoungeId, document.getElementById('lounge-header-title').textContent);
        } else {
            alert('Error: ' + body.error);
        }
    });
}

function showAllCircuitsPage() {
    // --- THIS IS THE FIX: We now add the "New Circuit" button to this page's header ---
    const headerRight = document.querySelector('#all-circuits-page .header-right');
    headerRight.innerHTML = `
        <button class="login-btn" onclick="navigateTo('/circuits/new')">New Circuit</button>
    `;
    // --- END OF FIX ---

    renderAllCircuitsGrid(); // This function will now only render the grid of circuits
    showPage('all-circuits-page');
}

function handleForcePasswordSubmit() {
    const newPass = document.getElementById('force-new-password').value;
    if (newPass.length < MIN_PASSWORD_LENGTH) {
        alert(`Password must be at least ${MIN_PASSWORD_LENGTH} characters.`);
        return;
    }

    fetch(`${API_BASE_URL}/api/auth/update-password`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ new_password: newPass })
    })
    .then(r => r.json())
    .then(data => {
        if (data.ok) {
            showToast("Password updated! You can now access your account.",'success');
            document.getElementById('force-password-modal').classList.add('hidden');
            
            // Resume normal login flow
            fetchConversations();
            initializeSocket();
            fetchNotifications();
            navigateTo('/'); 
        } else {
            alert(data.error);
        }
    });
}

function showForgotPasswordModal() {
    document.getElementById('forgot-password-modal').classList.remove('hidden');
    document.getElementById('forgot-password-input').value = ''; // Clear input
    document.getElementById('forgot-password-input').focus();
}

function closeForgotPasswordModal() {
    document.getElementById('forgot-password-modal').classList.add('hidden');
}

function handleForgotPasswordSubmit() {
    const identifier = document.getElementById('forgot-password-input').value.trim();
    if (!identifier) {
        showToast("Please enter your username or email.", "error");
        return;
    }

    const btn = document.querySelector('#forgot-password-modal .confirm-btn-confirm');
    const originalText = btn.textContent;
    btn.disabled = true;
    btn.textContent = "Sending...";

    fetch(`${API_BASE_URL}/api/auth/forgot-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ identifier: identifier })
    })
    .then(r => r.json())
    .then(data => {
        if (data.ok) {
            showToast(data.message, 'success');
            closeForgotPasswordModal();
        } else {
            showToast(data.error, 'error');
        }
    })
    .catch(err => {
        console.error(err);
        showToast("Network error. Please try again.", 'error');
    })
    .finally(() => {
        btn.disabled = false;
        btn.textContent = originalText;
    });
}

function renderAllCircuitsGrid() {
    const grid = document.getElementById('all-circuits-grid');
    grid.innerHTML = '';
    
    // 1. Build the creation card, but hand it to the grid AFTER the scroller has
    //    filled it -- the scroller owns the container's children and clears it on
    //    the way in, which is what used to swallow this card entirely.
    const createCard = document.createElement('div');
    createCard.className = 'circuit-card create-circuit-card';
    createCard.onclick = () => navigateTo('/circuits/new');
    createCard.innerHTML = `<h4>+</h4><p>New Circuit</p>`;

    // 2. Pass the rest to the virtual scroller
    applyVirtualScroller('all-circuits-grid', allCircuitsData, 'circuits', (circuit) => {
        const card = document.createElement('div');
        card.className = 'circuit-card';
        card.onclick = () => navigateTo(`/circuits/${circuit.code}`);
        
        if (circuit.coverImage) {
            card.style.backgroundImage = `url(${circuit.coverImage})`;
        } else {
            card.classList.add('no-image');
        }
        
        card.innerHTML = `
            <h4>${circuit.title}</h4>
            <p>${circuit.hostSchool}</p>
        `;
        return card;
    });

    grid.prepend(createCard);
}

function toggleMessageOptions(event, messageId) {
    event.stopPropagation();
    // Close any other open dropdowns first
    document.querySelectorAll('.message-options-dropdown').forEach(d => d.classList.add('hidden'));

    const dropdown = document.getElementById(`options-dropdown-${messageId}`);
    dropdown.classList.toggle('hidden');

    // Position the dropdown correctly next to the button
    const buttonRect = event.target.getBoundingClientRect();
    dropdown.style.top = `${buttonRect.bottom + 5}px`;
    dropdown.style.left = `${buttonRect.left - dropdown.offsetWidth + buttonRect.width}px`;
}

function copyMessage(messageId) {
    const textElement = document.getElementById(`message-text-${messageId}`);
    if (textElement) {
        navigator.clipboard.writeText(textElement.textContent)
            .then(() => alert('Message copied!'))
            .catch(err => console.error('Failed to copy text: ', err));
    }
    // Close all dropdowns after action
    document.querySelectorAll('.message-options-dropdown').forEach(d => d.classList.add('hidden'));
}

function deleteMessage(messageId) {
    if (confirm('Are you sure you want to delete this message?')) {
        fetch(`${API_BASE_URL}/api/dm/message/${messageId}`, {
            method: 'DELETE',
            headers: { 'Authorization': `Bearer ${apiToken}` }
        });
    }
    document.querySelectorAll('.message-options-dropdown').forEach(d => d.classList.add('hidden'));
}



function showEditUI(messageId) {
    const contentDiv = document.getElementById(`message-content-${messageId}`);
    const text = contentDiv.querySelector('p').textContent;

    contentDiv.innerHTML = `
        <input type="text" id="edit-input-${messageId}" value="${text}" style="width: 80%;" />
        <button onclick="saveEdit(${messageId})">Save</button>
        <button onclick="cancelEdit(${messageId}, '${text}')">Cancel</button>
    `;
    document.querySelectorAll('.message-options-dropdown').forEach(d => d.classList.add('hidden'));
}

function saveEdit(messageId) {
    const newText = document.getElementById(`edit-input-${messageId}`).value.trim();
    if (!newText) return;

    fetch(`${API_BASE_URL}/api/dm/message/${messageId}/edit`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ new_text: newText })
    });
}

function cancelEdit(messageId, originalText) {
    // This is just a UI function, it doesn't need to call the server.
    const contentDiv = document.getElementById(`message-content-${messageId}`);
    contentDiv.innerHTML = `<p id="message-text-${messageId}">${originalText}</p>`;
}

// Declared, not conjured. This used to spring into existence only as a side effect
// of fetchAndRenderLounges() running -- so opening a lounge without having passed
// through the home page first left it undefined, and the `if (allLoungesData)` in
// handleEditLounge threw a ReferenceError. That throw was caught by the fetch's
// .catch, which is why saving a lounge showed "updated successfully" immediately
// followed by "an unexpected error occurred", and why the live title update and the
// navigate-back after it never ran.
let allLoungesData = null;

// A lounge that isn't public says so on its card: a coloured ring around the circle
// and a labelled tag on its bottom rim. It used to be a white 0.8em icon in the
// corner, which vanished against any light cover photo. Shared by every lounge row
// and grid so they can't drift apart again. Returns the tag's HTML ('' for public).
function applyLoungePrivacy(card, privacy) {
    const kinds = {
        private:  { icon: 'fa-lock', label: 'Private',  title: 'Private lounge: request access to join' },
        unlisted: { icon: 'fa-link', label: 'Unlisted', title: 'Unlisted lounge: hidden from public discovery' },
    };
    const kind = kinds[privacy];
    if (!kind) return '';
    card.classList.add('has-privacy', `is-${privacy}`);
    return `<span class="lounge-privacy-tag" title="${kind.title}"><i class="fas ${kind.icon}" aria-hidden="true"></i>${kind.label}</span>`;
}

function fetchAndRenderLounges() {
    // Recommended order (members you know -> your communities -> same school ->
    // popular, with ~1/4 discovery). Fetch the full list so allLoungesData stays
    // complete for the edit-cache patch below; the row itself slices to 7.
    fetch(`${API_BASE_URL}/api/lounges/recommended?limit=1000`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(response => response.json())
    .then(lounges => {
        allLoungesData = lounges;
        const row = document.getElementById('lounge-list-row');
        row.innerHTML = '';

        const createCard = document.createElement('div');
        createCard.className = 'circuit-card create-circuit-card';
        createCard.onclick = () => navigateTo('/lounges/new');
        createCard.innerHTML = `<h4>+</h4><p>New Lounge</p>`;
        row.appendChild(createCard);

        lounges.slice(0, 7).forEach(lounge => {
            const card = document.createElement('div');
            card.className = 'circuit-card';
            // --- THIS IS THE FIX ---
            card.onclick = () => navigateToLounge(lounge.id);
            // --- END FIX ---
            
            if (loungeCoverUrl(lounge)) {
                card.style.backgroundImage = `url("${loungeCoverUrl(lounge)}")`;
            } else {
                card.classList.add('no-image');
            }
            
            const privacyIcon = applyLoungePrivacy(card, lounge.privacy);
            
            card.innerHTML = `
                <h4>${truncate(lounge.name, 10)}</h4> 
                <p>${truncate(lounge.description, 15)}</p>
                ${privacyIcon}
            `;
            row.appendChild(card);
        });
    });
}

// Invitations still waiting on this user, shown above their lounges. The
// notifications list only keeps the newest rows, so an invite that wasn't
// answered right away used to be impossible to find by the time it mattered.
function fetchAndRenderLoungeInvites() {
    const boxes = ['explore-lounge-invites', 'my-lounge-invites']
        .map(id => document.getElementById(id)).filter(Boolean);
    if (!boxes.length || !apiToken) return;

    fetch(`${API_BASE_URL}/api/me/lounge-invites`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(response => response.ok ? response.json() : [])
    .then(invites => boxes.forEach(box => renderLoungeInvites(box, invites)))
    .catch(error => console.error('Failed to load lounge invites:', error));
}

function renderLoungeInvites(box, invites) {
    box.innerHTML = '';
    box.hidden = !invites || invites.length === 0;
    if (box.hidden) return;

    const heading = document.createElement('p');
    heading.className = 'lounge-invites-heading';
    heading.textContent = invites.length === 1 ? '1 invitation' : `${invites.length} invitations`;
    box.appendChild(heading);

    invites.forEach(invite => {
        const row = document.createElement('div');
        row.className = 'lounge-invite-row';

        const thumb = document.createElement('div');
        thumb.className = 'lounge-invite-thumb';
        if (loungeCoverUrl(invite.lounge)) {
            thumb.style.backgroundImage = `url("${loungeCoverUrl(invite.lounge)}")`;
        } else {
            thumb.innerHTML = '<i class="fas fa-couch"></i>';
        }

        const text = document.createElement('div');
        text.className = 'lounge-invite-text';
        const name = document.createElement('span');
        name.className = 'lounge-invite-name';
        name.textContent = invite.lounge.name;
        const meta = document.createElement('span');
        meta.className = 'lounge-invite-meta';
        const who = invite.inviter ? (invite.inviter.fullName || `@${invite.inviter.username}`) : 'Someone';
        meta.textContent = `${who} invited you · ${formatTimestamp(new Date(invite.timestamp))}`;
        text.append(name, meta);

        const actions = document.createElement('div');
        actions.className = 'lounge-invite-actions';
        const accept = document.createElement('button');
        accept.className = 'login-btn';
        accept.textContent = 'Join';
        const decline = document.createElement('button');
        decline.className = 'login-btn lounge-invite-decline';
        decline.textContent = 'Decline';
        actions.append(accept, decline);

        const respond = (action) => {
            accept.disabled = decline.disabled = true;
            fetch(`${API_BASE_URL}/api/notification/${invite.id}/respond`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
                body: JSON.stringify({ action })
            })
            .then(response => response.json())
            .then(data => {
                if (!data.ok) {
                    showToast(data.error || 'Could not respond to the invite.', 'error');
                    accept.disabled = decline.disabled = false;
                    return;
                }
                if (action === 'accept') {
                    navigateToLounge(invite.lounge.id);
                } else {
                    showToast(`Declined the invite to ${invite.lounge.name}.`, 'success');
                }
                fetchAndRenderMyLounges();
            })
            .catch(() => {
                showToast('Could not respond to the invite. Please try again.', 'error');
                accept.disabled = decline.disabled = false;
            });
        };
        accept.onclick = () => respond('accept');
        decline.onclick = () => respond('decline');

        row.append(thumb, text, actions);
        box.appendChild(row);
    });
}

function fetchAndRenderMyLounges() {
    fetchAndRenderLoungeInvites();
    // 1. Always fetch the data first
    fetch(`${API_BASE_URL}/api/me/lounges`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(response => response.json())
    .then(lounges => {
        // --- CALCULATION LOGIC FIX ---
        let totalUnread = 0;
        unreadChannelSet.clear(); // Reset the tracking set on full refresh

        lounges.forEach(l => {
            if (l.unread_count > 0) {
                totalUnread += l.unread_count;
                // --- THIS IS THE FIX: Populate the set with specific channel IDs ---
                if (l.unread_channel_ids) {
                    l.unread_channel_ids.forEach(id => unreadChannelSet.add(id));
                }
                // ------------------------------------------------------------------
            }
        });
        
        unreadLoungeCount = totalUnread; // Sync global variable
        updatePageTitleCount();

        // Explore deliberately carries NO lounge count any more. Lounges are read
        // in Messages now, so a badge here pointed at the wrong tab: you tapped
        // it, found a directory of lounges to join, and still had to go to
        // Messages to read the thing that raised it. The number goes to the
        // Messages nav item and to the Lounges half of the switch instead.
        const exploreBadge = document.getElementById('explore-notification-badge');
        if (exploreBadge) exploreBadge.style.display = 'none';
        updateNotificationBadge();
        
        // 2. Render to Explore Page Row if visible
        const exploreRow = document.getElementById('explore-my-lounges-list');
        const myLoungesGrid = document.getElementById('my-lounges-grid');
        
        // Helper to render a card
        const createCard = (lounge) => {
            const card = document.createElement('div');
            card.className = 'circuit-card';
            card.id = `lounge-card-${lounge.id}`; 
            
            card.onclick = () => navigateToLounge(lounge.id);
            
            if (loungeCoverUrl(lounge)) {
                card.style.backgroundImage = `url("${loungeCoverUrl(lounge)}")`;
            } else {
                card.classList.add('no-image');
            }
            
            const privacyIcon = applyLoungePrivacy(card, lounge.privacy);
            
            let badgeHtml = '';
            if (lounge.unread_count > 0) {
                const countDisplay = lounge.unread_count > 99 ? '99+' : lounge.unread_count;
                badgeHtml = `<div class="lounge-unread-badge">${countDisplay}</div>`;
            }

            card.innerHTML = `
                ${badgeHtml}
                ${privacyIcon}
                <h4>${truncate(lounge.name, 10)}</h4> 
                <p>${truncate(lounge.description, 15)}</p>
            `;
            return card;
        };

        // Render Explore Page
        if (exploreRow && document.getElementById('explore-page').classList.contains('active')) {
            exploreRow.innerHTML = '';
            if (lounges.length === 0) {
                exploreRow.innerHTML = '<p style="padding-left: 15px; color: #888;">You haven\'t joined any lounges yet.</p>';
            } else {
                lounges.slice(0, 8).forEach(l => exploreRow.appendChild(createCard(l)));
            }
        } 
        
        // Render My Lounges Page
        if (myLoungesGrid && document.getElementById('my-lounges-page').classList.contains('active')) {
            myLoungesGrid.innerHTML = '';
            if (lounges.length === 0) {
                myLoungesGrid.innerHTML = '<p>You are not a member of any lounges yet.</p>';
            } else {
                lounges.forEach(l => myLoungesGrid.appendChild(createCard(l)));
            }
        }
    });
}

// --- Group mention handles (@everyone, @mods, @<job label>, @<channel>) -------
// These name a group rather than a person, so they resolve against the lounge
// rather than against /api/users/details -- which is why they cannot go through
// verifyMentions(): there is no account called "everyone", and that path would
// correctly conclude the handle is fake and strip it back to grey text. Someone
// typing @everyone has to be able to see that it registered.

const RESERVED_GROUP_HANDLES = new Set(['everyone', 'mods']);

// Mirrors _title_slug() on the server. The two have to agree, or a label
// highlights here and notifies nobody -- which is worse than not highlighting,
// because the writer believes it landed.
function titleHandleSlug(title) {
    const slug = (title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    return (slug.length >= 4 && slug.length <= 20) ? slug : null;
}

function isGroupMentionHandle(handle) {
    // Only inside a lounge. linkifyUsernames() is shared with DMs, posts and
    // articles, where "@everyone" is just a word somebody typed.
    if (!isLoungeOnScreen()) return false;

    const key = (handle || '').toLowerCase();
    if (RESERVED_GROUP_HANDLES.has(key)) return true;

    // Job labels come from the member list this lounge already loaded.
    if (Object.values(loungeMemberTitles || {})
            .some(title => titleHandleSlug(title) === key)) return true;

    // ...and channel handles from the same list the sidebar is drawn from, which
    // only ever holds channels this member may open. Highlighted on existence
    // rather than on permission, exactly like @everyone above: whether the
    // handle FIRES is the lounge's broadcast setting, which the server owns.
    return (currentLoungeChannelList || [])
        .some(c => (c.kind || 'chat') === 'chat' && titleHandleSlug(c.name) === key);
}

// --- #hashtags ---------------------------------------------------------------
// One spelling of what counts as a tag, and it has to agree with the server's
// HASHTAG_REGEX: a '#' this highlights and links but the server never indexed
// leads to an empty tag page, which reads as the feature being broken rather
// than as the word not being a tag.
//
// \p{L} rather than [a-z], because a great deal of what gets written on APEX is
// Korean and a tag rule that silently dropped #축제 would be useless to the
// people using tags most. A tag that is only digits is not a tag (#1 and #2020
// are ordinals and years), and a '#' glued to the end of a word is not one
// either -- see the notes in server.py, which this mirrors.
const HASHTAG_MAX_LEN = 60;

// Capture 1 is the character before the '#', re-emitted by the replacer. A
// lookbehind would read better, but this runs inside the one function that
// renders every post, DM and article body -- and a RegExp the engine refuses
// to construct throws there, blanking all of it. Lookbehind is the newest
// thing in this regex by years, so it is the part not worth betting that page
// on. A fresh object per call: a /g regex carries lastIndex between uses.
function hashtagLinkRegex() {
    return new RegExp(
        String.raw`(^|[^\p{L}\p{N}_#])#([\p{L}\p{N}_]{1,${HASHTAG_MAX_LEN}})(?![\p{L}\p{N}_])`,
        'gu'
    );
}

// The stored spelling of a tag: lowercased, no '#'. Mirrors normalize_hashtag().
function normalizeHashtag(raw) {
    const tag = String(raw || '').trim().replace(/^#+/, '').toLowerCase();
    if (!tag || tag.length > HASHTAG_MAX_LEN) return null;
    if (/^\p{N}+$/u.test(tag)) return null;            // #1, #2020
    if (!/^[\p{L}\p{N}_]+$/u.test(tag)) return null;
    return tag;
}

function linkifyUsernames(text) {
    if (!text) return '';

    const urlRegex = /(\b(?:https?:\/\/|www\.|[a-zA-Z0-9.-]+\.(?:com|org|net|edu|gov|io|kr|xyz|info))[^\s]*)/gi;
    
    // Updated to match your new strict 4-20 character backend rules!
    // Same regex the composer highlights with -- see mentionLinkRegex().
    const usernameRegex = mentionLinkRegex();
    
    let formattedText = text;

    formattedText = formattedText.replace(urlRegex, (match) => {
        let fullUrl = match;
        const punctuation = /[.,!?;:]+$/;
        const cleanMatch = match.replace(punctuation, '');
        if (!/^https?:\/\//i.test(fullUrl)) {
            fullUrl = 'https://' + fullUrl;
        }
        return `<a href="#" class="gradient-hyperlink" onclick="handleExternalLinkClick(event, '${fullUrl}')">${match}</a>`;
    });

    // After the URLs, so a '#' inside a link's fragment is already wrapped in an
    // anchor and out of reach, and before the mentions only because the two
    // cannot overlap -- '#' and '@' are both excluded from a handle's
    // characters, so neither pass can eat the other's marker.
    formattedText = formattedText.replace(hashtagLinkRegex(), (fullMatch, pre, raw) => {
        const tag = normalizeHashtag(raw);
        // Not a tag the server would have indexed (all digits, say). Left as
        // the plain text it was written as rather than linked to nothing.
        if (!tag) return fullMatch;
        // A real href, so the link can be copied, opened in a tab and read by
        // a screen reader as the link it is; the handler keeps the tap itself
        // inside the app. No quoting needed on `tag`: normalizeHashtag has
        // already refused anything but letters, digits and underscore.
        return `${pre}<a href="/tags/${encodeURIComponent(tag)}" class="hashtag-link"` +
               ` data-tag="${tag}" onclick="openHashtag(event, '${tag}')">#${raw}</a>`;
    });

    formattedText = formattedText.replace(usernameRegex, (fullMatch, username) => {
        // A group handle is settled here and now -- it has no account to look up,
        // so sending it down the unverified path would have verifyMentions()
        // strip it to plain text a moment later.
        if (isGroupMentionHandle(username)) {
            return `<span class="group-mention">${fullMatch}</span>`;
        }
        // Already settled once this session: render the final form straight away.
        // Otherwise every re-render (sending a message redraws the whole list)
        // drops each mention back to plain text until verifyMentions() answers,
        // and the links visibly reset and re-apply.
        const key = username.toLowerCase();
        if (mentionValidity.get(key) === true) {
            return `<a href="/users/${encodeURIComponent(key)}" class="user-mention"` +
                   ` data-username="${escapeMentionText(key)}" onclick="openUserMention(event, this)">${fullMatch}</a>`;
        }
        if (mentionValidity.get(key) === false) return fullMatch;
        // Pass 1: Render a temporary unverified span
        return `<span class="unverified-mention" data-username="${escapeMentionText(key)}">${fullMatch}</span>`;
    });

    return formattedText;
}

function openUserMention(event, a) {
    event.stopPropagation();
    event.preventDefault();
    // The profile opens on the page behind whatever this mention was
    // rendered into, so a modal around it has to come down first --
    // otherwise the post lightbox stays parked over the profile it
    // just navigated to. No-op outside a modal.
    navigateFromModal(a, `/users/${a.dataset.username}`);
}

function verifyMentions() {
    const unverified = document.querySelectorAll('.unverified-mention');
    if (unverified.length === 0) return;

    // 1. Gather all unique usernames currently on screen
    const usernamesToVerify = new Set();
    unverified.forEach(el => usernamesToVerify.add(el.dataset.username));

    // 2. Use your existing endpoint to bulk-check them
    fetch(`${API_BASE_URL}/api/users/details`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ usernames: Array.from(usernamesToVerify) })
    })
    .then(response => response.json())
    .then(validUsers => {
        // Create a quick lookup set of valid usernames
        const validUsernames = new Set(validUsers.map(u => u.username.toLowerCase()));
        // Remembered so the next render links these immediately -- see linkifyUsernames().
        usernamesToVerify.forEach(name => noteMentionValidity(name, validUsernames.has(name)));

        // 3. Pass 2: Upgrade or Downgrade the spans
        unverified.forEach(el => {
            const username = el.dataset.username;
            const originalText = el.textContent;

            if (validUsernames.has(username)) {
                // IT'S REAL! Upgrade to a clickable hyperlink
                const a = document.createElement('a');
                a.href = `/users/${username}`;
                a.className = 'user-mention';
                a.dataset.username = username;
                a.onclick = (event) => openUserMention(event, a);
                a.textContent = originalText;
                el.replaceWith(a);
            } else {
                // FAKE USER! Strip the span and leave boring plain text
                const textNode = document.createTextNode(originalText);
                el.replaceWith(textNode);
            }
        });
    })
    .catch(err => console.error("Mention verification failed:", err));
}


// ---------------------------------------------------------------------------
// Message previews: link cards and mention cards
// ---------------------------------------------------------------------------
// A link or an @mention in a DM or lounge message gets a small card under the
// bubble: thumbnail, title and site for a link (fetched and cached server-side,
// see link_previews.py -- the phone never contacts the linked site), avatar and
// name for a person. The bubble text is untouched. Cards hang off the
// text-content wrapper next to polls, outside the bubble, so they never sit under
// double-tap reactions or swipe-to-reply.
const MESSAGE_PREVIEW_MAX_LINKS = 2;
const MESSAGE_PREVIEW_MAX_MENTIONS = 2;
// The shape linkifyUsernames() turns into a link, so a card only ever sits under
// something that visibly is one.
const PREVIEW_URL_REGEX = /\b(?:https?:\/\/|www\.|[a-zA-Z0-9.-]+\.(?:com|org|net|edu|gov|io|kr|xyz|info))[^\s]*/gi;

// url -> { status: 'pending' | 'ready' | 'none' | 'retry', data, promise, retryAt }
const linkPreviewCache = new Map();
// username (lowercase) -> { status: 'pending' | 'ready' | 'none', data, promise, resolve }
const mentionCardCache = new Map();
let mentionCardFlushTimer = null;

function normalizePreviewUrl(raw) {
    const trimmed = raw.replace(/[.,!?;:'")\]}>]+$/, '');
    if (!trimmed) return null;
    const withScheme = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
    try {
        const url = new URL(withScheme);
        if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
        url.hash = '';
        return url.href;
    } catch (e) {
        return null;
    }
}

function previewDomain(url) {
    try {
        return new URL(url).hostname.replace(/^www\./, '');
    } catch (e) {
        return url;
    }
}

// An APEX post link of our own -- /posts/<id> or the older /post/<id> spelling,
// on this origin. Sending a post puts one of these in a DM, and it deserves the
// post itself rather than a generic page card scraped back off our own server.
const APEX_POST_LINK = /^\/posts?\/(\d+)\/?$/;

function apexPostIdFromUrl(url) {
    try {
        const parsed = new URL(url);
        if (parsed.origin !== window.location.origin) return null;
        const match = APEX_POST_LINK.exec(parsed.pathname);
        return match ? Number(match[1]) : null;
    } catch (e) {
        return null;
    }
}

// A message that is NOTHING but one APEX post link -- which is exactly what
// the send sheet produces. Those render as the post card alone: the URL is
// plumbing, and printing it above the card said the same thing twice, once in
// a form nobody reads. A link someone typed alongside words keeps its text,
// because there the sentence is the message and the card is the footnote.
function postOnlyMessageId(text) {
    const trimmed = (text || '').trim();
    if (!trimmed || /\s/.test(trimmed)) return null;
    return apexPostIdFromUrl(normalizePreviewUrl(trimmed) || '');
}

// The links, posts and mentions in a message worth a card, in the order they appear.
function messagePreviewTargets(text) {
    const links = [];
    const posts = [];
    const mentions = [];
    if (!text) return { links, posts, mentions };

    const linkRanges = [];
    for (const match of text.matchAll(PREVIEW_URL_REGEX)) {
        linkRanges.push([match.index, match.index + match[0].length]);
        // "someone@gmail.com" -- the domain half of an address, not a link.
        if (match.index > 0 && text[match.index - 1] === '@') continue;
        const url = normalizePreviewUrl(match[0]);
        if (!url) continue;
        const postId = apexPostIdFromUrl(url);
        if (postId) {
            if (!posts.includes(postId) && posts.length < MESSAGE_PREVIEW_MAX_LINKS) posts.push(postId);
            continue;
        }
        if (!links.includes(url) && links.length < MESSAGE_PREVIEW_MAX_LINKS) links.push(url);
    }
    for (const match of text.matchAll(mentionLinkRegex())) {
        // medium.com/@someone is part of a link, not a mention.
        if (linkRanges.some(([start, end]) => match.index >= start && match.index < end)) continue;
        const username = match[1].toLowerCase();
        if (!mentions.includes(username) && mentions.length < MESSAGE_PREVIEW_MAX_MENTIONS) mentions.push(username);
    }
    return { links, posts, mentions };
}

function requestLinkPreview(url) {
    const cached = linkPreviewCache.get(url);
    if (cached && (cached.status !== 'retry' || Date.now() < cached.retryAt)) return cached.promise;

    const entry = { status: 'pending', data: null, retryAt: 0 };
    entry.promise = fetch(`${API_BASE_URL}/api/link-preview?url=${encodeURIComponent(url)}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(res => res.json().then(body => ({ status: res.status, body })))
    .then(({ status, body }) => {
        if (status === 429 || status >= 500) {
            // Rate-limited or the server hiccupped: nothing is known about this
            // link yet, so ask again later rather than deciding it has no card.
            entry.status = 'retry';
            entry.retryAt = Date.now() + 60000;
            return null;
        }
        entry.data = (body && body.preview) || null;
        entry.status = entry.data ? 'ready' : 'none';
        return entry.data;
    })
    .catch(() => {
        entry.status = 'retry';
        entry.retryAt = Date.now() + 30000;
        return null;
    });
    linkPreviewCache.set(url, entry);
    return entry.promise;
}

// Mentions resolve through the same bulk endpoint verifyMentions() uses, batched
// across a render so a thread full of @s is one request, not one per name.
function requestMentionUser(username) {
    const existing = mentionCardCache.get(username);
    if (existing) return existing.promise;

    const entry = { status: 'pending', data: null };
    entry.promise = new Promise(resolve => { entry.resolve = resolve; });
    mentionCardCache.set(username, entry);
    clearTimeout(mentionCardFlushTimer);
    mentionCardFlushTimer = setTimeout(flushMentionUserRequests, 30);
    return entry.promise;
}

function flushMentionUserRequests() {
    const batch = [...mentionCardCache.entries()].filter(([, e]) => e.status === 'pending' && !e.inFlight);
    if (!batch.length) return;
    batch.forEach(([, e]) => { e.inFlight = true; });

    const settle = (users) => {
        const byName = new Map((users || []).map(u => [String(u.username).toLowerCase(), u]));
        batch.forEach(([name, e]) => {
            if (users === null) {
                // A failed request is not "no such user": forget it so the next
                // render asks again.
                mentionCardCache.delete(name);
                e.resolve(null);
                return;
            }
            e.data = byName.get(name) || null;
            e.status = e.data ? 'ready' : 'none';
            e.resolve(e.data);
        });
    };

    fetch(`${API_BASE_URL}/api/users/details`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ usernames: batch.map(([name]) => name) })
    })
    .then(res => (res.ok ? res.json() : null))
    .then(users => settle(Array.isArray(users) ? users : null))
    .catch(() => settle(null));
}

// postId -> { status, data, promise }. One request per post per session, shared
// by every bubble that links it -- a thread where the same post was sent three
// times is one fetch.
const postCardCache = new Map();

function requestPostCard(postId) {
    const existing = postCardCache.get(postId);
    if (existing) return existing.promise;

    const entry = { status: 'pending', data: null };
    entry.promise = fetch(`${API_BASE_URL}/api/post/${postId}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(res => (res.ok ? res.json() : null))
    .then(post => {
        entry.data = post && post.id ? post : null;
        entry.status = entry.data ? 'ready' : 'none';
        return entry.data;
    })
    .catch(() => {
        // A failed request is not "no such post" -- forget it so the next
        // render asks again, the same way requestMentionUser does.
        postCardCache.delete(postId);
        return null;
    });
    postCardCache.set(postId, entry);
    return entry.promise;
}

// A post sent into a chat, drawn as the post rather than as a reference to
// one. The send sheet's whole job is to put someone's post in front of a
// friend, and a filename-width row with a stamp of the photo beside it made
// them tap through to find out what they had been sent. So: the author across
// the top the way the magnified post has it, the picture at the size it was
// taken at, the caption under it. The URL that carried it is not shown at all
// (see postOnlyMessageId).
function buildPostCard(post) {
    const author = post.author || {};
    const username = author.username || 'unknown';
    if (author.username && !profileData[username]) {
        profileData[username] = {
            username, name: author.fullName, fullName: author.fullName,
            rank: author.rank, profilePicUrl: author.profilePic,
            account_type: author.account_type,
        };
    }

    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'post-preview-card';
    card.addEventListener('click', (event) => {
        event.stopPropagation();
        navigateTo(`/posts/${post.id}`);
    });

    // --- Who wrote it ------------------------------------------------------
    const head = document.createElement('span');
    head.className = 'post-preview-head';

    const pic = document.createElement('span');
    pic.className = 'profile-pic post-preview-pic';
    pic.setAttribute('data-user-pic-id', username);
    head.appendChild(pic);

    const who = document.createElement('span');
    who.className = 'post-preview-author';
    who.textContent = author.fullName || username;   // textContent: user input
    who.insertAdjacentHTML('beforeend', ` ${rankIconFor(username, author.rank)}`);
    head.appendChild(who);

    card.appendChild(head);

    // --- The picture -------------------------------------------------------
    const images = postImagesOf(post);
    if (images.length) {
        const media = document.createElement('span');
        media.className = 'post-preview-media';
        // The same capped box every other surface gives a post, so the crop
        // here is the crop they will see when they open it.
        media.style.aspectRatio = String(postBoxRatio(post.image_ratio));

        const img = document.createElement('img');
        img.src = images[0];
        img.alt = '';
        img.loading = 'lazy';
        media.appendChild(img);

        if (images.length > 1) {
            const badge = document.createElement('span');
            badge.className = 'post-preview-badge';
            badge.innerHTML = '<i class="fas fa-clone"></i>';
            badge.append(String(images.length));
            media.appendChild(badge);
        }
        card.appendChild(media);
    }

    // --- Caption and footer ------------------------------------------------
    const body = document.createElement('span');
    body.className = 'post-preview-body';

    if (post.text) {
        const text = document.createElement('span');
        // A post with no picture has nothing else to show, so it gets the room
        // the picture would have taken.
        text.className = images.length ? 'post-preview-text' : 'post-preview-text is-lead';
        text.textContent = post.text;
        body.appendChild(text);
    }

    const meta = document.createElement('span');
    meta.className = 'post-preview-meta';

    if (post.poll) {
        // Named, not drawn: the card points at the post, and a votable poll in
        // a chat bubble would be a second place to answer the same question.
        const chip = document.createElement('span');
        chip.className = 'post-preview-chip';
        chip.innerHTML = '<i class="fas fa-square-poll-vertical"></i>Poll';
        meta.appendChild(chip);
    }

    const where = document.createElement('span');
    where.className = 'post-preview-where';
    where.textContent = (post.circuit && post.circuit.title) || 'Post';
    meta.appendChild(where);

    const likes = document.createElement('span');
    likes.className = 'post-preview-likes';
    likes.innerHTML = '<i class="fas fa-heart"></i>';
    likes.append(String(post.likes || 0));
    meta.appendChild(likes);

    body.appendChild(meta);
    card.appendChild(body);

    // Scoped to the card, so the avatar paints before it is attached.
    updateProfilePictures(username, card);
    return card;
}

function buildLinkPreviewCard(preview, url) {
    const card = document.createElement('a');
    card.className = 'link-preview-card';
    if (preview.kind === 'video') card.classList.add('is-video');
    card.href = url;
    card.rel = 'noopener noreferrer';
    // Through the same "you're leaving APEX" check as the link in the bubble.
    card.addEventListener('click', (event) => handleExternalLinkClick(event, url));

    if (preview.image) {
        const media = document.createElement('span');
        media.className = 'link-preview-media';
        const img = document.createElement('img');
        img.src = preview.image;
        img.alt = '';
        img.loading = 'lazy';
        img.decoding = 'async';
        media.appendChild(img);
        if (preview.kind === 'video') {
            const play = document.createElement('span');
            play.className = 'link-preview-play';
            play.innerHTML = '<i class="fas fa-play"></i>';
            media.appendChild(play);
        }
        card.appendChild(media);
    }

    // Spans, never <p>: every <p> inside a chat message is painted as a bubble.
    const body = document.createElement('span');
    body.className = 'link-preview-body';
    const site = document.createElement('span');
    site.className = 'link-preview-site';
    site.textContent = preview.site_name || preview.domain || previewDomain(url);
    body.appendChild(site);
    const title = document.createElement('span');
    title.className = 'link-preview-title';
    title.textContent = preview.title || preview.domain || previewDomain(url);
    body.appendChild(title);
    if (preview.description && preview.kind !== 'video') {
        const desc = document.createElement('span');
        desc.className = 'link-preview-desc';
        desc.textContent = preview.description;
        body.appendChild(desc);
    }
    card.appendChild(body);
    return card;
}

function buildMentionCard(user) {
    const username = String(user.username);
    // Seed the avatar cache the way seedLoungeAuthorCache does, so the picture can
    // be painted from profileData like every other avatar.
    if (!profileData[username]) {
        profileData[username] = {
            username, name: user.fullName, fullName: user.fullName,
            rank: user.rank, profilePicUrl: user.profile_pic
        };
    } else if (!profileData[username].profilePicUrl && user.profile_pic) {
        profileData[username].profilePicUrl = user.profile_pic;
    }

    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'mention-preview-card';
    card.addEventListener('click', (event) => {
        event.stopPropagation();
        openUserPreview(username);
    });

    const pic = document.createElement('div');
    pic.className = 'profile-pic mention-preview-pic';
    pic.setAttribute('data-user-pic-id', username);
    card.appendChild(pic);

    const text = document.createElement('span');
    text.className = 'mention-preview-text';
    const name = document.createElement('span');
    name.className = 'mention-preview-name';
    name.textContent = user.fullName || username;
    name.insertAdjacentHTML('beforeend', ` ${rankIconFor(username, user.rank)}`);
    const handle = document.createElement('span');
    handle.className = 'mention-preview-handle';
    handle.textContent = `@${username}`;
    text.append(name, handle);
    card.appendChild(text);

    const chevron = document.createElement('i');
    chevron.className = 'fas fa-chevron-right';
    card.appendChild(chevron);

    // Scoped to the card, so this works before it is attached to the page.
    updateProfilePictures(username, card);
    return card;
}

// A card that arrives while you're reading the newest message must not push that
// message up out of view.
function keepChatBottomPinned(scope, mutate) {
    const body = document.getElementById(scope === 'dm' ? 'chat-body' : 'lounge-body');
    const pinned = body && body.scrollHeight - body.scrollTop - body.clientHeight < 60;
    mutate();
    if (pinned) body.scrollTop = body.scrollHeight;
}

function appendMessagePreviews(wrapper, msg, scope) {
    // A spoiler stays hidden until tapped; a card under it would give it away.
    if (!msg || msg.is_deleted || !msg.text || msg.effect === 'spoiler') return;
    const { links, posts, mentions } = messagePreviewTargets(msg.text);
    if (!links.length && !posts.length && !mentions.length) return;

    const container = document.createElement('div');
    container.className = 'message-previews';
    // The card IS the message here, not an annotation hanging under one, so it
    // loses the indent and the width cap a footnote card gets.
    if (postOnlyMessageId(msg.text)) container.classList.add('is-solo-post');
    wrapper.appendChild(container);

    const slots = [
        ...posts.map(key => ({ type: 'post', key })),
        ...links.map(key => ({ type: 'link', key })),
        ...mentions.map(key => ({ type: 'mention', key })),
    ];
    slots.forEach(slot => {
        // One slot per target, created up front, so cards that resolve out of order
        // still land in the order the message mentions them.
        const holder = document.createElement('div');
        holder.className = 'message-preview-slot';
        container.appendChild(holder);

        const drop = () => {
            holder.remove();
            if (!container.children.length) container.remove();
        };
        const fill = (data) => {
            if (!data) { drop(); return; }
            const card = slot.type === 'link' ? buildLinkPreviewCard(data, slot.key)
                : slot.type === 'post' ? buildPostCard(data)
                : buildMentionCard(data);
            if (holder.isConnected) keepChatBottomPinned(scope, () => holder.appendChild(card));
            else holder.appendChild(card);
        };

        const cache = slot.type === 'link' ? linkPreviewCache
            : slot.type === 'post' ? postCardCache
            : mentionCardCache;
        const entry = cache.get(slot.key);
        // Known answers are drawn synchronously, so a re-render (the lounge
        // rebuilds every bubble on each new message) never flickers or jumps.
        if (entry && entry.status === 'ready') fill(entry.data);
        else if (entry && entry.status === 'none') drop();
        else (slot.type === 'link' ? requestLinkPreview(slot.key)
            : slot.type === 'post' ? requestPostCard(slot.key)
            : requestMentionUser(slot.key)).then(fill);
    });
}


// ---------------------------------------------------------------------------
// @mention autocomplete
// ---------------------------------------------------------------------------
// Every field whose text is later run through linkifyUsernames() can carry a
// mention, so those are exactly the fields that get the picker. Typing '@' at the
// start of a word opens it; it filters as you type and completes on click, Tab or
// Enter.
const MENTION_INPUT_IDS = ['main-chat-input-field', 'lounge-input-field', 'postText', 'editBio',
                           'notice-input-field', 'notice-comment-input', 'pc-input'];
// The characters that can follow '@' in a query. This is linkifyUsernames()'s own
// set minus '@' itself, which would swallow the opening '@' when scanning back.
const MENTION_QUERY_CHARS = /[a-z0-9!#$%^&*(),._-]/i;
// Whether a username is one linkifyUsernames() would actually turn into a link.
// Offering anyone else would complete a mention that silently stays plain text.
// Short handles are the admin-granted exceptions -- see SHORT_MENTION_HANDLES.
const MENTION_LINKABLE = /^(?:[a-z0-9!@#$%^&*(),._-]{4,20}|s)$/i;
const MENTION_CACHE_TTL_MS = 5 * 60 * 1000;
const MENTION_MAX_MATCHES = 30;

let mentionUsers = [];
let mentionUsersFetchedAt = 0;
let mentionUsersPromise = null;
let mentionEl = null;
let mentionState = null; // { input, start, query, matches, index } while open

function loadMentionUsers() {
    if (mentionUsers.length && Date.now() - mentionUsersFetchedAt < MENTION_CACHE_TTL_MS) {
        return Promise.resolve(mentionUsers);
    }
    if (mentionUsersPromise) return mentionUsersPromise;

    // Relevance-ordered by the server (posts + followers), so the default list is
    // already the people you're most likely to mean. Cached and filtered locally --
    // a round trip per keystroke would never keep up with typing.
    mentionUsersPromise = fetch(`${API_BASE_URL}/api/users/for-chat`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
        .then(res => res.json())
        .then(users => {
            mentionUsers = (Array.isArray(users) ? users : [])
                .filter(u => u && MENTION_LINKABLE.test(u.username || ''));
            mentionUsersFetchedAt = Date.now();
            // updateProfilePictures() reads avatars out of profileData, same as the
            // new-chat list does.
            mentionUsers.forEach(u => {
                if (!profileData[u.username]) profileData[u.username] = { name: u.fullName, ...u };
                // Everyone here exists, so the composer's highlighter can skip a
                // lookup for them.
                noteMentionValidity(u.username, true);
            });
            refreshMentionOverlays(true);
            return mentionUsers;
        })
        .catch(err => {
            console.error('Mention user list failed:', err);
            return [];
        })
        .finally(() => { mentionUsersPromise = null; });

    return mentionUsersPromise;
}

// The '@...' being typed at the caret, or null if the caret isn't in one.
function readMentionQuery(input) {
    const caret = input.selectionStart;
    if (caret === null || caret !== input.selectionEnd) return null; // a selection, not a caret

    const text = input.value.slice(0, caret);
    let i = caret;
    while (i > 0 && MENTION_QUERY_CHARS.test(text[i - 1])) i--;

    if (i === 0 || text[i - 1] !== '@') return null;
    const at = i - 1;
    // Only at a word start, so emails and "a@b" don't open the picker.
    if (at > 0 && !/\s/.test(text[at - 1])) return null;

    const query = text.slice(i, caret);
    if (query.length > 20) return null; // past what a username could be

    return { start: at, query };
}

// ---------------------------------------------------------------------------
// #hashtag autocomplete -- the same picker, a second trigger
// ---------------------------------------------------------------------------
// A tag is only worth anything if the next person spells it the same way, so
// the moment somebody types '#' is the moment to show them what already exists:
// the bare '#' lists the tags most relevant to them, and every letter after it
// narrows that down. The ranking is the server's (see suggest_hashtags): exact,
// then prefix, then substring, each ordered by use, this week's use, the
// writer's own use and how often it appears with the tags already in the draft.
const TAG_SUGGEST_DEBOUNCE_MS = 150;
const TAG_SUGGEST_LIMIT = 8;
const TAG_SUGGEST_CACHE_TTL_MS = 60 * 1000;
const tagSuggestCache = new Map(); // "query|with" -> { at, tags }
let tagSuggestTimer = null;
let tagSuggestSeq = 0;

// The '#...' being typed at the caret, or null if the caret isn't in one.
// Mirrors hashtagLinkRegex(): the '#' must not be glued to the end of a word
// (a#b, a URL's fragment), and a digits-only word is an ordinal, not a tag.
function readTagQuery(input) {
    const caret = input.selectionStart;
    if (caret === null || caret !== input.selectionEnd) return null;

    const text = input.value.slice(0, caret);
    let i = caret;
    while (i > 0 && /[\p{L}\p{N}_]/u.test(text[i - 1])) i--;

    if (i === 0 || text[i - 1] !== '#') return null;
    const hash = i - 1;
    if (hash > 0 && /[\p{L}\p{N}_#/:.&=?]/u.test(text[hash - 1])) return null;

    const query = text.slice(i, caret);
    if (query.length > HASHTAG_MAX_LEN) return null;
    if (query && /^\p{N}+$/u.test(query)) return null; // #1, #2020

    return { start: hash, query };
}

// The tags already written in this field, minus the one being typed, so the
// server can rank what goes with them and leave them out of the list.
function draftTagsExcept(input, start) {
    const value = input.value;
    let end = start + 1;
    while (end < value.length && /[\p{L}\p{N}_]/u.test(value[end])) end++;
    const text = value.slice(0, start) + ' ' + value.slice(end);
    const tags = [];
    for (const m of text.matchAll(hashtagLinkRegex())) {
        const tag = normalizeHashtag(m[2]);
        if (tag && !tags.includes(tag)) tags.push(tag);
        if (tags.length >= 10) break;
    }
    return tags;
}

function tagSuggestKey(query, withTags) {
    return `${query.toLowerCase()}|${withTags.join(',')}`;
}

function fetchTagSuggestions(query, withTags) {
    const key = tagSuggestKey(query, withTags);
    const hit = tagSuggestCache.get(key);
    if (hit && Date.now() - hit.at < TAG_SUGGEST_CACHE_TTL_MS) return Promise.resolve(hit.tags);

    const params = new URLSearchParams({ q: query, limit: String(TAG_SUGGEST_LIMIT) });
    if (withTags.length) params.set('with', withTags.join(','));
    return fetch(`${API_BASE_URL}/api/tags/suggest?${params}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
        .then(r => r.json())
        .then(body => {
            const tags = (body && Array.isArray(body.tags)) ? body.tags : [];
            tagSuggestCache.set(key, { at: Date.now(), tags });
            return tags;
        })
        .catch(() => []); // a convenience: the '#' still types either way
}

// The second line of a tag row: why it is in the list, in the order it matters.
function describeTagSuggestion(row) {
    const parts = [row.count === 1 ? '1 post' : `${row.count} posts`];
    if (row.recent) parts.push(`${row.recent} this week`);
    if (row.with) parts.push('goes with your tags');
    else if (row.mine) parts.push('you\'ve used it');
    return parts.join(' · ');
}

function cancelTagSuggest() {
    clearTimeout(tagSuggestTimer);
    tagSuggestSeq++;
}

function updateTagPicker(input, hit) {
    clearTimeout(tagSuggestTimer);
    const seq = ++tagSuggestSeq;
    const withTags = draftTagsExcept(input, hit.start);
    const run = () => {
        fetchTagSuggestions(hit.query, withTags).then(tags => {
            if (seq !== tagSuggestSeq) return; // a later keystroke asked again
            const now = document.activeElement === input ? readTagQuery(input) : null;
            if (!now || now.start !== hit.start || now.query !== hit.query) return;
            // Nothing to browse and nothing typed yet: stay out of the way
            // rather than open an empty box over a fresh install.
            if (!tags.length && !hit.query) {
                closeMentionPicker();
                return;
            }
            mentionState = {
                kind: 'tag',
                input,
                start: hit.start,
                query: hit.query,
                matches: tags,
                index: 0
            };
            renderMentionPicker();
        });
    };
    // A cached answer draws at once; only a trip to the server waits for the
    // typing to settle.
    const cached = tagSuggestCache.get(tagSuggestKey(hit.query, withTags));
    if (cached && Date.now() - cached.at < TAG_SUGGEST_CACHE_TTL_MS) run();
    else tagSuggestTimer = setTimeout(run, TAG_SUGGEST_DEBOUNCE_MS);
}

// The group handles the picker offers, ahead of the people. Synthesised rather
// than fetched: there is no account behind @everyone, so /api/users/for-chat --
// which is where mentionUsers comes from -- can never return one. That is the
// whole reason typing "@every" used to show an empty picker while the handle it
// was about to produce worked perfectly well on send.
function groupMentionEntries() {
    // Only inside a lounge. In a DM or a post there is no group to name.
    if (!isLoungeOnScreen()) return [];

    const entries = [];

    // @everyone and @mods are gated on the lounge's broadcast setting, so they
    // are offered only to people the server would actually let use them.
    if (currentLoungeCanBroadcast) {
        entries.push({
            username: 'everyone',
            fullName: 'Everyone',
            isGroup: true,
            icon: 'fa-users',
            hint: 'Notifies every member of this lounge',
        });
        entries.push({
            username: 'mods',
            fullName: 'Moderators',
            isGroup: true,
            icon: 'fa-user-shield',
            hint: 'Notifies this lounge\'s owner and moderators',
        });
    }

    // Job labels are never gated -- they name a working group of a few people,
    // which is the same reach as naming them one at a time. Deduped by slug,
    // because several members share one label and it is one handle.
    const seen = new Set();
    Object.values(loungeMemberTitles || {}).forEach(title => {
        const slug = titleHandleSlug(title);
        if (!slug || seen.has(slug)) return;
        seen.add(slug);
        const count = Object.values(loungeMemberTitles)
            .filter(t => titleHandleSlug(t) === slug).length;
        entries.push({
            username: slug,
            fullName: title,
            isGroup: true,
            icon: 'fa-tag',
            hint: `${count} member${count === 1 ? '' : 's'} with this job label`,
        });
    });

    // Channel handles: "@highschool" reaches the people who can open #highschool.
    // Offered on the same terms the server resolves them on -- a restricted
    // channel is a working group of a few people and is free, anything else is
    // readable by the whole lounge and so is the broadcast setting's business.
    // Sharing `seen` with the job labels above means a channel and a label that
    // slug the same way are one handle in the list, not two rows that do the
    // same thing.
    (currentLoungeChannelList || []).forEach(channel => {
        if ((channel.kind || 'chat') !== 'chat') return;
        const slug = titleHandleSlug(channel.name);
        if (!slug || seen.has(slug)) return;
        const restricted = channel.permission_level === 'restricted';
        if (!restricted && !currentLoungeCanBroadcast) return;
        seen.add(slug);
        entries.push({
            username: slug,
            fullName: `#${channel.name}`,
            isGroup: true,
            icon: 'fa-hashtag',
            hint: restricted && channel.access_count
                ? `${channel.access_count} member${channel.access_count === 1 ? '' : 's'} of #${channel.name}`
                : `Notifies everyone who can see #${channel.name}`,
        });
    });

    return entries;
}

function rankMentionMatches(query) {
    const q = query.toLowerCase();

    // Group rows sit above the people. They match on handle or label, and they
    // lead the list because "@everyone" is an exact target somebody is typing on
    // purpose -- ranking it among forty names would hide the thing they asked for.
    const groups = groupMentionEntries().filter(g =>
        !q || g.username.startsWith(q) || g.fullName.toLowerCase().includes(q));

    if (!q) {
        return groups.concat(mentionUsers).slice(0, MENTION_MAX_MATCHES);
    }

    // Bands, best first. sort() is stable, so the server's relevance order survives
    // inside each band.
    const scored = [];
    for (const u of mentionUsers) {
        const username = (u.username || '').toLowerCase();
        const fullName = (u.fullName || '').toLowerCase();
        let band = -1;

        if (username.startsWith(q)) band = 0;
        else if (fullName.startsWith(q)) band = 1;
        else if (fullName.split(/\s+/).some(word => word.startsWith(q))) band = 2; // surname, etc
        else if (username.includes(q)) band = 3;
        else if (fullName.includes(q)) band = 4;

        if (band >= 0) scored.push({ u, band });
    }
    scored.sort((a, b) => a.band - b.band);
    return groups.concat(scored.map(s => s.u)).slice(0, MENTION_MAX_MATCHES);
}

function escapeMentionText(text) {
    const div = document.createElement('div');
    div.textContent = text == null ? '' : text;
    return div.innerHTML;
}

// Show which part of the row the query actually matched, so it's obvious why a
// result is in the list.
function highlightMentionMatch(text, query) {
    const safe = escapeMentionText(text);
    if (!query) return safe;
    const at = (text || '').toLowerCase().indexOf(query.toLowerCase());
    if (at < 0) return safe;
    return escapeMentionText(text.slice(0, at))
        + '<b class="mention-hit">' + escapeMentionText(text.slice(at, at + query.length)) + '</b>'
        + escapeMentionText(text.slice(at + query.length));
}

function ensureMentionEl() {
    if (mentionEl) return mentionEl;

    mentionEl = document.createElement('div');
    mentionEl.className = 'mention-picker';
    mentionEl.setAttribute('role', 'listbox');
    // Keep the caret in the field: a blur here would close the picker before the
    // click ever lands.
    mentionEl.addEventListener('mousedown', event => event.preventDefault());
    document.body.appendChild(mentionEl);
    return mentionEl;
}

function renderMentionPicker() {
    const el = ensureMentionEl();
    const { matches, index, query } = mentionState;

    if (mentionState.kind === 'tag') {
        renderTagPicker(el, matches, index, query);
        el.classList.add('is-open');
        positionMentionPicker();
        return;
    }

    if (!matches.length) {
        el.innerHTML = `<div class="mention-empty">No one matches <b>@${escapeMentionText(query)}</b></div>`;
    } else {
        const rows = matches.map((user, i) => {
            const active = i === index ? ' is-active' : '';
            const lead = user.isGroup
                ? `<div class="mention-group-icon"><i class="fas ${user.icon}"></i></div>`
                : `<div class="profile-pic" data-user-pic-id="${escapeMentionText(user.username)}"></div>`;
            // A group's second line explains what it will do; a person's repeats
            // their handle, which is what you are matching against.
            const sub = user.isGroup
                ? `<span class="mention-username">${escapeMentionText(user.hint)}</span>`
                : `<span class="mention-username">@${highlightMentionMatch(user.username, query)}</span>`;
            const title = user.isGroup
                ? `@${highlightMentionMatch(user.username, query)}`
                : highlightMentionMatch(user.fullName || user.username, query);
            return `
            <li class="mention-item${active}${user.isGroup ? ' is-group' : ''}" role="option"
                aria-selected="${i === index}" data-index="${i}">
                ${lead}
                <div class="mention-identity">
                    <span class="mention-name">${title}${user.isGroup ? '' : rankIconFor(user.username, user.rank)}</span>
                    ${sub}
                </div>
            </li>`;
        }).join('');

        el.innerHTML = `<ul class="mention-list">${rows}</ul>`;

        el.querySelectorAll('.mention-item').forEach(item => {
            const i = Number(item.dataset.index);
            item.addEventListener('click', () => applyMention(matches[i]));
            item.addEventListener('mouseenter', () => setMentionIndex(i, false));
        });
        // Only real people have avatars to fill in.
        matches.filter(u => !u.isGroup).forEach(user => updateProfilePictures(user.username, el));
    }

    el.classList.add('is-open');
    positionMentionPicker();
}

function renderTagPicker(el, matches, index, query) {
    if (!matches.length) {
        // Not an error: a new tag is a perfectly good thing to write. Say so,
        // so the box reads as "you're first" rather than "not allowed".
        el.innerHTML = `<div class="mention-empty">New tag <b>#${escapeMentionText(query)}</b> — no posts use it yet</div>`;
        return;
    }
    const head = query ? 'Tags' : 'Popular tags';
    const rows = matches.map((row, i) => `
        <li class="mention-item is-tag${i === index ? ' is-active' : ''}" role="option"
            aria-selected="${i === index}" data-index="${i}">
            <div class="mention-group-icon"><i class="fas fa-hashtag"></i></div>
            <div class="mention-identity">
                <span class="mention-name">#${highlightMentionMatch(row.tag, query)}</span>
                <span class="mention-username">${escapeMentionText(describeTagSuggestion(row))}</span>
            </div>
        </li>`).join('');
    el.innerHTML = `<div class="mention-picker-head">${head}</div><ul class="mention-list">${rows}</ul>`;

    el.querySelectorAll('.mention-item').forEach(item => {
        const i = Number(item.dataset.index);
        item.addEventListener('click', () => applyMention(matches[i]));
        item.addEventListener('mouseenter', () => setMentionIndex(i, false));
    });
}

// Shared placement for the two composer pickers (@mention and //command).
//
// Desktop: a card floating over the field, as wide as the field within
// [minWidth, maxWidth], above it unless there isn't room.
//
// Phone: a sheet spanning the whole screen edge to edge, sat flush on top of the
// composer bar. A 300px card hovering over a 390px screen with slivers of chat
// showing either side of it read as a desktop popup that had wandered onto a
// phone; attached to the composer it reads as part of the keyboard area, which
// is where the eye already is.
function placeComposerPicker(el, input, minWidth, maxWidth) {
    const phone = document.documentElement.classList.contains('ui-phone');
    el.classList.toggle('is-sheet', phone);

    if (phone) {
        // The composer bar, not the textarea inside it: the textarea is inset by
        // the bar's padding and buttons, and a sheet stopping short of the bar's
        // edge leaves a strip of thread showing between the two.
        const anchor = input.closest('.chat-input') || input;
        const rect = anchor.getBoundingClientRect();
        const gap = anchor === input ? 8 : 0;
        el.style.width = '';
        el.style.left = '0px';

        const height = el.offsetHeight;
        let top = rect.top - gap - height;
        let placement = 'above';
        if (top < 0) {
            top = rect.bottom + gap;
            placement = 'below';
        }
        el.style.top = `${Math.round(top)}px`;
        el.dataset.placement = placement;
        return;
    }

    const rect = input.getBoundingClientRect();
    const margin = 8;
    const width = Math.max(minWidth, Math.min(rect.width, maxWidth));
    el.style.width = `${width}px`;

    const height = el.offsetHeight;
    // Sit above the field by default -- chat inputs live at the bottom of the
    // screen -- and flip below only when there isn't room up there.
    let top = rect.top - margin - height;
    let placement = 'above';
    if (top < margin) {
        top = rect.bottom + margin;
        placement = 'below';
    }

    const left = Math.max(margin, Math.min(rect.left, window.innerWidth - width - margin));
    el.style.top = `${Math.round(top)}px`;
    el.style.left = `${Math.round(left)}px`;
    el.dataset.placement = placement;
}

function positionMentionPicker() {
    if (!mentionState || !mentionEl) return;
    placeComposerPicker(mentionEl, mentionState.input, 248, 380);
}

function setMentionIndex(index, scrollIntoView = true) {
    if (!mentionState || !mentionState.matches.length) return;

    const count = mentionState.matches.length;
    mentionState.index = ((index % count) + count) % count; // wraps both ways

    const items = mentionEl.querySelectorAll('.mention-item');
    items.forEach((item, i) => {
        const active = i === mentionState.index;
        item.classList.toggle('is-active', active);
        item.setAttribute('aria-selected', String(active));
        if (active && scrollIntoView) item.scrollIntoView({ block: 'nearest' });
    });
}

function closeMentionPicker() {
    mentionState = null;
    if (mentionEl) {
        mentionEl.classList.remove('is-open');
        mentionEl.innerHTML = '';
    }
}

function applyMention(user) {
    if (!mentionState || !user) return;

    const { input, start, query } = mentionState;
    const insert = mentionState.kind === 'tag' ? `#${user.tag} ` : `@${user.username} `;
    const before = input.value.slice(0, start);
    const after = input.value.slice(start + 1 + query.length);

    input.value = before + insert + after;
    const caret = before.length + insert.length;
    input.setSelectionRange(caret, caret);
    closeMentionPicker();
    input.focus();

    // Setting .value fires no 'input' event, and the field's other listeners --
    // auto-resize, send-button toggle, typing indicator, char counter -- all hang
    // off one.
    input.dispatchEvent(new Event('input', { bubbles: true }));
}

function updateMentionPicker(input) {
    if (!readMentionQuery(input)) {
        const tagHit = readTagQuery(input);
        if (tagHit) {
            updateTagPicker(input, tagHit);
            return;
        }
        cancelTagSuggest();
        closeMentionPicker();
        return;
    }
    // Now an @: a '#' answer still in flight must not land on top of it.
    cancelTagSuggest();

    loadMentionUsers().then(() => {
        // The caret can move while the first fetch is in flight.
        const hit = document.activeElement === input ? readMentionQuery(input) : null;
        if (!hit) {
            closeMentionPicker();
            return;
        }
        mentionState = {
            input,
            start: hit.start,
            query: hit.query,
            matches: rankMentionMatches(hit.query),
            index: 0
        };
        renderMentionPicker();
    });
}

function handleMentionKeydown(event) {
    if (!mentionState || event.target !== mentionState.input) return;
    if (event.isComposing || event.keyCode === 229) return; // mid-CJK composition

    if (event.key === 'Escape') {
        closeMentionPicker();
    } else if (!mentionState.matches.length) {
        return; // nothing to pick: leave Enter alone so the message still sends
    } else if (event.key === 'ArrowDown') {
        setMentionIndex(mentionState.index + 1);
    } else if (event.key === 'ArrowUp') {
        setMentionIndex(mentionState.index - 1);
    } else if (event.key === 'Enter' || event.key === 'Tab') {
        applyMention(mentionState.matches[mentionState.index]);
    } else {
        return;
    }

    // Runs in the capture phase, so stopping here is what keeps Enter from also
    // sending the message and the arrows from moving the caret.
    event.preventDefault();
    event.stopImmediatePropagation();
}

document.addEventListener('input', e => {
    if (e.target && e.target.id === 'rp-details') updateReportSubmitState();
});

function initializeMentionPicker() {
    MENTION_INPUT_IDS.forEach(id => {
        const input = document.getElementById(id);
        if (!input) return;

        input.addEventListener('input', () => updateMentionPicker(input));
        // Caret moved by arrow/click without editing: re-read where we are.
        input.addEventListener('keyup', event => {
            if (['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) updateMentionPicker(input);
        });
        input.addEventListener('click', () => updateMentionPicker(input));
        input.addEventListener('blur', () => {
            cancelTagSuggest();
            closeMentionPicker();
        });
    });

    // Capture, so this beats the send-on-Enter listeners bound to the fields.
    document.addEventListener('keydown', handleMentionKeydown, true);
    window.addEventListener('resize', positionMentionPicker);
    window.addEventListener('scroll', positionMentionPicker, true);

    initializeMentionHighlighter();
}

// ---------------------------------------------------------------------------
// The `//` command palette
// ---------------------------------------------------------------------------
// Typing '//' at the start of a chat composer opens a list of every message
// effect, each with its argument shape and one line saying what it does -- the
// same affordance a game console gives you, and the reason //fire is no longer
// something you can only find out about by being told.
//
// Structurally a sibling of the @mention picker above: same floating panel, same
// filter-as-you-type, same capture-phase keydown so Enter picks a row instead of
// sending the message. It borrows that picker's escaping and match-highlighting
// helpers rather than growing a second copy of them.
//
// Only the two chat composers get it. The other fields the mention picker
// serves (postText, editBio) never reach extract_message_effect() on the server,
// so offering commands there would complete something that stays literal text.
const COMMAND_INPUT_IDS = ['main-chat-input-field', 'lounge-input-field'];

let commandEl = null;
let commandState = null; // { input, start, end, word, matches, index } while open

// The '//...' being typed, or null if the caret isn't in one.
//
// Anchored to the START of the message deliberately: extract_message_effect()
// only recognises a command there (it lstrips, then requires a leading '//'), so
// a '//' in the middle of a sentence -- a URL, a code snippet, a comment -- is
// ordinary text, and the palette must not suggest otherwise.
function readCommandQuery(input) {
    const caret = input.selectionStart;
    if (caret === null || caret !== input.selectionEnd) return null; // a selection, not a caret

    const text = input.value;
    const before = text.slice(0, caret).match(/^(\s*)\/\/([a-z]*)$/i);
    if (!before) return null;

    // The caret can sit in the MIDDLE of a command being edited, so the word
    // runs on past it. Completion has to replace the whole word rather than just
    // the half to the left of the caret, or "//fi|re" completes to "//firere".
    const tail = (text.slice(caret).match(/^[a-z]*/i) || [''])[0];
    return {
        start: before[1].length,        // where '//' begins, after any leading space
        end: caret + tail.length,       // where the command word ends
        word: before[2] + tail
    };
}

// Prefix matches first, then anything containing the query. Short list, exact
// names -- there is nothing here that needs the mention picker's five bands.
function rankCommandMatches(query) {
    const q = (query || '').toLowerCase();
    if (!q) return MESSAGE_EFFECTS.slice();

    const startsWith = [];
    const contains = [];
    for (const cmd of MESSAGE_EFFECTS) {
        if (cmd.name.startsWith(q)) startsWith.push(cmd);
        else if (cmd.name.includes(q)) contains.push(cmd);
    }
    return startsWith.concat(contains);
}

function ensureCommandEl() {
    if (commandEl) return commandEl;

    commandEl = document.createElement('div');
    commandEl.className = 'command-picker';
    commandEl.setAttribute('role', 'listbox');
    // Keep the caret in the field: a blur here would close the panel before the
    // click ever lands.
    commandEl.addEventListener('mousedown', event => event.preventDefault());
    document.body.appendChild(commandEl);
    return commandEl;
}

function renderCommandPicker() {
    const el = ensureCommandEl();
    const { matches, index, word } = commandState;

    if (!matches.length) {
        el.innerHTML = `<div class="command-empty">No command called <b>//${escapeMentionText(word)}</b></div>`;
    } else {
        const rows = matches.map((cmd, i) => `
            <li class="command-item${i === index ? ' is-active' : ''}" role="option"
                aria-selected="${i === index}" data-index="${i}">
                <span class="command-line">
                    <span class="command-name">//${highlightMentionMatch(cmd.name, word)}</span>
                    <span class="command-args">${escapeMentionText(cmd.args)}</span>
                </span>
                <span class="command-blurb">${escapeMentionText(cmd.blurb)}</span>
            </li>`).join('');

        el.innerHTML = `<div class="command-head">Message commands</div>
                        <ul class="command-list">${rows}</ul>`;

        el.querySelectorAll('.command-item').forEach(item => {
            const i = Number(item.dataset.index);
            item.addEventListener('click', () => applyCommand(matches[i]));
            item.addEventListener('mouseenter', () => setCommandIndex(i, false));
        });
    }

    el.classList.add('is-open');
    positionCommandPicker();
}

function positionCommandPicker() {
    if (!commandState || !commandEl) return;
    placeComposerPicker(commandEl, commandState.input, 268, 400);
}

function setCommandIndex(index, scrollIntoView = true) {
    if (!commandState || !commandState.matches.length) return;

    const count = commandState.matches.length;
    commandState.index = ((index % count) + count) % count; // wraps both ways

    commandEl.querySelectorAll('.command-item').forEach((item, i) => {
        const active = i === commandState.index;
        item.classList.toggle('is-active', active);
        item.setAttribute('aria-selected', String(active));
        if (active && scrollIntoView) item.scrollIntoView({ block: 'nearest' });
    });
}

function closeCommandPicker() {
    commandState = null;
    if (commandEl) {
        commandEl.classList.remove('is-open');
        commandEl.innerHTML = '';
    }
}

function applyCommand(cmd) {
    if (!commandState || !cmd) return;

    const { input, start, end } = commandState;
    const before = input.value.slice(0, start);
    const after = input.value.slice(end);

    // Only add the separating space when there isn't one already. Completing a
    // command that is being EDITED mid-word ("//fi|re hello") keeps the rest of
    // the line, and that line already starts with a space -- appending another
    // gave "//fire  hello".
    const hasSpace = after.startsWith(' ');
    const insert = `//${cmd.name}` + (hasSpace ? '' : ' ');

    input.value = before + insert + after;
    // Past the separator either way, so the caret lands where the message goes.
    const caret = before.length + insert.length + (hasSpace ? 1 : 0);
    input.setSelectionRange(caret, caret);
    closeCommandPicker();
    input.focus();

    // Setting .value fires no 'input' event, and the composer's other listeners
    // -- auto-resize, send-button toggle, typing indicator -- all hang off one.
    input.dispatchEvent(new Event('input', { bubbles: true }));
}

function updateCommandPicker(input) {
    const hit = readCommandQuery(input);
    if (!hit) {
        closeCommandPicker();
        return;
    }

    // No fetch and no await: the command list is a constant, so unlike the
    // mention picker this can be built synchronously and the caret cannot move
    // out from under it.
    commandState = {
        input,
        start: hit.start,
        end: hit.end,
        word: hit.word,
        matches: rankCommandMatches(hit.word),
        index: 0
    };
    renderCommandPicker();
}

function handleCommandKeydown(event) {
    if (!commandState || event.target !== commandState.input) return;
    if (event.isComposing || event.keyCode === 229) return; // mid-CJK composition

    if (event.key === 'Escape') {
        closeCommandPicker();
    } else if (!commandState.matches.length) {
        return; // nothing to pick: leave Enter alone so the message still sends
    } else if (event.key === 'ArrowDown') {
        setCommandIndex(commandState.index + 1);
    } else if (event.key === 'ArrowUp') {
        setCommandIndex(commandState.index - 1);
    } else if (event.key === 'Enter' || event.key === 'Tab') {
        applyCommand(commandState.matches[commandState.index]);
    } else {
        return;
    }

    // Runs in the capture phase, so stopping here is what keeps Enter from also
    // sending the message and the arrows from moving the caret.
    event.preventDefault();
    event.stopImmediatePropagation();
}

function initializeCommandPalette() {
    COMMAND_INPUT_IDS.forEach(id => {
        const input = document.getElementById(id);
        if (!input) return;

        input.addEventListener('input', () => updateCommandPicker(input));
        // Caret moved by arrow/click without editing: re-read where we are.
        input.addEventListener('keyup', event => {
            if (['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) updateCommandPicker(input);
        });
        input.addEventListener('click', () => updateCommandPicker(input));
        input.addEventListener('blur', () => closeCommandPicker());
    });

    // Capture, so this beats the send-on-Enter listeners bound to the fields.
    // It shares the phase with handleMentionKeydown, which is safe because the
    // two can never be open at once: one needs a leading '//', the other an '@'.
    document.addEventListener('keydown', handleCommandKeydown, true);
    window.addEventListener('resize', positionCommandPicker);
    // Passive: this fires for every scroll in the app, including the chat thread,
    // and it only ever reads a rect. Telling the browser it will never call
    // preventDefault keeps it off the critical path of a scroll.
    window.addEventListener('scroll', positionCommandPicker, { capture: true, passive: true });
}

// ---------------------------------------------------------------------------
// @mention and #hashtag live highlighting (composer + edit mode)
// ---------------------------------------------------------------------------
// A mention only turned blue once the text was posted, so while writing -- or
// while editing a post or a message, which reuse the same fields -- there was
// nothing to tell you whether "@sam" had actually landed on a real account.
//
// Tags are here for the same reason and answer a narrower question: not "does
// this exist" but "did the app read that as a tag at all". #2020 and a '#'
// typed onto the end of a word are not tags, and staying black while
// everything around them goes teal is the only warning anyone gets.
// A textarea cannot style its own text, so each mention field gets an overlay
// pinned exactly on top of it that repaints the verified mentions as links. The
// overlay mirrors the field's font, padding, wrapping and scroll offset, so the
// two texts sit glyph-for-glyph on each other; each mention paints an opaque
// patch of the field's own background first, so the plain text underneath is
// covered rather than doubled.
//
// Only usernames that exist get highlighted -- the same check the posted text
// gets in verifyMentions() -- so this is a live answer to "did that tag work?".

// One spelling of what counts as a mention, shared with linkifyUsernames() so the
// composer can never highlight something the rendered post would leave plain.
// A fresh object per call: a /g regex carries lastIndex between uses.
//
// SHORT_MENTION_HANDLES mirrors the server's SHORT_HANDLE_EXCEPTIONS: usernames an
// admin let past the 4-20 rule. They only count as the whole handle (the lookahead
// uses the server's handle characters), so @s links but @sam's front never does.
const SHORT_MENTION_HANDLES = ['s'];
function mentionLinkRegex() {
    return new RegExp(
        '@([a-z0-9!@#$%^&*(),._-]{4,20}|(?:' + SHORT_MENTION_HANDLES.join('|') + ')(?![a-z0-9!._*-]))',
        'gi'
    );
}

// username (lowercased) -> whether an account exists. Populated from the picker's
// user list and, for anyone missing from it (yourself, anyone the list omits), by
// the same bulk endpoint verifyMentions() uses.
const mentionValidity = new Map();
const mentionValidityQueue = new Set();
let mentionValidityTimer = null;

// input id -> { input, overlay, inner, signature }
const mentionOverlays = new Map();

// The properties that decide where a glyph lands. Copied onto the overlay so its
// line breaks fall in the same places as the field's.
const MENTION_OVERLAY_FONT_PROPS = [
    'fontFamily', 'fontSize', 'fontWeight', 'fontStyle', 'fontVariant', 'fontStretch',
    'lineHeight', 'letterSpacing', 'wordSpacing', 'textTransform', 'textIndent',
    'textAlign', 'direction', 'tabSize', 'overflowWrap', 'wordBreak'
];

function noteMentionValidity(username, exists) {
    if (username) mentionValidity.set(username.toLowerCase(), exists);
}

// null while we don't know yet -- unknown mentions stay plain until the answer
// arrives, so nothing flickers from link to plain text.
function isMentionValid(username) {
    const key = (username || '').toLowerCase();
    // Group handles are valid without a round trip -- and asking the user
    // endpoint about "everyone" would come back false and leave the composer
    // showing the handle as a typo while it is being typed.
    if (isGroupMentionHandle(key)) return true;
    if (mentionValidity.has(key)) return mentionValidity.get(key);

    if (!mentionValidityQueue.has(key)) {
        mentionValidityQueue.add(key);
        // One request per burst of typing rather than one per keystroke.
        if (!mentionValidityTimer) mentionValidityTimer = setTimeout(flushMentionValidity, 250);
    }
    return null;
}

function flushMentionValidity() {
    mentionValidityTimer = null;
    const names = Array.from(mentionValidityQueue);
    mentionValidityQueue.clear();
    if (!names.length || !apiToken) return;

    fetch(`${API_BASE_URL}/api/users/details`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ usernames: names })
    })
        .then(res => res.json())
        .then(users => {
            const found = new Set((Array.isArray(users) ? users : [])
                .map(u => (u.username || '').toLowerCase()));
            names.forEach(name => mentionValidity.set(name, found.has(name)));
            refreshMentionOverlays(true);
        })
        // Left uncached on failure: a lookup that never answered should be retried,
        // not remembered as "no such user".
        .catch(err => console.error('Mention highlight lookup failed:', err));
}

// The colour a mention has to paint over to hide the field's own text. Walks up
// until something is actually opaque, so themes and modals all mask correctly.
function fieldBackgroundColor(el) {
    let node = el;
    while (node && node.nodeType === 1) {
        const bg = getComputedStyle(node).backgroundColor;
        if (bg && bg !== 'transparent' && !/,\s*0\s*\)$/.test(bg)) return bg;
        node = node.parentElement;
    }
    return '#ffffff';
}

function ensureMentionOverlay(input) {
    const existing = mentionOverlays.get(input.id);
    if (existing) return existing;

    const overlay = document.createElement('div');
    overlay.className = 'mention-overlay';
    overlay.setAttribute('aria-hidden', 'true');

    const inner = document.createElement('div');
    inner.className = 'mention-overlay-text';
    overlay.appendChild(inner);

    // A sibling of the field, not a wrapper: several rules target
    // `.chat-input > textarea` directly, and position:absolute keeps the overlay
    // out of the composer's flex flow.
    (input.parentElement || document.body).appendChild(overlay);

    const entry = { input, overlay, inner, signature: null };
    mentionOverlays.set(input.id, entry);
    return entry;
}

// Absolutely positioned, so it has to be placed against whatever ancestor it
// actually resolves against.
function placeMentionOverlay(entry, rect) {
    const { overlay } = entry;
    const parent = overlay.offsetParent;
    let top = rect.top;
    let left = rect.left;

    if (parent && parent !== document.body && parent !== document.documentElement) {
        const parentRect = parent.getBoundingClientRect();
        top = rect.top - parentRect.top + parent.scrollTop - parent.clientTop;
        left = rect.left - parentRect.left + parent.scrollLeft - parent.clientLeft;
    } else {
        top += window.scrollY;
        left += window.scrollX;
    }

    overlay.style.top = `${top}px`;
    overlay.style.left = `${left}px`;
    overlay.style.width = `${rect.width}px`;
    overlay.style.height = `${rect.height}px`;
}

function styleMentionOverlay(entry) {
    const { input, overlay, inner } = entry;
    const cs = getComputedStyle(input);

    overlay.style.borderRadius = cs.borderRadius;
    MENTION_OVERLAY_FONT_PROPS.forEach(prop => { inner.style[prop] = cs[prop]; });

    // The field's text box: inside its border, minus any scrollbar (clientWidth
    // already accounts for both), carrying the field's own padding.
    inner.style.top = cs.borderTopWidth;
    inner.style.left = cs.borderLeftWidth;
    inner.style.width = `${input.clientWidth}px`;
    inner.style.paddingTop = cs.paddingTop;
    inner.style.paddingRight = cs.paddingRight;
    inner.style.paddingBottom = cs.paddingBottom;
    inner.style.paddingLeft = cs.paddingLeft;
    inner.style.whiteSpace = input.tagName === 'TEXTAREA' ? 'pre-wrap' : 'pre';
}

// Everything the overlay repaints, in the order it appears in the text.
//
// Two regexes over one string rather than one combined pattern: the two are
// shared with linkifyUsernames(), which is the whole point of them -- the
// composer must never highlight something the posted text would leave plain.
// Merging them into a third spelling here is how that guarantee quietly rots.
function mentionOverlayTokens(text) {
    const found = [];
    let match;

    const mentions = mentionLinkRegex();
    while ((match = mentions.exec(text)) !== null) {
        found.push({
            kind: 'mention',
            start: match.index,
            end: match.index + match[0].length,
            handle: match[1],
        });
    }

    const tags = hashtagLinkRegex();
    while ((match = tags.exec(text)) !== null) {
        // Capture 1 is the character BEFORE the '#' (the regex uses it in place
        // of a lookbehind -- see hashtagLinkRegex), so it is not part of the
        // token and the start has to skip past it.
        const start = match.index + match[1].length;
        found.push({
            kind: 'hashtag',
            start: start,
            end: match.index + match[0].length,
            handle: match[2],
        });
    }

    return found.sort((a, b) => a.start - b.start);
}

// The token the caret sits inside is left plain: the mask is opaque, and a
// caret underneath it is a caret you cannot see. The caret sitting at the END
// of a token counts as outside it, which is what makes a tag light up on the
// keystroke that finishes it rather than one character later.
function buildMentionOverlayHtml(input, maskColor) {
    const text = input.value || '';
    const focused = document.activeElement === input;
    const caret = focused && input.selectionStart === input.selectionEnd ? input.selectionStart : -1;

    let html = '';
    let cursor = 0;

    mentionOverlayTokens(text).forEach(token => {
        // Two independent scans, so a token could in principle begin inside one
        // already emitted. It cannot in practice -- '@' and '#' are each
        // excluded from the other's characters -- but emitting it anyway would
        // duplicate a slice of somebody's text on screen, so it is dropped
        // rather than trusted.
        if (token.start < cursor) return;

        if (caret > token.start && caret < token.end) return;

        // A mention is a link only if the account exists, and that answer comes
        // from the server -- isMentionValid returns null until it lands, which
        // is why an unknown handle stays plain rather than flickering. Whether a
        // '#' is a tag needs nothing from the server: it is a question about how
        // the thing is spelled, and normalizeHashtag is the same rule the server
        // indexes by. So tags highlight on the keystroke, mentions on the reply.
        const isLink = token.kind === 'mention'
            ? isMentionValid(token.handle) === true
            : normalizeHashtag(token.handle) !== null;
        if (!isLink) return;

        html += escapeMentionText(text.slice(cursor, token.start));
        html += `<span class="mention-overlay-token${token.kind === 'hashtag' ? ' is-hashtag' : ''}"`
            + ` style="background-color:${maskColor}">`
            + escapeMentionText(text.slice(token.start, token.end)) + '</span>';
        cursor = token.end;
    });

    return html + escapeMentionText(text.slice(cursor));
}

function syncMentionOverlay(input, force = false) {
    const entry = mentionOverlays.get(input.id);
    const rect = input.getBoundingClientRect();
    const visible = input.offsetParent !== null && rect.width > 0 && rect.height > 0;
    const selecting = document.activeElement === input && input.selectionStart !== input.selectionEnd;

    // Nothing to decorate, off-screen, or mid-selection -- the field's own
    // selection highlight has to win, so the overlay gets out of the way.
    if (!visible || !input.value || selecting) {
        if (entry) {
            entry.overlay.classList.remove('is-visible');
            entry.signature = null;
        }
        return;
    }

    const live = entry || ensureMentionOverlay(input);
    const caret = document.activeElement === input ? input.selectionStart : -1;
    const signature = [
        input.value, caret, Math.round(rect.width), Math.round(rect.height),
        Math.round(input.scrollTop), Math.round(input.scrollLeft),
        Math.round(rect.top), Math.round(rect.left)
    ].join('|');
    if (!force && live.signature === signature) return;
    live.signature = signature;

    // Shown before it is measured: a display:none overlay reports an all-zero
    // rect, and the correction below would read that as being 'off' by its own
    // position and move it clean out of the field.
    live.overlay.classList.add('is-visible');
    placeMentionOverlay(live, rect);
    // Fractional layout, a transformed ancestor or an unexpected offsetParent can
    // still leave it a fraction off, and a fraction is enough to fringe the text
    // it covers. Correct against where it actually landed.
    const landed = live.overlay.getBoundingClientRect();
    if (Math.abs(landed.top - rect.top) > 0.01 || Math.abs(landed.left - rect.left) > 0.01) {
        live.overlay.style.top = `${parseFloat(live.overlay.style.top) + (rect.top - landed.top)}px`;
        live.overlay.style.left = `${parseFloat(live.overlay.style.left) + (rect.left - landed.left)}px`;
    }
    styleMentionOverlay(live);
    live.inner.style.transform = `translate(${-input.scrollLeft}px, ${-input.scrollTop}px)`;
    live.inner.innerHTML = buildMentionOverlayHtml(input, fieldBackgroundColor(input));
}

function refreshMentionOverlays(force = false) {
    MENTION_INPUT_IDS.forEach(id => {
        const input = document.getElementById(id);
        if (input) syncMentionOverlay(input, force);
    });
}

function initializeMentionHighlighter() {
    MENTION_INPUT_IDS.forEach(id => {
        const input = document.getElementById(id);
        if (!input) return;

        ['input', 'scroll', 'focus', 'blur', 'keyup', 'click', 'mouseup'].forEach(evt => {
            input.addEventListener(evt, () => syncMentionOverlay(input));
        });
    });

    window.addEventListener('resize', () => refreshMentionOverlays(true));
    window.addEventListener('scroll', () => refreshMentionOverlays(), true);
    document.addEventListener('selectionchange', () => {
        const active = document.activeElement;
        if (active && MENTION_INPUT_IDS.includes(active.id)) syncMentionOverlay(active);
    });

    // Plenty of code sets .value directly (entering edit mode, resetInputState,
    // drafts) and the composer auto-resizes as you type; neither fires anything we
    // can listen for on the field itself. The signature check makes a tick with
    // nothing to do free.
    setInterval(() => refreshMentionOverlays(), 200);
}

/* --- Lounges inside Messages ---------------------------------------------
   A lounge and a DM are the same shape -- side nav, a list, a conversation -- so
   Messages carries both behind a switch instead of sending people to another
   page for half their conversations. The lounge page still exists and Explore
   still links to it; this is a second door into the same room.

   The lounge UI is MOVED here, never rebuilt. adoptLoungeNodes() lifts the four
   real nodes out of #lounge-page and drops them into the Messages hosts, and
   releaseLoungeNodes() puts them back. Because they are the same elements, every
   id, handler, socket binding and open modal survives the trip, and there is no
   second copy of the lounge to keep in step with the first. The cost is that
   only one of the two pages may hold them at a time -- which is fine, because
   only one page is ever on screen.

   Order matters on the way back: .lounge-container lays out rail, sidebar, pane,
   shelf from left to right, and appending in that order restores it. */

let messagesPaneMode = 'dms';   // 'dms' | 'lounges'

function loungeNodeSet() {
    return {
        rail: document.getElementById('lounge-rail'),
        sidebar: document.querySelector('.lounge-sidebar'),
        pane: document.querySelector('.active-lounge-pane'),
        shelf: document.getElementById('lounge-resources-sidebar'),
        // Not part of .lounge-container. The whole header travels, so the
        // channel title, the back button and the swipe handler come with it.
        header: document.getElementById('lounge-page-header'),
    };
}

// Is the lounge UI parked inside Messages? Asked of the DOM rather than of
// messagesPaneMode, so it stays honest in the moment between a mode flip and the
// nodes actually moving.
function loungeHostedInMessages() {
    const host = document.getElementById('msg-lounge-content');
    const pane = document.querySelector('.active-lounge-pane');
    return !!(host && pane && host.contains(pane));
}

// The lounge is on screen either on its own page or inside Messages. Every "am I
// already reading this?" check has to accept both, or an unread dot comes back
// for a channel the user is looking straight at.
function isLoungeOnScreen() {
    if (loungeHostedInMessages()) {
        return messagesPaneMode === 'lounges' &&
               !!document.getElementById('messages-page')?.classList.contains('active');
    }
    return !!document.getElementById('lounge-page')?.classList.contains('active');
}

// .mobile-chat-active goes on whichever container is hosting the lounge right
// now. Found by following the pane rather than by naming a container, so it
// cannot drift out of step with where the nodes actually are.
function loungeHostContainer() {
    const pane = document.querySelector('.active-lounge-pane');
    return pane ? pane.closest('.messages-container, .lounge-container') : null;
}

/* --- Remembered scroll ------------------------------------------------------
   .page is `display: none` while you are on another page, and a browser throws
   away the scroll position of every box inside a display:none subtree. So
   swiping out to Home and back put the channel list at the top and the lounge
   rail back on its first cover -- every time, no matter how far down the lounge
   you were reading was. Moving the nodes between the two hosts loses it too: an
   appendChild is a move, and a moved element is re-laid-out from zero.

   Both positions are recorded as they change and put back once the page is on
   screen again. They are stored here rather than read off the nodes because by
   the time we can put them back, the nodes have already been zeroed. */
// bodyFromBottom: how far the message thread was from its end when Lounges was
// last left, or null before that. Measured from the bottom, not the top, so
// messages that arrive while you're in Direct don't shift where you land.
const loungeScrollMemory = { sidebar: 0, rail: 0, bodyFromBottom: null };

function watchLoungeScroll(node, key, prop) {
    // Once per node, not once per adopt: these are the same elements for the
    // life of the page, so a listener added here survives every move.
    if (!node || node.dataset.apexScrollWatched) return;
    node.dataset.apexScrollWatched = '1';
    node.addEventListener('scroll', () => {
        // A node that is off screen reads 0; recording that would erase the
        // position we are about to restore.
        if (node.offsetParent === null) return;
        loungeScrollMemory[key] = node[prop];
    }, { passive: true });
}

function restoreLoungeScroll() {
    // After a paint: assigning scrollTop to a box that is still display:none is
    // silently dropped, and this runs while Messages is being shown.
    requestAnimationFrame(() => {
        const sidebar = document.querySelector('.lounge-sidebar');
        const rail = document.getElementById('lounge-rail-top');
        if (sidebar && loungeScrollMemory.sidebar) sidebar.scrollTop = loungeScrollMemory.sidebar;
        if (rail && loungeScrollMemory.rail) rail.scrollLeft = loungeScrollMemory.rail;

        // The thread too. Moving it between hosts resets its scroll to 0, which
        // dropped you at the very top of the channel every time you came back.
        const body = document.getElementById('lounge-body');
        if (body && loungeScrollMemory.bodyFromBottom != null) {
            body.scrollTop = Math.max(0,
                body.scrollHeight - body.clientHeight - loungeScrollMemory.bodyFromBottom);
        }
        // And the per-theme bubble gradient, which is only ever recomputed on
        // scroll -- and skips itself while the pane is hidden. Without this each
        // bubble showed its own little gradient until the first scroll.
        syncInstagramGradients('lounge-body');
    });
}

function adoptLoungeNodes() {
    const { rail, sidebar, pane, shelf, header } = loungeNodeSet();
    const sidebarHost = document.getElementById('msg-lounge-sidebar');
    const contentHost = document.getElementById('msg-lounge-content');
    const headerHost = document.getElementById('msg-lounge-header-host');
    if (!sidebarHost || !contentHost || !pane) return;
    // Only move what is not already here. setMessagesPaneMode re-asserts the
    // mode it is already in on every route into Messages, and appending a node
    // to the parent it already has is still a move as far as layout is
    // concerned -- which is one of the two ways the channel list kept jumping
    // back to the top.
    const place = (host, node) => { if (node && node.parentElement !== host) host.appendChild(node); };
    place(sidebarHost, rail);
    place(sidebarHost, sidebar);
    place(contentHost, pane);
    place(contentHost, shelf);
    if (headerHost) place(headerHost, header);

    watchLoungeScroll(sidebar, 'sidebar', 'scrollTop');
    watchLoungeScroll(document.getElementById('lounge-rail-top'), 'rail', 'scrollLeft');
}

function releaseLoungeNodes() {
    const { rail, sidebar, pane, shelf, header } = loungeNodeSet();
    const page = document.getElementById('lounge-page');
    const container = document.querySelector('#lounge-page .lounge-container');
    if (!container || !pane) return;

    // Read where the thread is BEFORE it moves -- the move is what zeroes it.
    // Only while it is actually on screen: a hidden thread reads 0 everywhere.
    const body = document.getElementById('lounge-body');
    if (body && body.offsetParent !== null && body.clientHeight) {
        loungeScrollMemory.bodyFromBottom = body.scrollHeight - body.scrollTop - body.clientHeight;
    }

    if (rail) container.appendChild(rail);
    if (sidebar) container.appendChild(sidebar);
    container.appendChild(pane);
    if (shelf) container.appendChild(shelf);
    // The header goes back FIRST, above <main>, which is where it started.
    if (header && page) page.insertBefore(header, page.firstChild);
}

function setMessagesPaneMode(mode, opts = {}) {
    const lounges = mode === 'lounges';
    const changed = messagesPaneMode !== (lounges ? 'lounges' : 'dms');
    messagesPaneMode = lounges ? 'lounges' : 'dms';

    if (lounges) adoptLoungeNodes(); else releaseLoungeNodes();

    document.getElementById('msg-dm-sidebar')?.classList.toggle('hidden', lounges);
    document.getElementById('msg-lounge-sidebar')?.classList.toggle('hidden', !lounges);
    // The whole page is flagged, which is what swaps the Messages header for
    // the lounge's own and lets the phone rules tell the two halves apart.
    document.getElementById('messages-page')?.classList.toggle('is-lounge-mode', lounges);
    document.querySelector('#messages-page .messages-container')
        ?.classList.toggle('is-lounge-mode', lounges);
    document.querySelector('#messages-page .active-chat-pane')?.classList.toggle('hidden', lounges);
    document.getElementById('msg-lounge-content')?.classList.toggle('hidden', !lounges);

    [['msg-mode-dms', !lounges], ['msg-mode-lounges', lounges]].forEach(([id, on]) => {
        const btn = document.getElementById(id);
        if (!btn) return;
        btn.classList.toggle('is-active', on);
        btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });

    // Flipping the switch is a decision to look at the list, not at whatever was
    // open behind it -- and on a phone that pane covers the whole screen, so
    // leaving it up would make the switch look like it did nothing.
    //
    // ONLY when the switch actually moved. openChat() adds .mobile-chat-active
    // and then routes to /messages/<user>, where this function is called to
    // re-assert the mode it is already in -- and clearing the class there closed
    // the conversation the route had just opened, leaving you sitting on the
    // list. Re-asserting a mode is not a decision to leave what you opened.
    if (changed) {
        document.querySelector('#messages-page .messages-container')
            ?.classList.remove('mobile-chat-active');
        // Flipping to Direct closes the channel view, so its history entry goes
        // with it -- otherwise it sits on the stack and eats the next Back.
        dropMsgLoungeChannelHistory();
    }

    // The switch is a preference, not a route: coming back to Messages should
    // land where you left it. Only a deliberate flip counts -- being moved out of
    // lounge mode because something asked for the lounge page by its own URL is
    // not the user changing their mind, and must not rewrite what they chose.
    if (opts.persist !== false) {
        try { localStorage.setItem('apex.messagesPaneMode', messagesPaneMode); } catch (e) {}
    }

    if (lounges && !opts.skipOpen) openLastLoungeInMessages();
    if (lounges) restoreLoungeScroll();
    // The DM thread was display:none while Lounges showed, and the gradient sync
    // skips a hidden pane -- so redo it once the thread is back on screen.
    else requestAnimationFrame(() => syncInstagramGradients('chat-body'));
    updateMessagesModeBadges();
}

// What the Messages header's Back button does.
//
// On a phone an open conversation is a full-screen pane, so Back has to mean
// "back to the list" before it means "leave Messages". DMs already get that for
// free -- each one pushes a history entry, so history.back() lands on the list.
// A lounge opened through the switch pushes nothing (the URL stays /messages on
// purpose), so there is no entry to pop and Back would jump straight out of the
// page, skipping the channel list entirely. The lounge page's own mobile back
// button is no help here: it lives in #lounge-page's header, which stays behind
// when the nodes move.
function messagesBackAction() {
    const container = document.querySelector('#messages-page .messages-container');
    if (messagesPaneMode === 'lounges' && container?.classList.contains('mobile-chat-active')) {
        showMobileChannelList();
        return;
    }
    navigateBack();
}

function restoreMessagesPaneMode() {
    let saved = 'dms';
    try { saved = localStorage.getItem('apex.messagesPaneMode') || 'dms'; } catch (e) {}
    setMessagesPaneMode(saved);
}

// Lounge mode with nothing open is an empty pane, so the switch opens something:
// the lounge you were last in, else the first one on the rail.
function openLastLoungeInMessages() {
    // Already open with its channels drawn -- just repaint the rail so the
    // active pill lands on the right cover.
    if (currentLoungeId && document.getElementById('lounge-channels-list')?.children.length) {
        renderLoungeRail();
        return;
    }

    if (loungeRailList.length) {
        openFirstAvailableLounge();
        return;
    }

    // Nothing has fetched the rail yet, and nothing else is going to: every
    // other caller of fetchLoungeRail() hangs off a path that starts on the
    // lounge page or the switcher popup. Messages has no such step, so before
    // this the switch opened onto a rail holding nothing but its own buttons --
    // and stayed that way until you reached a lounge the long way round, through
    // Explore. Then it worked, which is exactly the bug report.
    renderLoungeRail();   // draw the frame now; the covers land when this returns
    fetchLoungeRail().then(() => {
        // The switch may have been flipped back to Direct while this was in
        // flight, and a lounge must not open behind the DM list.
        if (messagesPaneMode !== 'lounges') return;
        openFirstAvailableLounge();
    });
}

function openFirstAvailableLounge() {
    // Prefer the one you were last in, which is what makes flipping back to
    // Lounges feel like returning rather than restarting.
    const remembered = currentLoungeId &&
        loungeRailList.find(l => Number(l.id) === Number(currentLoungeId));
    const target = remembered || loungeRailList[0];
    if (target) showLounge(target.id);
    else showNoLoungesInMessages();
}

// Joined nothing yet. Without this the pane sits on the markup's own
// placeholders -- a sidebar headed "Lounge Name", an empty channel list, and a
// composer inviting you to "Message in #general", which is not a real channel
// and would post nowhere.
function showNoLoungesInMessages() {
    const input = document.getElementById('lounge-input');
    if (input) input.style.display = 'none';

    const title = document.getElementById('lounge-sidebar-title');
    if (title) title.textContent = 'Lounges';

    const channels = document.getElementById('lounge-channels-list');
    if (channels) channels.innerHTML = '';

    const body = document.getElementById('lounge-body');
    if (!body) return;
    body.style.display = 'flex';
    body.innerHTML = `
        <div class="lounge-empty-state">
            <i class="fas fa-users"></i>
            <div class="lounge-empty-state-title">No lounges yet</div>
            <div class="lounge-empty-state-sub">Find one in Explore, or start your own with +.</div>
        </div>`;
}

// The counts on the two switch buttons. Both are read straight off the same
// globals the side nav and the title bar use, so the three can never disagree.
function updateMessagesModeBadges() {
    const paint = (id, count) => {
        const badge = document.getElementById(id);
        if (!badge) return;
        badge.style.display = count > 0 ? 'block' : 'none';
        badge.textContent = count > 99 ? '99+' : count;
    };
    paint('msg-mode-dms-badge', unreadSenders.size);
    paint('msg-mode-lounges-badge', unreadLoungeCount);
}

function exitMobileChat() {
    // FIX: Use history.back() instead of navigateTo.
    // This pops the "Chat" state off the stack, returning naturally to the "List" state.
    history.back();
}

function exitMobileLounge() {
    // In MESSAGES the channel list and the channel are two screens, so the
    // header's back arrow is the way between them: it steps back to the list
    // first and only leaves once you are already on it. (That is also why the
    // separate channel-list button is hidden in there -- one control, one
    // meaning.) The lounge page keeps its original behaviour: it is a
    // destination you arrived at, and Back means leave it.
    if (isMessagesLoungeChannelOpen()) {
        showMobileChannelList();
        return;
    }
    navigateBack();
}

function showMobileChannelList() {
    const container = loungeHostContainer();
    if (container) {
        // Removing this class hides the chat and shows the sidebar (channel list)
        container.classList.remove('mobile-chat-active');
    }
    dropMsgLoungeChannelHistory();
}

/* --- The phone's own back button, inside a lounge in Messages ---------------
   A DM gets this for free: opening one routes to /messages/<user>, so there is
   a history entry for Back to spend and it lands on the list. A lounge channel
   opened through the Direct/Lounges switch deliberately leaves the URL at
   /messages -- that is the point of the switch -- so there was no entry, and
   Back walked straight out of Messages to whatever came before it, skipping the
   channel list that the user was one step above.

   So opening a channel pushes a throwaway entry at the same URL, exactly as a
   full-screen modal does (see pushModalHistory), and the popstate handler
   spends it on returning to the list. Closing the view any other way -- the
   header's back arrow, flipping back to Direct -- rewinds the entry, so the
   history depth never drifts from what is on screen. */
let msgLoungeChannelEntry = false;

// Is a lounge channel filling a phone screen inside Messages right now? Asked of
// the DOM, and it includes #messages-page.active on purpose: the flag above can
// outlive the view if the user leaves the page from inside a channel, and
// without this the next Back would try to "return to the channel list" while
// standing on Home.
function isMessagesLoungeChannelOpen() {
    if (!loungeHostedInMessages() || !isPhoneLayout()) return false;
    if (!document.getElementById('messages-page')?.classList.contains('active')) return false;
    return !!document.querySelector('#messages-page .messages-container')
        ?.classList.contains('mobile-chat-active');
}

function pushMsgLoungeChannelHistory() {
    if (msgLoungeChannelEntry || !loungeHostedInMessages() || !isPhoneLayout()) return;
    msgLoungeChannelEntry = true;
    history.pushState({ apexMsgLoungeChannel: true }, '', location.href);
}

function dropMsgLoungeChannelHistory() {
    if (!msgLoungeChannelEntry) return;
    msgLoungeChannelEntry = false;
    // Counted the same way popModalHistory counts its own: the popstate this
    // produces is a rewind we asked for, at a URL we never really left, and it
    // must not route.
    modalHistoryRewinds++;
    history.go(-1);
}

// Add this new function to handle creating a lounge
// --- Built-in lounge covers --------------------------------------------------
// Shipped as SVGs under /lounge-covers/ (see server.py LOUNGE_COVER_PRESETS; the
// two lists must name the same files). A lounge with no cover of its own is drawn
// with one of these, picked from its id, so it is never a bare grey circle and
// always gets the same one.
const LOUNGE_COVER_PRESETS = [
    ['aurora', 'Aurora'], ['sunset', 'Sunset'], ['ocean', 'Ocean'], ['forest', 'Forest'],
    ['grape', 'Grape'], ['peach', 'Peach'], ['midnight', 'Midnight'], ['blueprint', 'Blueprint'],
    ['confetti', 'Confetti'], ['mint', 'Mint'], ['dunes', 'Dunes'], ['neon', 'Neon'],
];
const loungePresetUrl = key => `/lounge-covers/${key}.svg`;

function loungeCoverUrl(lounge) {
    if (!lounge) return loungePresetUrl(LOUNGE_COVER_PRESETS[0][0]);
    const own = lounge.cover_image || lounge.coverImage;
    if (own) return own;
    const seed = String(lounge.id ?? lounge.name ?? '');
    let h = 0;
    for (const ch of seed) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
    return loungePresetUrl(LOUNGE_COVER_PRESETS[h % LOUNGE_COVER_PRESETS.length][0]);
}

function randomLoungePresetUrl() {
    return loungePresetUrl(LOUNGE_COVER_PRESETS[Math.floor(Math.random() * LOUNGE_COVER_PRESETS.length)][0]);
}

// The row of built-in covers under a cover uploader. `uploader` is what
// attachMediaUploader() returns. Its set() redraws the preview but does not fire
// onChange, so a pick is reported through `onPick` as well. Returns sync(url),
// which keeps the ring on the swatch matching whatever the preview now shows.
function attachLoungeCoverPresets(containerId, uploader, onPick) {
    const box = document.getElementById(containerId);
    if (!box) return () => {};
    box.innerHTML = '';

    const head = document.createElement('div');
    head.className = 'cover-presets-head';
    head.innerHTML = '<span>Default covers</span>';
    const shuffle = document.createElement('button');
    shuffle.type = 'button';
    shuffle.className = 'cover-presets-shuffle';
    shuffle.innerHTML = '<i class="fas fa-shuffle"></i> Surprise me';
    head.appendChild(shuffle);
    box.appendChild(head);

    const grid = document.createElement('div');
    grid.className = 'cover-presets-grid';
    box.appendChild(grid);

    const choose = url => { uploader.set(url); onPick(url); };
    const swatches = LOUNGE_COVER_PRESETS.map(([key, label]) => {
        const url = loungePresetUrl(key);
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'cover-preset';
        b.dataset.url = url;
        b.setAttribute('role', 'radio');
        b.setAttribute('aria-label', label);
        b.title = label;
        b.style.backgroundImage = `url("${url}")`;
        b.innerHTML = '<i class="fas fa-check"></i>';
        b.onclick = () => choose(url);
        grid.appendChild(b);
        return b;
    });

    shuffle.onclick = () => {
        const current = uploader.get && uploader.get();
        const others = swatches.filter(b => b.dataset.url !== current);
        const pick = others[Math.floor(Math.random() * others.length)];
        choose(pick.dataset.url);
    };

    const sync = url => swatches.forEach(b => {
        const on = b.dataset.url === url;
        b.classList.toggle('is-selected', on);
        b.setAttribute('aria-checked', String(on));
    });
    sync(uploader.get ? uploader.get() : null);
    return sync;
}

function handleCreateLounge(button) {
    button.disabled = true;
    button.textContent = 'Creating...';

    const name = document.getElementById('loungeName').value.trim();
    const description = document.getElementById('loungeDescription').value.trim();
    const privacy = document.querySelector('input[name="loungePrivacy"]:checked').value;
    const coverImage = newLoungeCoverUrl;

    if (!name) {
        showToast('Lounge name is required.', 'error');
        button.disabled = false;
        button.textContent = 'Create';
        return;
    }

    // --- FIX: Define payload here so it's available for both fetch AND appeal ---
    const payload = { 
        name: name, 
        description: description, 
        privacy: privacy, 
        coverImage: coverImage 
    };

    fetch(`${API_BASE_URL}/api/lounges`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(payload) // Use the object we just created
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 201) {
            showToast('Lounge created successfully!', 'success');
            
            // --- NEW FIX: Re-join socket rooms so we get live notifications instantly ---
            if (socket) socket.emit('join_all_lounge_rooms');

            // navigateTo, not showPage: showPage swaps the visible page without
            // touching the URL, so the bar still read /create-lounge and a
            // reload dropped you back onto the form you had just submitted.
            // Straight into the lounge just made -- the next thing anyone does
            // with a new lounge is set it up or invite people.
            navigateTo(body.lounge && body.lounge.id ? `/lounges/${body.lounge.id}` : '/');
        } else {
            // --- MODERATION CHECK ---
            if (isModerationError(body.error)) {
                // Now 'payload' is defined and contains all the images/text
                showModerationErrorModal(body.error, 'lounge', payload);
            } else {
                showToast(body.error, 'error');
            }
        }
    })
    .catch(error => {
        console.error("Error creating lounge:", error);
        showToast("An unexpected error occurred.", 'error');
    })
    .finally(() => {
        button.disabled = false;
        button.textContent = 'Create';
    });
}

function renderLoungeChannels(channels) {
    const list = document.getElementById('lounge-channels-list');
    const categoryHeader = document.querySelector('.lounge-channel-category');
    list.innerHTML = '';

    // Add "+" button for mods/owners
    if (currentUserLoungeRole === 'owner' || currentUserLoungeRole === 'moderator') {
        categoryHeader.innerHTML = 'Chats <i class="fas fa-plus" style="cursor: pointer; float: right;" onclick="showCreateChannelModal()"></i>';
    } else {
        categoryHeader.textContent = 'Chats';
    }

    channels.forEach(channel => {
        // 1. Join the socket room for this channel immediately
        // This ensures we get events even if we aren't looking at the channel
        if (socket) {
            socket.emit('join_lounge_channel', { channel_id: channel.id });
        }

        const li = document.createElement('li');
        li.className = 'lounge-channel-item';
        li.id = `channel-item-${channel.id}`;
        li.onclick = () => loadLoungeChannel(channel);

        const channelNameSpan = document.createElement('span');
        // Use flex to align text and dots
        channelNameSpan.style.display = 'flex'; 
        channelNameSpan.style.alignItems = 'center';

        // Three distinct states, three distinct icons: a padlock is "you can read
        // but not write", a shield is "moderators only", and the user-lock is the
        // committee case -- a channel whose membership is a list of names rather
        // than a rank. Using the same padlock for the last two would tell a
        // member the exec channel is merely read-only.
        let suffixIcon = channelLockIcon(channel.permission_level);

        let mainChannelIcon = '';
        if (channel.is_main) {
            mainChannelIcon = '<i class="fas fa-star main-channel-icon" style="margin-left: 6px;"></i>';
        }

        // 2. Add the unread indicator div here
        channelNameSpan.innerHTML = `# ${channel.name} ${suffixIcon} ${mainChannelIcon} <div class="unread-indicator"></div>`;

        li.appendChild(channelNameSpan);

        const menuBtn = document.createElement('i');
        menuBtn.className = 'fas fa-ellipsis-v channel-options-btn';
        menuBtn.onclick = (event) => openChannelContextMenu(event, channel);
        li.appendChild(menuBtn);

        list.appendChild(li);
    });
}

// The address bar follows whichever channel is open, so a channel is a link you
// can send, bookmark and reload into. replaceState rather than pushState: the
// router already reads /lounges/<lounge>/<channel>, and pushing one entry per
// channel tap would turn Back into a walk through every channel you glanced at
// instead of a way out of the lounge.
function syncLoungeChannelUrl(channelId) {
    if (!currentLoungeId || !channelId) return;
    // Inside Messages the address is /messages and stays there -- that is the
    // whole point of the switch. Rewriting it to /lounges/<id> would leave Back
    // and a reload disagreeing with the page the user is looking at.
    if (loungeHostedInMessages()) return;
    const path = `/lounges/${currentLoungeId}/${channelId}`;
    if (window.location.pathname === path) return;
    try {
        history.replaceState(history.state, '', path);
    } catch (e) {
        // A replaceState that the browser refuses (rare, and only ever in an
        // exotic embedding) must not take the channel open down with it.
        console.warn('Could not sync the channel URL', e);
    }
}

// `opts.enterOnMobile: false` loads the channel into the pane but leaves the
// phone on the channel list. Tapping a LOUNGE is a request to see what is in it,
// not a request to be dropped into whichever channel happens to be first --
// inside Messages, where the rail and the list are one screen, being thrown into
// #general every time you glance at another lounge is the opposite of browsing.
// Tapping a CHANNEL still enters it (that call passes nothing).
function loadLoungeChannel(channel, opts = {}) {
    const enterOnMobile = opts.enterOnMobile !== false;
    const { id, name, permission_level } = channel;
    syncLoungeChannelUrl(id);

    // Project channels take the board path and stop. Everything above this line in
    // the chat path -- message paging, typing indicators, the composer -- has no
    // meaning on a checklist, and running it would leave a chat's scroll handlers
    // bound while a board is on screen.
    if ((channel.kind || 'chat') !== 'chat') {
        hideRolesBoard();
        emitTypingStop('lounge');
        currentLoungeChannelId = id;
        setActiveView('lounge', id);
        // One notification per lounge, not per channel (see queue_lounge_pushes).
        clearPushNotifications(`lounge-${currentLoungeId}`);
        markChannelReadLocally(id);
        highlightSidebarChannel(id);
        updateMobileChannelBadge();

        const mobileChannelName = document.getElementById('channel-header-name-mobile');
        if (mobileChannelName) mobileChannelName.textContent = name;
        const container = loungeHostContainer();
        if (container && enterOnMobile) {
            container.classList.add('mobile-chat-active');
            pushMsgLoungeChannelHistory();
        }

        if (channel.kind === 'notice') showNoticePane(channel);
        else showTaskPane(channel);
        return;
    }

    // A chat channel after a board: put the chat panes back before anything below
    // starts writing into them.
    hideRolesBoard();
    hideNoticePane();
    hideTaskPane();

    oldestLoungeMessageId = null;
    isLoungeLoadingMore = false;
    // Pins are per channel, so the bar is emptied and refetched here rather than
    // left showing the previous channel's agenda for the length of one request.
    loadLoungePins(id);
    // Walking out of a channel mid-draft leaves our start hanging there -- retract it
    // before currentLoungeChannelId moves on and we lose the address.
    emitTypingStop('lounge');
    // Files in the tray were uploaded (and permission-checked) for the channel
    // being left; they are not carried into this one.
    if (String(currentLoungeChannelId) !== String(id) && composerAttachments.lounge.length) clearComposerAttachments('lounge');
    currentLoungeChannelId = id;
    unreadBarRendered = false;
    clearTypers('lounge');
    // Another channel's read markers point at messages that are not in this
    // thread, so they are dropped rather than carried across.
    resetLoungeReaders(id);

    // Tell the server which channel is on screen, so it can skip pushing the one
    // we're already reading -- the same deal DMs have had. showPage('lounge-page')
    // released the view a moment ago; this re-asserts it with the channel.
    setActiveView('lounge', id);
    // And retire anything already sitting in the tray for its lounge -- lounge
    // notifications are grouped per lounge, not per channel.
    clearPushNotifications(`lounge-${currentLoungeId}`);
    // --- NOTIFICATION FIX: Mark this channel as read locally ---
    if (unreadChannelSet.has(id)) {
        unreadChannelSet.delete(id);
        if (unreadLoungeCount > 0) unreadLoungeCount--;
        updateGeneralNotificationBadge();
        updateNotificationBadge();
        updatePageTitleCount();
        
        // Also update the UI dot immediately for responsiveness
        const channelItem = document.getElementById(`channel-item-${id}`);
        if (channelItem) channelItem.classList.remove('has-unread');
    }
    // -----------------------------------------------------------

    document.querySelectorAll('.lounge-channel-item').forEach(item => item.classList.remove('active'));
    const channelElement = document.getElementById(`channel-item-${id}`);
    if (channelElement) {
        channelElement.classList.add('active');
        channelElement.classList.remove('has-unread');
    }
    updateMobileChannelBadge();

    const inputField = document.getElementById('lounge-input-field');
    inputField.placeholder = `Message in #${name}`;
    if (permission_level === 'mods_only_chat' && currentUserLoungeRole === 'member') {
        inputField.disabled = true;
        inputField.placeholder = 'Only moderators can send messages here.';
    } else {
        inputField.disabled = false;
    }

    // Normalise the input height now that the lounge is on screen -- mirrors the DM
    // input, which is re-measured every time the messages page is shown. Heals any
    // height baked in while this bar was hidden (which otherwise looks thin).
    if (typeof autoResizeTextarea === 'function') autoResizeTextarea({ target: inputField });

    const chatBody = document.getElementById('lounge-body');
    // Opening a channel starts you following it. The render clears this again if it
    // lands on the unread divider instead of the bottom.
    loungeStickToBottom = true;
    loungeProgrammaticScrollUntil = 0;

    // Clear previous scroll handler, but keep watching for the user scrolling away
    // from the bottom until the full handler is installed a second from now --
    // otherwise a message arriving inside that window drags them back down.
    // Assigned, not addEventListener, so the handler below replaces it.
    chatBody.onscroll = () => noteLoungeScroll(chatBody);

    // FIX: Delay attaching the scroll listener by 1 second.
    // This prevents the initial "jump to unread" from accidentally deleting the bar.
    setTimeout(() => {
        let ticking = false; // The throttle lock

        chatBody.onscroll = () => {
            // Outside the rAF throttle: this is the only place the user gets to say
            // "stop following the channel", and dropped frames would miss a fast flick.
            noteLoungeScroll(chatBody);

            if (!ticking) {
                window.requestAnimationFrame(() => {
                    // The shared gradient is offset per bubble against the container's
                    // VISIBLE box, so it has to be recomputed on every scroll or the
                    // offsets go stale and the gradient tears. This used to say
                    // 'chat-body' -- the DM container -- from a copy/paste, so it did
                    // nothing useful here and was commented out rather than repointed.
                    syncInstagramGradients('lounge-body');

                    // Page the LOUNGE here. This used to call loadMoreDMs() against
                    // oldestDMMessageId -- the same copy/paste that once pointed the
                    // gradient sync at 'chat-body'. It meant hitting the top of a
                    // channel fetched and re-rendered the DM thread instead (real work,
                    // off-screen, while you scroll), and the channel's own history
                    // never loaded at all.
                    if (chatBody.scrollTop === 0 && !isLoungeLoadingMore && oldestLoungeMessageId) {
                        loadMoreLoungeMessages();
                    }
                    if (chatBody.scrollTop + chatBody.clientHeight >= chatBody.scrollHeight - 50) {
                        const bar = document.querySelector('.unread-messages-bar');
                        if (bar) {
                            bar.remove();
                        }
                        currentFirstUnreadId = null;
                    }
                    
                    ticking = false;
                });
                ticking = true;
            }
        };
    }, 1000);

    // --- FIX: Update Mobile Channel Label ---
    const mobileChannelLabel = document.getElementById('channel-header-name-mobile');
    if (mobileChannelLabel) mobileChannelLabel.textContent = `# ${channel.name}`;
    // ----------------------------------------

    // loungeHostContainer(), not '.lounge-container': in Messages the lounge is
    // parked in .messages-container and the (empty) .lounge-container on
    // #lounge-page is what this used to find -- so on a phone tapping a channel
    // marked a container nobody was looking at and the channel list just sat
    // there. Unconditional, so tapping the channel you are already in still
    // takes you into it: on a phone the list and the conversation are two
    // screens, and a tap on a row is a request for the second one.
    const container = loungeHostContainer();
    if (container && enterOnMobile) {
        container.classList.add('mobile-chat-active');
        pushMsgLoungeChannelHistory();
    }
    clearKeyboardViewportLock(); // never inherit the last visit's keyboard height
    clearKeyboardViewport();

    // Swiping between channels used to leave the previous channel's messages on
    // screen until the new ones landed, which read as "this channel has those
    // messages in it". Clear to the skeleton for the duration of the fetch.
    showLoungeBodySkeleton();

    // Fetch messages
    fetch(`${API_BASE_URL}/api/lounge/channel/${id}/messages?limit=80`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        // Swiping through channels can put several of these in flight at once, and
        // they do not have to come back in order. Whichever channel is on screen
        // now is the only one allowed to draw into the body.
        if (String(currentLoungeChannelId) !== String(id)) return;

        // Before anything renders: the avatars now arrive once per person here
        // rather than on every message.
        seedLoungeAuthorCache(data.authors);

        seedMyReactions('lounge', data.messages);
        currentLoungeMessages = data.messages;
        // Restore any of this channel's still-unsent messages (see the DM path).
        mergePendingIntoChannel(id);

        // The server now sends the *previous* read time in `last_read_at`.
        currentLoungeLastReadTime = data.last_read_at ? new Date(data.last_read_at) : null;
        
        if (currentLoungeMessages.length > 0) {
            oldestLoungeMessageId = currentLoungeMessages[0].id;
        }
        
        // Pass TRUE for isInitialLoad to allow jumping to the red line if it exists
        renderLoungeMessages(currentLoungeMessages, false, true);

        // Refresh global lounge counts (badges) just in case
        fetchAndRenderMyLounges();
        // Who else has read how far. After the messages, because the faces are
        // placed against the thread that just landed.
        fetchLoungeReaders(id);
    })
    .catch(error => {
        console.error("Error loading lounge channel messages:", error);
        // Without this the skeleton would shimmer forever on a dropped request,
        // which is the exact ambiguity it was added to remove.
        if (String(currentLoungeChannelId) !== String(id)) return;
        clearLoungeBodySkeleton();
        const chatBody = document.getElementById('lounge-body');
        if (chatBody) {
            const failed = document.createElement('div');
            failed.className = 'lounge-empty-state';
            failed.innerHTML = `
                <i class="fas fa-exclamation-triangle"></i>
                <div class="lounge-empty-state-title">Couldn't load messages</div>
                <div class="lounge-empty-state-sub">Check your connection and try again.</div>
            `;
            chatBody.appendChild(failed);
        }
    });
}

// `onLoaded` runs once the older page is on screen. Used by the jump-to-message
// paths (pin bar, search results), which have to keep paging until the message
// they want exists before they can scroll to it. Called with no argument by the
// scroll handler, which simply wants more history.
function loadMoreLoungeMessages(onLoaded) {
    if (isLoungeLoadingMore || !oldestLoungeMessageId || !currentLoungeChannelId) {
        // Tell a waiting caller there is nothing left to fetch, or it sits
        // forever expecting a callback that can never come.
        if (typeof onLoaded === 'function' && !oldestLoungeMessageId) onLoaded(false);
        return;
    }
    isLoungeLoadingMore = true;

    const chatBody = document.getElementById('lounge-body');
    const oldScrollHeight = chatBody.scrollHeight; 
    const spinner = document.createElement('div');
    spinner.className = 'system-message';
    spinner.textContent = 'Loading older messages...';
    spinner.id = 'lounge-loading-spinner';
    chatBody.prepend(spinner);

    fetch(`${API_BASE_URL}/api/lounge/channel/${currentLoungeChannelId}/messages?limit=80&before_id=${oldestLoungeMessageId}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        seedLoungeAuthorCache(data.authors);
        const messages = data.messages;
        seedMyReactions('lounge', messages);

        if (messages.length > 0) {
            oldestLoungeMessageId = messages[0].id;
            currentLoungeMessages.unshift(...messages);
            
            // Pass FALSE for isInitialLoad, TRUE for preserveScroll
            renderLoungeMessages(currentLoungeMessages, true, false, false, oldScrollHeight);
            
            const newScrollHeight = chatBody.scrollHeight;
            chatBody.scrollTop = newScrollHeight - oldScrollHeight;
        } else {
            oldestLoungeMessageId = null;
        }
    })
    .catch(error => console.error("Error loading more lounge messages:", error))
    .finally(() => {
        document.getElementById('lounge-loading-spinner')?.remove();
        isLoungeLoadingMore = false;
        // After the flag is cleared, so a callback that wants another page can
        // ask for one immediately instead of being turned away by the guard.
        if (typeof onLoaded === 'function') onLoaded(true);
    });
}

function markNotificationsAsRead() {
    // Reading them here retires the stacked activity push too, so a notification
    // never outlives the thing it was notifying about.
    clearPushNotifications('apex-notifications');

    fetch(`${API_BASE_URL}/api/notifications/mark-all-read`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    }).then(() => {
        unreadNotificationCount = 0;
        updateGeneralNotificationBadge();
        updatePageTitleCount();
    });
}

// Replace your existing sendLoungeMessage function
// Replace your existing sendLoungeMessage function
function sendLoungeMessage() {
    // 1. Handle Edit Mode
    if (currentEditContext.type === 'lounge') {
        saveMessageEdit(currentEditContext.id, 'lounge', 'lounge-input-field');
        return;
    }

    const replyId = currentReplyContext.id;
    // resetInputState() below wipes currentReplyContext, so copy it first (same as
    // sendMessage does for DMs).
    const replyContextCopy = { ...currentReplyContext };
    const inputField = document.getElementById('lounge-input-field');
    const text = inputField.value.trim();
    const image = loungeImagePreviewUrl;
    // A sticker send stages loungeImagePreviewUrl and calls straight through; it
    // must not sweep up files sitting in the tray.
    const sendingSticker = typeof image === 'string' && image.includes('/api/sticker/');
    const taken = sendingSticker ? { blocked: false, ready: [] } : takeComposerAttachments('lounge');
    if (taken.blocked) {
        showToast('Wait for your files to finish uploading.', 'error');
        return;
    }
    const attachments = taken.ready;

    // Split off any "//fire" style command for the optimistic bubble; the raw text
    // still goes to the server, which is authoritative for parsing.
    const { effect: msgEffect, text: displayText } = extractMessageEffect(text);

    if (text.length > 3000) {
        showToast('Message is too long (max 3000 characters).', 'error');
        return;
    }

    const pollPayload = takePendingPoll('lounge');

    if ((!displayText && !image && !pollPayload && !attachments.length) || !currentLoungeChannelId) return;

    // 2. Prepare Payload
    const payload = {
        text: text,
        image: image,
        reply_to_id: replyId,
        poll: pollPayload
    };
    // What the optimistic bubble shows until the server's copy arrives.
    let optimisticImage = image;
    let optimisticAttachments = null;
    const attachmentFields = attachmentSendFields(attachments);
    if (attachmentFields) {
        payload.attachments = attachmentFields.tokens;
        optimisticImage = attachmentFields.image;
        optimisticAttachments = attachmentFields.attachments;
        clearComposerAttachments('lounge');
    }

    // 3. Reset UI immediately (Fixes buttons not reappearing)
    if (replyId) resetInputState('lounge');
    inputField.value = '';
    // Immediate + no scroll fixup: renderLoungeMessages below owns the scroll, and a
    // composer collapse arriving a frame later would cancel its smooth scroll.
    autoResizeTextarea({ target: inputField }, { immediate: true, adjustScroll: false });
    removeImagePreview('lounge');
    if (pollPayload) clearPendingPoll('lounge');
    // Clearing the field in code fires no 'input' event -- see sendMessage().
    emitTypingStop('lounge', currentLoungeChannelId);
    
    const loungeContainer = document.querySelector('#lounge-input');
    if (loungeContainer) loungeContainer.classList.remove('typing-active');

    // Only if it was already focused -- see the same line in sendMessage().
    if (document.activeElement === inputField) inputField.focus();

    // And back to letters, for the same reason as there.
    resetSoftKeyboardLayer(inputField);

    // 3.5 Optimistic render: show the message right away instead of waiting for the
    // POST to return AND the socket to echo it back -- which is why sending here
    // felt so much slower than a DM, where sendMessage() has always done this.
    // The 'new_lounge_message' handler already looks for a temp_ id and swaps in the
    // real message (and skips re-animating it), so this needs no dedupe of its own.
    const tempId = `temp_${Date.now()}`;
    // The server echoes this back on 'new_lounge_message', which is how this device
    // tells its own message apart from the same message arriving from another one of
    // its own sessions (phone -> desktop).
    payload.client_id = tempId;
    lastOptimisticRenderAt = Date.now();
    currentLoungeMessages.push({
        id: tempId,
        text: displayText,
        image: optimisticImage,
        attachments: optimisticAttachments,
        timestamp: new Date().toISOString(),
        channel_id: currentLoungeChannelId,
        reactions: {},
        is_deleted: false,
        edited_at: null,
        effect: msgEffect,
        user_id: profileData.me.id,
        // See the same line in sendMessage(): the draft stands in for the poll
        // until the server's copy arrives on the socket echo.
        poll: pollPayload ? { ...pollPayload, pending: true } : null,
        reply_to_id: replyId || null,
        reply_to: replyId ? { text: replyContextCopy.text, author_name: replyContextCopy.author } : null,
        author: {
            username: profileData.me.username,
            fullName: profileData.me.name,
            profilePic: profileData.me.profilePicUrl,
            rank: profileData.me.rank
        }
    });
    renderLoungeMessages(currentLoungeMessages, false, false, true);

    // 4. Send -- via the outbox, so a failed request queues and retries instead of
    // deleting what the user wrote. See the note in sendMessage().
    enqueueOutbox({
        id: tempId,
        kind: 'lounge',
        target: currentLoungeChannelId,
        body: payload,
        view: {
            text: displayText,
            effect: msgEffect,
            replyTo: replyId ? { text: replyContextCopy.text, author_name: replyContextCopy.author } : null
        }
    });
}

// A failed send must not leave its optimistic bubble on screen pretending to be a
// real message -- the socket echo that would normally replace it is never coming.
function dropOptimisticLoungeMessage(tempId) {
    const i = currentLoungeMessages.findIndex(m => m.id === tempId);
    if (i > -1) {
        currentLoungeMessages.splice(i, 1);
        renderLoungeMessages(currentLoungeMessages, true);
    }
}
let currentLoungeChannelId = null;

function handleJoinLounge() {
    if (!currentLoungeId) return;
    const joinButton = document.getElementById('join-lounge-btn');
    joinButton.disabled = true;
    joinButton.innerHTML = 'Joining...';

    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/join`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 200) {
            showToast(`Welcome to the lounge!`, 'success');
            const loungeName = document.getElementById('lounge-header-title').textContent;
            
            // --- NEW FIX: Re-join socket rooms so we get live notifications instantly ---
            if (socket) socket.emit('join_all_lounge_rooms');
            
            showLounge(currentLoungeId, loungeName);
        } else {
            showToast(body.error || 'Could not join the lounge.', 'error');
            joinButton.disabled = false;
            joinButton.innerHTML = '<i class="fas fa-sign-in-alt"></i> Join Lounge';
        }
    });
}

let editLoungeCoverUrl = null;

// The lounge's settings modal: members and lounge details behind one left rail,
// the way a Google Chat space does it. Everyone can open it -- members to see who
// is in here, the owner to edit -- so the details tab and the Save bar, not the
// modal, are what the owner check gates.
let loungeSettingsTab = 'members';

function openLoungeSettings(tab) {
    const modal = document.getElementById('lounge-members-modal');
    if (!modal) return;

    // A save that failed last time left the button disabled and captioned
    // "Saving..."; this is the reset the old page did on entry.
    const saveBtn = document.querySelector('#lounge-settings-footer-bar .login-btn');
    if (saveBtn) {
        saveBtn.disabled = false;
        saveBtn.textContent = 'Save';
    }

    const isOwner = currentUserLoungeRole === 'owner';
    // The owner, or a moderator the owner has handed the details to.
    const canEditDetails = loungeCan('details');
    const detailsTab = document.getElementById('lounge-settings-details-tab');
    const footer = document.getElementById('lounge-settings-footer-bar');

    // Someone with nothing to save doesn't get the details tab or the Save bar
    // at all -- not merely disabled.
    if (detailsTab) detailsTab.classList.toggle('hidden', !canEditDetails);
    if (footer) footer.classList.toggle('hidden', !canEditDetails);

    // The log is visible to moderators as well. They are the people a handover
    // is handed TO, and the endpoint already allows them.
    const isMod = isOwner || currentUserLoungeRole === 'moderator';
    const historyTab = document.getElementById('lounge-settings-history-tab');
    if (historyTab) historyTab.classList.toggle('hidden', !isMod);

    modal.classList.remove('hidden');
    pushModalHistory('lounge-members-modal', closeLoungeMembersModal);

    setLoungeSettingsTab(canEditDetails ? (tab || 'members') : 'members');
    renderLoungeSettingsMembers();
    if (canEditDetails) loadLoungeSettingsDetails();
}

function setLoungeSettingsTab(tab) {
    loungeSettingsTab = tab;
    document.querySelectorAll('#lounge-members-modal .lounge-settings-tab').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.tab === tab);
    });
    ['members', 'details', 'history'].forEach(name => {
        const panel = document.getElementById(`lounge-settings-panel-${name}`);
        if (panel) panel.classList.toggle('hidden', name !== tab);
    });
    const footer = document.getElementById('lounge-settings-footer-bar');
    // Save belongs to the details form only; leaving it under the member list
    // implied the list had unsaved edits in it.
    if (footer && loungeCan('details')) footer.classList.toggle('hidden', tab !== 'details');

    // Fetched on open rather than with the modal: most visits to Lounge settings
    // are to add somebody, and the log is a page nobody asked for until they do.
    if (tab === 'history') loadLoungeAuditLog();
}

// --- Lounge history (audit log) -----------------------------------------------

// How each action reads in the list. A table rather than a chain of ifs, so an
// action the server starts writing later falls back to its raw name instead of
// rendering as a blank row.
const LOUNGE_AUDIT_LABELS = {
    role_changed: 'changed a role',
    ownership_transferred: 'transferred ownership',
    channel_created: 'created a channel',
    channel_deleted: 'deleted a channel',
    channel_visibility_changed: 'changed who can see a channel',
    channel_group_created: 'created a channel group',
    channel_group_renamed: 'renamed a channel group',
    channel_group_deleted: 'deleted a channel group',
    channel_group_moved: 'moved a channel to a group',
    message_pinned: 'pinned a message',
    message_unpinned: 'unpinned a message',
    member_removed: 'removed a member',
    mod_powers_changed: 'changed what moderators can do',
};

let loungeAuditState = { loading: false, nextBeforeId: null };

function loadLoungeAuditLog(append = false) {
    const list = document.getElementById('lounge-audit-list');
    if (!list || !currentLoungeId) return;
    if (loungeAuditState.loading) return;
    loungeAuditState.loading = true;

    if (!append) {
        loungeAuditState.nextBeforeId = null;
        list.innerHTML = '<li class="lounge-audit-status">Loading…</li>';
    }

    const params = new URLSearchParams();
    if (append && loungeAuditState.nextBeforeId) {
        params.set('before_id', loungeAuditState.nextBeforeId);
    }

    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/audit?${params}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.ok ? r.json() : Promise.reject(r.status))
    .then(data => {
        if (!append) list.innerHTML = '';
        list.querySelector('.lounge-audit-more')?.remove();
        list.querySelector('.lounge-audit-status')?.remove();

        const entries = Array.isArray(data.entries) ? data.entries : [];
        if (!entries.length && !append) {
            list.innerHTML = '<li class="lounge-audit-status">Nothing has been changed yet.</li>';
            return;
        }

        entries.forEach(e => list.appendChild(buildAuditRow(e)));

        loungeAuditState.nextBeforeId = data.next_before_id || null;
        if (loungeAuditState.nextBeforeId) {
            const more = document.createElement('li');
            more.className = 'lounge-audit-more';
            more.textContent = 'Load older';
            more.onclick = () => loadLoungeAuditLog(true);
            list.appendChild(more);
        }
    })
    .catch(() => {
        list.innerHTML = '<li class="lounge-audit-status">Could not load the history.</li>';
    })
    .finally(() => { loungeAuditState.loading = false; });
}

function buildAuditRow(entry) {
    const li = document.createElement('li');
    li.className = 'lounge-audit-item';

    const head = document.createElement('div');
    head.className = 'lounge-audit-head';

    const who = document.createElement('strong');
    // An entry outlives its actor's account on purpose -- see the model comment.
    who.textContent = entry.actor
        ? (entry.actor.fullName || entry.actor.username)
        : 'A former member';
    head.appendChild(who);

    const what = document.createElement('span');
    const verb = LOUNGE_AUDIT_LABELS[entry.action] || entry.action;
    what.textContent = entry.target
        ? ` ${verb}: @${entry.target.username}`
        : ` ${verb}`;
    head.appendChild(what);

    li.appendChild(head);

    if (entry.summary) {
        const detail = document.createElement('div');
        detail.className = 'lounge-audit-detail';
        // textContent: a summary can carry a channel name or a message preview.
        detail.textContent = entry.summary;
        li.appendChild(detail);
    }

    const when = document.createElement('div');
    when.className = 'lounge-audit-when';
    const d = new Date(entry.created_at);
    when.textContent = isNaN(d) ? '' : d.toLocaleString(undefined, {
        year: 'numeric', month: 'short', day: 'numeric',
        hour: 'numeric', minute: '2-digit'
    });
    li.appendChild(when);

    return li;
}


function handleTransferOwnership(username) {
    document.querySelectorAll('.context-menu').forEach(m => m.remove());
    showConfirmationModal({
        title: 'Transfer this lounge?',
        text: `<strong>@${username}</strong> will become the owner and you will become a moderator. ` +
              'Only they will be able to transfer it back.',
        onConfirm: () => {
            fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/transfer-owner`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
                body: JSON.stringify({ username })
            })
            .then(r => r.json().then(body => ({ status: r.status, body })))
            .then(({ status, body }) => {
                if (status !== 200 || !body.ok) {
                    showToast(body.error || 'Could not transfer the lounge.', 'error');
                    return;
                }
                showToast(body.message, 'success');
                closeLoungeMembersModal();
                // Our own role just changed, so everything gated on it -- the
                // settings tabs, the channel menus -- has to be rebuilt.
                showLounge(currentLoungeId, document.getElementById('lounge-header-title').textContent);
            })
            .catch(() => showToast('Could not transfer the lounge.', 'error'));
        }
    });
}

// Kept under its old name: showLoungeMembers() is called from the role-change and
// job-label handlers to refresh the list, and from the lounge menu.
function showLoungeMembers() {
    if (document.getElementById('lounge-members-modal').classList.contains('hidden')) {
        openLoungeSettings('members');
    } else {
        renderLoungeSettingsMembers();
    }
}

function loadLoungeSettingsDetails() {
    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/details`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(lounge => {
        if (lounge.error) {
            showToast(lounge.error, 'error');
            return;
        }

        const nameInput = document.getElementById('editLoungeName');
        const descInput = document.getElementById('editLoungeDescription');

        nameInput.value = lounge.name;
        descInput.value = lounge.description || '';

        document.getElementById('editLoungeNameCounter').textContent = `${lounge.name.length} / 20`;
        document.getElementById('editLoungeDescCounter').textContent = `${(lounge.description || '').length} / 600`;
        document.getElementById('editLoungePrivacyDisplay').textContent = `Privacy setting (${lounge.privacy}) cannot be changed.`;

        // --- Broadcast mentions ---
        const broadcast = lounge.broadcast_mentions || 'mods';
        const broadcastRadio = document.querySelector(
            `input[name="lounge-broadcast"][value="${broadcast}"]`);
        if (broadcastRadio) broadcastRadio.checked = true;

        // --- Removing members ---
        const kick = lounge.kick_permission || 'mods';
        const kickRadio = document.querySelector(`input[name="lounge-kick"][value="${kick}"]`);
        if (kickRadio) kickRadio.checked = true;

        // --- Project tools switch ---
        const projectToggle = document.getElementById('editLoungeProjectToggle');
        const projectHint = document.getElementById('editLoungeProjectHint');
        projectToggle.checked = !!lounge.project_enabled;

        renderLoungeModPowers(lounge.mod_powers || []);

        // Say up front why the switch will not go off, rather than letting them
        // flip it and take a rejection from the server on save.
        const projectChannelCount = lounge.project_channel_count || 0;
        if (lounge.project_enabled && projectChannelCount > 0) {
            projectHint.textContent = `On. Delete your ${projectChannelCount} project channel${projectChannelCount === 1 ? '' : 's'} before turning this off.`;
        } else if (lounge.project_enabled) {
            projectHint.textContent = 'On. The Project section is showing in the sidebar.';
        } else {
            projectHint.textContent = 'Adds a Project section to the sidebar with a task board. Off by default — most lounges never need it.';
        }

        // Image Setup -- seeded with the banner the lounge already has, so the
        // clear button removes it rather than only cancelling a fresh pick.
        newLoungeCoverUrl = loungeCoverUrl(lounge);
        let syncEditPresets = () => {};
        const editUploader = attachMediaUploader({
            previewId: 'editLoungeCoverPreview',
            inputId: 'editLoungeCoverInput',
            kind: 'cover',
            label: 'Add a cover photo',
            previewName: () => nameInput.value,
            initial: newLoungeCoverUrl,
            onChange: (url) => {
                newLoungeCoverUrl = url;
                syncEditPresets(url);
                if (!url) showToast('Cover image removed from preview.', 'success');
            },
        });
        syncEditPresets = attachLoungeCoverPresets('editLoungeCoverPresets', editUploader,
            url => { newLoungeCoverUrl = url; syncEditPresets(url); });

        nameInput.oninput = () => document.getElementById('editLoungeNameCounter').textContent = `${nameInput.value.length} / 20`;
        descInput.oninput = () => document.getElementById('editLoungeDescCounter').textContent = `${descInput.value.length} / 600`;
    })
    .catch(error => {
        console.error("Error fetching lounge details:", error);
        showToast("Could not load lounge details.", 'error');
    });
}

// The Moderator permissions block in Lounge settings: one switch per power.
function renderLoungeModPowers(enabled) {
    const section = document.getElementById('lounge-mod-powers-section');
    const box = document.getElementById('lounge-mod-powers');
    if (!section || !box) return;
    section.hidden = currentUserLoungeRole !== 'owner';
    box.innerHTML = '';
    LOUNGE_MOD_POWERS.forEach(([key, icon, title, note]) => {
        const row = document.createElement('label');
        row.className = 'mod-power';
        row.innerHTML = `
            <span class="mod-power-icon"><i class="fas ${icon}"></i></span>
            <span class="mod-power-copy"><b></b><span></span></span>
            <span class="lounge-switch">
                <input type="checkbox" data-power="${key}">
                <span class="lounge-switch-slider"></span>
            </span>`;
        row.querySelector('b').textContent = title;
        row.querySelector('.mod-power-copy span').textContent = note;
        row.querySelector('input').checked = enabled.includes(key);
        box.appendChild(row);
    });
}

function readLoungeModPowers() {
    return Array.from(document.querySelectorAll('#lounge-mod-powers input[data-power]'))
        .filter(i => i.checked).map(i => i.dataset.power);
}

function handleEditLounge(button) {
    button.disabled = true;
    button.textContent = 'Saving...';

    const name = document.getElementById('editLoungeName').value.trim();
    const description = document.getElementById('editLoungeDescription').value.trim();
    const coverImage = newLoungeCoverUrl;

    if (!name) {
        showToast('Lounge name is required.', 'error');
        button.disabled = false;
        button.textContent = 'Save Changes';
        return;
    }

    const projectEnabled = document.getElementById('editLoungeProjectToggle').checked;

    const broadcastMentions = document.querySelector(
        'input[name="lounge-broadcast"]:checked')?.value;

    const payload = {
        lounge_id: currentLoungeId,
        name: name,
        description: description,
        cover_image: coverImage,
        project_enabled: projectEnabled
    };
    // Only sent when the form actually has a value. The server treats an absent
    // key as "leave it alone", which is what the moderation-appeal replay needs.
    if (broadcastMentions) payload.broadcast_mentions = broadcastMentions;
    const kickPermission = document.querySelector('input[name="lounge-kick"]:checked')?.value;
    if (kickPermission) {
        payload.kick_permission = kickPermission;
        // The member menu reads this, and it is only refreshed when the lounge is
        // next opened -- keep the owner's own menu in step with what they saved.
        currentLoungeKickPermission = kickPermission;
    }

    // lounge_id is what tells approve_content this is an edit and not a create;
    // without it an approved appeal spawns a duplicate lounge.
    payload.lounge_id = currentLoungeId;

    // Moderator permissions are the owner's alone; a moderator's save leaves them
    // out entirely rather than echoing back values it may not change.
    const modPowers = currentUserLoungeRole === 'owner' ? readLoungeModPowers() : null;
    const savePayload = { ...payload, coverImage };
    if (modPowers) savePayload.mod_powers = modPowers;

    // Editing runs the same AI moderation pass as creating does, so it gets the
    // same progress modal. Without it the save button just sat there while Gemini
    // was called, with nothing on screen saying anything was happening.
    showActionProgress("Saving Lounge...", "Running AI safety checks.");

    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(savePayload)
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 200 && body.ok) {
            completeActionProgress(); // snap the bar to 100% and fade out
            showToast('Lounge updated successfully!', 'success');
            if (modPowers) currentLoungeModPowers = modPowers;
            
            // 1. Update Global Cache
            if (allLoungesData) {
                const index = allLoungesData.findIndex(l => l.id === currentLoungeId);
                if (index > -1) {
                    allLoungesData[index].name = body.lounge.name;
                    allLoungesData[index].description = body.lounge.description;
                    allLoungesData[index].cover_image = body.lounge.cover_image;
                }
            }

            // 2. LIVE UPDATE
            document.getElementById('lounge-header-title').textContent = body.lounge.name;
            document.getElementById('lounge-sidebar-title').textContent = body.lounge.name;

            // Project mode drives the sidebar's Project section and the role chips
            // in chat. showLounge() used to redraw both as a side effect of the
            // navigation this no longer does.
            const projectNowOn = !!projectEnabled;
            if (projectNowOn !== currentLoungeProjectEnabled) {
                currentLoungeProjectEnabled = projectNowOn;
                renderLoungeProjectChannels(
                    currentLoungeChannelList.filter(c => (c.kind || 'chat') !== 'chat')
                );
                if (projectNowOn) {
                    fetchLoungeMembers(true);
                } else {
                    hideRolesBoard();
                    resetLoungeMemberCache();
                    refreshLoungeRoleChips();
                }
            }
            
            // 3. Close the settings modal. showLounge() used to run here because
            // the editor was a whole page and had to be left; from a modal a full
            // reload would throw away the channel and scroll position the user is
            // standing in for no reason.
            closeLoungeMembersModal();
        } else {
            // Take the progress modal down before putting the verdict up, so the
            // two are never stacked on top of each other.
            hideActionProgress();
            // --- MODERATION CHECK ---
            if (isModerationError(body.error)) {
                showModerationErrorModal(body.error, 'edit_lounge', payload);
            } else {
                showToast(body.error || 'Could not update lounge.', 'error');
            }
        }
    })
    .catch(error => {
        hideActionProgress();
        console.error("Error updating lounge:", error);
        showToast("An unexpected error occurred.", 'error');
    })
    .finally(() => {
        // The editor is a modal now, so "are we still on that page" became "is the
        // modal still up". Re-enabling a button inside a closed modal is harmless
        // but leaves it reading "Saving..." the next time it is opened.
        if (!document.getElementById('lounge-members-modal').classList.contains('hidden')) {
            button.disabled = false;
            button.textContent = 'Save';
        }
    });
}

// Add this new function to show a specific lounge's chat
// In index.html, inside the <script> tag


function enterLoungeIncognito() {
    const channels = window.tempIncognitoChannels || [];
    const chatBody = document.getElementById('lounge-body');
    const chatInput = document.getElementById('lounge-input');
    const joinOverlay = document.getElementById('lounge-join-overlay');
    const loungeSidebar = document.querySelector('.lounge-sidebar');

    // UI Setup for Read-Only
    chatBody.style.display = 'flex';
    joinOverlay.classList.remove('visible');
    loungeSidebar.style.display = 'flex';
    
    // Hide input completely for incognito
    chatInput.style.display = 'none'; 

    const mobileListBtn = document.querySelector('.mobile-channel-list-btn');
    if (mobileListBtn) mobileListBtn.classList.remove('force-hidden');

    renderLoungeChannels(channels, window.tempIncognitoGroups);
    updateMobileChannelBadge();
    if (channels.length > 0) {
        loadLoungeChannel(channels[0]);
    }

    showToast("Entered Incognito Mode. You are invisible.", "success");
}

// --- Lounge rail -------------------------------------------------------------
// Every lounge you're in, one tap away from inside any lounge: a strip down the
// left on desktop, a row across the top of the channel list on a phone. Pinned
// lounges come first in your own order (drag to reorder, or pin / move from the
// right-click / long-press menu); the rest follow by recent activity, which is
// how /api/me/lounges already sorts them. Both strips draw from one list.
let loungeRailList = [];
let loungeRailTimer = null;

function fetchLoungeRail() {
    if (!apiToken) return Promise.resolve();
    return fetch(`${API_BASE_URL}/api/me/lounges`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => r.json())
        .then(list => {
            if (!Array.isArray(list)) return;
            loungeRailList = list;
            renderLoungeRail();
        })
        .catch(() => { /* the rail keeps what it had */ });
}

// Many messages can land at once in a busy lounge; one refresh covers them all.
function scheduleLoungeRailRefresh(delay = 1200) {
    clearTimeout(loungeRailTimer);
    loungeRailTimer = setTimeout(fetchLoungeRail, delay);
}

function renderLoungeRail() {
    ['lounge-rail', 'lounge-rail-top'].forEach(id => {
        const box = document.getElementById(id);
        if (box) drawLoungeRail(box, id === 'lounge-rail-top');
    });
}

function drawLoungeRail(box, horizontal) {
    // Redrawing empties the box, and an empty box scrolls to 0. The rail is
    // repainted on every lounge open and on every unread change, so without
    // this the horizontal row snapped back to its first cover constantly.
    const keptScroll = horizontal ? box.scrollLeft : box.scrollTop;
    box.innerHTML = '';
    const pinned = loungeRailList.filter(l => l.pinned);
    const rest = loungeRailList.filter(l => !l.pinned);

    if (!horizontal) {
        const home = document.createElement('button');
        home.type = 'button';
        home.className = 'lr-item lr-action';
        home.title = 'Switch lounge';
        home.setAttribute('aria-label', 'Switch lounge');
        home.id = 'lounge-rail-switch';
        home.innerHTML = '<span class="lr-cover"><i class="fas fa-table-cells-large"></i></span>';
        home.onclick = e => { e.stopPropagation(); toggleLoungeSwitcher(home); };
        box.appendChild(home);
        box.appendChild(Object.assign(document.createElement('span'), { className: 'lr-divider' }));
    }

    pinned.forEach(l => box.appendChild(loungeRailItem(l, horizontal)));
    if (pinned.length && rest.length) {
        box.appendChild(Object.assign(document.createElement('span'), { className: 'lr-divider' }));
    }
    rest.forEach(l => box.appendChild(loungeRailItem(l, horizontal)));

    const add = document.createElement('button');
    add.type = 'button';
    add.className = 'lr-item lr-action lr-add';
    add.title = 'New lounge';
    add.setAttribute('aria-label', 'New lounge');
    add.innerHTML = '<span class="lr-cover"><i class="fas fa-plus"></i></span>' +
        (horizontal ? '<span class="lr-name">New</span>' : '');
    add.onclick = () => openQuickCreateLounge();
    box.appendChild(add);

    if (horizontal) box.scrollLeft = keptScroll || loungeScrollMemory.rail;
    else box.scrollTop = keptScroll;

    // Keep the lounge you're in on screen in a long horizontal row. Scrolled by
    // hand: scrollIntoView() also scrolls every ancestor, which shoved the whole
    // lounge page sideways.
    const active = box.querySelector('.lr-item.is-active');
    if (active && horizontal) {
        const left = active.offsetLeft - box.offsetLeft;
        if (left < box.scrollLeft || left + active.offsetWidth > box.scrollLeft + box.clientWidth) {
            box.scrollLeft = Math.max(0, left - 14);
        }
    }
}

function loungeRailItem(lounge, horizontal) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'lr-item';
    b.dataset.id = lounge.id;
    const isActive = Number(lounge.id) === Number(currentLoungeId) &&
        isLoungeOnScreen();
    b.classList.toggle('is-active', isActive);
    b.classList.toggle('has-unread', !isActive && lounge.unread_count > 0);
    b.classList.toggle('is-pinned', !!lounge.pinned);
    b.title = lounge.name;
    b.setAttribute('aria-label', lounge.name + (lounge.unread_count > 0 ? ', unread' : ''));
    if (isActive) b.setAttribute('aria-current', 'page');

    const cover = document.createElement('span');
    cover.className = 'lr-cover';
    cover.style.backgroundImage = `url("${loungeCoverUrl(lounge)}")`;
    b.append(Object.assign(document.createElement('span'), { className: 'lr-pill' }), cover,
             Object.assign(document.createElement('span'), { className: 'lr-dot' }));
    if (lounge.pinned) {
        const pin = document.createElement('span');
        pin.className = 'lr-pin';
        pin.innerHTML = '<i class="fas fa-thumbtack"></i>';
        b.appendChild(pin);
    }
    if (horizontal) {
        const name = document.createElement('span');
        name.className = 'lr-name';
        name.textContent = lounge.name;
        b.appendChild(name);
    }

    b.onclick = () => {
        if (b.dataset.suppressClick) { delete b.dataset.suppressClick; return; }
        if (isActive) return;
        // In Messages the rail switches lounges in place. Routing to
        // /lounges/<id> would hand the nodes back to the lounge page and take
        // the user with them.
        if (loungeHostedInMessages()) showLounge(lounge.id);
        else navigateToLounge(lounge.id);
    };
    b.oncontextmenu = e => { e.preventDefault(); openLoungeRailMenu(lounge, e.pageX, e.pageY); };

    // Touch: long-press opens the same menu. iOS never fires contextmenu.
    let pressTimer = null;
    b.addEventListener('touchstart', e => {
        const t = e.touches[0];
        pressTimer = setTimeout(() => {
            b.dataset.suppressClick = '1';
            openLoungeRailMenu(lounge, t.pageX, t.pageY);
        }, 500);
    }, { passive: true });
    ['touchend', 'touchmove', 'touchcancel'].forEach(ev =>
        b.addEventListener(ev, () => clearTimeout(pressTimer), { passive: true }));

    // Mouse: drag onto a lounge to put it there. Dropping onto a pinned lounge
    // pins the dragged one at that spot; onto an unpinned one, at the end.
    b.draggable = true;
    b.ondragstart = e => {
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', String(lounge.id));
        b.classList.add('is-dragging');
    };
    b.ondragend = () => {
        b.classList.remove('is-dragging');
        document.querySelectorAll('.lr-item.is-drop-target').forEach(x => x.classList.remove('is-drop-target'));
    };
    b.ondragover = e => { e.preventDefault(); b.classList.add('is-drop-target'); };
    b.ondragleave = () => b.classList.remove('is-drop-target');
    b.ondrop = e => {
        e.preventDefault();
        b.classList.remove('is-drop-target');
        const draggedId = Number(e.dataTransfer.getData('text/plain'));
        if (!draggedId || draggedId === Number(lounge.id)) return;
        const pins = loungeRailList.filter(l => l.pinned).map(l => Number(l.id)).filter(id => id !== draggedId);
        const at = lounge.pinned ? pins.indexOf(Number(lounge.id)) : pins.length;
        pins.splice(at, 0, draggedId);
        saveLoungePins(pins);
    };
    return b;
}

function openLoungeRailMenu(lounge, x, y) {
    document.querySelectorAll('.context-menu').forEach(m => m.remove());
    const pins = loungeRailList.filter(l => l.pinned).map(l => Number(l.id));
    const id = Number(lounge.id);
    const idx = pins.indexOf(id);

    const menu = document.createElement('div');
    menu.className = 'context-menu lr-menu';
    const add = (icon, label, fn) => {
        const a = document.createElement('a');
        a.className = 'context-menu-item';
        a.innerHTML = `<i class="fas ${icon}"></i><span></span>`;
        a.querySelector('span').textContent = label;
        a.onclick = () => { menu.remove(); fn(); };
        menu.appendChild(a);
    };
    const title = document.createElement('div');
    title.className = 'lr-menu-title';
    title.textContent = lounge.name;
    menu.appendChild(title);

    if (idx === -1) {
        add('fa-thumbtack', 'Pin to top', () => saveLoungePins([...pins, id]));
    } else {
        if (idx > 0) add('fa-arrow-up', 'Move up', () => { pins.splice(idx, 1); pins.splice(idx - 1, 0, id); saveLoungePins(pins); });
        if (idx < pins.length - 1) add('fa-arrow-down', 'Move down', () => { pins.splice(idx, 1); pins.splice(idx + 1, 0, id); saveLoungePins(pins); });
        add('fa-thumbtack-slash', 'Unpin', () => saveLoungePins(pins.filter(p => p !== id)));
    }
    document.body.appendChild(menu);

    const w = menu.offsetWidth, h = menu.offsetHeight;
    menu.style.left = `${Math.max(8, Math.min(x, window.scrollX + window.innerWidth - w - 8))}px`;
    menu.style.top = `${Math.max(8, Math.min(y, window.scrollY + window.innerHeight - h - 8))}px`;

    // Close on the next tap anywhere else.
    setTimeout(() => document.addEventListener('pointerdown', function close(e) {
        if (!menu.contains(e.target)) { menu.remove(); document.removeEventListener('pointerdown', close); }
    }), 0);
}

// Pin state is saved as the whole ordered list, and applied locally first so
// the rail moves the instant you let go.
function saveLoungePins(ids) {
    const before = loungeRailList;
    const order = new Map(ids.map((id, i) => [Number(id), i]));
    const pinned = ids.map(id => loungeRailList.find(l => Number(l.id) === Number(id)))
        .filter(Boolean).map(l => ({ ...l, pinned: true }));
    const rest = loungeRailList.filter(l => !order.has(Number(l.id))).map(l => ({ ...l, pinned: false }));
    loungeRailList = [...pinned, ...rest];
    renderLoungeRail();

    fetch(`${API_BASE_URL}/api/me/lounges/pins`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ ids: ids.map(Number) })
    })
    .then(r => { if (!r.ok) throw new Error(); })
    .catch(() => {
        loungeRailList = before;
        renderLoungeRail();
        showToast('Could not save your lounge order.', 'error');
    });
}

// --- Lounge switcher ---------------------------------------------------------
// The grid button at the top of the rail: every lounge you're in, searchable,
// in a popover beside the rail -- so finding one never costs a trip to another
// page. Enter opens the first match.
function toggleLoungeSwitcher(anchor) {
    const pop = document.getElementById('lounge-switcher');
    if (!pop.classList.contains('hidden')) { closeLoungeSwitcher(); return; }

    const input = document.getElementById('lsw-input');
    input.value = '';
    input.oninput = () => renderLoungeSwitcher(input.value);
    input.onkeydown = e => {
        if (e.key === 'Escape') { closeLoungeSwitcher(); return; }
        const rows = [...document.querySelectorAll('#lsw-list .lsw-row')];
        if (!rows.length) return;
        let i = rows.findIndex(r => r.classList.contains('is-focus'));
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            e.preventDefault();
            i = e.key === 'ArrowDown' ? Math.min(rows.length - 1, i + 1) : Math.max(0, i - 1);
            rows.forEach((r, k) => r.classList.toggle('is-focus', k === i));
            rows[i].scrollIntoView({ block: 'nearest' });
        } else if (e.key === 'Enter') {
            e.preventDefault();
            (rows[i] || rows[0]).click();
        }
    };
    document.getElementById('lsw-browse').onclick = () => { closeLoungeSwitcher(); navigateTo('/lounges'); };

    renderLoungeSwitcher('');
    const r = anchor.getBoundingClientRect();
    pop.style.left = `${r.right + 12}px`;
    pop.style.top = `${Math.max(12, Math.min(r.top, window.innerHeight - 440))}px`;
    pop.classList.remove('hidden');
    anchor.classList.add('is-open');
    setTimeout(() => input.focus(), 30);
    if (!loungeRailList.length) fetchLoungeRail().then(() => renderLoungeSwitcher(input.value));

    setTimeout(() => document.addEventListener('pointerdown', loungeSwitcherOutside), 0);
}

function loungeSwitcherOutside(e) {
    const pop = document.getElementById('lounge-switcher');
    if (pop.contains(e.target) || e.target.closest('#lounge-rail-switch')) return;
    closeLoungeSwitcher();
}

function closeLoungeSwitcher() {
    document.getElementById('lounge-switcher').classList.add('hidden');
    document.getElementById('lounge-rail-switch')?.classList.remove('is-open');
    document.removeEventListener('pointerdown', loungeSwitcherOutside);
}

function renderLoungeSwitcher(query) {
    const list = document.getElementById('lsw-list');
    list.innerHTML = '';
    const q = query.trim().toLowerCase();
    const rows = loungeRailList.filter(l => !q || (l.name || '').toLowerCase().includes(q));
    if (!rows.length) {
        const li = document.createElement('li');
        li.className = 'lsw-empty';
        li.textContent = q ? `No lounge called “${query.trim()}”` : 'You haven’t joined any lounges yet';
        list.appendChild(li);
        return;
    }
    rows.forEach((l, i) => {
        const li = document.createElement('li');
        li.className = 'lsw-row' + (i === 0 && q ? ' is-focus' : '');
        li.setAttribute('role', 'option');
        const here = Number(l.id) === Number(currentLoungeId);
        li.classList.toggle('is-here', here);
        li.innerHTML = `<span class="lsw-cover"></span><span class="lsw-name"></span>
            <span class="lsw-dot"></span>
            <button type="button" class="lsw-pin" aria-label="${l.pinned ? 'Unpin' : 'Pin'}" title="${l.pinned ? 'Unpin' : 'Pin to top'}"><i class="fas fa-thumbtack"></i></button>`;
        li.querySelector('.lsw-cover').style.backgroundImage = `url("${loungeCoverUrl(l)}")`;
        li.querySelector('.lsw-name').textContent = l.name;
        li.classList.toggle('has-unread', !here && l.unread_count > 0);
        li.classList.toggle('is-pinned', !!l.pinned);
        li.onclick = () => { closeLoungeSwitcher(); if (!here) navigateToLounge(l.id); };
        li.querySelector('.lsw-pin').onclick = e => {
            e.stopPropagation();
            const pins = loungeRailList.filter(x => x.pinned).map(x => Number(x.id));
            saveLoungePins(l.pinned ? pins.filter(p => p !== Number(l.id)) : [...pins, Number(l.id)]);
            renderLoungeSwitcher(document.getElementById('lsw-input').value);
        };
        list.appendChild(li);
    });
}

// --- New lounge, in place -----------------------------------------------------
// The + at the bottom of the rail. Same fields and the same request as the
// create page, in a dialog over the lounge you're in, and it drops you straight
// into the new lounge instead of back on the home page.
let quickLoungeCoverUrl = null;

function openQuickCreateLounge() {
    const modal = document.getElementById('quick-lounge-modal');
    const name = document.getElementById('qlName');
    const desc = document.getElementById('qlDesc');
    const counter = document.getElementById('qlNameCounter');
    name.value = '';
    desc.value = '';
    counter.textContent = '0 / 20';
    name.oninput = () => { counter.textContent = `${name.value.length} / 20`; };
    name.onkeydown = e => { if (e.key === 'Enter') { e.preventDefault(); document.getElementById('ql-create').click(); } };
    document.querySelector('input[name="qlPrivacy"][value="public"]').checked = true;
    const btn = document.getElementById('ql-create');
    btn.disabled = false;
    btn.textContent = 'Create lounge';

    quickLoungeCoverUrl = randomLoungePresetUrl();
    let sync = () => {};
    const uploader = attachMediaUploader({
        previewId: 'qlCoverPreview',
        inputId: 'qlCoverInput',
        kind: 'cover',
        label: 'Add a cover photo',
        previewName: () => name.value,
        initial: quickLoungeCoverUrl,
        onChange: url => { quickLoungeCoverUrl = url; sync(url); },
    });
    sync = attachLoungeCoverPresets('qlCoverPresets', uploader, url => { quickLoungeCoverUrl = url; sync(url); });

    modal.classList.remove('hidden');
    setTimeout(() => name.focus(), 60);
}

function closeQuickCreateLounge() {
    document.getElementById('quick-lounge-modal')?.classList.add('hidden');
}

function submitQuickCreateLounge(button) {
    const name = document.getElementById('qlName').value.trim();
    if (!name) {
        showToast('Give your lounge a name.', 'error');
        document.getElementById('qlName').focus();
        return;
    }
    const payload = {
        name,
        description: document.getElementById('qlDesc').value.trim(),
        privacy: document.querySelector('input[name="qlPrivacy"]:checked').value,
        coverImage: quickLoungeCoverUrl,
    };
    button.disabled = true;
    button.innerHTML = '<span class="ql-spinner"></span> Creating…';

    fetch(`${API_BASE_URL}/api/lounges`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(payload)
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status === 201) {
            closeQuickCreateLounge();
            if (socket) socket.emit('join_all_lounge_rooms');
            showToast(`${body.lounge.name} is ready.`, 'success');
            fetchLoungeRail();
            navigateToLounge(body.lounge.id);
        } else if (isModerationError(body.error)) {
            closeQuickCreateLounge();
            showModerationErrorModal(body.error, 'lounge', payload);
        } else {
            showToast(body.error || 'Could not create the lounge.', 'error');
        }
    })
    .catch(() => showToast('Could not create the lounge. Please try again.', 'error'))
    .finally(() => {
        button.disabled = false;
        button.textContent = 'Create lounge';
    });
}

// True only while showLounge is switching to Messages to host a lounge; tells
// showPage's Messages setup to leave the DM half alone.
let openingLoungeInMessages = false;

function showLounge(loungeId, targetChannelId = null) {
    setPageTitle('Loading...');
    
    // Increment view count
    fetch(`${API_BASE_URL}/api/lounge/${loungeId}/view`, { method: 'POST', headers: { 'Authorization': `Bearer ${apiToken}` } });

    if (currentLoungeChannelId && socket) {
        socket.emit('leave_lounge_channel', { channel_id: currentLoungeChannelId });
    }
    currentLoungeId = loungeId;
    currentLoungeChannelId = null;

    // A shelf left open belongs to the lounge we're leaving.
    closeLoungeResources();

    // UI References
    const chatBody = document.getElementById('lounge-body');
    const chatInput = document.getElementById('lounge-input');
    const joinOverlay = document.getElementById('lounge-join-overlay');
    const loungeSidebar = document.querySelector('.lounge-sidebar');
    const joinButton = document.getElementById('join-lounge-btn');

    // Reset UI
    if (joinButton) {
        joinButton.style.display = 'block';
        joinButton.disabled = false;
        joinButton.onclick = handleJoinLounge;
    }
    
    const existingAdminBtns = document.getElementById('admin-lounge-actions');
    if(existingAdminBtns) existingAdminBtns.remove();

    // The wait starts here, not at loadLoungeChannel: the channel list has to come
    // back before we even know which channel to open, and that gap used to show as
    // a blank box. The non-member branch below hides this again for the join screen.
    chatBody.style.display = 'flex';
    showLoungeBodySkeleton();

    chatInput.style.display = 'none';
    joinOverlay.classList.remove('visible');
    loungeSidebar.style.display = 'none';

    document.getElementById('lounge-header-title').textContent = 'Loading...';
    document.getElementById('lounge-sidebar-title').textContent = 'Loading...';
    
    // --- FIX: Update Mobile Header Loading State ---
    const mobileTitle = document.getElementById('lounge-header-title-mobile');
    if (mobileTitle) mobileTitle.textContent = 'Loading...';
    // ----------------------------------------------

    document.getElementById('lounge-channels-list').innerHTML = '<li>Loading...</li>';
    // Drop the previous lounge's channels: the non-member path never calls
    // renderLoungeChannels, so a stale list would survive into the join screen
    // and let the header swipe jump into a lounge we just left.
    currentLoungeChannelList = [];
    currentLoungeProjectEnabled = false;
    currentLoungeCanBroadcast = false;
    resetLoungeMemberCache();

    // Lounges live in Messages now -- there is no lounge page to go to. Opening
    // one from anywhere (a Home card, Explore, a push, a /lounges/<id> link) shows
    // Messages already on its Lounges half with this lounge in it.
    //
    // All of it in this one synchronous call, before the browser gets a frame:
    // the page switch, the mode flip that moves the lounge's nodes into Messages,
    // and the skeleton set up above. So the first thing ever painted is the
    // lounge loading in place -- never the DM list for a beat and the lounge
    // arriving after it.
    if (!loungeHostedInMessages() ||
        !document.getElementById('messages-page')?.classList.contains('active')) {
        openingLoungeInMessages = true;
        try {
            showPage('messages-page');
        } finally {
            openingLoungeInMessages = false;
        }
        setMessagesPaneMode('lounges', { skipOpen: true });
    }
    initializeAllEmojiPickers();

    fetch(`${API_BASE_URL}/api/lounge/${loungeId}/channels`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        if (data.error) {
            showToast(data.error, 'error');
            navigateTo('/');
            return;
        }

        const realLoungeName = data.lounge_name || 'Lounge';
        renderLoungeRail();
        scheduleLoungeRailRefresh(600);
        currentLoungeDescription = data.lounge_description || "No description.";
        currentLoungeCover = data.lounge_cover || null;
        currentLoungePrivacy = data.privacy || 'public';
        setPageTitle(realLoungeName);
        document.getElementById('lounge-header-title').textContent = realLoungeName;
        document.getElementById('lounge-sidebar-title').textContent = realLoungeName;
        const sidebarHeader = document.getElementById('lounge-sidebar-header');
        if (sidebarHeader) {
            sidebarHeader.style.setProperty('--lounge-cover',
                `url("${loungeCoverUrl({ id: loungeId, cover_image: data.lounge_cover })}")`);
            sidebarHeader.classList.add('has-cover');
        }

        // --- FIX: Update Mobile Header Text ---
        if (mobileTitle) mobileTitle.textContent = realLoungeName;
        // -------------------------------------

        // --- Setup Header Buttons (Invite / Menu) ---
        // By id, not by page. This group is re-parented into the Messages header
        // while the Direct/Lounges switch is on Lounges, so a
        // '#lounge-page .header-right' lookup finds nothing there -- and the
        // null reference it produced was thrown inside this fetch's .then(),
        // where the .catch() below turns any error at all into "Could not load
        // lounge information" and sends you to the home page. The node keeps its
        // id wherever it is parked, so this works from either host.
        const headerRight = document.getElementById('lounge-header-actions');
        headerRight.innerHTML = ''; 

        // 1. NEW: Add Mobile Channel List Button
        const mobileListBtn = document.createElement('div');
        mobileListBtn.className = 'profile-menu-button mobile-channel-list-btn';
        mobileListBtn.innerHTML = '<i class="fas fa-list-ul"></i><span id="mobile-channel-unread-badge" class="mobile-channel-unread-badge" style="display:none;"></span>';
        // This now calls the TOGGLE function instead of just 'show'
        mobileListBtn.onclick = toggleMobileChannelList;
        headerRight.appendChild(mobileListBtn);

        // 2. Invite Button (Only for Owner/Mod)
        if (data.user_role === 'owner' || data.user_role === 'moderator') {
            const inviteBtn = document.createElement('div');
            inviteBtn.className = 'profile-menu-button';
            inviteBtn.innerHTML = '<i class="fas fa-user-plus"></i>';
            inviteBtn.onclick = showInviteUserModal;
            headerRight.appendChild(inviteBtn);
        }

        // 3. Menu Button
        const menuBtn = document.createElement('div');
        menuBtn.className = 'profile-menu-button';
        menuBtn.innerHTML = '<i class="fas fa-ellipsis-v"></i>';
        menuBtn.onclick = toggleLoungeMenu;
        headerRight.appendChild(menuBtn);

        // 4. Dropdown Container
        const menuDropdown = document.createElement('div');
        menuDropdown.id = 'lounge-menu-dropdown';
        menuDropdown.className = 'profile-menu-dropdown hidden';
        headerRight.appendChild(menuDropdown);

        // --- ACCESS & VIEW LOGIC ---

        if (data.is_member) {
            // === MEMBER VIEW (All Ranks) ===
            chatBody.style.display = 'flex';
            chatInput.style.display = 'flex';
            joinOverlay.classList.remove('visible');
            loungeSidebar.style.display = 'flex';

            currentUserLoungeRole = data.user_role;
            currentLoungeProjectEnabled = !!data.project_enabled;
            currentLoungeCanBroadcast = !!data.can_broadcast;
            currentLoungeKickPermission = data.kick_permission || 'mods';
            currentLoungeModPowers = Array.isArray(data.mod_powers) ? data.mod_powers : [];
            // Who has which job label, for the chips in chat and the Roles board.
            // Only project lounges have labels, so only they pay for the request.
            resetLoungeMemberCache();
            if (currentLoungeProjectEnabled) fetchLoungeMembers();
            mobileListBtn?.classList.remove('force-hidden');
            renderLoungeChannels(data.channels, data.channel_groups);
            updateMobileChannelBadge();

            // Read the list back from renderLoungeChannels rather than trusting the
            // payload again: it has already coerced a missing/!Array `channels` to
            // [], so a half-broken response lands on the "no channels yet" branch
            // instead of throwing here and bouncing the user out of the lounge.
            const loadedChannels = currentLoungeChannelList;

            if (loadedChannels.length > 0) {
                // A lounge push deep-links to the channel it came from; fall back
                // to the first channel if that one is gone or not visible to us.
                const requested = targetChannelId
                    ? loadedChannels.find(c => String(c.id) === String(targetChannelId))
                    : null;
                // A deep link names its channel and means it; anything else --
                // the rail, the switch, coming back to Messages -- is "show me
                // this lounge", which on a phone in Messages means its channel
                // list. On the lounge page, and on any desktop, this is
                // unchanged: there is no list/pane split to stay on the near
                // side of.
                const asked = !!requested;
                loadLoungeChannel(requested || loadedChannels[0],
                                  { enterOnMobile: asked || !loungeHostedInMessages() });
            } else {
                clearLoungeBodySkeleton();
                chatBody.innerHTML = '<p style="text-align:center;color:#888;">No channels have been created yet.</p>';
                document.getElementById('lounge-input-field').placeholder = 'No channels available';
                document.getElementById('lounge-input-field').disabled = true;
            }
        } 
        else {
            // === NON-MEMBER VIEW ===
            chatBody.style.display = 'none';
            // The join card is the answer now, so retire the skeleton rather than
            // leaving it shimmering behind a hidden box.
            clearLoungeBodySkeleton();
            chatInput.style.display = 'none';
            loungeSidebar.style.display = 'none';
            joinOverlay.classList.add('visible');
            currentUserLoungeRole = null;

            // On mobile the lounge opens in "list mode" by default, which for a
            // non-member means a stray channel list instead of the join card.
            // Force the pane view and take the channel-list button away.
            const loungeContainer = loungeHostContainer();
            if (loungeContainer) loungeContainer.classList.add('mobile-chat-active');
            mobileListBtn?.classList.add('force-hidden');
            document.getElementById('lounge-channels-list').innerHTML = '';

            const joinTitle = document.getElementById('join-lounge-title');
            const joinDesc = document.getElementById('join-lounge-description');
            const joinIcon = document.getElementById('join-lounge-privacy-icon');
            
            joinTitle.textContent = data.lounge_name;
            joinDesc.textContent = data.lounge_description || "You've discovered a new lounge!";
            
            // Hide default single button (we will build custom buttons below)
            joinButton.style.display = 'none';

            // Create Button Container
            const btnContainer = document.createElement('div');
            btnContainer.id = 'admin-lounge-actions';
            btnContainer.style.display = 'flex';
            btnContainer.style.gap = '10px';
            btnContainer.style.marginTop = '20px';
            btnContainer.style.flexWrap = 'wrap';
            btnContainer.style.justifyContent = 'center';

            let buttonsHtml = '';

            // === ADMIN LOGIC (Based on prompt) ===
            if (data.can_view_incognito) { // Server returns True only for Admin rank
                joinIcon.className = 'fas fa-user-shield privacy-icon';
                
                // Store channels for Incognito usage
                window.tempIncognitoChannels = data.channels;
                window.tempIncognitoGroups = data.channel_groups;

                if (data.privacy === 'public') {
                    // Public: Incognito OR Join
                    buttonsHtml += `
                        <button class="join-lounge-btn" style="background: #333;" onclick="enterLoungeIncognito()">
                            <i class="fas fa-user-secret"></i> Incognito
                        </button>
                        <button class="join-lounge-btn" onclick="handleJoinLounge()">
                            <i class="fas fa-sign-in-alt"></i> Join
                        </button>
                    `;
                } else if (data.privacy === 'private') {
                    // Private: Incognito OR Request Access
                    buttonsHtml += `
                        <button class="join-lounge-btn" style="background: #333;" onclick="enterLoungeIncognito()">
                            <i class="fas fa-user-secret"></i> Incognito
                        </button>
                        <button class="join-lounge-btn" onclick="handleRequestLoungeAccess()">
                            <i class="fas fa-paper-plane"></i> Request Access
                        </button>
                    `;
                } else if (data.privacy === 'unlisted') {
                    // Unlisted: Incognito ONLY
                    buttonsHtml += `
                        <button class="join-lounge-btn" style="background: #333;" onclick="enterLoungeIncognito()">
                            <i class="fas fa-user-secret"></i> Incognito
                        </button>
                    `;
                }
            } 
            // === MODERATOR & USER LOGIC (Based on prompt) ===
            else {
                joinIcon.className = data.privacy === 'private' ? 'fas fa-lock privacy-icon' : 'fas fa-globe-americas privacy-icon';

                if (data.privacy === 'public') {
                    // Public: Join
                    buttonsHtml += `
                        <button class="join-lounge-btn" onclick="handleJoinLounge()">
                            <i class="fas fa-sign-in-alt"></i> Join Lounge
                        </button>
                    `;
                } else if (data.privacy === 'private') {
                    // Private: Request Access
                    buttonsHtml += `
                        <button class="join-lounge-btn" onclick="handleRequestLoungeAccess()">
                            <i class="fas fa-paper-plane"></i> Request Access
                        </button>
                    `;
                }
                // Unlisted: Should generally not be reachable here, but if so, show nothing or generic message.
            }

            btnContainer.innerHTML = buttonsHtml;
            document.querySelector('.join-lounge-card').appendChild(btnContainer);
        }
    })
    .catch(error => {
        console.error("Error loading lounge:", error);
        showToast("Could not load lounge information.", 'error');
        navigateTo('/');
    });
}

// Add this new function inside your <script> tag

// Mirrors the per-channel unread dots onto the mobile header button, so the count
// is visible while the channel list is collapsed.
// The badge on the button that REVEALS the channel list on a phone. It counts
// the dots in the list it is standing in for, so it has to count both lists:
// chat channels and project ones. A notice board is a project channel and can
// genuinely be unread -- posting a notice bumps its channel's last_message_at
// the same way a message does -- so counting only the chat list left an unread
// notice board with a dot nobody on a phone could ever see, the sidebar being
// hidden behind this very button.
function updateMobileChannelBadge() {
    const badge = document.getElementById('mobile-channel-unread-badge');
    if (!badge) return;

    const count = document.querySelectorAll(
        '#lounge-channels-list .lounge-channel-item.has-unread,' +
        ' #lounge-project-channels-list .lounge-channel-item.has-unread').length;
    if (count > 0) {
        badge.textContent = count > 99 ? '99+' : count;
        badge.style.display = 'flex';
    } else {
        badge.style.display = 'none';
    }
}

function toggleMobileChannelList() {
    // This is what the rebuilt header button actually calls (showMobileChannelList
    // only serves the static markup showLounge replaces). In Messages the lounge
    // lives in .messages-container, and toggling the class on an empty
    // .lounge-container did nothing at all.
    const container = loungeHostContainer();
    if (!container) return;
    // Toggling this class switches between the Chat view and the List view on mobile
    const opened = container.classList.toggle('mobile-chat-active');
    if (opened) pushMsgLoungeChannelHistory();
    else dropMsgLoungeChannelHistory();
}

// --- Mobile lounge header: swipe to change channel --------------------------
// Swiping the header down moves to the next channel, up to the previous one --
// the same list, and the same order, as the sidebar. Wraps at both ends so a
// two-channel lounge behaves like a toggle.

// --- Lounge channel loading state -------------------------------------------
// A pending fetch and an empty channel both used to render as a blank box, so
// there was no way to tell "nothing here" from "not here yet". The skeleton
// covers the wait; showLoungeEmptyState covers the other case.

// Shape of the placeholder conversation: which side, and the line widths.
const LOUNGE_SKELETON_ROWS = [
    { sent: false, lines: ['wide', 'short'] },
    { sent: true,  lines: ['mid'] },
    { sent: false, lines: ['mid', 'wide'] },
    { sent: true,  lines: ['short'] },
    { sent: false, lines: ['wide'] }
];

// Shared by the lounge and DM loaders: the same placeholder conversation, so a
// thread that is still loading looks the same wherever you are.
function buildChatSkeleton() {
    const skeleton = document.createElement('div');
    skeleton.className = 'lounge-skeleton';

    LOUNGE_SKELETON_ROWS.forEach(({ sent, lines }) => {
        const row = document.createElement('div');
        row.className = `lounge-skeleton-row${sent ? ' sent' : ''}`;

        // Only received rows carry an avatar, same as a real message row.
        if (!sent) {
            const avatar = document.createElement('div');
            avatar.className = 'lounge-skeleton-avatar';
            row.appendChild(avatar);
        }

        const lineBox = document.createElement('div');
        lineBox.className = 'lounge-skeleton-lines';
        lines.forEach(width => {
            const line = document.createElement('div');
            line.className = `lounge-skeleton-line ${width}`;
            lineBox.appendChild(line);
        });

        row.appendChild(lineBox);
        skeleton.appendChild(row);
    });

    return skeleton;
}

function showLoungeBodySkeleton() {
    const chatBody = document.getElementById('lounge-body');
    if (!chatBody) return;
    chatBody.innerHTML = '';
    chatBody.appendChild(buildChatSkeleton());
}

// The DM half of the same idea. Opening a thread used to leave the PREVIOUS
// conversation on screen until the fetch landed, and a cold open showed a blank
// white box -- neither said "loading".
function showDmBodySkeleton() {
    const chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    chatBody.innerHTML = '';
    chatBody.appendChild(buildChatSkeleton());
}

function clearDmBodySkeleton() {
    document.getElementById('chat-body')?.querySelectorAll('.lounge-skeleton').forEach(el => el.remove());
}

function clearLoungeBodySkeleton() {
    const chatBody = document.getElementById('lounge-body');
    if (!chatBody) return;
    chatBody.querySelectorAll('.lounge-skeleton, .lounge-empty-state').forEach(el => el.remove());
}

function showLoungeEmptyState() {
    const chatBody = document.getElementById('lounge-body');
    if (!chatBody) return;

    clearLoungeBodySkeleton();

    const empty = document.createElement('div');
    empty.className = 'lounge-empty-state';
    empty.innerHTML = `
        <i class="fas fa-comments"></i>
        <div class="lounge-empty-state-title">No messages yet</div>
        <div class="lounge-empty-state-sub">Be the first to say something.</div>
    `;
    chatBody.appendChild(empty);
}

function switchToAdjacentChannel(step) {
    const channels = currentLoungeChannelList;
    if (!Array.isArray(channels) || channels.length < 2) return;

    const current = channels.findIndex(c => String(c.id) === String(currentLoungeChannelId));
    if (current === -1) return;

    const next = channels[(current + step + channels.length) % channels.length];
    if (!next || String(next.id) === String(currentLoungeChannelId)) return;

    // Direction the *text* travels, which reads as the header itself being pulled.
    const info = document.querySelector('.mobile-lounge-header-info');
    if (info) {
        info.classList.remove('channel-swap-down', 'channel-swap-up');
        // Reading offsetWidth restarts the animation when two swipes land in a row.
        void info.offsetWidth;
        info.classList.add(step > 0 ? 'channel-swap-down' : 'channel-swap-up');
    }

    loadLoungeChannel(next);
}

function initLoungeHeaderSwipe() {
    // By id: this header is re-parented into Messages in lounge mode, and a
    // page-scoped lookup would silently stop finding it there -- costing the
    // swipe-to-change-channel gesture with no error to show for it.
    const header = document.getElementById('lounge-page-header');
    if (!header) return;

    // The listeners go on the DOCUMENT, not on #lounge-page. Finding the header
    // by id was only half the job: in Messages the header is a child of
    // #messages-page, so a touch on it never reached a listener bound to
    // #lounge-page and the gesture did nothing there at all. What decides
    // whether the gesture applies is whether a lounge is on screen -- which is
    // true on either host -- not which page element happens to contain it.
    const page = document;

    // Only distances matter here, so a single touch point is all we track.
    let startX = 0, startY = 0, startTime = 0, tracking = false;
    let startedBelowHeader = false, startScrollTop = 0;
    // Any touch that travelled is a gesture, not a tap. The browser still fires a
    // click at the end of it, and without this that click opened the channel list
    // every time a swipe fell short -- which is what made swiping feel unreliable.
    let lastGestureAt = 0;

    const SWIPE_DISTANCE = 38;   // px before a drag counts as a swipe
    const SWIPE_TIMEOUT = 800;   // ms -- a slow drag is a scroll attempt, not a flick
    const TAP_SLOP = 10;         // px of travel a real tap is allowed
    // The bar alone is a thin target sitting right under the status bar, where a
    // downward drag fights the notification shade. The gesture reaches this far
    // past the bar so there is somewhere comfortable to start from.
    const ZONE_BELOW_HEADER = 90;

    const loungeBody = () => document.getElementById('lounge-body');

    page.addEventListener('touchstart', event => {
        // Desktop keeps the sidebar, so the gesture belongs to the phone layout --
        // which a tablet in portrait is now running too.
        tracking = isPhoneLayout() && isLoungeOnScreen() && event.touches.length === 1;
        if (!tracking) return;

        const touch = event.touches[0];
        const limit = header.getBoundingClientRect().bottom;

        if (touch.clientY > limit + ZONE_BELOW_HEADER) {
            tracking = false;
            return;
        }

        startX = touch.clientX;
        startY = touch.clientY;
        startTime = Date.now();
        startedBelowHeader = touch.clientY > limit;
        // Below the bar we are sharing space with the message list, so remember
        // where it was parked (see the touchend check).
        startScrollTop = startedBelowHeader && loungeBody() ? loungeBody().scrollTop : 0;
    }, { passive: true });

    page.addEventListener('touchend', event => {
        if (!tracking) return;
        tracking = false;

        const touch = event.changedTouches[0];
        if (!touch) return;

        const dy = touch.clientY - startY;
        const dx = touch.clientX - startX;

        if (Math.hypot(dx, dy) > TAP_SLOP) lastGestureAt = Date.now();

        if (Date.now() - startTime > SWIPE_TIMEOUT) return;
        // Vertical intent: the horizontal drift has to stay well under the travel.
        if (Math.abs(dy) < SWIPE_DISTANCE || Math.abs(dy) < Math.abs(dx) * 1.5) return;

        // In the strip below the bar, the message list gets first refusal: if it
        // moved, the user was reading history, not changing channel. If it did not
        // move -- because it is already at the end it was pulled towards -- the
        // drag was only ever going to be a channel switch.
        if (startedBelowHeader) {
            const body = loungeBody();
            if (body && body.scrollTop !== startScrollTop) return;
        }

        lastGestureAt = Date.now();
        switchToAdjacentChannel(dy > 0 ? 1 : -1);
    }, { passive: true });

    // Tapping the title block opens the full channel list -- the escape hatch for
    // when swiping through them one at a time is the wrong tool.
    const info = header.querySelector('.mobile-lounge-header-info');
    if (info) {
        info.addEventListener('click', () => {
            if (!isPhoneLayout()) return;
            if (Date.now() - lastGestureAt < 400) return;
            toggleMobileChannelList();
        });
    }
}

// Full roster from the last fetch, so typing filters locally instead of re-hitting the API.
let newChatAllUsers = [];
let newChatListenersBound = false;

function renderNewChatUsers(query = '') {
    const userList = document.getElementById('new-chat-user-list');
    const term = query.trim().toLowerCase();
    const users = term
        ? newChatAllUsers.filter(u =>
            (u.username || '').toLowerCase().includes(term) ||
            (u.fullName || '').toLowerCase().includes(term))
        : newChatAllUsers;

    userList.innerHTML = '';

    if (newChatAllUsers.length === 0) {
        userList.innerHTML = '<li class="new-chat-empty">No other users to message.</li>';
        return;
    }
    if (users.length === 0) {
        userList.innerHTML = '<li class="new-chat-empty">No people match that search.</li>';
        return;
    }

    users.forEach(user => {
        const li = document.createElement('li');
        // We use a <label> to make the whole row clickable
        li.innerHTML = `
            <label class="new-chat-list-item">
                <input type="radio" name="chat-recipient" value="${user.username}">
                <div class="profile-pic" data-user-pic-id="${user.username}"></div>
                <div class="user-info">
                    <span class="username">${user.fullName}${rankIconFor(user.username, user.rank)}</span>
                    <span class="fullname" style="color: #888;">@${user.username}</span>
                </div>
            </label>
        `;
        userList.appendChild(li);
        updateProfilePictures(user.username);
    });
}

function showNewChatModal() {
    const modal = document.getElementById('new-chat-modal');
    const userList = document.getElementById('new-chat-user-list');
    const startBtn = document.getElementById('start-chat-btn');
    const searchInput = document.getElementById('new-chat-search');

    modal.classList.remove('hidden');
    startBtn.disabled = true; // Disable button until a user is selected
    searchInput.value = '';
    userList.innerHTML = '<li class="new-chat-empty">Loading users...</li>';

    if (!newChatListenersBound) {
        newChatListenersBound = true;
        // Selection lives in the re-rendered list, so listen on the container.
        userList.addEventListener('change', () => {
            startBtn.disabled = !userList.querySelector('input[name="chat-recipient"]:checked');
        });
        // Re-rendering drops any checked radio, so the button has to reset with it.
        searchInput.addEventListener('input', () => {
            renderNewChatUsers(searchInput.value);
            startBtn.disabled = true;
        });
        // Don't let Enter submit/close anything -- filtering is already live.
        searchInput.addEventListener('keydown', e => {
            if (e.key === 'Enter') e.preventDefault();
        });
    }

    fetch(`${API_BASE_URL}/api/users/for-chat`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(users => {
        newChatAllUsers = users || [];

        // Store user data locally so avatars resolve
        newChatAllUsers.forEach(user => {
            if (!profileData[user.username]) {
                profileData[user.username] = { name: user.fullName, ...user };
            }
        });

        renderNewChatUsers(searchInput.value);
    });
}

function closeNewChatModal() {
    document.getElementById('new-chat-modal').classList.add('hidden');
}

function initiateChat() {
    const selectedRadio = document.querySelector('input[name="chat-recipient"]:checked');
    if (!selectedRadio) {
        alert("Please select a user to start a chat with.");
        return;
    }
    const username = selectedRadio.value;

    // If a chat with this user doesn't exist locally, create an empty one.
    if (!messageHistory[username]) {
        messageHistory[username] = [];
    }

    // Open the chat (whether it was new or existing)
    openChat(username);

    // Close the modal
    closeNewChatModal();
}



function showCreateLoungePage() {
    // --- ADD LIVE CHARACTER COUNTERS ---
    const nameInput = document.getElementById('loungeName');
    const descInput = document.getElementById('loungeDescription');
    const nameCounter = document.getElementById('loungeNameCounter');
    const descCounter = document.getElementById('loungeDescCounter');

    nameInput.oninput = () => nameCounter.textContent = `${nameInput.value.length} / 20`;
    descInput.oninput = () => descCounter.textContent = `${descInput.value.length} / 600`;
    // --- END ADDITION ---

    nameInput.value = '';
    descInput.value = '';
    nameCounter.textContent = '0 / 20'; // Reset counters
    descCounter.textContent = '0 / 600';

    document.getElementById('privacyPublic').checked = true;

    newLoungeCoverUrl = randomLoungePresetUrl();
    let syncCreatePresets = () => {};
    const createUploader = attachMediaUploader({
        previewId: 'loungeCoverPreview',
        inputId: 'loungeCoverInput',
        kind: 'cover',
        label: 'Add a cover photo',
        previewName: () => nameInput.value,
        initial: newLoungeCoverUrl,
        onChange: (url) => { newLoungeCoverUrl = url; syncCreatePresets(url); },
    });
    syncCreatePresets = attachLoungeCoverPresets('loungeCoverPresets', createUploader,
        url => { newLoungeCoverUrl = url; syncCreatePresets(url); });
    showPage('create-lounge-page');
}

function handleLogout() {
    if (profileData.me && profileData.me.username) {
        const accounts = getSavedAccounts();
        delete accounts[profileData.me.username];
        localStorage.setItem('apex_saved_accounts', JSON.stringify(accounts));
    }
    // With this device's push endpoint, so the server stops pushing this account's
    // notifications to a phone it has been signed out of. Captured first: the
    // token is gone by the time anything below runs.
    const logoutToken = apiToken;
    currentPushEndpoint().then(endpoint => fetch(`${API_BASE_URL}/api/logout`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${logoutToken}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ endpoint })
    })).finally(() => {
        if (socket) {
            socket.disconnect();
            socket = null;
        }
        localStorage.removeItem('apiToken');
        apiToken = null;
        loggedIn = false;
        
        // --- THE SECURITY CLEAR OUT ---
        profileData.me = {}; // Clear user data
        messageHistory = {}; // <-- NEW: Completely wipe local chat history from memory
        
        navigateTo('/login');
    });
}

function handleVerifyCode(verifyButton) {
    const enteredCode = document.getElementById('verificationCodeInput').value.trim();

    if (enteredCode.length !== 6) {
        showToast('Please enter the 6-digit code.', 'error');
        return;
    }

    // ADD DEBUG LOGS HERE
    console.log("[Debug] Entered Code:", enteredCode);
    console.log("[Debug] Expected Code:", generatedVerificationCode);
    console.log("[Debug] Pending Signup Data before fetch:", pendingSignupData);

    if (enteredCode === generatedVerificationCode) {
        // Code is correct, proceed with server-side signup
        console.log("[Debug] Verification code MATCHES. Preparing to call /api/signup..."); // <-- ADD THIS
        verifyButton.disabled = true;
        verifyButton.textContent = 'Verifying...';

        if (!pendingSignupData) {
            console.error("[Debug] ERROR: pendingSignupData is missing!"); // <-- ADD THIS
            showToast('Signup data lost. Please go back and try again.', 'error');
            verifyButton.disabled = false;
            verifyButton.textContent = 'Verify Code';
            return;
        }

        // ADD A LOG RIGHT BEFORE FETCH
        console.log("[Debug] Sending fetch request to /api/signup with data:", JSON.stringify(pendingSignupData)); // <-- ADD THIS

        fetch(`${API_BASE_URL}/api/signup`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(pendingSignupData), // Use the stored data
        })
        .then(response => { // ADD response logging
            console.log("[Debug] Received response from /api/signup:", response.status, response.statusText);
            return response.json().then(data => ({ status: response.status, body: data }));
        })
        .then(({ status, body }) => {
            console.log("[Debug] Parsed response body:", body); // ADD body logging
            if (status === 200 && body.ok) {
                showToast('Verification successful! Account created.', 'success');
                pendingSignupData = null; // Clear temporary data
                generatedVerificationCode = null;
                // The approval is spent server-side once the account exists;
                // drop our copy so a later signup can't try to reuse it.
                guardianConsentToken = null;
                stopGuardianConsentPolling();
                showPage('login-page'); // Redirect to login
            } else {
                showToast(body.error || 'Signup failed after verification.', 'error');
                // The precheck normally catches a moderation block long before this,
                // but /api/signup is the authoritative gate and can still be the one
                // to say no -- so the appeal has to be reachable from here too.
                if (body.moderation && pendingSignupData) {
                    showSignupModerationModal(body.error, body.moderation, pendingSignupData.email);
                }
                // Optionally redirect back to signup page on server error
                // showPage('signup-page');
            }
        })
        .catch(error => {
            console.error('[Debug] Fetch to /api/signup FAILED:', error); // <-- ADD THIS
            showToast('An error occurred during final signup. Please try again.', 'error');
        })
        .finally(() => {
            console.log("[Debug] Fetch finally block executed."); // <-- ADD THIS
            if (document.getElementById('verify-page').classList.contains('active')) {
                verifyButton.disabled = false;
                verifyButton.textContent = 'Verify Code';
            }
        });

    } else {
        // Code is incorrect
        console.log("[Debug] Verification code MISMATCH."); // <-- ADD THIS
        showToast('Incorrect verification code.', 'error');
        document.getElementById('verificationCodeInput').value = ''; // Clear input
    }
}

// A server error while restoring a session is the server, not the session --
// most often the few seconds a deploy restart answers 502. Retried with these
// waits (ms) behind the loader, before handing over to the offline page.
const SESSION_RETRY_DELAYS = [1000, 2000, 4000, 8000];
let sessionRetryCount = 0;
let sessionCheckInFlight = false;

function hideAppLoader() {
    const loader = document.getElementById('loader');
    if (loader) {
        loader.style.opacity = '0';
        setTimeout(() => loader.style.display = 'none', 500);
    }
}

function checkForSavedSession() {
    const savedToken = localStorage.getItem('apiToken');
    if (savedToken) {
        // Boot, the offline page's retry and the reconnect path can all ask at
        // once; one answer is enough.
        if (sessionCheckInFlight) return;
        sessionCheckInFlight = true;
        apiToken = savedToken;

        fetch(`${API_BASE_URL}/api/me`, {
            headers: { 'Authorization': `Bearer ${apiToken}` }
        })
        .then(response => {
            if (!response.ok) {
                // Create a custom error object that includes the status code
                const error = new Error('Session validation failed');
                error.status = response.status; 
                throw error;
            }
            return response.json();
        })
        .then(userData => {
            sessionCheckInFlight = false;
            sessionRetryCount = 0;
            loggedIn = true;
            reportNetwork('up');
            populateProfileData(userData);
            saveAccountToDevice(apiToken, userData);
            // Pick up anything that was still queued when the app was last closed,
            // now that we know whose queue it is.
            initializeOutbox();
            fetchConversations();
            initializeSocket();
            fetchNotifications();
            fetchAndRenderMyLounges();
            
            // --- FIX: Hide the loader if we are switching accounts ---
            const loader = document.getElementById('loader');
            if (loader) {
                loader.style.opacity = '0';
                setTimeout(() => loader.style.display = 'none', 500);
            }
            // ---------------------------------------------------------
            
            handleRouting();
        })
        .catch(error => {
            sessionCheckInFlight = false;
            console.error("Session verification check:", error);

            // No status means the request never reached the server: we're offline,
            // not signed out. This used to fall through without routing, leaving a
            // half-drawn login screen with broken images and no explanation --
            // exactly the "the logo is gone" state. Say what's wrong instead; the
            // recheck timer (and retryConnection) resumes the session by itself.
            if (!error.status) {
                reportNetwork('down');
                const loader = document.getElementById('loader');
                if (loader) {
                    loader.style.opacity = '0';
                    setTimeout(() => loader.style.display = 'none', 500);
                }
                return;
            }

            // Anything but an explicit rejection leaves the session alone. This
            // used to fall through doing nothing, which left the login page on
            // screen for a session that was perfectly valid.
            if (error.status !== 401 && error.status !== 403) {
                if (sessionRetryCount < SESSION_RETRY_DELAYS.length) {
                    setTimeout(checkForSavedSession, SESSION_RETRY_DELAYS[sessionRetryCount++]);
                    return;
                }
                // Still failing: say so. The offline page's recheck resumes the
                // session once the server answers again -- see setNetState().
                sessionRetryCount = 0;
                reportNetwork('down');
                hideAppLoader();
                return;
            }

            // Only log out if the server EXPLICITLY rejected the token (401 or 403).
            if (error.status === 401 || error.status === 403) {
                console.warn("Token rejected by server. Logging out.");
                
                // --- FIX: Remove the dead account from the switcher and pre-fill login ---
                const deadToken = localStorage.getItem('apiToken');
                const accounts = getSavedAccounts();
                for (const username in accounts) {
                    if (accounts[username].token === deadToken) {
                        const loginInput = document.getElementById('loginIdentifier');
                        if (loginInput) loginInput.value = username; // Pre-fill login
                        delete accounts[username]; // Remove dead account
                        showToast('Session expired. Please log in again.', 'error');
                    }
                }
                localStorage.setItem('apex_saved_accounts', JSON.stringify(accounts));
                // --- END FIX ---

                localStorage.removeItem('apiToken');
                apiToken = null;
                loggedIn = false;
                
                const loader = document.getElementById('loader');
                if (loader) {
                    loader.style.opacity = '0';
                    setTimeout(() => loader.style.display = 'none', 500);
                }
                
                handleRouting();
            }
        });
    } else {
        handleRouting();
    }
}



function fetchAndRenderProfiles() {
    // Blocking is client-side only, so hand the server our block list to drop
    // before it ranks. The endpoint returns users already ordered by relevance
    // (most-contacted -> cross-follows -> ~1/4 fresh discovery), so we render in
    // the order received rather than re-sorting locally.
    const blocked = (typeof blockedUsers !== 'undefined' && blockedUsers.size)
        ? Array.from(blockedUsers).join(',') : '';
    const url = `${API_BASE_URL}/api/users/recommended?limit=16`
        + (blocked ? `&exclude=${encodeURIComponent(blocked)}` : '');

    fetch(url, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(response => response.json())
    .then(users => {
        const order = [];
        users.forEach(user => {
            profileData[user.username] = {
                ...(profileData[user.username] || {}),
                name: user.fullName,
                username: user.username,
                rank: user.rank,
                profilePicUrl: user.profile_pic,
                account_type: user.account_type,
                "is_birthday": user.is_birthday
            };
            order.push(user.username);
        });
        renderProfiles(order);
    }).catch(error => console.error("Error fetching recommendations:", error));
}


// ===========================================================================
// "People you might know"
// ===========================================================================
// Distinct from the profile row above it, which ranks the whole directory
// (including people you already follow). This row is only people you DON'T
// follow, and every card states the reason it is there -- "Follows you",
// "In Photography Club with you", "Grade 9 at your school".
//
// The server refuses to suggest anyone it can't explain, so this row is short by
// design and hides itself entirely rather than padding out with strangers. It is
// a nudge toward a few real classmates, not a directory to grind through.
// Whether the suggestions may currently be on screen: only with the search box
// empty and nothing rendered below it. The moment anything is typed this is the
// wrong content to be showing.
function searchIsIdle() {
    const input = document.getElementById('mobile-search-input');
    const results = document.getElementById('mobile-search-results-container');
    return !(input && input.value.trim()) && !(results && results.children.length);
}

// Re-evaluates visibility without re-fetching. Called on every keystroke.
function syncSuggestedVisibility() {
    // The trending tags live on the same blank screen and appear and disappear
    // with it, so the one call every keystroke already makes covers both.
    syncTrendingTagsVisibility();

    const block = document.getElementById('search-suggested-block');
    if (!block) return;
    // hasChildNodes: nothing to reveal until a fetch has actually populated it.
    const populated = block.querySelector('.suggested-list')?.children.length > 0;
    block.style.display = (populated && searchIsIdle()) ? '' : 'none';
}

function fetchAndRenderSuggestedUsers() {
    const block = document.getElementById('search-suggested-block');
    const list = block ? block.querySelector('.suggested-list') : null;
    if (!block || !list) return;

    const blocked = (typeof blockedUsers !== 'undefined' && blockedUsers.size)
        ? Array.from(blockedUsers).join(',') : '';
    const url = `${API_BASE_URL}/api/users/suggested?limit=8`
        + (blocked ? `&exclude=${encodeURIComponent(blocked)}` : '');

    fetch(url, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(r => r.json())
    .then(users => {
        if (!Array.isArray(users) || users.length === 0) {
            list.innerHTML = '';
            block.style.display = 'none';
            return;
        }
        renderSuggestedUsers(users, list);
        // Typing may have started while this was in flight.
        syncSuggestedVisibility();
    })
    .catch(error => {
        console.error("Error fetching suggested users:", error);
        list.innerHTML = '';
        block.style.display = 'none';
    });
}

function renderSuggestedUsers(users, list) {
    if (!list) return;
    list.innerHTML = '';

    users.forEach(user => {
        // Cache it so the avatar painter and any later profile visit reuse it.
        profileData[user.username] = {
            ...(profileData[user.username] || {}),
            name: user.fullName,
            username: user.username,
            rank: user.rank,
            profilePicUrl: user.profile_pic,
            account_type: user.account_type,
            is_birthday: user.is_birthday
        };

        // A row, not a card: avatar, two lines of text, and a right-aligned
        // action. The button sits in the same column on every row, which the
        // variable-height cards could never manage.
        const row = document.createElement('div');
        row.className = 'suggested-item';
        row.onclick = () => navigateTo(`/users/${user.username}`);

        row.innerHTML = `
            <div class="profile-pic" data-user-pic-id="${user.username}"></div>
            <div class="suggested-info">
                <p class="suggested-name"></p>
                <p class="suggested-reason"></p>
            </div>
            <button class="suggested-follow-btn" type="button">Follow</button>
        `;

        // textContent, not interpolation: names, schools and lounge names are all
        // user-supplied and land inside the reason string.
        row.querySelector('.suggested-name').textContent = user.fullName || user.username;
        appendRankIcon(row.querySelector('.suggested-name'), user.username, user.rank);
        row.querySelector('.suggested-reason').textContent = user.reason || '';

        const btn = row.querySelector('.suggested-follow-btn');
        btn.onclick = (e) => {
            e.stopPropagation();   // the row itself opens the profile
            followSuggestedUser(user.username, btn);
        };

        list.appendChild(row);
        updateProfilePictures(user.username, row);
    });
}

// The click pulse + star burst that fires when a follow lands. Extracted from the
// profile-page Follow button so the suggestion rows get the identical feedback --
// two follow buttons that celebrate differently read as two different features.
function playFollowBurst(button) {
    button.classList.add('following-anim');
    setTimeout(() => button.classList.remove('following-anim'), 500);

    // Stars are positioned against the offsetParent, which is what offsetTop/Left
    // are measured from -- anchoring to button.parentElement instead puts them in
    // the wrong place whenever the parent isn't itself positioned.
    const host = button.offsetParent || button.parentElement;
    if (!host) return;

    const stars = [];
    for (let i = 0; i < 15; i++) {
        const star = document.createElement('span');
        star.className = 'star';
        star.textContent = '✦';

        star.style.top = `${button.offsetTop + button.offsetHeight / 2}px`;
        star.style.left = `${button.offsetLeft + button.offsetWidth / 2}px`;

        star.style.setProperty('--x', `${(Math.random() - 0.5) * 300}px`);
        star.style.setProperty('--y', `${(Math.random() - 0.5) * 300}px`);

        star.style.color = Math.random() > 0.5 ? 'var(--accent)' : '#275EFE';
        star.style.animationDelay = `${Math.random() * 0.2}s`;

        host.appendChild(star);
        stars.push(star);
    }

    // Remove exactly the nodes we added: a blanket querySelectorAll('.star') on a
    // shared container would also clear a burst another row started meanwhile.
    setTimeout(() => stars.forEach(s => s.remove()), 1000);
}

function followSuggestedUser(username, button) {
    if (button.disabled) return;
    button.disabled = true;

    fetch(`${API_BASE_URL}/api/user/${username}/follow`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (!ok) throw new Error(body.error || 'Could not follow');

        if (!followingList.includes(username)) followingList.push(username);

        // The row stays put and turns into confirmation. Removing it would make
        // the list jump under the finger that just tapped it, and re-fetching would
        // slide a fresh stranger into the gap -- which is the "just one more"
        // pattern this list exists to avoid.
        button.textContent = 'Following';
        button.classList.add('following');
        playFollowBurst(button);
    })
    .catch(err => {
        console.error("Error following suggested user:", err);
        button.disabled = false;
        showToast(err.message || 'Could not follow', 'error');
    });
}

function showMessagesHome() {
    // If we aren't at the root /messages URL yet, go there.
    if (window.location.pathname !== '/messages') {
        navigateTo('/messages');
        return;
    }

    // FIX: Force the mobile UI out of "Chat Mode" and back to "List Mode"
    // This is crucial because handleRouting/popstate doesn't automatically remove this class.
    const container = document.querySelector('.messages-container');
    if (container) container.classList.remove('mobile-chat-active');
    // Same reason as in setMessagesPaneMode: the channel view just closed, so
    // its entry is spent. A no-op when we got here BY that entry being popped,
    // because popstate cleared the flag before routing.
    dropMsgLoungeChannelHistory();

    currentChatRecipient = null;
    // Back on the list. New messages show up on it live, so DM pushes stay quiet
    // here too (the server treats 'messages' like an open thread).
    setActiveView('messages', 'all');
    showPage('messages-page');
    restoreMessagesPaneMode();
}

function fetchAndRenderCircuits() {
    // Recommendation order (host-school -> people you know posting there -> trending,
    // with ~1/4 discovery). This feeds both the Explore row and the full all-circuits
    // grid, which renders from allCircuitsData.
    fetch(`${API_BASE_URL}/api/circuits/recommended?limit=1000`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(circuits => {
        allCircuitsData = circuits; // Store the data globally
        renderExploreCircuits(circuits); // Render the single row on the Explore page
    })
    .catch(error => console.error("Error fetching circuits:", error));
}

function fetchMyProfile() {
    if (!apiToken) return;

    fetch(`${API_BASE_URL}/api/me`, {
        method: 'GET',
        headers: {
            'Authorization': `Bearer ${apiToken}` // Use the token to authenticate
        }
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 200) {
            profileData.me.email = body.email;
            profileData.me.name = body.fullName; // Use fullName for name
            profileData.me.username = body.username;
            profileData.me.school = body.school;
            profileData.me.dob = body.dob;
            profileData.me.bio = body.bio;
            profileData.me.provider = body.provider;
            profileData.me.rank = body.rank;
            profileData.me.permissions = body.permissions || [];
            profileData.me.profilePicUrl = body.profile_pic; // 👈 ADD THIS LINE
            profileData.me.show_birthday = body.show_birthday;
            profileData.me.show_social_stats = body.show_social_stats;
            followingList = body.following || [];

            // Server is the source of truth for blocks (needed so it can withhold
            // pushes for a blocked sender); merge it into the local set used for
            // instant client-side filtering everywhere else.
            (body.blocked_usernames || []).forEach(u => blockedUsers.add(u));
            saveBlockedUsers();

            fetchConversations();

            profileData.me.grade = inferGradeFromEmail(body.email);

            showPage('index-page');
            updateProfilePictures('me');
        } else {
            alert('Error fetching profile: ' + (body.error || 'Unknown error.'));
            handleLogout();
        }
    })
    .catch(err => {
        console.error("Error fetching profile:", err);
        alert("Could not connect to the server to get your profile.");
    });
}


// root lets callers target a node before it is inserted into the document,
// so the avatar is painted in the same frame as the rest of the item.
function updateProfilePictures(userKey, root = document) {

    console.log(`[Debug] updateProfilePictures attempting for userKey: ${userKey}`);
    const user = profileData[userKey];

    if (!user) {
        console.warn(`[Debug] No profileData found for userKey: ${userKey}`);
        return; // Stop if no user object exists
    }
        if (!user.profilePicUrl && !user.profile_pic) {
            console.warn(`[Debug] No profilePicUrl or profile_pic found for userKey: ${userKey}`, user);
            // Don't return here, let it use the default avatar
        }

    if (!user) {
        console.warn(`updateProfilePictures called for unknown userKey: ${userKey}`);
        return;
    }

    const profilePicUrl = user.profilePicUrl || user.profile_pic;
    console.log(`[Debug] Found URL for ${userKey}:`, profilePicUrl);
    const rank = user.rank;
    const pictureElements = root.querySelectorAll(`[data-user-pic-id="${userKey}"]`);

    pictureElements.forEach(picElement => {
        console.log(`[Debug] Setting --avatar-image for element associated with ${userKey} to:`, profilePicUrl ? `url(${profilePicUrl})` : 'removed (fallback)');
        if (profilePicUrl) {
            picElement.style.setProperty('--avatar-image', `url(${profilePicUrl})`);
        } else {
            // This correctly removes the variable so the CSS fallback to the default avatar works.
            picElement.style.removeProperty('--avatar-image');
        }

        picElement.classList.remove('rank-admin', 'rank-moderator');
        if (rank === 'admin') {
            picElement.classList.add('rank-admin');
        } else if (rank === 'moderator') {
            picElement.classList.add('rank-moderator');
        }

        picElement.classList.toggle('birthday-user', user.is_birthday === true && user.show_birthday === true);

    });
}

function showValidationError(inputId, message) {
    const inputElement = document.getElementById(inputId);
    if (!inputElement) return;

    // Remove any old error message first
    hideValidationError(inputId);

    const errorElement = document.createElement('div');
    errorElement.className = 'form-error-message';
    errorElement.id = `error-${inputId}`;
    errorElement.textContent = message;

    // Insert after the input's direct parent if it's a special container, otherwise after the input itself
    const parentContainer = inputElement.closest('.form-field-wrapper, .tos-container');
    const signupField = inputElement.closest('.signup-field');

    if (signupField) {
        // The whole field turns red -- border, icon, and label -- so the message
        // is never the only thing pointing at what went wrong.
        signupField.classList.remove('is-valid');
        signupField.classList.add('has-error');
        signupField.appendChild(errorElement);
        signupField.classList.remove('shake');
        void signupField.offsetWidth; // restart the animation on a repeat error
        signupField.classList.add('shake');
    } else if (parentContainer) {
        parentContainer.insertAdjacentElement('afterend', errorElement);
        parentContainer.closest('.agreements-card')?.classList.add('has-error');
    } else {
        inputElement.insertAdjacentElement('afterend', errorElement);
    }
}

/**
    * Hides the validation error message for a specific input field.
    * @param {string} inputId The ID of the input element.
    */
function hideValidationError(inputId) {
    const errorElement = document.getElementById(`error-${inputId}`);
    if (errorElement) {
        errorElement.remove();
    }
    const inputElement = document.getElementById(inputId);
    inputElement?.closest('.signup-field')?.classList.remove('has-error', 'shake');

    // The agreements card only stays red while one of its three boxes is still
    // unticked, so re-check the siblings before clearing it.
    const card = inputElement?.closest('.agreements-card');
    if (card && !card.querySelector('.form-error-message')) {
        card.classList.remove('has-error', 'shake');
    }
}

/**
    * Clears all validation messages within a given form or page.
    * @param {string} containerId The ID of the parent container (e.g., 'signup-page').
    */
function clearAllValidationErrors(containerId) {
    const container = document.getElementById(containerId);
    if (container) {
        container.querySelectorAll('.form-error-message').forEach(el => el.remove());
        container.querySelectorAll('.signup-field, .agreements-card').forEach(el => {
            el.classList.remove('has-error', 'shake');
        });
        // Any summary banner inside this container, whichever page it belongs to.
        container.querySelectorAll('.signup-summary').forEach(box => { box.hidden = true; });
    }
}

/**
 * The banner above the Register button. A long form scrolls, so a field that
 * failed can sit off-screen; this lists every problem in one place and each
 * entry jumps to the field it came from.
 */
function showSignupErrorSummary(problems, boxId = 'signup-error-summary') {
    const box = document.getElementById(boxId);
    if (!box || !problems.length) return;

    box.querySelector('.signup-summary-title').textContent =
        problems.length === 1
            ? 'One thing needs fixing before you can continue:'
            : `${problems.length} things need fixing before you can continue:`;

    const list = box.querySelector('.signup-summary-list');
    list.innerHTML = '';
    problems.forEach(({ inputId, message }) => {
        const li = document.createElement('li');
        const link = document.createElement('a');
        link.textContent = message;
        link.href = '#';
        link.addEventListener('click', (e) => {
            e.preventDefault();
            focusSignupField(inputId);
        });
        li.appendChild(link);
        list.appendChild(li);
    });

    box.hidden = false;
}

function hideSignupErrorSummary(boxId = 'signup-error-summary') {
    const box = document.getElementById(boxId);
    if (box) box.hidden = true;
}

function focusSignupField(inputId) {
    const el = document.getElementById(inputId);
    if (!el) return;
    const field = el.closest('.signup-field, .tos-container') || el;
    field.scrollIntoView({ behavior: 'smooth', block: 'center' });
    // A hidden input (the DOB) can't take focus -- move to its visible trigger.
    const target = el.type === 'hidden'
        ? field.querySelector('button, input:not([type="hidden"]), select')
        : el;
    setTimeout(() => target?.focus({ preventScroll: true }), 320);
}

/**
 * Live per-field validation. Each rule returns null when the value is fine, or
 * the exact sentence the user should read. These are the same rules handleSignup
 * enforces on submit -- kept in one table so the two can never disagree.
 */
const SIGNUP_FIELD_RULES = {
    signupFullName: (v) => {
        const val = v.trim();
        if (!val) return 'Full name is required.';
        // Mirrors FULL_NAME_MAX on the server. Long enough for any real name;
        // past it the byline stops fitting the surfaces that draw it.
        if (val.length > 50) return `Too long -- 50 characters max (you have ${val.length}).`;
        return null;
    },
    signupUsername: (v) => {
        const val = v.trim();
        if (!val) return 'Pick a username -- this is your @mention handle.';
        if (/[A-Z]/.test(val)) return 'Usernames are lowercase only. Try "' + val.toLowerCase() + '".';
        if (val.length < 4) return `Too short -- usernames need at least 4 characters (you have ${val.length}).`;
        if (val.length > 20) return `Too long -- 20 characters max (you have ${val.length}).`;
        const bad = [...new Set(val.split('').filter(c => !/[a-z0-9!._*-]/.test(c)))];
        if (bad.length) {
            return `"${bad.join('", "')}" can't be used. Only lowercase letters, numbers, and . _ - * ! are allowed.`;
        }
        return null;
    },
    signupSchool: (v) => (v ? null : 'Please select your school from the list.'),
    signupEmail: (v) => {
        const val = v.trim();
        if (!val) return 'Email is required -- your verification code is sent there.';
        if (!/\S+@\S+\.\S+/.test(val)) return 'That doesn\'t look like an email address. It should look like you@yourschool.edu.';
        return null;
    },
    signupPassword: (v) => {
        if (!v) return 'Password is required.';
        if (v.length < MIN_PASSWORD_LENGTH) return `Passwords need at least ${MIN_PASSWORD_LENGTH} characters (you have ${v.length}).`;
        return null;
    },
    signupConfirmPassword: (v) => {
        if (!v) return 'Please type your password a second time.';
        if (v !== document.getElementById('signupPassword').value) return 'These two passwords don\'t match.';
        return null;
    },
    signupSubject: (v) => (v.trim() ? null : 'Primary subject is required.'),
};

/**
 * Checks one field and paints its state. `silent` suppresses the red message
 * while the user is still typing -- we only clear a stale error mid-keystroke
 * and save the complaint for when they leave the field.
 */
function validateSignupField(inputId, { silent = false } = {}) {
    const input = document.getElementById(inputId);
    const rule = SIGNUP_FIELD_RULES[inputId];
    if (!input || !rule) return true;

    const field = input.closest('.signup-field');
    // Fields hidden for this account type (subject, DOB) don't get judged.
    if (field && field.style.display === 'none') return true;

    const message = rule(input.value);
    if (message) {
        hideValidationError(inputId);
        field?.classList.remove('is-valid');
        if (!silent) showValidationError(inputId, message);
        return false;
    }

    hideValidationError(inputId);
    if (input.value.trim()) field?.classList.add('is-valid');
    return true;
}

/** 0-4 strength score, used only to give the password field some feedback. */
function scoreSignupPassword(pw) {
    if (pw.length < MIN_PASSWORD_LENGTH) return { level: 0, label: 'Too short' };
    let score = 1;
    if (pw.length >= 8) score++;
    if (pw.length >= 12) score++;
    if (/[a-z]/.test(pw) && /[A-Z]/.test(pw)) score++;
    if (/\d/.test(pw)) score++;
    if (/[^A-Za-z0-9]/.test(pw)) score++;
    const level = Math.min(4, Math.max(1, Math.round(score * 4 / 6)));
    return { level, label: ['', 'Weak', 'Okay', 'Good', 'Strong'][level] };
}

function updateSignupPasswordMeter() {
    const input = document.getElementById('signupPassword');
    const meter = document.getElementById('signup-pw-meter');
    if (!input || !meter) return;

    if (!input.value) {
        meter.hidden = true;
        return;
    }
    const { level, label } = scoreSignupPassword(input.value);
    meter.hidden = false;
    meter.dataset.level = String(level);
    meter.querySelector('.pw-meter-label').textContent = label;
}

/**
 * Wires the signup page once. Validation fires on blur (so we never nag
 * mid-word) and clears on input (so a corrected field goes green immediately).
 */
function initSignupFormInteractions() {
    const page = document.getElementById('signup-page');
    if (!page || page.dataset.validationWired === 'true') return;
    page.dataset.validationWired = 'true';

    Object.keys(SIGNUP_FIELD_RULES).forEach(id => {
        const input = document.getElementById(id);
        if (!input) return;

        const eventName = input.tagName === 'SELECT' ? 'change' : 'blur';
        input.addEventListener(eventName, () => validateSignupField(id));
        input.addEventListener('input', () => {
            hideSignupErrorSummary();
            validateSignupField(id, { silent: true });
            if (id === 'signupPassword') {
                updateSignupPasswordMeter();
                // Re-check the confirmation so it doesn't keep claiming a
                // mismatch the user already resolved by editing this box.
                if (document.getElementById('signupConfirmPassword').value) {
                    validateSignupField('signupConfirmPassword', { silent: true });
                }
            }
        });
    });

    page.querySelectorAll('.tos-container input[type="checkbox"]').forEach(box => {
        box.addEventListener('change', () => {
            if (box.checked) hideValidationError(box.id);
            hideSignupErrorSummary();
        });
    });

    page.querySelectorAll('.shell-reveal').forEach(btn => {
        btn.addEventListener('click', () => {
            const target = document.getElementById(btn.dataset.target);
            if (!target) return;
            const showing = target.type === 'text';
            target.type = showing ? 'password' : 'text';
            btn.querySelector('i').className = showing ? 'fas fa-eye' : 'fas fa-eye-slash';
            btn.setAttribute('aria-label', showing ? 'Show password' : 'Hide password');
        });
    });
}

function handleLogin() {
    requestNotificationPermission();
    clearAllValidationErrors('login-page');
    const identifier = document.getElementById('loginIdentifier').value;
    const password = document.getElementById('loginPassword').value;

    if (!identifier || !password) {
        showValidationError('loginPassword', 'Please enter your username/email and password.');
        return;
    }

    const loginBtn = document.querySelector('#login-page button');
    const originalText = loginBtn.textContent;
    loginBtn.textContent = "Logging in...";
    loginBtn.disabled = true;

    fetch(`${API_BASE_URL}/api/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: identifier, password: password }),
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        loginBtn.textContent = originalText;
        loginBtn.disabled = false;

        if (status === 200 && body.multiple_accounts) {
            showAccountSelectionModal(body.accounts, password);
            return;
        }

        if (status === 200 && body.token && body.user) {
            localStorage.setItem('apiToken', body.token);
            apiToken = body.token;
            loggedIn = true;
            saveAccountToDevice(body.token, body.user);
            
            // --- CRASH PROOFING ---
            // We wrap this in try-catch so if a helper fails, we STILL navigate.
            try {
                populateProfileData(body.user);

                // Anything this account left queued last session goes out now.
                initializeOutbox();

                if (body.user.force_password_change) {
                    document.getElementById('force-password-modal').classList.remove('hidden');
                    return; 
                }

                // These might be failing, but we won't let them stop the login
                fetchConversations();
                initializeSocket();
                fetchNotifications();
            } catch (e) {
                console.warn("Post-login setup error (ignoring to force redirect):", e);
            }
            // ----------------------

            // FORCE REDIRECT
            navigateTo('/');

            // Signing in cancels a pending account deletion server-side. Say so
            // -- otherwise the only signal that the account was rescued is that
            // it still works, which is indistinguishable from nothing happening.
            if (body.deletion_cancelled) {
                setTimeout(() => showToast(
                    'Welcome back — your scheduled account deletion has been cancelled.',
                    'success'), 600);
            }

            // First-run notification ask. Delayed so it lands after the app has
            // settled rather than on top of the redirect.
            setTimeout(() => maybeShowPushSoftAsk(), 1500);
        } else {
            const error = body.error || 'Login failed.';
            showValidationError('loginPassword', error);
        }
    })
    .catch(error => {
        console.error('Login network error:', error);
        alert('The server connection failed. Please try again.');
        loginBtn.textContent = originalText;
        loginBtn.disabled = false;
    });
}

function handleLogout() {
    if (profileData.me && profileData.me.username) {
        const accounts = getSavedAccounts();
        delete accounts[profileData.me.username];
        localStorage.setItem('apex_saved_accounts', JSON.stringify(accounts));
    }
    // With this device's push endpoint, so the server stops pushing this account's
    // notifications to a phone it has been signed out of. Captured first: the
    // token is gone by the time anything below runs.
    const logoutToken = apiToken;
    currentPushEndpoint().then(endpoint => fetch(`${API_BASE_URL}/api/logout`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${logoutToken}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ endpoint })
    })).finally(() => {
        if (socket) {
            socket.disconnect();
            socket = null;

        }
        localStorage.removeItem('apiToken');
        apiToken = null;
        loggedIn = false;
        profileData.me = {}; // Clear user data
        // The service worker keeps viewed media, DM and lounge files included; the
        // next person to sign in on this device must not be served them.
        if (window.caches) caches.delete('apex-media').catch(() => {});
        navigateTo('/login');
    });
}

function formatPostTimestamp(date) {
    if (!(date instanceof Date) || isNaN(date)) return '';
    // Example format: Oct 19, 2025, 10:30 PM
    return date.toLocaleString('en-US', {
        month: 'short', day: 'numeric', year: 'numeric',
        hour: 'numeric', minute: '2-digit', hour12: true
    });
}

function formatDateSeparator(dateString) {
    const today = new Date();
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    
    const messageDate = new Date(dateString);

    if (messageDate.toDateString() === today.toDateString()) {
        return 'Today';
    }
    if (messageDate.toDateString() === yesterday.toDateString()) {
        return 'Yesterday';
    }
    
    // Fallback for older dates
    return messageDate.toLocaleDateString('en-US', {
        month: 'long',
        day: 'numeric',
        year: 'numeric'
    });
}

function resendVerificationCode() {
    if (!pendingSignupData || !pendingSignupData.email) {
        showToast('Could not retrieve email to resend code. Please go back.', 'error');
        return;
    }
    // Reuse the sendVerificationCode function
    showToast('Resending verification code...', 'success'); // Give user feedback
    sendVerificationCode(pendingSignupData.email, pendingSignupData.fullName, null); // Pass null for button as we're not on signup page
}

function populateProfileData(userData) {
    // --- 1. CLEANUP STATE FOR ACCOUNT SWITCHER ---
    messageHistory = {};
    unreadSenders.clear();
    Object.keys(profileData).forEach(key => {
        if (key !== 'me') delete profileData[key];
    });
    // ---------------------------------------------

    console.log("[Debug] Populating profile data with:", userData);
    profileData.me.id = userData.id;
    profileData.me.email = userData.email;
    profileData.me.name = userData.fullName;
    profileData.me.username = userData.username;
    profileData.me.school = userData.school;
    profileData.me.dob = userData.dob;
    profileData.me.bio = userData.bio;
    profileData.me.provider = userData.provider;
    profileData.me.rank = userData.rank;
    profileData.me.permissions = userData.permissions || [];
    profileData.me.profilePicUrl = userData.profile_pic;
    // Privacy toggles. Missing them here is not harmless: editProfile() renders the
    // switches from this object, so an absent field drew an ON setting as OFF, and
    // saving from that form then wrote the OFF back to the database.
    profileData.me.show_birthday = userData.show_birthday;
    profileData.me.show_social_stats = userData.show_social_stats;
    followingList = userData.following || [];

    profileData.me.grade = inferGradeFromEmail(userData.email);
    updateProfilePictures('me');

    // Accounts that predate the guardian-consent step and are still under 14 are
    // asked here, on every hydration path, rather than at one call site that a
    // future login route could forget to copy.
    maybeShowGuardianConsentModal(userData);

    // Close notifications for anything read while the app was closed -- on
    // another device, or before a restart. Same reasoning as above: every
    // hydration path lands here, so a cold start and a sign-in both get it.
    setTimeout(reconcilePushNotifications, 2000);
}

function fetchConversations() {
    fetch(`${API_BASE_URL}/api/dm/conversations?t=${Date.now()}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(convos => {
        unreadSenders.clear();

        // The server owns the pin list. Rebuild it here (most recently pinned first)
        // so a chat pinned on another device shows up pinned on this one.
        const serverPins = convos
            .filter(c => c.pinned && c.pinned_at)
            .sort((a, b) => new Date(b.pinned_at) - new Date(a.pinned_at))
            .map(c => c.other_user.username);
        pinnedChats = serverPins;
        savePinnedChats();

        convos.forEach(convo => {
            const username = convo.other_user.username;

            if (!profileData[username]) {
                profileData[username] = {
                    name: convo.other_user.fullName,
                    ...convo.other_user
                };
            }

            // An entry may already exist from a profile visit, which seeds a
            // placeholder name -- the conversation payload is authoritative.
            if (convo.other_user.fullName) {
                profileData[username].name = convo.other_user.fullName;
            }

            profileData[username].lastMessage = convo.last_message;
            // --- THE FIX: Store time in profile, NOT as a fake chat bubble ---
            profileData[username].lastMessageTime = new Date(convo.timestamp);

            if (convo.unread_count > 0) {
                unreadSenders.add(username);
            }
        });

        updateNotificationBadge(); 
        renderChatList(); 
        updatePageTitleCount();
    })
    .catch(error => console.error("Could not fetch conversations:", error));
}



function sendVerificationCode(email, name, signupButton) {
    generatedVerificationCode = Math.floor(100000 + Math.random() * 900000).toString(); // Generate 6-digit code
    console.log("Generated Verification Code:", generatedVerificationCode); // For testing

    // --- THIS IS THE FIX ---
    const templateParams = {
        email: email, // Use 'email' to match your EmailJS template
        to_name: name || 'User',
        verification_code: generatedVerificationCode
    };
    // --- END OF FIX ---

    // Use your NEW Service ID and Template ID for Verification
    const serviceID = 'service_2x7d4jf';
    const templateID = 'template_kxxodjk'; // Corrected ID

    // Show loading state on the calling button while sending. The label is
    // restored rather than hard-coded back to "Register", because this is also
    // reached from the guardian-consent step, whose button says something else.
    const originalLabel = signupButton ? signupButton.textContent : null;
    if (signupButton) {
        signupButton.textContent = 'Sending Code...';
        signupButton.disabled = true;
    }

    // EmailJS is fetched and init'd on demand -- signup is the only thing that
    // sends mail, so the library no longer loads for everyone at boot.
    ensureEmailJs()
        .then(() => emailjs.send(serviceID, templateID, templateParams))
        .then(function(response) {
            console.log('Verification Email SUCCESS!', response.status, response.text);
            document.getElementById('verify-email-display').textContent = email; // Show email on verify page
            showPage('verify-page'); // Go to verification page
        }, function(error) {
            console.error('FAILED to send verification email...', error);
            // Display the specific error from EmailJS
            showToast(`Failed to send verification email. Error: ${error.text || 'Check console.'}`, 'error');
            // Re-enable the calling button if sending fails
            if (signupButton) {
                signupButton.disabled = false;
                signupButton.textContent = originalLabel || 'Register';
            }
        });
}

function verifyCode() {
    const enteredCode = document.getElementById('verificationCode').value.trim();

    if (!enteredCode) {
        alert('Please enter a code to continue.');
        return;
    }

    // For now, we accept any code and treat it as a success.
    showToast('Verification successful! Please log in with your new account.','success');
    showPage('login-page');
}

function renderProfiles(orderedKeys) {
    const profileList = document.getElementById('profile-list');
    profileList.innerHTML = '';

    // When called with a server-ranked list, honour that exact order (it's already
    // filtered + de-duped). Otherwise fall back to the cached-profile keys.
    let userKeys;
    if (Array.isArray(orderedKeys)) {
        userKeys = orderedKeys.filter(key =>
            key && key !== 'me' && key !== 'ANNOUNCEMENTS' && key !== profileData.me.username
        );
    } else {
        userKeys = Object.keys(profileData).filter(key =>
            key !== 'me' && key !== 'ANNOUNCEMENTS' && key !== profileData.me.username
        );
    }

    // Cap the row at 16 users
    userKeys.slice(0, 16).forEach(key => {
        const user = profileData[key];
        if (!user || !user.name) return;

        const profileItem = document.createElement('a');
        profileItem.className = 'profile-item';
        // --- THIS IS THE FIX ---
        profileItem.href = `/users/${key}`;
        profileItem.onclick = (e) => {
            e.preventDefault();
            navigateTo(`/users/${key}`);
        };
        // --- END FIX ---

        let displayName = user.name;
        if (displayName.length > 7) {
            displayName = displayName.substring(0, 7) + "...";
        }

        profileItem.innerHTML = `
            <div class="profile-pic" data-user-pic-id="${key}"></div>
            <p class="profile-name">${displayName} ${rankIconFor(key, user.rank)}</p>
        `;

        profileList.appendChild(profileItem);
        updateProfilePictures(key);
    });
}

function renderAllProfiles() {
    const grid = document.getElementById('all-profiles-grid');
    grid.innerHTML = '<p style="text-align: center;">Loading profiles...</p>'; // Show a loading state

    // 1. Fetch the FULL directory in recommendation order (same algorithm as the
    // Home row, just uncapped). Hand the server our client-side block list to drop.
    const blocked = (typeof blockedUsers !== 'undefined' && blockedUsers.size)
        ? Array.from(blockedUsers).join(',') : '';
    const url = `${API_BASE_URL}/api/users/recommended?limit=1000`
        + (blocked ? `&exclude=${encodeURIComponent(blocked)}` : '');
    fetch(url, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(users => {
        grid.innerHTML = ''; // Clear loading message

        if (users.length === 0) {
            grid.innerHTML = '<p style="text-align: center;">No other users found.</p>';
            return;
        }

        // 2. Iterate over the FRESH list from the API
        users.forEach(user => {
            // 3. Add to profileData cache (good practice)
            if (!profileData[user.username]) {
                profileData[user.username] = { 
                    name: user.fullName, 
                    ...user 
                };
            } else {
                // Update existing cache entry
                Object.assign(profileData[user.username], { name: user.fullName, ...user });
            }

            // 4. Render the card (same logic as before)
            const card = document.createElement('div');
            card.className = 'profile-grid-card';
            card.onclick = () => navigateTo(`/users/${user.username}`);

            const tagHtml = getAccountTypeTag(user.account_type);
            card.innerHTML = `
                <div class="profile-pic" data-user-pic-id="${user.username}"></div>
                <p class="profile-card-name"><span class="profile-card-name-text">${user.fullName}</span>${rankIconFor(user.username, user.rank)}${tagHtml}</p>
                <p class="profile-card-username">@${user.username}</p>
            `;
            grid.appendChild(card);
            
            // 5. Update the picture
            updateProfilePictures(user.username);
        });
    })
    .catch(error => {
        console.error("Error fetching all profiles:", error);
        grid.innerHTML = '<p style="text-align: center; color: red;">Could not load profiles.</p>';
    });
}

// The images and stickers that sit either side of the one currently magnified,
// so a swipe can page through them (see attachSwipeNavigation). Captured as URLs
// rather than elements because the chat re-renders while the viewer is open and
// would leave us holding detached nodes.
let imageViewerItems = [];
let imageViewerIndex = -1;

// Every magnifiable image in the same conversation as `sourceEl`, in the order
// they appear. Falls back to a single-item group when the caller didn't tell us
// where the image came from, which just means swiping does nothing.
function buildImageViewerGroup(sourceEl, imageUrl) {
    const container = sourceEl && sourceEl.closest('.chat-body');
    if (!container) return { items: [imageUrl], index: 0 };

    const images = Array.from(container.querySelectorAll('img.chat-media'));
    const index = images.indexOf(sourceEl);
    if (index === -1) return { items: [imageUrl], index: 0 };

    return { items: images.map(el => el.getAttribute('src')), index };
}

function renderImageViewer(imageUrl) {
    const img = document.getElementById('image-viewer-content');
    const downloadBtn = document.getElementById('image-viewer-download');

    img.src = imageUrl;
    syncImageViewerArrows();

    // Stickers aren't the user's own image to save, so hide the download button
    // for them. Stickers are served from /api/sticker/<id>/image; real user
    // uploads come from /apex_media/... .
    const isSticker = imageUrl.includes('/api/sticker/');
    if (downloadBtn) downloadBtn.style.display = isSticker ? 'none' : '';
}

function openImageViewer(imageUrl, sourceEl) {
    const modal = document.getElementById('image-viewer-modal');
    const img = document.getElementById('image-viewer-content');

    const group = buildImageViewerGroup(sourceEl, imageUrl);
    imageViewerItems = group.items;
    imageViewerIndex = group.index;

    resetSwipeNavPane(img);
    renderImageViewer(imageUrl);

    modal.classList.remove('hidden');
    pushModalHistory('image-viewer-modal', closeImageViewer);

    // Optional: Add Escape key functionality to close the modal
    window.addEventListener('keydown', handleEscKey);
}

// An arrow that goes nowhere is worse than no arrow: it invites the click and then
// does nothing. Recomputed on every render because the group is per-conversation and
// the ends of it move as you page.
function syncImageViewerArrows() {
    const prev = document.getElementById('image-viewer-prev');
    const next = document.getElementById('image-viewer-next');
    // Left as the stylesheet found it rather than set to 'block': whether these are
    // shown AT ALL is the (hover: none) rule's decision, and writing an inline
    // display here would override it and put the arrows back on every phone.
    if (prev) prev.style.display = canStepImageViewer(-1) ? '' : 'none';
    if (next) next.style.display = canStepImageViewer(1) ? '' : 'none';
}

// dir is +1 for the next image, -1 for the previous one.
function canStepImageViewer(dir) {
    const target = imageViewerIndex + dir;
    return target >= 0 && target < imageViewerItems.length;
}

function stepImageViewer(dir) {
    if (!canStepImageViewer(dir)) return;
    imageViewerIndex += dir;
    renderImageViewer(imageViewerItems[imageViewerIndex]);
}

function closeImageViewer() {
    const modal = document.getElementById('image-viewer-modal');
    const img = document.getElementById('image-viewer-content');

    modal.classList.add('hidden');
    img.src = ''; // Clear the image source
    resetSwipeNavPane(img);
    img.style.animation = ''; // let the open animation play again next time
    imageViewerItems = [];
    imageViewerIndex = -1;
    window.removeEventListener('keydown', handleEscKey);
    popModalHistory('image-viewer-modal');
}

function handleEscKey(event) {
    if (event.key === 'Escape') {
        closeImageViewer();
    }
}

// --- Paging the viewers from the keyboard ------------------------------------
//
// Both viewers page with a horizontal swipe, which is the whole gesture on a phone
// and on a bare iPad. Neither had a keyboard equivalent, so an iPad with a keyboard
// -- where the arrow keys are right there and every other image viewer on the
// machine answers them -- could only page by reaching up and dragging the screen.
//
// Not gated on hasHardwareKeyboard(): a keypress IS the evidence of a keyboard, so
// gating on the latch would only add a way for the first press of a session to do
// nothing. On a desktop this is the same behaviour, which it should always have had.
//
// One listener for both, keyed on which modal is actually open, because they are
// mutually exclusive and two listeners fighting over the same keystroke is how the
// post behind an image viewer ends up paging as well.
function isModalOpen(id) {
    const el = document.getElementById(id);
    return !!el && !el.classList.contains('hidden');
}

function handleViewerArrowKeys(event) {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    // A field has the arrow keys while it is focused; they move the caret.
    if (isTextEntryElement(document.activeElement)) return;
    if (event.metaKey || event.ctrlKey || event.altKey) return;
    // A comment thread open over the post: paging behind it would leave the
    // sheet showing one post's comments on top of another.
    if (isModalOpen('post-comments-modal')) return;

    const dir = event.key === 'ArrowRight' ? 1 : -1;

    if (isModalOpen('image-viewer-modal')) {
        if (!canStepImageViewer(dir)) return;
        event.preventDefault();
        stepImageViewer(dir);
        return;
    }

    if (isModalOpen('post-modal')) {
        const target = currentPostIndexInModal + dir;
        if (target < 0 || target >= getModalPosts().length) return;
        event.preventDefault();
        showPostModal(target);
    }
}

// Save the currently magnified image to the device. Fetch it as a blob and click
// a synthetic <a download> so the browser saves it instead of navigating to it --
// a plain href would just open the image on Android. Falls back to opening the
// image in a new tab if the fetch is blocked for any reason.
async function downloadViewerImage() {
    const img = document.getElementById('image-viewer-content');
    const url = img && img.src;
    if (!url) return;

    // Build a sensible filename from the URL path.
    let name = (url.split('/').pop() || 'image').split('?')[0] || 'apex-image';
    if (!name.includes('.')) name += '.jpg';

    try {
        const res = await fetch(url);
        const blob = await res.blob();
        const objectUrl = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = objectUrl;
        a.download = name;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
    } catch (e) {
        console.warn('Image download fell back to open-in-tab', e);
        window.open(url, '_blank', 'noopener');
    }
}

// Magnified profile picture viewer. Painted as a CSS background on a plain div
// (same mechanism the small avatars already use via --avatar-image) instead of
// an <img>, so there's no element for the browser's native "Save image" /
// "Copy image" context menu to attach to -- see .profile-pic-viewer-content.
function openProfilePicViewer(userKey) {
    const modal = document.getElementById('profile-pic-viewer-modal');
    const content = document.getElementById('profile-pic-viewer-content');
    const user = profileData[userKey];
    const picUrl = user && (user.profilePicUrl || user.profile_pic);

    if (picUrl) {
        content.style.setProperty('--avatar-image', `url(${picUrl})`);
    } else {
        content.style.removeProperty('--avatar-image');
    }

    modal.classList.remove('hidden');
    pushModalHistory('profile-pic-viewer-modal', closeProfilePicViewer);
    window.addEventListener('keydown', handleProfilePicViewerEscKey);
}

function closeProfilePicViewer() {
    document.getElementById('profile-pic-viewer-modal').classList.add('hidden');
    window.removeEventListener('keydown', handleProfilePicViewerEscKey);
    popModalHistory('profile-pic-viewer-modal');
}

function handleProfilePicViewerEscKey(event) {
    if (event.key === 'Escape') closeProfilePicViewer();
}

// --- Swipe navigation for full-screen viewers (mobile) ---------------------
// The circuit post modal and the magnified image viewer both page through a
// list with the < / > buttons on desktop. Those buttons are cramped on a phone,
// so the same navigation is driven by a horizontal swipe: the content tracks
// the finger, and past the commit threshold it slides out while its neighbour
// slides in from the other side. Swiping toward an end with nothing left
// rubber-bands back instead of moving.
const SWIPE_NAV_LOCK_PX = 12;            // travel before an axis is committed to
const SWIPE_NAV_COMMIT_PX = 55;          // travel that counts as "go to the next one"
const SWIPE_NAV_EDGE_RESISTANCE = 0.25;  // drag damping when there is nothing there
const SWIPE_NAV_SLIDE_MS = 190;

function resetSwipeNavPane(pane) {
    if (!pane) return;
    pane.style.transition = '';
    pane.style.transform = '';
    pane.style.opacity = '';
}

// config: { getPane(), canStep(dir), step(dir) } where dir is +1 for next, -1 for
// previous. getPane returns the element that slides; it is re-read after each
// step in case the content was rebuilt rather than updated in place.
function attachSwipeNavigation(surface, config) {
    if (!surface) return;

    let startX = 0;
    let startY = 0;
    let axis = null;      // null = undecided, 'x' = ours, 'y' = hand it back
    let tracking = false;
    let animating = false;
    let pane = null;

    const surfaceWidth = () => surface.clientWidth || window.innerWidth || 1;

    function slide(dir) {
        animating = true;
        const w = surfaceWidth();
        const outgoing = pane;

        outgoing.style.transition = `transform ${SWIPE_NAV_SLIDE_MS}ms ease-in, opacity ${SWIPE_NAV_SLIDE_MS}ms ease-in`;
        outgoing.style.transform = `translateX(${dir === 1 ? -w : w}px)`;
        outgoing.style.opacity = '0';

        setTimeout(() => {
            config.step(dir);
            const incoming = config.getPane() || outgoing;

            // Park the new content off-screen on the far side, then animate it
            // home. The reflow is what stops the browser from collapsing both
            // writes into a single frame where nothing appears to move.
            incoming.style.transition = 'none';
            incoming.style.transform = `translateX(${dir === 1 ? w : -w}px)`;
            incoming.style.opacity = '0';
            void incoming.offsetWidth;

            incoming.style.transition = `transform ${SWIPE_NAV_SLIDE_MS}ms ease-out, opacity ${SWIPE_NAV_SLIDE_MS}ms ease-out`;
            incoming.style.transform = 'translateX(0)';
            incoming.style.opacity = '1';

            setTimeout(() => {
                resetSwipeNavPane(incoming);
                animating = false;
            }, SWIPE_NAV_SLIDE_MS);
        }, SWIPE_NAV_SLIDE_MS);
    }

    surface.addEventListener('touchstart', (event) => {
        if (animating || tracking) return;
        if (event.touches.length !== 1) return;   // a pinch is not a swipe
        // isTouchUi, not isMobileDevice: an iPad's user agent says Macintosh, and
        // paging a post with the arrows is exactly what a finger should not have
        // to do. See the touch-capability block near isMobileDevice().
        if (!isTouchUi()) return;

        // A carousel inside the post owns sideways drags that start on it.
        // Without this, one swipe moved both: the strip scrolled to the next
        // photo AND the surface paged to the next post. Inside the strip a
        // swipe means "next photo"; anywhere else on the post it means "next
        // post". A lone picture is a plain <img>, not a strip, so it still
        // pages the post.
        if (event.target.closest && event.target.closest('.post-gallery-track')) return;

        pane = config.getPane();
        if (!pane) return;

        tracking = true;
        axis = null;
        startX = event.touches[0].clientX;
        startY = event.touches[0].clientY;
        pane.style.transition = 'none';
        // Both panes open with a zoomIn keyframe animation, and a running
        // animation outranks the inline transform we are about to set. Killing it
        // is safe: the close handlers restore it for the next open.
        pane.style.animation = 'none';
    }, { passive: true });

    // Non-passive: once the drag is horizontal we own it and cancel the browser's
    // own scrolling.
    surface.addEventListener('touchmove', (event) => {
        if (!tracking) return;
        if (event.touches.length !== 1) {         // turned into a pinch mid-drag
            tracking = false;
            resetSwipeNavPane(pane);
            return;
        }

        const dx = event.touches[0].clientX - startX;
        const dy = event.touches[0].clientY - startY;

        if (!axis) {
            if (Math.abs(dx) < SWIPE_NAV_LOCK_PX && Math.abs(dy) < SWIPE_NAV_LOCK_PX) return;
            // Vertical wins ties, so scrolling a long post still works.
            axis = Math.abs(dx) > Math.abs(dy) ? 'x' : 'y';
            if (axis === 'y') {
                tracking = false;
                resetSwipeNavPane(pane);
                return;
            }
        }

        if (event.cancelable) event.preventDefault();
        const room = config.canStep(dx < 0 ? 1 : -1);
        pane.style.transform = `translateX(${room ? dx : dx * SWIPE_NAV_EDGE_RESISTANCE}px)`;
    }, { passive: false });

    surface.addEventListener('touchend', (event) => {
        if (!tracking) return;
        tracking = false;

        if (axis !== 'x') {
            resetSwipeNavPane(pane);
            return;
        }

        // Both viewers close on a background click, and a swipe that ends over
        // the backdrop would otherwise synthesise one.
        if (event.cancelable) event.preventDefault();

        const touch = event.changedTouches && event.changedTouches[0];
        const dx = touch ? touch.clientX - startX : 0;
        const dir = dx < 0 ? 1 : -1;

        if (Math.abs(dx) < SWIPE_NAV_COMMIT_PX || !config.canStep(dir)) {
            pane.style.transition = `transform ${SWIPE_NAV_SLIDE_MS}ms ease-out`;
            pane.style.transform = 'translateX(0)';
            return;
        }

        slide(dir);
    }, { passive: false });

    surface.addEventListener('touchcancel', () => {
        if (!tracking) return;
        tracking = false;
        pane.style.transition = `transform ${SWIPE_NAV_SLIDE_MS}ms ease-out`;
        pane.style.transform = 'translateX(0)';
    }, { passive: true });
}

function initSwipeNavigation() {
    attachSwipeNavigation(document.getElementById('post-modal'), {
        getPane: () => document.getElementById('modal-content'),
        canStep: (dir) => {
            const target = currentPostIndexInModal + dir;
            return target >= 0 && target < getModalPosts().length;
        },
        step: (dir) => showPostModal(currentPostIndexInModal + dir)
    });

    attachSwipeNavigation(document.getElementById('image-viewer-modal'), {
        getPane: () => document.getElementById('image-viewer-content'),
        canStep: canStepImageViewer,
        step: stepImageViewer
    });

    // The same two steps from the arrow keys. See handleViewerArrowKeys.
    document.addEventListener('keydown', handleViewerArrowKeys);
}

// --- Background scroll lock for every modal --------------------------------
// A dimmed overlay is supposed to make the page behind it inert, but only a
// few call sites remembered to set `modal-open` on <body> (and the class had
// no CSS behind it anyway), so the feed kept scrolling underneath. Rather than
// patching ~20 open/close functions, one observer derives the lock from what
// is actually visible -- new modals get it for free.
const MODAL_OVERLAY_SELECTOR = '.following-modal, .post-modal, .resume-modal, .poll-composer-modal';

function syncModalScrollLock() {
    const anyOpen = Array.prototype.some.call(
        document.querySelectorAll(MODAL_OVERLAY_SELECTOR),
        el => !el.classList.contains('hidden') && getComputedStyle(el).display !== 'none'
    );
    // Toggling to the value it already has is a no-op, so this can't loop with
    // the observer below even though <body>'s own class is being watched.
    document.body.classList.toggle('modal-open', anyOpen);
    document.documentElement.classList.toggle('modal-open', anyOpen);
}

(function watchModalVisibility() {
    let queued = 0;
    const schedule = () => {
        if (queued) return;
        queued = requestAnimationFrame(() => { queued = 0; syncModalScrollLock(); });
    };
    const start = () => {
        // Attributes only, and only for overlay elements -- class changes fire
        // constantly all over this app and must not cost anything here.
        new MutationObserver(mutations => {
            for (const mut of mutations) {
                const t = mut.target;
                if (t === document.body || (t.matches && t.matches(MODAL_OVERLAY_SELECTOR))) {
                    schedule();
                    return;
                }
            }
        }).observe(document.body, {
            subtree: true,
            attributes: true,
            attributeFilter: ['class', 'style'],
        });
        syncModalScrollLock();
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
    else start();
})();

// --- Pinch zoom, desktop ---------------------------------------------------
// The viewport tag in index.html turns off pinch zoom on touchscreens, but it
// says nothing about a laptop trackpad: there, a two-finger pinch arrives as a
// wheel event with ctrlKey set, and ctrl+wheel on a mouse is the same event.
// Both listeners have to be non-passive -- browsers treat wheel and touch
// listeners as passive by default and ignore preventDefault() from them.
(function blockDesktopPinchZoom() {
    window.addEventListener('wheel', (event) => {
        if (event.ctrlKey) event.preventDefault();
    }, { passive: false });

    // Safari does not report a trackpad pinch as ctrl+wheel; it has its own
    // gesture events, and they are the only way to stop it there.
    ['gesturestart', 'gesturechange', 'gestureend'].forEach(type => {
        document.addEventListener(type, (event) => event.preventDefault(), { passive: false });
    });
})();

// --- APEX QR encoder -------------------------------------------------------
// Self-contained byte-mode QR generator (ECC level H, versions 1-10). Replaces
// the old api.qrserver.com <img>: no network round-trip, no layout jump, and
// the output is inline SVG so it renders at any size without resampling. Level
// H is deliberate -- ~30% recovery is what lets the apex logo sit in the middle.
const ApexQR = (() => {
    const EXP = new Uint8Array(512), LOG = new Uint8Array(256);
    for (let i = 0, x = 1; i < 255; i++) { EXP[i] = x; LOG[x] = i; x <<= 1; if (x & 256) x ^= 0x11d; }
    for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
    const mul = (a, b) => (a && b) ? EXP[LOG[a] + LOG[b]] : 0;

    // [dataCodewords, ecCodewordsPerBlock, blockCount] for ECC level H.
    const SPEC = [null, [9, 17, 1], [16, 28, 1], [26, 22, 2], [36, 16, 4], [46, 22, 4],
                  [60, 28, 4], [66, 26, 5], [86, 26, 6], [100, 24, 8], [122, 28, 8]];
    const ALIGN = { 2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30], 6: [6, 34],
                    7: [6, 22, 38], 8: [6, 24, 42], 9: [6, 26, 46], 10: [6, 28, 50] };
    const MASKS = [
        (r, c) => (r + c) % 2 === 0,
        (r, c) => r % 2 === 0,
        (r, c) => c % 3 === 0,
        (r, c) => (r + c) % 3 === 0,
        (r, c) => ((r / 2 | 0) + (c / 3 | 0)) % 2 === 0,
        (r, c) => (r * c) % 2 + (r * c) % 3 === 0,
        (r, c) => ((r * c) % 2 + (r * c) % 3) % 2 === 0,
        (r, c) => ((r + c) % 2 + (r * c) % 3) % 2 === 0,
    ];

    function ecc(data, deg) {
        let gen = [1];
        for (let i = 0; i < deg; i++) {
            const q = new Array(gen.length + 1).fill(0);
            for (let j = 0; j < gen.length; j++) { q[j] ^= gen[j]; q[j + 1] ^= mul(gen[j], EXP[i]); }
            gen = q;
        }
        gen = gen.slice(1);
        const rem = new Uint8Array(deg);
        for (const byte of data) {
            const factor = byte ^ rem[0];
            rem.copyWithin(0, 1); rem[deg - 1] = 0;
            if (factor) for (let i = 0; i < deg; i++) rem[i] ^= mul(gen[i], factor);
        }
        return rem;
    }

    function codewords(text) {
        const bytes = new TextEncoder().encode(text);
        let ver = 1;
        while (ver <= 10 && bytes.length > SPEC[ver][0] - (ver < 10 ? 2 : 3)) ver++;
        if (ver > 10) return null;

        const [totalData, ecLen, blockCount] = SPEC[ver];
        const bits = [];
        const put = (val, n) => { for (let i = n - 1; i >= 0; i--) bits.push((val >> i) & 1); };
        put(4, 4);
        put(bytes.length, ver < 10 ? 8 : 16);
        for (const b of bytes) put(b, 8);
        put(0, Math.min(4, totalData * 8 - bits.length));
        while (bits.length % 8) bits.push(0);

        const data = [];
        for (let i = 0; i < bits.length; i += 8) {
            let v = 0; for (let j = 0; j < 8; j++) v = (v << 1) | bits[i + j];
            data.push(v);
        }
        for (let i = 0; data.length < totalData; i++) data.push(i % 2 ? 0x11 : 0xEC);

        const shortLen = Math.floor(totalData / blockCount), longCount = totalData % blockCount;
        const dBlocks = [], eBlocks = [];
        for (let i = 0, off = 0; i < blockCount; i++) {
            const len = shortLen + (i >= blockCount - longCount ? 1 : 0);
            const block = data.slice(off, off + len); off += len;
            dBlocks.push(block); eBlocks.push(ecc(block, ecLen));
        }
        const out = [];
        for (let i = 0; i <= shortLen; i++) for (const b of dBlocks) if (i < b.length) out.push(b[i]);
        for (let i = 0; i < ecLen; i++) for (const b of eBlocks) out.push(b[i]);
        return { ver, out };
    }

    function penalty(m, size) {
        let score = 0;
        const run = (get) => {
            for (let a = 0; a < size; a++) {
                let len = 1, prev = get(a, 0);
                for (let b = 1; b < size; b++) {
                    const cur = get(a, b);
                    if (cur === prev) { len++; } else { if (len >= 5) score += len - 2; len = 1; prev = cur; }
                }
                if (len >= 5) score += len - 2;
            }
        };
        run((r, c) => m[r][c]); run((c, r) => m[r][c]);
        for (let r = 0; r < size - 1; r++) for (let c = 0; c < size - 1; c++) {
            const v = m[r][c];
            if (v === m[r][c + 1] && v === m[r + 1][c] && v === m[r + 1][c + 1]) score += 3;
        }
        const pat = [1, 0, 1, 1, 1, 0, 1, 0, 0, 0, 0];
        const hit = (get, a, b) => { for (let i = 0; i < 11; i++) if (get(a, b + i) !== pat[i]) return false; return true; };
        for (let a = 0; a < size; a++) for (let b = 0; b <= size - 11; b++) {
            if (hit((x, y) => m[x][y], a, b)) score += 40;
            if (hit((x, y) => m[y][x], a, b)) score += 40;
        }
        let dark = 0;
        for (let r = 0; r < size; r++) for (let c = 0; c < size; c++) dark += m[r][c];
        score += Math.floor(Math.abs(dark * 20 / (size * size) - 10)) * 10;
        return score;
    }

    function matrix(text) {
        const enc = codewords(text);
        if (!enc) return null;
        const { ver, out } = enc;
        const size = ver * 4 + 17;
        const m = Array.from({ length: size }, () => new Uint8Array(size));
        const fn = Array.from({ length: size }, () => new Uint8Array(size));
        const set = (r, c, v) => { m[r][c] = v; fn[r][c] = 1; };

        const finder = (row, col) => {
            for (let i = -1; i <= 7; i++) for (let j = -1; j <= 7; j++) {
                const r = row + i, c = col + j;
                if (r < 0 || c < 0 || r >= size || c >= size) continue;
                const dark = (i >= 0 && i <= 6 && (j === 0 || j === 6)) ||
                             (j >= 0 && j <= 6 && (i === 0 || i === 6)) ||
                             (i >= 2 && i <= 4 && j >= 2 && j <= 4);
                set(r, c, dark ? 1 : 0);
            }
        };
        finder(0, 0); finder(0, size - 7); finder(size - 7, 0);

        for (let i = 8; i < size - 8; i++) { const v = i % 2 === 0 ? 1 : 0; set(6, i, v); set(i, 6, v); }

        for (const r of (ALIGN[ver] || [])) for (const c of (ALIGN[ver] || [])) {
            const nearFinder = (r < 8 && c < 8) || (r < 8 && c > size - 9) || (r > size - 9 && c < 8);
            if (nearFinder) continue;
            for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++)
                set(r + i, c + j, Math.max(Math.abs(i), Math.abs(j)) !== 1 ? 1 : 0);
        }

        // Reserve format/version areas before data placement.
        for (let i = 0; i < 9; i++) { if (!fn[8][i]) set(8, i, 0); if (!fn[i][8]) set(i, 8, 0); }
        for (let i = 0; i < 8; i++) { set(8, size - 1 - i, 0); set(size - 1 - i, 8, 0); }
        set(size - 8, 8, 1); // permanently dark module
        if (ver >= 7) {
            let bch = ver;
            for (let i = 0; i < 12; i++) bch = (bch << 1) ^ ((bch >>> 11) * 0x1f25);
            const vbits = (ver << 12) | bch;
            for (let i = 0; i < 18; i++) {
                const bit = (vbits >> i) & 1, a = Math.floor(i / 3), b = i % 3;
                set(size - 11 + b, a, bit); set(a, size - 11 + b, bit);
            }
        }

        let idx = 0, upward = true;
        for (let col = size - 1; col > 0; col -= 2) {
            if (col === 6) col--;
            for (let i = 0; i < size; i++) {
                const r = upward ? size - 1 - i : i;
                for (const c of [col, col - 1]) {
                    if (fn[r][c]) continue;
                    m[r][c] = idx < out.length * 8 ? (out[idx >> 3] >> (7 - (idx & 7))) & 1 : 0;
                    idx++;
                }
            }
            upward = !upward;
        }

        let best = null, bestScore = Infinity;
        for (let mask = 0; mask < 8; mask++) {
            const test = m.map((row, r) => row.map((v, c) => fn[r][c] ? v : v ^ (MASKS[mask](r, c) ? 1 : 0)));
            const s = penalty(test, size);
            if (s < bestScore) { bestScore = s; best = { mask, test }; }
        }

        let fbits = (0b10 << 3) | best.mask, rem = fbits;
        for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
        fbits = (((fbits << 10) | rem) ^ 0x5412);
        for (let i = 0; i < 15; i++) {
            const bit = (fbits >> i) & 1;
            // First copy: down the left of the top-left finder, then right along row 8.
            if (i < 6) best.test[i][8] = bit;
            else if (i === 6) best.test[7][8] = bit;
            else if (i === 7) best.test[8][8] = bit;
            else if (i === 8) best.test[8][7] = bit;
            else best.test[8][14 - i] = bit;
            // Second copy: bottom-left column and top-right row.
            if (i < 8) best.test[8][size - 1 - i] = bit;
            else best.test[size - 15 + i][8] = bit;
        }
        best.test[size - 8][8] = 1;
        return { m: best.test, size };
    }

    // Renders as one <path> of dots plus hand-drawn finder "eyes" -- a single
    // static SVG node, no per-module elements, nothing to download or drag.
    function svg(text) {
        const built = matrix(text);
        if (!built) return '';
        const { m, size } = built;
        const q = 2, dim = size + q * 2;              // 2-module quiet zone
        const half = size * 0.13, mid = size / 2;     // logo knockout region
        const inFinder = (r, c) => (r < 7 && c < 7) || (r < 7 && c >= size - 7) || (r >= size - 7 && c < 7);

        let d = '';
        for (let r = 0; r < size; r++) for (let c = 0; c < size; c++) {
            if (!m[r][c] || inFinder(r, c)) continue;
            if (Math.abs(r + 0.5 - mid) < half && Math.abs(c + 0.5 - mid) < half) continue;
            const x = (c + q + 0.5).toFixed(2), y = (r + q + 0.5).toFixed(2);
            d += `M${x} ${y}m-.5 0a.5.5 0 1 0 1 0a.5.5 0 1 0-1 0`;
        }

        const eye = (r, c) => {
            const x = c + q, y = r + q;
            return `<path d="M${x} ${y}h7v7h-7z" fill="none"/>` +
                   `<rect x="${x + .5}" y="${y + .5}" width="6" height="6" rx="2" fill="none" stroke="url(#apexQrG)" stroke-width="1"/>` +
                   `<rect x="${x + 2}" y="${y + 2}" width="3" height="3" rx="1" fill="url(#apexQrG)"/>`;
        };

        const plaque = (2 * half).toFixed(2), pOff = (mid + q - half).toFixed(2);
        const logo = (2 * half * 0.72).toFixed(2), lOff = (mid + q - half * 0.72).toFixed(2);

        return `<svg class="apex-qr-svg" viewBox="0 0 ${dim} ${dim}" xmlns="http://www.w3.org/2000/svg" ` +
               `role="img" aria-label="QR code linking to this page" focusable="false">` +
               `<defs><linearGradient id="apexQrG" x1="0" y1="0" x2="1" y2="1">` +
               `<stop offset="0" stop-color="#0033ff"/><stop offset="1" stop-color="#00b8d4"/>` +
               `</linearGradient></defs>` +
               `<rect width="${dim}" height="${dim}" fill="#fff"/>` +
               `<path d="${d}" fill="url(#apexQrG)"/>` +
               eye(0, 0) + eye(0, size - 7) + eye(size - 7, 0) +
               `<rect x="${pOff}" y="${pOff}" width="${plaque}" height="${plaque}" rx="${(half * 0.5).toFixed(2)}" fill="#fff"/>` +
               `<image href="/api/asset/logo_icon" x="${lOff}" y="${lOff}" width="${logo}" height="${logo}" ` +
               `preserveAspectRatio="xMidYMid meet"/>` +
               `</svg>`;
    }

    const cache = new Map();
    return (text) => {
        if (!cache.has(text)) cache.set(text, svg(text));
        return cache.get(text);
    };
})();

// --- APEX A-Line ------------------------------------------------------------
// APEX's own share mark, alongside the QR. A QR is a stranger's format and has
// to carry a whole URL because anything might scan it. An A-Line is only ever
// read by APEX, so it carries a route type and a number -- twenty-four bits --
// and spends everything that saves on being readable and on being worth looking
// at.
//
// The mark is a range of hills on solid ground: fifteen vertices on a fixed
// grid, each at one of sixteen heights, and that height is the data. Every
// slope's angle and length therefore falls out of the pair of heights it spans.
// Two things shape it beyond the raw numbers:
//
//   * a whitening mask, so consecutive ids draw completely different ranges
//     instead of near-identical ones,
//   * one smooth swell, low at both ends and high through the middle, so the
//     range has somewhere to build to.
//
// Fifteen points across the whole width is what makes it calm -- each slope runs
// a fourteenth of the mark, so the eye reads hills rather than teeth -- and it
// is also what makes it quick. At this spacing one level is nine or ten pixels
// of a phone frame where a denser mark would have four, which is the difference
// between a scan that lands first try and one that hunts.
//
// Everything runs locally: string -> SVG on one side, ImageData -> string on the
// other, no endpoint in either direction.
const ApexALine = (() => {

    // --- Reed-Solomon over GF(16) -------------------------------------------
    // Sixteen elements, because here a symbol IS a vertex: one misread hill is
    // exactly one corrupt symbol. Over GF(256) a symbol would span two
    // neighbouring hills, so a single bad reading would burn both and the same
    // parity would buy half the protection.
    const EXP = new Uint8Array(32), LOG = new Uint8Array(16);
    for (let i = 0, x = 1; i < 15; i++) { EXP[i] = x; LOG[x] = i; x <<= 1; if (x & 16) x ^= 0b10011; }
    for (let i = 15; i < 32; i++) EXP[i] = EXP[i - 15];
    const gmul = (a, b) => (a && b) ? EXP[(LOG[a] + LOG[b]) % 15] : 0;
    const gdiv = (a, b) => a === 0 ? 0 : EXP[(LOG[a] + 15 - LOG[b]) % 15];
    const ginv = (a) => EXP[(15 - LOG[a]) % 15];

    // Polynomials are highest-degree-first, matching the usual write-ups.
    function polyMul(p, q) {
        const r = new Array(p.length + q.length - 1).fill(0);
        for (let j = 0; j < q.length; j++)
            for (let i = 0; i < p.length; i++) r[i + j] ^= gmul(p[i], q[j]);
        return r;
    }
    function polyAdd(p, q) {
        const r = new Array(Math.max(p.length, q.length)).fill(0);
        for (let i = 0; i < p.length; i++) r[i + r.length - p.length] = p[i];
        for (let i = 0; i < q.length; i++) r[i + r.length - q.length] ^= q[i];
        return r;
    }
    const polyScale = (p, s) => p.map(c => gmul(c, s));
    function polyEval(p, x) { let y = p[0]; for (let i = 1; i < p.length; i++) y = gmul(y, x) ^ p[i]; return y; }

    const V = 15;               // vertices, and RS symbols: GF(16) allows no more
    const DATA = 8, ECC = 7;    // 8 data symbols (32 bits), 7 parity -> corrects 3

    let GEN = null;
    function generator() {
        if (!GEN) { let g = [1]; for (let i = 0; i < ECC; i++) g = polyMul(g, [1, EXP[i]]); GEN = g; }
        return GEN;
    }

    function rsEncode(data) {
        const gen = generator();
        const out = new Uint8Array(V);
        out.set(data);
        for (let i = 0; i < data.length; i++) {
            const coef = out[i];
            if (coef) for (let j = 1; j < gen.length; j++) out[i + j] ^= gmul(gen[j], coef);
        }
        out.set(data);              // the division trampled it; this is systematic
        return out;
    }

    // Berlekamp-Massey, Chien, Forney. Returns the corrected codeword or null.
    function rsDecode(msg) {
        const synd = new Array(ECC + 1).fill(0);   // synd[0] stays 0, as BM wants
        let clean = true;
        for (let i = 0; i < ECC; i++) {
            synd[i + 1] = polyEval(msg, EXP[i]);
            if (synd[i + 1]) clean = false;
        }
        if (clean) return msg.slice();

        let errLoc = [1], oldLoc = [1];
        for (let i = 0; i < ECC; i++) {
            const K = i + 1;
            let delta = synd[K];
            for (let j = 1; j < errLoc.length; j++)
                delta ^= gmul(errLoc[errLoc.length - 1 - j], synd[K - j]);
            oldLoc = oldLoc.concat([0]);
            if (delta !== 0) {
                if (oldLoc.length > errLoc.length) {
                    const newLoc = polyScale(oldLoc, delta);
                    oldLoc = polyScale(errLoc, ginv(delta));
                    errLoc = newLoc;
                }
                errLoc = polyAdd(errLoc, polyScale(oldLoc, delta));
            }
        }
        while (errLoc.length && errLoc[0] === 0) errLoc.shift();
        const errCount = errLoc.length - 1;
        if (errCount <= 0 || errCount * 2 > ECC) return null;

        const errPos = [];
        for (let i = 0; i < msg.length; i++)
            if (polyEval(errLoc, EXP[(15 - (i % 15)) % 15]) === 0) errPos.push(msg.length - 1 - i);
        if (errPos.length !== errCount) return null;

        const coefPos = errPos.map(p => msg.length - 1 - p);
        let errata = [1];
        for (const p of coefPos) errata = polyMul(errata, polyAdd([1], [EXP[p % 15], 0]));

        let evaluator = polyMul(synd.slice().reverse(), errata);
        evaluator = evaluator.slice(evaluator.length - (errata.length - 1) - 1);
        const evalFwd = evaluator.slice().reverse();

        const out = msg.slice();
        const X = coefPos.map(p => EXP[p % 15]);
        for (let i = 0; i < X.length; i++) {
            const Xi = X[i], XiInv = ginv(Xi);
            let denom = 1;
            for (let j = 0; j < X.length; j++) if (j !== i) denom = gmul(denom, 1 ^ gmul(XiInv, X[j]));
            if (denom === 0) return null;
            const y = gmul(Xi, polyEval(evalFwd.slice().reverse(), XiInv));
            out[errPos[i]] ^= gdiv(y, denom);
        }

        // Berlekamp-Massey will happily converge on a plausible-but-wrong locator
        // once the damage is past what the parity can carry. Re-checking the
        // syndromes is what stops a wrong route reaching the router.
        for (let i = 0; i < ECC; i++) if (polyEval(out, EXP[i]) !== 0) return null;
        return out;
    }

    // --- Payload -------------------------------------------------------------
    // Everything APEX shares is a type and a number: lounges, posts and articles
    // by row id, circuits by their six-digit code, profiles by user id. That is
    // twenty-four bits, and a byte of checksum on top makes exactly the thirty
    // two the eight data symbols hold -- which is the whole reason this mark can
    // be seven hills rather than twenty-four.
    const ID_BITS = 21;         // 2,097,151: past every six-digit circuit code
    const TYPES = [
        { code: 0, long: '/lounges/',  short: '/l/' },
        { code: 1, long: '/users/',    short: '/u/' },
        { code: 2, long: '/posts/',    short: '/p/' },
        { code: 3, long: '/circuits/', short: '/c/' },
        { code: 4, long: '/articles/', short: '/a/' },
        // Any other page: the number is an ALineLink row on the server, which
        // holds the page's path (see linkALineFor / resolveALineLink).
        { code: 5, long: '/links/',    short: '/k/' },
    ];

    // CRC-8/ATM over the three payload bytes. Reed-Solomon already refuses most
    // bad codewords, but "most" is not good enough for something that navigates
    // the app on its own.
    function crc8(bytes) {
        let crc = 0xFF;
        for (const b of bytes) {
            crc ^= b;
            for (let i = 0; i < 8; i++) crc = (crc & 0x80) ? ((crc << 1) ^ 0x07) & 0xFF : (crc << 1) & 0xFF;
        }
        return crc;
    }

    // type(3) | id(21) -> three bytes, plus a fourth of CRC, split into nibbles.
    function encode(path) {
        const clean = String(path || '').trim().replace(/^https?:\/\/[^\/]+/i, '') || '/';
        for (const t of TYPES) {
            for (const prefix of [t.long, t.short]) {
                if (!clean.startsWith(prefix)) continue;
                const rest = clean.slice(prefix.length).split(/[\/?#]/)[0];
                if (!/^\d+$/.test(rest)) continue;
                const id = parseInt(rest, 10);
                if (!(id >= 0 && id < (1 << ID_BITS))) return null;
                const b = [((t.code & 7) << 5) | (id >>> 16), (id >>> 8) & 0xFF, id & 0xFF];
                b.push(crc8(b));
                const sym = new Uint8Array(DATA);
                for (let i = 0; i < 4; i++) { sym[i * 2] = b[i] >> 4; sym[i * 2 + 1] = b[i] & 15; }
                return rsEncode(sym);
            }
        }
        return null;
    }

    function decodeCodeword(symbols) {
        const fixed = rsDecode(Array.from(symbols));
        if (!fixed) return null;
        const b = [];
        for (let i = 0; i < 4; i++) b.push((fixed[i * 2] << 4) | fixed[i * 2 + 1]);
        if (crc8(b.slice(0, 3)) !== b[3]) return null;
        const type = (b[0] >> 5) & 7;
        const t = TYPES.find(x => x.code === type);
        if (!t) return null;
        return t.long + (((b[0] & 0x1F) << 16) | (b[1] << 8) | b[2]);
    }

    // --- Geometry ------------------------------------------------------------
    // Heights are fractions of the frame, measured up from the baseline. FLOOR
    // is the solid ground every mark stands on -- it is also the full-width
    // straight edge the scanner finds the mark by, so it is not decoration.
    // LEVELS is what the data moves through and ENV is the swell on top of it.
    // The swell is deliberately almost as strong as the data. Let the data
    // dominate and the range wanders -- the tallest peak lands wherever the id
    // happens to put it, and the shape reads as noise. At these proportions the
    // arc is always low at the ends and high through the middle, and the payload
    // decides the character of the hills rather than the shape of the range.
    const FLOOR = 0.18, ENV = 0.28, LEVELS = 0.38, STEP = LEVELS / 15;
    const CEILING = FLOOR + ENV + LEVELS;   // 0.84, leaving the top rule clear
    // A thin rule all the way round. It is the one piece of the mark that no
    // payload can move, so it is what the scanner measures everything against:
    // four exact corners give the full perspective of a mark photographed at an
    // angle, which two points on a baseline cannot. The old version bought the
    // same thing with two full-height pillars at the ends -- structurally fine,
    // but they towered over the range and made a low-high-low skyline read as
    // high-low-high. A frame does the job and gets out of the way.
    const RULE = 0.026;                     // thickness, as a fraction of height

    // Low at both ends, high through the middle. One term, deliberately: the
    // old three-harmonic envelope made the range busy before any data was in it.
    const envelope = (i) => Math.sin(Math.PI * i / (V - 1));

    // Whitening. Without it /l/41 and /l/42 draw almost the same range; with it
    // every id gets its own skyline.
    function mask(i) {
        let x = Math.imul(i + 0x9E37, 0x85EBCA6B) >>> 0;
        x ^= x >>> 15; x = Math.imul(x, 0xC2B2AE35) >>> 0;
        x ^= x >>> 13; x = Math.imul(x, 0x27D4EB2F) >>> 0;
        return (x ^ (x >>> 16)) & 15;
    }

    const levels   = (cw) => cw.map((s, i) => s ^ mask(i));
    const unlevels = (lv) => Array.from(lv, (s, i) => s ^ mask(i));
    const heightAt = (level, i) => FLOOR + envelope(i) * ENV + level * STEP;

    // --- Styles --------------------------------------------------------------
    // Quiet on purpose. Each is one hue: a saturated stop at the ridge fading
    // into a muted body within the top third, and flat below that. The one hard
    // rule is that every stop stays firmly on one side of the ground it sits on,
    // because that separation is the only thing the scanner has to work with.
    const STYLES = [
        { id: 'apex',  name: 'Apex',  bg: '#f4f7fd', top: '#0b3fd4', body: '#8aabe6', dark: false },
        { id: 'slate', name: 'Slate', bg: '#f7f8fa', top: '#33475f', body: '#93a5b8', dark: false },
        { id: 'moss',  name: 'Moss',  bg: '#f4f8f4', top: '#2f6a44', body: '#9bbca6', dark: false },
        { id: 'clay',  name: 'Clay',  bg: '#fbf6f2', top: '#a4552f', body: '#d9ab90', dark: false },
        { id: 'night', name: 'Night', bg: '#111721', top: '#e2eaf5', body: '#61798f', dark: true },
    ];
    const styleById = (id) => STYLES.find(s => s.id === id) || STYLES[0];

    // --- Renderer ------------------------------------------------------------
    const SLOT = 40;                        // generous: the mark is meant to breathe
    const W = (V - 1) * SLOT, H = 6 * SLOT; // 560 x 240, so 2.33:1
    const PAD = Math.round(SLOT * 0.6);

    function svg(path, styleId) {
        const cw = encode(path);
        if (!cw) return '';
        const lv = levels(Array.from(cw));
        const style = styleById(styleId);
        const uid = 'al' + Math.random().toString(36).slice(2, 8);
        const vw = W + PAD * 2, vh = H + PAD * 2;

        const T = RULE * H;
        const xAt = (i) => PAD + T + i * (W - 2 * T) / (V - 1);
        const yAt = (i) => PAD + H * (1 - heightAt(lv[i], i));

        // One closed silhouette: the range across the top, then straight down and
        // back along the baseline. The band of solid fill under the lowest valley
        // is the ground the hills sit on AND the long straight edge the scanner
        // locks onto -- the same shape doing both jobs, which is why there are no
        // pillars or markers cluttering the ends any more.
        let d = `M${(PAD + T).toFixed(1)} ${PAD + H}`;
        for (let i = 0; i < V; i++) d += `L${xAt(i).toFixed(1)} ${yAt(i).toFixed(1)}`;
        d += `L${(PAD + W - T).toFixed(1)} ${PAD + H}Z`;

        // The rule, as one even-odd path: outer rectangle, inner rectangle. It
        // touches the range at the ground and at both ends, so mark and frame
        // threshold as a single connected shape -- which is what lets the
        // scanner take the frame's four corners as the code's own.
        const rule = `M${PAD} ${PAD}h${W}v${H}h${-W}Z` +
            `M${(PAD + T).toFixed(1)} ${(PAD + T).toFixed(1)}v${(H - 2 * T).toFixed(1)}` +
            `h${(W - 2 * T).toFixed(1)}v${(-(H - 2 * T)).toFixed(1)}Z`;

        // The colour lives at the ridge and is gone by a third of the way down.
        // Below that the body is one flat muted tone, which is what keeps the
        // mark calm -- and, not coincidentally, keeps every part of it the same
        // safe distance from the background.
        return `<svg class="apex-aline-svg" width="${vw}" height="${vh}" viewBox="0 0 ${vw} ${vh}" ` +
            `xmlns="http://www.w3.org/2000/svg" role="img" ` +
            `aria-label="APEX A-Line code for ${escapeHtmlText(path)}" focusable="false" ` +
            `preserveAspectRatio="xMidYMid meet">` +
            `<defs><linearGradient id="${uid}f" x1="0" y1="0" x2="0" y2="1">` +
            `<stop offset="0" stop-color="${style.top}"/>` +
            `<stop offset="0.34" stop-color="${style.body}"/>` +
            `<stop offset="1" stop-color="${style.body}"/>` +
            `</linearGradient></defs>` +
            `<rect width="${vw}" height="${vh}" rx="${PAD}" fill="${style.bg}"/>` +
            `<path d="${rule}" fill="${style.body}" fill-rule="evenodd"/>` +
            `<path d="${d}" fill="url(#${uid}f)"/>` +
            `</svg>`;
    }

    // --- Decoder -------------------------------------------------------------
    // Block-wise thresholding of the kind QR readers settled on: a midpoint
    // between the darkest and lightest pixel of each block, smoothed across the
    // blocks around it so the cut-off follows a lighting gradient without
    // following the mark. Only blocks that actually straddle an edge vote -- a
    // block of flat colour knows nothing about where ink ends, and letting it
    // guess is what hollows out the pale half of a gradient.
    const BLOCK = 16;
    function binarize(gray, w, h) {
        const bw = Math.max(1, Math.ceil(w / BLOCK)), bh = Math.max(1, Math.ceil(h / BLOCK));
        const points = new Float32Array(bw * bh);
        const edged = new Uint8Array(bw * bh);
        let sumEdged = 0, nEdged = 0, sumAll = 0, nAll = 0;
        for (let by = 0; by < bh; by++) for (let bx = 0; bx < bw; bx++) {
            const x0 = bx * BLOCK, y0 = by * BLOCK;
            const x1 = Math.min(w, x0 + BLOCK), y1 = Math.min(h, y0 + BLOCK);
            let min = 255, max = 0, sum = 0, n = 0;
            for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
                const g = gray[y * w + x];
                if (g < min) min = g;
                if (g > max) max = g;
                sum += g; n++;
            }
            if (max - min > 24) {
                points[by * bw + bx] = (min + max) / 2;
                edged[by * bw + bx] = 1;
                sumEdged += (min + max) / 2; nEdged++;
            }
            sumAll += n ? sum / n : 128; nAll++;
        }
        const fallback = nEdged ? sumEdged / nEdged : (nAll ? sumAll / nAll : 128);
        const mask = new Uint8Array(w * h);
        for (let by = 0; by < bh; by++) for (let bx = 0; bx < bw; bx++) {
            let sum = 0, n = 0;
            for (let r = 2; r <= 6 && !n; r += 2)
                for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
                    const ny = by + dy, nx = bx + dx;
                    if (ny < 0 || nx < 0 || ny >= bh || nx >= bw || !edged[ny * bw + nx]) continue;
                    sum += points[ny * bw + nx]; n++;
                }
            const cut = n ? sum / n : fallback;
            const x0 = bx * BLOCK, y0 = by * BLOCK;
            const x1 = Math.min(w, x0 + BLOCK), y1 = Math.min(h, y0 + BLOCK);
            for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++)
                mask[y * w + x] = gray[y * w + x] < cut ? 1 : 0;
        }
        return mask;
    }

    // Flood-filled blobs, biggest first, each tagged in a label map so a later
    // pass can ask "is this pixel part of THAT blob" rather than the much weaker
    // "is this pixel ink" -- at polarity 0 the mark and the page behind it are
    // both non-ink, and a scan that only consulted the mask would read the page
    // as the top of every column.
    function components(mask, w, h, polarity, limit) {
        const seen = new Uint8Array(w * h), labels = new Int32Array(w * h);
        const stack = new Int32Array(w * h);
        const found = [];
        const minArea = (w * h) / 900;
        let id = 0;
        for (let p = 0; p < w * h; p++) {
            if (seen[p] || mask[p] !== polarity) continue;
            const mine = ++id;
            let sp = 0, area = 0, minY = h, maxY = -1;
            stack[sp++] = p; seen[p] = 1;
            const rowMin = new Int32Array(h).fill(w), rowMax = new Int32Array(h).fill(-1);
            while (sp) {
                const q = stack[--sp], qx = q % w, qy = (q / w) | 0;
                labels[q] = mine; area++;
                if (qy < minY) minY = qy;
                if (qy > maxY) maxY = qy;
                if (qx < rowMin[qy]) rowMin[qy] = qx;
                if (qx > rowMax[qy]) rowMax[qy] = qx;
                if (qx > 0     && !seen[q - 1] && mask[q - 1] === polarity) { seen[q - 1] = 1; stack[sp++] = q - 1; }
                if (qx < w - 1 && !seen[q + 1] && mask[q + 1] === polarity) { seen[q + 1] = 1; stack[sp++] = q + 1; }
                if (qy > 0     && !seen[q - w] && mask[q - w] === polarity) { seen[q - w] = 1; stack[sp++] = q - w; }
                if (qy < h - 1 && !seen[q + w] && mask[q + w] === polarity) { seen[q + w] = 1; stack[sp++] = q + w; }
            }
            if (area < minArea) continue;
            const pts = [];
            for (let y = minY; y <= maxY; y++) {
                if (rowMax[y] < 0) continue;
                pts.push([rowMin[y], y]);
                if (rowMax[y] !== rowMin[y]) pts.push([rowMax[y], y]);
            }
            found.push({ area, pts, id: mine });
        }
        found.sort((a, b) => b.area - a.area);
        return { labels, list: found.slice(0, limit) };
    }

    function hull(points) {
        const pts = points.slice().sort((a, b) => a[0] - b[0] || a[1] - b[1]);
        if (pts.length < 3) return pts;
        const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
        const lower = [];
        for (const p of pts) {
            while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) <= 0) lower.pop();
            lower.push(p);
        }
        const upper = [];
        for (let i = pts.length - 1; i >= 0; i--) {
            const p = pts[i];
            while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) <= 0) upper.pop();
            upper.push(p);
        }
        lower.pop(); upper.pop();
        return lower.concat(upper);
    }

    // The code's own four corners, taken as the hull's extremes along the two
    // diagonals of its bounding rectangle.
    //
    // This works because of the rule: it is a rectangle enclosing everything, so
    // the hull IS that rectangle and its corners are structural rather than
    // whatever peak happens to be tallest. Four corners is also the minimum for
    // a projective map, which is what a mark photographed at an angle needs --
    // a baseline alone gives two, and two only ever buys a rotation and a scale.
    function frameQuad(points) {
        const hp = hull(points);
        if (hp.length < 4) return null;
        let best = null;
        for (let i = 0; i < hp.length; i++) {
            const a = hp[i], b = hp[(i + 1) % hp.length];
            const dx = b[0] - a[0], dy = b[1] - a[1];
            const len = Math.hypot(dx, dy);
            if (len < 1) continue;
            const ux = dx / len, uy = dy / len;
            let minU = Infinity, maxU = -Infinity, minV = Infinity, maxV = -Infinity;
            for (const p of hp) {
                const u = p[0] * ux + p[1] * uy, v = -p[0] * uy + p[1] * ux;
                if (u < minU) minU = u; if (u > maxU) maxU = u;
                if (v < minV) minV = v; if (v > maxV) maxV = v;
            }
            const area = (maxU - minU) * (maxV - minV);
            if (!best || area < best.area) best = { area, ux, uy, w: maxU - minU, h: maxV - minV };
        }
        if (!best) return null;

        // Turn the frame so its long axis runs left to right; the mark is always
        // wider than it is tall, whichever way up the phone happens to be.
        let { ux, uy } = best;
        if (best.h > best.w) { const t = ux; ux = -uy; uy = t; }

        let TL = null, TR = null, BR = null, BL = null;
        let a1 = Infinity, a2 = -Infinity, a3 = -Infinity, a4 = -Infinity;
        for (const p of hp) {
            const u = p[0] * ux + p[1] * uy, v = -p[0] * uy + p[1] * ux;
            if (u + v < a1) { a1 = u + v; TL = p; }
            if (u - v > a2) { a2 = u - v; TR = p; }
            if (u + v > a3) { a3 = u + v; BR = p; }
            if (v - u > a4) { a4 = v - u; BL = p; }
        }
        if (!TL || !TR || !BR || !BL || TL === BR || TR === BL) return null;
        return [TL, TR, BR, BL];
    }

    function projection(quad) {
        const [p0, p1, p2, p3] = quad;
        const dx1 = p1[0] - p2[0], dx2 = p3[0] - p2[0], dx3 = p0[0] - p1[0] + p2[0] - p3[0];
        const dy1 = p1[1] - p2[1], dy2 = p3[1] - p2[1], dy3 = p0[1] - p1[1] + p2[1] - p3[1];
        let a, b, c, d, e, f, g, hh;
        const det = dx1 * dy2 - dy1 * dx2;
        if (Math.abs(dx3) < 1e-9 && Math.abs(dy3) < 1e-9) {
            g = 0; hh = 0;
            a = p1[0] - p0[0]; b = p2[0] - p1[0]; c = p0[0];
            d = p1[1] - p0[1]; e = p2[1] - p1[1]; f = p0[1];
        } else {
            if (Math.abs(det) < 1e-9) return null;
            g = (dx3 * dy2 - dy3 * dx2) / det;
            hh = (dx1 * dy3 - dy1 * dx3) / det;
            a = p1[0] - p0[0] + g * p1[0]; b = p3[0] - p0[0] + hh * p3[0]; c = p0[0];
            d = p1[1] - p0[1] + g * p1[1]; e = p3[1] - p0[1] + hh * p3[1]; f = p0[1];
        }
        return (u, v) => {
            const wgt = g * u + hh * v + 1;
            if (Math.abs(wgt) < 1e-9) return [-1, -1];
            return [(a * u + b * v + c) / wgt, (d * u + e * v + f) / wgt];
        };
    }

    // The silhouette's upper boundary across the frame, as a height above the
    // baseline, with NaN where a column held no ink at all.
    function profile(labels, w, h, map, id, steps, n) {
        const out = new Float32Array(n);
        const at = (u, v) => {
            const [x, y] = map(u, v);
            const xi = Math.round(x), yi = Math.round(y);
            if (xi < 0 || yi < 0 || xi >= w || yi >= h) return false;
            return labels[yi * w + xi] === id;
        };
        // A real hit has the whole hill under it -- the fill is solid from the
        // ridge to the ground, and the shallowest part of it is a fifth of the
        // frame deep -- so demanding a run of ink costs nothing and throws away
        // the speckle that would otherwise read as a peak halfway up the sky.
        const need = Math.max(3, Math.round(steps * 0.03));
        // Start below the top rule, or every column would report the rule as its
        // ridge. The geometry keeps a clear band between the two: the rule ends
        // at RULE of the height and no peak comes above CEILING.
        const from = Math.ceil(steps * (RULE + (1 - CEILING - RULE) * 0.45));
        for (let i = 0; i < n; i++) {
            const u = i / (n - 1);
            let top = NaN, run = 0;
            for (let s = from; s < steps; s++) {
                if (at(u, s / (steps - 1))) {
                    if (++run >= need) { top = (s - need + 1) / (steps - 1); break; }
                } else run = 0;
            }
            out[i] = isNaN(top) ? NaN : 1 - top;
        }
        return out;
    }

    // The ridge is piecewise linear with its knots at the vertices, so every
    // profile sample is a linear equation in two neighbouring heights and least
    // squares over all of them is a tridiagonal system. Nothing is read AT a
    // vertex: a pixel of horizontal error at a corner is a whole level of
    // vertical error, and softness rounds corners downwards.
    function fitRidge(us, ys, u0, slot, robust) {
        const seg = [], frac = [], val = [];
        for (let k = 0; k < us.length; k++) {
            const y = ys[k];
            if (y > CEILING + 0.06) continue;
            const t = (us[k] - u0) / slot;
            if (t < 0 || t > V - 1) continue;
            const j = Math.min(V - 2, Math.floor(t)), f = t - j;
            if (f < 0.12 || f > 0.88) continue;
            seg.push(j); frac.push(f); val.push(y);
        }
        if (seg.length < V * 3) return null;

        const height = new Float64Array(V);
        const keep = new Uint8Array(seg.length).fill(1);
        let rms = 0;
        for (let pass = 0; pass < (robust ? 2 : 1); pass++) {
            const diag = new Float64Array(V), upper = new Float64Array(V), rhs = new Float64Array(V);
            const support = new Int32Array(V);
            for (let k = 0; k < seg.length; k++) {
                if (!keep[k]) continue;
                const j = seg[k], f = frac[k], y = val[k], a = 1 - f;
                diag[j] += a * a; upper[j] += a * f; diag[j + 1] += f * f;
                rhs[j] += a * y;  rhs[j + 1] += f * y;
                support[j]++; support[j + 1]++;
            }
            for (let i = 0; i < V; i++) if (support[i] < 3) return null;
            const c = new Float64Array(V), dd = new Float64Array(V);
            let den = diag[0];
            if (Math.abs(den) < 1e-12) return null;
            c[0] = upper[0] / den; dd[0] = rhs[0] / den;
            for (let i = 1; i < V; i++) {
                den = diag[i] - upper[i - 1] * c[i - 1];
                if (Math.abs(den) < 1e-12) return null;
                c[i] = (i < V - 1 ? upper[i] : 0) / den;
                dd[i] = (rhs[i] - upper[i - 1] * dd[i - 1]) / den;
            }
            height[V - 1] = dd[V - 1];
            for (let i = V - 2; i >= 0; i--) height[i] = dd[i] - c[i] * height[i + 1];

            const resid = new Float64Array(seg.length);
            let sum = 0;
            for (let k = 0; k < seg.length; k++) {
                const j = seg[k], f = frac[k];
                resid[k] = Math.abs(val[k] - (height[j] * (1 - f) + height[j + 1] * f));
                sum += resid[k] * resid[k];
            }
            rms = Math.sqrt(sum / seg.length);
            if (!robust || pass) break;
            const sorted = Array.from(resid).sort((a, b) => a - b);
            const scale = Math.max(sorted[sorted.length >> 1] * 2.5, STEP * 0.3);
            for (let k = 0; k < seg.length; k++) keep[k] = resid[k] <= scale ? 1 : 0;
        }
        return { height, rms };
    }

    // The grid is searched rather than trusted. The baseline pins it to within a
    // fraction of a percent, but a fraction of a percent compounds across the
    // width, and misalignment leaves a signature -- it cannot fit the steep parts
    // -- so the residual is a reliable thing to minimise.
    function readHeights(prof) {
        const n = prof.length;
        const us = [], ys = [];
        for (let i = 0; i < n; i++) if (!isNaN(prof[i])) { us.push(i / (n - 1)); ys.push(prof[i]); }
        if (us.length < V * 6) return null;

        const inset = RULE * (H / W);            // the rule, in units of the width
        let u0 = inset, slot = (1 - 2 * inset) / (V - 1);
        let du = slot * 0.30, ds = slot * 0.03;
        for (let round = 0; round < 3; round++) {
            let bu = u0, bs = slot, br = Infinity;
            for (let a = -2; a <= 2; a++) for (let b = -2; b <= 2; b++) {
                const cu = u0 + a * du / 2, cs = slot + b * ds / 2;
                const f = fitRidge(us, ys, cu, cs, false);
                if (f && f.rms < br) { br = f.rms; bu = cu; bs = cs; }
            }
            if (!isFinite(br)) return null;
            u0 = bu; slot = bs; du /= 2.5; ds /= 2.5;
        }
        const fitted = fitRidge(us, ys, u0, slot, true);
        return fitted ? fitted.height : null;
    }

    function heightsToPath(height, shift) {
        const sym = new Uint8Array(V);
        for (let i = 0; i < V; i++) {
            const lvl = Math.round((height[i] + shift - FLOOR - envelope(i) * ENV) / STEP);
            if (lvl < -1 || lvl > 16) return null;      // nowhere near a real reading
            sym[i] = Math.max(0, Math.min(15, lvl));
        }
        return decodeCodeword(unlevels(sym));
    }

    // ImageData -> route, or null. Both ink polarities, the largest few blobs in
    // each, both ends first, and a few whole-mark height offsets. None of those
    // guesses can return a wrong answer on its own: a candidate has to survive a
    // Reed-Solomon correction that re-verifies its own syndromes and then a CRC
    // over the payload.
    function decodeImage(imageData) {
        const { width: w, height: h, data } = imageData;
        const gray = new Uint8Array(w * h);
        for (let i = 0, p = 0; i < data.length; i += 4, p++)
            gray[p] = (data[i] * 77 + data[i + 1] * 150 + data[i + 2] * 29) >> 8;
        const mask = binarize(gray, w, h);

        for (const polarity of [1, 0]) {
            const { labels, list } = components(mask, w, h, polarity, 4);
            for (const comp of list) {
                const quad = frameQuad(comp.pts);
                if (!quad) continue;
                const dist = (a, b) => Math.hypot(quad[b][0] - quad[a][0], quad[b][1] - quad[a][1]);
                const n = Math.min(1600, Math.max(300, Math.round(dist(3, 2) * 2)));
                const steps = Math.max(60, Math.round(dist(0, 3)));
                for (const flip of [false, true]) {
                    // Rotate the corners by two, not swap them in pairs: the
                    // second is a mirror, and a mirrored mark is a different
                    // mark. This is what a code read upside down needs.
                    const q = flip ? [quad[2], quad[3], quad[0], quad[1]] : quad;
                    const map = projection(q);
                    if (!map) continue;
                    const prof = profile(labels, w, h, map, comp.id, steps, n);
                    const height = readHeights(prof);
                    if (!height) continue;
                    // A uniform edge bias shifts every height together, which is
                    // the one error Reed-Solomon cannot see past -- it corrupts
                    // all fifteen symbols at once. Cheap to just try either side.
                    for (const shift of [0, STEP * 0.3, -STEP * 0.3]) {
                        const hit = heightsToPath(height, shift);
                        if (hit) return hit;
                    }
                }
            }
        }
        return null;
    }

    const cache = new Map();
    return {
        STYLES,
        styleById,
        svg(path, styleId) {
            const key = styleId + ' ' + path;
            if (!cache.has(key)) cache.set(key, svg(path, styleId));
            return cache.get(key);
        },
        decodeImage,
        shorten(path) {
            for (const t of TYPES) if (path.startsWith(t.long)) return t.short + path.slice(t.long.length);
            return path;
        },
        expand(path) {
            for (const t of TYPES) if (path.startsWith(t.short)) return t.long + path.slice(t.short.length);
            return path;
        },
    };
})();

// --- A-Line in the share sheet ---------------------------------------------
// The sheet offers both codes for the same link. A-Line leads because the
// people being shared with are, overwhelmingly, already here -- but a QR is one
// tap away for the friend who has not installed APEX yet, and the plain link is
// always underneath both.
const ALINE_STYLE_KEY = 'apexALineStyle';

function currentALineStyle() {
    let saved = null;
    try { saved = localStorage.getItem(ALINE_STYLE_KEY); } catch { /* private mode */ }
    return ApexALine.STYLES.some(s => s.id === saved) ? saved : ApexALine.STYLES[0].id;
}

function renderALineStyleRow() {
    const row = document.getElementById('share-aline-styles');
    if (!row) return;
    const active = currentALineStyle();
    row.innerHTML = ApexALine.STYLES.map(s => {
        const on = s.id === active;
        // Inline handler rather than one delegated listener on the document:
        // the modal's own content div stops click propagation before it ever
        // gets there, so a delegated swatch would look right and do nothing.
        return `<button type="button" class="share-aline-swatch${on ? ' is-active' : ''}" role="radio" ` +
            `aria-checked="${on}" aria-label="${escapeHtmlText(s.name)}" title="${escapeHtmlText(s.name)}" ` +
            `data-aline-style="${s.id}" onclick="setALineStyle('${s.id}')" ` +
            `style="background:linear-gradient(160deg,${s.top},${s.body});` +
            `box-shadow:inset 0 0 0 3px ${s.bg},0 1px 3px rgba(13,27,42,.2)"></button>`;
    }).join('');
}

function setALineStyle(id) {
    if (!ApexALine.STYLES.some(s => s.id === id)) return;
    try { localStorage.setItem(ALINE_STYLE_KEY, id); } catch { /* private mode */ }
    renderALineStyleRow();
    const modal = document.getElementById('share-profile-modal');
    const path = modal && modal.dataset.sharePath;
    if (path) document.getElementById('share-profile-aline').innerHTML = ApexALine.svg(path, id);
}

function setShareCodeType(type) {
    const wanted = type === 'qr' ? 'qr' : 'aline';
    const modal = document.getElementById('share-profile-modal');
    modal.dataset.codeType = wanted;
    modal.querySelectorAll('.share-code-tab').forEach(tab => {
        const on = tab.dataset.code === wanted;
        tab.classList.toggle('is-active', on);
        tab.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    document.getElementById('share-profile-qr').classList.toggle('hidden', wanted !== 'qr');
    document.getElementById('share-profile-aline').classList.toggle('hidden', wanted !== 'aline');
    document.getElementById('share-aline-styles').classList.toggle('hidden', wanted !== 'aline');
    document.getElementById('share-modal-hint').textContent =
        wanted === 'aline' ? (modal.dataset.alineHint || '') : (modal.dataset.qrHint || '');
}

// One share modal, reused for anything with a public link (profiles, lounges).
// Only the heading, the hint lines and the path itself change between them.
function openShareModal({ heading, hint, path, codePath, shareTitle, copiedToast }) {
    const modal = document.getElementById('share-profile-modal');
    const link = `${window.location.origin}${path}`;
    const preferQr = modal.dataset.codeType === 'qr';

    document.getElementById('share-modal-title').textContent = heading;
    document.getElementById('share-profile-link-input').value = link;
    document.getElementById('share-profile-qr').innerHTML = ApexQR(link);
    // The A-Line is only ever read by APEX, so it carries the route alone --
    // "/l/12", not the whole origin. What that saves pays for the error
    // correction that makes it readable off a phone screen at arm's length.
    const encoded = codePath || ApexALine.shorten(path);
    const art = ApexALine.svg(encoded, currentALineStyle());
    document.getElementById('share-profile-aline').innerHTML = art;

    // A page with no id of its own (Home, a hashtag, a DM thread, a circuit
    // whose code has letters in it) gets a "link" A-Line instead: the server
    // hands out a number for the path. The A-Line tab opens straight away with
    // an empty frame and fills in when the number arrives; only if that fails
    // does the sheet fall back to the QR alone.
    const needsLink = !art && !!apiToken;
    const shareId = String(Math.random());
    modal.dataset.shareId = shareId;
    modal.dataset.hasALine = art || needsLink ? '1' : '';
    modal.querySelector('.share-code-switch').classList.toggle('hidden', !art && !needsLink);
    modal.dataset.sharePath = art ? encoded : '';
    modal.dataset.copiedToast = copiedToast || 'Link copied!';
    modal.dataset.alineHint = 'Scan with the camera in APEX search';
    modal.dataset.qrHint = hint;
    renderALineStyleRow();
    setShareCodeType((!art && !needsLink) || preferQr ? 'qr' : 'aline');

    if (needsLink) {
        const giveUp = () => {
            if (modal.dataset.shareId !== shareId) return;
            modal.dataset.hasALine = '';
            modal.querySelector('.share-code-switch').classList.add('hidden');
            setShareCodeType('qr');
        };
        linkALineFor(path).then(code => {
            if (modal.dataset.shareId !== shareId) return; // the sheet moved on
            const linked = code && ApexALine.svg(code, currentALineStyle());
            if (!linked) return giveUp();
            modal.dataset.sharePath = code;
            document.getElementById('share-profile-aline').innerHTML = linked;
        }).catch(giveUp);
    }

    const nativeBtn = document.getElementById('share-profile-native-btn');
    if (navigator.share) {
        nativeBtn.classList.remove('hidden');
        nativeBtn.onclick = () => {
            navigator.share({ title: shareTitle, url: link }).catch(() => {});
        };
    } else {
        nativeBtn.classList.add('hidden');
    }

    modal.classList.remove('hidden');
}

// Share Profile modal: a copyable link plus two locally generated codes.
// The link people copy is still /users/<handle> -- that is the readable one and
// the one that works everywhere. The A-Line beside it carries the numeric id,
// because a mark this size has room for a number and not a name.
function openShareProfileModal(username, userId) {
    openShareModal({
        heading: 'Share Profile',
        hint: 'Scan to open this profile',
        path: `/users/${username}`,
        codePath: Number.isInteger(userId) ? `/u/${userId}` : null,
        shareTitle: 'My APEX Profile',
        copiedToast: 'Profile link copied!'
    });
}

// Same modal for lounges -- the codes point at the lounge page, where a
// non-member lands on the join card.
function openShareLoungeModal(loungeId) {
    document.getElementById('lounge-menu-dropdown')?.classList.add('hidden');

    const id = loungeId || currentLoungeId;
    if (!id) return;

    const nameEl = document.getElementById('lounge-header-title');
    const loungeName = (nameEl && nameEl.textContent.trim()) || 'Lounge';

    openShareModal({
        heading: 'Share Lounge',
        hint: 'Scan to open this lounge',
        path: `/lounges/${id}`,
        shareTitle: `${loungeName} on APEX`,
        copiedToast: 'Lounge link copied!'
    });
}

// Share whatever page is open. Called by the share button in the Windows/Mac
// app's title bar (desktop/src-tauri/src/lib.rs evals it into this page), which
// has no idea what APEX is showing -- so the route decides. Pages with their own
// share button get exactly that sheet; every other page shares itself, and gets
// a "link" A-Line from openShareModal (so every page has one while you're
// logged in to APEX).
function openSharePageModal() {
    const [, section, id] = window.location.pathname.split('/');
    // Keep the query (a search's ?q=) but not the account switcher's apex_acct.
    const params = new URLSearchParams(window.location.search);
    params.delete('apex_acct');
    const query = params.toString();
    const path = window.location.pathname + (query ? `?${query}` : '');

    if (section === 'users') {
        // /users/me would send whoever scans it to THEIR own profile.
        const name = decodeURIComponent(id || 'me');
        const isMe = name === 'me' || name === profileData.me.username;
        const user = profileData[isMe ? 'me' : name] || {};
        openShareProfileModal(user.username || (isMe ? profileData.me.username : name), user.id);
        return;
    }
    if (section === 'lounges' && /^\d+$/.test(id || '')) {
        openShareLoungeModal(Number(id));
        return;
    }
    const kinds = {
        posts: ['Share Post', 'Scan to open this post', 'A post on APEX'],
        circuits: ['Share Circuit', 'Scan to open this circuit', 'A circuit on APEX'],
        articles: ['Share Article', 'Scan to open this article', 'An article on APEX'],
    };
    if (id && kinds[section]) {
        const [heading, hint, shareTitle] = kinds[section];
        openShareModal({ heading, hint, path, shareTitle, copiedToast: 'Link copied!' });
        return;
    }
    // "APEX - Home" -> "Share Home".
    const pageName = (document.title || '').replace(/^APEX\s*[-|·:]\s*/i, '').trim();
    openShareModal({
        heading: pageName && !/^apex$/i.test(pageName) ? `Share ${pageName}` : 'Share Page',
        hint: 'Scan to open this page', path,
        shareTitle: document.title || 'APEX', copiedToast: 'Link copied!',
    });
}

// --- Send a post ------------------------------------------------------------
//
// The paper plane beside the heart. A post's link is the thing being sent, and
// what travels is an ordinary DM carrying that link -- no new message type, no
// server change -- which the chat then draws as a post card, the same way it
// already draws a card for an @mention or an outside URL (see buildPostCard).
//
// The two rows at the bottom hand the same link to the share sheet every other
// shareable thing in APEX uses, so "send it to Min" and "put it in a group chat
// somewhere else" are one control rather than two.
let sendPostState = { postId: null, people: [], sent: new Set() };
let sendPostListenersBound = false;

function postShareLink(postId) {
    return `${window.location.origin}/posts/${postId}`;
}

function openSendPostSheet(postId) {
    if (!Number.isInteger(postId)) return;
    const modal = document.getElementById('send-post-modal');
    const list = document.getElementById('send-post-list');
    const search = document.getElementById('send-post-search');
    if (!modal || !list) return;

    // A fresh sheet every time: "Sent" ticks belong to the post that was open
    // when they were earned, not to the next one.
    sendPostState = { postId, people: [], sent: new Set() };
    search.value = '';
    list.innerHTML = '<li class="new-chat-empty">Loading people…</li>';

    if (!sendPostListenersBound) {
        sendPostListenersBound = true;
        search.addEventListener('input', () => renderSendPostList(search.value));
        search.addEventListener('keydown', e => { if (e.key === 'Enter') e.preventDefault(); });
        list.addEventListener('click', (event) => {
            const row = event.target.closest('.send-post-row');
            if (row && !row.disabled) sendPostToUser(row.dataset.username, row);
        });
        modal.querySelector('.send-post-footer').addEventListener('click', (event) => {
            const btn = event.target.closest('.send-post-alt');
            if (!btn) return;
            if (btn.dataset.act === 'copy') {
                const link = postShareLink(sendPostState.postId);
                closeSendPostSheet();
                navigator.clipboard.writeText(link)
                    .then(() => showToast('Post link copied!', 'success'))
                    .catch(() => showToast('Could not copy the link.', 'error'));
            } else {
                const id = sendPostState.postId;
                closeSendPostSheet();
                openShareModal({
                    heading: 'Share Post',
                    hint: 'Scan to open this post',
                    path: `/posts/${id}`,
                    codePath: `/p/${id}`,
                    shareTitle: 'A post on APEX',
                    copiedToast: 'Post link copied!'
                });
            }
        });
    }

    modal.classList.remove('hidden');
    pushModalHistory('send-post-modal', closeSendPostSheet);

    fetch(`${API_BASE_URL}/api/users/for-chat`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json())
    .then(users => {
        // Dropped if the sheet was closed, or reopened on another post, while
        // this was in flight.
        if (sendPostState.postId !== postId) return;
        sendPostState.people = (Array.isArray(users) ? users : [])
            .filter(u => u && u.username && u.username !== profileData.me.username);
        sendPostState.people.forEach(u => {
            if (!profileData[u.username]) profileData[u.username] = { name: u.fullName, ...u };
        });
        // People you actually talk to first. The endpoint is already ordered by
        // relevance, which is the right answer for everyone below that line.
        sendPostState.people.sort((a, b) => {
            const at = profileData[a.username]?.lastMessageTime;
            const bt = profileData[b.username]?.lastMessageTime;
            return (bt ? new Date(bt).getTime() : 0) - (at ? new Date(at).getTime() : 0);
        });
        renderSendPostList(document.getElementById('send-post-search').value);
    })
    .catch(() => {
        if (sendPostState.postId !== postId) return;
        list.innerHTML = '<li class="new-chat-empty">Could not load your people. The link below still works.</li>';
    });
}

function renderSendPostList(query) {
    const list = document.getElementById('send-post-list');
    if (!list) return;
    const term = (query || '').trim().toLowerCase();
    const people = term
        ? sendPostState.people.filter(u =>
            (u.username || '').toLowerCase().includes(term) ||
            (u.fullName || '').toLowerCase().includes(term))
        : sendPostState.people;

    list.innerHTML = '';
    if (!sendPostState.people.length) {
        list.innerHTML = '<li class="new-chat-empty">Nobody to send this to yet.</li>';
        return;
    }
    if (!people.length) {
        list.innerHTML = '<li class="new-chat-empty">No people match that search.</li>';
        return;
    }

    people.forEach(user => {
        const done = sendPostState.sent.has(user.username);
        const li = document.createElement('li');
        li.innerHTML = `
            <button type="button" class="send-post-row${done ? ' is-sent' : ''}"
                    data-username="${user.username}" ${done ? 'disabled' : ''}>
                <div class="profile-pic" data-user-pic-id="${user.username}"></div>
                <div class="user-info">
                    <span class="username"></span>
                    <span class="fullname">@${user.username}</span>
                </div>
                <span class="send-post-row-action">${done ? 'Sent' : 'Send'}</span>
            </button>`;
        // textContent, then the rank mark: a display name is raw user input.
        const name = li.querySelector('.username');
        name.textContent = user.fullName || user.username;
        name.insertAdjacentHTML('beforeend', ` ${rankIconFor(user.username, user.rank)}`);
        list.appendChild(li);
        updateProfilePictures(user.username);
    });
}

// Through the outbox, exactly like a typed message: a send that fails on a bad
// connection is retried rather than silently dropped, and the thread's own
// optimistic bubble appears if that chat happens to be open.
function sendPostToUser(username, row) {
    if (!username || !sendPostState.postId) return;
    const link = postShareLink(sendPostState.postId);
    const tempId = `temp_${Date.now()}_${username}`;

    if (!messageHistory[username]) messageHistory[username] = [];
    messageHistory[username].push({
        id: tempId, sender: 'me', text: link, image: null,
        time: new Date(), reply_to_id: null, reply_to: null
    });
    if (profileData[username]) {
        profileData[username].lastMessage = 'You sent a post.';
        profileData[username].lastMessageTime = new Date();
    }
    if (currentChatRecipient === username) renderChatMessages(false, true);
    renderChatList();

    enqueueOutbox({
        id: tempId,
        kind: 'dm',
        target: username,
        body: { to_username: username, message: link, image: null,
                reply_to_id: null, poll: null, client_id: tempId },
        view: { text: link, effect: null, replyTo: null }
    });

    sendPostState.sent.add(username);
    if (row) {
        row.disabled = true;
        row.classList.add('is-sent');
        row.querySelector('.send-post-row-action').textContent = 'Sent';
    }
}

function closeSendPostSheet() {
    const modal = document.getElementById('send-post-modal');
    if (!modal || modal.classList.contains('hidden')) return;
    modal.classList.add('hidden');
    sendPostState = { postId: null, people: [], sent: new Set() };
    popModalHistory('send-post-modal');
}

// The modal and the single-post page draw their send button outside any grid,
// so those clicks never reach handleGridClick.
document.addEventListener('click', (event) => {
    const btn = event.target.closest('.send-post-button');
    if (!btn) return;
    event.preventDefault();
    openSendPostSheet(parseInt(btn.dataset.sendPostId, 10));
});

// --- Post comments ------------------------------------------------------------
// One sheet for every place a post is drawn. On a phone it is a bottom sheet;
// on desktop it docks to the right of the post lightbox (or the right edge of
// the window on the single-post page). Top-level comments oldest first, paged
// in as the list scrolls, each with its replies one level beneath it. See the
// "Post comments" block in server.py.
const postCommentsState = {
    postId: null,
    byId: new Map(),     // every loaded comment and reply, by id
    nextAfter: null,     // cursor for the next page of top-level comments
    total: 0,            // comments + replies, as the server counts them
    loading: false,
    gen: 0,              // bumped per open so a slow response for another post is dropped
    replyTo: null,       // { rootId, name } while replying
    editing: null,       // the comment being edited
    quietUntil: 0,       // our own change is already on screen; skip its echo
};
let postCommentsObserver = null;
let postCommentsCloseTimer = 0;
let postCommentErrorTimer = 0;
const POST_COMMENT_MAX = 500;

// Same as the send button: the lightbox and the single-post page draw their
// comment button outside any grid, so those clicks never reach handleGridClick.
document.addEventListener('click', (event) => {
    const btn = event.target.closest('.comment-post-button');
    if (!btn) return;
    event.preventDefault();
    openPostComments(parseInt(btn.dataset.commentPostId, 10));
});

function setPostCommentCount(postId, count) {
    document.querySelectorAll(`[data-comment-count-id="${postId}"]`).forEach(el => {
        el.textContent = count ? count : '';
    });
    // The in-memory copies too, so the next re-render of a card or the
    // lightbox doesn't put the old number back.
    [getModalPosts(), currentCircuitPosts].forEach(list => {
        (list || []).forEach(p => { if (p && p.id === postId) p.comments = count; });
    });
    if (postCommentsState.postId === postId) {
        postCommentsState.total = count;
        const badge = document.getElementById('pc-count');
        if (badge) badge.textContent = count ? count : '';
    }
}

function postCommentsOpen() {
    const modal = document.getElementById('post-comments-modal');
    return !!modal && !modal.classList.contains('hidden') && !modal.classList.contains('is-closing');
}

// Docked beside the post on anything that isn't a phone.
function postCommentsShouldDock() {
    return !isPhoneLayout();
}

function openPostComments(postId) {
    if (!postId || !apiToken) return;
    const modal = document.getElementById('post-comments-modal');
    if (!modal) return;
    const st = postCommentsState;

    // The button again on a docked panel for the same post: put it away.
    if (st.postId === postId && postCommentsOpen() && modal.classList.contains('is-docked')) {
        closePostComments();
        return;
    }

    clearTimeout(postCommentsCloseTimer);
    modal.classList.remove('is-closing');

    const samePost = st.postId === postId && postCommentsOpen();
    if (!samePost) {
        st.postId = postId;
        st.byId = new Map();
        st.nextAfter = null;
        st.total = 0;
        st.loading = false;
        st.gen++;
        st.replyTo = null;
        st.editing = null;
        document.getElementById('pc-count').textContent = '';
        document.getElementById('pc-list').innerHTML = postCommentSkeletonHtml(4);
        document.getElementById('pc-input').value = '';
        syncPostCommentContext();
        showPostCommentError('');
        closePostCommentTray();
    }

    initPostCommentsUi();

    const docked = postCommentsShouldDock();
    modal.classList.toggle('is-docked', docked);
    const postModal = document.getElementById('post-modal');
    const beside = docked && postModal && !postModal.classList.contains('hidden');
    postModal?.classList.toggle('has-comments', beside);
    modal.classList.toggle('is-page-docked', docked && !beside);

    // Every open starts at the regular height, whatever the last drag left.
    const sheet = modal.querySelector('.pc-sheet');
    sheet.style.height = '';
    sheet.style.transition = '';
    sheet.style.transform = '';
    modal.style.backgroundColor = '';
    modal.style.transition = '';

    modal.classList.remove('hidden');
    pushModalHistory('post-comments-modal', closePostComments);
    // After it is on screen: measured while hidden, the field reads as 0px tall.
    requestAnimationFrame(syncPostCommentComposer);
    if (docked && shouldAutoFocus()) {
        setTimeout(() => document.getElementById('pc-input')?.focus({ preventScroll: true }), 60);
    }
    if (!samePost) loadPostComments(true);
}

function closePostComments(opts) {
    const modal = document.getElementById('post-comments-modal');
    if (!modal || modal.classList.contains('hidden') || modal.classList.contains('is-closing')) return;
    document.getElementById('pc-input').blur();
    closePostCommentTray();
    popModalHistory('post-comments-modal');
    document.getElementById('post-modal')?.classList.remove('has-comments');

    // Instant when a drag has already carried the sheet off screen.
    const animate = !(opts && opts.instant) &&
        !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!animate) {
        modal.classList.add('hidden');
        modal.classList.remove('is-docked', 'is-page-docked');
        return;
    }
    modal.classList.add('is-closing');
    postCommentsCloseTimer = setTimeout(() => {
        modal.classList.add('hidden');
        modal.classList.remove('is-closing', 'is-docked', 'is-page-docked');
    }, 260);
}

// The lightbox paged to another post while the thread is docked beside it:
// the thread follows.
function syncDockedCommentsToPost(postId) {
    const modal = document.getElementById('post-comments-modal');
    if (!postCommentsOpen() || !modal.classList.contains('is-docked')) return;
    if (postCommentsState.postId !== postId) openPostComments(postId);
}

function initPostCommentsUi() {
    if (postCommentsObserver !== null) return;
    const list = document.getElementById('pc-list');
    const input = document.getElementById('pc-input');
    if (!list || !input) return;

    input.addEventListener('input', () => {
        syncPostCommentComposer();
        showPostCommentError('');
    });
    // Enter sends and Shift+Enter breaks the line, on a keyboard. A phone's
    // return key stays a newline -- the send button is right there.
    input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey && !e.isComposing && !isTouchInput()) {
            e.preventDefault();
            submitPostComment();
        } else if (e.key === 'Escape' && (postCommentsState.replyTo || postCommentsState.editing)) {
            e.preventDefault();
            e.stopPropagation();
            clearPostCommentContext();
        }
    });

    list.addEventListener('click', (e) => {
        const act = e.target.closest('.pc-act');
        if (act) {
            e.stopPropagation();
            const row = act.closest('.pc-row');
            const comment = postCommentsState.byId.get(Number(row?.dataset.id));
            if (!comment) return;
            if (act.dataset.act === 'reply') startPostCommentReply(comment);
            else if (act.dataset.act === 'edit') startPostCommentEdit(comment);
            else if (act.dataset.act === 'delete') armPostCommentDelete(act, comment);
            return;
        }
        const more = e.target.closest('.pc-more-replies');
        if (more) {
            loadMorePostCommentReplies(Number(more.dataset.root), more);
            return;
        }
        const fresh = e.target.closest('.pc-refresh');
        if (fresh) {
            reloadPostComments();
            return;
        }
        const author = e.target.closest('.pc-author');
        if (author) {
            e.preventDefault();
            navigateFromPostComments(`/users/${author.dataset.username}`);
        }
    });
    // An @mention in a comment. Caught on the way down, ahead of the link's own
    // handler, which would close only this sheet and leave the post open over
    // the profile it navigated to.
    list.addEventListener('click', (e) => {
        const mention = e.target.closest('.user-mention');
        if (!mention) return;
        e.preventDefault();
        e.stopPropagation();
        navigateFromPostComments(`/users/${mention.dataset.username}`);
    }, { capture: true });

    // Emoji / sticker buttons and the tray.
    document.querySelectorAll('#pc-composer .pc-tool').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            togglePostCommentTray(btn.dataset.tray);
        });
    });
    document.querySelectorAll('#pc-tray .pc-tray-tab').forEach(tab => {
        tab.addEventListener('click', () => showPostCommentTrayTab(tab.dataset.tab));
    });
    const traySearch = document.getElementById('pc-tray-search');
    let trayTimer = 0;
    traySearch.addEventListener('input', () => {
        clearTimeout(trayTimer);
        trayTimer = setTimeout(renderPostCommentTray, 250);
    });

    window.addEventListener('resize', () => {
        // Crossing between phone and desktop layouts with the thread open.
        if (!postCommentsOpen()) return;
        const modal = document.getElementById('post-comments-modal');
        const docked = postCommentsShouldDock();
        if (docked === modal.classList.contains('is-docked')) return;
        const postModal = document.getElementById('post-modal');
        const beside = docked && postModal && !postModal.classList.contains('hidden');
        modal.classList.toggle('is-docked', docked);
        modal.classList.toggle('is-page-docked', docked && !beside);
        postModal?.classList.toggle('has-comments', beside);
    });

    initPostCommentsDrag();

    postCommentsObserver = 'IntersectionObserver' in window
        ? new IntersectionObserver(entries => {
            if (entries.some(en => en.isIntersecting)) loadPostComments(false);
        }, { root: list, rootMargin: '0px 0px 240px 0px' })
        : false;
}

// --- Dragging the phone sheet ------------------------------------------------------
// Same feel as the other bottom sheets (initSheetDragToDismiss): hold the top of
// the sheet and it follows the finger. Downward the whole sheet slides 1:1 and the
// backdrop fades with it; let go past a third of the way, or flick, and it closes,
// otherwise it springs back. Upward it grows taller, up to nearly the full screen,
// and stays there if let go closer to tall than to regular -- the one thing this
// sheet has that the short menus don't: more thread above to reveal.
//
// From the list, a drag takes the sheet only where the list itself has nowhere to
// go: pulling down while already scrolled to the top, or pushing up while the
// sheet isn't tall yet. Growing is height, not a transform, so the composer rides
// along at the bottom instead of sliding off screen.
const PC_SHEET_REGULAR = 0.84;   // of the viewport; matches the CSS default
const PC_SHEET_TALL = 0.95;
const PC_SHEET_BACKDROP = 0.55;  // the modal's own rgba(10,16,34,0.55)

function initPostCommentsDrag() {
    const modal = document.getElementById('post-comments-modal');
    const sheet = modal.querySelector('.pc-sheet');
    const head = sheet.querySelector('.pc-head');
    const list = document.getElementById('pc-list');
    let drag = null;

    const viewport = () => (window.visualViewport ? window.visualViewport.height : window.innerHeight);
    const draggable = () => isPhoneLayout() && !modal.classList.contains('is-docked') &&
        !modal.classList.contains('is-closing');

    const start = (e, fromList) => {
        if (!draggable() || e.touches.length !== 1) return;
        const t = e.touches[0];
        drag = {
            fromList,
            startY: t.clientY,
            startX: t.clientX,
            startH: sheet.getBoundingClientRect().height,
            lastY: t.clientY,
            lastT: e.timeStamp,
            v: 0,
            offset: 0,        // how far the sheet is slid down
            active: false,    // decided once the finger has moved far enough
        };
    };

    const move = (e) => {
        if (!drag) return;
        const t = e.touches[0];
        const dy = t.clientY - drag.startY;
        const dx = t.clientX - drag.startX;
        if (!drag.active) {
            if (Math.abs(dy) < SHEET_DRAG_START_PX && Math.abs(dx) < SHEET_DRAG_START_PX) return;
            // Sideways is not ours.
            if (Math.abs(dx) > Math.abs(dy)) { drag = null; return; }
            if (drag.fromList) {
                const atTop = list.scrollTop <= 0;
                const tall = drag.startH >= viewport() * PC_SHEET_TALL - 4;
                if (!((dy > 0 && atTop) || (dy < 0 && !tall))) { drag = null; return; }
            }
            drag.active = true;
            drag.startY = t.clientY;   // no jump by the slop distance
            sheet.style.transition = 'none';
            modal.style.transition = 'none';
            document.getElementById('pc-input').blur();
        }
        e.preventDefault();

        const d = t.clientY - drag.startY;
        const vh = viewport();
        if (d >= 0) {
            // Down: slide the whole sheet, the backdrop fading as it goes.
            drag.offset = d;
            sheet.style.height = `${drag.startH}px`;
            sheet.style.transform = `translateY(${d}px)`;
            const progress = Math.min(1, d / drag.startH);
            modal.style.backgroundColor = `rgba(10, 16, 34, ${PC_SHEET_BACKDROP * (1 - progress)})`;
        } else {
            // Up: grow, 1:1 until tall, then a little damped give.
            drag.offset = 0;
            sheet.style.transform = '';
            modal.style.backgroundColor = '';
            const want = drag.startH - d;
            const cap = vh * PC_SHEET_TALL;
            const h = want <= cap ? want : cap + Math.min(16, Math.sqrt(want - cap) * 2);
            sheet.style.height = `${h}px`;
        }

        const dt = Math.max(1, e.timeStamp - drag.lastT);
        drag.v = (t.clientY - drag.lastY) / dt;   // px/ms, positive = downward
        drag.lastY = t.clientY;
        drag.lastT = e.timeStamp;
    };

    const end = () => {
        if (!drag) return;
        const d = drag;
        drag = null;
        if (!d.active) return;
        const vh = viewport();
        const spring = 'cubic-bezier(0.22, 1, 0.36, 1)';

        // Pulled down far enough, or flicked: slide the rest of the way out from
        // where the finger left it, then close without a second animation.
        if (d.offset > 0 && (d.offset > d.startH * SHEET_DISMISS_FRACTION || d.v > SHEET_DISMISS_VELOCITY)) {
            sheet.style.transition = `transform 0.22s ${spring}`;
            modal.style.transition = 'background-color 0.22s ease';
            sheet.style.transform = `translateY(${d.startH + 40}px)`;
            modal.style.backgroundColor = 'rgba(10, 16, 34, 0)';
            setTimeout(() => closePostComments({ instant: true }), 220);
            return;
        }

        // Otherwise settle: back into place, at the regular or the tall height.
        const h = sheet.getBoundingClientRect().height;
        let target;
        if (d.offset > 0) target = PC_SHEET_REGULAR;
        else if (d.v < -0.4) target = PC_SHEET_TALL;
        else if (d.v > 0.4) target = PC_SHEET_REGULAR;
        else target = Math.abs(h - vh * PC_SHEET_TALL) < Math.abs(h - vh * PC_SHEET_REGULAR)
            ? PC_SHEET_TALL : PC_SHEET_REGULAR;
        sheet.style.transition = `transform 0.3s ${spring}, height 0.3s ${spring}`;
        modal.style.transition = 'background-color 0.3s ease';
        sheet.style.transform = '';
        modal.style.backgroundColor = '';
        sheet.style.height = `${Math.round(vh * target)}px`;
    };

    head.addEventListener('touchstart', e => start(e, false), { passive: true });
    list.addEventListener('touchstart', e => start(e, true), { passive: true });
    // Non-passive: once the drag is ours, the list must not scroll underneath it.
    sheet.addEventListener('touchmove', move, { passive: false });
    sheet.addEventListener('touchend', end);
    sheet.addEventListener('touchcancel', end);
}

// Leave the thread for a page. When the sheet sits over the post lightbox, the
// lightbox goes too -- closing it drops every modal stacked above it.
function navigateFromPostComments(path) {
    const postModal = document.getElementById('post-modal');
    const anchor = postModal && !postModal.classList.contains('hidden')
        ? document.getElementById('modal-content')
        : document.getElementById('pc-list');
    navigateFromModal(anchor, path);
}

function showPostCommentError(message) {
    const el = document.getElementById('pc-error');
    if (!el) return;
    el.textContent = message;
    el.hidden = !message;
    clearTimeout(postCommentErrorTimer);
    if (message) postCommentErrorTimer = setTimeout(() => { el.hidden = true; }, 6000);
}

function syncPostCommentComposer() {
    const input = document.getElementById('pc-input');
    const send = document.getElementById('pc-send');
    const counter = document.getElementById('pc-counter');
    if (!input) return;
    // Grow with the text up to a few lines, then scroll inside. Never below one
    // line: a field measured while its sheet is hidden reports 0.
    input.style.height = 'auto';
    const h = input.scrollHeight;
    input.style.height = h ? Math.max(40, Math.min(h, 120)) + 'px' : '';
    const len = input.value.trim().length;
    const editingSticker = postCommentsState.editing && postCommentsState.editing.sticker_url;
    send.disabled = (!len && !editingSticker) || input.value.length > POST_COMMENT_MAX;
    // Only worth showing once it is close to mattering.
    const left = POST_COMMENT_MAX - input.value.length;
    counter.textContent = left <= 60 ? String(left) : '';
    counter.classList.toggle('is-over', left < 0);
}

// --- Reply / edit context ------------------------------------------------------
function syncPostCommentContext() {
    const st = postCommentsState;
    const bar = document.getElementById('pc-context');
    const text = document.getElementById('pc-context-text');
    const input = document.getElementById('pc-input');
    const send = document.getElementById('pc-send');
    if (st.editing) {
        text.innerHTML = '<i class="fas fa-pen"></i> Editing your comment';
    } else if (st.replyTo) {
        text.innerHTML = `<i class="fas fa-reply"></i> Replying to <b>${escapeHtmlText(st.replyTo.name)}</b>`;
    }
    bar.hidden = !(st.editing || st.replyTo);
    input.placeholder = st.editing ? 'Edit your comment…'
        : st.replyTo ? `Reply to ${st.replyTo.name}…` : 'Add a comment…';
    send.setAttribute('aria-label', st.editing ? 'Save comment' : 'Post comment');
    send.innerHTML = st.editing ? '<i class="fas fa-check"></i>' : '<i class="fas fa-arrow-up"></i>';
    document.querySelectorAll('#pc-list .pc-row.is-target').forEach(r => r.classList.remove('is-target'));
    const targetId = st.editing ? st.editing.id : st.replyTo ? st.replyTo.id : null;
    if (targetId) {
        document.querySelector(`#pc-list .pc-row[data-id="${targetId}"]`)?.classList.add('is-target');
    }
    // A sticker can't be edited into a comment, so the sticker button rests.
    document.querySelector('#pc-composer .pc-tool[data-tray="stickers"]').disabled = !!st.editing;
}

function clearPostCommentContext() {
    const st = postCommentsState;
    const wasEditing = !!st.editing;
    st.replyTo = null;
    st.editing = null;
    if (wasEditing) document.getElementById('pc-input').value = '';
    syncPostCommentContext();
    syncPostCommentComposer();
}

function focusPostCommentInput() {
    const input = document.getElementById('pc-input');
    input.focus({ preventScroll: true });
    const end = input.value.length;
    try { input.setSelectionRange(end, end); } catch (e) { /* not focusable yet */ }
}

function startPostCommentReply(comment) {
    const st = postCommentsState;
    const input = document.getElementById('pc-input');
    if (st.editing) input.value = '';
    st.editing = null;
    const name = (comment.author && (comment.author.fullName || comment.author.username)) || 'comment';
    st.replyTo = { id: comment.id, rootId: comment.parent_id || comment.id, name };
    // Replying under a reply: name who you're answering, since the thread
    // itself only says which top-level comment it belongs to.
    const handle = comment.author && comment.author.username;
    if (comment.parent_id && handle && !comment.is_mine && !input.value.includes(`@${handle}`)) {
        input.value = `@${handle} ` + input.value;
    }
    syncPostCommentContext();
    syncPostCommentComposer();
    focusPostCommentInput();
}

function startPostCommentEdit(comment) {
    const st = postCommentsState;
    st.replyTo = null;
    st.editing = comment;
    document.getElementById('pc-input').value = comment.text || '';
    closePostCommentTray();
    syncPostCommentContext();
    syncPostCommentComposer();
    focusPostCommentInput();
}

// --- Loading and drawing ---------------------------------------------------------
function postCommentSkeletonHtml(rows) {
    return Array.from({ length: rows }, () => `
        <li class="pc-skeleton" aria-hidden="true">
            <span class="pc-skel-avatar"></span>
            <span class="pc-skel-lines"><span></span><span></span></span>
        </li>`).join('');
}

function reloadPostComments() {
    const st = postCommentsState;
    st.byId = new Map();
    st.nextAfter = null;
    st.loading = false;
    st.gen++;
    loadPostComments(true);
}

function loadPostComments(first) {
    const st = postCommentsState;
    if (st.loading || !st.postId) return;
    if (!first && !st.nextAfter) return;
    st.loading = true;
    const gen = st.gen;
    const params = new URLSearchParams();
    if (!first && st.nextAfter) params.set('after', String(st.nextAfter));

    fetch(`${API_BASE_URL}/api/post/${st.postId}/comments?${params}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (gen !== st.gen) return;
        if (!ok) throw new Error(body.error || 'load failed');
        const list = document.getElementById('pc-list');
        if (first) list.innerHTML = '';
        const fresh = (body.comments || []).filter(c => !st.byId.has(c.id));
        st.nextAfter = body.next_after || null;
        setPostCommentCount(st.postId, body.total || 0);
        appendPostCommentThreads(fresh);
        if (first && !fresh.length) renderPostCommentsEmpty();
    })
    .catch(err => {
        console.error('Could not load comments:', err);
        if (gen === st.gen && first) {
            document.getElementById('pc-list').innerHTML =
                `<li class="pc-empty"><b>Couldn't load comments</b><span>Check your connection and try again.</span></li>`;
        }
    })
    .finally(() => {
        if (gen === st.gen) {
            st.loading = false;
            syncPostCommentSentinel();
        }
    });
}

function renderPostCommentsEmpty() {
    document.getElementById('pc-list').innerHTML = `
        <li class="pc-empty">
            <span class="pc-empty-icon"><i class="far fa-comment"></i></span>
            <b>No comments yet</b>
            <span>Start the conversation.</span>
        </li>`;
}

// The list's children are threads: a top-level comment and the replies under
// it. New threads always go before the sentinel, so the loader stays last.
function appendPostCommentThreads(roots) {
    const list = document.getElementById('pc-list');
    if (!list || !roots.length) return;
    list.querySelector('.pc-empty')?.remove();
    const missing = new Set();
    const before = list.querySelector('.pc-sentinel');
    roots.forEach(root => {
        list.insertBefore(buildPostCommentThread(root, missing), before);
    });
    finishPostCommentPaint(missing);
    syncPostCommentSentinel();
}

function buildPostCommentThread(root, missing) {
    const st = postCommentsState;
    const li = document.createElement('li');
    li.className = 'pc-thread';
    li.dataset.root = root.id;
    st.byId.set(root.id, root);
    li.appendChild(buildPostCommentRow(root, missing));

    const replies = document.createElement('ul');
    replies.className = 'pc-replies';
    (root.replies || []).forEach(r => {
        st.byId.set(r.id, r);
        replies.appendChild(buildPostCommentRow(r, missing));
    });
    li.appendChild(replies);
    root.loadedReplies = (root.replies || []).length;
    syncMoreRepliesButton(li, root);
    return li;
}

function syncMoreRepliesButton(thread, root) {
    let btn = thread.querySelector(':scope > .pc-more-replies');
    const remaining = (root.reply_count || 0) - (root.loadedReplies || 0);
    if (remaining <= 0) {
        btn?.remove();
        return;
    }
    if (!btn) {
        btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'pc-more-replies';
        btn.dataset.root = root.id;
        thread.appendChild(btn);
    }
    btn.disabled = false;
    btn.innerHTML = `<span class="pc-more-line"></span>View ${remaining} more ${remaining === 1 ? 'reply' : 'replies'}`;
}

function loadMorePostCommentReplies(rootId, btn) {
    const st = postCommentsState;
    const root = st.byId.get(rootId);
    const thread = document.querySelector(`#pc-list .pc-thread[data-root="${rootId}"]`);
    if (!root || !thread) return;
    const gen = st.gen;
    const rows = thread.querySelectorAll('.pc-replies > .pc-row');
    const last = rows.length ? Number(rows[rows.length - 1].dataset.id) : 0;
    btn.disabled = true;
    btn.innerHTML = '<span class="pc-more-line"></span>Loading…';

    fetch(`${API_BASE_URL}/api/post-comments/${rootId}/replies?after=${last}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (gen !== st.gen) return;
        if (!ok) throw new Error(body.error || 'load failed');
        const missing = new Set();
        const box = thread.querySelector('.pc-replies');
        (body.replies || []).forEach(r => {
            if (st.byId.has(r.id)) return;
            st.byId.set(r.id, r);
            box.appendChild(buildPostCommentRow(r, missing));
            root.loadedReplies = (root.loadedReplies || 0) + 1;
        });
        if (!body.next_after) root.loadedReplies = Math.max(root.loadedReplies, root.reply_count || 0);
        finishPostCommentPaint(missing);
        syncMoreRepliesButton(thread, root);
    })
    .catch(() => {
        if (gen !== st.gen) return;
        showPostCommentError("Couldn't load replies. Try again.");
        syncMoreRepliesButton(thread, root);
    });
}

function finishPostCommentPaint(missing) {
    document.querySelectorAll('#pc-list [data-user-pic-id]').forEach(el => {
        const u = el.dataset.userPicId;
        if (u && !missing.has(u)) updateProfilePictures(u);
    });
    hydrateNotificationAvatars([...missing]);
    verifyMentions();
    paintRankSlots(document.getElementById('pc-list'));
}

function buildPostCommentRow(c, missing) {
    const row = document.createElement('div');
    row.className = 'pc-row' + (c.parent_id ? ' is-reply' : '');
    row.dataset.id = c.id;
    const username = (c.author && c.author.username) || '';
    const name = (c.author && (c.author.fullName || c.author.username)) || 'Unknown';
    const when = c.created_at ? new Date(c.created_at) : null;
    const time = when && !isNaN(when)
        ? `<time class="pc-time" datetime="${escapeHtmlText(c.created_at)}" title="${escapeHtmlText(when.toLocaleString())}">${notificationTimeLabel(when)}</time>`
        : '';
    const textHtml = c.text ? `<p class="pc-text">${linkifyUsernames(escapeHtmlText(c.text))}</p>` : '';
    const stickerHtml = c.sticker_url
        ? `<img class="pc-sticker" src="${escapeHtmlText(c.sticker_url)}" alt="Sticker" loading="lazy">` : '';

    row.innerHTML = `
        <a href="/users/${encodeURIComponent(username)}" class="pc-author pc-avatar" data-username="${escapeHtmlText(username)}" aria-label="${escapeHtmlText(name)}">
            <div class="profile-pic" data-user-pic-id="${escapeHtmlText(username)}"></div>
        </a>
        <div class="pc-body">
            <div class="pc-bubble${c.text ? '' : ' is-bare'}">
                <div class="pc-meta">
                    <a href="/users/${encodeURIComponent(username)}" class="pc-author pc-name" data-username="${escapeHtmlText(username)}">${escapeHtmlText(name)}</a>${rankIconFor(username, c.author && c.author.rank)}
                    ${c.is_post_author ? '<span class="pc-badge">Author</span>' : ''}
                </div>
                ${textHtml}
            </div>
            ${stickerHtml}
            <div class="pc-actions">
                ${time}
                ${c.edited_at ? '<span class="pc-edited">Edited</span>' : ''}
                <button type="button" class="pc-act" data-act="reply">Reply</button>
                ${c.can_edit ? '<button type="button" class="pc-act" data-act="edit">Edit</button>' : ''}
                ${c.can_delete ? '<button type="button" class="pc-act pc-act--danger" data-act="delete">Delete</button>' : ''}
            </div>
        </div>
    `;
    if (username && missing) {
        const cached = profileData[username];
        if (!(cached && (cached.profilePicUrl || cached.profile_pic))) missing.add(username);
    }
    return row;
}

// Everything that loads more sits at the bottom of the list: a skeleton while
// a page is coming, nothing once the whole thread is here.
function syncPostCommentSentinel() {
    const list = document.getElementById('pc-list');
    const st = postCommentsState;
    if (!list) return;
    let sentinel = list.querySelector('.pc-sentinel');
    if (!st.nextAfter || !list.querySelector('.pc-thread')) {
        sentinel?.remove();
        return;
    }
    if (!sentinel) {
        sentinel = document.createElement('li');
        sentinel.className = 'pc-sentinel';
        sentinel.innerHTML = `<ul class="pc-list-inner">${postCommentSkeletonHtml(2)}</ul>`;
        list.appendChild(sentinel);
        if (postCommentsObserver) postCommentsObserver.observe(sentinel);
    } else {
        list.appendChild(sentinel); // keep it last
    }
    // A short page can leave it already on screen, which the observer won't
    // report again on its own.
    requestAnimationFrame(() => {
        const s = list.querySelector('.pc-sentinel');
        if (!s) return;
        const lr = list.getBoundingClientRect();
        if (s.getBoundingClientRect().top < lr.bottom + 240) loadPostComments(false);
    });
}

// --- Writing ---------------------------------------------------------------------
function submitPostComment(extra) {
    const st = postCommentsState;
    const input = document.getElementById('pc-input');
    const send = document.getElementById('pc-send');
    if (!st.postId || send.dataset.busy) return;

    if (st.editing && !extra) return savePostCommentEdit();

    const text = extra ? '' : input.value.trim();
    const payload = { ...(extra || {}), text };
    if (!text && !payload.sticker_id) return;
    if (text.length > POST_COMMENT_MAX) {
        showPostCommentError(`A comment can be up to ${POST_COMMENT_MAX} characters.`);
        return;
    }
    if (st.replyTo) payload.parent_id = st.replyTo.rootId;

    const postId = st.postId;
    send.dataset.busy = '1';
    send.disabled = true;
    send.classList.add('is-busy');
    st.quietUntil = Date.now() + 2500;

    fetch(`${API_BASE_URL}/api/post/${postId}/comments`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(payload)
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (!ok || !body.comment) {
            showPostCommentError(body.error || 'Could not post your comment.');
            return;
        }
        if (st.postId !== postId) return;
        if (!extra) input.value = '';
        st.replyTo = null;
        syncPostCommentContext();
        const row = placeNewPostComment(body.comment);
        setPostCommentCount(postId, st.total + 1);
        if (row) {
            row.classList.add('is-new');
            row.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
        }
    })
    .catch(() => showPostCommentError('Could not post your comment.'))
    .finally(() => {
        delete send.dataset.busy;
        send.classList.remove('is-busy');
        syncPostCommentComposer();
    });
}

// Puts a comment we just wrote where it belongs: a reply at the end of its
// thread, a top-level comment at the end of the list.
function placeNewPostComment(c) {
    const st = postCommentsState;
    if (st.byId.has(c.id)) return document.querySelector(`#pc-list .pc-row[data-id="${c.id}"]`);
    const missing = new Set();
    let row = null;
    if (c.parent_id) {
        const root = st.byId.get(c.parent_id);
        const thread = document.querySelector(`#pc-list .pc-thread[data-root="${c.parent_id}"]`);
        if (!root || !thread) return null;
        st.byId.set(c.id, c);
        row = buildPostCommentRow(c, missing);
        thread.querySelector('.pc-replies').appendChild(row);
        root.reply_count = (root.reply_count || 0) + 1;
        root.loadedReplies = (root.loadedReplies || 0) + 1;
        syncMoreRepliesButton(thread, root);
    } else {
        c.replies = [];
        c.reply_count = 0;
        appendPostCommentThreads([c]);
        row = document.querySelector(`#pc-list .pc-row[data-id="${c.id}"]`);
    }
    finishPostCommentPaint(missing);
    return row;
}

function savePostCommentEdit() {
    const st = postCommentsState;
    const comment = st.editing;
    const input = document.getElementById('pc-input');
    const send = document.getElementById('pc-send');
    const text = input.value.trim();
    if (!comment) return;
    if (text.length > POST_COMMENT_MAX) {
        showPostCommentError(`A comment can be up to ${POST_COMMENT_MAX} characters.`);
        return;
    }
    send.dataset.busy = '1';
    send.disabled = true;
    send.classList.add('is-busy');
    st.quietUntil = Date.now() + 2500;

    fetch(`${API_BASE_URL}/api/post-comments/${comment.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ text })
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (!ok || !body.comment) {
            showPostCommentError(body.error || 'Could not save your edit.');
            return;
        }
        const updated = { ...comment, ...body.comment };
        st.byId.set(updated.id, updated);
        const old = document.querySelector(`#pc-list .pc-row[data-id="${updated.id}"]`);
        if (old) {
            const missing = new Set();
            const fresh = buildPostCommentRow(updated, missing);
            fresh.classList.add('is-new');
            old.replaceWith(fresh);
            finishPostCommentPaint(missing);
        }
        st.editing = null;
        input.value = '';
        syncPostCommentContext();
    })
    .catch(() => showPostCommentError('Could not save your edit.'))
    .finally(() => {
        delete send.dataset.busy;
        send.classList.remove('is-busy');
        syncPostCommentComposer();
    });
}

// Two taps: the first turns "Delete" red and asks, the second deletes. No
// dialog to stack over the sheet, and no one-tap accidents.
function armPostCommentDelete(btn, comment) {
    if (btn.classList.contains('is-armed')) {
        deletePostComment(btn, comment);
        return;
    }
    btn.classList.add('is-armed');
    btn.textContent = comment.reply_count ? 'Delete with replies?' : 'Delete?';
    clearTimeout(btn._disarm);
    btn._disarm = setTimeout(() => {
        btn.classList.remove('is-armed');
        btn.textContent = 'Delete';
    }, 3000);
}

function deletePostComment(btn, comment) {
    const st = postCommentsState;
    clearTimeout(btn._disarm);
    btn.disabled = true;
    st.quietUntil = Date.now() + 2500;

    fetch(`${API_BASE_URL}/api/post-comments/${comment.id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (!ok) {
            btn.disabled = false;
            showPostCommentError(body.error || 'Could not delete that comment.');
            return;
        }
        if (st.editing && st.editing.id === comment.id) clearPostCommentContext();
        if (st.replyTo && (st.replyTo.id === comment.id || st.replyTo.rootId === comment.id)) clearPostCommentContext();
        // A top-level comment goes with its whole thread.
        const el = comment.parent_id
            ? document.querySelector(`#pc-list .pc-row[data-id="${comment.id}"]`)
            : document.querySelector(`#pc-list .pc-thread[data-root="${comment.id}"]`);
        st.byId.delete(comment.id);
        if (comment.parent_id) {
            const root = st.byId.get(comment.parent_id);
            if (root) {
                root.reply_count = Math.max(0, (root.reply_count || 0) - 1);
                root.loadedReplies = Math.max(0, (root.loadedReplies || 0) - 1);
            }
        }
        el?.classList.add('is-leaving');
        setTimeout(() => {
            el?.remove();
            if (!document.querySelector('#pc-list .pc-thread') && !st.nextAfter) renderPostCommentsEmpty();
        }, 200);
        setPostCommentCount(st.postId, Math.max(0, st.total - (body.removed || 1)));
    })
    .catch(() => {
        btn.disabled = false;
        showPostCommentError('Could not delete that comment.');
    });
}

// --- Emoji and sticker tray ------------------------------------------------------
let postCommentTrayTab = 'emoji';
let postCommentStickers = null;   // the unfiltered sticker list, once fetched

function togglePostCommentTray(tab) {
    const tray = document.getElementById('pc-tray');
    if (!tray.hidden && postCommentTrayTab === tab) {
        closePostCommentTray();
        return;
    }
    tray.hidden = false;
    document.getElementById('pc-composer').classList.add('has-tray');
    showPostCommentTrayTab(tab);
}

function closePostCommentTray() {
    const tray = document.getElementById('pc-tray');
    if (!tray) return;
    tray.hidden = true;
    document.getElementById('pc-composer')?.classList.remove('has-tray');
    document.querySelectorAll('#pc-composer .pc-tool').forEach(b => b.classList.remove('is-on'));
}

function showPostCommentTrayTab(tab) {
    postCommentTrayTab = tab;
    document.querySelectorAll('#pc-tray .pc-tray-tab').forEach(t =>
        t.setAttribute('aria-selected', t.dataset.tab === tab ? 'true' : 'false'));
    document.querySelectorAll('#pc-composer .pc-tool').forEach(b =>
        b.classList.toggle('is-on', b.dataset.tray === tab));
    const search = document.getElementById('pc-tray-search');
    search.value = '';
    search.placeholder = tab === 'emoji' ? 'Search emoji' : 'Search stickers';
    renderPostCommentTray();
}

function renderPostCommentTray() {
    const body = document.getElementById('pc-tray-body');
    const q = document.getElementById('pc-tray-search').value.trim().toLowerCase();
    if (postCommentTrayTab === 'emoji') {
        if (typeof EMOJI_LIST === 'undefined') {
            body.innerHTML = '<p class="pc-tray-note">Loading…</p>';
            loadScriptOnce(EMOJILIST_SRC)
                .then(renderPostCommentTray)
                .catch(() => { body.innerHTML = '<p class="pc-tray-note">Could not load emoji.</p>'; });
            return;
        }
        const cell = ch => `<button type="button" class="pc-emoji" data-char="${ch}">${ch}</button>`;
        if (q) {
            const hits = EMOJI_LIST.filter(it =>
                (it.name || '').toLowerCase().includes(q) || (it.keywords || '').toLowerCase().includes(q)).slice(0, 160);
            body.innerHTML = hits.length
                ? `<div class="pc-emoji-grid">${hits.map(it => cell(it.char)).join('')}</div>`
                : '<p class="pc-tray-note">No emoji found.</p>';
        } else {
            const recents = getRecentEmojis();
            const byCat = {};
            EMOJI_LIST.forEach(it => { (byCat[it.category || 'symbols'] = byCat[it.category || 'symbols'] || []).push(it); });
            let html = recents.length
                ? `<p class="pc-tray-head">Recently used</p><div class="pc-emoji-grid">${recents.map(cell).join('')}</div>` : '';
            EMOJI_CATEGORIES.forEach(c => {
                const items = byCat[c.key];
                if (!items || !items.length) return;
                html += `<p class="pc-tray-head">${escapeHtmlText(c.label)}</p><div class="pc-emoji-grid">${items.map(it => cell(it.char)).join('')}</div>`;
            });
            body.innerHTML = html;
        }
        body.scrollTop = 0;
        body.onclick = (e) => {
            const b = e.target.closest('.pc-emoji');
            if (!b) return;
            insertPostCommentText(b.dataset.char);
            pushRecentEmoji(b.dataset.char);
        };
        return;
    }

    // Stickers
    const draw = (stickers) => {
        body.innerHTML = stickers.length
            ? `<div class="pc-sticker-grid">${stickers.map(s =>
                `<button type="button" class="pc-sticker-pick" data-id="${Number(s.id)}" aria-label="Sticker"><img src="${escapeHtmlText(s.url)}" alt="" loading="lazy"></button>`).join('')}</div>`
            : '<p class="pc-tray-note">No stickers found.</p>';
        body.onclick = (e) => {
            const b = e.target.closest('.pc-sticker-pick');
            if (!b || !Number(b.dataset.id)) return;
            closePostCommentTray();
            submitPostComment({ sticker_id: Number(b.dataset.id) });
        };
    };
    if (q) {
        // Searched on the server, which knows each sticker's keywords.
        body.innerHTML = '<p class="pc-tray-note">Searching…</p>';
        fetch(`/api/stickers?q=${encodeURIComponent(q)}`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
            .then(r => r.json()).then(list => draw(Array.isArray(list) ? list : []))
            .catch(() => { body.innerHTML = '<p class="pc-tray-note">Could not load stickers.</p>'; });
        return;
    }
    if (postCommentStickers) { draw(postCommentStickers); return; }
    body.innerHTML = '<p class="pc-tray-note">Loading…</p>';
    fetch('/api/stickers?q=', { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => r.json())
        .then(list => {
            postCommentStickers = Array.isArray(list) ? list : [];
            if (postCommentTrayTab === 'stickers' && !document.getElementById('pc-tray-search').value) draw(postCommentStickers);
        })
        .catch(() => { body.innerHTML = '<p class="pc-tray-note">Could not load stickers.</p>'; });
}

function insertPostCommentText(str) {
    const input = document.getElementById('pc-input');
    const start = input.selectionStart ?? input.value.length;
    const end = input.selectionEnd ?? input.value.length;
    input.value = input.value.slice(0, start) + str + input.value.slice(end);
    const caret = start + str.length;
    // Not on a finger: focusing would raise the keyboard over the tray.
    if (shouldAutoFocus()) {
        input.focus({ preventScroll: true });
        try { input.setSelectionRange(caret, caret); } catch (e) { /* ignore */ }
    }
    syncPostCommentComposer();
}

// Someone else commented, replied or deleted while the thread is open. Rather
// than reshuffle what you're reading, offer the fresh thread with one tap.
// Our own changes are drawn already, so their echo is ignored.
function handlePostCommentsChanged(data, edited = false) {
    if (!data || !data.post_id) return;
    const st = postCommentsState;
    const open = st.postId === data.post_id && postCommentsOpen();
    if (!open || Date.now() < st.quietUntil) {
        if (!open && !edited) setPostCommentCount(data.post_id, data.count || 0);
        return;
    }
    if (edited) {
        // Our own edit is already redrawn in place.
        const mine = st.byId.get(data.comment_id);
        if (mine && mine.is_mine) return;
    } else if (data.count === st.total) {
        return;
    }
    const list = document.getElementById('pc-list');
    if (!list.querySelector('.pc-thread')) {
        reloadPostComments();
        return;
    }
    if (!list.querySelector('.pc-refresh-row')) {
        const li = document.createElement('li');
        li.className = 'pc-refresh-row';
        li.innerHTML = '<button type="button" class="pc-refresh"><i class="fas fa-arrow-rotate-right"></i> New activity · Refresh</button>';
        list.prepend(li);
    }
}

// --- The A-Line reader ------------------------------------------------------
// Frames go camera -> canvas -> decoder and stop there. Nothing is uploaded,
// nothing is kept, and the only thing a successful scan produces is a route
// this app was going to navigate to anyway. That is a deliberate property, not
// an accident of the implementation: a reader that phoned home would turn every
// glance at a poster into a request, and the whole point of owning the
// symbology is that we do not have to.
let alineStream = null, alineTrack = null, alineTimer = 0, alineBusy = false, alineTorchOn = false;
let alineCanvas = null;

function alineHint(text) {
    const el = document.getElementById('aline-scanner-hint');
    if (el) el.textContent = text;
}

async function openALineScanner() {
    const overlay = document.getElementById('aline-scanner');
    if (!overlay || !overlay.classList.contains('hidden')) return;

    overlay.classList.remove('hidden');
    overlay.setAttribute('aria-hidden', 'false');
    pushModalHistory('aline-scanner', closeALineScanner);
    alineHint('Point the camera at an A-Line');
    alineTorchOn = false;
    document.getElementById('aline-scanner-torch').classList.remove('is-on');

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        alineHint('This device has no camera APEX can use. Try a saved image instead.');
        return;
    }

    try {
        alineStream = await navigator.mediaDevices.getUserMedia({
            video: {
                facingMode: { ideal: 'environment' },
                width: { ideal: 1280 },
                height: { ideal: 720 }
            },
            audio: false
        });
    } catch (err) {
        // A closed scanner with a toast is a dead end; leaving it open with the
        // saved-image button still there gives the refusal somewhere to go.
        alineHint(err && err.name === 'NotAllowedError'
            ? 'APEX needs camera access to scan. You can still scan a saved image.'
            : 'That camera could not be opened. You can still scan a saved image.');
        return;
    }

    const video = document.getElementById('aline-scanner-video');
    video.srcObject = alineStream;
    try { await video.play(); } catch { /* autoplay already handled it */ }

    alineTrack = alineStream.getVideoTracks()[0] || null;
    const torchBtn = document.getElementById('aline-scanner-torch');
    const caps = alineTrack && alineTrack.getCapabilities ? alineTrack.getCapabilities() : null;
    torchBtn.classList.toggle('hidden', !(caps && caps.torch));

    alineBusy = false;
    alineTimer = setTimeout(alineScanTick, 250);
}

function closeALineScanner() {
    const overlay = document.getElementById('aline-scanner');
    if (!overlay || overlay.classList.contains('hidden')) return;

    clearTimeout(alineTimer);
    alineTimer = 0;
    if (alineStream) alineStream.getTracks().forEach(t => t.stop());
    alineStream = null;
    alineTrack = null;
    alineTorchOn = false;

    const video = document.getElementById('aline-scanner-video');
    video.pause();
    video.srcObject = null;

    overlay.classList.add('hidden');
    overlay.setAttribute('aria-hidden', 'true');
    popModalHistory('aline-scanner');
}

async function toggleALineTorch() {
    if (!alineTrack) return;
    alineTorchOn = !alineTorchOn;
    try {
        await alineTrack.applyConstraints({ advanced: [{ torch: alineTorchOn }] });
        document.getElementById('aline-scanner-torch').classList.toggle('is-on', alineTorchOn);
    } catch {
        alineTorchOn = false;
        showToast('This camera has no light APEX can switch on.', 'error');
    }
}

// Copies the whole camera frame into a canvas at a size the decoder can work
// with. The WHOLE frame, deliberately: the reticle is a guide for the person
// holding the phone, not a crop. Cropping to it is what made a tilted code fail
// -- a mark wider than it is tall pushes its own corners outside the guide as
// soon as it is turned even slightly, and the decoder was then being handed a
// clipped shape whose corners were nowhere near the real ones.
function alineGrabFrame() {
    const video = document.getElementById('aline-scanner-video');
    const sw = video.videoWidth, sh = video.videoHeight;
    if (!sw || !sh) return null;

    const out = Math.min(900, sw);
    if (!alineCanvas) alineCanvas = document.createElement('canvas');
    alineCanvas.width = out;
    alineCanvas.height = Math.max(1, Math.round(sh * out / sw));
    const ctx = alineCanvas.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(video, 0, 0, sw, sh, 0, 0, alineCanvas.width, alineCanvas.height);
    return ctx.getImageData(0, 0, alineCanvas.width, alineCanvas.height);
}

function alineScanTick() {
    alineTimer = 0;
    const overlay = document.getElementById('aline-scanner');
    if (!overlay || overlay.classList.contains('hidden') || !alineStream) return;

    // Nothing to read while the app is in the background, and decoding there
    // just burns battery against a frozen frame.
    if (document.hidden || alineBusy) {
        alineTimer = setTimeout(alineScanTick, 200);
        return;
    }

    alineBusy = true;
    let hit = null;
    try {
        const frame = alineGrabFrame();
        if (frame) hit = ApexALine.decodeImage(frame);
    } catch { /* a frame we could not read is just a frame we skip */ }
    alineBusy = false;

    if (hit) {
        onALineScanned(hit);
        return;
    }
    alineTimer = setTimeout(alineScanTick, 60);
}

function onALineScanned(path) {
    if (navigator.vibrate) navigator.vibrate(30);
    // Navigate OUT of the scanner rather than closing it and then navigating:
    // this spends the scanner's own history entry on the destination, so Back
    // from a scanned page returns where the user came from instead of reopening
    // a camera they have finished with. It still closes through
    // closeALineScanner, so the camera is released either way.
    navigateFromModal(document.getElementById('aline-scanner'), path);
}

// The one thing a scan cannot do offline: turn a user id into a handle. It runs
// after a successful local decode, on the way to a page that was going to be
// fetched anyway, so it costs nothing that opening the profile did not already.
// A scanned "link" A-Line (/links/<n>): ask which page number n stands for, put
// that address in place of this one, and route to it.
async function resolveALineLink(id) {
    try {
        const res = await fetch(`${API_BASE_URL}/api/aline/links/${id}`, {
            headers: { 'Authorization': `Bearer ${apiToken}` }
        });
        const data = res.ok ? await res.json() : null;
        if (data && typeof data.path === 'string' && data.path.startsWith('/') && !data.path.startsWith('//')) {
            history.replaceState(null, '', data.path);
            handleRouting();
            return;
        }
    } catch { /* fall through to the not-found page */ }
    showPage('not-found-page');
}

// The number for a page with no id of its own, minted (or looked up -- one per
// path) by the server. Remembered per page for the session so reopening the
// sheet doesn't ask again.
const alineLinkIds = new Map();
async function linkALineFor(path) {
    if (alineLinkIds.has(path)) return alineLinkIds.get(path);
    const res = await fetch(`${API_BASE_URL}/api/aline/links`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ path })
    });
    const data = res.ok ? await res.json() : null;
    if (!data || !Number.isInteger(data.id)) return null;
    const code = `/k/${data.id}`;
    alineLinkIds.set(path, code);
    return code;
}

async function resolveScannedProfile(id) {
    try {
        const res = await fetch(`${API_BASE_URL}/api/user-handle/${id}`, {
            headers: { 'Authorization': `Bearer ${apiToken}` }
        });
        const data = res.ok ? await res.json() : null;
        if (data && data.username) {
            history.replaceState(null, '', `/users/${data.username}`);
            showProfile(data.username);
            return;
        }
    } catch { /* fall through to the not-found page */ }
    showPage('not-found-page');
}

function pickALineImage() {
    const input = document.getElementById('aline-scanner-file');
    input.value = '';
    input.click();
}

// The same decoder, pointed at a screenshot instead of a camera. Held codes are
// the common case, but an A-Line someone sent you in a chat is a picture in
// your gallery, and it would be strange if the reader could not read it.
function decodeALineFromFile(file) {
    if (!file) return;
    alineHint('Reading that image...');
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
        URL.revokeObjectURL(url);
        // Big enough for the decoder to resolve slots, small enough that a 12MP
        // photo does not spend a second in a flood fill.
        const scale = Math.min(1, 1400 / Math.max(img.width, img.height));
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(img.width * scale));
        canvas.height = Math.max(1, Math.round(img.height * scale));
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        let hit = null;
        try { hit = ApexALine.decodeImage(ctx.getImageData(0, 0, canvas.width, canvas.height)); } catch { }
        if (hit) onALineScanned(hit);
        else alineHint('No A-Line found in that image. Try one where the whole code is visible.');
    };
    img.onerror = () => {
        URL.revokeObjectURL(url);
        alineHint('That file could not be opened as an image.');
    };
    img.src = url;
}

document.addEventListener('DOMContentLoaded', () => {
    const input = document.getElementById('aline-scanner-file');
    if (input) input.addEventListener('change', () => decodeALineFromFile(input.files && input.files[0]));
});

// Leaving the app mid-scan should release the camera, not leave the light on
// and the sensor running behind whatever the user switched to.
document.addEventListener('visibilitychange', () => {
    if (document.hidden && alineStream) closeALineScanner();
});

function closeShareProfileModal() {
    document.getElementById('share-profile-modal').classList.add('hidden');
}

function copyShareProfileLink() {
    const link = document.getElementById('share-profile-link-input').value;
    const btn = document.getElementById('share-profile-copy-btn');
    const toastText = document.getElementById('share-profile-modal').dataset.copiedToast || 'Link copied!';

    navigator.clipboard.writeText(link)
        .then(() => {
            showToast(toastText);
            // Brief checkmark confirmation on the button itself, not just the toast.
            if (btn) {
                const icon = btn.querySelector('i');
                btn.classList.add('copied');
                icon.className = 'fas fa-check';
                setTimeout(() => {
                    btn.classList.remove('copied');
                    icon.className = 'fas fa-copy';
                }, 1500);
            }
        })
        .catch(() => showToast('Could not copy the link.', 'error'));
}

function showToast(message, type = 'success') {
    const container = document.getElementById('notification-toast-container');
    const toast = document.createElement('div');
    toast.className = `notification-toast ${type}`;
    toast.textContent = message;

    container.appendChild(toast);

    // Set a timeout to remove the toast
    setTimeout(() => {
        toast.classList.add('exiting');
        // Wait for the exit animation to finish before removing from the DOM
        setTimeout(() => {
            toast.remove();
        }, 400); // This duration should match the CSS animation time
    }, 4000); // The toast will be visible for 4 seconds
}

// --- Lounge invite dialog --------------------------------------------------
// Three views over one lounge: people you can invite, invitations still waiting
// (with one-tap reminders), and who is already in. Picks live in `selected`,
// not in the result rows, so searching for someone else never drops them.
const inviteModalState = {
    tab: 'invite',
    selected: new Map(),     // username -> user, in the order they were picked
    results: [],             // the last search's rows
    query: '',
    roster: null,            // /invite-roster reply
    searchSeq: 0,            // discards replies to searches that were overtaken
    searchTimer: null,
    loungeId: null,
    reminding: new Set(),    // usernames with a reminder in flight
};

function invShortTime(iso, future = false) {
    if (!iso) return '';
    const ms = Math.abs(new Date(iso) - Date.now());
    const min = Math.round(ms / 60000), hr = Math.round(ms / 3600000), day = Math.round(ms / 86400000);
    const span = min < 1 ? null : min < 60 ? `${min}m` : hr < 24 ? `${hr}h` : `${day}d`;
    if (!span) return future ? 'now' : 'just now';
    return future ? `in ${span}` : `${span} ago`;
}

function invAvatar(user, size = 'md') {
    profileData[user.username] = { ...(profileData[user.username] || {}), name: user.fullName, ...user };
    const pic = document.createElement('div');
    pic.className = `profile-pic inv-avatar inv-avatar-${size}`;
    pic.dataset.userPicId = user.username;
    return pic;
}

function invPersonText(user, meta) {
    const text = document.createElement('div');
    text.className = 'inv-person-text';
    const name = document.createElement('span');
    name.className = 'inv-person-name';
    name.textContent = user.fullName || user.username;
    appendRankIcon(name, user.username, user.rank);
    const sub = document.createElement('span');
    sub.className = 'inv-person-meta';
    sub.textContent = meta || `@${user.username}`;
    text.append(name, sub);
    return text;
}

function invRow(user, meta, extraClass = '') {
    const li = document.createElement('li');
    li.className = `inv-row ${extraClass}`.trim();
    li.dataset.username = user.username;
    li.append(invAvatar(user), invPersonText(user, meta));
    return li;
}

function invEmpty(list, icon, title, body) {
    const li = document.createElement('li');
    li.className = 'inv-empty';
    li.innerHTML = `<span class="inv-empty-icon"><i class="fas ${icon}"></i></span><b></b><span></span>`;
    li.querySelector('b').textContent = title;
    li.querySelector('span:last-child').textContent = body;
    list.appendChild(li);
}

function invPaintAvatars(root) {
    new Set(Array.from(root.querySelectorAll('[data-user-pic-id]'), el => el.dataset.userPicId))
        .forEach(u => updateProfilePictures(u, root));
}

function showInviteUserModal() {
    const modal = document.getElementById('invite-lounge-member-modal');
    const st = inviteModalState;
    // Picks belong to the lounge they were made for; reopening the same one keeps them.
    if (st.loungeId !== currentLoungeId) st.selected.clear();
    st.loungeId = currentLoungeId;
    st.roster = null;
    st.results = [];
    st.query = '';

    const title = document.getElementById('lounge-header-title');
    document.getElementById('inv-title').textContent = (title && title.textContent) || 'Lounge';
    document.getElementById('inv-summary').innerHTML = '&nbsp;';
    ['inv-count-pending', 'inv-count-members'].forEach(id => { document.getElementById(id).hidden = true; });
    document.getElementById('inv-pending-list').innerHTML = '<li class="inv-skeleton"></li>'.repeat(3);
    document.getElementById('inv-member-list').innerHTML = '<li class="inv-skeleton"></li>'.repeat(3);
    document.getElementById('inv-declined-list').innerHTML = '';
    document.getElementById('inv-declined-head').hidden = true;
    document.getElementById('inv-remind-banner').hidden = true;

    const search = document.getElementById('invite-user-search');
    search.value = '';
    search.oninput = () => {
        clearTimeout(st.searchTimer);
        st.searchTimer = setTimeout(() => invSearch(search.value.trim()), 180);
    };
    search.onkeydown = e => {
        // Enter adds the top result: type a name, Enter, type the next.
        if (e.key !== 'Enter') return;
        e.preventDefault();
        const first = document.querySelector('#invite-user-list .inv-row.is-pickable');
        if (first) first.click();
    };

    document.querySelectorAll('#inv-tabs .inv-tab').forEach(btn => {
        btn.onclick = () => invSetTab(btn.dataset.tab);
    });
    document.getElementById('inv-tray-clear').onclick = () => {
        st.selected.clear();
        invRenderTray();
        invRenderResults();
    };
    document.getElementById('inv-remind-all').onclick = () => {
        const due = (st.roster?.invited || []).filter(u => u.can_remind).map(u => u.username);
        if (due.length) invRemind(due);
    };

    modal.classList.remove('hidden');
    invSetTab('invite', true);
    invRenderTray();
    invSearch('');
    invLoadRoster();
    if (!document.documentElement.classList.contains('ui-phone')) {
        setTimeout(() => search.focus(), 60);
    }
}

function closeInviteUserModal() {
    const modal = document.getElementById('invite-lounge-member-modal');
    if (!modal) return;
    clearTimeout(inviteModalState.searchTimer);
    modal.classList.add('hidden');
}

function invSetTab(tab, instant = false) {
    inviteModalState.tab = tab;
    const tabs = document.getElementById('inv-tabs');
    tabs.style.setProperty('--inv-tab-index', ['invite', 'pending', 'members'].indexOf(tab));
    tabs.classList.toggle('no-anim', instant);
    if (instant) requestAnimationFrame(() => requestAnimationFrame(() => tabs.classList.remove('no-anim')));
    tabs.querySelectorAll('.inv-tab').forEach(btn => {
        btn.setAttribute('aria-selected', String(btn.dataset.tab === tab));
    });
    document.querySelectorAll('#invite-lounge-member-modal .inv-panel').forEach(p => {
        p.hidden = p.dataset.panel !== tab;
    });
    document.getElementById('inv-footer').classList.toggle('is-away', tab !== 'invite');
    document.querySelector('#invite-lounge-member-modal .inv-body').scrollTop = 0;
}

function invLoadRoster(highlight = []) {
    const st = inviteModalState;
    const loungeId = st.loungeId;
    return fetch(`${API_BASE_URL}/api/lounge/${loungeId}/invite-roster`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json())
    .then(data => {
        if (loungeId !== st.loungeId || data.error) return;
        st.roster = data;
        invRenderHero();
        invRenderPending(highlight);
        invRenderMembers();
    })
    .catch(err => console.error('Failed to load the invite roster:', err));
}

function invRenderHero() {
    const { lounge, members, invited } = inviteModalState.roster;
    document.getElementById('inv-title').textContent = lounge.name;
    const cover = document.getElementById('inv-cover');
    const hero = document.getElementById('inv-hero');
    const img = `url("${loungeCoverUrl(lounge)}")`;
    cover.classList.toggle('has-image', !!img);
    cover.style.backgroundImage = img;
    hero.classList.toggle('has-image', !!img);
    hero.style.setProperty('--inv-cover', img || 'none');

    const bits = [`${members.length} member${members.length === 1 ? '' : 's'}`];
    if (invited.length) bits.push(`${invited.length} waiting on an answer`);
    document.getElementById('inv-summary').textContent = bits.join(' · ');

    const setCount = (id, n) => {
        const el = document.getElementById(id);
        el.hidden = !n;
        el.textContent = n;
    };
    setCount('inv-count-pending', invited.length);
    setCount('inv-count-members', members.length);
    document.getElementById('inv-count-pending').classList.toggle('is-due', invited.some(u => u.can_remind));
}

function invSearch(query) {
    const st = inviteModalState;
    const seq = ++st.searchSeq;
    const list = document.getElementById('invite-user-list');
    const bar = document.querySelector('#invite-lounge-member-modal .inv-search');
    bar.classList.add('is-loading');
    if (!st.results.length) list.innerHTML = '<li class="inv-skeleton"></li>'.repeat(5);

    fetch(`${API_BASE_URL}/api/lounge/${st.loungeId}/potential-invitees?q=${encodeURIComponent(query)}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json())
    .then(users => {
        if (seq !== st.searchSeq) return;   // a newer search owns the list now
        st.results = Array.isArray(users) ? users : [];
        st.query = query;
        invRenderResults();
    })
    .catch(err => {
        if (seq !== st.searchSeq) return;
        console.error('Failed to load potential invitees:', err);
        list.innerHTML = '';
        invEmpty(list, 'fa-wifi', 'Couldn’t load people', 'Check your connection and try again.');
    })
    .finally(() => { if (seq === st.searchSeq) bar.classList.remove('is-loading'); });
}

function invRenderResults() {
    const st = inviteModalState;
    const list = document.getElementById('invite-user-list');
    list.innerHTML = '';
    // Someone already picked lives in the tray; listing them here too would
    // make it look like the pick didn't take.
    const rows = st.results.filter(u => !st.selected.has(u.username));

    if (!rows.length) {
        if (st.query) invEmpty(list, 'fa-magnifying-glass', `No one new matches “${st.query}”`, 'Members and people you already picked don’t show up here.');
        else if (st.results.length) invEmpty(list, 'fa-check', 'Everyone here is picked', 'Search for more people, or send the invites.');
        else invEmpty(list, 'fa-user-group', 'No one left to invite', 'Everyone you could invite is already in.');
        return;
    }

    let lastGroup = null;
    rows.forEach((user, i) => {
        const group = st.query ? 'Results' : (user.followed ? 'People you follow' : 'Suggested');
        if (group !== lastGroup) {
            const head = document.createElement('li');
            head.className = 'inv-group';
            head.textContent = group;
            list.appendChild(head);
            lastGroup = group;
        }

        let meta = `@${user.username}`;
        let state = 'pickable';
        if (user.invite_pending) {
            state = 'pending';
            meta = user.can_remind ? 'Invited · ready for a reminder'
                 : user.reminders_left > 0 ? `Invited · can remind ${invShortTime(user.remind_at, true)}`
                 : 'Invited · no reminders left';
        } else if (user.declined_recently) {
            state = 'declined';
            meta = `Declined · can invite again ${invShortTime(user.invite_again_at, true)}`;
        }

        const li = invRow(user, meta, `is-${state}`);
        li.style.setProperty('--i', Math.min(i, 12));
        const side = document.createElement('div');
        side.className = 'inv-row-side';

        if (state === 'pickable') {
            li.tabIndex = 0;
            li.setAttribute('role', 'button');
            li.setAttribute('aria-label', `Add ${user.fullName || user.username}`);
            side.innerHTML = '<span class="inv-add"><i class="fas fa-plus"></i></span>';
            li.onclick = () => invPick(user, li);
            li.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); invPick(user, li); } };
        } else if (state === 'pending' && user.can_remind) {
            side.appendChild(invRemindButton(user.username));
        } else {
            side.innerHTML = state === 'declined'
                ? '<span class="inv-tag is-declined">Declined</span>'
                : '<span class="inv-tag">Invited</span>';
        }
        li.appendChild(side);
        list.appendChild(li);
    });
    invPaintAvatars(list);
}

function invPick(user, rowEl) {
    const st = inviteModalState;
    if (st.selected.has(user.username)) return;
    st.selected.set(user.username, user);
    const finish = () => { invRenderTray(user.username); invRenderResults(); };
    if (rowEl && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        rowEl.classList.add('is-leaving');
        setTimeout(finish, 160);
    } else finish();
}

function invUnpick(username) {
    inviteModalState.selected.delete(username);
    invRenderTray();
    invRenderResults();
}

function invRenderTray(justAdded = null) {
    const st = inviteModalState;
    const tray = document.getElementById('inv-tray');
    const chips = document.getElementById('inv-tray-chips');
    const n = st.selected.size;
    tray.dataset.empty = String(n === 0);
    document.getElementById('inv-tray-count').textContent = n;
    chips.innerHTML = '';

    st.selected.forEach(user => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'inv-chip' + (user.username === justAdded ? ' is-new' : '');
        chip.title = `Remove ${user.fullName || user.username}`;
        chip.setAttribute('aria-label', chip.title);
        const name = document.createElement('span');
        name.className = 'inv-chip-name';
        name.textContent = (user.fullName || user.username).split(' ')[0];
        const x = document.createElement('span');
        x.className = 'inv-chip-x';
        x.innerHTML = '<i class="fas fa-xmark"></i>';
        chip.append(invAvatar(user, 'sm'), name, x);
        chip.onclick = () => invUnpick(user.username);
        chips.appendChild(chip);
    });
    invPaintAvatars(chips);
    if (justAdded) chips.scrollTo({ top: chips.scrollHeight, behavior: 'smooth' });

    // Footer: the faces about to be invited, and a button that says how many.
    const stack = document.getElementById('inv-footer-stack');
    stack.innerHTML = '';
    const picked = Array.from(st.selected.values());
    if (picked.length > 4) {
        const more = document.createElement('span');
        more.className = 'inv-stack-more';
        more.textContent = `+${picked.length - 4}`;
        stack.appendChild(more);
    }
    picked.slice(-4).forEach(u => stack.appendChild(invAvatar(u, 'xs')));
    invPaintAvatars(stack);

    const btn = document.getElementById('send-invite-btn');
    btn.disabled = n === 0;
    btn.querySelector('.inv-send-label').textContent =
        n === 0 ? 'Pick people to invite' : n === 1 ? 'Send 1 invite' : `Send ${n} invites`;
}

function invRemindButton(username) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'inv-btn inv-btn-remind';
    btn.dataset.remind = username;
    btn.innerHTML = '<i class="fas fa-bell"></i><span>Remind</span>';
    btn.disabled = inviteModalState.reminding.has(username);
    btn.onclick = e => { e.stopPropagation(); invRemind([username]); };
    return btn;
}

function invRemind(usernames) {
    const st = inviteModalState;
    usernames = usernames.filter(u => !st.reminding.has(u));
    if (!usernames.length) return;
    usernames.forEach(u => st.reminding.add(u));
    const buttons = () => usernames.flatMap(u =>
        Array.from(document.querySelectorAll(`#invite-lounge-member-modal [data-remind="${CSS.escape(u)}"]`)));
    buttons().forEach(b => { b.disabled = true; b.classList.add('is-busy'); });
    const allBtn = document.getElementById('inv-remind-all');
    allBtn.disabled = true;

    fetch(`${API_BASE_URL}/api/lounge/${st.loungeId}/invite`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ usernames })
    })
    .then(r => r.json().then(body => ({ ok: r.ok, body })))
    .then(({ ok, body }) => {
        if (ok && body.ok) {
            buttons().forEach(b => {
                b.classList.remove('is-busy');
                b.classList.add('is-done');
                b.innerHTML = '<i class="fas fa-check"></i><span>Sent</span>';
            });
            showToast(body.message, 'success');
            if (body.skipped_message) showToast(body.skipped_message, 'error');
        } else {
            showToast(body.error || 'Could not send the reminder.', 'error');
        }
    })
    .catch(() => showToast('Could not send the reminder. Please try again.', 'error'))
    .finally(() => {
        usernames.forEach(u => st.reminding.delete(u));
        allBtn.disabled = false;
        // Let the "Sent" tick land before the rows re-render into their new state.
        setTimeout(() => { invLoadRoster(); invSearch(st.query); }, 900);
    });
}

function invRenderPending(highlight = []) {
    const { invited, declined, max_reminders: maxReminders } = inviteModalState.roster;
    const list = document.getElementById('inv-pending-list');
    list.innerHTML = '';

    const due = invited.filter(u => u.can_remind);
    document.getElementById('inv-remind-banner').hidden = due.length === 0;
    document.getElementById('inv-remind-due').textContent = due.length;
    document.getElementById('inv-remind-due-label').textContent =
        due.length === 1 ? ' invite is ready for a reminder' : ' invites are ready for a reminder';
    document.getElementById('inv-remind-all').textContent = due.length === 1 ? 'Remind' : 'Remind all';

    if (!invited.length) {
        invEmpty(list, 'fa-paper-plane', 'No invitations waiting', 'People you invite show up here until they answer.');
    }
    // Ready-to-remind first: those are the rows that want something from you.
    [...invited].sort((a, b) => b.can_remind - a.can_remind).forEach((user, i) => {
        const by = user.inviter ? ` by @${user.inviter}` : '';
        const li = invRow(user, `Invited ${invShortTime(user.invited_at)}${by}`,
                          highlight.includes(user.username) ? 'is-fresh' : '');
        li.style.setProperty('--i', Math.min(i, 12));
        const side = document.createElement('div');
        side.className = 'inv-row-side inv-row-side-stack';

        if (user.can_remind) {
            side.appendChild(invRemindButton(user.username));
        } else {
            const when = document.createElement('span');
            when.className = 'inv-when';
            when.textContent = user.reminders_left > 0
                ? `Remind ${invShortTime(user.remind_at, true)}` : 'No reminders left';
            side.appendChild(when);
        }

        // One pip per send: the first invite, then each reminder used.
        const pips = document.createElement('span');
        pips.className = 'inv-pips';
        pips.title = `Sent ${user.sends} time${user.sends === 1 ? '' : 's'} · ${user.reminders_left} reminder${user.reminders_left === 1 ? '' : 's'} left`;
        for (let k = 0; k < 1 + maxReminders; k++) {
            const dot = document.createElement('i');
            if (k < user.sends) dot.className = 'is-on';
            pips.appendChild(dot);
        }
        side.appendChild(pips);
        li.appendChild(side);
        list.appendChild(li);
    });

    const dList = document.getElementById('inv-declined-list');
    dList.innerHTML = '';
    document.getElementById('inv-declined-head').hidden = declined.length === 0;
    declined.forEach(user => {
        const li = invRow(user, `Can invite again ${invShortTime(user.invite_again_at, true)}`, 'is-declined');
        const side = document.createElement('div');
        side.className = 'inv-row-side';
        side.innerHTML = '<span class="inv-tag is-declined">Declined</span>';
        li.appendChild(side);
        dList.appendChild(li);
    });
    invPaintAvatars(document.querySelector('#invite-lounge-member-modal [data-panel="pending"]'));
}

function invRenderMembers() {
    const { members } = inviteModalState.roster;
    const list = document.getElementById('inv-member-list');
    list.innerHTML = '';
    members.forEach((user, i) => {
        const li = invRow(user, user.joined_at ? `Joined ${invShortTime(user.joined_at)}` : `@${user.username}`);
        li.style.setProperty('--i', Math.min(i, 12));
        const side = document.createElement('div');
        side.className = 'inv-row-side';
        if (user.role === 'owner') {
            side.innerHTML = '<span class="inv-role is-owner"><i class="fas fa-crown"></i>Owner</span>';
        } else if (user.role === 'moderator') {
            side.innerHTML = '<span class="inv-role is-moderator"><i class="fas fa-shield-halved"></i>Mod</span>';
        } else {
            side.innerHTML = '<span class="inv-in"><i class="fas fa-check"></i>In</span>';
        }
        li.appendChild(side);
        list.appendChild(li);
    });
    invPaintAvatars(list);
}

function handleSendLoungeInvite() {
    const st = inviteModalState;
    const usernames = Array.from(st.selected.keys());
    if (!usernames.length) return;

    const sendBtn = document.getElementById('send-invite-btn');
    const label = sendBtn.querySelector('.inv-send-label');
    sendBtn.disabled = true;
    sendBtn.classList.add('is-busy');
    label.textContent = 'Sending…';

    fetch(`${API_BASE_URL}/api/lounge/${st.loungeId}/invite`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ usernames })
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 200 || body.ok) {
            showToast(body.message, 'success');
            // Some went out and some didn't (already invited, already a member):
            // say which and why.
            if (body.skipped_message) showToast(body.skipped_message, 'error');
            st.selected.clear();
            invRenderTray();
            // Land on the Invited tab so the new rows are right there to see.
            invLoadRoster(usernames).then(() => invSetTab('pending'));
            invSearch(st.query);
        } else {
            // Keep the picks so the inviter can adjust them.
            showToast(body.error || 'Could not send the invitations.', 'error');
        }
    })
    .catch(error => {
        console.error('Error sending lounge invites:', error);
        showToast('Could not send the invitations. Please try again.', 'error');
    })
    .finally(() => {
        sendBtn.classList.remove('is-busy');
        invRenderTray();
    });
}

function respondToInvite(notificationId, action, buttonContainer) {
    const buttons = buttonContainer.querySelectorAll('button');
    buttons.forEach(b => { b.disabled = true; });

    fetch(`${API_BASE_URL}/api/notification/${notificationId}/respond`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ action: action })
    })
    .then(response => response.json())
    .then(data => {
        if (data.ok) {
            // Settle the loaded row too, so a re-render doesn't bring the
            // buttons back before the next fetch.
            const notif = notifListState.items.find(n => n.id === notificationId) ||
                { id: notificationId, event_type: 'lounge_invite' };
            notif.status = action === 'accept' ? 'accepted' : 'declined';
            notif.actionable = false;
            notif.is_read = true;
            buttonContainer.innerHTML = notificationStatusChip(notif);
            fetchAndRenderMyLounges();
        } else {
            buttons.forEach(b => { b.disabled = false; });
            showToast(data.error || 'Could not respond to invite.', 'error');
        }
    })
    .catch(() => {
        buttons.forEach(b => { b.disabled = false; });
        showToast('Could not respond to invite.', 'error');
    });
}

// username (lowercased) -> 'admin' | 'moderator', from /api/users/ranks. Most
// payloads that name somebody carry a username but no rank, so the icon can't come
// from the payload -- this map is what lets every name in the app wear it.
let staffRanks = null;
let staffRanksPromise = null;

function loadStaffRanks() {
    if (staffRanks || staffRanksPromise || !apiToken) return;
    staffRanksPromise = fetch(`${API_BASE_URL}/api/users/ranks`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
        .then(res => (res.ok ? res.json() : {}))
        .then(map => {
            staffRanks = new Map(Object.entries(map || {}).map(([u, r]) => [u.toLowerCase(), r]));
            paintRankSlots();
        })
        .catch(err => console.error('Rank list failed:', err))
        .finally(() => { staffRanksPromise = null; });
}

// The loaded map wins over a payload's rank (it is the fresher of the two); the
// payload's rank covers the moment before the map arrives.
function rankOf(username, rank) {
    loadStaffRanks();
    if (staffRanks) return staffRanks.get(String(username || '').toLowerCase()) || '';
    return rank || '';
}

// A rank icon for `username`, wrapped in a slot so paintRankSlots() can fill or
// correct it once the rank map loads (or a rank changes).
function rankIconFor(username, rank) {
    if (!username) return getRankIcon(rank);
    return `<span class="rank-slot" data-rank-user="${escapeMentionText(username)}">${getRankIcon(rankOf(username, rank))}</span>`;
}

function appendRankIcon(el, username, rank) {
    if (el) el.insertAdjacentHTML('beforeend', rankIconFor(username, rank));
}

function paintRankSlots(root = document) {
    root.querySelectorAll('.rank-slot[data-rank-user]').forEach(slot => {
        const html = getRankIcon(rankOf(slot.dataset.rankUser));
        if (slot.innerHTML !== html) slot.innerHTML = html;
    });
}

function getRankIcon(rank) {
    if (rank === 'admin') {
        // Blue checkmark for admins
        return '<i class="fas fa-check-circle rank-icon admin-icon"></i>';
    }
    if (rank === 'moderator') {
        // Black gear for moderators
        return '<i class="fas fa-cog rank-icon mod-icon"></i>';
    }
    return ''; // Return nothing for regular users
}

// True once the privacy switches in the edit form are known to match the database.
// saveProfile() refuses to send them while this is false, so a form that was drawn
// from an incomplete cache can never silently turn a setting off.
let privacyTogglesHydrated = false;

function editProfile() {
    // Safety check: If profile data isn't loaded yet, try to fetch it or default to empty object
    const me = profileData.me || {};

    // Populate form with safety checks using optional chaining (?.) or OR (||) operators
    document.getElementById('editFullName').value = me.name || '';
    
    // --- DELETED LINE: document.getElementById('editUsername').value = me.username || ''; --- 
    // Since the element doesn't exist in HTML, we just skip it.

    const bioTextarea = document.getElementById('editBio');
    const charCounter = document.getElementById('bioCharCounter');

    bioTextarea.value = me.bio || '';
    // Update the character counter immediately
    charCounter.textContent = `${bioTextarea.value.length} / 150`;
    
    bioTextarea.oninput = () => {
        const currentLength = bioTextarea.value.length;
        charCounter.textContent = `${currentLength} / 150`;
    };

    // Privacy switches. Paint the cached value immediately so the form does not
    // flicker, then reconcile against the database -- these are the settings people
    // notice being wrong, and a cached copy that predates a change on another device
    // is exactly how a switch ends up disagreeing with what the profile actually does.
    // privacyTogglesHydrated gates the save: until we know the real values, the form
    // must not be allowed to write its placeholder state back.
    privacyTogglesHydrated = (typeof me.show_birthday === 'boolean' &&
                              typeof me.show_social_stats === 'boolean');
    document.getElementById('editShowBirthday').checked = me.show_birthday !== false;
    document.getElementById('editShowSocialStats').checked = me.show_social_stats !== false;

    // Same paint-then-reconcile, and the same save guard, for the contact settings.
    accountSettingsHydrated = typeof me.dm_privacy === 'string';
    paintAccountSettings(me);
    loadSessionsList();
    loadBlockedAccountsList();
    renderGuardianInfo(me);

    fetch(`${API_BASE_URL}/api/me`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => r.ok ? r.json() : Promise.reject(r.status))
        .then(fresh => {
            profileData.me.show_birthday = fresh.show_birthday;
            profileData.me.show_social_stats = fresh.show_social_stats;
            document.getElementById('editShowBirthday').checked = !!fresh.show_birthday;
            document.getElementById('editShowSocialStats').checked = !!fresh.show_social_stats;
            privacyTogglesHydrated = true;

            ACCOUNT_SETTING_KEYS.forEach(k => { profileData.me[k] = fresh[k]; });
            profileData.me.guardian = fresh.guardian;
            profileData.me.guardian_consent = fresh.guardian_consent;
            paintAccountSettings(fresh);
            renderGuardianInfo(fresh);
            accountSettingsHydrated = true;
        })
        .catch(() => { /* keep the cached paint; the save guard covers the rest */ });

    // What this device is actually running. Reading it off a screen beats reading it
    // out of a server log: the log cannot tell you which device a line came from or
    // when, and an installed PWA can report a build it is not running if the page
    // itself was never reloaded.
    renderBuildInfo();

    // The desktop/mobile override, and what Automatic currently thinks. Hides itself
    // on anything that is not a tablet.
    syncLayoutSetting();

    // Push notification toggle logic — mobile only, so hide the row entirely on
    // desktop rather than offering a switch that refuses to do anything.
    const pushToggle = document.getElementById('pushNotifToggle');
    const pushSetting = document.getElementById('pushNotifSetting');
    if (!isMobileDevice()) {
        if (pushSetting) pushSetting.style.display = 'none';
    } else if (pushToggle) {
        // Reflect a subscription BOTH sides agree on. Permission being "granted"
        // does not mean this device is subscribed, and a local subscription does
        // not mean the server still has a row for it -- either mismatch shows a
        // switch that does not match what the phone actually receives.
        // getPushOptInState() re-registers a local-only subscription on the way
        // past, so opening this page also repairs that case.
        const blockedHint = document.getElementById('pushBlockedHint');
        if (blockedHint) blockedHint.classList.add('hidden');
        pushToggle.disabled = true;
        // Start from OFF, every time. This <input> is never destroyed -- the edit
        // form is shown and hidden, not rebuilt -- so without this it still holds
        // whatever it was left at the last time the form was open, and that stale
        // ON is what the user stares at for as long as the check below takes.
        // getPushOptInState() makes up to two network round trips behind a 3s
        // registration race, so on a phone that is exactly when you are looking at
        // it. If those requests fail the .catch never gets to correct anything
        // either, because the value it would write is already on screen. OFF is the
        // only honest default: it is the state in which nothing gets delivered, and
        // it is what an unanswered "are we subscribed?" actually means.
        pushToggle.checked = false;
        getPushOptInState()
            .then(state => {
                // 'unknown' only happens with permission granted and the check
                // itself failing -- nearly always a device that IS subscribed.
                // Showing OFF there invites a tap that "turns on" something already
                // on. The next open of this page gets a real answer.
                pushToggle.checked = (state === 'subscribed' || state === 'unknown');
                // A blocked device cannot be fixed from this screen at all, so the
                // switch on its own is a lie either way: leave it off, disabled, and
                // say where the block actually is.
                if (state === 'blocked' && blockedHint) {
                    blockedHint.textContent = pushBlockedHelpText();
                    blockedHint.classList.remove('hidden');
                    pushToggle.disabled = true;
                    return;
                }
                pushToggle.disabled = false;
            })
            .catch(() => { pushToggle.checked = false; pushToggle.disabled = false; });
    }

    // --- School & Subject Logic ---
    const schoolSelect = document.getElementById('editSchool');
    if (schoolSelect) schoolSelect.value = me.school || '';

    const subjectWrapper = document.getElementById('edit-subject-wrapper');
    const subjectInput = document.getElementById('editSubject');
    
    if (me.account_type === 'teacher') {
        subjectInput.value = me.subject || '';
        subjectWrapper.style.display = 'block';
    } else {
        subjectInput.value = '';
        subjectWrapper.style.display = 'none';
    }

    // --- Profile Picture Preview ---
    const preview = document.getElementById('editProfilePicPreview');
    // Check both potential property names for the image URL
    const picUrl = me.profilePicUrl || me.profile_pic;

    if (picUrl) {
        preview.style.setProperty('--avatar-image', `url(${picUrl})`);
    } else {
        preview.style.removeProperty('--avatar-image');
    }

    // Re-attach file input listener
    const fileInput = document.getElementById('profilePicInput');
    const removeBtn = document.getElementById('removeProfilePicBtn');
    const editPicBtn = document.getElementById('editProfilePicBtn');
    const picWrap = document.getElementById('editProfilePicWrap');

    // Reset per-open: a removal abandoned by backing out must not still be armed
    // the next time the page is opened.
    profilePicRemoved = false;
    fileInput.value = null;
    // The original file behind a photo picked on this visit, plus how it was
    // framed, so Edit reopens the whole photo rather than re-cropping the crop.
    let avatarEdit = null;
    const syncPicButtons = () => {
        const hasPic = !!(profileData.me && profileData.me.profilePicUrl);
        if (removeBtn) removeBtn.classList.toggle('hidden', !hasPic);
        if (editPicBtn) editPicBtn.classList.toggle('hidden', !hasPic);
    };
    syncPicButtons();

    const applyAvatar = (res) => {
        preview.style.setProperty('--avatar-image', `url(${res.dataUrl})`);
        // Update the global object so it saves correctly
        profileData.me.profilePicUrl = res.dataUrl;
        profilePicRemoved = false;  // picking a photo cancels a pending removal
        avatarEdit = res.source ? { source: res.source, state: res.state } : null;
        syncPicButtons();
        replayClass(picWrap, 'pe-just-set');
    };
    const pickAvatar = async (file) => {
        const res = await editPickedPhoto(file, 'avatar');
        if (res) applyAvatar(res);
    };
    const editAvatar = async () => {
        const url = profileData.me.profilePicUrl;
        if (!avatarEdit && !url) { fileInput.click(); return; }
        if (!avatarEdit && isGifUrl(url)) {
            showToast('GIFs can\'t be edited. Pick a photo to crop instead.', 'error');
            return;
        }
        const res = await openPhotoEditor({
            kind: 'avatar',
            source: avatarEdit ? avatarEdit.source : url,
            state: avatarEdit ? avatarEdit.state : null,
        });
        if (res) applyAvatar(res);
    };

    fileInput.onchange = (event) => {
        const file = event.target.files[0];
        fileInput.value = null;
        if (file) pickAvatar(file);
    };
    if (editPicBtn) editPicBtn.onclick = editAvatar;

    if (picWrap) {
        picWrap.onclick = () => { fileInput.value = null; fileInput.click(); };
        picWrap.onkeydown = (e) => {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            e.preventDefault();
            picWrap.onclick();
        };
        // This page re-runs on every visit and addEventListener would stack a
        // new drop handler each time, so the listener goes on once and calls
        // whichever visit's handler is current.
        picWrap._peDrop = pickAvatar;
        if (!picWrap.dataset.dropWired) {
            picWrap.dataset.dropWired = '1';
            initImageDropZone(picWrap, (file) => picWrap._peDrop(file));
        }
    }

    if (removeBtn) {
        removeBtn.onclick = () => {
            // Falls back to the default avatar; the flag is what tells the server
            // this was deliberate rather than an untouched form.
            preview.style.removeProperty('--avatar-image');
            profileData.me.profilePicUrl = null;
            profileData.me.profile_pic = null;
            profilePicRemoved = true;
            avatarEdit = null;
            fileInput.value = null;
            syncPicButtons();
            showToast('Photo removed. Save to confirm.', 'success');
        };
    }

    // Finally, show the page
    showPage('edit-profile-page');
}

// --- Account settings: contact preferences, quiet hours, devices, blocks, guardian ---
const ACCOUNT_SETTING_KEYS = ['dm_privacy', 'tag_privacy', 'show_online_status', 'show_follow_lists',
                              'quiet_hours_enabled', 'quiet_hours_start', 'quiet_hours_end'];
let accountSettingsHydrated = false;

function paintAccountSettings(src) {
    const s = src || {};
    document.getElementById('editDmPrivacy').value = s.dm_privacy || 'everyone';
    document.getElementById('editTagPrivacy').value = s.tag_privacy || 'everyone';
    document.getElementById('editShowOnline').checked = s.show_online_status !== false;
    document.getElementById('editShowFollowLists').checked = s.show_follow_lists !== false;
    document.getElementById('editQuietHours').checked = !!s.quiet_hours_enabled;
    document.getElementById('editQuietStart').value = s.quiet_hours_start || '22:00';
    document.getElementById('editQuietEnd').value = s.quiet_hours_end || '07:00';
    syncQuietHoursRow();
}

function syncQuietHoursRow() {
    const on = document.getElementById('editQuietHours').checked;
    document.getElementById('quietHoursTimes').classList.toggle('hidden', !on);
}

function settingsEmptyRow(text) {
    const li = document.createElement('li');
    li.className = 'settings-list-empty';
    li.textContent = text;
    return li;
}

function settingsListRow({ title, sub, badge, avatar, buttonLabel, onButton }) {
    const li = document.createElement('li');
    li.className = 'settings-list-row';
    if (avatar !== undefined) {
        const pic = document.createElement('div');
        pic.className = 'settings-avatar';
        pic.style.backgroundImage = `url("${avatar || 'default-avatar.png'}")`;
        li.appendChild(pic);
    }
    const text = document.createElement('div');
    text.className = 'settings-list-text';
    const titleEl = document.createElement('div');
    titleEl.className = 'settings-list-title';
    titleEl.textContent = title;
    if (badge) {
        const b = document.createElement('span');
        b.className = 'settings-badge';
        b.textContent = badge;
        titleEl.appendChild(b);
    }
    text.appendChild(titleEl);
    if (sub) {
        const subEl = document.createElement('div');
        subEl.className = 'settings-list-sub';
        subEl.textContent = sub;
        text.appendChild(subEl);
    }
    li.appendChild(text);
    if (buttonLabel) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'settings-row-btn';
        btn.textContent = buttonLabel;
        btn.onclick = () => onButton(btn, li);
        li.appendChild(btn);
    }
    return li;
}

function loadSessionsList() {
    const list = document.getElementById('sessionsList');
    const revokeAll = document.getElementById('revokeOtherSessionsBtn');
    list.replaceChildren(settingsEmptyRow('Loading…'));
    revokeAll.classList.add('hidden');

    fetch(`${API_BASE_URL}/api/me/sessions`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => r.ok ? r.json() : Promise.reject(r.status))
        .then(data => {
            const sessions = data.sessions || [];
            list.replaceChildren();
            sessions.forEach(s => {
                const issued = s.created_at ? formatPostTimestamp(new Date(s.created_at)) : '';
                list.appendChild(settingsListRow({
                    title: s.current ? 'This device' : 'Signed-in device',
                    badge: s.current ? 'Current' : null,
                    sub: issued ? `Signed in ${issued}` : null,
                    buttonLabel: s.current ? null : 'Sign out',
                    onButton: (btn, row) => revokeSession(s.id, btn, row),
                }));
            });
            if (!sessions.length) list.appendChild(settingsEmptyRow('No signed-in devices.'));
            revokeAll.classList.toggle('hidden', !sessions.some(s => !s.current));
        })
        .catch(() => list.replaceChildren(settingsEmptyRow('Could not load your devices.')));
}

function revokeSession(sessionId, btn, row) {
    btn.disabled = true;
    fetch(`${API_BASE_URL}/api/me/sessions/${sessionId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
        .then(r => r.json().then(body => ({ ok: r.ok, body })))
        .then(({ ok, body }) => {
            if (!ok) throw new Error(body.error || 'Could not sign out that device.');
            showToast('Device signed out.', 'success');
            loadSessionsList();
        })
        .catch(err => {
            btn.disabled = false;
            showToast(err.message || 'Could not sign out that device.', 'error');
        });
}

function revokeOtherSessions() {
    showConfirmationModal({
        title: 'Sign out of other devices?',
        text: 'Every device except this one will be signed out of your account.',
        onConfirm: () => {
            fetch(`${API_BASE_URL}/api/me/sessions/revoke-others`, {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${apiToken}` }
            })
                .then(r => r.ok ? r.json() : Promise.reject(r.status))
                .then(() => {
                    showToast('Signed out of all other devices.', 'success');
                    loadSessionsList();
                })
                .catch(() => showToast('Could not sign out other devices.', 'error'));
        }
    });
}

function loadBlockedAccountsList() {
    const list = document.getElementById('blockedAccountsList');
    list.replaceChildren(settingsEmptyRow('Loading…'));

    fetch(`${API_BASE_URL}/api/me/blocked`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => r.ok ? r.json() : Promise.reject(r.status))
        .then(data => {
            const blocked = data.blocked || [];
            list.replaceChildren();
            blocked.forEach(u => {
                list.appendChild(settingsListRow({
                    avatar: u.profile_pic,
                    title: u.fullName || u.username,
                    sub: `@${u.username}`,
                    buttonLabel: 'Unblock',
                    onButton: (btn, row) => {
                        unblockUser(u.username);
                        row.remove();
                        if (!list.children.length) list.appendChild(settingsEmptyRow("You haven't blocked anyone."));
                    },
                }));
            });
            if (!blocked.length) list.appendChild(settingsEmptyRow("You haven't blocked anyone."));
        })
        .catch(() => list.replaceChildren(settingsEmptyRow('Could not load blocked accounts.')));
}

function maskEmail(email) {
    const [local, domain] = String(email || '').split('@');
    if (!domain) return email || '';
    return `${local.charAt(0)}${'*'.repeat(Math.max(1, local.length - 1))}@${domain}`;
}

// Read-only: what is on record, or what is still owed. Asking a guardian reuses
// the existing consent modal rather than a second flow.
function renderGuardianInfo(src) {
    const section = document.getElementById('guardianInfoSection');
    const box = document.getElementById('guardianInfo');
    const guardian = src && src.guardian;
    const consent = src && src.guardian_consent;
    box.replaceChildren();

    const line = (text) => {
        const p = document.createElement('div');
        p.textContent = text;
        box.appendChild(p);
    };

    if (guardian && guardian.approved_at) {
        line(`A guardian approved this account on ${formatGuardianDeadline(guardian.approved_at)}.`);
        if (guardian.email) line(`Guardian email: ${maskEmail(guardian.email)}`);
    } else if (consent && consent.required) {
        if (consent.status === 'pending') {
            line(`Waiting for your guardian (${maskEmail(consent.guardian_email)}) to respond.`);
        } else {
            line(`Guardian consent is needed by ${formatGuardianDeadline(consent.deadline)}.`);
        }
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'settings-row-btn';
        btn.textContent = consent.status === 'pending' ? 'View request' : 'Ask my guardian';
        btn.onclick = () => {
            guardianConsentDismissed = false;
            maybeShowGuardianConsentModal({ guardian_consent: consent });
        };
        box.appendChild(btn);
    } else {
        section.classList.add('hidden');
        return;
    }
    section.classList.remove('hidden');
}

// Replace your existing saveProfile function with this one

// Replace your existing saveProfile function with this one

// The channels of the lounge currently on screen, in the order they are drawn in
// the sidebar. The header swipe gesture walks this list, so it has to stay in
// sync with what the user can actually see.
// What each visibility setting looks like in the channel sidebar. One table for
// the three places that draw it, which before this were three copies that each
// had to be remembered separately whenever a setting was added.
const CHANNEL_LOCK_ICONS = {
    mods_only_chat: 'fas fa-lock',
    mods_only_view: 'fas fa-user-shield',
    restricted: 'fas fa-user-lock',
};

const CHANNEL_LOCK_TITLES = {
    mods_only_chat: 'Only moderators can post here',
    mods_only_view: 'Only moderators can see this channel',
    restricted: 'Only chosen members can see this channel',
};

function channelLockIcon(level) {
    const cls = CHANNEL_LOCK_ICONS[level];
    if (!cls) return '';
    const title = CHANNEL_LOCK_TITLES[level] || '';
    return `<i class="${cls}" title="${title}" style="margin-left: 8px; color: #888; font-size: 0.8em;"></i>`;
}

let currentLoungeChannelList = [];
// The lounge's channel groups, in sidebar order: [{ id, name }].
let currentLoungeChannelGroups = [];

function renderLoungeChannels(channels, groups) {
    const list = document.getElementById('lounge-channels-list');
    list.innerHTML = '';

    // Iterate the sanitised copy, never the argument. A failed /channels request
    // hands this `undefined`, and calling .forEach on it threw right here -- which
    // left the sidebar stuck on the "Loading..." row showLounge had just put there,
    // with no error anywhere the user could see.
    currentLoungeChannelList = Array.isArray(channels) ? channels : [];
    currentLoungeChannelGroups = Array.isArray(groups) ? groups : [];

    // The category header ("Chats" + the create button, or the reorder bar) is drawn
    // by setChannelReorderMode at the bottom of this function -- one place decides
    // what it says, so the two states cannot get out of step.

    // Project channels are drawn in their own section below the chat list rather
    // than mixed into it. Two reasons: the drag-to-reorder gestures wired further
    // down operate on every child of #lounge-channels-list, so a non-draggable row
    // in there would be a hole in the gesture; and a task board genuinely is a
    // different kind of thing, which is the whole point of giving it a heading.
    // A lounge with project mode off has none of these, so this is a no-op and the
    // sidebar is byte-for-byte what it was.
    const chatChannels = currentLoungeChannelList.filter(c => (c.kind || 'chat') === 'chat');
    const projectChannels = currentLoungeChannelList.filter(c => (c.kind || 'chat') !== 'chat');
    renderLoungeProjectChannels(projectChannels);

    // Ungrouped channels first, straight into the list, then one block per group.
    // Each group carries its own inner .lounge-channels-list, which is what keeps
    // a drag inside its group: the gesture measures the rows of the list the
    // grabbed row belongs to. A channel pointing at a group that no longer exists
    // falls back to ungrouped rather than vanishing.
    const groupIds = new Set(currentLoungeChannelGroups.map(g => g.id));
    const inGroup = new Map(currentLoungeChannelGroups.map(g => [g.id, []]));
    const ungrouped = [];
    chatChannels.forEach(channel => {
        if (channel.group_id != null && groupIds.has(channel.group_id)) inGroup.get(channel.group_id).push(channel);
        else ungrouped.push(channel);
    });

    ungrouped.forEach(channel => list.appendChild(buildLoungeChannelRow(channel)));
    currentLoungeChannelGroups.forEach(group => {
        const members = inGroup.get(group.id);
        // A group this member has nothing in is not shown to them. Mods still
        // see it -- it is somewhere to move channels into.
        if (!members.length && !canReorderChannels()) return;
        list.appendChild(buildLoungeChannelGroup(group, members));
    });

    // The header swipe walks this list, so it follows the order actually drawn:
    // chats top to bottom through their groups, then the Project section.
    currentLoungeChannelList = [
        ...ungrouped,
        ...currentLoungeChannelGroups.flatMap(g => inGroup.get(g.id)),
        ...projectChannels,
    ];

    // A fresh list is never mid-drag. Leaving the flag set would strand the grips on
    // screen with no Done button (the header above is rebuilt every render).
    setChannelReorderMode(false);

    updateMobileChannelBadge();
}

function buildLoungeChannelRow(channel) {
    if (socket) {
        socket.emit('join_lounge_channel', { channel_id: channel.id });
    }

    const li = document.createElement('li');
    li.className = 'lounge-channel-item';
    li.id = `channel-item-${channel.id}`;
    
    // --- ADD THIS CHECK ---
    // If the server says it's unread, add the class immediately
    if (channel.has_unread) {
        li.classList.add('has-unread');
    }
    // --- END CHECK ---

    li.onclick = () => loadLoungeChannel(channel);

    const channelNameSpan = document.createElement('span');
    channelNameSpan.style.display = 'flex'; 
    channelNameSpan.style.alignItems = 'center';

    // Three distinct states, three distinct icons: a padlock is "you can read
    // but not write", a shield is "moderators only", and the user-lock is the
    // committee case -- a channel whose membership is a list of names rather
    // than a rank. Using the same padlock for the last two would tell a
    // member the exec channel is merely read-only.
    let suffixIcon = channelLockIcon(channel.permission_level);

    let mainChannelIcon = '';
    if (channel.is_main) {
        mainChannelIcon = '<i class="fas fa-star main-channel-icon" style="margin-left: 6px;"></i>';
    }

    channelNameSpan.innerHTML = `# ${channel.name} ${suffixIcon} ${mainChannelIcon} <div class="unread-indicator"></div>`;

    li.appendChild(channelNameSpan);

    const menuBtn = document.createElement('i');
    menuBtn.className = 'fas fa-ellipsis-v channel-options-btn';
    menuBtn.onclick = (event) => openChannelContextMenu(event, channel);
    li.appendChild(menuBtn);

    // The grip only becomes visible once the list is in reorder mode; it lives in
    // the DOM unconditionally so entering that mode is a class flip, not a redraw
    // (redrawing mid-gesture is what would drop the finger's grab).
    const grip = document.createElement('i');
    grip.className = 'fas fa-grip-lines channel-drag-handle';
    li.appendChild(grip);

    // The order the server is told is read straight off the DOM, so the id has to
    // travel on the element rather than in a parallel array.
    li.dataset.channelId = String(channel.id);
    li._channelData = channel;

    wireChannelReorderGestures(li, channel);

    return li;
}

/* --- Channel groups: named, collapsible sections of the chat list --- */

// Which groups this viewer has folded, per lounge. A per-viewer convenience, so
// browser storage is fine -- and a storage failure just means everything opens.
function loungeGroupCollapseKey() {
    return `apex.loungeGroupsCollapsed.${currentLoungeId}`;
}

function collapsedLoungeGroups() {
    try {
        const raw = JSON.parse(localStorage.getItem(loungeGroupCollapseKey()) || '[]');
        return new Set(Array.isArray(raw) ? raw.map(Number) : []);
    } catch (e) {
        return new Set();
    }
}

function setLoungeGroupCollapsed(groupId, collapsed) {
    const set = collapsedLoungeGroups();
    if (collapsed) set.add(Number(groupId)); else set.delete(Number(groupId));
    try { localStorage.setItem(loungeGroupCollapseKey(), JSON.stringify([...set])); } catch (e) { /* not remembered */ }
}

function buildLoungeChannelGroup(group, channels) {
    const block = document.createElement('li');
    block.className = 'lounge-channel-group';
    block.dataset.groupId = String(group.id);
    // A folded group still shows the channel you are in, and its header gets a
    // dot while anything folded away is unread -- see the CSS.
    if (collapsedLoungeGroups().has(group.id)) block.classList.add('is-collapsed');

    const header = document.createElement('div');
    header.className = 'lounge-channel-group-header';
    header.setAttribute('role', 'button');
    header.setAttribute('aria-expanded', String(!block.classList.contains('is-collapsed')));
    header.innerHTML = '<i class="fas fa-chevron-down lounge-group-chevron"></i>';

    // Free text a moderator typed, so it goes in as text.
    const name = document.createElement('span');
    name.className = 'lounge-group-name';
    name.textContent = group.name;
    header.appendChild(name);

    const dot = document.createElement('span');
    dot.className = 'lounge-group-unread';
    header.appendChild(dot);

    if (canReorderChannels()) {
        const add = document.createElement('i');
        add.className = 'fas fa-plus lounge-group-btn';
        add.title = 'Create a channel in this group';
        add.onclick = (event) => { event.stopPropagation(); showCreateChannelModal(group.id); };
        header.appendChild(add);

        const more = document.createElement('i');
        more.className = 'fas fa-ellipsis-h lounge-group-btn';
        more.title = 'Group options';
        more.onclick = (event) => { event.stopPropagation(); openChannelGroupMenu(event, group); };
        header.appendChild(more);
    }

    header.onclick = () => {
        const collapsed = !block.classList.contains('is-collapsed');
        block.classList.toggle('is-collapsed', collapsed);
        header.setAttribute('aria-expanded', String(!collapsed));
        setLoungeGroupCollapsed(group.id, collapsed);
    };
    block.appendChild(header);

    const inner = document.createElement('ul');
    inner.className = 'lounge-channels-list lounge-group-channels';
    channels.forEach(channel => inner.appendChild(buildLoungeChannelRow(channel)));
    if (!channels.length) {
        const empty = document.createElement('li');
        empty.className = 'lounge-group-empty';
        empty.textContent = 'No channels yet';
        inner.appendChild(empty);
    }
    block.appendChild(inner);
    return block;
}

// One menu, drawn as a context menu under a mouse and as the bottom sheet on a
// touchscreen -- the same split the channel menu itself makes.
function openLoungeChoiceMenu(point, title, actions) {
    if (isTouchUi()) {
        showChannelOptionsSheet(title, actions);
        return;
    }
    // Next tick: when this is opened from an item in another context menu, the
    // same click is still on its way up to the document handler that hides every
    // .context-menu, and would take this one down with it.
    setTimeout(() => drawLoungeChoiceMenu(point, actions), 0);
}

function drawLoungeChoiceMenu(point, actions) {
    document.querySelectorAll('.context-menu').forEach(menu => menu.remove());
    const menu = document.createElement('div');
    menu.className = 'context-menu';
    actions.forEach(action => {
        const item = document.createElement('a');
        item.className = 'context-menu-item' + (action.danger ? ' danger' : '');
        item.innerHTML = `<i class="fas ${action.icon}" style="margin-right: 8px;"></i>`;
        item.appendChild(document.createTextNode(action.label));
        item.onclick = () => { menu.remove(); action.run(); };
        menu.appendChild(item);
    });
    document.body.appendChild(menu);

    let x = point.x;
    let y = point.y;
    if (x + menu.offsetWidth > window.innerWidth) x -= menu.offsetWidth;
    if (y + menu.offsetHeight > window.innerHeight) y -= menu.offsetHeight;
    menu.style.left = `${x}px`;
    menu.style.top = `${y}px`;
}

function openChannelGroupMenu(event, group) {
    const index = currentLoungeChannelGroups.findIndex(g => g.id === group.id);
    const actions = [
        { icon: 'fa-plus', label: 'Create Channel Here', run: () => showCreateChannelModal(group.id) },
        { icon: 'fa-pen', label: 'Rename Group', run: () => openChannelGroupNameModal(group) },
    ];
    if (index > 0) actions.push({ icon: 'fa-arrow-up', label: 'Move Up', run: () => moveChannelGroup(group.id, -1) });
    if (index > -1 && index < currentLoungeChannelGroups.length - 1) {
        actions.push({ icon: 'fa-arrow-down', label: 'Move Down', run: () => moveChannelGroup(group.id, 1) });
    }
    actions.push({ icon: 'fa-trash', label: 'Delete Group', run: () => deleteChannelGroup(group), danger: true });
    openLoungeChoiceMenu({ x: event.pageX, y: event.pageY }, group.name, actions);
}

// Where the last channel context menu opened, so the group picker it leads to
// can open in the same spot rather than jumping to a corner.
let lastChannelMenuPoint = { x: 0, y: 0 };

function openMoveChannelToGroup(channelId) {
    const channel = currentLoungeChannelList.find(c => c.id === channelId);
    if (!channel) return;
    const actions = currentLoungeChannelGroups
        .filter(g => g.id !== channel.group_id)
        .map(g => ({ icon: 'fa-folder', label: g.name, run: () => setChannelGroup(channel.id, g.id) }));
    if (channel.group_id != null) {
        actions.push({ icon: 'fa-folder-minus', label: 'Remove From Group', run: () => setChannelGroup(channel.id, null) });
    }
    actions.push({ icon: 'fa-folder-plus', label: 'New Group…', run: () => openChannelGroupNameModal(null, channel.id) });
    openLoungeChoiceMenu(lastChannelMenuPoint, `Move #${channel.name} to`, actions);
}

function channelGroupRequest(url, method, body) {
    return fetch(`${API_BASE_URL}${url}`, {
        method,
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: body === undefined ? undefined : JSON.stringify(body)
    })
    .then(response => response.json().then(data => {
        if (!response.ok) throw new Error(data.error || 'Something went wrong.');
        return data;
    }));
}

function setChannelGroup(channelId, groupId) {
    return channelGroupRequest(`/api/lounge/channel/${channelId}/group`, 'PUT', { group_id: groupId })
        .then(() => reloadLoungeChannels(currentLoungeId))
        .catch(err => showToast(err.message, 'error'));
}

function moveChannelGroup(groupId, step) {
    const order = currentLoungeChannelGroups.map(g => g.id);
    const from = order.indexOf(groupId);
    const to = from + step;
    if (from === -1 || to < 0 || to >= order.length) return;
    [order[from], order[to]] = [order[to], order[from]];
    channelGroupRequest(`/api/lounge/${currentLoungeId}/channel-groups/reorder`, 'PUT', { order })
        .then(() => reloadLoungeChannels(currentLoungeId))
        .catch(err => showToast(err.message, 'error'));
}

function deleteChannelGroup(group) {
    showConfirmationModal({
        title: 'Delete Group?',
        // The modal renders this as HTML and the group name is moderator free
        // text, so the name stays out of it.
        text: 'Its channels are kept and move back to the top of the list.',
        onConfirm: () => channelGroupRequest(`/api/lounge/channel-group/${group.id}`, 'DELETE')
            .then(() => {
                setLoungeGroupCollapsed(group.id, false);
                reloadLoungeChannels(currentLoungeId);
            })
            .catch(err => showToast(err.message, 'error'))
    });
}

// Create (group null) or rename. With moveChannelId, the new group is created
// and that channel moved straight into it -- the "New Group…" picker entry.
function openChannelGroupNameModal(group, moveChannelId = null) {
    const modal = document.getElementById('channel-group-modal');
    const input = document.getElementById('channel-group-name-input');
    const saveBtn = document.getElementById('channel-group-save-btn');
    document.getElementById('channel-group-modal-title').textContent = group ? 'Rename Group' : 'New Channel Group';
    input.value = group ? group.name : '';
    modal.classList.remove('hidden');
    setTimeout(() => input.focus(), 100);

    const submit = () => {
        const name = input.value.trim();
        if (!name) {
            showToast('Give the group a name.', 'error');
            return;
        }
        saveBtn.disabled = true;
        const request = group
            ? channelGroupRequest(`/api/lounge/channel-group/${group.id}`, 'PUT', { name })
            : channelGroupRequest(`/api/lounge/${currentLoungeId}/channel-groups`, 'POST', { name })
                .then(created => moveChannelId
                    ? channelGroupRequest(`/api/lounge/channel/${moveChannelId}/group`, 'PUT', { group_id: created.id })
                    : created);
        request
            .then(() => {
                closeChannelGroupModal();
                reloadLoungeChannels(currentLoungeId);
            })
            .catch(err => showToast(err.message, 'error'))
            .finally(() => { saveBtn.disabled = false; });
    };
    saveBtn.onclick = submit;
    input.onkeydown = (event) => { if (event.key === 'Enter') { event.preventDefault(); submit(); } };
}

// A desktop build only exists once its file has been put on the server (the Mac
// one comes out of a GitHub Actions run and is copied up by hand). Until then
// its button would hand the browser a 404 page, which Chrome saves as
// "mac.html -- File wasn't available on site". /api/app-release reports null
// for a missing file, so those buttons become a disabled "Coming soon" instead.
function markUnavailableDownloads() {
    fetch(`${API_BASE_URL}/api/app-release`, { cache: 'no-store' })
        .then(res => res.json())
        .then(release => {
            document.querySelectorAll('#download-page [data-release]').forEach(btn => {
                if (release[btn.dataset.release]) return;
                btn.classList.add('dl-btn--unavailable');
                btn.removeAttribute('href');
                btn.removeAttribute('download');
                btn.setAttribute('aria-disabled', 'true');
                btn.textContent = 'Coming soon';
            });
        })
        .catch(() => { /* leave the buttons as they are */ });
}

function closeChannelGroupModal() {
    document.getElementById('channel-group-modal').classList.add('hidden');
}

/* ===========================================================================
   CHANNEL REORDERING
   Lounge owners and moderators arrange their own sidebar by dragging.

   Reordering is always an explicit mode, on every input type. You arm it from the
   channel's own menu -- the 3-dot on a mouse, a long press on a touchscreen -- and
   leave it with Done. Dragging is deliberately NOT live outside that mode: a
   sidebar row is a link first, the list scrolls on a phone, and a drag that could
   fire at any moment turns both of those into a coin flip.
   =========================================================================== */

// Whether the touch list is armed for dragging. Mouse dragging ignores this.
let channelReorderMode = false;

// The in-flight drag: null between gestures.
let channelDragState = null;

function canReorderChannels() {
    // Lounge role only. A global staff account can delete a channel it is policing,
    // but the server will not let it rearrange someone's sidebar, so offering the
    // control here would just produce a 403.
    return currentUserLoungeRole === 'owner' || currentUserLoungeRole === 'moderator';
}

// Press-and-hold a channel row to open its options, and the tap that opens the
// channel. Split out of wireChannelReorderGestures so the PROJECT list can have
// it too: that list is drawn separately (deliberately -- the drag gestures below
// operate on #lounge-channels-list, and a board is not reorderable), and the
// split meant boards got no long press at all. On a phone that left them with no
// options menu whatsoever, since the 3-dot only appears on hover.
//
// `onTap` rather than a hard-coded loadLoungeChannel so this owns onclick
// outright -- the click swallowing below has to be in the same handler as the
// navigation it is suppressing, or the row opens behind the sheet.
function wireChannelOptionsLongPress(li, channel, onTap) {
    // Stops iOS raising the text-selection loupe over a long press, and stops a
    // mouse drag painting the channel name blue as it moves.
    li.style.userSelect = 'none';
    li.style.webkitTouchCallout = 'none';

    let pressTimer = null;
    let isLongPress = false;
    const cancelPress = () => {
        if (pressTimer) { clearTimeout(pressTimer); pressTimer = null; }
    };

    li.addEventListener('touchstart', () => {
        if (!isTouchUi()) return;
        if (channelReorderMode) return; // the row is a drag handle now, not a link
        isLongPress = false;
        pressTimer = setTimeout(() => {
            pressTimer = null;
            isLongPress = true;
            openChannelOptionsSheet(channel);
        }, LONG_PRESS_DURATION);
    }, { passive: true });

    li.addEventListener('touchend', cancelPress);
    li.addEventListener('touchmove', cancelPress);
    li.addEventListener('touchcancel', cancelPress);

    // Android raises `contextmenu` on a long press as well, which would open the
    // sheet a second time on top of the timer above and re-run its entry animation.
    li.oncontextmenu = (event) => {
        if (isTouchInput()) { event.preventDefault(); return; }
        openChannelContextMenu(event, channel);
    };

    li.onclick = (e) => {
        // A long press still emits a click on touchend, and by then the sheet is
        // under the finger. Swallow it, or the channel opens behind the sheet.
        if (isLongPress) {
            e.preventDefault();
            e.stopPropagation();
            isLongPress = false;
            return;
        }
        // In reorder mode the rows are handles, not links.
        if (channelReorderMode) {
            e.preventDefault();
            return;
        }
        onTap();
    };
}

function wireChannelReorderGestures(li, channel) {
    wireChannelOptionsLongPress(li, channel, () => loadLoungeChannel(channel));

    li.addEventListener('pointerdown', (event) => {
        // Reorder mode is the whole gate. Outside it a press on a channel is a
        // press on a link, whatever it was made with.
        if (!channelReorderMode || !canReorderChannels()) return;
        if (event.button > 0) return; // right/middle click is not a drag
        startChannelDrag(li, event);
    });

}

// How long the picked-up channel takes to float into its gap on release.
const CHANNEL_SETTLE_MS = 220;

// Finishes a settle animation that is still running. Held at module scope because
// the drag state is already gone by the time the float-into-place plays, and a new
// gesture (or leaving reorder mode) has to be able to cut it short.
let channelSettleFinish = null;

function startChannelDrag(li, event) {
    // Never let a previous gesture linger. If one ever did survive, its stale state
    // would block every drag that followed it for the rest of the page's life.
    endChannelDrag(false);
    if (channelSettleFinish) channelSettleFinish();

    // Whichever list the row belongs to -- the chat list or the Project one.
    // This used to name #lounge-channels-list outright, which is why boards
    // could not be dragged: the row was not in the list the maths was measuring,
    // so indexOf came back -1 and the gesture bailed on the first frame.
    const list = li.closest('.lounge-channels-list');
    if (!list) return;

    // Roles is a virtual row with no LoungeChannel behind it, so it has no
    // position to save and must not take part. Excluded from `rows` rather than
    // merely refused a drag: it sits at the top of the Project list, and leaving
    // it in would shift every index by one against the order actually sent.
    // :scope > -- direct rows only. The chat list holds each group's own list
    // inside it, and a drag stays within the list it started in.
    const rows = Array.from(list.querySelectorAll(':scope > .lounge-channel-item:not(.lounge-roles-item)'));
    const index = rows.indexOf(li);
    if (index === -1) return;

    // Measure the layout ONCE, up front, and do every calculation from here on in
    // those frozen coordinates.
    //
    // This is the whole trick behind the drag feeling smooth. Nothing moves in the
    // DOM until the finger lifts: the picked-up row and the rows getting out of its
    // way are all just transforms over a layout that never changes. So the maths
    // can never feed back into itself -- a row shifting cannot move the threshold
    // that made it shift, which is what makes a naive sortable flicker -- and a
    // gesture across ten channels costs zero reflows.
    //
    // offsetTop, not getBoundingClientRect: it is relative to the list, so
    // auto-scrolling mid-drag does not invalidate a single measurement.
    const tops = rows.map(r => r.offsetTop);
    const heights = rows.map(r => r.offsetHeight);
    const centers = tops.map((t, i) => t + heights[i] / 2);

    // Row-to-row pitch, taken from the real layout so it includes the gap between
    // rows rather than assuming the margin.
    let pitch = heights[index];
    if (rows.length > 1) {
        pitch = index < rows.length - 1
            ? tops[index + 1] - tops[index]
            : tops[index] - tops[index - 1];
    }

    // The row's OWN scroller. Each list has a wrapper of its own, and a
    // document-wide query returned the chat one for every drag -- so a board
    // drag auto-scrolled the wrong pane.
    const wrapper = li.closest('.lounge-channel-list-wrapper');

    channelDragState = {
        list, wrapper, rows, tops, heights, centers, pitch,
        li, index,
        targetIndex: index,
        pointerId: event.pointerId,
        startY: event.clientY,
        startScroll: wrapper ? wrapper.scrollTop : 0,
        lastClientY: event.clientY,
        moved: false,
        raf: null
    };

    li.classList.add('channel-dragging');
    rows.forEach(row => { if (row !== li) row.classList.add('channel-shifting'); });
    if (navigator.vibrate) navigator.vibrate(15);

    // The listeners go on the document, and the row is deliberately NOT given
    // pointer capture -- a captured element that gets re-inserted in the DOM loses
    // the rest of its gesture. Nothing re-inserts anything mid-drag any more, but
    // document listeners remain the right place: they keep hearing the pointer even
    // when it outruns the row or leaves the sidebar entirely.
    document.addEventListener('pointermove', onChannelDragMove, { passive: false });
    document.addEventListener('pointerup', onChannelDragEnd);
    document.addEventListener('pointercancel', onChannelDragEnd);

    channelDragState.raf = requestAnimationFrame(channelDragFrame);
}

function onChannelDragMove(event) {
    const state = channelDragState;
    if (!state || event.pointerId !== state.pointerId) return;

    state.moved = true;
    state.lastClientY = event.clientY;
    // The rows carry `touch-action: none` in reorder mode, so the browser is not
    // also scrolling the list underneath us -- this stops the text selection a
    // mouse drag would otherwise paint across the channel names.
    if (event.cancelable) event.preventDefault();

    updateChannelDrag(state);
}

// Runs every frame for as long as a channel is held. Only the edge auto-scroll
// actually needs this -- holding still against the top or bottom of the list has to
// keep scrolling even though no pointermove is being fired.
function channelDragFrame() {
    const state = channelDragState;
    if (!state) return;
    if (autoScrollChannelList(state)) updateChannelDrag(state);
    state.raf = requestAnimationFrame(channelDragFrame);
}

function updateChannelDrag(state) {
    const { li, index, rows, centers, tops, heights, pitch } = state;

    // Follow the finger 1:1, including however far the list has scrolled under it.
    const scrollDelta = state.wrapper ? state.wrapper.scrollTop - state.startScroll : 0;
    let dy = (state.lastClientY - state.startY) + scrollDelta;

    // Keep the card inside the list. Without this it can be flung far past the
    // first or last channel, and the long float back on release reads as a glitch.
    const listTop = tops[0];
    const listBottom = tops[rows.length - 1] + heights[rows.length - 1];
    dy = Math.max(listTop - tops[index], Math.min(dy, listBottom - (tops[index] + heights[index])));

    li.style.translate = `0 ${dy}px`;

    // Which slot the card is over, measured against where the rows STARTED. Using
    // the frozen centres is what gives the swap a stable half-row of hysteresis
    // instead of a threshold that runs away from the finger.
    // The comparisons are inclusive, and that matters at exactly two points: the
    // ends. Dragged hard against either end, the clamp above puts the card's centre
    // exactly ON the first or last row's centre -- and with a strict `>` that ties,
    // leaving the card one slot short of the end it is visibly pressed against.
    const center = centers[index] + dy;
    let target = index;
    while (target < rows.length - 1 && center >= centers[target + 1]) target++;
    while (target > 0 && center <= centers[target - 1]) target--;

    if (target === state.targetIndex) return;
    state.targetIndex = target;

    // Everything between the card's old slot and its new one steps aside by exactly
    // one row, opening the gap the card will drop into. These rows carry a CSS
    // transition, so each step is a glide rather than a jump.
    rows.forEach((row, i) => {
        if (row === li) return;
        let shift = 0;
        if (i > index && i <= target) shift = -pitch;
        else if (i < index && i >= target) shift = pitch;
        row.style.translate = shift ? `0 ${shift}px` : '';
    });
}

// Drags the list along when the card is held against either end of it. Returns
// whether it actually scrolled, so the caller knows to recompute. Speed ramps with
// how far into the edge zone the pointer is -- a gentle nudge near the boundary,
// faster the further in you push.
function autoScrollChannelList(state) {
    const wrapper = state.wrapper;
    if (!wrapper) return false;

    const rect = wrapper.getBoundingClientRect();
    const edge = 48;
    const maxSpeed = 14;
    const y = state.lastClientY;

    let delta = 0;
    if (y < rect.top + edge) {
        delta = -Math.ceil(maxSpeed * Math.min(1, (rect.top + edge - y) / edge));
    } else if (y > rect.bottom - edge) {
        delta = Math.ceil(maxSpeed * Math.min(1, (y - (rect.bottom - edge)) / edge));
    }
    if (!delta) return false;

    const before = wrapper.scrollTop;
    wrapper.scrollTop = before + delta;
    return wrapper.scrollTop !== before;
}

function onChannelDragEnd(event) {
    if (channelDragState && event.pointerId !== channelDragState.pointerId) return;
    endChannelDrag(true);
}

// The single teardown. Safe to call at any time, including when no drag is running,
// so anything that needs to get back to a clean slate can just call it.
function endChannelDrag(save) {
    document.removeEventListener('pointermove', onChannelDragMove);
    document.removeEventListener('pointerup', onChannelDragEnd);
    document.removeEventListener('pointercancel', onChannelDragEnd);

    const state = channelDragState;
    channelDragState = null;
    if (!state) return;

    if (state.raf) cancelAnimationFrame(state.raf);

    if (!save || !state.moved) {
        clearChannelDragStyles(state);
        return;
    }
    settleChannelDrag(state);
}

// The release. The card floats from wherever the finger left it into the gap the
// other rows have been holding open, and only once it has landed does the DOM
// actually change -- so the reorder itself is invisible, happening underneath a
// card already sitting exactly where the new markup will put it.
function settleChannelDrag(state) {
    const { li, index, targetIndex, tops, heights } = state;

    // Where the card's top ends up once the list closes around it.
    const restTop = targetIndex > index
        ? tops[targetIndex] + heights[targetIndex] - heights[index]
        : tops[targetIndex];

    li.classList.remove('channel-dragging');
    li.classList.add('channel-settling');
    li.style.translate = `0 ${restTop - tops[index]}px`;

    let done = false;
    const finish = () => {
        if (done) return;
        done = true;
        channelSettleFinish = null;
        li.removeEventListener('transitionend', onTransitionEnd);
        clearTimeout(timer);
        commitChannelOrder(state);
    };

    const onTransitionEnd = (event) => {
        if (event.target === li && event.propertyName === 'translate') finish();
    };
    li.addEventListener('transitionend', onTransitionEnd);

    // A drop that does not move the card fires no transition at all, and a dropped
    // frame can eat the event -- so this timer, not transitionend, is what actually
    // guarantees the DOM gets committed.
    const timer = setTimeout(finish, CHANNEL_SETTLE_MS + 120);
    channelSettleFinish = finish;
}

// Puts the reordered markup in place under the settled card and tells the server.
function commitChannelOrder(state) {
    const { list, li, rows, index, targetIndex } = state;

    clearChannelDragStyles(state);
    if (targetIndex === index) return;

    const others = rows.filter(row => row !== li);
    const before = others[targetIndex];
    if (before) list.insertBefore(li, before);
    else list.appendChild(li);

    saveChannelOrder();
}

function clearChannelDragStyles(state) {
    state.li.classList.remove('channel-dragging', 'channel-settling');
    state.rows.forEach(row => {
        row.classList.remove('channel-shifting');
        row.style.translate = '';
    });
}

// Reads the order off the DOM and tells the server. The sidebar is already showing
// the new order by the time this runs, so it only has to undo itself on failure.
function saveChannelOrder() {
    if (!currentLoungeId) return;

    // BOTH lists, chats first. The server rewrites the whole lounge's positions
    // as a dense 0..n-1 run from the ids it is given, so sending only one list
    // would renumber its channels ahead of every channel it did not mention --
    // reordering a board would have shuffled the chat list above it.
    //
    // :not(.lounge-roles-item) for the same reason as the drag: it is a virtual
    // row with no id, and .filter(Boolean) below would silently drop it anyway.
    const items = Array.from(document.querySelectorAll(
        '#lounge-channels-list .lounge-channel-item:not(.lounge-roles-item),' +
        ' #lounge-project-channels-list .lounge-channel-item:not(.lounge-roles-item)'));
    const order = items.map(li => Number(li.dataset.channelId)).filter(Boolean);
    if (!order.length) return;

    // Keep the in-memory list in step -- the lounge header's swipe gesture walks it,
    // and it would otherwise still swipe in the old order until the next reload.
    const byId = new Map(currentLoungeChannelList.map(c => [c.id, c]));
    const reordered = order.map(id => byId.get(id)).filter(Boolean);
    if (reordered.length === currentLoungeChannelList.length) {
        currentLoungeChannelList = reordered;
    }

    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/channels/reorder`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ order })
    })
    .then(response => response.json().then(body => ({ status: response.status, body })))
    .then(({ status, body }) => {
        if (status !== 200 || !body.ok) {
            showToast(body.error || 'Could not save the channel order.', 'error');
            // Put the sidebar back to whatever the server actually holds, rather than
            // leaving a rejected order on screen for the mod to trust.
            showLounge(currentLoungeId, document.getElementById('lounge-header-title').textContent);
        }
    })
    .catch(error => {
        console.error('Error saving channel order:', error);
        showToast('Could not save the channel order.', 'error');
    });
}

/* ===========================================================================
   LOUNGE PROJECT TOOLS

   A task board is a channel with kind === 'task', so it arrives through the same
   /channels payload, sits in the same sidebar, and inherits the lounge's
   membership and permission_level rules without a second access path. Nothing
   here is reachable -- or even rendered -- in a lounge that has project mode off.
   =========================================================================== */

// The board currently on screen, so the editor knows where to POST. Null whenever
// a chat channel is open.
let currentTaskChannel = null;
// Whether this member may change the board. Mirrors the server's own answer
// rather than being recomputed from the role here, so the two cannot disagree.
let currentTaskCanEdit = false;
// The task open in the editor, or null when the editor is adding a new one.
let editingTaskId = null;

const TASK_KIND_ICONS = {
    task: 'fa-list-check',
    deadline: 'fa-calendar-days',
    notice: 'fa-bullhorn',
};

// A tie decides WHO can see a board, never WHEN it is listed. Every board this
// member is allowed to see stays in the sidebar all the time, in the channel it
// has always been in -- the server has already dropped the ones they may not
// open (see _tie_allows), so whatever arrives here is simply drawn.
function renderLoungeProjectChannels(projectChannels) {
    const section = document.getElementById('lounge-project-section');
    const list = document.getElementById('lounge-project-channels-list');
    if (!section || !list) return;

    list.innerHTML = '';

    // No project channels AND no project mode means no heading. The section is not
    // merely empty, it is absent -- an empty "Project" header in a book club's
    // sidebar is exactly the kind of dead surface this feature is supposed to
    // avoid. Project mode on is enough on its own, because Roles below is there
    // from the moment the switch is flipped.
    if (!projectChannels.length && !currentLoungeProjectEnabled) {
        section.classList.add('hidden');
        return;
    }
    section.classList.remove('hidden');

    // Roles: a virtual channel, with no LoungeChannel row behind it. Job labels
    // used to be reachable only by opening the members list and long-pressing a
    // row, which is nowhere near where the work happens. It leads the section
    // because "who is doing what" is the first question a group project asks.
    if (currentLoungeProjectEnabled) {
        const rolesLi = document.createElement('li');
        rolesLi.className = 'lounge-channel-item lounge-roles-item';
        // Same gate the real rows get from wireChannelOptionsLongPress: in
        // reorder mode a row is a handle, not a link. Roles is wired by hand
        // (it has no channel behind it to drag), so it needs the check here.
        rolesLi.onclick = () => { if (!channelReorderMode) openRolesBoard(); };

        const rolesSpan = document.createElement('span');
        rolesSpan.style.display = 'flex';
        rolesSpan.style.alignItems = 'center';

        const rolesIcon = document.createElement('i');
        rolesIcon.className = 'fas fa-id-badge';
        rolesIcon.style.marginRight = '8px';
        rolesIcon.style.fontSize = '0.85em';
        rolesSpan.appendChild(rolesIcon);
        rolesSpan.appendChild(document.createTextNode('roles'));

        rolesLi.appendChild(rolesSpan);
        list.appendChild(rolesLi);
    }

    projectChannels.forEach(channel => {
        const li = document.createElement('li');
        li.className = 'lounge-channel-item';
        li.id = `channel-item-${channel.id}`;
        if (channel.has_unread) li.classList.add('has-unread');

        const nameSpan = document.createElement('span');
        nameSpan.style.display = 'flex';
        nameSpan.style.alignItems = 'center';

        const icon = document.createElement('i');
        icon.className = `fas ${TASK_KIND_ICONS[channel.kind] || 'fa-list-check'}`;
        icon.style.marginRight = '8px';
        icon.style.fontSize = '0.85em';
        nameSpan.appendChild(icon);

        // textContent, not innerHTML: a channel name is member-authored. The server
        // already restricts it to [a-z0-9-], but this file has no escaping helper
        // and there is no reason for new code to depend on that check holding.
        nameSpan.appendChild(document.createTextNode(channel.name));

        const lockClass = CHANNEL_LOCK_ICONS[channel.permission_level];
        if (lockClass) {
            const lock = document.createElement('i');
            lock.className = lockClass;
            lock.style.cssText = 'margin-left: 8px; color: #888; font-size: 0.8em;';
            lock.title = CHANNEL_LOCK_TITLES[channel.permission_level] || '';
            nameSpan.appendChild(lock);
        }

        const dot = document.createElement('div');
        dot.className = 'unread-indicator';
        nameSpan.appendChild(dot);

        li.appendChild(nameSpan);

        // Same 3-dot menu chat channels get -- rename and delete apply unchanged,
        // because a project channel is a LoungeChannel row like any other.
        const menuBtn = document.createElement('i');
        menuBtn.className = 'fas fa-ellipsis-v channel-options-btn';
        menuBtn.onclick = (event) => openChannelContextMenu(event, channel);
        li.appendChild(menuBtn);

        // The grip, exactly as the chat rows carry it: in the DOM always, visible
        // only in reorder mode, so entering that mode is a class flip rather than
        // a redraw that would drop a finger mid-gesture.
        const grip = document.createElement('i');
        grip.className = 'fas fa-grip-lines channel-drag-handle';
        li.appendChild(grip);

        li.dataset.channelId = String(channel.id);
        li._channelData = channel;

        // Press-and-hold for the options sheet, and drag-to-reorder. Boards are
        // ordered within the Project section the same way chats are within theirs.
        wireChannelReorderGestures(li, channel);

        list.appendChild(li);
    });
}

/* --- The board itself ---------------------------------------------------- */

// Pulled out of loadLoungeChannel's chat path so the board path can reuse the
// exact same unread bookkeeping instead of a near-copy that drifts.
function markChannelReadLocally(id) {
    if (!unreadChannelSet.has(id)) return;
    unreadChannelSet.delete(id);
    if (unreadLoungeCount > 0) unreadLoungeCount--;
    updateGeneralNotificationBadge();
    // Messages owns the lounge count now, so its nav badge and the Lounges half
    // of the switch both have to come down with it.
    updateNotificationBadge();
    updatePageTitleCount();
    const item = document.getElementById(`channel-item-${id}`);
    if (item) item.classList.remove('has-unread');
}

function highlightSidebarChannel(id) {
    document.querySelectorAll('.lounge-channel-item').forEach(item => item.classList.remove('active'));
    const el = document.getElementById(`channel-item-${id}`);
    if (el) {
        el.classList.add('active');
        el.classList.remove('has-unread');
    }
}

function showTaskPane(channel) {
    hideNoticePane();
    currentTaskChannel = channel;

    // Swap panes. The chat composer is hidden rather than disabled: there is
    // nothing to type into on a board, and a greyed-out message box would read as
    // something broken instead of something absent.
    document.getElementById('lounge-body').style.display = 'none';
    document.getElementById('lounge-input').style.display = 'none';
    const preview = document.getElementById('lounge-image-preview-container');
    if (preview) preview.classList.add('hidden');

    const pane = document.getElementById('lounge-task-body');
    pane.classList.remove('hidden');

    const isDeadline = channel.kind === 'deadline';
    // The channel's own name, for either kind. It used to be hardcoded to
    // "Deadlines" on a deadline board, which both disagreed with the name in the
    // sidebar beside it and stuttered against the badge ("Deadlines DEADLINES").
    document.getElementById('task-board-title').textContent = channel.name;
    document.getElementById('task-add-btn').classList.toggle('hidden', isDeadline);

    // Says out loud what KIND of board this is, so the two are never confused
    // for one another -- one is worked on, the other is watched. It names the
    // kind, the way the notices and roles badges beside it do; both arms of this
    // said "Deadlines", so every checklist was labelled as a deadline view.
    const badge = document.getElementById('task-board-badge');
    badge.textContent = isDeadline ? 'Deadlines' : 'Checklist';
    badge.className = `task-board-badge ${isDeadline ? 'is-deadline' : 'is-task'}`;
    pane.classList.toggle('is-deadline-pane', isDeadline);

    loadTaskBoard(channel.id);
}

// The Roles board rides the same pane-swap as the task board. Kept as its own
// pair of functions so hideTaskPane's careful "only undo what showTaskPane did"
// rule -- which is what stops an incognito viewer being handed a composer --
// keeps applying unchanged.
function openRolesBoard() {
    hideTaskPane();
    hideNoticePane();

    document.getElementById('lounge-body').style.display = 'none';
    document.getElementById('lounge-input').style.display = 'none';
    const preview = document.getElementById('lounge-image-preview-container');
    if (preview) preview.classList.add('hidden');

    document.getElementById('lounge-roles-body').classList.remove('hidden');

    const mobileChannelName = document.getElementById('channel-header-name-mobile');
    if (mobileChannelName) mobileChannelName.textContent = 'roles';
    const container = loungeHostContainer();
    if (container) container.classList.add('mobile-chat-active');

    document.querySelectorAll('.lounge-channel-item.active').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.lounge-roles-item').forEach(el => el.classList.add('active'));

    renderRolesBoard();
}

function hideRolesBoard() {
    const pane = document.getElementById('lounge-roles-body');
    if (!pane || pane.classList.contains('hidden')) return;
    pane.classList.add('hidden');
    document.getElementById('lounge-body').style.display = 'flex';
    document.getElementById('lounge-input').style.display = 'flex';
    document.querySelectorAll('.lounge-roles-item').forEach(el => el.classList.remove('active'));
}

/* ===========================================================================
   NOTICES

   A notices channel is the task board with the scheduling taken out: plain text
   everybody in the lounge needs to have read, each notice carrying its own
   comment thread. It rides the same pane-swap as the task board, so it inherits
   the lounge header, sidebar, unread dots and mobile back button unchanged.
   =========================================================================== */

let currentNoticeChannel = null;
let currentNoticeList = [];
let currentNoticeCanPost = false;
let currentNoticeIsMod = false;
// The notice being edited in the composer at the top, or null when it is adding
// a new one. Editing reuses that one box rather than turning each card into a
// form -- there is only ever one thing being written at a time.
let editingNoticeId = null;
// Only one thread is expanded at a time, which is what lets a single comment box
// move into it (see #notice-comment-form).
let openNoticeThreadId = null;

function showNoticePane(channel) {
    hideTaskPane();
    hideRolesBoard();
    currentNoticeChannel = channel;

    document.getElementById('lounge-body').style.display = 'none';
    document.getElementById('lounge-input').style.display = 'none';
    const preview = document.getElementById('lounge-image-preview-container');
    if (preview) preview.classList.add('hidden');

    document.getElementById('lounge-notice-body').classList.remove('hidden');
    document.getElementById('notice-board-title').textContent = channel.name;

    // Posting a notice bumps the channel's last_message_at, which is what puts an
    // unread dot on it. Opening the board is reading it, so clear that server
    // side too -- the chat path gets this for free when it fetches messages.
    fetch(`${API_BASE_URL}/api/lounge/channel/${channel.id}/mark_read`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    }).catch(() => {});

    loadNoticeBoard(channel.id);
}

function hideNoticePane() {
    const pane = document.getElementById('lounge-notice-body');
    // Same rule as hideTaskPane: only undo what showNoticePane actually did, so a
    // caller that hid the composer on purpose (incognito staff view) does not get
    // it handed back.
    if (!pane || pane.classList.contains('hidden')) {
        currentNoticeChannel = null;
        return;
    }
    cancelNoticeEdit();
    closeNoticeThread();
    currentNoticeChannel = null;
    pane.classList.add('hidden');
    document.getElementById('lounge-body').style.display = 'flex';
    document.getElementById('lounge-input').style.display = 'flex';
}

// The comment box is a single element that lives inside whichever thread is
// open, so it has to be parked back in the pane before anything empties the list
// -- otherwise clearing the board destroys it, and with it the @mention picker
// listeners bound to its id at startup.
function parkNoticeCommentForm() {
    const form = document.getElementById('notice-comment-form');
    if (!form) return;
    form.classList.add('hidden');
    const pane = document.getElementById('lounge-notice-body');
    if (pane && form.parentElement !== pane) pane.appendChild(form);
}

function loadNoticeBoard(channelId) {
    const listEl = document.getElementById('notice-list');
    const emptyEl = document.getElementById('notice-empty');
    parkNoticeCommentForm();
    listEl.innerHTML = '';
    emptyEl.classList.add('hidden');
    document.getElementById('notice-board-summary').textContent = 'Loading...';

    fetch(`${API_BASE_URL}/api/lounge/channels/${channelId}/notices`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        // They may have moved on while this was in flight; drawing now would
        // paint a stale board over whichever channel they actually opened.
        if (!currentNoticeChannel || currentNoticeChannel.id !== channelId) return;

        if (status !== 200) {
            document.getElementById('notice-board-summary').textContent = '';
            emptyEl.textContent = body.error || 'Could not load this board.';
            emptyEl.classList.remove('hidden');
            return;
        }
        currentNoticeCanPost = !!body.can_post;
        currentNoticeIsMod = !!body.is_mod;
        renderNoticeBoard(body.notices || []);
    })
    .catch(() => {
        if (!currentNoticeChannel || currentNoticeChannel.id !== channelId) return;
        document.getElementById('notice-board-summary').textContent = '';
        emptyEl.textContent = 'Could not load this board.';
        emptyEl.classList.remove('hidden');
    });
}

function renderNoticeBoard(notices) {
    const listEl = document.getElementById('notice-list');
    const emptyEl = document.getElementById('notice-empty');
    parkNoticeCommentForm();
    currentNoticeList = notices;

    document.getElementById('notice-composer').classList.toggle('hidden', !currentNoticeCanPost);
    document.getElementById('notice-board-summary').textContent =
        notices.length === 1 ? '1 notice' : `${notices.length} notices`;

    listEl.innerHTML = '';
    if (!notices.length) {
        emptyEl.innerHTML = '';
        const icon = document.createElement('i');
        icon.className = 'far fa-bell';
        emptyEl.appendChild(icon);
        const p = document.createElement('p');
        p.textContent = currentNoticeCanPost
            ? 'No notices yet. Post the first one -- everyone in the lounge will see it above their chat.'
            : 'No notices yet.';
        emptyEl.appendChild(p);
        emptyEl.classList.remove('hidden');
        return;
    }
    emptyEl.classList.add('hidden');

    notices.forEach(notice => listEl.appendChild(buildNoticeCard(notice)));

    // The board is full of @handles; this is what turns the grey spans the
    // linkifier leaves behind into real profile links.
    verifyMentions();

    // Re-open whichever thread was open before this redraw, so posting a comment
    // does not collapse the thread you are in the middle of reading.
    if (openNoticeThreadId && notices.some(n => n.id === openNoticeThreadId)) {
        const id = openNoticeThreadId;
        openNoticeThreadId = null;
        openNoticeThread(id, { focus: false });
    } else {
        openNoticeThreadId = null;
    }
}

// Put an author's avatar into profileData (which is where updateProfilePictures
// reads from) and paint whatever is already drawn for them inside `root`.
function cacheNoticeAuthor(author, root) {
    if (!author || !author.username) return;
    const existing = profileData[author.username] || {};
    profileData[author.username] = {
        ...existing,
        name: existing.name || author.fullName,
        // Never overwrite a picture we already have with a missing one: the
        // payload for a comment carries less than a full profile does.
        profile_pic: existing.profile_pic || existing.profilePicUrl || author.profile_pic,
        rank: existing.rank || author.rank,
    };
    updateProfilePictures(author.username, root || document);
}

// Notice text is member-authored: escape it first, THEN linkify, so the only
// markup in the result is the mention spans this file put there.
function noticeTextHtml(text) {
    return linkifyUsernames(escapeHtmlText(text)).replace(/\n/g, '<br>');
}

// There is no global for "me" in this file; every other caller reads it off
// profileData the same way.
function myUsername() {
    return (profileData && profileData.me && profileData.me.username) || null;
}

function canManageNotice(notice) {
    return currentNoticeIsMod ||
           (notice.author && notice.author.username === myUsername()) ||
           hasPerm('content.lounge.delete');
}

function buildNoticeCard(notice) {
    const card = document.createElement('article');
    card.className = 'notice-card';
    card.id = `notice-${notice.id}`;

    // A div, not a <header>: the stylesheet's bare `header` rule is page chrome
    // (60px tall, its own padding, a bottom border) and `body.with-sidebar
    // header` adds margin-left: 60px to clear the nav rail. A <header> nested in
    // a card inherits all of it, which is what shoved this author row 60px right
    // and drew a divider under it. Inside an <article> the element is scoped out
    // of the landmark tree anyway, so there is nothing to lose here.
    const head = document.createElement('div');
    head.className = 'notice-card-head';

    const pic = document.createElement('div');
    pic.className = 'profile-pic notice-avatar';
    if (notice.author) pic.dataset.userPicId = notice.author.username;

    const who = document.createElement('div');
    who.className = 'notice-who';
    const name = document.createElement('span');
    name.className = 'notice-author';
    name.textContent = notice.author ? (notice.author.fullName || notice.author.username) : 'Someone';
    if (notice.author) appendRankIcon(name, notice.author.username, notice.author.rank);
    const when = document.createElement('span');
    when.className = 'notice-when';
    when.textContent = formatTimestamp(new Date(notice.created_at)) +
                       (notice.edited_at ? ' · edited' : '');
    who.append(name, when);

    head.append(pic, who);

    if (canManageNotice(notice)) {
        const actions = document.createElement('div');
        actions.className = 'notice-card-actions';

        const edit = document.createElement('button');
        edit.type = 'button';
        edit.className = 'notice-icon-btn';
        edit.title = 'Edit this notice';
        edit.setAttribute('aria-label', 'Edit this notice');
        edit.innerHTML = '<i class="fas fa-pen"></i>';
        edit.onclick = () => startNoticeEdit(notice);

        const del = document.createElement('button');
        del.type = 'button';
        del.className = 'notice-icon-btn is-danger';
        del.title = 'Delete this notice';
        del.setAttribute('aria-label', 'Delete this notice');
        del.innerHTML = '<i class="fas fa-trash"></i>';
        del.onclick = () => deleteNotice(notice.id);

        actions.append(edit, del);
        head.appendChild(actions);
    }

    const body = document.createElement('p');
    body.className = 'notice-text';
    body.innerHTML = noticeTextHtml(notice.text);

    const foot = document.createElement('div');
    foot.className = 'notice-foot';
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'notice-thread-toggle';
    toggle.id = `notice-thread-toggle-${notice.id}`;
    const count = notice.comment_count || (notice.comments || []).length;
    toggle.innerHTML = `<i class="far fa-comment"></i> <span>${
        count === 0 ? 'Comment' : count === 1 ? '1 comment' : `${count} comments`
    }</span>`;
    toggle.onclick = () => toggleNoticeThread(notice.id);
    foot.appendChild(toggle);

    const thread = document.createElement('div');
    thread.className = 'notice-thread hidden';
    thread.id = `notice-thread-${notice.id}`;
    (notice.comments || []).forEach(c => thread.appendChild(buildNoticeComment(notice, c)));

    card.append(head, body, foot, thread);
    // `card` as the root, not the document: this node is not in the page yet, and
    // updateProfilePictures() only paints elements it can find under the root it
    // is given -- which is why these avatars came up blank.
    cacheNoticeAuthor(notice.author, card);
    (notice.comments || []).forEach(c => cacheNoticeAuthor(c.author, card));
    return card;
}

function buildNoticeComment(notice, comment) {
    const row = document.createElement('div');
    row.className = 'notice-comment';
    row.id = `notice-comment-${comment.id}`;

    const pic = document.createElement('div');
    pic.className = 'profile-pic notice-comment-avatar';
    if (comment.author) pic.dataset.userPicId = comment.author.username;

    const bubble = document.createElement('div');
    bubble.className = 'notice-comment-bubble';

    const meta = document.createElement('div');
    meta.className = 'notice-comment-meta';
    const who = document.createElement('span');
    who.className = 'notice-comment-author';
    who.textContent = comment.author ? (comment.author.fullName || comment.author.username) : 'Someone';
    if (comment.author) appendRankIcon(who, comment.author.username, comment.author.rank);
    const when = document.createElement('span');
    when.className = 'notice-comment-when';
    when.textContent = formatTimestamp(new Date(comment.created_at));
    meta.append(who, when);

    bubble.append(meta);

    if (comment.text) {
        const text = document.createElement('p');
        text.className = 'notice-comment-text';
        text.innerHTML = noticeTextHtml(comment.text);
        bubble.appendChild(text);
    }

    // A sticker on its own is a whole comment -- "got it" without the typing.
    if (comment.sticker_url) {
        const sticker = document.createElement('img');
        sticker.className = 'notice-comment-sticker';
        sticker.src = comment.sticker_url;
        sticker.alt = 'Sticker';
        sticker.loading = 'lazy';
        bubble.appendChild(sticker);
    }

    // Your own comment, the notice you wrote, or a mod -- the same three the
    // server accepts, so the button never appears on something that would 403.
    const mine = comment.author && comment.author.username === myUsername();
    if (mine || canManageNotice(notice)) {
        const del = document.createElement('button');
        del.type = 'button';
        del.className = 'notice-icon-btn is-danger notice-comment-delete';
        del.title = 'Delete this comment';
        del.setAttribute('aria-label', 'Delete this comment');
        del.innerHTML = '<i class="fas fa-xmark"></i>';
        del.onclick = () => deleteNoticeComment(comment.id);
        bubble.appendChild(del);
    }

    row.append(pic, bubble);
    return row;
}

/* --- Writing one --------------------------------------------------------- */

function handlePostNotice(button) {
    const input = document.getElementById('notice-input-field');
    const text = input.value.trim();
    if (!text) {
        showToast('Write the notice first.', 'error');
        return;
    }
    if (!currentNoticeChannel) return;

    const editing = editingNoticeId;
    const url = editing
        ? `${API_BASE_URL}/api/lounge/notices/${editing}`
        : `${API_BASE_URL}/api/lounge/channels/${currentNoticeChannel.id}/notices`;

    button.disabled = true;
    const originalText = button.textContent;
    button.textContent = editing ? 'Saving...' : 'Posting...';

    fetch(url, {
        method: editing ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ text })
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status >= 400 || !body.ok) {
            showToast(body.error || 'Could not post that notice.', 'error');
            return;
        }
        cancelNoticeEdit();
        loadNoticeBoard(currentNoticeChannel.id);
        showToast(editing ? 'Notice updated.' : 'Notice posted.', 'success');
    })
    .catch(() => showToast('Could not post that notice.', 'error'))
    .finally(() => {
        button.disabled = false;
        button.textContent = originalText;
    });
}

function startNoticeEdit(notice) {
    editingNoticeId = notice.id;
    const input = document.getElementById('notice-input-field');
    const composer = document.getElementById('notice-composer');
    composer.classList.remove('hidden');
    composer.classList.add('is-editing');
    input.value = notice.text || '';
    document.getElementById('notice-post-btn').textContent = 'Save changes';
    document.getElementById('notice-cancel-btn').classList.remove('hidden');
    document.getElementById('notice-composer-hint').textContent = 'Editing a notice.';
    composer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    input.focus();
}

function cancelNoticeEdit() {
    editingNoticeId = null;
    const input = document.getElementById('notice-input-field');
    if (input) input.value = '';
    const composer = document.getElementById('notice-composer');
    if (composer) composer.classList.remove('is-editing');
    const post = document.getElementById('notice-post-btn');
    if (post) post.textContent = 'Post notice';
    const cancel = document.getElementById('notice-cancel-btn');
    if (cancel) cancel.classList.add('hidden');
    const hint = document.getElementById('notice-composer-hint');
    if (hint) hint.textContent = 'Use @ to tag someone.';
}

function deleteNotice(noticeId) {
    if (!confirm('Delete this notice? Its comments go with it.')) return;

    fetch(`${API_BASE_URL}/api/lounge/notices/${noticeId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status !== 200 || !body.ok) {
            showToast(body.error || 'Could not delete that notice.', 'error');
            return;
        }
        if (editingNoticeId === noticeId) cancelNoticeEdit();
        if (openNoticeThreadId === noticeId) closeNoticeThread();
        if (currentNoticeChannel) loadNoticeBoard(currentNoticeChannel.id);
        showToast('Notice deleted.', 'success');
    })
    .catch(() => showToast('Could not delete that notice.', 'error'));
}

/* --- Threads ------------------------------------------------------------- */

function toggleNoticeThread(noticeId) {
    if (openNoticeThreadId === noticeId) closeNoticeThread();
    else openNoticeThread(noticeId);
}

function openNoticeThread(noticeId, { focus = true } = {}) {
    closeNoticeThread();
    const thread = document.getElementById(`notice-thread-${noticeId}`);
    if (!thread) return;

    openNoticeThreadId = noticeId;
    thread.classList.remove('hidden');
    document.getElementById(`notice-${noticeId}`)?.classList.add('is-open');

    const form = document.getElementById('notice-comment-form');
    form.classList.remove('hidden');
    thread.appendChild(form);
    if (focus && shouldAutoFocus()) {
        document.getElementById('notice-comment-input').focus({ preventScroll: true });
    }
}

function closeNoticeThread() {
    if (openNoticeThreadId === null) return;
    const thread = document.getElementById(`notice-thread-${openNoticeThreadId}`);
    if (thread) thread.classList.add('hidden');
    document.getElementById(`notice-${openNoticeThreadId}`)?.classList.remove('is-open');

    // The form is shared, so it goes back to the pane before the thread holding
    // it is hidden or re-rendered out from under it.
    const input = document.getElementById('notice-comment-input');
    if (input) input.value = '';
    parkNoticeCommentForm();
    openNoticeThreadId = null;
}

function handlePostNoticeComment(event) {
    event.preventDefault();
    const input = document.getElementById('notice-comment-input');
    const text = input.value.trim();
    if (!text) return false;
    postNoticeComment({ text });
    return false;
}

// Text, a sticker, or both. The sticker panel stays open after a send (same rule
// as the chat composer), so this never touches the panel or the keyboard.
function postNoticeComment(payload) {
    const noticeId = openNoticeThreadId;
    if (!noticeId) return;
    const input = document.getElementById('notice-comment-input');

    input.disabled = true;
    fetch(`${API_BASE_URL}/api/lounge/notices/${noticeId}/comments`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(payload)
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status >= 400 || !body.ok) {
            showToast(body.error || 'Could not post that comment.', 'error');
            return;
        }
        if (payload.text) input.value = '';
        // Keep the thread open across the redraw; renderNoticeBoard re-opens
        // whichever id is in openNoticeThreadId.
        if (currentNoticeChannel) loadNoticeBoard(currentNoticeChannel.id);
    })
    .catch(() => showToast('Could not post that comment.', 'error'))
    .finally(() => {
        input.disabled = false;
    });
}

function deleteNoticeComment(commentId) {
    fetch(`${API_BASE_URL}/api/lounge/notice-comments/${commentId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status !== 200 || !body.ok) {
            showToast(body.error || 'Could not delete that comment.', 'error');
            return;
        }
        if (currentNoticeChannel) loadNoticeBoard(currentNoticeChannel.id);
    })
    .catch(() => showToast('Could not delete that comment.', 'error'));
}

/* --- The notices bar above a chat ---------------------------------------- */
// The notices this channel carries, in their own bar under the pin bar. This is
// the "automatic pin" part: posting a notice puts it here without anybody
// pinning anything. Which channels a board reaches is the board's ties -- tied
// to #events and only #events gets the bar; tied to nothing and the whole lounge
// does. The server decides that in notices_for_pin_panel().

let loungeNotices = { lounge_id: null, notices: [] };
let loungeNoticeListOpen = false;

function renderLoungeNoticeBar() {
    const bar = document.getElementById('lounge-notice-bar');
    if (!bar) return;

    const notices = loungeNotices.notices || [];
    if (!notices.length) {
        bar.classList.add('hidden');
        return;
    }
    bar.classList.remove('hidden');

    const newest = notices[0];
    // textContent, not innerHTML: a notice is a member's own writing.
    document.getElementById('lounge-notice-bar-text').textContent = newest.text || 'Notice';
    document.getElementById('lounge-notice-bar-count').textContent =
        notices.length > 1 ? `+${notices.length - 1} more` : '';

    const caret = document.getElementById('lounge-notice-bar-caret');
    caret.classList.toggle('hidden', notices.length <= 1);
    caret.classList.toggle('open', loungeNoticeListOpen);

    const list = document.getElementById('lounge-notice-list');
    list.innerHTML = '';
    list.classList.toggle('hidden', !loungeNoticeListOpen);
    if (!loungeNoticeListOpen) return;

    notices.forEach(notice => {
        const li = document.createElement('li');
        li.className = 'lounge-pin-item';

        const body = document.createElement('div');
        body.className = 'lounge-pin-item-body';

        const who = document.createElement('span');
        who.className = 'lounge-pin-item-author';
        const author = notice.author ? (notice.author.fullName || notice.author.username) : 'Someone';
        who.textContent = notice.channel_name ? `${author} · #${notice.channel_name}` : author;

        const text = document.createElement('span');
        text.className = 'lounge-pin-item-text';
        text.textContent = notice.text || '';

        body.append(who, text);
        li.appendChild(body);
        li.onclick = () => openNoticeBoardFromBar(notice);
        list.appendChild(li);
    });
}

function toggleLoungeNoticeList() {
    const notices = loungeNotices.notices || [];
    // One notice needs no list -- the bar already shows it, so the control is
    // just a way into the board it lives on.
    if (notices.length <= 1) {
        if (notices.length === 1) openNoticeBoardFromBar(notices[0]);
        return;
    }
    loungeNoticeListOpen = !loungeNoticeListOpen;
    loungePinListOpen = false;
    renderLoungeNoticeBar();
    renderLoungePinBar();
}

function openNoticeBoardFromBar(notice) {
    loungeNoticeListOpen = false;
    renderLoungeNoticeBar();

    const channel = (currentLoungeChannelList || []).find(c => c.id === notice.channel_id);
    if (!channel) {
        showToast('That notices channel is no longer here.', 'error');
        return;
    }
    loadLoungeChannel(channel);
    // Open the thread for the notice they actually tapped, once the board has
    // drawn. A miss is harmless: the notice is on screen either way.
    setTimeout(() => {
        if (document.getElementById(`notice-${notice.id}`)) openNoticeThread(notice.id, { focus: false });
    }, 400);
}

function renderRolesBoard(force = false) {
    const list = document.getElementById('roles-list');
    const summary = document.getElementById('roles-board-summary');
    if (!list) return;

    list.innerHTML = '';
    summary.textContent = 'Loading...';

    const canManage = currentUserLoungeRole === 'owner' || currentUserLoungeRole === 'moderator';

    fetchLoungeMembers(force).then(members => {
        const sorted = members.slice().sort((a, b) => {
            // Everyone with a job first: the board is about the project, and the
            // unassigned rows collected at the bottom are the ones needing action.
            if (!!a.title !== !!b.title) return a.title ? -1 : 1;
            return (a.fullName || a.username).localeCompare(b.fullName || b.username);
        });

        const assigned = sorted.filter(m => m.title).length;
        summary.textContent = assigned + ' of ' + sorted.length + ' assigned';

        list.innerHTML = '';
        sorted.forEach(member => {
            const row = document.createElement('div');
            row.className = 'roles-row' + (member.title ? '' : ' is-unassigned');

            const pic = document.createElement('div');
            pic.className = 'profile-pic';
            pic.dataset.userPicId = member.username;
            row.appendChild(pic);

            const info = document.createElement('div');
            info.className = 'roles-row-info';

            const name = document.createElement('span');
            name.className = 'roles-row-name';
            // textContent throughout: names and job labels are member-authored.
            name.textContent = member.fullName || member.username;
            appendRankIcon(name, member.username, member.rank);
            const rank = document.createElement('span');
            rank.className = 'roles-row-rank';
            rank.textContent = member.role;
            name.appendChild(rank);
            info.appendChild(name);

            const job = document.createElement('span');
            job.className = 'roles-row-job';
            job.textContent = member.title || 'No role yet';
            info.appendChild(job);

            row.appendChild(info);

            if (canManage) {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'roles-row-edit';
                btn.setAttribute('aria-label', 'Set role');
                const pen = document.createElement('i');
                pen.className = 'fas fa-pen';
                btn.appendChild(pen);
                btn.onclick = () => showMemberTitleModal(member.username, member.fullName, member.title || '');
                row.appendChild(btn);
            }

            list.appendChild(row);
            updateProfilePictures(member.username);
        });
    })
    .catch(() => { summary.textContent = 'Could not load members.'; });
}

function hideTaskPane() {
    const pane = document.getElementById('lounge-task-body');

    // Only undo what showTaskPane actually did. Restoring the panes
    // unconditionally would re-show the composer for callers that deliberately
    // hid it and never opened a board at all -- enterLoungeIncognito is exactly
    // that: it hides the input, then loads a channel, and a staff account
    // watching a lounge invisibly must not be handed a message box.
    if (!pane || pane.classList.contains('hidden')) {
        currentTaskChannel = null;
        return;
    }

    currentTaskChannel = null;
    pane.classList.add('hidden');
    document.getElementById('lounge-body').style.display = 'flex';
    document.getElementById('lounge-input').style.display = 'flex';
}

function loadTaskBoard(channelId) {
    const listEl = document.getElementById('task-list');
    const emptyEl = document.getElementById('task-empty');
    listEl.innerHTML = '';
    emptyEl.classList.add('hidden');
    document.getElementById('task-board-summary').textContent = 'Loading...';

    fetch(`${API_BASE_URL}/api/lounge/channels/${channelId}/tasks`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        // The user may have moved on while this was in flight; drawing now would
        // paint a stale board over whichever channel they actually opened.
        if (!currentTaskChannel || currentTaskChannel.id !== channelId) return;

        if (status !== 200) {
            document.getElementById('task-board-summary').textContent = '';
            emptyEl.textContent = body.error || 'Could not load this board.';
            emptyEl.classList.remove('hidden');
            return;
        }
        currentTaskCanEdit = !!body.can_edit;
        renderTaskBoard(body.tasks || [], body.kind);
    })
    .catch(() => {
        if (!currentTaskChannel || currentTaskChannel.id !== channelId) return;
        document.getElementById('task-board-summary').textContent = '';
        emptyEl.textContent = 'Could not load this board.';
        emptyEl.classList.remove('hidden');
    });
}

// The tasks currently drawn, so ticking a box can update the count without
// re-fetching and re-rendering the whole list mid-animation.
let currentTaskList = [];
let currentTaskListKind = 'task';

// Which task ids were on the board the last time it was drawn, and which board
// that was. The entrance belongs to a row that is NEW, not to a render: saving an
// edit re-renders the whole list, and animating all of it again floated the entire
// board up the screen every time the editor closed.
let taskRowsSeen = new Set();
let taskRowsSeenBoard = '';

function taskBoardKey(kind) {
    return `${currentTaskChannel ? currentTaskChannel.id : '?'}:${kind}`;
}

function renderTaskBoard(tasks, kind) {
    const listEl = document.getElementById('task-list');
    const emptyEl = document.getElementById('task-empty');
    const progress = document.getElementById('task-progress');
    listEl.innerHTML = '';
    currentTaskList = tasks;
    currentTaskListKind = kind;

    listEl.classList.toggle('is-deadline-board', kind === 'deadline');

    if (!tasks.length) {
        document.getElementById('task-board-summary').textContent = '';
        progress.classList.add('hidden');
        emptyEl.innerHTML = '';
        const icon = document.createElement('i');
        icon.className = kind === 'deadline' ? 'far fa-calendar' : 'far fa-square-check';
        emptyEl.appendChild(icon);
        const p = document.createElement('p');
        p.textContent = kind === 'deadline'
            ? 'Nothing has a due date yet. Put a due date on a task and it turns up here.'
            : (currentTaskCanEdit ? 'No tasks yet. Add the first one.' : 'No tasks yet.');
        emptyEl.appendChild(p);
        emptyEl.classList.remove('hidden');
        taskRowsSeen = new Set();
        taskRowsSeenBoard = taskBoardKey(kind);
        return;
    }
    emptyEl.classList.add('hidden');

    refreshTaskSummary();

    // Opening a different board is a fresh assembly; re-drawing the one already on
    // screen is not. Rebuilding the set from the tasks in hand also drops the ids of
    // anything deleted, so it cannot grow without bound.
    const boardKey = taskBoardKey(kind);
    const seenBefore = boardKey === taskRowsSeenBoard ? taskRowsSeen : new Set();
    taskRowsSeenBoard = boardKey;
    taskRowsSeen = new Set(tasks.map(t => String(t.id)));

    // Counts only the rows that actually animate, so a single task added to a long
    // board starts at delay zero instead of inheriting the stagger of its position.
    let entering = 0;

    tasks.forEach(task => {
        const row = buildTaskRow(task, kind);
        if (!seenBefore.has(String(task.id))) {
            // A short stagger so the list assembles instead of snapping in. Capped at
            // ten steps: past that the delay is longer than the patience for it.
            row.style.setProperty('--row-index', String(Math.min(entering, 10)));
            row.classList.add('task-row-enter');
            entering++;
        }
        listEl.appendChild(row);
    });
}

// A plain count of what is left, plus a bar of the same fact. Deliberately NOT a
// per-person score: this says how the work is going, never who is behind.
function refreshTaskSummary() {
    const summaryEl = document.getElementById('task-board-summary');
    const progress = document.getElementById('task-progress');
    const fill = document.getElementById('task-progress-fill');
    const tasks = currentTaskList || [];

    if (currentTaskListKind === 'deadline') {
        const upcoming = tasks.filter(t => dueUrgency(t) !== 'overdue').length;
        const late = tasks.length - upcoming;
        summaryEl.textContent = late
            ? `${tasks.length} dated \u00b7 ${late} overdue`
            : `${tasks.length} coming up`;
        progress.classList.add('hidden');
        return;
    }

    const done = tasks.filter(t => t.status === 'done').length;
    summaryEl.textContent = `${done} of ${tasks.length} done`;
    if (!tasks.length) { progress.classList.add('hidden'); return; }
    progress.classList.remove('hidden');
    fill.style.width = `${Math.round((done / tasks.length) * 100)}%`;
    progress.classList.toggle('is-complete', done === tasks.length);
}

function buildTaskRow(task, kind) {
    return kind === 'deadline' ? buildDeadlineRow(task) : buildChecklistRow(task);
}

/* A task board row: a thing you tick off. The checkbox is the point. */
function buildChecklistRow(task) {
    const row = document.createElement('div');
    row.className = 'task-row';
    if (task.status === 'done') row.classList.add('is-done');

    const check = document.createElement('input');
    check.type = 'checkbox';
    check.className = 'task-check';
    check.checked = task.status === 'done';
    check.disabled = !currentTaskCanEdit;
    check.setAttribute('aria-label', `Mark "${task.title}" done`);
    check.onchange = () => toggleTaskDone(task, check, row);
    row.appendChild(check);

    const main = document.createElement('div');
    main.className = 'task-row-main';

    const title = document.createElement('div');
    title.className = 'task-row-title';
    title.textContent = task.title;
    main.appendChild(title);

    if (task.notes) {
        const notes = document.createElement('p');
        notes.className = 'task-row-notes';
        notes.textContent = task.notes;
        main.appendChild(notes);
    }

    const meta = document.createElement('div');
    meta.className = 'task-row-meta';
    meta.appendChild(buildWhoChip(task));
    if (task.due_at) meta.appendChild(buildDueChip(task));
    main.appendChild(meta);
    row.appendChild(main);

    if (currentTaskCanEdit) {
        const edit = document.createElement('button');
        edit.type = 'button';
        edit.className = 'task-row-edit';
        edit.setAttribute('aria-label', `Edit ${task.title}`);
        edit.innerHTML = '<i class="fas fa-pen"></i>';
        edit.onclick = () => showTaskEditor(task);
        row.appendChild(edit);
    }
    return row;
}

/* A deadlines row: a thing on a calendar. Deliberately a different shape from a
   checklist row -- a date rail down the left, the date itself set large, and no
   checkbox at all, because this board is a read-only view over the task boards
   and ticking here would be editing a task that lives somewhere else. */
function buildDeadlineRow(task) {
    const row = document.createElement('div');
    row.className = 'deadline-row';

    const urgency = dueUrgency(task);
    if (urgency) row.classList.add(`is-${urgency}`);
    if (task.status === 'done') row.classList.add('is-done');

    const rail = document.createElement('div');
    rail.className = 'deadline-rail';

    const due = new Date(task.due_at);
    const precision = task.due_precision || 'minute';

    const big = document.createElement('span');
    big.className = 'deadline-rail-day';
    // At month precision there is no meaningful day number, so the rail shows the
    // month short-name instead of inventing "1".
    big.textContent = precision === 'month'
        ? due.toLocaleString(undefined, { month: 'short' })
        : String(due.getDate());
    rail.appendChild(big);

    const small = document.createElement('span');
    small.className = 'deadline-rail-sub';
    small.textContent = precision === 'month'
        ? String(due.getFullYear())
        : due.toLocaleString(undefined, { month: 'short' });
    rail.appendChild(small);
    row.appendChild(rail);

    const main = document.createElement('div');
    main.className = 'task-row-main';

    const title = document.createElement('div');
    title.className = 'task-row-title';
    title.textContent = task.title;
    main.appendChild(title);

    const meta = document.createElement('div');
    meta.className = 'task-row-meta';
    meta.appendChild(buildDueChip(task));
    meta.appendChild(buildWhoChip(task));
    if (task.channel_name) {
        const from = document.createElement('span');
        from.className = 'task-chip task-chip-quiet';
        from.textContent = `#${task.channel_name}`;
        meta.appendChild(from);
    }
    main.appendChild(meta);
    row.appendChild(main);
    return row;
}

function buildWhoChip(task) {
    const who = document.createElement('span');
    who.className = 'task-chip';
    if (task.assignee) {
        const pic = document.createElement('span');
        pic.className = 'task-chip-avatar profile-pic';
        pic.setAttribute('data-user-pic-id', task.assignee.username);
        who.appendChild(pic);
        who.appendChild(document.createTextNode(task.assignee.fullName || task.assignee.username));
        // Reuses the app's own avatar cache, so a face appears here the moment it
        // is known without this board fetching anything of its own.
        if (typeof updateProfilePictures === 'function') {
            setTimeout(() => updateProfilePictures(task.assignee.username), 0);
        }
    } else {
        who.classList.add('task-chip-quiet');
        who.textContent = 'Unassigned';
    }
    return who;
}

/* --- Due dates at three precisions -------------------------------------- */

// The instant a due date stops being "upcoming". A task due in February 2026 is
// not late on Feb 1st -- it is late once February is over. Same for a day.
function dueEndsAt(task) {
    const d = new Date(task.due_at);
    const p = task.due_precision || 'minute';
    if (p === 'month') return new Date(d.getFullYear(), d.getMonth() + 1, 1);
    if (p === 'day') return new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1);
    return d;
}

function dueUrgency(task) {
    if (!task.due_at) return null;
    // A finished task is never late, no matter what its date says -- nobody needs
    // a red badge on work they already handed in.
    if (task.status === 'done') return null;
    const msLeft = dueEndsAt(task) - new Date();
    if (msLeft < 0) return 'overdue';
    if (msLeft < 2 * 86400000) return 'soon';
    return null;
}

function formatDue(task) {
    const d = new Date(task.due_at);
    const p = task.due_precision || 'minute';
    if (p === 'month') return d.toLocaleString(undefined, { month: 'long', year: 'numeric' });
    if (p === 'day')   return d.toLocaleString(undefined, { month: 'short', day: 'numeric' });
    return d.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
}

function buildDueChip(task) {
    const chip = document.createElement('span');
    chip.className = 'task-chip';
    const urgency = dueUrgency(task);
    if (urgency) chip.classList.add(`is-${urgency}`);

    const icon = document.createElement('i');
    icon.className = urgency === 'overdue' ? 'fas fa-triangle-exclamation' : 'far fa-clock';
    chip.appendChild(icon);

    // The state is spelled out in words as well as colour, so the chip still says
    // what it means in greyscale or to a colourblind reader.
    const prefix = urgency === 'overdue' ? 'Overdue \u2014 was due ' : 'Due ';
    chip.appendChild(document.createTextNode(prefix + formatDue(task)));
    return chip;
}

function toggleTaskDone(task, checkbox, row) {
    const wanted = checkbox.checked ? 'done' : 'todo';
    checkbox.disabled = true;

    // Strike the line through immediately rather than after the round trip. The
    // server is still authoritative -- the class comes back off below if it says no.
    if (row) {
        row.classList.toggle('is-done', wanted === 'done');
        if (wanted === 'done') {
            row.classList.remove('just-completed');
            void row.offsetWidth; // restart the animation on a re-tick
            row.classList.add('just-completed');
        }
    }

    fetch(`${API_BASE_URL}/api/lounge/tasks/${task.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ status: wanted })
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status !== 200) {
            // Put the box back the way it was -- leaving it ticked would claim a
            // change the server refused.
            checkbox.checked = !checkbox.checked;
            if (row) row.classList.toggle('is-done', checkbox.checked);
            showToast(body.error || 'Could not update that task.', 'error');
            return;
        }
        task.status = wanted;
        // Only the count needs redrawing; re-fetching the whole board here would
        // yank the list out from under the animation that is still running.
        refreshTaskSummary();
    })
    .catch(() => {
        checkbox.checked = !checkbox.checked;
        if (row) row.classList.toggle('is-done', checkbox.checked);
        showToast('Could not update that task.', 'error');
    })
    .finally(() => { checkbox.disabled = false; });
}

/* --- Task editor --------------------------------------------------------- */

function showTaskEditor(task = null) {
    if (!currentTaskChannel || !currentTaskCanEdit) return;

    editingTaskId = task ? task.id : null;
    document.getElementById('task-editor-heading').textContent = task ? 'Edit Task' : 'New Task';
    document.getElementById('task-title-input').value = task ? task.title : '';
    document.getElementById('task-notes-input').value = task ? (task.notes || '') : '';
    fillDuePicker(task && task.due_at, task && task.due_precision);
    document.getElementById('task-delete-btn').classList.toggle('hidden', !task);

    populateAssigneeOptions(task && task.assignee ? task.assignee.username : '');
    // Every panel starts closed, whether this is a new task or an edit: the chips
    // already say what is set, so the form opens one field tall either way.
    closeAllTaskPanels();
    refreshTaskChips();
    document.getElementById('task-editor-modal').classList.remove('hidden');
    // Taken after the fields are populated, so "dirty" means the user changed
    // something rather than merely that the form has content.
    taskEditorBaseline = snapshotTaskEditor();
    if (shouldAutoFocus()) {
        setTimeout(() => document.getElementById('task-title-input').focus({ preventScroll: true }), 60);
    }
}

function closeTaskEditor() {
    editingTaskId = null;
    taskEditorBaseline = null;
    document.getElementById('task-editor-modal').classList.add('hidden');
}

// What the form looked like when it opened, so a background click can tell an
// abandoned empty form from half-typed work.
let taskEditorBaseline = null;

function snapshotTaskEditor() {
    const picked = readDuePicker();
    return [
        document.getElementById('task-title-input').value.trim(),
        document.getElementById('task-notes-input').value.trim(),
        document.getElementById('task-assignee-input').value,
        picked.due_at || '',
        picked.due_precision || '',
    ].join('\u0000');
}

function taskEditorIsDirty() {
    return taskEditorBaseline !== null && snapshotTaskEditor() !== taskEditorBaseline;
}

// Clicking the dark area is a dismissal, not a question. Nothing changed -> just
// close. Something changed -> keep it, by running the same save the Save button
// runs. No browser dialog: a native confirm() looks nothing like APEX, and asking
// "are you sure" about work someone just did is the wrong default anyway.
function requestCloseTaskEditor() {
    if (!taskEditorIsDirty()) { closeTaskEditor(); return; }

    const title = document.getElementById('task-title-input').value.trim();
    if (!title) {
        // A brand-new task with no name has nothing worth keeping, so this is a
        // discard rather than a failed save -- no error for something the user
        // never really started.
        if (editingTaskId === null) { closeTaskEditor(); return; }
        // An existing task whose name was cleared genuinely cannot be saved. Say so
        // and leave the form up rather than dropping the edit on the floor.
        showToast('Give the task a name to save it.', 'error');
        return;
    }

    handleSaveTask(document.querySelector('#task-editor-modal .login-btn'));
}

// Same rule for the job label: one field, so a background click keeps whatever
// was typed instead of throwing it away.
function requestCloseMemberTitleModal() {
    const input = document.getElementById('member-title-input');
    if (!input || input.value.trim() === (memberTitleBaseline || '')) {
        closeMemberTitleModal();
        return;
    }
    handleSaveMemberTitle(document.querySelector('#member-title-modal .login-btn'));
}

/* --- The due picker -----------------------------------------------------
   Four parts that narrow each other: Month + Year is already a complete answer,
   Day sharpens it, Time sharpens it again. Whatever is filled in decides the
   precision that gets stored, so "February 2026" saves as February 2026 instead
   of being rejected for having no day and no clock time.

   Everything here is local wall-clock; the ISO string handed to the API is the
   start of the chosen period converted to UTC. */

/* --- Chips and panels ---------------------------------------------------
   The editor shows one field -- the name -- and three chips. A chip both reports
   what is set ("Due Mar 4", "@rick") and opens the panel that sets it. Only one
   panel is open at a time, so the form never grows taller than about two fields,
   and nothing has to be touched to save a task. */

function closeAllTaskPanels() {
    ['due', 'assignee', 'notes'].forEach(name => {
        document.getElementById(`task-panel-${name}`).classList.add('hidden');
        document.getElementById(`task-chip-${name}`).setAttribute('aria-expanded', 'false');
    });
}

function toggleTaskPanel(name) {
    const panel = document.getElementById(`task-panel-${name}`);
    const wasOpen = !panel.classList.contains('hidden');
    closeAllTaskPanels();
    if (wasOpen) return;

    panel.classList.remove('hidden');
    document.getElementById(`task-chip-${name}`).setAttribute('aria-expanded', 'true');

    // A date already on the task is unlikely to be one of the three presets, so
    // the exact picker comes up with it rather than hiding the current answer.
    if (name === 'due') showDueDetail(!!readDuePicker().due_at);
    if (name === 'notes' && shouldAutoFocus()) {
        setTimeout(() => document.getElementById('task-notes-input').focus({ preventScroll: true }), 40);
    }
}

function toggleDueDetail() {
    showDueDetail(document.getElementById('task-due-detail').classList.contains('hidden'));
}

function showDueDetail(show) {
    document.getElementById('task-due-detail').classList.toggle('hidden', !show);
    document.getElementById('task-preset-pick').classList.toggle('is-active', show);
}

// Presets land on a whole day, which is the precision people actually mean when
// they say "tomorrow". Anything finer is a job for the picker underneath.
function applyDuePreset(kind) {
    const d = new Date();
    if (kind === 'tomorrow') d.setDate(d.getDate() + 1);
    if (kind === 'week') d.setDate(d.getDate() + 7);

    buildDuePicker();
    document.getElementById('task-due-month').value = String(d.getMonth());
    document.getElementById('task-due-year').value = String(d.getFullYear());
    rebuildDayOptions();
    document.getElementById('task-due-day').value = String(d.getDate());
    document.getElementById('task-due-time').value = '';
    onDuePickerChange();
}

function clearTaskDue(event) {
    event.stopPropagation();
    fillDuePicker(null, null);
    showDueDetail(false);
}

function clearTaskAssignee(event) {
    event.stopPropagation();
    document.getElementById('task-assignee-input').value = '';
    refreshTaskChips();
}

function clearTaskNotes(event) {
    event.stopPropagation();
    document.getElementById('task-notes-input').value = '';
    refreshTaskChips();
}

// Keeps each chip's label and filled state in step with the panel behind it.
function refreshTaskChips() {
    const setChip = (name, label, isSet) => {
        const chip = document.getElementById(`task-chip-${name}`);
        document.getElementById(`task-chip-${name}-label`).textContent = label;
        chip.classList.toggle('is-set', isSet);
    };

    const picked = readDuePicker();
    setChip('due',
        picked.due_at ? formatDue({ due_at: picked.due_at, due_precision: picked.due_precision }) : 'Due date',
        !!picked.due_at);

    const assignee = document.getElementById('task-assignee-input');
    const chosen = assignee.value;
    setChip('assignee', chosen ? `@${chosen}` : 'Assign', !!chosen);

    const notes = document.getElementById('task-notes-input').value.trim();
    setChip('notes', notes ? 'Notes added' : 'Notes', !!notes);
}

const MONTH_NAMES = ['January','February','March','April','May','June',
                     'July','August','September','October','November','December'];

function buildDuePicker() {
    const monthSel = document.getElementById('task-due-month');
    const yearSel = document.getElementById('task-due-year');
    if (monthSel.options.length) return; // built once

    monthSel.appendChild(new Option('Month', ''));
    MONTH_NAMES.forEach((m, idx) => monthSel.appendChild(new Option(m, String(idx))));

    yearSel.appendChild(new Option('Year', ''));
    const thisYear = new Date().getFullYear();
    // One year back covers a task carried over from last term; three forward is
    // further than any school assignment realistically runs.
    for (let y = thisYear - 1; y <= thisYear + 3; y++) yearSel.appendChild(new Option(String(y), String(y)));
}

function rebuildDayOptions() {
    const daySel = document.getElementById('task-due-day');
    const month = document.getElementById('task-due-month').value;
    const year = document.getElementById('task-due-year').value;
    const keep = daySel.value;
    daySel.innerHTML = '';
    daySel.appendChild(new Option('Day \u2014 optional', ''));

    if (month === '' || year === '') { daySel.disabled = true; return; }
    daySel.disabled = false;

    // Day 0 of the next month is the last day of this one, so February gets 28 or
    // 29 without a leap-year rule written out by hand.
    const days = new Date(Number(year), Number(month) + 1, 0).getDate();
    for (let d = 1; d <= days; d++) daySel.appendChild(new Option(String(d), String(d)));
    if (keep && Number(keep) <= days) daySel.value = keep;
}

function onDuePickerChange() {
    rebuildDayOptions();
    const dayVal = document.getElementById('task-due-day').value;
    const timeInput = document.getElementById('task-due-time');
    // A time with no day would be a clock reading attached to a whole month, which
    // means nothing -- so time only unlocks once a day is chosen.
    timeInput.disabled = !dayVal;
    if (!dayVal) timeInput.value = '';
    updateDueSummary();
}

// The chip above the panel already reads back the chosen date, so this line is
// left for the one state the chip cannot show: half a date, which saves as no
// date at all unless it is finished.
function updateDueSummary() {
    const el = document.getElementById('task-due-summary');
    const month = document.getElementById('task-due-month').value;
    const year = document.getElementById('task-due-year').value;
    const halfFilled = (month === '') !== (year === '');

    el.textContent = halfFilled
        ? 'Pick both a month and a year, or leave both empty for no due date.'
        : '';
    el.classList.toggle('is-warning', halfFilled);
    refreshTaskChips();
}

// Returns {due_at, due_precision}; both null when there is no usable date.
function readDuePicker() {
    const month = document.getElementById('task-due-month').value;
    const year = document.getElementById('task-due-year').value;
    const day = document.getElementById('task-due-day').value;
    const time = document.getElementById('task-due-time').value;

    if (month === '' || year === '') return { due_at: null, due_precision: null };

    let precision = 'month';
    let d = new Date(Number(year), Number(month), 1, 0, 0, 0, 0);

    if (day !== '') {
        precision = 'day';
        d = new Date(Number(year), Number(month), Number(day), 0, 0, 0, 0);
        if (time) {
            const [hh, mm] = time.split(':').map(Number);
            if (!isNaN(hh) && !isNaN(mm)) {
                precision = 'minute';
                d = new Date(Number(year), Number(month), Number(day), hh, mm, 0, 0);
            }
        }
    }
    return isNaN(d) ? { due_at: null, due_precision: null }
                    : { due_at: d.toISOString(), due_precision: precision };
}

function fillDuePicker(iso, precision) {
    buildDuePicker();
    const monthSel = document.getElementById('task-due-month');
    const yearSel = document.getElementById('task-due-year');
    const timeInput = document.getElementById('task-due-time');

    if (!iso) {
        monthSel.value = ''; yearSel.value = '';
        rebuildDayOptions();
        timeInput.value = ''; timeInput.disabled = true;
        updateDueSummary();
        return;
    }

    const d = new Date(iso);
    const p = precision || 'minute';
    monthSel.value = String(d.getMonth());
    yearSel.value = String(d.getFullYear());
    rebuildDayOptions();

    const daySel = document.getElementById('task-due-day');
    daySel.value = (p === 'month') ? '' : String(d.getDate());

    timeInput.disabled = !daySel.value;
    const pad = n => String(n).padStart(2, '0');
    timeInput.value = (p === 'minute') ? `${pad(d.getHours())}:${pad(d.getMinutes())}` : '';
    updateDueSummary();
}

function populateAssigneeOptions(selectedUsername) {
    const select = document.getElementById('task-assignee-input');
    select.innerHTML = '';

    const unassigned = document.createElement('option');
    unassigned.value = '';
    unassigned.textContent = 'Unassigned';
    select.appendChild(unassigned);

    // Only lounge members can be assigned -- the server enforces this too, so the
    // dropdown is a convenience rather than the check.
    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/members`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json())
    .then(members => {
        if (!Array.isArray(members)) return;
        members.forEach(m => {
            const opt = document.createElement('option');
            opt.value = m.username;
            opt.textContent = m.fullName ? `${m.fullName} (@${m.username})` : `@${m.username}`;
            if (m.username === selectedUsername) opt.selected = true;
            select.appendChild(opt);
        });
        // The chip was drawn before this list arrived, so the name it shows has to
        // be filled in once the option it names actually exists.
        refreshTaskChips();
    })
    .catch(() => { /* the Unassigned option alone still lets the task be saved */ });
}

function handleSaveTask(button) {
    if (!currentTaskChannel) return;

    const title = document.getElementById('task-title-input').value.trim();
    if (!title) {
        showToast('Give the task a name.', 'error');
        return;
    }

    const picked = readDuePicker();
    const payload = {
        title,
        notes: document.getElementById('task-notes-input').value.trim(),
        due_at: picked.due_at,
        due_precision: picked.due_precision,
        assignee: document.getElementById('task-assignee-input').value || null,
    };

    const isEdit = editingTaskId !== null;
    const url = isEdit
        ? `${API_BASE_URL}/api/lounge/tasks/${editingTaskId}`
        : `${API_BASE_URL}/api/lounge/channels/${currentTaskChannel.id}/tasks`;

    button.disabled = true;
    button.textContent = 'Saving...';

    fetch(url, {
        method: isEdit ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(payload)
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status !== 200 && status !== 201) {
            showToast(body.error || 'Could not save that task.', 'error');
            return;
        }
        closeTaskEditor();
        loadTaskBoard(currentTaskChannel.id);
    })
    .catch(() => showToast('Could not save that task.', 'error'))
    .finally(() => {
        button.disabled = false;
        button.textContent = 'Save';
    });
}

function handleDeleteTask() {
    if (editingTaskId === null) return;
    const taskId = editingTaskId;
    const taskName = document.getElementById('task-title-input').value.trim();

    // Deleting still asks -- it is the one action here that destroys something --
    // but through APEX's own confirmation modal rather than the browser's.
    showConfirmationModal({
        title: 'Delete task?',
        text: taskName
            ? `<strong>${taskName.replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}</strong> will be removed for everyone in this lounge.`
            : 'This task will be removed for everyone in this lounge.',
        onConfirm: () => performDeleteTask(taskId),
    });
}

function performDeleteTask(taskId) {
    fetch(`${API_BASE_URL}/api/lounge/tasks/${taskId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status !== 200) {
            showToast(body.error || 'Could not delete that task.', 'error');
            return;
        }
        closeTaskEditor();
        if (currentTaskChannel) loadTaskBoard(currentTaskChannel.id);
    })
    .catch(() => showToast('Could not delete that task.', 'error'));
}

/* --- Job labels ---------------------------------------------------------- */

let editingMemberUsername = null;

// What the label was when the modal opened, so a background click can tell an
// edit from an untouched form.
let memberTitleBaseline = '';

function showMemberTitleModal(username, fullName, currentTitle) {
    editingMemberUsername = username;
    memberTitleBaseline = (currentTitle || '').trim();
    document.getElementById('member-title-who').textContent = fullName ? `${fullName} (@${username})` : `@${username}`;
    document.getElementById('member-title-input').value = currentTitle || '';
    document.getElementById('member-title-modal').classList.remove('hidden');
}

function closeMemberTitleModal() {
    editingMemberUsername = null;
    document.getElementById('member-title-modal').classList.add('hidden');
}

function handleSaveMemberTitle(button) {
    if (!editingMemberUsername) return;
    const title = document.getElementById('member-title-input').value.trim();
    const username = editingMemberUsername;

    button.disabled = true;
    fetch(`${API_BASE_URL}/api/lounge/${currentLoungeId}/members/${encodeURIComponent(username)}/title`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ title })
    })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        if (status !== 200) {
            showToast(body.error || 'Could not save that label.', 'error');
            return;
        }
        closeMemberTitleModal();
        // Force past the per-visit cache: the label just changed, and the chips in
        // chat and the Roles board are both drawn from it.
        fetchLoungeMembers(true).then(() => {
            renderLoungeSettingsMembers();
            if (!document.getElementById('lounge-roles-body').classList.contains('hidden')) {
                renderRolesBoard();
            }
        });
    })
    .catch(() => showToast('Could not save that label.', 'error'))
    .finally(() => { button.disabled = false; });
}

function setChannelReorderMode(on) {
    channelReorderMode = !!on;

    // Leaving the mode ends any gesture still in flight, so Done always gets you
    // out -- even if a drag were somehow still holding on.
    if (!channelReorderMode) endChannelDrag(false);

    // Both lists: the mode is one state, and the CSS that reveals the grips and
    // suppresses the row links hangs off this class.
    document.querySelectorAll('.lounge-channels-list').forEach(list => {
        list.classList.toggle('is-reordering', channelReorderMode);
    });

    const categoryHeader = document.querySelector('.lounge-channel-category');
    if (!categoryHeader) return;

    if (channelReorderMode) {
        categoryHeader.innerHTML = '';
        // "Channels", not "Chats": the Project list is draggable too now, and
        // the one Done button ends the mode for both.
        categoryHeader.appendChild(document.createTextNode('Reorder Channels'));

        const done = document.createElement('button');
        done.type = 'button';
        done.className = 'channel-reorder-done';
        done.textContent = 'Done';
        done.onclick = () => setChannelReorderMode(false);
        categoryHeader.appendChild(done);
    } else if (canReorderChannels()) {
        // One container for both buttons: on a phone the header is a flex row, and
        // two separately right-pushed icons split the free space between them,
        // which parked the "+" in the middle of the header.
        categoryHeader.innerHTML = 'Chats <span class="channel-category-actions">'
            + '<i class="fas fa-folder-plus" title="Create a channel group" onclick="openChannelGroupNameModal(null)"></i>'
            + '<i class="fas fa-plus" title="Create a channel" onclick="showCreateChannelModal()"></i>'
            + '</span>';
    } else {
        categoryHeader.textContent = 'Chats';
    }
}

function startChannelReorder() {
    if (!canReorderChannels()) return;
    setChannelReorderMode(true);
    showToast('Drag the channels into the order you want, then tap Done.', 'success');

    // The sidebar is a separate pane on a phone; arming reorder mode from a sheet
    // opened over the chat view would otherwise leave the mod looking at messages.
    const container = loungeHostContainer();
    if (container) container.classList.remove('mobile-chat-active');
}

/* --- Mobile: long-press sheet, the touch twin of openChannelContextMenu --- */

function createChannelOptionsModal() {
    if (document.getElementById('channel-options-modal')) return;
    document.body.insertAdjacentHTML('beforeend', `
        <div id="channel-options-modal" onclick="closeChannelOptions(event)">
            <div class="mobile-message-sheet" onclick="event.stopPropagation()">
                <div class="mobile-sheet-handle"></div>
                <div class="chat-options-title" id="channel-options-title"></div>
                <div class="mobile-action-list" id="channel-options-actions"></div>
            </div>
        </div>
    `);
}

// One source of truth for what a channel's options are, so the long-press sheet and
// the desktop 3-dot menu cannot drift apart.
function getChannelActions(channel) {
    const actions = [];
    const canManage = canReorderChannels() || hasPerm('content.channel.delete');

    if (!canManage) {
        actions.push({ icon: 'fa-circle-info', label: 'Show Description', run: () => showLoungeDetails() });
        return actions;
    }

    const isBoard = (channel.kind || 'chat') !== 'chat';

    // Boards excluded: main is where the lounge opens and where system messages
    // land, and a board has no message list to show them in. The server refuses
    // it too -- see set_main_channel.
    if (!channel.is_main && !isBoard) {
        actions.push({ icon: 'fa-star', label: 'Make Main Channel', run: () => handleSetMainChannel(channel.id) });
    }

    actions.push({ icon: 'fa-pen', label: 'Edit Name', run: () => editLoungeChannel(channel.id, channel.name) });

    // These two were on the desktop 3-dot only, which on a phone meant they were
    // on nothing at all -- the sheet IS the menu there. Same gates as
    // openChannelContextMenu, so the two lists cannot drift apart.
    if (loungeCan('channels')) {
        actions.push({ icon: 'fa-lock', label: 'Visibility', run: () => openChannelPrivacyModal(channel.id, channel.name) });
    }
    if (isBoard) {
        actions.push({ icon: 'fa-link', label: 'Tie Channel', run: () => openChannelTiesModal(channel.id, channel.name) });
    }

    // Reordering is the lounge's own mods only -- see canReorderChannels().
    if (canReorderChannels()) {
        actions.push({ icon: 'fa-arrows-up-down', label: 'Reorder Channels', run: () => startChannelReorder() });
        // Chat channels only; boards have the Project section instead.
        if (!isBoard) {
            actions.push({ icon: 'fa-folder', label: 'Move to Group', run: () => openMoveChannelToGroup(channel.id) });
        }
    }

    actions.push({ icon: 'fa-trash', label: 'Delete Channel', run: () => deleteLoungeChannel(channel.id), danger: true });

    return actions;
}

function openChannelOptionsSheet(channel) {
    if (!channel) return;
    if (navigator.vibrate) navigator.vibrate(50);
    showChannelOptionsSheet(`# ${channel.name}`, getChannelActions(channel));
}

// The sheet itself, for any list of { icon, label, run, danger } -- the channel
// menu above, and the channel-group menus.
function showChannelOptionsSheet(title, actions) {
    createChannelOptionsModal();

    const modal = document.getElementById('channel-options-modal');
    const list = document.getElementById('channel-options-actions');
    document.getElementById('channel-options-title').textContent = title;

    list.innerHTML = '';
    actions.forEach(action => {
        const btn = document.createElement('button');
        btn.className = 'mobile-action-btn' + (action.danger ? ' danger' : '');
        btn.innerHTML = `<i class="fas ${action.icon}"></i>`;
        btn.appendChild(document.createTextNode(' ' + action.label));
        btn.onclick = () => {
            // Close first: "Reorder Channels" reveals the list behind this sheet, and
            // deleteLoungeChannel opens a confirmation the sheet would otherwise cover.
            closeChannelOptions();
            action.run();
        };
        list.appendChild(btn);
    });

    modal.dataset.openedAt = String(Date.now());
    modal.classList.add('visible');
    document.body.style.overflow = 'hidden';
}

function closeChannelOptions(event) {
    const modal = document.getElementById('channel-options-modal');
    if (!modal) return;
    if (event) {
        if (event.target.id !== 'channel-options-modal') return;
        // The long press emits its click on touchend, by which point the overlay is
        // under the finger -- it would close the sheet in the frame it opened.
        if (Date.now() - Number(modal.dataset.openedAt || 0) < 400) return;
    }
    modal.classList.remove('visible');
    document.body.style.overflow = '';
}

// Every write path that Gemini can reject funnels its error through here, so the
// appeal modal comes up for all of them and not just the ones whose message
// happens to say "moderation". Image rejections in particular used to read
// "Cover Image: Image violates community safety guidelines." and fell through to
// a plain toast, leaving no way to appeal a blocked cover photo.
function isModerationError(message) {
    if (!message) return false;
    return /moderation|community safety guidelines/i.test(message);
}

// Leaves the edit-profile form once a save (or an appeal for one) has resolved:
// staying on a form whose contents were either committed or handed to a human is
// what made this confusing. Goes to the profile rather than history.back() so the
// destination is the same whether the page was opened from the profile or by URL.
function exitEditProfile() {
    const page = document.getElementById('edit-profile-page');
    if (!page || !page.classList.contains('active')) return;
    navigateTo('/users/me');
}

// An appeal hands the item to a human, so the page or sheet it was written on
// has nothing left to do -- leave it the same way a successful submit would.
// Each case is guarded on its own surface still being on screen: the appeal can
// be filed from a modal raised over a page the user already navigated away from
// (the circuit post verdict arrives from Celery, seconds later), and yanking
// them off wherever they went by then would be worse than staying put.
// Resume items are absent on purpose -- handleAddResumeItem / handleEditResumeItem
// already close their form modal before the appeal modal opens.
function exitAfterAppeal(type) {
    const leavePage = (id, go) => {
        const page = document.getElementById(id);
        if (page && page.classList.contains('active')) go();
    };
    const backToCircuit = () => {
        const code = currentCircuitDetails && currentCircuitDetails.code;
        if (code) navigateTo(`/circuits/${code}`);
        else navigateTo('/explore');
    };

    switch (type) {
        case 'edit_profile':
            exitEditProfile();
            break;
        case 'lounge':
            // Matches handleCreateLounge's success path rather than /lounges:
            // the lounge list is not where you land after making one.
            leavePage('create-lounge-page', () => navigateTo('/'));
            break;
        case 'edit_lounge':
            // The lounge editor is a modal over the lounge itself, so there is
            // no page to leave -- just take the sheet down.
            closeLoungeMembersModal();
            break;
        case 'create_circuit':
            leavePage('create-circuit-page', () => navigateTo('/explore'));
            break;
        case 'edit_circuit':
            leavePage('edit-circuit-page', backToCircuit);
            break;
        case 'post':
            leavePage('create-post-page', () => {
                // The compose page is reused for edits; clear what it was
                // editing so the next open doesn't inherit a stale target.
                postCreationContext = { type: null, id: null };
                backToCircuit();
            });
            break;
    }
}

function requestModerationAppeal(type, payload) {
    const btn = document.getElementById('moderation-appeal-btn');
    if(btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending...';
    }

    fetch(`${API_BASE_URL}/api/moderation/appeal`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ type: type, payload: payload })
    })
    .then(response => response.json())
    .then(data => {
        if (data.ok) {
            showToast('Review request sent to @apex.', 'success');
            closeConfirmationModal(); // Close the modal if it's open
            // Nothing more to do on the form -- the item is now a human's call.
            exitAfterAppeal(type);
        } else {
            showToast(data.error || 'Failed to send request.', 'error');
        }
    })
    .catch(err => {
        console.error(err);
        showToast('Network error.', 'error');
    });
}

function showModerationErrorModal(errorMessage, type, payload) {
    // Reuse your confirmation modal for this purpose
    const modal = document.getElementById('confirmation-modal');
    document.getElementById('confirm-modal-title').textContent = "Content Flagged";
    document.getElementById('confirm-modal-text').innerHTML = `
        <p style="color: #e74c3c; font-weight: bold;">${errorMessage}</p>
        <p>If you believe this is a mistake, you can request a manual review by @apex.</p>
    `;
    
    const footer = document.querySelector('.confirm-modal-footer');
    footer.innerHTML = `
        <button class="confirm-btn-cancel" onclick="closeConfirmationModal()">Cancel</button>
        <button id="moderation-appeal-btn" class="confirm-btn-confirm" style="background-color: #f39c12;">
            Request Review
        </button>
    `;
    
    // Attach the event listener with the specific payload
    document.getElementById('moderation-appeal-btn').onclick = () => requestModerationAppeal(type, payload);
    
    // Last child of <body>, for the same reason showConfirmationModal does it: this
    // is that same element, and the verdict usually lands while the modal that
    // submitted the content is still open -- lounge settings, after Save. Every
    // .following-modal sits at the max z-index, so DOM order decides, and
    // #confirmation-modal is declared above all of them in index.html.
    document.body.appendChild(modal);
    modal.classList.remove('hidden');
}

function saveProfile() {
    const successMessage = document.getElementById('save-success');
    successMessage.style.opacity = '0'; // Hide it initially
    clearAllValidationErrors('edit-profile-page'); // Clear old errors

    // --- 1. Get ALL form values ---
    const fullName = document.getElementById('editFullName').value;
    const username = profileData.me.username;
    const bio = document.getElementById('editBio').value;
    const school = document.getElementById('editSchool').value;
    const subject = document.getElementById('editSubject').value.trim();
    
    // Note: profileData.me.profilePicUrl is updated by the file input onchange handler previously
    const profilePicData = profileData.me.profilePicUrl; 
    
    const showBirthday = document.getElementById('editShowBirthday').checked;
    const showSocialStats = document.getElementById('editShowSocialStats').checked;

    const currentPassword = document.getElementById('editCurrentPassword').value;
    const newPassword = document.getElementById('editPassword').value;
    const confirmPassword = document.getElementById('editConfirmPassword').value;

    // --- 2. Build the payload EARLY ---
    const payload = {
        fullName: fullName,
        username: username,
        bio: bio,
        school: school,
        subject: subject,
        profilePic: profilePicData
    };

    // Only sent when the remove button was actually pressed. The server ignores a
    // null profilePic on purpose, so this flag is the only way to clear an avatar.
    if (profilePicRemoved) payload.removeProfilePic = true;

    // Omit the privacy flags unless the form is known to be showing the real ones.
    // The server treats a missing key as "leave it alone", so a save that happens
    // before hydration lands keeps the database value instead of overwriting it
    // with whatever the switches happened to be drawn as.
    if (privacyTogglesHydrated) {
        payload.showBirthday = showBirthday;
        payload.showSocialStats = showSocialStats;
    }

    if (accountSettingsHydrated) {
        const quietOn = document.getElementById('editQuietHours').checked;
        const quietStart = document.getElementById('editQuietStart').value;
        const quietEnd = document.getElementById('editQuietEnd').value;
        if (quietOn && (!quietStart || !quietEnd)) {
            showValidationError('editQuietStart', 'Pick a start and end time for quiet hours.');
            return;
        }
        payload.dmPrivacy = document.getElementById('editDmPrivacy').value;
        payload.tagPrivacy = document.getElementById('editTagPrivacy').value;
        payload.showOnlineStatus = document.getElementById('editShowOnline').checked;
        payload.showFollowLists = document.getElementById('editShowFollowLists').checked;
        payload.quietHoursEnabled = quietOn;
        if (quietStart) payload.quietHoursStart = quietStart;
        if (quietEnd) payload.quietHoursEnd = quietEnd;
    }

    // --- 3. Validate and add password (if one was entered) ---
    if (newPassword) {
        if (newPassword.length < MIN_PASSWORD_LENGTH) {
            showValidationError('editPassword', `Password must be at least ${MIN_PASSWORD_LENGTH} characters.`);
            return; // Stop execution
        }
        if (newPassword !== confirmPassword) {
            showValidationError('editConfirmPassword', 'Passwords do not match.');
            return; // Stop execution
        }
        // The server refuses a password change that cannot prove the current one,
        // so an empty box here is a rejected save rather than a silent no-op.
        if (!currentPassword) {
            showValidationError('editCurrentPassword', 'Enter your current password to change it.');
            return;
        }
        payload.password = newPassword;
        payload.current_password = currentPassword;
    } else if (confirmPassword) {
        showValidationError('editPassword', 'Please enter your new password.');
        return;
    }

    // --- NEW: Trigger the loading modal before the fetch ---
    showActionProgress("Saving Profile...", "Uploading your details.");

    // --- 4. Send the complete payload ---
    fetch(`${API_BASE_URL}/api/profile`, {
        method: 'PUT',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${apiToken}`
        },
        body: JSON.stringify(payload)
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 200 && body.ok) {
            // --- NEW: Complete the loading modal ---
            // Exiting is deferred to the overlay actually being gone, so the save
            // reads as one motion: bar fills, modal fades, form closes.
            completeActionProgress(exitEditProfile);

            // --- Success Logic ---
            successMessage.style.opacity = '1';
            setTimeout(() => {
                successMessage.style.opacity = '0';
            }, 2000);

            if (newPassword) {
                document.getElementById('editCurrentPassword').value = '';
                document.getElementById('editPassword').value = '';
                document.getElementById('editConfirmPassword').value = '';
            }

            // Update all profile data from the server's response
            profileData.me.name = body.user.fullName;
            profileData.me.username = body.user.username;
            profileData.me.bio = body.user.bio;
            profileData.me.profilePicUrl = body.user.profile_pic;
            profileData.me.school = body.user.school;
            profileData.me.subject = body.user.subject;
            profileData.me.show_birthday = body.user.show_birthday;
            profileData.me.show_social_stats = body.user.show_social_stats;
            ACCOUNT_SETTING_KEYS.forEach(k => { profileData.me[k] = body.user[k]; });

            updateProfilePictures('me'); // Refresh sidebar image immediately
        } else {
            // --- NEW: Hide the loading modal on error ---
            hideActionProgress();

            // --- MODERATION CHECK ---
            if (isModerationError(body.error)) {
                showModerationErrorModal(body.error, 'edit_profile', payload);
            } else {
                // Standard Error Handling
                const error = body.error || 'Could not save profile.';
                if (error.includes('Username')) {
                    showValidationError('editUsername', error);
                } else if (error.includes('Quiet hours')) {
                    showValidationError('editQuietStart', error);
                } else if (error.includes('current password')) {
                    showValidationError('editCurrentPassword', error);
                } else if (error.includes('Password')) {
                    showValidationError('editPassword', error);
                } else {
                    showValidationError('editConfirmPassword', error);
                }
            }
        }
    })
    .catch(err => {
        // --- NEW: Hide the loading modal on network crash ---
        hideActionProgress();
        console.error('Error updating profile:', err);
        alert('An error occurred while saving. Please try again.');
    });
}

function blockUser(userIdToBlock) {
    if (!profileData.me.blockedUsers) {
        profileData.me.blockedUsers = [];
    }
    if (profileData.me.blockedUsers.includes(userIdToBlock)) {
        alert('This user is already blocked.');
        return;
    }
    profileData.me.blockedUsers.push(userIdToBlock);
    alert(`${profileData[userIdToBlock].name} has been blocked.`);
    document.getElementById('profile-menu-dropdown').classList.add('hidden');
}

function openChat(username) {
    // Retract any start still outstanding to the previous recipient (see loadLoungeChannel).
    emitTypingStop('dm');
    currentChatRecipient = username;
    lastSeenMessageIdByRecipient = null;
    clearTypers('dm');
    window.hasUnreadDM = unreadSenders.has(username);
    if (unreadSenders.has(username)) {
        unreadSenders.delete(username);
        updateNotificationBadge();
        updatePageTitleCount();
    }
    // Reading the thread here retires its push notification. Tag must match the
    // one server.py sends for DMs. This only catches pushes already in flight --
    // setActiveView below is what stops new ones being sent at all.
    clearPushNotifications(`dm-${username}`);
    setActiveView('dm', username);
    renderChatList();
    
    // --- NEW: Enable Mobile Chat View ---
    const container = document.querySelector('.messages-container');
    if (container) container.classList.add('mobile-chat-active');
    clearKeyboardViewportLock(); // never inherit the last visit's keyboard height
    clearKeyboardViewport();
    // --- END NEW ---

    navigateTo(`/messages/${username}`);
}

// A backgrounded phone suspends the page and its socket. Anything sent during that
// window never reaches the live handlers, and we used to re-sync nothing on the way
// back -- so new messages simply never appeared, and the chat list kept showing a
// stale preview (its text lives in profileData[].lastMessage, which only the socket
// or fetchConversations() ever writes).
//
// This re-pulls the authoritative state. It deliberately calls the SAME fetches the
// app already uses on login, so it cannot invent a new source of truth:
//   fetchConversations() -> chat list preview + unread badges
//   renderActiveChat()   -> the open DM's history (which also marks it read)
// Both the visibility handler and the socket's reconnect call this, so it is
// debounced; they usually fire within a moment of each other on resume.
let lastLiveResyncAt = 0;

// Set when the socket drops, cleared once we've caught up. While the socket is up
// it delivers everything live, so there is nothing to catch up ON -- this flag is
// what tells a real gap apart from merely glancing at another app.
let missedEventsWhileDisconnected = false;
// When the page went into the background, so a brief look away can be told from a
// phone that was asleep in a pocket.
let hiddenSince = 0;
// A resume this short cannot have lost anything a live socket wouldn't have caught.
const RESYNC_HIDDEN_GRACE_MS = 20000;

// `force` is for the paths that KNOW they missed things (the offline page's retry
// button), which must resync regardless of how things look.
function resyncLiveState(reason, force = false) {
    if (!loggedIn || !apiToken) return;

    const now = Date.now();
    if (now - lastLiveResyncAt < 1500) return;

    // The bell's badge, ALWAYS -- before the "do we actually need a resync" gate
    // below, not inside it. This was the missing piece behind "the notification dot
    // is not live on mobile": the only thing that ever refreshed
    // unreadNotificationCount in a running app was the 'new_notification' socket
    // event, and a PWA that was suspended has no socket to have received it on.
    // The push still arrived (that path does not go through the socket at all),
    // which is exactly why notifications worked while the dot did not. It is one
    // small GET, and the gate below is specifically about NOT paying for the
    // expensive conversation re-pull -- a different question.
    fetchNotifications(document.getElementById('notifications-page')?.classList.contains('active'));

    // This is not a cheap call. It re-pulls the whole conversation list (~64KB, and
    // the better part of a second of Pi time) and re-fetches AND fully re-renders
    // the open thread -- every image element in it destroyed and rebuilt, which on
    // a phone means re-decoding them. It used to run on EVERY visibilitychange, so
    // glancing at another app and coming back paid the entire bill, over and over.
    //
    // It is only worth paying when we could actually have missed something: the
    // socket dropped, or we were away long enough that it probably did.
    const hiddenFor = hiddenSince ? now - hiddenSince : 0;
    const socketIsDown = !socket || !socket.connected;
    const needsResync = force || missedEventsWhileDisconnected || socketIsDown ||
                        hiddenFor >= RESYNC_HIDDEN_GRACE_MS;

    if (!needsResync) {
        // socket.connected only means "we have not been told otherwise". A phone
        // that loses its radio keeps the flag true until the ping timeout notices,
        // up to ~45s later -- and in that window the socket delivers nothing while
        // still claiming to be up. Skipping on that alone is what stopped the phone
        // seeing messages sent from the desktop.
        //
        // So make the socket prove it: one tiny round trip, against ~64KB and a
        // full re-render for the resync it usually saves.
        verifySocketLive().then(alive => {
            if (alive) {
                console.log(`[Resync] Skipped (${reason}): socket answered, nothing missed`);
                return;
            }
            console.log(`[Resync] Socket did not answer (${reason}) -- treating as a gap`);
            missedEventsWhileDisconnected = true;
            diag('socket_silent', { reason: String(reason) });
            // It is dead but hasn't noticed. Drop it now rather than waiting out the
            // ping timeout; doLiveResync() reconnects a disconnected socket as its
            // first act, so live delivery resumes immediately instead of ~45s later.
            if (socket) socket.disconnect();
            doLiveResync(reason + ' / socket silent');
        });
        return;
    }

    doLiveResync(reason);
}

// Ask the server to answer on the socket we already have. Resolves false if nothing
// comes back in time, which is the only reliable evidence that a "connected" socket
// has actually stopped carrying anything.
// 2s was too tight to be evidence of anything on a slow phone. The ack runs on the
// main thread, and the field log shows that thread blocked for 400-600ms at a time
// (capped reporting, so the real stalls are worse) -- two of those inside one probe
// and a perfectly healthy socket answers late and gets destroyed for it. 5s is around
// ten times the stalls actually observed, while still leaving room for two probes to
// disagree inside the ~45s ping timeout this exists to beat.
function verifySocketLive(timeoutMs = 5000) {
    return new Promise(resolve => {
        if (!socket || !socket.connected) return resolve(false);

        let settled = false;
        const finish = (alive) => { if (!settled) { settled = true; resolve(alive); } };

        const timer = setTimeout(() => finish(false), timeoutMs);
        try {
            socket.emit('sync_ping', () => { clearTimeout(timer); finish(true); });
        } catch (e) {
            clearTimeout(timer);
            finish(false);
        }
    });
}

function doLiveResync(reason) {
    lastLiveResyncAt = Date.now();
    missedEventsWhileDisconnected = false;
    console.log(`[Resync] Re-pulling live state (${reason})`);

    // socket.io reconnects on its own, but if the OS killed it while suspended this
    // gets us back on the wire immediately rather than after its backoff.
    if (socket && !socket.connected) socket.connect();

    // The chat list's "latest message" and unread badges come from here.
    fetchConversations();


    // Refresh the DM you are actually looking at. Keep the existing at-bottom gate:
    // re-rendering while you are scrolled up through history would yank you away.
    // The gate is dmStickToBottom rather than a fresh scroll measurement, for the
    // same reason the renderer's is: measuring here on a phone that came back mid
    // scroll answered "not at the bottom" and skipped the refresh entirely, so the
    // open thread stayed missing whatever arrived while the app was away.
    const onMessages = document.getElementById('messages-page')?.classList.contains('active');
    if (onMessages && currentChatRecipient && dmStickToBottom) {
        renderActiveChat(true);
    }

    // Same treatment for the channel you're looking at. Nothing used to re-pull a
    // lounge on resume, so a socket that died while suspended left the channel
    // frozen at whatever it had -- and only a reload brought it back.
    const onLounge = isLoungeOnScreen();
    if (onLounge && currentLoungeChannelId) resyncLoungeChannel();
}

// Re-pull the open channel from the server, the same fetch loadLoungeChannel() uses.
// Only when we're already at the bottom: re-rendering while the user is scrolled up
// through history would yank them away (same gate as the DM path above).
function resyncLoungeChannel() {
    const channelId = currentLoungeChannelId;
    const chatBody = document.getElementById('lounge-body');
    if (!channelId || !chatBody) return;

    // Gate on loungeStickToBottom, not a fresh measurement: a phone that came back
    // mid-scroll measured "not at the bottom" and skipped the catch-up entirely, so
    // the channel stayed missing whatever arrived while the app was away.
    if (!loungeStickToBottom) return;

    fetch(`${API_BASE_URL}/api/lounge/channel/${channelId}/messages?limit=80`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        // The user may have walked into another channel while this was in flight.
        if (currentLoungeChannelId !== channelId || !data || !data.messages) return;

        seedMyReactions('lounge', data.messages);
        currentLoungeMessages = data.messages;
        // Keep anything still waiting in the outbox -- this assignment would drop it.
        mergePendingIntoChannel(channelId);
        if (currentLoungeMessages.length > 0) {
            oldestLoungeMessageId = currentLoungeMessages[0].id;
        }
        // We're at the bottom, so there is nothing unread to mark: say the bar is
        // already handled. Otherwise this render could drop a "New Messages" line
        // into the middle of the history and scroll the user up to it.
        unreadBarRendered = true;
        renderLoungeMessages(currentLoungeMessages, false, false, false);
    })
    .catch(error => console.error("Error resyncing lounge channel:", error));
}

// ---------------------------------------------------------------------------
// Socket watchdog -- bound the damage when the socket is down
// ---------------------------------------------------------------------------
// There is no fetch fallback in this app: while the socket is down, nothing
// arrives at all, and the thread just stops updating until it comes back. The
// field log has mobile sockets down for 18s, 22s, 50s and 122s at a stretch, so
// that is how long a message can sit undelivered on a phone that looks perfectly
// fine to the person holding it.
//
// This does not fix whatever is closing the transport -- it stops that being the
// user's problem. Once the gap is long enough to have cost a message, we re-pull
// over plain HTTP instead of waiting for the socket to sort itself out.
const SOCKET_WATCHDOG_MS = 2000;
// How long the socket may be down before we stop waiting for it and fetch. This was
// 5s, which -- plus the tick interval -- put the worst case around 6s, and 6s is
// precisely the "sometimes you wait ages for a message" people were reporting. The
// tick itself costs two boolean checks when the socket is healthy, and the fetch
// only ever happens while it is genuinely down, so buying the time back is cheap.
const SOCKET_GAP_BEFORE_RESYNC_MS = 2000;
// A resync is a real cost (the whole conversation list, plus the open thread), so
// while the socket stays down, repeat it at a pace the server can carry.
const SOCKET_RESYNC_EVERY_MS = 15000;
let socketWatchdogTimer = null;
let lastGapResyncAt = 0;

// A socket that says it is connected is not the same as a socket that is carrying
// anything. Engine.IO only notices a dead one when its ping timeout fires -- on the
// server's defaults that is up to ~45s -- and for that entire window socket.connected
// stays true. The watchdog below bailed out at exactly that test, and resyncLiveState
// (the only caller of verifySocketLive) is reached from visibilitychange, reconnect and
// the offline retry button -- none of which a phone sitting in the foreground on an
// open thread ever fires. So nothing at all was watching the one case that matters:
// the app in front of the user, the socket quietly dead.
//
// This is why the same fault looks like three different bugs. Where the outage lands
// inside that ~45s window decides whether the message arrives instantly, arrives
// "eventually" (the ping timeout finally fires and the disconnect path resyncs), or
// never arrives until the thread is reopened -- reopening only appears to fix it
// because renderActiveChat() re-pulls the thread over plain HTTP. The socket is still
// dead afterwards, which is why it then happens again.
//
// It also explains the missing push: the server skips the push for a thread it
// believes you are looking at, and that belief comes from active_views, which is keyed
// on the socket. A zombie socket keeps the claim alive, so the phone loses the socket
// frame AND the push that was supposed to be its safety net. Dropping the socket here
// fires 'disconnect' on the server, which releases the view.
let lastSocketTrafficAt = 0;
let lastSocketProbeAt = 0;
let socketProbeInFlight = false;
// Consecutive unanswered probes. Tearing down the socket is expensive -- it costs a
// reconnect plus a full resync (conversation list + open thread), and that resync is
// itself a render storm, which on a slow phone blocks the main thread and makes the
// NEXT probe more likely to be missed. One late ack was enough to start that loop.
// Requiring two in a row means a single stall is absorbed, while a socket that is
// genuinely dead still fails every probe and is dropped one interval later.
let socketProbeFailures = 0;
const SOCKET_PROBE_FAILURES_BEFORE_DROP = 2;
// Quiet for this long is worth one ack-sized question. Well inside the ping timeout
// we are trying to beat, and long enough that an active conversation never probes.
//
// This was 12s, which is not a quiet socket -- it is a quiet CONVERSATION. onAny only
// counts inbound events and deliberately ignores Engine.IO heartbeats (see the comment
// on it in initializeSocket), so a thread where nobody happens to be typing crosses
// this line every 12 seconds by design. The field log shows exactly that: every
// socket_zombie fired at quietMs 12616, 12705, 13562, 13895, 16131 -- all sitting just
// over the threshold, none of them a dead socket. 30s is longer than any natural gap
// between turns in a live exchange, so the probe goes back to meaning something.
const SOCKET_QUIET_BEFORE_PROBE_MS = 30000;
// Floor on probe rate for a thread that is simply idle.
const SOCKET_PROBE_EVERY_MS = 10000;

function startSocketWatchdog() {
    if (socketWatchdogTimer) return;

    socketWatchdogTimer = setInterval(() => {
        if (!loggedIn || !apiToken) return;

        // A hidden page is the OS's business: it is frozen or throttled, and the
        // visibilitychange handler already resyncs on the way back. Fetching from
        // here would only burn the battery of a phone in a pocket.
        if (document.visibilityState !== 'visible') return;

        if (!socket) return;

        // The socket claims to be up. Make it prove it, but only when silence would
        // actually cost something: the user is looking at a thread or a channel
        // (activeViewTarget), and nothing has come down the pipe for a while. Anywhere
        // else a late message is invisible anyway, and this stays off.
        if (socket.connected) {
            if (!activeViewTarget) return;
            if (socketProbeInFlight) return;

            const quietFor = lastSocketTrafficAt ? Date.now() - lastSocketTrafficAt : 0;
            if (quietFor < SOCKET_QUIET_BEFORE_PROBE_MS) return;
            if (Date.now() - lastSocketProbeAt < SOCKET_PROBE_EVERY_MS) return;

            lastSocketProbeAt = Date.now();
            socketProbeInFlight = true;
            // The probe takes up to 8s to time out. Both of these can move underneath
            // it -- the user walks out of the thread, or a re-login builds a new
            // socket -- and tearing down whatever `socket` points at by then would
            // kill a healthy connection on the strength of a dead one's silence.
            const probed = socket;
            const probedView = activeViewTarget.type;
            verifySocketLive().then(alive => {
                socketProbeInFlight = false;
                // A socket we no longer hold tells us nothing about the one we do, so
                // its verdict must not carry into the new socket's failure count.
                if (socket !== probed) return;
                if (alive) {
                    // The ack is itself traffic; onAny does not see acks, so record it
                    // here or a healthy but idle thread would re-probe every interval.
                    lastSocketTrafficAt = Date.now();
                    socketProbeFailures = 0;
                    return;
                }

                // One missed ack is not proof. On a phone that blocks its main thread
                // for hundreds of milliseconds at a time, it is at least as likely to
                // be a late answer as a dead pipe -- and acting on it costs the very
                // resync that makes the next probe more likely to be missed. Wait for
                // the next tick to agree before doing anything irreversible.
                socketProbeFailures++;
                if (socketProbeFailures < SOCKET_PROBE_FAILURES_BEFORE_DROP) {
                    diag('socket_probe_missed', { quietMs: quietFor, n: socketProbeFailures });
                    // Ask again on the next tick rather than waiting out the idle-probe
                    // floor: that floor paces probes on a thread that is merely quiet,
                    // and this one has already failed once. Holding the confirmation
                    // back by another 10s would push the whole decision past the ping
                    // timeout, and then the watchdog would never beat Engine.IO to it.
                    lastSocketProbeAt = 0;
                    return;
                }
                socketProbeFailures = 0;

                diag('socket_zombie', { quietMs: quietFor, view: probedView });
                // Believed connected, delivering nothing. Anything sent to us in this
                // window is genuinely lost, so earn the resync before tearing it down.
                missedEventsWhileDisconnected = true;
                if (!socketDownSince) socketDownSince = Date.now();
                // Drop it rather than waiting out the ping timeout: doLiveResync
                // reconnects a disconnected socket as its first act, so live delivery
                // resumes now instead of up to ~45s from now.
                socket.disconnect();
                resyncLiveState('socket connected but silent', true);
            });
            return;
        }

        // Socket.IO is waiting out its own backoff; ask it to try now.
        socket.connect();

        const downFor = socketDownSince ? Date.now() - socketDownSince : 0;
        if (downFor < SOCKET_GAP_BEFORE_RESYNC_MS) return;
        if (Date.now() - lastGapResyncAt < SOCKET_RESYNC_EVERY_MS) return;

        lastGapResyncAt = Date.now();
        // resyncLiveState sees the dead socket and re-pulls the chat list and the
        // open thread over HTTP -- the same fetches login uses, so no new source of
        // truth and no new failure mode.
        resyncLiveState('socket down -- catching up over HTTP');
    }, SOCKET_WATCHDOG_MS);
}

function initializeSocket() {
    if (socket) {
        socket.disconnect();
    }

    socket = io.connect(API_BASE_URL, {
        query: { token: apiToken },
        // Socket.IO's default backoff climbs to 5s between attempts. A phone that
        // drops constantly (the field log showed 18s, 22s, 50s and 122s outages)
        // spends most of that time waiting rather than trying, so keep the retries
        // close together -- the connection is cheap, the silence is not.
        reconnectionDelay: 500,
        reconnectionDelayMax: 2000
    });

    // Any inbound event is proof the pipe is still carrying. Bound once on the socket
    // rather than inside each handler, so it cannot drift as handlers are added, and
    // so a thread that is merely quiet is told apart from one that is cut off.
    // Engine.IO's own heartbeats deliberately do NOT count: they are the thing whose
    // ~45s timeout we are trying to beat.
    socket.onAny(() => { lastSocketTrafficAt = Date.now(); });

    // A post verdict can arrive before anyone is listening for it. The worker's
    // local keyword blocklist decides in about a millisecond -- well before the
    // browser has finished reading the HTTP 202 and run the .then() that attaches
    // the listeners. That verdict landed on nobody, and the user sat through the
    // full 20s "server is busy" timeout for a post that was rejected instantly.
    // Bound here instead, at socket setup, so nothing is missed; handleCreatePost
    // claims its verdict out of this buffer.
    socket.on('post_published', (data) => bufferPostVerdict('post_published', data));
    socket.on('post_rejected',  (data) => bufferPostVerdict('post_rejected', data));

    startSocketWatchdog();

    // 'connect' also fires for the very first connection, where the normal login
    // path has already loaded everything -- only a RE-connect means we were offline
    // and may have missed messages.
    let hasConnectedBefore = false;

    socket.on('connect', () => {
        console.log('Socket.IO connected successfully!');
        // A fresh socket has, by definition, just carried something.
        lastSocketTrafficAt = Date.now();
        // Whatever the old socket failed to answer is not this one's record.
        socketProbeFailures = 0;
        // A reconnect means we were cut off. How often this happens, and how long
        // the gap was, is the difference between "the app is slow" and "the phone's
        // link keeps dying and every recovery costs a full resync".
        if (socketDownSince) {
            diag('socket_up', { downMs: Date.now() - socketDownSince });
            socketDownSince = 0;
        }
        socket.emit('join_all_lounge_rooms');

        // A live socket is proof the network is back. This is what clears the
        // offline page and drains the outbox after a tunnel or a dead spot.
        reportNetwork('up');
        flushOutbox('socket connected');

        // Anything we believed about typing predates the gap and any stop sent during it
        // never reached us. Drop it all; a live typer re-announces within a ping.
        clearTypers('dm');
        clearTypers('lounge');

        // This is a new socket, so the server has no idea what we're looking at and
        // would push a DM we have open. Tell it again.
        lastSentActiveView = null;
        syncActiveView();

        if (!hasConnectedBefore) {
            // One line per session, per device. This is the ground truth for "is this
            // phone even running the code we just shipped?"
            diag('boot', {
                v: APP_BUILD,
                standalone: window.matchMedia('(display-mode: standalone)').matches,
                // Whichever transport this session actually opened on. It can read
                // 'websocket' straight away, or 'polling' if the connection is still
                // to be upgraded -- the 'upgrade' event below reports where it ends up.
                transport: socket.io?.engine?.transport?.name || '?'
            });
        }

        // Did this device actually reach a WebSocket? A phone whose upgrade probe
        // fails stays on long-polling for the life of the socket, paying a full round
        // trip per message -- which through Cloudflare is a very different experience
        // from one frame down an open pipe. Nothing else reports this, and it is
        // invisible from the server: both transports look like a connected client.
        const engine = socket.io && socket.io.engine;
        if (engine && !engine.__apexTransportWatched) {
            engine.__apexTransportWatched = true;
            engine.on('upgrade', () => diag('transport', { to: engine.transport.name }));
            engine.on('upgradeError', (err) => diag('transport_failed', {
                stuckOn: engine.transport.name,
                err: String((err && err.message) || err).slice(0, 80)
            }));
            // No upgrade either way within this long means it is not coming.
            setTimeout(() => {
                if (engine.transport && engine.transport.name !== 'websocket') {
                    diag('transport_stuck', { on: engine.transport.name });
                }
            }, 15000);
        }

        if (hasConnectedBefore) resyncLiveState('socket reconnected');
        hasConnectedBefore = true;
    });

    // Socket.IO retries on its own; each failed attempt is another vote that the
    // network is not there.
    socket.on('connect_error', () => reportNetwork('trouble'));

    socket.on('disconnect', (reason) => {
        if (!socketDownSince) socketDownSince = Date.now();
        // Whether the user was actually LOOKING at the app when this died is the
        // difference between "Android froze a backgrounded PWA", which is normal and
        // already handled on resume, and "the connection was killed under someone
        // mid-conversation", which is a real fault in the path. The reason string is
        // 'transport close' either way, so it cannot tell them apart on its own.
        diag('socket_down', {
            reason: String(reason || 'unknown'),
            vis: document.visibilityState,
            transport: socket?.io?.engine?.transport?.name || '?',
            // How long the page had been backgrounded when it went. A drop moments
            // after hiding is the freeze; one after minutes hidden is the OS
            // reclaiming an idle socket.
            hiddenMs: (document.visibilityState === 'hidden' && hiddenSince)
                ? Date.now() - hiddenSince : 0
        });

        // Anything sent to us from here until the socket is back is a genuine miss,
        // and only a resync can recover it. This is the flag that earns the next
        // resync the right to run.
        missedEventsWhileDisconnected = true;

        // The socket is the earliest warning that the connection went bad -- it
        // drops well before a fetch times out. Treat it as suspicion, not proof:
        // reportNetwork() probes, and only a probe that keeps failing for
        // NET_UNSTABLE_TO_OFFLINE_MS puts the offline page up. A server restart or
        // a one-second blip therefore shows the banner at most.
        reportNetwork('trouble');

        // Our own outstanding starts died with the socket -- forget them so a reconnect
        // doesn't leave us believing we already announced.
        outgoingTyping.dm = { contextId: null, lastPingAt: 0, stopTimer: null };
        outgoingTyping.lounge = { contextId: null, lastPingAt: 0, stopTimer: null };
        clearTypers('dm');
        clearTypers('lounge');

        // The server dropped our view with the socket; don't let the cache claim it's
        // still reported, or a reconnect would silently leave pushes suppressed.
        lastSentActiveView = null;
    });

    socket.on('dm_received', (data) => {
        const senderUsername = data.from;
        const isBlocked = isUserBlocked(senderUsername);
        // A message landing in the open thread knocks the googly eyes (a no-op
        // on every other theme).
        if (senderUsername === currentChatRecipient && !isBlocked) googlyNudge();

        if (!messageHistory[senderUsername]) messageHistory[senderUsername] = [];
        
        // Handle missing profile data for ANNOUNCEMENTS or new users
        if (!profileData[senderUsername]) {
            if (senderUsername === 'ANNOUNCEMENTS') {
                profileData['ANNOUNCEMENTS'] = {
                    name: 'ANNOUNCEMENTS',
                    username: 'ANNOUNCEMENTS',
                    rank: 'admin',
                    profilePicUrl: null, 
                    lastMessage: ''
                };
            } else {
                profileData[senderUsername] = {
                    name: senderUsername,
                    username: senderUsername,
                    rank: 'user',
                    lastMessage: ''
                };
            }
        }

        // Add message to history
        messageHistory[senderUsername].push({
            id: data.id,
            sender: senderUsername,
            text: data.message,
            image: data.image,
            attachments: data.attachments || null,
            time: new Date(data.created_at),
            reply_to_id: data.reply_to_id,
            reply_to: data.reply_to,
            message_type: data.message_type || 'user_message',
            effect: data.effect,
            poll: storePoll(data.poll) || null
        });

        if (profileData[senderUsername]) {
            profileData[senderUsername].lastMessage = data.message
                ? previewTextFor(data.message, data.effect)
                : wordlessPreviewText(!!data.poll, false, data.attachments);
            profileData[senderUsername].lastMessageTime = new Date(data.created_at);
        }

        // --- VISIBILITY LOGIC START ---
        const messagesPage = document.getElementById('messages-page');
        const isChatOpen = messagesPage.classList.contains('active') && currentChatRecipient === senderUsername;
        
        // You are "viewing" the chat ONLY if the page is open AND the browser tab is visible.
        const isActuallyViewing = isChatOpen && document.visibilityState === 'visible';

        // If you are NOT actually viewing it (or blocked), treat as unread
        if (!isActuallyViewing && !isBlocked) {
            unreadSenders.add(senderUsername);
            updateNotificationBadge();
            updatePageTitleCount();
            startTitleFlash(`New message from ${senderUsername}`); // Flash the title

            // No notification is raised here. Desktop gets in-app cues only
            // (title flash, badge, unread counts); mobile gets a real push from
            // the server, grouped per sender. Raising one here too would double
            // up on mobile and resurrect desktop popups.
        } else if (isActuallyViewing) {
            // The server pushes on every DM regardless of what you are looking
            // at, so retire it immediately if you are already in this thread.
            clearPushNotifications(`dm-${senderUsername}`);
        }

        renderChatList();

        // "A DM landed in a thread I had open and nothing appeared" has two causes
        // that look identical from the outside, and only one of them is a delivery
        // problem at all:
        //   open=0  -> the render was skipped, because this device did not agree the
        //              thread was on screen (page not .active, or a recipient mismatch)
        //   open=1, stick=0 -> the render RAN and the bubble is in the DOM, but the
        //              scroll was preserved instead of followed, so it drew below the
        //              fold. Reopening the thread resets the flag, which is exactly why
        //              backing out and coming back "fixes" it.
        // gap is how far the thread was from its own bottom when the message arrived;
        // anything over DM_BOTTOM_THRESHOLD is what turned stick off.
        {
            const cb = document.getElementById('chat-body');
            diag('dm_gate', {
                open: isChatOpen ? 1 : 0,
                page: messagesPage.classList.contains('active') ? 1 : 0,
                recip: currentChatRecipient === senderUsername ? 1 : 0,
                vis: document.visibilityState === 'visible' ? 1 : 0,
                stick: dmStickToBottom ? 1 : 0,
                bar: currentFirstUnreadId ? 1 : 0,
                gap: cb ? Math.round(cb.scrollHeight - cb.scrollTop - cb.clientHeight) : -1,
                v: APP_BUILD
            });
        }

        // If the chat is open (even if hidden), render the message to the DOM
        // If the chat is open (even if hidden), render the message to the DOM
        if (isChatOpen) {
            // Whether we follow this message down is dmStickToBottom, not a fresh
            // reading of scrollTop: measuring here is what broke on mobile, where a
            // message routinely lands while the previous one is still scrolling.
            // ...but the bubble itself flies in either way. Whether we FOLLOW the
            // message down is a scroll decision; whether it slides into place is not,
            // and gating the slide on the same flag is what made a message from the
            // other person snap in while our own always glided.
            renderChatMessages(!dmStickToBottom, dmStickToBottom, 0, true);

            // ONLY mark as read on the server if the user is actually looking at the tab
            if (isActuallyViewing) {
                socket.emit('mark_message_as_read', { message_id: data.id });
            }
        }
        // --- VISIBILITY LOGIC END ---
    });

    // Registered here, once. This used to live INSIDE the 'dm_received' handler, so
    // every message received added another copy of it: after a busy thread a single
    // theme change re-ran applyChatTheme hundreds of times, and the listener list
    // grew for the life of the socket.
    socket.on('theme_updated', (data) => {
        // If you are currently looking at the chat with the person who changed the theme
        if (currentChatRecipient === data.conversation_with) {
            applyChatTheme(data.theme);
        }
    });

    // Our own message, sent from one of our OTHER sessions (typically the phone
    // while this desktop tab sat in the background). 'dm_received' only ever goes to
    // the other person, so before this the thread here silently lost every message
    // written elsewhere -- their replies appeared, ours didn't, and only F5 healed it.
    socket.on('dm_sent', (data) => {
        const recipient = data.to;
        if (!recipient) return;
        if (recipient === currentChatRecipient) googlyNudge(0.7);

        // Did THIS device send it? Then the bubble is already on screen (and
        // onOutboxItemSent gives it its real id). Nothing to add.
        const thread = messageHistory[recipient];
        if (data.client_id && thread && thread.some(m => String(m.id) === String(data.client_id))) {
            return;
        }
        // Belt and braces: an echo we've already applied (a reconnect can redeliver).
        if (thread && thread.some(m => String(m.id) === String(data.id))) return;

        if (thread) {
            thread.push({
                id: data.id,
                sender: 'me',
                text: data.message,
                image: data.image,
                attachments: data.attachments || null,
                time: new Date(data.created_at),
                reply_to_id: data.reply_to_id,
                reply_to: data.reply_to,
                message_type: data.message_type || 'user_message',
                effect: data.effect,
                poll: storePoll(data.poll) || null
            });
        }

        // Keep the chat list honest even for a thread whose history isn't loaded
        // here: same preview text and ordering the local send path writes.
        if (profileData[recipient]) {
            profileData[recipient].lastMessage = data.message
                ? `You: ${previewTextFor(data.message, data.effect)}`
                : wordlessPreviewText(!!data.poll, true, data.attachments);
            profileData[recipient].lastMessageTime = new Date(data.created_at);
        }

        // Writing in a thread means we read it, wherever we did it. Without this the
        // desktop keeps a stale unread dot on a conversation we've already answered.
        if (unreadSenders.has(recipient)) {
            unreadSenders.delete(recipient);
            updateNotificationBadge();
            updatePageTitleCount();
        }

        renderChatList();

        const messagesPage = document.getElementById('messages-page');
        const isChatOpen = messagesPage.classList.contains('active') && currentChatRecipient === recipient;
        if (isChatOpen && thread) {
            // Same split as 'dm_received': fly the new bubble in regardless of whether
            // this thread is following the bottom.
            renderChatMessages(!dmStickToBottom, dmStickToBottom, 0, true);
        }
    });

    // A comment added or removed on any post: keep counts and an open thread current.
    socket.on('post_comments_changed', handlePostCommentsChanged);
    socket.on('post_comment_edited', data => handlePostCommentsChanged(data, true));

    socket.on('new_notification', () => {
        // No popup here: this socket event only fires while the app is open, so
        // it was a desktop-only notification. In-app badges cover it. Someone
        // already on the page sees the new row land at the top.
        fetchNotifications(!!document.getElementById('notifications-page')?.classList.contains('active'));
    });

    // Someone removed us from a lounge. The server has already taken this socket
    // out of the lounge's rooms, so if it is on screen it has gone silent -- close
    // it rather than leave a chat that will never update again.
    socket.on('lounge_member_removed', (data) => {
        if (!data) return;
        // isLoungeOnScreen(), not '#lounge-page.active': the lounge is equally on
        // screen when it is parked inside Messages, and asking only about the page
        // meant being removed from a lounge you were reading THERE did nothing at
        // all -- you were left sitting in a channel the server had already stopped
        // sending to, with no way to tell.
        const viewingIt = isLoungeOnScreen()
            && Number(currentLoungeId) === Number(data.lounge_id);
        if (viewingIt) {
            showToast(`You were removed from ${data.lounge_name || 'this lounge'}.`, 'error');
            // Leaving Messages entirely would be a bigger move than the event
            // warrants: the half of the page you were not in is still yours. Fall
            // back to Direct there, and off the page on the lounge page.
            if (loungeHostedInMessages()) setMessagesPaneMode('dms');
            else showPage('index-page');
        }
        if (typeof fetchAndRenderLounges === 'function') fetchAndRenderLounges();
    });

    // Someone joined, left, was removed or changed role in a lounge we have
    // open. Drop the cached list and redraw whichever member views are showing,
    // so nobody has to reload to see a new face.
    socket.on('lounge_members_changed', (data) => {
        if (!data || Number(data.lounge_id) !== Number(currentLoungeId)) return;
        fetchLoungeMembers(true).then(() => {
            const open = id => {
                const el = document.getElementById(id);
                return el && !el.classList.contains('hidden');
            };
            if (open('lounge-members-modal')) renderLoungeSettingsMembers();
            if (open('channel-members-picker')) renderChannelMemberPicker();
            if (open('cp-members-picker')) renderChannelMemberPicker('cp-members-list', 'cp-members-filter');
            if (document.getElementById('roles-list')?.offsetParent) renderRolesBoard();
            if (open('invite-lounge-member-modal') && Number(inviteModalState.loungeId) === Number(data.lounge_id)) {
                invLoadRoster();
                invSearch(inviteModalState.query);
            }
        });
    });

    // Somebody added, edited or removed a notice on a board we have open.
    // Everyone else picks it up the next time they open a channel, when the pin
    // request brings the notices bar down with it.
    socket.on('lounge_notices_changed', (data) => {
        if (!data || !currentNoticeChannel) return;
        if (Number(data.channel_id) !== Number(currentNoticeChannel.id)) return;
        loadNoticeBoard(currentNoticeChannel.id);
    });

    socket.on('new_lounge_message', (msg) => {
        if (loungeRailList.length) scheduleLoungeRailRefresh();
        const isLoungePageActive = isLoungeOnScreen();
        const isActuallyViewing = isLoungePageActive && document.visibilityState === 'visible';

        // A message we wrote ourselves is never unread, no matter which of our devices
        // wrote it -- the server already moved our read marker when it accepted it.
        // Painting the dot here anyway left the desktop showing an unread channel for
        // something we'd just typed on the phone.
        const isMine = msg.author && profileData.me && msg.author.username === profileData.me.username;

        if (msg.channel_id === currentLoungeChannelId) {
            
            if (isLoungePageActive) {
                let wasOptimisticallyRendered = false; // <-- ADD THIS FLAG

                if (msg.author.username === profileData.me.username) {
                    // Which bubble is this echo? The server hands back the client_id
                    // we sent with it, so the answer is exact: the temp bubble with
                    // that id, and only on the device that actually sent it. The old
                    // code guessed -- "the oldest temp the server has already
                    // accepted" -- which was fine for one device but overwrote a
                    // pending bubble here whenever the message came from ANOTHER of
                    // our sessions (posting from the phone ate a desktop draft, or
                    // the message just never showed).
                    let tempMessageIndex = -1;
                    if (msg.client_id) {
                        tempMessageIndex = currentLoungeMessages.findIndex(m => String(m.id) === String(msg.client_id));
                    } else {
                        // No client_id (an older client, or a server-generated system
                        // message): fall back to the previous heuristic. Still skips
                        // temps that are only queued, so an echo can't overwrite a
                        // message that hasn't been sent yet.
                        tempMessageIndex = currentLoungeMessages.findIndex(m =>
                            m.id.toString().startsWith('temp_') && !findOutboxItem(m.id));
                    }

                    if (tempMessageIndex > -1) {
                        transferEntryAnimation('lounge', currentLoungeMessages[tempMessageIndex].id, msg.id);
                        currentLoungeMessages[tempMessageIndex] = msg;
                        wasOptimisticallyRendered = true; // <-- WE ALREADY ANIMATED THIS
                    } else if (!currentLoungeMessages.some(m => String(m.id) === String(msg.id))) {
                        // Sent from one of our other devices: nothing is on screen for
                        // it here, so it lands like any other new message.
                        currentLoungeMessages.push(msg);
                    }
                } else {
                    currentLoungeMessages.push(msg);
                }

                // Whether we follow this message down is loungeStickToBottom, not a
                // fresh reading of scrollTop -- measuring here is what stranded the
                // channel mid-history whenever a message landed while the previous
                // one was still scrolling.
                const shouldPreserveScroll = !loungeStickToBottom;
                const shouldAnimate = loungeStickToBottom && !wasOptimisticallyRendered;

                if (wasOptimisticallyRendered) {
                    // We already drew this message, and it is mid fly-in. Every render
                    // rebuilds the whole list from scratch, so re-rendering now would
                    // destroy the animating bubble and snap it into place -- and this
                    // render exists only to swap the temp id for the real one. Let the
                    // animation finish first.
                    // NB: pass preserveScroll=false. The optimistic render kicked off a
                    // SMOOTH scroll to the bottom that may still be in flight; freezing
                    // the current (mid-flight) offset cancels it and strands the new
                    // message below the fold. Landing at the bottom is what we want.
                    const remaining = Math.max(0, MSG_FLY_IN_MS - (Date.now() - lastOptimisticRenderAt));
                    setTimeout(() => {
                        renderLoungeMessages(currentLoungeMessages, false, false, false);
                    }, remaining);
                } else {
                    // shouldAnimate still decides the scroll; the fly-in is
                    // unconditional here, so a message landing while the channel is
                    // scrolled up slides in rather than appearing fully formed.
                    renderLoungeMessages(currentLoungeMessages, shouldPreserveScroll, false, shouldAnimate, 0, true);
                }
            }
            
            // 3. Mark as read OR trigger live notification
            if (isActuallyViewing) {
                fetch(`${API_BASE_URL}/api/lounge/channel/${currentLoungeChannelId}/mark_read`, {
                    method: 'POST',
                    headers: { 'Authorization': `Bearer ${apiToken}` }
                });
            } else {
                // --- FIX: Force Absolute Truth Sync ---
                fetchAndRenderMyLounges();
                const channelItem = document.getElementById(`channel-item-${msg.channel_id}`);
                if (channelItem && !isMine) {
                    channelItem.classList.add('has-unread');
                    updateMobileChannelBadge();
                }
            }

        }
        else {
            // The channel isn't the one on screen. If we wrote this from another
            // device its messages are already read, so only refresh the badges from
            // the server -- don't paint a dot the server would immediately deny.
            // --- FIX: Force Absolute Truth Sync ---
            fetchAndRenderMyLounges();
            const channelItem = document.getElementById(`channel-item-${msg.channel_id}`);
            if (channelItem && !isMine) {
                channelItem.classList.add('has-unread');
                updateMobileChannelBadge();
            }
        }
    });

    // Somebody voted, added an option, or closed a poll we can see. The signal
    // carries no tally on purpose -- see handlePollUpdateSignal.
    socket.on('poll_update', (signal) => handlePollUpdateSignal(signal));

    socket.on('message_updated', (data) => {
        if (!messageHistory[currentChatRecipient]) return;

        const msgToUpdate = messageHistory[currentChatRecipient].find(m => m.id === data.message_id);
        if (msgToUpdate) {
            if (data.is_deleted) {
                msgToUpdate.is_deleted = true;
                msgToUpdate.text = data.text;
                msgToUpdate.image = null;
                msgToUpdate.attachments = null;
                msgToUpdate.reactions = {};
            }
            if (data.text && !data.is_deleted) {
                msgToUpdate.text = data.text;
            }
            if (data.edited_at) {
                msgToUpdate.edited_at = new Date(data.edited_at);
            }
            if (data.reactions !== undefined) {
                msgToUpdate.reactions = data.reactions;
            }
            renderChatMessages(true);
        }
    });
    socket.on('lounge_message_updated', (data) => {
        const msgToUpdate = currentLoungeMessages.find(m => m.id === data.message_id);
        if (msgToUpdate) {
            if (data.is_deleted) {
                msgToUpdate.is_deleted = true;
                msgToUpdate.text = data.text;
                msgToUpdate.image = null;
                msgToUpdate.attachments = null;
                msgToUpdate.reactions = {};
            }
            if (data.text && !data.is_deleted) {
                msgToUpdate.text = data.text;
            }
            if (data.edited_at) {
                msgToUpdate.edited_at = new Date(data.edited_at);
            }
            if (data.reactions !== undefined) {
                msgToUpdate.reactions = data.reactions;
            }
            renderLoungeMessages(currentLoungeMessages, true, false);
        }
    });
    socket.on('recipient_read_messages', (data) => {
        if (currentChatRecipient === data.sender_username) {
            lastSeenMessageIdByRecipient = data.last_read_message_id;
            renderChatMessages(true);
        }
    });
    // An officer pinning something on their laptop updates the bar on every
    // phone in the channel. The server sends the whole list rather than a delta,
    // so a client that missed an earlier event still lands in the right state.
    socket.on('lounge_pins_updated', (data) => {
        if (!data || String(data.channel_id) !== String(currentLoungeChannelId)) return;
        loungePins = {
            channelId: data.channel_id,
            pins: Array.isArray(data.pins) ? data.pins : [],
        };
        renderLoungePinBar();
    });

    // Somebody read the channel we are looking at: walk their face down to the
    // message they stopped at. Only for the open channel -- a marker for any
    // other one points at messages that are not on screen, and the channel's
    // own open will fetch the current answer anyway.
    // A mod tied or untied a board. That can add rows to this sidebar, remove
    // them, or remove a board this member may no longer open at all -- so the
    // list is refetched rather than patched, and the server reapplies its own
    // permission checks on the way.
    socket.on('lounge_channels_changed', (data) => {
        if (!data || String(data.lounge_id) !== String(currentLoungeId)) return;
        if (!isLoungeOnScreen()) return;
        reloadLoungeChannels(currentLoungeId);
        // A tie also decides which notice boards reach the channel we are sitting
        // in, so the bar above the thread is now stale too.
        if (currentLoungeChannelId) loadLoungePins(currentLoungeChannelId);
    });

    socket.on('lounge_read', (data) => {
        if (!data || String(data.channel_id) !== String(currentLoungeChannelId)) return;
        if (profileData.me && data.username === profileData.me.username) return;
        noteLoungeReader(data);
        if (currentLoungeMessages && currentLoungeMessages.length) {
            // preserveScroll: a face moving is not a reason to follow the thread
            // anywhere, least of all while someone is reading back through it.
            renderLoungeMessages(currentLoungeMessages, true);
        }
    });

    socket.on('lounge_activity', (data) => {
        console.log("[Socket] Lounge Activity:", data); 

        // 1. If we are currently looking at this specific channel, do nothing
        if (currentLoungeChannelId === data.channel_id && isLoungeOnScreen() && document.visibilityState === 'visible') {
            return;
        }

        // --- FIX: ABSOLUTE TRUTH SYNC ---
        // Instead of manually counting and guessing, we just ping the server
        // to re-evaluate the badges. This perfectly updates the sidebar, 
        // the explore page, and the home page in real-time.
        fetchAndRenderMyLounges();
        // The rail keeps its OWN copy of the lounge list, so the line above does
        // not touch it. It has to be told too, and this is the only event that
        // reaches us for a lounge whose channel rooms we never joined -- i.e.
        // any lounge not opened since the page loaded, which is most of them.
        // Without this the switcher showed no dot on exactly the lounges whose
        // dot you needed, while the Explore badge beside it counted them.
        if (loungeRailList.length) scheduleLoungeRailRefresh();
    });
    socket.on('user_typing', (data) => {
        // Determine if this event is for the page we are currently looking at
        let type = null;
        
        // Check DM match
        if (currentChatRecipient && data.context_id === currentChatRecipient) {
            type = 'dm';
        } 
        // Check Lounge match
        else if (currentLoungeChannelId && String(data.context_id) === String(currentLoungeChannelId)) {
            type = 'lounge';
        }

        if (type) {
            noteTyping(type, data.username, data.full_name);
        }
    });

    socket.on('user_stopped_typing', (data) => {
        let type = null;

        // Logic must match above to ensure we clear the correct list
        if (currentChatRecipient && data.context_id === currentChatRecipient) {
            type = 'dm';
        }
        else if (currentLoungeChannelId && String(data.context_id) === String(currentLoungeChannelId)) {
            type = 'lounge';
        }

        if (type && currentTypers[type].delete(data.username)) {
            updateTypingUI(type);
        }
    });
    // This device's session was signed out from another device in Settings.
    socket.on('session_revoked', () => {
        showToast('This device was signed out from another device.', 'error');
        handleLogout();
    });
    socket.on('online_status_update', (data) => {
        // Sync the global online list with the server's truth
        currentOnlineUsers = data.online_usernames;
        // Presence is noisy -- a backgrounded phone or a dropped socket takes a user
        // out of this list for a few seconds constantly. The dots follow the raw
        // truth; the Active now row runs off the debounced view below.
        recordActiveSeen(currentOnlineUsers);
        // Re-run the UI logic (which now includes the 'me on index' filter)
        applyOnlineStatuses();
        renderActiveNowRow();
    });
    setInterval(() => {
        if (currentOnlineUsers.length > 0) {
            console.log("[Heartbeat] Re-applying dots for:", currentOnlineUsers);
            applyOnlineStatuses();
        }
        // Runs even with nobody online: this is what expires the last stragglers
        // out of the row once their 5 minutes are up.
        renderActiveNowRow();
    }, 5000);
}
/* The only surfaces where the presence dot answers a question the user is
   actually asking. Everywhere else a list of faces exists to identify people --
   who holds this role, who can I invite, who am I mentioning, who contributed --
   and "are they online right now" is not part of that. The dot there is noise:
   it pulses, it draws the eye to whichever row happens to be green, and it
   implies the list is ranked or filtered by activity when it isn't.

   This is an allowlist rather than a growing pile of exclusions on purpose. New
   rosters and pickers get added constantly, and the right default for a new one
   is no dot -- a surface that genuinely reports presence should have to say so
   by adding itself here. */
const PRESENCE_SURFACES = [
    '#active-now-row',                  // the row whose entire subject is who is around
    '#chat-list',                       // DM list -- "can I reach them right now"
    '#active-chat-header',              // the person you are currently talking to
    '#user-preview-pic',                // the preview card is a small profile...
    '#profile-page .profile-pic-large'  // ...and this is the profile itself
].join(',');

function applyOnlineStatuses() {
    if (!profileData.me || !profileData.me.username) return;
    const allPics = document.querySelectorAll('[data-user-pic-id]');
    
    // 1. Clear all existing indicators
    allPics.forEach(el => el.classList.remove('online-user'));

    // 2. Paint only the avatars sitting on a presence surface
    currentOnlineUsers.forEach(username => {
        const key = (username === profileData.me.username) ? 'me' : username;
        const targets = document.querySelectorAll(`[data-user-pic-id="${key}"]`);

        targets.forEach(el => {
            if (el.closest(PRESENCE_SURFACES)) el.classList.add('online-user');
        });
    });
}

/* ============================================================
   ACTIVE NOW  (Messages page)
   ============================================================
   online_status_update is the server's instantaneous truth, and it flickers:
   phones background, sockets reconnect, and a user drops off the list for a few
   seconds at a time. Rendering that directly made the row jump around. Instead we
   remember the last time each username was seen online and keep them in the row
   until they have been gone for ACTIVE_NOW_GRACE_MS straight. */
const ACTIVE_NOW_GRACE_MS = 5 * 60 * 1000; // 5 minutes
const activeSeenAt = {};          // username -> ms timestamp of last sighting
let activeNowDirectoryFetched = false;
let lastActiveNowSignature = '';

function recordActiveSeen(usernames) {
    const now = Date.now();
    (usernames || []).forEach(u => { activeSeenAt[u] = now; });
}

// Usernames still inside the grace window, oldest sighting pruned as we go.
// Sorted by name so the row keeps a stable order instead of reshuffling on
// every heartbeat.
function getActiveNowUsers() {
    const now = Date.now();
    const me = profileData.me ? profileData.me.username : null;

    Object.keys(activeSeenAt).forEach(u => {
        if (now - activeSeenAt[u] > ACTIVE_NOW_GRACE_MS) delete activeSeenAt[u];
    });

    // The server's presence list is everyone online on APEX, not just people you
    // know, so the row is ordered by who you are likeliest to message: pinned
    // chats, then everyone you have a conversation with (most recent first), then
    // the rest by name. The cap in renderActiveNowRow() then keeps the people who
    // matter on screen and folds the strangers into "+N".
    const rank = u => {
        const p = profileData[u] || {};
        if (typeof isChatPinned === 'function' && isChatPinned(u)) return 0;
        return p.lastMessageTime ? 1 : 2;
    };
    const last = u => {
        const t = profileData[u] && profileData[u].lastMessageTime;
        return t ? new Date(t).getTime() || 0 : 0;
    };
    return Object.keys(activeSeenAt)
        .filter(u => u && u !== me && u !== 'ANNOUNCEMENTS' && !isUserBlocked(u))
        .sort((a, b) => {
            const r = rank(a) - rank(b);
            if (r) return r;
            if (rank(a) === 1) {
                const t = last(b) - last(a);
                if (t) return t;
            }
            const nameA = (profileData[a] && profileData[a].name) || a;
            const nameB = (profileData[b] && profileData[b].name) || b;
            return nameA.localeCompare(nameB);
        });
}

// At most two rows, however many people are online. The strip wraps rather than
// scrolls (see its CSS), so without a cap a busy evening would push the chat list
// itself off the bottom of the panel. The last slot becomes "+N", which expands
// the row in place; "Less" folds it back.
const ACTIVE_NOW_MAX_ROWS = 2;
const ACTIVE_NOW_ITEM_W = 58;   // .active-now-item width + the strip's column gap
let activeNowExpanded = false;

function activeNowPerRow(strip) {
    // 20px is the strip's own horizontal padding.
    const width = strip.clientWidth || (strip.parentElement && strip.parentElement.clientWidth) || 280;
    return Math.max(3, Math.floor((width - 20 + 2) / ACTIVE_NOW_ITEM_W));
}

function buildActiveNowMoreChip(label, title, onClick) {
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'active-now-item active-now-more';
    chip.title = title;
    chip.innerHTML = `<span class="active-now-avatar"><span class="active-now-more-disc"></span></span>
                      <span class="active-now-name"></span>`;
    chip.querySelector('.active-now-more-disc').textContent = label;
    chip.querySelector('.active-now-name').textContent = label.startsWith('+') ? 'more' : 'less';
    chip.onclick = onClick;
    return chip;
}

// Avatars only resolve for users already in profileData. Someone can be online
// without ever having messaged us, so pull the chat directory once and merge.
function ensureActiveNowProfiles(usernames) {
    // A username can already be in profileData as a bare placeholder -- an
    // incoming socket message seeds { name: <username> } for a stranger -- so
    // "has an entry" isn't the same as "has a real name". Treat a name that is
    // just the username as still missing, or the row shows a lowercase handle
    // next to everyone else's display name.
    const missing = usernames.filter(u => {
        const p = profileData[u];
        return !p || !p.name || p.name === u;
    });
    if (!missing.length || activeNowDirectoryFetched) return;

    activeNowDirectoryFetched = true;
    fetch(`${API_BASE_URL}/api/users/for-chat`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(res => res.json())
    .then(users => {
        (users || []).forEach(user => {
            const existing = profileData[user.username];
            // Merge rather than skip: an existing entry is often the bare
            // placeholder above, and skipping it left that user permanently
            // labelled with their handle. Anything already known wins, except
            // a name that's only the username -- the directory beats that.
            const keepName = existing && existing.name && existing.name !== user.username;
            profileData[user.username] = {
                name: user.fullName,
                ...user,
                ...(existing || {}),
                ...(keepName ? {} : { name: user.fullName || user.username })
            };
        });
        lastActiveNowSignature = ''; // force a repaint now that names exist
        renderActiveNowRow();
    })
    .catch(() => { activeNowDirectoryFetched = false; });
}

function renderActiveNowRow() {
    const row = document.getElementById('active-now-row');
    const strip = document.getElementById('active-now-strip');
    if (!row || !strip) return;

    const users = getActiveNowUsers();

    if (!users.length) {
        row.classList.add('hidden');
        strip.innerHTML = '';
        lastActiveNowSignature = '';
        return;
    }

    ensureActiveNowProfiles(users);

    // Repainting an identical row on every 5s heartbeat would restart the
    // entrance animation. The name is part of the signature because the rest of
    // the profile (avatar, rank ring) lands with it, after the first paint --
    // keying on usernames alone froze whatever was on screen at that moment.
    // How many fit is part of what is on screen, so it is part of the signature:
    // a resize or an expand repaints, an identical heartbeat does not.
    const capacity = activeNowPerRow(strip) * ACTIVE_NOW_MAX_ROWS;
    const overflow = users.length > capacity;
    const shown = overflow && !activeNowExpanded ? users.slice(0, capacity - 1) : users;

    const signature = users.map(u => `${u}:${(profileData[u] || {}).name || ''}`).join('|')
        + `#${capacity}:${activeNowExpanded ? 1 : 0}`;
    if (signature === lastActiveNowSignature) {
        row.classList.remove('hidden');
        return;
    }
    lastActiveNowSignature = signature;

    strip.innerHTML = '';
    shown.forEach(username => {
        const user = profileData[username] || {};
        const label = user.name || username;

        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'active-now-item';
        item.title = `${label} — active now`;
        // .profile-pic doesn't set display, so this has to be a block-level div --
        // as a <span> it stays inline and collapses to a zero-size circle.
        item.innerHTML = `
            <span class="active-now-avatar">
                <div class="profile-pic" data-user-pic-id="${username}"></div>
            </span>
            <span class="active-now-name"></span>
        `;
        // The label is the username, always -- one fixed rule, no dependence on
        // whether a display name has loaded yet. Full name is on the hover title.
        item.querySelector('.active-now-name').textContent = username;
        appendRankIcon(item.querySelector('.active-now-name'), username, user.rank);
        item.onclick = () => openUserPreview(username);

        // applyOnlineStatuses() only paints elements that exist when it runs, so a
        // freshly built item would sit dotless until the next 5s heartbeat.
        if (currentOnlineUsers.includes(username)) {
            item.querySelector('.profile-pic').classList.add('online-user');
        }

        updateProfilePictures(username, item);
        strip.appendChild(item);
    });

    if (overflow) {
        const hidden = users.length - shown.length;
        strip.appendChild(activeNowExpanded
            ? buildActiveNowMoreChip('Less', 'Show fewer', () => {
                activeNowExpanded = false;
                renderActiveNowRow();
            })
            : buildActiveNowMoreChip(`+${hidden}`, `${hidden} more active now`, () => {
                activeNowExpanded = true;
                renderActiveNowRow();
            }));
    }

    row.classList.remove('hidden');
}

// The number that fit per row changes with the panel's width.
window.addEventListener('resize', () => {
    clearTimeout(window._activeNowResizeTimer);
    window._activeNowResizeTimer = setTimeout(renderActiveNowRow, 150);
});

/* --- Profile preview modal ---
   Tapping someone in the row shouldn't yank you off the Messages page: this is
   a quick look plus a one-tap way into the DM. */
function openUserPreview(username) {
    const modal = document.getElementById('user-preview-modal');
    if (!modal || !username) return;

    const cached = profileData[username] || {};
    const picEl = document.getElementById('user-preview-pic');
    const nameEl = document.getElementById('user-preview-name');
    const bioEl = document.getElementById('user-preview-bio');
    const metaEl = document.getElementById('user-preview-meta');
    const statsEl = document.getElementById('user-preview-stats');

    // Paint what we already know first so the card never opens empty.
    picEl.setAttribute('data-user-pic-id', username);
    nameEl.innerHTML = `${cached.name || username} ${rankIconFor(username, cached.rank)}`;
    document.getElementById('user-preview-handle').textContent = `@${username}`;
    bioEl.textContent = '';
    bioEl.style.display = 'none';
    metaEl.innerHTML = '';
    statsEl.classList.add('hidden');
    updateProfilePictures(username);

    document.getElementById('user-preview-message-btn').onclick = () => {
        closeUserPreview();
        if (!messageHistory[username]) messageHistory[username] = [];
        openChat(username);
    };
    document.getElementById('user-preview-profile-btn').onclick = () => {
        closeUserPreview();
        showProfile(username);
    };

    // The card stays hidden until the profile lands, so bio / chips / stats fade
    // in WITH it instead of popping in on top of an already-settled modal.
    let revealed = false;
    const reveal = () => {
        if (revealed) return;
        revealed = true;
        modal.classList.remove('hidden');
        window.addEventListener('keydown', handleUserPreviewEsc);
        syncModalScrollLock();
    };
    // A stalled request must never leave the tap doing nothing visible.
    const revealTimer = setTimeout(reveal, 1200);

    fetch(`${API_BASE_URL}/api/user/${username}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(res => res.json())
    .then(full => {
        if (!full || full.error) return;
        // Still looking at the same person? A fast double-tap could have moved on.
        if (picEl.getAttribute('data-user-pic-id') !== username) return;
        clearTimeout(revealTimer);

        profileData[username] = { ...cached, ...full, name: full.fullName || cached.name };
        profileData[username].profilePicUrl = full.profile_pic;
        updateProfilePictures(username);

        nameEl.innerHTML = `${full.fullName || username} ${rankIconFor(username, full.rank)} ${getAccountTypeTag(full.account_type)}`;

        const bioText = (full.bio || '').replace(/^\/\/rainbow\s+/, '').trim();
        bioEl.textContent = bioText;
        bioEl.style.display = bioText ? 'block' : 'none';

        const chips = [];
        if (full.school) chips.push(full.school);
        // The API hands back grades already prefixed ("G9"), which would read as
        // "Grade G9" if pasted in raw.
        if (full.account_type === 'student' && full.grade) {
            chips.push(`Grade ${String(full.grade).replace(/^G/i, '')}`);
        }
        if (full.account_type === 'teacher' && full.subject) chips.push(full.subject);
        metaEl.innerHTML = chips.map(c => `<span class="user-preview-chip">${c}</span>`).join('');

        if (full.show_social_stats) {
            document.getElementById('user-preview-posts').textContent = full.post_count || 0;
            document.getElementById('user-preview-followers').textContent = full.follower_count || 0;
            document.getElementById('user-preview-following').textContent = full.following_count || 0;
            statsEl.classList.remove('hidden');
        }
    })
    .catch(err => console.error('Failed to load profile preview:', err))
    .finally(reveal);
}

function handleUserPreviewEsc(event) {
    if (event.key === 'Escape') closeUserPreview();
}

function closeUserPreview() {
    const modal = document.getElementById('user-preview-modal');
    if (!modal) return;
    modal.classList.add('hidden');
    window.removeEventListener('keydown', handleUserPreviewEsc);
    syncModalScrollLock();
}

// isBackgroundRefresh: this is a re-pull of a thread the user is ALREADY reading
// (resume, reconnect), not them opening it. The difference is the scroll: opening a
// chat should land you on the "New Messages" divider, but a refresh must not move
// you at all. resyncLiveState() runs on every visibilitychange, so on a phone --
// which backgrounds constantly, every time you glance at another app -- this fired
// over and over, and each one threw the view back to the oldest unread message.
// That is the "flying into older messages" that looks like it comes from nowhere.
function renderActiveChat(isBackgroundRefresh = false) {
    if (!currentChatRecipient) return;

    // --- THIS IS THE FIX: Handle direct links & hard refreshes ---
    // If the user data hasn't loaded yet from fetchConversations(), create a stub.
    if (!profileData[currentChatRecipient]) {
        profileData[currentChatRecipient] = {
            name: currentChatRecipient, // Fallback to username
            username: currentChatRecipient,
            rank: 'user'
        };
        
        // Fetch their real details in the background
        fetch(`${API_BASE_URL}/api/users/details`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
            body: JSON.stringify({ usernames: [currentChatRecipient] })
        })
        .then(r => r.json())
        .then(users => {
            if (users.length > 0) {
                const u = users[0];
                profileData[currentChatRecipient] = { 
                    ...profileData[currentChatRecipient], 
                    name: u.fullName,
                    ...u
                };
                // Update header if they are still on this chat
                if (currentChatRecipient === u.username) {
                    const headerName = document.querySelector('#active-chat-header p');
                    if (headerName) {
                        headerName.textContent = u.fullName;
                        appendRankIcon(headerName, u.username, u.rank);
                    }
                    updateProfilePictures(u.username);
                }
            }
        }).catch(e => console.error(e));
    }

    const user = profileData[currentChatRecipient];
    // --- END OF FIX ---

    oldestDMMessageId = null;
    isChatLoadingMore = false;
    // Not resumable until this render lands (see dmThreadMemory).
    dmThreadMemory.thread = null;
    if (!isBackgroundRefresh) dmThreadMemory.fromBottom = null;
    // "Already handled" for a background refresh, so the divider still draws but
    // nothing scrolls to it. Only a real chat-open earns the jump.
    unreadBarRendered = isBackgroundRefresh;

    // Opening a thread starts you following it. A background refresh must not touch
    // this: the user may well be reading history, and this is not their scroll.
    // (The render itself clears the flag again if it lands on the unread divider
    // instead of the bottom.)
    if (!isBackgroundRefresh) {
        dmStickToBottom = true;
        dmProgrammaticScrollUntil = 0;
    }

    // --- THE FIX: Ensure Mobile UI activates perfectly on a hard reload ---
    const container = document.querySelector('.messages-container');
    if (container) container.classList.add('mobile-chat-active');
    clearKeyboardViewportLock(); // never inherit the last visit's keyboard height
    clearKeyboardViewport();
    // ----------------------------------------------------------------------

    const header = document.getElementById('active-chat-header');
    const chatBody = document.getElementById('chat-body');
    
    // Clear previous handler. Until the full one is installed a second from now,
    // still watch for the user scrolling away from the bottom -- a message arriving
    // inside that window would otherwise drag them back down from history they had
    // already started reading. Assigned (not addEventListener) so the handler below
    // replaces it rather than stacking on top of it, chat open after chat open.
    chatBody.onscroll = () => noteDmScroll(chatBody);

    // FIX: Delay here too
    setTimeout(() => {
        let ticking = false; // The throttle lock
        
        chatBody.onscroll = () => {
            // Outside the rAF throttle on purpose: this is the only place the user
            // gets to say "stop following the conversation", and dropping the frames
            // in between would let a fast flick past the bottom go unnoticed.
            noteDmScroll(chatBody);

            if (!ticking) {
                window.requestAnimationFrame(() => {
                    // All your heavy math goes inside here
                    syncInstagramGradients('chat-body');

                    if (chatBody.scrollTop === 0 && !isChatLoadingMore && oldestDMMessageId) {
                        loadMoreDMs();
                    }
                    if (chatBody.scrollTop + chatBody.clientHeight >= chatBody.scrollHeight - 50) {
                        const bar = document.querySelector('.unread-messages-bar');
                        if (bar) {
                            bar.remove();
                        }
                        currentFirstUnreadId = null;
                    }
                    
                    ticking = false; // Unlock for the next frame
                });
                ticking = true; // Lock it immediately
            }
        };
    }, 1000);

    header.innerHTML = `
        <i class="fas fa-arrow-left mobile-back-btn" onclick="exitMobileChat()"></i> 
        
        <a href="/users/${currentChatRecipient}" class="active-chat-link" onclick="event.preventDefault(); navigateTo('/users/${currentChatRecipient}')">
            <div class="profile-pic" data-user-pic-id="${currentChatRecipient}"></div>
            <p>${user.name}${rankIconFor(currentChatRecipient, user.rank)}</p>
        </a>
        <div id="chat-menu-container" style="margin-left: auto; position: relative;">
            <div id="chat-menu-button" class="profile-menu-button" onclick="toggleChatMenu(event)"><i class="fas fa-ellipsis-h"></i></div>
            <div id="chat-menu-dropdown" class="profile-menu-dropdown hidden">
                <a href="#" class="profile-menu-item" onclick="event.preventDefault(); openSearchSidebar('dm')"><i class="fas fa-search"></i><span>Search</span></a>
                <a href="#" class="profile-menu-item" onclick="event.preventDefault(); openThemeSidebar(event)"><i class="fas fa-palette"></i><span>Customize chat</span></a>
            </div>
        </div>
    `;
    updateProfilePictures(currentChatRecipient);
    // The header was just rebuilt, so its online dot -- and every dot in the list
    // this re-renders -- would sit missing until the next 5s heartbeat repainted
    // them. That gap is the flicker when switching between chats.
    applyOnlineStatuses();
    renderChatList();

    // A background refresh keeps what is on screen; only a real open waits.
    if (!isBackgroundRefresh) showDmBodySkeleton();

    fetch(`${API_BASE_URL}/api/dm/history/${currentChatRecipient}?limit=80`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        const chatBody = document.getElementById('chat-body');
        const placeholder = chatBody.querySelector('div[style*="display:flex"]');
        if (placeholder) placeholder.remove();
        clearDmBodySkeleton();

        if (data.conversation_start) {
            if (!chatBody.querySelector('.chat-context-separator')) {
                const startMarker = document.createElement('div');
                startMarker.className = 'chat-context-separator';
                const startDate = formatDateSeparator(data.conversation_start.timestamp);
                startMarker.textContent = `${data.conversation_start.starter_name} started this chat on ${startDate}`;
                chatBody.appendChild(startMarker);
            }
        }

        const messages = data.messages.map(msg => ({ ...msg, time: new Date(msg.time) }));
        seedMyReactions('dm', messages);
        messageHistory[currentChatRecipient] = messages;
        // This assignment throws the thread away and rebuilds it from the server,
        // which would silently delete any message still queued in the outbox. Put
        // the unsent ones back on the end.
        mergePendingIntoThread(currentChatRecipient);

        if (messages.length > 0) oldestDMMessageId = messages[0].id;

        lastSeenMessageIdByRecipient = data.last_message_read_by_recipient;

        // The server is the single source of truth for the "New Messages" divider.
        // If it returns null, every message from them is read -> no bar, and the
        // scroll logic falls through to the bottom (latest message).
        //
        // The old fallback here set the divider to the OLDEST message in the loaded
        // batch whenever a stale unread badge (window.hasUnreadDM) was set -- which is
        // exactly what threw you into the middle of an old conversation. Removed: a
        // stale badge must never invent an unread position the server didn't report.
        currentFirstUnreadId = data.first_unread_id;
        window.hasUnreadDM = false;

        // This fetch marked every message from them as read on the server (see
        // /api/dm/history). So clear any lingering unread badge for this thread --
        // e.g. one the socket added while the tab was hidden, which the resume-time
        // re-render silently resolved on the server but never reflected in the list.
        // Without this the DM list kept showing a phantom "unread" on a thread whose
        // newest message is your own.
        if (unreadSenders.has(currentChatRecipient)) {
            unreadSenders.delete(currentChatRecipient);
            updateNotificationBadge();
            updatePageTitleCount();
            renderChatList();
        }

        applyChatTheme(data.theme);
        renderChatMessages();

        // The thread on screen is now this recipient's, and complete. The
        // position is read once here as well, since a thread short enough not
        // to scroll never fires the scroll event that normally records it.
        const renderedFor = currentChatRecipient;
        dmThreadMemory.thread = renderedFor;
        requestAnimationFrame(() => {
            const body = document.getElementById('chat-body');
            if (body && currentChatRecipient === renderedFor && body.offsetParent !== null) {
                dmThreadMemory.fromBottom = body.scrollHeight - body.clientHeight - body.scrollTop;
            }
        });
    })
    .catch(error => {
        console.error('Could not load this conversation:', error);
        clearDmBodySkeleton();
        const chatBody = document.getElementById('chat-body');
        if (chatBody && !chatBody.querySelector('.chat-message')) {
            const note = document.createElement('p');
            note.className = 'chat-load-error';
            note.textContent = 'Couldn\u2019t load this conversation. Check your connection.';
            chatBody.appendChild(note);
        }
    });
}

function handleExternalLinkClick(event, url) {
    event.preventDefault();
    event.stopPropagation();
    
    pendingExternalLink = url;
    document.getElementById('external-link-display').textContent = url;
    const modal = document.getElementById('external-link-modal');
    // Last child of <body>, for the same reason as showConfirmationModal(): links
    // are clicked inside other modals (a post in the lightbox, a notice), every
    // .following-modal shares the maximum z-index, and a tie goes to whichever
    // comes later in the DOM -- so the warning opened underneath the modal the
    // link was in.
    if (modal.parentElement !== document.body || modal.nextElementSibling) {
        document.body.appendChild(modal);
    }
    modal.classList.remove('hidden');
}

function closeExternalLinkModal() {
    document.getElementById('external-link-modal').classList.add('hidden');
    pendingExternalLink = null;
}

function proceedToExternalLink() {
    if (pendingExternalLink) {
        window.open(pendingExternalLink, '_blank', 'noopener,noreferrer');
    }
    closeExternalLinkModal();
}

// Ensure the modal closes if clicking the background overlay
document.getElementById('external-link-modal').addEventListener('click', (e) => {
    if (e.target.id === 'external-link-modal') {
        closeExternalLinkModal();
    }
});

function loadMoreDMs() {
    if (isChatLoadingMore || !oldestDMMessageId || !currentChatRecipient) return;
    isChatLoadingMore = true;

    const chatBody = document.getElementById('chat-body');
    const oldScrollHeight = chatBody.scrollHeight; // Store old height

    // Show a temporary loading spinner (optional)
    const spinner = document.createElement('div');
    spinner.className = 'system-message';
    spinner.textContent = 'Loading older messages...';
    spinner.id = 'dm-loading-spinner';
    chatBody.prepend(spinner);

    fetch(`${API_BASE_URL}/api/dm/history/${currentChatRecipient}?limit=80&before_id=${oldestDMMessageId}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(data => {
        const messages = data.messages.map(msg => ({ ...msg, time: new Date(msg.time) }));
        seedMyReactions('dm', messages);

        if (messages.length > 0) {
            // Update the oldest ID for the *next* fetch
            oldestDMMessageId = messages[0].id;
            
            // Prepend new messages to the existing history
            messageHistory[currentChatRecipient].unshift(...messages);
            
            // Re-render, preserving scroll
            renderChatMessages(true, false, oldScrollHeight);
            // --- End Restore ---

        } else {
            // No more messages to load
            oldestDMMessageId = null;
        }
    })
    .catch(error => console.error("Error loading more DMs:", error))
    .finally(() => {
        document.getElementById('dm-loading-spinner')?.remove();
        isChatLoadingMore = false;
    });
}

function prepareSignupForm(type) {
    currentSignupType = type;

    // Get form elements
    const fullNameInput = document.getElementById('signupFullName');
    const usernameInput = document.getElementById('signupUsername');
    const schoolSelect = document.getElementById('signupSchool');
    const emailInput = document.getElementById('signupEmail');
    const passwordInput = document.getElementById('signupPassword');
    const confirmPasswordInput = document.getElementById('signupConfirmPassword');
    const tosCheckbox = document.getElementById('signupTos');
    const privacyCheckbox = document.getElementById('signupPrivacy');
    const guidelinesCheckbox = document.getElementById('signupGuidelines');
    const dobInput = document.getElementById('signupDOB');
    const dobBtn = document.getElementById('dob-display-btn'); // <--- ADD THIS
    const subjectInput = document.getElementById('signupSubject');
    const formTitle = document.getElementById('signup-form-title');

    // --- Clear Fields Block ---
    fullNameInput.value = '';
    usernameInput.value = '';
    schoolSelect.value = '';
    emailInput.value = '';
    passwordInput.value = '';
    confirmPasswordInput.value = '';
    tosCheckbox.checked = false;
    privacyCheckbox.checked = false;
    guidelinesCheckbox.checked = false;
    dobInput.value = '';
    
    // --- ADD THIS: Reset the button UI if they switch tabs ---
    if (dobBtn) {
        dobBtn.innerHTML = '<i class="fas fa-calendar-alt"></i> Select Date of Birth';
    }

    subjectInput.value = '';
    clearAllValidationErrors('signup-page');

    // Drop every green tick from a previous visit, and reset the strength bar.
    document.querySelectorAll('#signup-page .signup-field').forEach(f => f.classList.remove('is-valid'));
    const pwMeter = document.getElementById('signup-pw-meter');
    if (pwMeter) {
        pwMeter.hidden = true;
        pwMeter.dataset.level = '0';
    }

    // Reset dynamic field visibility first. The wrapper is what hides now --
    // hiding the bare input would strand its label and hint on the page.
    const subjectField = document.getElementById('signup-subject-field');
    const dobField = document.getElementById('signup-dob-field');
    if (subjectField) subjectField.style.display = 'none';
    if (dobField) dobField.style.display = 'none';

    // Configure form based on selected type
    if (type === 'student') {
        formTitle.textContent = 'Register as Student';
        fullNameInput.placeholder = 'e.g. Hubert';
        if (dobField) dobField.style.display = '';
    } else if (type === 'teacher') {
        formTitle.textContent = 'Register as Teacher';
        fullNameInput.placeholder = 'e.g. Bartholomew III Jr. The Great';
        if (dobField) dobField.style.display = '';
        if (subjectField) subjectField.style.display = '';
    } else if (type === 'team') {
        formTitle.textContent = 'Register Team Account';
        fullNameInput.placeholder = 'e.g. ECECECEC';
    }

    const signupButton = document.querySelector('#signup-page button[onclick^="handleSignup"]');
    if (signupButton) {
        signupButton.disabled = false;
        signupButton.textContent = 'Register';
    }

    initSignupFormInteractions();

    navigateTo('/signup');
}

function handleSelfDeleteAccount() {
    const myUsername = profileData.me.username;
    
    showConfirmationModal({
        title: 'Delete Your Account?',
        // Add a text input to the modal for confirmation
        // The 180-day window is stated here rather than only in the settings
        // copy, because this modal is the last thing a User reads before the
        // account goes away -- and "you can undo this by signing in" is the
        // single most useful thing they can know at that moment.
        text: `You will be signed out everywhere and your account will be permanently erased in 180 days. Signing in again before then cancels the deletion. Please type your username <strong>${myUsername}</strong> to confirm.`,
        customHtml: `<input type="text" id="delete-confirm-input" class="confirm-delete-input" placeholder="Type your username...">`,
        onConfirm: () => {
            const input = document.getElementById('delete-confirm-input');
            if (input && input.value === myUsername) {
                // Username matches, proceed with deletion
                fetch(`${API_BASE_URL}/api/me/delete`, {
                    method: 'DELETE',
                    headers: { 'Authorization': `Bearer ${apiToken}` }
                })
                .then(response => response.json().then(data => ({ status: response.status, body: data })))
                .then(({ status, body }) => {
                    if (status === 200 && body.ok) {
                        showToast(body.message || 'Account scheduled for deletion.', 'success');
                        handleLogout(); // Log the user out
                    } else {
                        showToast(body.error || 'Could not delete account.', 'error');
                    }
                })
                .catch(err => showToast('An error occurred.', 'error'));
            } else {
                // Username did not match
                showToast('Username did not match. Deletion cancelled.', 'error');
                // We don't close the modal, so they can try again or cancel.
                // Re-show the modal (since it auto-closes)
                handleSelfDeleteAccount();
            }
        }
    });
}

// Upload budget for the base64 string, not the binary. A data URL is ~4/3 the
// size of the bytes it carries, and nginx's default client_max_body_size is 1 MB,
// so anything past this is not "a big upload", it is a failed one. We aim under
// it by stepping quality down rather than by capping dimensions harder: at normal
// photo sizes losing a little WebP quality is far less visible than losing pixels.
const UPLOAD_BUDGET_BYTES = 900 * 1024;
const UPLOAD_QUALITY_LADDER = [0.92, 0.86, 0.80, 0.72];

const readFileAsDataURL = (file) => new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => resolve(e.target.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
});

/**
 * Prepare a picked/pasted/dropped image for upload.
 *
 * The old version resized to 800px and encoded WebP at 0.85 -- and then the
 * server decoded that and re-encoded it AGAIN at q85. Two lossy generations, the
 * second one unable to recover anything the first discarded and only able to
 * smear what survived. On top of that, 800px shown in a ~350pt bubble on a 3x
 * phone is being upscaled by the display, so every softness got magnified.
 *
 * Now: one downscale with a real filter, one encode, at a resolution that still
 * has pixels left after the device scales it. The server recognises an in-bounds
 * WebP and stores those exact bytes instead of re-encoding, so what is on disk is
 * a single generation from the original.
 */
async function processImage(file, maxWidth = 1600) {
    if (!file || !file.type.startsWith('image/')) {
        throw new Error('Not an image file.');
    }

    // Animated formats must never touch a canvas -- drawImage grabs one frame and
    // silently turns a GIF into a still. The server keeps these byte-for-byte.
    if (file.type === 'image/gif') {
        if (file.size <= UPLOAD_BUDGET_BYTES * 0.75) return readFileAsDataURL(file);
        throw new Error('That GIF is too large to send.');
    }

    // decode() on a bitmap beats the old drawImage-into-a-smaller-canvas path:
    // resizeQuality 'high' asks the browser for a proper multi-step filter rather
    // than the near-box sampling it uses when collapsing 4000px to 800 in one go.
    let bitmap;
    try {
        bitmap = await createImageBitmap(file);
    } catch (err) {
        // Safari and older browsers without createImageBitmap(Blob).
        return processImageLegacy(file, maxWidth);
    }

    // Try the full resolution first and only give pixels back if quality alone
    // cannot get under the budget. A very noisy photo (foliage, grain, confetti)
    // is the case that needs this -- it compresses badly at any quality, so past
    // some point trading resolution is the only thing that actually helps.
    let out = null;
    let lastWidth = 0;
    for (const capScale of [1, 0.75, 0.5]) {
        const cap = Math.round(maxWidth * capScale);
        const scale = Math.min(1, cap / Math.max(bitmap.width, bitmap.height));
        const width = Math.max(1, Math.round(bitmap.width * scale));
        const height = Math.max(1, Math.round(bitmap.height * scale));

        // An image already smaller than the cap comes out the same size on the
        // next rung too; re-encoding it identically would just burn time.
        if (width === lastWidth) continue;
        lastWidth = width;

        let source = bitmap;
        if (scale < 1) {
            try {
                source = await createImageBitmap(bitmap, {
                    resizeWidth: width, resizeHeight: height, resizeQuality: 'high'
                });
            } catch (err) { /* fall through to canvas scaling below */ }
        }

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(source, 0, 0, width, height);
        if (source !== bitmap) source.close?.();

        // Walk the quality ladder until it fits. Almost every photo lands on the
        // first rung; only very large or very noisy images ever step down.
        for (const q of UPLOAD_QUALITY_LADDER) {
            out = canvas.toDataURL('image/webp', q);
            // toDataURL falls back to PNG when WebP is unsupported, and a PNG
            // photo is enormous -- no point walking the ladder for it.
            if (!out.startsWith('data:image/webp')) {
                out = canvas.toDataURL('image/jpeg', q);
            }
            if (out.length <= UPLOAD_BUDGET_BYTES) {
                bitmap.close?.();
                return out;
            }
        }
    }
    bitmap.close?.();
    return out;
}

// Pre-createImageBitmap fallback: same single-encode behaviour, older plumbing.
function processImageLegacy(file, maxWidth) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => {
                const scale = Math.min(1, maxWidth / Math.max(img.width, img.height));
                const width = Math.max(1, Math.round(img.width * scale));
                const height = Math.max(1, Math.round(img.height * scale));

                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx.imageSmoothingEnabled = true;
                ctx.imageSmoothingQuality = 'high';
                ctx.drawImage(img, 0, 0, width, height);

                let out = null;
                for (const q of UPLOAD_QUALITY_LADDER) {
                    out = canvas.toDataURL('image/webp', q);
                    if (!out.startsWith('data:image/webp')) {
                        out = canvas.toDataURL('image/jpeg', q);
                    }
                    if (out.length <= UPLOAD_BUDGET_BYTES) break;
                }
                resolve(out);
            };
            img.onerror = reject;
            img.src = e.target.result;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

/**
 * Drag-and-drop image attach, shared by the chat composers and the cover/photo
 * uploaders. `onFile` receives the dropped image; each caller decides what to do
 * with it (the composers run it through processImage, the uploaders read it raw).
 *
 * `dragleave` also fires when the pointer crosses into a CHILD element, so a
 * plain boolean makes the highlight flicker as the file passes over bubbles and
 * buttons. Counting enters and leaves only drops the highlight once the drag has
 * really left the zone.
 */
function initImageDropZone(zone, onFile, options = {}) {
    if (!zone) return;

    const isEnabled = options.isEnabled || (() => true);
    let depth = 0;

    // Only file drags count. Dragging selected text, or an image already on the
    // page, reports other types -- swallowing those would break ordinary
    // selection and the sticker/emoji drags.
    const hasFiles = (e) => Array.from((e.dataTransfer && e.dataTransfer.types) || []).includes('Files');
    const clear = () => { depth = 0; zone.classList.remove('drop-active'); };

    zone.addEventListener('dragenter', (e) => {
        if (!hasFiles(e) || !isEnabled()) return;
        e.preventDefault();
        depth++;
        zone.classList.add('drop-active');
    });

    zone.addEventListener('dragover', (e) => {
        if (!hasFiles(e) || !isEnabled()) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
    });

    zone.addEventListener('dragleave', (e) => {
        if (!hasFiles(e)) return;
        depth--;
        if (depth <= 0) clear();
    });

    // Dragging out of the window entirely fires neither dragleave nor drop in
    // every browser, so the highlight can be left stuck on.
    zone.addEventListener('dragend', clear);

    zone.addEventListener('drop', (e) => {
        if (!hasFiles(e)) return;
        e.preventDefault();
        clear();
        if (!isEnabled()) return;

        const files = Array.from((e.dataTransfer && e.dataTransfer.files) || []);
        // A zone that takes several files (the lounge) sorts them out itself.
        if (options.onFiles) {
            if (files.length) options.onFiles(files);
            return;
        }
        const image = files.find(f => f.type.startsWith('image/'));

        if (!image) {
            if (files.length) showToast('Only image files can be attached.', 'error');
            return;
        }
        // One image per message/post, same as the paperclip picker.
        if (files.length > 1) showToast('Attached the first image.', 'success');

        onFile(image);
    });
}

/**
 * Anywhere that is NOT a drop zone, a dropped file makes the browser navigate to
 * it -- which in an installed PWA throws the whole app away. Swallow those.
 * The zones above call preventDefault() at the target first; this only decides
 * what the browser default does afterwards, so it cannot block them.
 */
['dragover', 'drop'].forEach((evt) => {
    document.addEventListener(evt, (e) => {
        if (Array.from((e.dataTransfer && e.dataTransfer.types) || []).includes('Files')) {
            e.preventDefault();
        }
    });
});

function resetInputState(type) {
    // Clear global contexts
    currentEditContext = { id: null, type: null, originalText: null };
    currentReplyContext = { id: null, type: null, text: null, author: null };

    const typesToReset = (type === 'all') ? ['dm', 'lounge'] : [type];

    typesToReset.forEach(t => {
        const barId = (t === 'dm') ? 'dm-reply-bar' : 'lounge-reply-bar';
        const inputId = (t === 'dm') ? 'main-chat-input-field' : 'lounge-input-field';

        const bar = document.getElementById(barId);
        // Read before the class comes off below: it is what says whose text is in
        // the field.
        const wasEditing = !!(bar && bar.classList.contains('editing'));
        if (bar) {
            bar.classList.add('hidden');
            bar.classList.remove('editing'); // reply and edit share this bar
        }

        // Only an EDIT puts someone else's words in the field -- the message being
        // edited -- so only leaving an edit takes them back out. A reply is a
        // context attached to what the user is typing: dismissing it used to wipe
        // the draft along with it. The send paths clear the field themselves.
        const input = document.getElementById(inputId);
        if (input && wasEditing) {
            input.value = '';
            // --- FIX: Force the textarea to recalculate and shrink its height ---
            if (typeof autoResizeTextarea === 'function') autoResizeTextarea({ target: input });
        }

        setComposerEditMode(t, false);
        updateMobileSendButton(t);
    });
}

// Esc is the universal "get me out of this" on a keyboard, and the composer's
// cancel button covers touch. Without either, edit mode could only be escaped by
// saving something.
document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if (!currentEditContext.type && !currentReplyContext.type) return;
    resetInputState('all');
});

/**
    * Shows the reply UI bar above the chat input.
    * This is the function your reply buttons were trying to call.
    */
/**
 * Shows the reply UI bar above the chat input.
 * Fixed to prevent clearing text when clicking reply.
 */
function showReplyUI(messageId, type, text, authorName) {
    // 1. Identify the input field and SAVE current text
    const inputId = (type === 'dm') ? 'main-chat-input-field' : 'lounge-input-field';
    const inputElement = document.getElementById(inputId);
    // Keep the user's own draft, but not the text of a message they were editing:
    // switching from an edit to a reply would otherwise carry the old message into
    // the reply.
    const barEl = document.getElementById((type === 'dm') ? 'dm-reply-bar' : 'lounge-reply-bar');
    const wasEditing = !!(barEl && barEl.classList.contains('editing'));
    const savedText = (inputElement && !wasEditing) ? inputElement.value : '';

    // 2. Reset any other state (like editing mode), which normally clears text
    resetInputState(type); 
    closeAllPopups(); 

    // 3. Set the global reply context
    currentReplyContext = { id: messageId, type: type, text: text, author: authorName };

    // 4. Find the correct reply bar (DM or Lounge)
    const replyBarId = (type === 'dm') ? 'dm-reply-bar' : 'lounge-reply-bar';
    const replyBar = document.getElementById(replyBarId);
    if (!replyBar) return; 
    
    // 5. Populate and show the bar
    replyBar.innerHTML = `
    <span>Replying to <strong>${authorName}</strong>: "${truncate(text, 40)}"</span>
    <button class="reply-bar-close" onclick="resetInputState('${type}')">&times;</button>
    `;
    replyBar.classList.remove('hidden');
    
    // 6. Focus the input and RESTORE the saved text
    if (inputElement) {
        inputElement.value = savedText;
        inputElement.focus();
    }
}

