let currentStickerContext = null; // Tracks if we are in 'dm' or 'lounge'
let stickerDebounceTimer = null;

// Which popup belongs to which composer. A lookup rather than the two-way
// ternary this used to be, so adding a third composer (notices) does not turn
// every other context into "lounge".
const STICKER_POPUP_IDS = { dm: 'dm-sticker-popup', lounge: 'lounge-sticker-popup', notice: 'notice-sticker-popup' };
const COMPOSER_EMOJI_PANEL_IDS = { dm: 'emoji-panel', lounge: 'lounge-emoji-panel', notice: 'notice-emoji-panel' };

function toggleStickerPanel(context) {
    const stickerPopupId = STICKER_POPUP_IDS[context] || STICKER_POPUP_IDS.lounge;
    const emojiPanelId = COMPOSER_EMOJI_PANEL_IDS[context] || COMPOSER_EMOJI_PANEL_IDS.lounge;
    
    const stickerPopup = document.getElementById(stickerPopupId);
    const emojiPanel = document.getElementById(emojiPanelId);

    if (!stickerPopup) return;

    if (stickerPopup.classList.contains('hidden')) {
        // OPEN: Close Emoji Panel first
        hideComposerPanelEl(emojiPanel);
        
        stickerPopup.classList.remove('hidden');
        // Claims the keyboard's slot, takes the keyboard down, and registers itself
        // with the back button -- in that order.
        showComposerPanel(stickerPopup);
        
        // Render content if empty
        if (!stickerPopup.innerHTML.trim()) {
            stickerPopup.innerHTML = `
                <div class="sticker-panel-container">
                    <div class="sticker-panel-search">
                         <i class="fas fa-search"></i>
                         <input type="search" 
                                placeholder="Search stickers..." 
                                autocomplete="off" 
                                spellcheck="false" 
                                autocorrect="off" 
                                data-lpignore="true" 
                                data-form-type="other" 
                                onkeyup="handleStickerSearch(this.value, '${context}')">
                    </div>
                    <div id="${context}-sticker-grid" class="sticker-panel-grid"></div>
                </div>
            `;
            const input = stickerPopup.querySelector('input');
            // On mobile, don't auto-focus — it forces the on-screen keyboard up
            // the moment the panel opens, which is jarring. Let the user tap the
            // search box themselves if they actually want to search. A hardware
            // keyboard has no such cost, so there it focuses -- see shouldAutoFocus().
            if (input && shouldAutoFocus()) setTimeout(() => input.focus(), 50);
            
            // Load initial list (empty query = all/trending)
            loadStickers('', context);
        }
    } else {
        // CLOSE
        hideComposerPanelEl(stickerPopup);
        syncComposerPanelInset();
    }
}

function openStickersModal(context) {
    currentStickerContext = context;
    const modal = document.getElementById('stickers-modal');
    modal.classList.remove('hidden');
    
    // Focus search and load trending stickers if empty.
    // Skip auto-focus on mobile so the keyboard doesn't pop up on open.
    const searchInput = document.getElementById('sticker-search-input');
    searchInput.value = '';
    if (shouldAutoFocus()) searchInput.focus();
    loadStickers('trending'); // Load default trending stickers
}

function closeStickersModal() {
    document.getElementById('stickers-modal').classList.add('hidden');
    currentStickerContext = null;
}

function handleStickerSearch(query, context) {
    clearTimeout(stickerDebounceTimer);
    stickerDebounceTimer = setTimeout(() => {
        loadStickers(query, context);
    }, 400); // 400ms delay to reduce server load
}


function loadStickers(query, context) {
    const gridId = `${context}-sticker-grid`;
    const grid = document.getElementById(gridId);
    if (!grid) return;

    // Show loading state
    grid.innerHTML = '<p style="padding: 20px; text-align: center; color: #888; width: 100%;">Loading...</p>';

    // Fetch from your new API endpoint
    // If query is empty, the server will return all (or top) stickers
    const endpoint = `/api/stickers?q=${encodeURIComponent(query || '')}`;

    fetch(endpoint, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(stickers => {
        grid.innerHTML = ''; // Clear loading message

        if (!stickers || stickers.length === 0) {
            grid.innerHTML = '<p style="padding: 20px; text-align: center; color: #888; width: 100%;">No stickers found.</p>';
            return;
        }

        stickers.forEach(sticker => {
            const img = document.createElement('img');
            // The list now carries a cacheable image URL, not the Base64 bytes, so
            // loading="lazy" is finally effective and repeat opens hit the cache.
            img.src = sticker.url;
            img.className = 'sticker-panel-item';
            img.loading = "lazy";
            img.onclick = () => sendSticker(sticker.url, context);
            grid.appendChild(img);
        });
    })
    .catch(err => {
        console.error("Error loading stickers:", err);
        grid.innerHTML = '<p style="padding: 20px; text-align: center; color: #e74c3c; width: 100%;">Failed to load.</p>';
    });
}

// The panel deliberately STAYS OPEN. Stickers come in threes -- closing after every
// one meant reopening the picker to send the next, and because closing it used to hand
// focus back to the text field, it also meant the keyboard sliding up over the picker
// you were about to reopen. Sending one sticker changes nothing about the slot: the
// panel keeps it, the keyboard stays down, and nothing on screen moves.
function sendSticker(url, context) {
    if (context === 'notice') {
        // A notice comment carries the sticker's id, not its URL -- the bytes
        // already live in one place and are served cached from there.
        const match = /\/api\/sticker\/(\d+)\/image/.exec(url || '');
        if (!match) {
            showToast('Could not send that sticker.', 'error');
            return;
        }
        postNoticeComment({ sticker_id: Number(match[1]) });
        return;
    }
    if (context === 'dm') {
        dmImagePreviewUrl = url;
        sendMessage();
        dmImagePreviewUrl = null;
    } else {
        loungeImagePreviewUrl = url;
        sendLoungeMessage();
        loungeImagePreviewUrl = null;
    }
}

function selectSticker(url) {
    if (!currentStickerContext) return;

    // We reuse the existing image preview logic to "stage" the sticker
    // This allows the user to see it before sending, or we can send immediately.
    // Let's send immediately for a better "Sticker" feel.

    if (currentStickerContext === 'dm') {
        // Direct Send for DM
        // We temporarily set the global image preview var so sendMessage picks it up
        dmImagePreviewUrl = url; 
        sendMessage(); 
        dmImagePreviewUrl = null; // Reset immediately
    } else if (currentStickerContext === 'lounge') {
        // Direct Send for Lounge
        loungeImagePreviewUrl = url;
        sendLoungeMessage();
        loungeImagePreviewUrl = null;
    }

    closeStickersModal();
}

/**
    * Handles when a user selects an image from the file input.
    */
function handleImageUpload(event) {
    // Images, PDFs and audio, several at once -- see addComposerFiles.
    addComposerFiles('dm', event.target.files);
    event.target.value = null;
}

/**
    * Handles when a user pastes content into the chat input.
    */
function handleImagePaste(event, contextType) {
    const items = event.clipboardData.items;
    if (contextType === 'lounge' || contextType === 'dm') {
        const files = Array.from(items)
            .filter(it => it.kind === 'file' && (it.type.startsWith('image/')
                || it.type === 'application/pdf' || it.type.startsWith('audio/')))
            .map(it => it.getAsFile())
            .filter(Boolean);
        if (files.length) {
            event.preventDefault();
            addComposerFiles(contextType, files);
        }
        return;
    }
    for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf("image") !== -1) {
            const file = items[i].getAsFile();

            // We found an image. Process it and show it in the preview area.
            processImage(file)
                .then(base64Image => {
                    // This now uses your existing preview function for the correct context
                    showImagePreview(base64Image, contextType);
                })
                .catch(err => console.error("Pasted image processing failed:", err));

            event.preventDefault(); // Stop the browser from pasting the raw file object
            return; // Exit after handling the image
        }
    }
}

function updateGeneralNotificationBadge() {
    // 1. Sidebar Badge (Desktop)
    const sidebarBadge = document.getElementById('general-notification-badge');
    if (sidebarBadge) {
        sidebarBadge.style.display = unreadNotificationCount > 0 ? 'block' : 'none';
        sidebarBadge.textContent = unreadNotificationCount > 99 ? '99+' : unreadNotificationCount;
    }

    // 2. Mobile Header Badges (ALL Pages)
    // We use querySelectorAll with attribute syntax to find ALL elements with this ID
    const headerBadges = document.querySelectorAll('[id="header-general-badge"]');
    
    headerBadges.forEach(badge => {
        if (unreadNotificationCount > 0) {
            badge.style.display = 'block';
            badge.textContent = unreadNotificationCount > 99 ? '99+' : unreadNotificationCount;
        } else {
            badge.style.display = 'none';
        }
    });

    updateHomeNavBadge();
}

/**
 * The unread dot on the side-nav Home button.
 *
 * On mobile the DM and bell icons live in the HOME page's header -- the side nav
 * hides its own copies of them. So from any other tab there was nothing at all
 * pointing at a waiting DM or notification: you had to go to Home to find out.
 * Home inherits the dot from both sources.
 *
 * The count is the sum of both sources, matching the numbered badges used
 * everywhere else in the nav.
 */
function updateHomeNavBadge() {
    const badge = document.getElementById('home-notification-badge');
    if (!badge) return;

    const count = unreadSenders.size + unreadNotificationCount + unreadLoungeCount;
    badge.style.display = count > 0 ? 'block' : 'none';
    badge.textContent = count > 99 ? '99+' : count;
}

function showMyLoungesPage() {
    const grid = document.getElementById('my-lounges-grid');
    showPage('my-lounges-page');
    fetchAndRenderLoungeInvites();

    // Fetch the lounges (server now includes 'unread_count')
    fetch(`${API_BASE_URL}/api/me/lounges`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(response => response.json())
    .then(lounges => {
        if (lounges.length === 0) {
            grid.innerHTML = '<p>You are not a member of any lounges yet.</p>';
            return;
        }
        
        grid.innerHTML = ''; // Clear loading text

        applyVirtualScroller('my-lounges-grid', lounges, 'lounges', (lounge) => {
            const card = document.createElement('div');
            card.className = 'circuit-card';
            card.onclick = () => navigateToLounge(lounge.id);
            
            if (loungeCoverUrl(lounge)) {
                card.style.backgroundImage = `url("${loungeCoverUrl(lounge)}")`;
            } else {
                card.classList.add('no-image');
            }

            // --- BADGE LOGIC (PRESERVED) ---
            let badgeHtml = '';
            if (lounge.unread_count > 0) {
                // Show "99+" if there are many unread channels
                const countDisplay = lounge.unread_count > 99 ? '99+' : lounge.unread_count;
                badgeHtml = `<div class="lounge-unread-badge">${countDisplay}</div>`;
            }

            // --- PRIVACY ---
            const privacyIcon = applyLoungePrivacy(card, lounge.privacy);

            card.innerHTML = `
                ${badgeHtml} 
                <h4>${truncate(lounge.name, 10)}</h4>
                <p>${truncate(lounge.description, 15)}</p>
                ${privacyIcon}
            `;
            return card;
        });
    });
}

// ===========================================================================
// My Activity
// ===========================================================================
// One chronological timeline over every kind of activity the platform records,
// paged from /api/me/activity. The page used to render four fixed buckets from
// four fixed keys; it now renders whatever the server sends, so a new activity
// type needs no client change beyond an icon the server already supplies.
//
// Everything below builds DOM nodes and sets user-supplied strings via
// textContent. The previous version interpolated post text straight into
// innerHTML, so a post containing markup ran it on the author's own page.

const MY_ACTIVITY_PAGE_SIZE = 30;

let myActivityState = {
    category: 'all',
    offset: 0,
    hasMore: false,
    loading: false,
    counts: {},
    categories: [],
    lastDateKey: null,   // date separator currently open, so pages stitch together
    requestId: 0,        // guards against a slow response for an abandoned filter
};

function showMyActivityPage() {
    showPage('my-activity-page');
    myActivityState.category = 'all';
    loadMyActivity({ reset: true });
}

function loadMyActivity({ reset = false } = {}) {
    const container = document.getElementById('my-activity-container');
    if (!container) return;

    if (reset) {
        myActivityState.offset = 0;
        myActivityState.lastDateKey = null;
        container.innerHTML = '<div class="activity-chrome"></div>' +
                              '<div class="activity-feed"></div>' +
                              '<div class="activity-footer"><p class="activity-loading">Loading your activity...</p></div>';
    }

    if (myActivityState.loading) return;
    myActivityState.loading = true;
    const reqId = ++myActivityState.requestId;

    const params = new URLSearchParams({
        limit: MY_ACTIVITY_PAGE_SIZE,
        offset: myActivityState.offset,
        category: myActivityState.category,
    });

    fetch(`${API_BASE_URL}/api/me/activity?${params}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => {
        if (!r.ok) throw new Error(`Activity request failed (${r.status})`);
        return r.json();
    })
    .then(data => {
        // A newer filter click already went out; this response is for a view the
        // user has left, and appending it would interleave two categories.
        if (reqId !== myActivityState.requestId) return;

        myActivityState.loading = false;
        myActivityState.hasMore = !!data.has_more;
        myActivityState.offset = data.next_offset || 0;

        if (data.counts) myActivityState.counts = data.counts;
        if (data.categories) myActivityState.categories = data.categories;
        if (reset) renderMyActivityChrome();

        appendMyActivityItems(data.items || [], reset);
        renderMyActivityFooter();
    })
    .catch(err => {
        if (reqId !== myActivityState.requestId) return;
        myActivityState.loading = false;
        console.error('Error loading activity:', err);
        const footer = container.querySelector('.activity-footer');
        if (footer) {
            footer.innerHTML = '';
            const msg = document.createElement('p');
            msg.className = 'activity-empty';
            msg.textContent = "Couldn't load your activity.";
            const retry = document.createElement('button');
            retry.className = 'login-btn activity-more-btn';
            retry.textContent = 'Try again';
            retry.onclick = () => loadMyActivity({ reset: true });
            footer.append(msg, retry);
        }
    });
}

// The totals strip and the filter chips. Both are driven by the counts the
// server sends, so a category with nothing in it never shows up as a dead chip.
function renderMyActivityChrome() {
    const chrome = document.querySelector('#my-activity-container .activity-chrome');
    if (!chrome) return;
    chrome.innerHTML = '';

    const counts = myActivityState.counts || {};
    const total = Object.values(counts).reduce((a, b) => a + b, 0);

    const summary = document.createElement('div');
    summary.className = 'activity-summary';
    const totalTile = document.createElement('div');
    totalTile.className = 'activity-total';
    totalTile.innerHTML = `<span class="activity-total-num"></span><span class="activity-total-label">total actions</span>`;
    totalTile.querySelector('.activity-total-num').textContent = total.toLocaleString();
    summary.appendChild(totalTile);
    chrome.appendChild(summary);

    const chips = document.createElement('div');
    chips.className = 'activity-chips';

    const makeChip = (key, label, count) => {
        const chip = document.createElement('button');
        chip.className = 'activity-chip' + (myActivityState.category === key ? ' active' : '');
        chip.type = 'button';
        const name = document.createElement('span');
        name.textContent = label;
        chip.appendChild(name);
        if (count !== null) {
            const badge = document.createElement('span');
            badge.className = 'activity-chip-count';
            badge.textContent = count;
            chip.appendChild(badge);
        }
        chip.onclick = () => {
            if (myActivityState.category === key) return;
            myActivityState.category = key;
            loadMyActivity({ reset: true });
        };
        return chip;
    };

    chips.appendChild(makeChip('all', 'All', total));
    (myActivityState.categories || []).forEach(c => {
        const n = counts[c.key] || 0;
        if (n > 0) chips.appendChild(makeChip(c.key, c.label, n));
    });
    chrome.appendChild(chips);

    chrome.appendChild(buildDataExportCard());
    refreshDataExportState();
}

// ---------------------------------------------------------------------------
// Personal data export (PIPA right of access)
// ---------------------------------------------------------------------------
// The server builds the archive on a worker, so this is a three-state button:
// idle -> preparing (polling) -> ready (download). The state lives on the
// server, so re-opening the page finds an export that is still being built or
// is already waiting, instead of starting a second one.

const dataExportState = {
    state: 'none',      // none | pending | ready | failed
    token: null,
    size: 0,
    pollTimer: null,
};

const DATA_EXPORT_POLL_MS = 2500;

function buildDataExportCard() {
    const card = document.createElement('div');
    card.className = 'data-export-card';
    card.innerHTML = `
        <div class="data-export-text">
            <span class="data-export-title">Download my data</span>
            <span class="data-export-sub">Get a copy of everything APEX holds about you.</span>
        </div>
        <button type="button" class="data-export-btn"></button>`;
    card.querySelector('.data-export-btn').onclick = onDataExportClick;
    return card;
}

function dataExportEls() {
    return {
        btn: document.querySelector('#my-activity-container .data-export-btn'),
        sub: document.querySelector('#my-activity-container .data-export-sub'),
    };
}

function renderDataExportCard() {
    const { btn, sub } = dataExportEls();
    if (!btn) return;

    btn.disabled = (dataExportState.state === 'pending');
    if (dataExportState.state === 'pending') {
        btn.textContent = 'Preparing…';
        if (sub) sub.textContent = 'We are putting your archive together. This can take a minute.';
    } else if (dataExportState.state === 'ready') {
        const mb = (dataExportState.size || 0) / (1024 * 1024);
        btn.textContent = mb >= 0.05 ? `Download (${mb.toFixed(1)} MB)` : 'Download';
        if (sub) sub.textContent = 'Your archive is ready. The link expires in 24 hours.';
    } else if (dataExportState.state === 'failed') {
        btn.textContent = 'Try again';
        if (sub) sub.textContent = "That export didn't finish. Try once more.";
    } else {
        btn.textContent = 'Request file';
        if (sub) sub.textContent = 'Get a copy of everything APEX holds about you.';
    }
}

function stopDataExportPolling() {
    if (dataExportState.pollTimer) {
        clearTimeout(dataExportState.pollTimer);
        dataExportState.pollTimer = null;
    }
}

function applyDataExportStatus(data) {
    dataExportState.state = data.state || 'none';
    dataExportState.token = data.token || null;
    dataExportState.size = data.size || 0;
    renderDataExportCard();

    if (dataExportState.state === 'pending') {
        // Only ever one timer in flight, so leaving and returning to the page
        // cannot stack up pollers against the same job.
        stopDataExportPolling();
        dataExportState.pollTimer = setTimeout(refreshDataExportState, DATA_EXPORT_POLL_MS);
    } else {
        stopDataExportPolling();
    }
}

function refreshDataExportState() {
    // The card is gone once the user navigates away; stop rather than poll on
    // behalf of a page nobody is looking at.
    if (!dataExportEls().btn) {
        stopDataExportPolling();
        return;
    }
    fetch(`${API_BASE_URL}/api/me/export`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
        .then(r => r.json())
        .then(applyDataExportStatus)
        .catch(() => { /* transient -- the next click or page load retries */ });
}

function onDataExportClick() {
    if (dataExportState.state === 'ready' && dataExportState.token) {
        downloadDataExport(dataExportState.token);
        return;
    }

    dataExportState.state = 'pending';
    renderDataExportCard();

    fetch(`${API_BASE_URL}/api/me/export`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
        .then(async r => {
            const data = await r.json().catch(() => ({}));
            if (r.status === 429) {
                const mins = Math.ceil((data.retry_after || 0) / 60);
                showToast(`You just requested one. Try again in ${mins || 1} min.`, 'error');
                applyDataExportStatus({ state: 'none' });
                return;
            }
            if (!r.ok) {
                showToast('Could not start the export right now.', 'error');
                applyDataExportStatus({ state: 'failed' });
                return;
            }
            applyDataExportStatus({ state: 'pending' });
        })
        .catch(() => {
            showToast('Could not start the export right now.', 'error');
            applyDataExportStatus({ state: 'failed' });
        });
}

// The download needs the auth header, so it cannot be a plain link -- fetch the
// ZIP and hand the browser a blob URL instead.
function downloadDataExport(token) {
    const { btn } = dataExportEls();
    if (btn) { btn.disabled = true; btn.textContent = 'Downloading…'; }

    fetch(`${API_BASE_URL}/api/me/export/download/${token}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
        .then(r => {
            if (!r.ok) throw new Error('expired');
            return r.blob();
        })
        .then(blob => {
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `apex-takeout-${new Date().toISOString().slice(0, 10)}.zip`;
            document.body.appendChild(a);
            a.click();
            a.remove();
            URL.revokeObjectURL(url);
            renderDataExportCard();
        })
        .catch(() => {
            showToast('That download expired. Request a new one.', 'error');
            applyDataExportStatus({ state: 'none' });
        });
}

// Day headings ("Today", "Yesterday", a date, or "Undated" for rows that predate
// their table having a timestamp at all).
function activityDateKey(item) {
    if (!item.timestamp) return 'undated';
    const d = new Date(item.timestamp);
    if (isNaN(d)) return 'undated';
    return d.toISOString().slice(0, 10);
}

function activityDateLabel(key) {
    if (key === 'undated') return 'Undated';
    const d = new Date(key + 'T00:00:00');
    const today = new Date();
    const startOf = x => new Date(x.getFullYear(), x.getMonth(), x.getDate());
    const days = Math.round((startOf(today) - startOf(d)) / 86400000);
    if (days === 0) return 'Today';
    if (days === 1) return 'Yesterday';
    const opts = { weekday: 'short', month: 'short', day: 'numeric' };
    if (d.getFullYear() !== today.getFullYear()) opts.year = 'numeric';
    return d.toLocaleDateString(undefined, opts);
}

function appendMyActivityItems(items, reset) {
    const feed = document.querySelector('#my-activity-container .activity-feed');
    if (!feed) return;
    if (reset) feed.innerHTML = '';

    if (!items.length && reset) {
        const empty = document.createElement('p');
        empty.className = 'activity-empty';
        empty.textContent = myActivityState.category === 'all'
            ? "You haven't done anything on APEX yet. Post something!"
            : 'Nothing here yet.';
        feed.appendChild(empty);
        return;
    }

    const avatarsNeeded = new Set();

    items.forEach(item => {
        const key = activityDateKey(item);
        if (key !== myActivityState.lastDateKey) {
            myActivityState.lastDateKey = key;
            const sep = document.createElement('div');
            sep.className = 'activity-date-sep';
            sep.textContent = activityDateLabel(key);
            feed.appendChild(sep);
        }
        feed.appendChild(buildActivityRow(item, avatarsNeeded));
    });

    if (avatarsNeeded.size) hydrateNotificationAvatars([...avatarsNeeded]);
}

function buildActivityRow(item, avatarsNeeded) {
    const row = document.createElement('div');
    row.className = 'activity-item';
    row.dataset.activityId = item.id;   // stable server-side key, unique per event

    const linkable = item.link && item.link.kind && item.link.kind !== 'none';
    if (linkable) {
        row.classList.add('clickable');
        row.onclick = () => openActivityLink(item.link);
    }

    // The actor's avatar when the action was aimed at someone, the type icon
    // otherwise. Both occupy the same slot so rows stay aligned.
    if (item.actor) {
        const pic = document.createElement('div');
        pic.className = 'profile-pic activity-avatar';
        pic.setAttribute('data-user-pic-id', item.actor);
        row.appendChild(pic);
        const cached = profileData[item.actor];
        if (cached && (cached.profilePicUrl || cached.profile_pic)) {
            updateProfilePictures(item.actor);
        } else {
            avatarsNeeded.add(item.actor);
        }
        const badge = document.createElement('i');
        badge.className = `fas ${item.icon} activity-icon-badge`;
        badge.style.backgroundColor = item.color || 'var(--primary-solid)';
        row.appendChild(badge);
    } else {
        const icon = document.createElement('div');
        icon.className = 'activity-icon';
        icon.style.backgroundColor = item.color || 'var(--primary-solid)';
        icon.innerHTML = `<i class="fas ${item.icon}"></i>`;
        row.appendChild(icon);
    }

    const text = document.createElement('div');
    text.className = 'activity-text';

    const title = document.createElement('p');
    title.className = 'activity-title';
    title.textContent = item.title;
    text.appendChild(title);

    if (item.subtitle) {
        const sub = document.createElement('p');
        sub.className = 'activity-subtitle';
        sub.textContent = item.subtitle;
        text.appendChild(sub);
    }

    if (item.body) {
        const body = document.createElement('p');
        body.className = 'activity-body';
        body.textContent = `"${item.body}"`;
        text.appendChild(body);
    }

    if (item.image) {
        const img = document.createElement('img');
        img.className = 'activity-thumb';
        img.loading = 'lazy';
        img.src = item.image;
        img.onerror = () => img.remove();
        text.appendChild(img);
    }

    const when = document.createElement('span');
    when.className = 'message-timestamp activity-when';
    if (item.timestamp) {
        when.textContent = (item.approx ? '~' : '') + formatTimestamp(new Date(item.timestamp));
        // An approximate time is borrowed from a related row (a reaction has no
        // clock of its own), so say so rather than implying precision.
        if (item.approx) when.title = 'Approximate — taken from the message this refers to';
    } else {
        when.textContent = 'No recorded date';
    }
    text.appendChild(when);

    row.appendChild(text);
    return row;
}

function renderMyActivityFooter() {
    const footer = document.querySelector('#my-activity-container .activity-footer');
    if (!footer) return;
    footer.innerHTML = '';
    if (!myActivityState.hasMore) return;

    const btn = document.createElement('button');
    btn.className = 'login-btn activity-more-btn';
    btn.textContent = 'Load more';
    btn.onclick = () => {
        btn.disabled = true;
        btn.textContent = 'Loading...';
        loadMyActivity();
    };
    footer.appendChild(btn);
}

// Feed entries carry a link descriptor rather than a URL, so the client decides
// how to reach each destination (a post needs its circuit opened first).
function openActivityLink(link) {
    switch (link.kind) {
        case 'post':
            if (link.circuit_code) {
                navigateToPost({
                    circuit_id: link.circuit_id,
                    circuit_code: link.circuit_code,
                    post_id: link.post_id
                });
            } else if (link.post_id) {
                // A profile post, or one whose circuit is gone: its own page.
                navigateTo(`/posts/${link.post_id}`);
            } else {
                showToast('That post no longer exists.', 'error');
            }
            break;
        case 'circuit':
            if (link.circuit_code) navigateTo(`/circuits/${link.circuit_code}`);
            else showToast('That circuit no longer exists.', 'error');
            break;
        case 'lounge':
            if (!link.lounge_id) { showToast('That lounge no longer exists.', 'error'); break; }
            navigateTo(link.channel_id
                ? `/lounges/${link.lounge_id}/${link.channel_id}`
                : `/lounges/${link.lounge_id}`);
            break;
        case 'article':
            navigateTo(`/articles/${link.article_id}`);
            break;
        case 'dm':
            if (link.username) navigateTo(`/messages/${link.username}`);
            break;
        case 'profile':
            if (link.username) showProfile(link.username);
            break;
        default:
            break;
    }
}

function toggleMessageOptions(event, messageId, type, isAuthor, authorId) {
    event.stopPropagation();
    const menuId = `options-dropdown-${type}-${messageId}`;
    const menu = document.getElementById(menuId);
    if (!menu) return;

    const isAlreadyVisible = !menu.classList.contains('hidden');

    // --- Close all other menus ---
    document.querySelectorAll('.message-options-dropdown').forEach(m => {
        if (m.id !== menuId) {
            m.classList.add('hidden');
            m.style.visibility = 'hidden'; 
        }
    });

    // --- If it was already visible, just hide it and stop ---
    if (isAlreadyVisible) {
        menu.classList.add('hidden');
        menu.style.visibility = 'hidden';
        return;
    }

    // --- If it was hidden, build its content ---
    let menuHtml = '';
    const isMod = currentUserLoungeRole === 'owner' || currentUserLoungeRole === 'moderator' || hasPerm('content.message.delete');
    
    menuHtml += `<a onclick="copyMessageText(${messageId}, '${type}')">Copy Message</a>`;

    if (type === 'dm') {
        if (isAuthor) {
            menuHtml += `<a onclick="showEditMessageUI(${messageId}, '${type}')">Edit Message</a>`;
            menuHtml += `<hr class="message-options-divider">`;
            menuHtml += `<a class="danger" onclick="handleDeleteMessage(${messageId}, '${type}')">Delete Message</a>`;
        }
    } else if (type === 'lounge') {
        if (isAuthor) {
            menuHtml += `<a onclick="showEditMessageUI(${messageId}, '${type}')">Edit Message</a>`;
        }
        if (isAuthor || isMod) {
            menuHtml += `<hr class="message-options-divider">`;
            menuHtml += `<a class="danger" onclick="handleDeleteMessage(${messageId}, '${type}')">Delete Message</a>`;
        }
    }
    
    menu.innerHTML = menuHtml;

    // --- ▼▼▼ NEW "POP-UP" POSITIONING LOGIC ▼▼▼ ---
    
    // 1. Get button position & screen margins
    // --- THIS IS THE FIX ---
    // We use event.currentTarget (the button) instead of event.target (the icon)
    const buttonRect = event.currentTarget.getBoundingClientRect();
    // --- END OF FIX ---
    
    const screenEdgeMargin = 10;
    const viewportTop = screenEdgeMargin;
    const viewportBottom = window.innerHeight - screenEdgeMargin;

    // 2. Show the menu (but keep it invisible) so we can measure it
    menu.style.visibility = 'hidden';
    menu.classList.remove('hidden');
    const menuRect = menu.getBoundingClientRect();
    const menuHeight = menuRect.height;
    const menuWidth = menuRect.width;

    // --- Vertical Positioning ---
    let finalTop; // This will be the viewport-relative top
    
    // Calculate potential positions
    const topBelow = buttonRect.bottom + 5;
    const topAbove = buttonRect.top - menuHeight - 5;
    
    // Check if it overflows the BOTTOM
    const overflowsBottom = (topBelow + menuHeight > viewportBottom);
    // Check if it overflows the TOP
    const overflowsTop = (topAbove < viewportTop);

    if (overflowsBottom) {
        if (overflowsTop) {
            // Overflows BOTH: Stick it to the bottom edge (your diagram)
            finalTop = viewportBottom - menuHeight;
        } else {
            // Overflows bottom, but FITS above: Place it above
            finalTop = topAbove;
        }
    } else {
        // Fits below: Place it below (default)
        finalTop = topBelow;
    }

    // Convert to absolute page coordinate and apply
    menu.style.top = `${finalTop + window.scrollY}px`;


    // --- Horizontal Positioning (Same as before, but with menuWidth) ---
    let finalLeft; // Viewport-relative left
    
    const leftAligned = buttonRect.left;
    const rightAligned = buttonRect.right - menuWidth;
    
    // Check for right overflow
    if (leftAligned + menuWidth > (window.innerWidth - screenEdgeMargin)) {
        // It overflows right. Try aligning its right edge.
        finalLeft = rightAligned;
    } else {
        // It fits on the left.
        finalLeft = leftAligned;
    }

    // Check if it *still* overflows the left
    if (finalLeft < screenEdgeMargin) {
        finalLeft = screenEdgeMargin;
    }
    
    // Convert to absolute page coordinate and apply
    menu.style.left = `${finalLeft + window.scrollX}px`;
    menu.style.right = 'auto';

    // 7. Now that it's positioned correctly, make it visible.
    menu.style.visibility = 'visible';
    // --- ▲▲▲ END OF NEW LOGIC ▲▲▲ ---
}

// The "..." (3-dot) menu behind every chat message. It gathers what used to be
// separate inline hover buttons -- the exact send time (to the second), Copy,
// Edit, and Delete -- into one popup. Edit/Delete permissions are UNCHANGED from
// the old inline buttons: DM -> author only; lounge -> author edits, author or
// moderator/admin deletes. The menu is a single shared element reused by every
// message, created lazily so no markup changes are needed.
// Exact send time down to the second, shown in both the desktop 3-dot menu and
// the mobile long-press sheet so they read identically.
function formatExactTimestamp(timestamp) {
    if (!timestamp) return '';
    const d = new Date(timestamp);
    if (isNaN(d)) return '';
    return d.toLocaleString(undefined, {
        year: 'numeric', month: 'short', day: 'numeric',
        hour: 'numeric', minute: '2-digit', second: '2-digit'
    });
}

function openMsgOptionsMenu(event, messageId, type, isAuthor, timestamp) {
    event.stopPropagation();

    let menu = document.getElementById('global-message-options-dropdown');
    if (!menu) {
        menu = document.createElement('div');
        menu.id = 'global-message-options-dropdown';
        menu.className = 'message-options-dropdown hidden';
        document.body.appendChild(menu);
    }

    // Second click on the same message's 3-dot closes the menu.
    const key = `${type}-${messageId}`;
    if (!menu.classList.contains('hidden') && menu.dataset.activeMessageId === key) {
        closeMsgOptionsMenu();
        return;
    }

    const isMod = (currentUserLoungeRole === 'owner' || currentUserLoungeRole === 'moderator' || hasPerm('content.message.delete'));

    // Exact send time, down to the second.
    const timeLabel = formatExactTimestamp(timestamp);

    let menuHtml = '';
    if (timeLabel) {
        menuHtml += `<div class="message-options-time" style="padding:8px 14px;font-size:0.72rem;color:#888;border-bottom:1px solid #eee;white-space:nowrap;cursor:default;">${timeLabel}</div>`;
    }
    menuHtml += `<a onclick="copyMessageText(${messageId}, '${type}'); closeMsgOptionsMenu();"><i class="fas fa-copy" style="margin-right:8px;"></i>Copy Message</a>`;

    if (type === 'dm') {
        if (isAuthor) {
            menuHtml += `<a onclick="showEditMessageUI(${messageId}, '${type}'); closeMsgOptionsMenu();"><i class="fas fa-edit" style="margin-right:8px;"></i>Edit Message</a>`;
            menuHtml += `<hr class="message-options-divider">`;
            menuHtml += `<a class="danger" onclick="handleDeleteMessage(${messageId}, '${type}'); closeMsgOptionsMenu();"><i class="fas fa-trash" style="margin-right:8px;"></i>Delete Message</a>`;
        }
    } else if (type === 'lounge') {
        if (isAuthor) {
            menuHtml += `<a onclick="showEditMessageUI(${messageId}, '${type}'); closeMsgOptionsMenu();"><i class="fas fa-edit" style="margin-right:8px;"></i>Edit Message</a>`;
        }
        // Pinning is a moderator act, never an author one -- the person who wrote
        // a message is the last one who should decide it sits on top of everyone
        // else's channel. The server enforces the same rule; this only decides
        // whether the row is worth drawing.
        if (isMod) {
            const pinned = isMessagePinned(messageId);
            menuHtml += pinned
                ? `<a onclick="setLoungeMessagePinned(${messageId}, false); closeMsgOptionsMenu();"><i class="fas fa-thumbtack" style="margin-right:8px;"></i>Unpin Message</a>`
                : `<a onclick="setLoungeMessagePinned(${messageId}, true); closeMsgOptionsMenu();"><i class="fas fa-thumbtack" style="margin-right:8px;"></i>Pin Message</a>`;
        }
        if (isAuthor || isMod) {
            menuHtml += `<hr class="message-options-divider">`;
            menuHtml += `<a class="danger" onclick="handleDeleteMessage(${messageId}, '${type}'); closeMsgOptionsMenu();"><i class="fas fa-trash" style="margin-right:8px;"></i>Delete Message</a>`;
        }
    }

    menu.innerHTML = menuHtml;
    menu.dataset.activeMessageId = key;

    // --- Viewport-aware positioning (measure hidden, then place) ---
    const buttonRect = event.currentTarget.getBoundingClientRect();
    const screenEdgeMargin = 10;
    menu.style.visibility = 'hidden';
    menu.classList.remove('hidden');
    const menuRect = menu.getBoundingClientRect();
    const menuHeight = menuRect.height;
    const menuWidth = menuRect.width;

    const viewportTop = screenEdgeMargin;
    const viewportBottom = window.innerHeight - screenEdgeMargin;
    const topBelow = buttonRect.bottom + 5;
    const topAbove = buttonRect.top - menuHeight - 5;
    let finalTop;
    if (topBelow + menuHeight > viewportBottom) {
        finalTop = (topAbove < viewportTop) ? (viewportBottom - menuHeight) : topAbove;
    } else {
        finalTop = topBelow;
    }
    menu.style.top = `${finalTop + window.scrollY}px`;

    let finalLeft = buttonRect.right - menuWidth; // right-align to the button
    if (finalLeft < screenEdgeMargin) finalLeft = screenEdgeMargin;
    menu.style.left = `${finalLeft + window.scrollX}px`;
    menu.style.right = 'auto';

    // Hand visibility back to the CSS class so the outside-click close (which only
    // toggles .hidden) fully hides it.
    menu.style.visibility = '';
}

function closeMsgOptionsMenu() {
    const menu = document.getElementById('global-message-options-dropdown');
    if (menu) {
        menu.classList.add('hidden');
        menu.style.visibility = '';
    }
}

function copyMessageText(messageId, type) {
    const textEl = document.getElementById(`message-text-${type}-${messageId}`);
    if (textEl && textEl.textContent) {
        navigator.clipboard.writeText(textEl.textContent)
            .then(() => showToast('Message copied!', 'success'))
            .catch(err => showToast('Failed to copy.', 'error'));
    }
    // Close global menu
    document.getElementById('global-message-options-dropdown')?.classList.add('hidden');
}

/**
    * Replaces the old function.
    * Now just sets the state and moves the text to the main input.
    */
function showEditMessageUI(messageId, type) {
    resetInputState(type);
    closeAllPopups();
    // The mobile long-press sheet is not a ".context-menu", so closeAllPopups()
    // never touched it. It used to survive anyway by accident: this function threw
    // on the two ids below (they do not exist -- the real buttons are
    // #dm-mobile-send-btn / #lounge-mobile-send-btn), which killed the caller
    // before it could close the sheet. Close it here, explicitly.
    closeMobileMessageOptions();

    const textEl = document.getElementById(`message-text-${type}-${messageId}`);
    if (!textEl) return;

    const currentText = textEl.textContent;
    currentEditContext = { id: messageId, type: type, originalText: currentText };

    const inputField = document.getElementById(type === 'dm' ? 'main-chat-input-field' : 'lounge-input-field');
    const bar = document.getElementById(type === 'dm' ? 'dm-reply-bar' : 'lounge-reply-bar');

    // The way OUT of edit mode, on every device: the composer bar says what you are
    // doing and carries the cancel. Reply and edit are mutually exclusive (see
    // resetInputState), so they share the one bar above the input.
    if (bar) {
        bar.innerHTML = `
            <span class="edit-bar-label"><i class="fas fa-pen"></i>Editing message</span>
            <button class="reply-bar-close" type="button" title="Cancel editing (Esc)" aria-label="Cancel editing" onclick="cancelMessageEdit()">&times;</button>
        `;
        bar.classList.add('editing');
        bar.classList.remove('hidden');
    }

    if (inputField) {
        inputField.value = currentText;
        if (typeof autoResizeTextarea === 'function') autoResizeTextarea({ target: inputField });
        inputField.focus();
        // Caret at the end, not the start -- you are almost always fixing the tail.
        try { inputField.setSelectionRange(currentText.length, currentText.length); } catch (e) {}
    }

    // Setting .value in code fires no 'input' event, so the composer never learned
    // it had text and the mobile Send/Save button stayed hidden.
    updateMobileSendButton(type);
    setComposerEditMode(type, true);
}

/**
 * Flips the composer between "send" and "save" presentation.
 */
function setComposerEditMode(type, on) {
    const sendBtn = document.getElementById(type === 'dm' ? 'dm-mobile-send-btn' : 'lounge-mobile-send-btn');
    // An icon button now, so swap the icon rather than the text -- textContent
    // would wipe the <i> out. A check for Save, the paper plane for Send.
    if (sendBtn) {
        sendBtn.innerHTML = on ? '<i class="fas fa-check"></i>' : '<i class="fas fa-paper-plane"></i>';
        sendBtn.setAttribute('aria-label', on ? 'Save' : 'Send');
    }

    const inputField = document.getElementById(type === 'dm' ? 'main-chat-input-field' : 'lounge-input-field');
    const container = inputField ? inputField.closest('.chat-input') : null;
    if (container) container.classList.toggle('composer-editing', !!on);
}

/**
    * Replaces the old function.
    * Now called by the main "Send" buttons when in edit mode.
    */
function saveMessageEdit(messageId, type, inputFieldId) {
    const inputEl = document.getElementById(inputFieldId);
    const newText = inputEl.value.trim();
    if (!newText) {
        showToast('Message cannot be empty.', 'error');
        return;
    }

    // Check if text is unchanged
    if (newText === currentEditContext.originalText) {
        cancelMessageEdit(); // Just cancel if no change
        return;
    }

    const endpoint = (type === 'dm') 
        ? `/api/dm/message/${messageId}/edit` 
        : `/api/lounge/message/${messageId}/edit`;

    fetch(`${API_BASE_URL}${endpoint}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ new_text: newText })
    });
    // The socket event will handle the UI update.
    // We just need to reset the UI.
    cancelMessageEdit(); // This also clears the context and resets the UI
}

/**
    * Replaces the old function.
    * Resets the input bar and clears the edit context.
    */
function cancelMessageEdit() {
    // This now resets both edit and reply states
    resetInputState('all');
}

function handleDeleteMessage(messageId, type) {
    closeAllPopups();
    showConfirmationModal({
        title: 'Delete Message?',
        text: 'Are you sure you want to delete this message? This action is permanent.',
        onConfirm: () => {
            const endpoint = (type === 'dm')
                ? `/api/dm/message/${messageId}`
                : `/api/lounge/message/${messageId}`;
            
            fetch(`${API_BASE_URL}${endpoint}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${apiToken}` }
            });
            // Socket event will handle the UI update
        }
    });
}

function renderPatchNotesList() {
    const list = document.getElementById('patchnotes-list');
    const headerRight = document.getElementById('patchnotes-list-header-right');
    headerRight.innerHTML = ''; // Clear old buttons

    // --- ADD THIS BLOCK ---
    if (hasPerm('content.patchnote.manage')) {
        headerRight.innerHTML = `
            <button class="login-btn" onclick="navigateTo('/patchnotes/new')">Create New</button>
        `;
    }
    // --- END BLOCK ---

    list.innerHTML = '<li>Loading patch notes...</li>';
    fetch(`${API_BASE_URL}/api/patchnotes`)
    .then(response => response.json())
    .then(notes => {
        list.innerHTML = '';
        if (notes.length === 0) {
            list.innerHTML = '<li>No patch notes found.</li>';
            return;
        }
        notes.forEach(note => {
            const item = document.createElement('a');
            item.href = `/patchnotes/${note.version}`;
            item.className = 'notification-item';
            item.style.cursor = 'pointer';
            item.onclick = (e) => {
                e.preventDefault();
                navigateTo(`/patchnotes/${note.version}`);
            };
            item.innerHTML = `
                <div class="notification-text">
                    <p style="font-weight: bold; font-size: 1.1em;">${note.title}</p>
                    <span class="message-timestamp">${formatTimestamp(new Date(note.date))}</span>
                </div>
            `;
            list.appendChild(item);
        });
    });
}


function handleResetAvatar(username) {
    // Close the menu
    document.getElementById('profile-menu-dropdown').classList.add('hidden');

    showConfirmationModal({
        title: 'Reset Avatar?',
        text: `Are you sure you want to reset @${username}'s profile picture to the default avatar?`,
        onConfirm: () => {
            fetch(`${API_BASE_URL}/api/user/${username}/avatar`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${apiToken}` }
            })
            .then(response => response.json().then(data => ({ status: response.status, body: data })))
            .then(({ status, body }) => {
                if (status === 200 && body.ok) {
                    showToast(body.message, 'success');
                    
                    // Update local data so the UI refreshes
                    if (profileData[username]) {
                        profileData[username].profilePicUrl = null;
                        profileData[username].profile_pic = null;
                    }
                    
                    // Re-render the profile page to show the change
                    showProfile(username);
                } else {
                    showToast(body.error || 'Could not reset avatar.', 'error');
                }
            })
            .catch(err => showToast('An error occurred.', 'error'));
        }
    });
}
/**
    * Fetches and displays the content for a single patch note.
    */
function showPatchNoteDetail(version) {
    const titleEl = document.getElementById('patchnote-detail-title');
    const contentEl = document.getElementById('patchnote-detail-content');
    const headerRight = document.getElementById('patchnote-detail-header-right');
    headerRight.innerHTML = ''; // Clear old buttons

    // --- ADD THIS BLOCK ---
    if (hasPerm('content.patchnote.manage')) {
        headerRight.innerHTML = `
            <button class="admin-btn-danger" style="background: #e74c3c; color: white;" onclick="handleDeletePatchNote('${version}')">Delete</button>
            <button class="login-btn" onclick="navigateTo('/patchnotes/${version}/edit')">Edit</button>
        `;
    }
    // --- END BLOCK ---

    titleEl.textContent = 'Loading...';
    showPage('patchnote-detail-page');

    fetch(`${API_BASE_URL}/api/patchnotes/${version}`)
    .then(response => response.json())
    .then(note => {
        if (note.error) {
            titleEl.textContent = 'Error';
            contentEl.innerHTML = `<p style="color: red;">${note.error}</p>`;
            return;
        }

        titleEl.textContent = `Version ${note.version}`;
        contentEl.innerHTML = `
            <h1 style="font-size: 1.8em; margin-bottom: 5px;">${note.title}</h1>
            <p style="color: #888; margin-top: 0;">Released: ${new Date(note.date).toLocaleDateString()}</p>
            <hr>
            ${note.content_html}
        `;
    });
}
// ===========================================================================
// Profile posts
// ===========================================================================
// The payoff for following someone. The profile used to show a post *count* and
// nothing else, so there was no way anywhere in the app to see what a person had
// actually made -- which made following them a no-op.
//
// Pages load lazily: an IntersectionObserver watches a sentinel under the grid and
// pulls the next page as you reach it. This is not the infinite feed the rest of
// the app avoids -- it is one person's finite body of work, so it terminates on
// its own and the observer disconnects when there is nothing left. Nothing is
// injected to keep you scrolling.
//
// The "Show more posts" button survives as the fallback path: browsers with no
// IntersectionObserver, and any page whose fetch failed.
const PROFILE_POSTS_PAGE = 12;

// How far below the fold to start fetching, so the next page is usually already
// there by the time the last card clears the viewport.
const PROFILE_POSTS_PREFETCH_PX = 600;
const PROFILE_POSTS_PREFETCH_MARGIN = `${PROFILE_POSTS_PREFETCH_PX}px`;

let profilePostsObserver = null;
let profilePostsScrollHandler = null;
// True while either trigger is armed. The fallback button keys off this, not off
// the observer, so it appears whenever auto-load is genuinely off.
let profilePostsAutoLoad = false;

let profilePostsState = {
    username: null,
    offset: 0,
    hasMore: false,
    loading: false,
    requestId: 0,   // a slow response for a profile you've already left is dropped
    posts: [],      // accumulates across pages; this is what the post modal pages through
};

// --- Profile section tabs: Posts / Resume / Tagged ----------------------------
//
// One panel visible at a time. The three used to stack down the page, which put a
// long resume between the reader and the posts, and left nowhere to hang a fourth
// thing. Switching is purely local -- no navigation, no history entry -- because
// these are three views of the profile you are already on, not three places.
const PROFILE_TABS = ['posts', 'resume', 'tagged'];

let currentProfileTab = 'posts';

function switchProfileTab(tab) {
    if (!PROFILE_TABS.includes(tab)) return;
    currentProfileTab = tab;

    PROFILE_TABS.forEach(name => {
        const btn = document.getElementById(`profile-tab-${name}`);
        const panel = document.getElementById(`profile-panel-${name}`);
        const on = name === tab;
        if (btn) {
            btn.classList.toggle('active', on);
            btn.setAttribute('aria-selected', on ? 'true' : 'false');
        }
        if (panel) panel.classList.toggle('hidden', !on);
    });

    // Fetched the first time the tab is actually opened, not on every profile
    // view: most visits never leave the Posts tab, and a tagged query is a text
    // scan rather than an indexed lookup.
    if (tab === 'tagged') loadTaggedPostsIfNeeded();

    // The posts feed pages off a sentinel's position, and a hidden panel reports
    // a zero-sized one -- so coming back to Posts has to re-ask, or paging stays
    // stalled wherever it was when the tab was left.
    if (tab === 'posts') {
        const isMe = profilePostsState.username === profileData.me.username;
        requestAnimationFrame(() => maybeLoadMoreProfilePosts(isMe));
    }
}

// Every profile opens on Posts. Without this you would land on whatever tab you
// happened to leave the last person's profile on, looking at an empty Tagged
// panel that hasn't been told whose it is yet.
function resetProfileTabs() {
    switchProfileTab('posts');
}

// --- Tagged: posts by other people that @-mention this profile ----------------
//
// Deliberately NOT the posts feed's auto-loading sentinel. Being tagged is a
// finite, browsable list, and an explicit button keeps it something you finish.
const TAGGED_POSTS_PAGE = 12;

let taggedPostsState = {
    username: null,
    offset: 0,
    hasMore: false,
    loading: false,
    loaded: false,   // false until the tab has been opened once for this profile
    requestId: 0,
    posts: [],       // what the post modal pages through while the tab is open
};

function resetTaggedPosts(username) {
    taggedPostsState = {
        username,
        offset: 0,
        hasMore: false,
        loading: false,
        loaded: false,
        requestId: taggedPostsState.requestId + 1,
        posts: [],
    };

    const grid = document.getElementById('profile-tagged-grid');
    const empty = document.getElementById('profile-tagged-empty');
    const moreBtn = document.getElementById('profile-tagged-more');
    const heading = document.getElementById('profile-tagged-heading');
    if (grid) masonryReset(grid);
    if (empty) empty.style.display = 'none';
    if (moreBtn) moreBtn.style.display = 'none';
    if (heading) heading.textContent = 'Tagged';

    // Same delegated handler as the other grids, so likes, author links and the
    // post modal behave identically here.
    if (grid) {
        grid.removeEventListener('click', handleGridClick);
        grid.addEventListener('click', handleGridClick);
        attachGridLongPress(grid);
    }

    // If the reader is already sitting on the Tagged tab when they move to
    // another profile, the panel is on screen and empty -- fill it rather than
    // waiting for a tab switch that has already happened.
    if (currentProfileTab === 'tagged') loadTaggedPostsIfNeeded();
}

function loadTaggedPostsIfNeeded() {
    if (!taggedPostsState.username || taggedPostsState.loaded) return;
    taggedPostsState.loaded = true;
    fetchTaggedPostsPage();
}

function loadMoreTaggedPosts() {
    fetchTaggedPostsPage();
}

function fetchTaggedPostsPage() {
    const state = taggedPostsState;
    if (state.loading || !state.username) return;

    const grid = document.getElementById('profile-tagged-grid');
    const empty = document.getElementById('profile-tagged-empty');
    const moreBtn = document.getElementById('profile-tagged-more');
    const heading = document.getElementById('profile-tagged-heading');
    const spinner = document.getElementById('profile-tagged-spinner');
    if (!grid) return;

    const isMe = state.username === profileData.me.username;

    state.loading = true;
    const myRequest = state.requestId;
    if (moreBtn) moreBtn.disabled = true;
    // The first page shows where the posts will be; later ones say "loading more".
    const firstPage = state.offset === 0;
    if (firstPage) renderCircuitSkeleton(grid);
    else if (spinner) spinner.style.display = '';

    fetch(`${API_BASE_URL}/api/user/${state.username}/tagged?limit=${TAGGED_POSTS_PAGE}&offset=${state.offset}`,
          { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(r => r.json())
    .then(data => {
        // Navigated away, or switched profiles, while this was in flight.
        if (myRequest !== taggedPostsState.requestId) return;

        const posts = data.posts || [];
        if (firstPage) masonryReset(grid);   // the skeleton makes way
        // Collected and placed in one go: the masonry packs a batch against a
        // single layout flush, where card-at-a-time would force one apiece.
        const cards = posts.map(post => {
            // Push before building: the card's data-post-index addresses this
            // array and has to match where the post actually landed.
            const index = state.posts.push(post) - 1;
            return buildProfilePostCard(post, index);
        });
        masonryAppend(grid, cards);

        state.offset += posts.length;
        state.hasMore = !!data.has_more;
        state.loading = false;

        if (spinner) spinner.style.display = 'none';
        if (moreBtn) {
            moreBtn.disabled = false;
            moreBtn.textContent = 'Show more';   // may have been left as "Retry"
            moreBtn.style.display = state.hasMore ? '' : 'none';
        }

        if (!state.posts.length) {
            empty.textContent = isMe
                ? 'Nobody has tagged you in a post yet. Posts that @ you show up here.'
                : 'No tagged posts yet.';
            empty.style.display = '';
        } else {
            empty.style.display = 'none';
            if (heading) heading.textContent = `Tagged${data.total ? ` (${data.total})` : ''}`;
        }

        // A different author on every row here, so their avatars have to be
        // resolved by hand -- the Posts tab gets this for free by resolving the
        // one profile it is already showing.
        [...new Set(posts.map(item => item.author && item.author.username).filter(Boolean))]
            .forEach(u => updateProfilePictures(u));
        verifyMentions();
    })
    .catch(err => {
        if (myRequest !== taggedPostsState.requestId) return;
        console.error('Error loading tagged posts:', err);
        state.loading = false;
        if (spinner) spinner.style.display = 'none';
        if (moreBtn) {
            moreBtn.disabled = false;
            moreBtn.textContent = 'Retry';
            moreBtn.style.display = '';
        }
        if (!state.posts.length) {
            masonryReset(grid);
            empty.textContent = 'Could not load tagged posts.';
            empty.style.display = '';
            // Nothing landed, so the tab has not really been loaded -- let
            // reopening it try again instead of leaving a permanent error.
            state.loaded = false;
        }
    });
}

function loadProfilePosts(username, isMe) {
    const grid = document.getElementById('profile-posts-grid');
    const empty = document.getElementById('profile-posts-empty');
    const moreBtn = document.getElementById('profile-posts-more');
    const heading = document.getElementById('profile-posts-heading');
    if (!grid || !username) return;

    profilePostsState = {
        username,
        offset: 0,
        hasMore: false,
        loading: false,
        requestId: profilePostsState.requestId + 1,
        posts: [],
    };

    // Grey cards where the posts will be, from the first frame -- the same
    // shimmering skeleton a circuit shows. Replaced when the first page lands.
    renderCircuitSkeleton(grid);
    empty.style.display = 'none';
    moreBtn.style.display = 'none';
    heading.textContent = isMe ? 'Your posts' : 'Posts';
    const newPostBtn = document.getElementById('profile-new-post');
    if (newPostBtn) newPostBtn.hidden = !isMe;

    // Both feeds are keyed to the same profile, and this is the one call that
    // reliably has the real handle: on a hard reload at /users/me the alias is
    // not resolved until the profile response lands.
    resetTaggedPosts(username);

    // Same delegated handler the circuit grid uses, so likes, author links,
    // @mentions and the post modal all behave identically here.
    grid.removeEventListener('click', handleGridClick);
    grid.addEventListener('click', handleGridClick);
    attachGridLongPress(grid);

    startProfilePostsObserver(isMe);
    fetchProfilePostsPage(isMe);
}

function loadMoreProfilePosts() {
    const isMe = profilePostsState.username === profileData.me.username;
    fetchProfilePostsPage(isMe);
}

// Watches the sentinel under the grid. Torn down and rebuilt per profile so a
// stale observer can never append one person's posts under another's.
function startProfilePostsObserver(isMe) {
    stopProfilePostsObserver();

    const sentinel = document.getElementById('profile-posts-sentinel');
    if (!sentinel) return;

    // Two independent triggers, because the button that used to be the only way
    // to page is now hidden while auto-load is on -- if the trigger silently
    // fails there is no way left to reach the rest of someone's posts.
    //
    //   1. IntersectionObserver, the cheap path: no work at all while scrolling.
    //   2. A passive scroll listener doing the same rect check, as a backstop for
    //      any environment where the observer never delivers (it needs a live
    //      rendering pipeline, so a backgrounded or non-compositing page can stop
    //      firing it entirely).
    // Both funnel into the same guarded fetch, so a double trigger is a no-op.
    profilePostsAutoLoad = true;

    if (typeof IntersectionObserver !== 'undefined') {
        profilePostsObserver = new IntersectionObserver((entries) => {
            if (!entries.some(e => e.isIntersecting)) return;
            maybeLoadMoreProfilePosts(isMe);
        }, { rootMargin: PROFILE_POSTS_PREFETCH_MARGIN });
        profilePostsObserver.observe(sentinel);
    }

    // rAF-coalesced: scroll fires far more often than layout actually changes.
    let queued = false;
    profilePostsScrollHandler = () => {
        if (queued) return;
        queued = true;
        requestAnimationFrame(() => {
            queued = false;
            maybeLoadMoreProfilePosts(isMe);
        });
    };
    window.addEventListener('scroll', profilePostsScrollHandler, { passive: true });
    window.addEventListener('resize', profilePostsScrollHandler, { passive: true });
}

// The single guarded entry point for "should another page load right now?".
// Also the self-priming step after a page lands: if that page didn't fill the
// viewport the sentinel never left it, so no new scroll or intersection event is
// coming and paging would stall here.
function maybeLoadMoreProfilePosts(isMe) {
    if (!profilePostsAutoLoad) return;
    if (profilePostsState.loading || !profilePostsState.hasMore) return;

    const sentinel = document.getElementById('profile-posts-sentinel');
    if (!sentinel) return;

    const rect = sentinel.getBoundingClientRect();
    // Zero on both axes means the profile page is hidden entirely.
    if (!rect.width && !rect.height) return;
    if (rect.top > window.innerHeight + PROFILE_POSTS_PREFETCH_PX) return;

    fetchProfilePostsPage(isMe);
}

function stopProfilePostsObserver() {
    profilePostsAutoLoad = false;
    if (profilePostsObserver) {
        profilePostsObserver.disconnect();
        profilePostsObserver = null;
    }
    if (profilePostsScrollHandler) {
        window.removeEventListener('scroll', profilePostsScrollHandler);
        window.removeEventListener('resize', profilePostsScrollHandler);
        profilePostsScrollHandler = null;
    }
}

function fetchProfilePostsPage(isMe) {
    const state = profilePostsState;
    if (state.loading || !state.username) return;

    const grid = document.getElementById('profile-posts-grid');
    const empty = document.getElementById('profile-posts-empty');
    const moreBtn = document.getElementById('profile-posts-more');
    const heading = document.getElementById('profile-posts-heading');

    const spinner = document.getElementById('profile-posts-spinner');

    state.loading = true;
    const myRequest = state.requestId;
    moreBtn.disabled = true;
    // Only announce a load that has something to append to; the very first page
    // arrives under the section heading and needs no "loading more".
    if (spinner && state.offset > 0) spinner.style.display = '';

    fetch(`${API_BASE_URL}/api/user/${state.username}/posts?limit=${PROFILE_POSTS_PAGE}&offset=${state.offset}`,
          { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(r => r.json())
    .then(data => {
        // Navigated away, or switched profiles, while this was in flight.
        if (myRequest !== profilePostsState.requestId) return;

        const posts = data.posts || [];
        // The first page takes the skeleton's place rather than landing under it.
        if (state.offset === 0) masonryReset(grid);
        // Collected and placed in one go: the masonry packs a batch against a
        // single layout flush, where card-at-a-time would force one apiece.
        const cards = posts.map(post => {
            // The card's data-post-index addresses this array, so push before
            // building: the index has to match where the post actually landed.
            const index = state.posts.push(post) - 1;
            return buildProfilePostCard(post, index);
        });
        masonryAppend(grid, cards);

        state.offset += posts.length;
        state.hasMore = !!data.has_more;
        state.loading = false;

        if (spinner) spinner.style.display = 'none';
        moreBtn.disabled = false;
        moreBtn.textContent = 'Show more posts';   // may have been left as "Retry"

        // A page that failed earlier disarmed auto-load and put the user on the
        // button. This one succeeded, so the network is back: re-arm rather than
        // leaving them tapping for the rest of the profile.
        if (state.hasMore && !profilePostsAutoLoad) startProfilePostsObserver(isMe);

        // The button is only the fallback -- it shows when there is more to load
        // but nothing is armed to fetch it automatically.
        moreBtn.style.display = (state.hasMore && !profilePostsAutoLoad) ? '' : 'none';

        if (!state.hasMore) {
            stopProfilePostsObserver();   // nothing left to watch for
        } else {
            requestAnimationFrame(() => {
                if (myRequest !== profilePostsState.requestId) return;  // profile changed
                maybeLoadMoreProfilePosts(isMe);
            });
        }

        if (state.offset === 0) {
            // An empty state that points somewhere. "No posts" on its own is a
            // dead end, and a new student's whole first session is made of these.
            empty.innerHTML = isMe
                ? `No posts yet. <a href="#" onclick="event.preventDefault(); openProfileComposer()">Share your first post</a>, or <a href="#" onclick="event.preventDefault(); navigateTo('/circuits')">find a circuit</a> to post in.`
                : 'No posts yet.';
            empty.style.display = '';
        } else {
            empty.style.display = 'none';
            if (heading) {
                heading.textContent = (isMe ? 'Your posts' : 'Posts')
                    + (data.total ? ` (${data.total})` : '');
            }
        }
    })
    .catch(err => {
        if (myRequest !== profilePostsState.requestId) return;
        console.error("Error loading profile posts:", err);
        state.loading = false;
        if (spinner) spinner.style.display = 'none';
        moreBtn.disabled = false;
        // Hand control back to the user rather than letting the observer retry the
        // same failing request every time the sentinel scrolls into view.
        if (state.offset > 0 && state.hasMore) {
            stopProfilePostsObserver();
            moreBtn.textContent = 'Retry loading posts';
            moreBtn.style.display = '';
        }
        if (profilePostsState.offset === 0) {
            masonryReset(grid);   // no shimmering boxes over an error
            empty.textContent = 'Could not load posts.';
            empty.style.display = '';
        }
    });
}

// The same .circuit-post card a circuit renders -- same class, same element order,
// so it inherits the real style instead of a second look-alike that has to be kept
// in sync by hand. Clicks are handled by handleGridClick, which the grid shares
// with the circuit page.
//
// Two additions over the circuit card: the menu button carries the post's own
// circuit code (a profile has no currentCircuitDetails to fall back on), and a
// chip under the text opens the post inside the circuit it lives in.
// The card carries its author line and circuit chip on every surface. The
// phone hides both on the Posts tab in CSS rather than here, because that is a
// question about how much room there is -- three columns on a handset -- not
// about the post, and a card built without them would still be missing them
// after the tablet was turned round.
function buildProfilePostCard(post, index) {
    const authorUsername = post.author?.username || 'unknown';
    const authorFullName = post.author?.fullName || authorUsername;
    const circuitCode = post.circuit?.code || '';

    const postEl = document.createElement('div');
    postEl.className = 'circuit-post';
    postEl.dataset.postIndex = index;   // read by handleGridClick to open the modal

    const imageHTML = postImageHTML(post);

    postEl.innerHTML = `
        <div class="circuit-post-menu-button" data-post-id="${post.id}" data-author-id="${post.author_id}" data-circuit-code="${circuitCode}">
            <i class="fas fa-ellipsis-h"></i>
        </div>
        <div id="circuit-post-menu-${post.id}" class="circuit-post-menu-dropdown hidden"></div>
        ${imageHTML}
        ${post.text ? `<p class="circuit-post-text">${linkifyUsernames(post.text)}</p>` : ''}
        ${circuitCode ? `<a href="#" class="circuit-post-circuit-link" data-circuit-code="${circuitCode}" data-post-id="${post.id}">
            <i class="fas fa-layer-group"></i> <span></span>
        </a>` : ''}
        ${postActionsHTML(post)}
        <div class="circuit-post-author">
            <a href="#" class="circuit-post-author-link" data-username="${authorUsername}">
                <span></span>
                <div class="profile-pic" data-user-pic-id="${authorUsername}"></div>
            </a>
        </div>
    `;

    // A poll is NAMED here, not drawn. On a circuit the poll card is the post,
    // but a profile grid is three narrow columns of everything a person has
    // ever posted -- a full poll card in one of them costs more height than the
    // post it belongs to and is unreadable at that width anyway. The chip says
    // there is one, and the card opens to the poll you can actually vote in.
    if (post.poll) {
        const chip = document.createElement('div');
        chip.className = 'post-poll-chip';
        chip.innerHTML = '<i class="fas fa-square-poll-vertical"></i>';
        const label = document.createElement('span');
        label.textContent = post.poll.isClosed ? 'Poll · closed' : 'Poll';
        chip.appendChild(label);
        postEl.insertBefore(chip, postEl.querySelector('.like-button-container'));
    }

    // textContent, not interpolation -- a display name is raw user input.
    const authorSpan = postEl.querySelector('.circuit-post-author-link span');
    if (authorSpan) {
        authorSpan.textContent = `- ${authorFullName}`;
        appendRankIcon(authorSpan, authorUsername, post.author?.rank);
        // The card clamps long names to one line; the title keeps the whole
        // thing reachable instead of just losing the tail.
        authorSpan.title = authorFullName;
    }

    // textContent for the same reason: the title is user input.
    const circuitSpan = postEl.querySelector('.circuit-post-circuit-link span');
    if (circuitSpan && post.circuit) circuitSpan.textContent = post.circuit.title;

    if (post.author) {
        profileData[authorUsername] = {
            ...(profileData[authorUsername] || {}),
            name: post.author.fullName,
            username: authorUsername,
            rank: post.author.rank,
            profilePicUrl: post.author.profilePic,
            account_type: post.author.account_type,
        };
        updateProfilePictures(authorUsername, postEl);
    }

    return postEl;
}


// ===========================================================================
// Hashtag page (/tags/<tag>)
// ===========================================================================
// A tag is the one piece of search on APEX that its own users write, so it gets
// an address rather than being a filter somebody has to reconstruct. Cards are
// built by buildProfilePostCard and laid out by the same masonry as a profile,
// so a post looks and behaves identically here: likes, the 3-dot menu, the
// magnified modal, all of it, without a second card builder to keep in step.
const HASHTAG_PAGE_SIZE = 24;

let hashtagState = { tag: null, offset: 0, hasMore: false, loading: false, requestId: 0, posts: [] };

// The click target every rendered '#' carries. Kept separate from navigateTo so
// the tap works the same whether the tag was inside a grid card (where the card
// itself is a click target and would otherwise magnify the post) or in a modal
// (which has to come down before the page behind it changes).
function openHashtag(event, tag) {
    const key = normalizeHashtag(tag);
    if (!key) return;
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }
    const path = `/tags/${encodeURIComponent(key)}`;

    // Inside a modal, the tap has to bring the modal down and REPLACE its
    // history entry -- otherwise the lightbox stays parked over the tag page it
    // just opened, and Back re-opens it. navigateFromModal falls through to a
    // plain navigateTo for anything that is not in a modal, so this is the one
    // path for every surface a '#' can be rendered on: a card, a lightbox, the
    // post's own page, a chip, a row of the search dropdown.
    const from = event && (event.currentTarget || event.target);
    if (from && from.nodeType === 1) {
        navigateFromModal(from, path);
        return;
    }
    navigateTo(path);
}

function showHashtagPage(tag) {
    const key = normalizeHashtag(tag);
    const grid = document.getElementById('hashtag-grid');
    if (!grid) return;
    if (!key) {
        showPage('not-found-page');
        return;
    }

    hashtagState = {
        tag: key,
        offset: 0,
        hasMore: false,
        loading: false,
        requestId: hashtagState.requestId + 1,
        posts: [],
    };

    showPage('hashtag-page');
    setPageTitle(`#${key}`);
    document.getElementById('hashtag-header-title').textContent = `#${key}`;
    document.getElementById('hashtag-title').textContent = `#${key}`;
    document.getElementById('hashtag-count').textContent = 'Loading…';
    document.getElementById('hashtag-empty').style.display = 'none';
    document.getElementById('hashtag-more').style.display = 'none';
    const related = document.getElementById('hashtag-related');
    related.hidden = true;
    document.getElementById('hashtag-related-chips').innerHTML = '';

    // Grey post cards until the first page arrives (fetchHashtagPage clears them).
    renderCircuitSkeleton(grid);

    // The same delegated handler the circuit and profile grids use, so likes,
    // author links, @mentions, the post menu and the modal all behave here
    // exactly as they do everywhere else.
    grid.removeEventListener('click', handleGridClick);
    grid.addEventListener('click', handleGridClick);
    attachGridLongPress(grid);

    fetchHashtagPage();
}

function loadMoreHashtagPosts() {
    fetchHashtagPage();
}

function fetchHashtagPage() {
    const state = hashtagState;
    if (state.loading || !state.tag) return;

    const grid = document.getElementById('hashtag-grid');
    const empty = document.getElementById('hashtag-empty');
    const moreBtn = document.getElementById('hashtag-more');
    const countEl = document.getElementById('hashtag-count');

    state.loading = true;
    const myRequest = state.requestId;
    moreBtn.disabled = true;
    moreBtn.textContent = state.offset ? 'Loading…' : 'Load more';

    fetch(`${API_BASE_URL}/api/tags/${encodeURIComponent(state.tag)}/posts`
          + `?limit=${HASHTAG_PAGE_SIZE}&offset=${state.offset}`,
          { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(r => r.json().then(body => ({ status: r.status, body })))
    .then(({ status, body }) => {
        // Another tag was opened while this was in flight.
        if (myRequest !== hashtagState.requestId) return;
        state.loading = false;
        moreBtn.disabled = false;
        moreBtn.textContent = 'Load more';

        if (status !== 200) throw new Error(body.error || 'Could not load this tag.');

        const posts = body.posts || [];
        if (state.offset === 0) masonryReset(grid);   // replaces the skeleton
        const cards = posts.map(post => {
            // data-post-index addresses state.posts, so push before building.
            const index = state.posts.push(post) - 1;
            return buildProfilePostCard(post, index);
        });
        masonryAppend(grid, cards);

        state.offset += posts.length;
        state.hasMore = !!body.has_more;

        const total = body.total || state.posts.length;
        countEl.textContent = total === 1 ? '1 post' : `${total} posts`;
        moreBtn.style.display = state.hasMore ? '' : 'none';

        if (!state.posts.length) {
            countEl.textContent = 'No posts yet';
            empty.textContent = `Nobody has posted with #${state.tag} yet.`;
            empty.style.display = '';
        }

        if (state.offset === posts.length) renderRelatedHashtags(body.related || []);
        verifyMentions();
    })
    .catch(err => {
        if (myRequest !== hashtagState.requestId) return;
        console.error('Error loading tag:', err);
        state.loading = false;
        moreBtn.disabled = false;
        countEl.textContent = '';
        if (!state.posts.length) {
            masonryReset(grid);
            empty.textContent = err.message || 'Could not load this tag.';
            empty.style.display = '';
        } else {
            // Some of it is on screen: keep it, and leave a way to try for the
            // rest rather than replacing the page with an error.
            moreBtn.textContent = 'Retry';
            moreBtn.style.display = '';
        }
    });
}

// --- Trending tags -----------------------------------------------------------
// Shown on the blank search screen, under the same rule as the people
// suggestions beside it: only while nothing has been typed. It answers a
// different question from that row -- not "who should I follow" but "what is
// everyone talking about" -- and it is the only place on APEX where the answer
// was written by the people being asked about.
//
// One fetch per session, cached: the week's busiest tags do not change between
// two openings of the search box, and paying a round trip every time it opens
// would be the most visible cost of the cheapest thing on the screen.
let trendingTagsCache = null;
let trendingTagsInFlight = null;

function fetchTrendingTags() {
    if (trendingTagsCache) return Promise.resolve(trendingTagsCache);
    if (trendingTagsInFlight) return trendingTagsInFlight;

    trendingTagsInFlight = fetch(`${API_BASE_URL}/api/tags/trending?limit=12`,
                                 { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => r.json())
        .then(body => {
            trendingTagsCache = (body && body.tags) || [];
            return trendingTagsCache;
        })
        .catch(() => [])
        .finally(() => { trendingTagsInFlight = null; });

    return trendingTagsInFlight;
}

// Fills a chip container from the trending row. Resolves to how many chips
// landed, so a caller can hide its own heading when the answer is "none".
function renderTrendingTagChips(container) {
    if (!container) return Promise.resolve(0);
    return fetchTrendingTags().then(tags => {
        container.innerHTML = '';
        // The all-time count, not the week's: it is the number that says
        // whether the tag is worth opening. See the endpoint's own note.
        tags.forEach(row => container.appendChild(buildHashtagChip(row.tag, row.count)));
        return tags.length;
    });
}

// The block on the mobile search page. Same visibility rule as
// syncSuggestedVisibility, which is why that function now calls this one.
function fetchAndRenderTrendingTags() {
    const block = document.getElementById('search-trending-tags');
    const chips = document.getElementById('search-trending-chips');
    if (!block || !chips) return;

    renderTrendingTagChips(chips).then(count => {
        if (!count) {
            block.style.display = 'none';
            return;
        }
        syncTrendingTagsVisibility();
    });
}

function syncTrendingTagsVisibility() {
    const block = document.getElementById('search-trending-tags');
    if (!block) return;
    const populated = document.getElementById('search-trending-chips')?.children.length > 0;
    block.style.display = (populated && searchIsIdle()) ? '' : 'none';
}

function renderRelatedHashtags(related) {
    const wrap = document.getElementById('hashtag-related');
    const chips = document.getElementById('hashtag-related-chips');
    if (!wrap || !chips) return;
    chips.innerHTML = '';
    if (!related.length) {
        wrap.hidden = true;
        return;
    }
    related.forEach(row => chips.appendChild(buildHashtagChip(row.tag, row.count)));
    wrap.hidden = false;
}

// The one chip shape: the tag's own page in a tap, with its post count when
// there is one worth showing.
function buildHashtagChip(tag, count) {
    const a = document.createElement('a');
    a.className = 'hashtag-chip';
    a.href = `/tags/${encodeURIComponent(tag)}`;
    a.onclick = (event) => openHashtag(event, tag);

    const name = document.createElement('span');
    name.className = 'hashtag-chip-tag';
    name.textContent = `#${tag}`;
    a.appendChild(name);

    if (count) {
        const n = document.createElement('span');
        n.className = 'hashtag-chip-count';
        n.textContent = count;
        a.appendChild(n);
    }
    return a;
}


// ===========================================================================
// Single post page (/posts/<id>)
// ===========================================================================
// A post's own address. Reached from the profile grid, from a shared link, and
// from the /post/<id> spelling the server has always served.
let currentSinglePost = null;

function showSinglePostPage(postId) {
    const page = document.getElementById('single-post-page');
    const body = document.getElementById('single-post-body');
    if (!page || !body) return;

    currentSinglePost = null;
    // The post's own shape in grey -- picture on one side, author and text lines
    // on the other -- so the page is already the right layout when it fills in.
    body.innerHTML = `
        <div class="single-post-media sps-media"><div class="circuit-post-skeleton"></div></div>
        <div class="single-post-panel sps-panel" aria-label="Loading post">
            <div class="sps-author">
                <span class="circuit-post-skeleton sps-avatar"></span>
                <span class="circuit-post-skeleton sps-line" style="width: 40%"></span>
            </div>
            <span class="circuit-post-skeleton sps-line"></span>
            <span class="circuit-post-skeleton sps-line" style="width: 85%"></span>
            <span class="circuit-post-skeleton sps-line" style="width: 60%"></span>
        </div>`;
    showPage('single-post-page');
    setPageTitle('Post');

    fetch(`${API_BASE_URL}/api/post/${postId}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json().then(data => ({ ok: r.ok, data })))
    .then(({ ok, data }) => {
        if (!ok) throw new Error(data.error || 'Post not found');
        currentSinglePost = data;
        renderSinglePost(data);
    })
    .catch(err => {
        console.error("Error loading post:", err);
        body.innerHTML = `<p class="single-post-loading">${err.message === 'Post not found'
            ? 'This post no longer exists.' : 'Could not load this post.'}</p>`;
    });
}

function renderSinglePost(post) {
    const body = document.getElementById('single-post-body');
    const author = post.author || {};
    const username = author.username || 'unknown';

    // Cache the author so updateProfilePictures() can paint the avatar.
    if (author.username) {
        profileData[username] = {
            ...(profileData[username] || {}),
            name: author.fullName,
            username: username,
            rank: author.rank,
            profilePicUrl: author.profilePic,
            account_type: author.account_type,
        };
    }

    setPageTitle(author.fullName ? `${author.fullName}'s post` : 'Post');

    const pageImages = postImagesOf(post);
    const imageHTML = !post.image ? ''
        : pageImages.length > 1
            ? `<div class="single-post-media">${postGalleryHTML(post, pageImages)}</div>`
            : `<div class="single-post-media"><img src="${post.image}" alt="" class="post-media"
                    style="aspect-ratio:${postBoxRatio(post.image_ratio)};"
                    onload="adoptNaturalRatio(this)" onerror="adoptNaturalRatio(this)"></div>`;

    const circuitHTML = post.circuit
        ? `<a href="#" class="single-post-circuit"
              onclick="event.preventDefault(); navigateTo('/circuits/${post.circuit.code}')">
             <i class="fas fa-layer-group"></i> <span></span>
           </a>` : '';

    body.innerHTML = `
        ${imageHTML}
        <div class="single-post-panel">
            <div class="circuit-post-menu-button single-post-menu-button"
                 data-post-id="${post.id}" data-author-id="${post.author_id}"
                 data-circuit-code="${post.circuit ? post.circuit.code : ''}"
                 onclick="toggleCircuitPostMenu(event, ${post.id}, ${Number(post.author_id)})">
                <i class="fas fa-ellipsis-h"></i>
            </div>
            <div id="circuit-post-menu-${post.id}" class="circuit-post-menu-dropdown hidden"></div>
            <a href="#" class="single-post-author" onclick="event.preventDefault(); navigateTo('/users/${username}')">
                <div class="profile-pic" data-user-pic-id="${username}"></div>
                <div class="single-post-author-meta">
                    <span class="single-post-author-name"></span>
                    <span class="single-post-time">${post.timestamp
                        ? formatPostTimestamp(new Date(post.timestamp)) : ''}</span>
                </div>
            </a>
            ${post.text ? `<p class="single-post-text">${linkifyUsernames(post.text)}</p>` : ''}
            ${circuitHTML}
            <div class="single-post-actions">
                ${postActionsHTML(post, true)}
            </div>
        </div>
    `;

    if (post.poll) {
        const panel = body.querySelector('.single-post-panel');
        panel.insertBefore(buildPollCard(post.poll, 'circuit'),
                           panel.querySelector('.single-post-actions'));
    }

    // textContent for the user-supplied strings the template left empty.
    body.querySelector('.single-post-author-name').textContent = author.fullName || username;
    appendRankIcon(body.querySelector('.single-post-author-name'), username, author.rank);
    if (post.circuit) body.querySelector('.single-post-circuit span').textContent = post.circuit.title;

    updateProfilePictures(username);
    verifyMentions();
}


function showProfile(username) {
    const isMe = (username === 'me' || username === profileData.me.username);
    const userKey = isMe ? 'me' : username;
    
    if (!profileData[userKey]) {
        // Initialize a skeleton user so the page can render immediately
        profileData[userKey] = {
            username: username,
            name: 'Loading...',
            rank: 'user', // Default rank to prevent icon errors
            profilePicUrl: null,
            bio: '',
            school: '',
            email: ''
        };
    }
    
    const user = profileData[userKey];
    showPage('profile-page');
    resetProfileTabs();

    // Find all the elements we need to update
    const bioElement = document.getElementById('userBio');
    const schoolElement = document.getElementById('userSchool');
    const emailElement = document.getElementById('userEmail');
    const gradeElement = document.getElementById('userAge');
    const mainPic = document.querySelector('#profile-page .profile-pic-large');
    const statsBar = document.getElementById('profile-stats-bar');

    // Hide stats bar by default while we load data
    statsBar.style.display = 'none';

    // Set initial content before fetching full details
    mainPic.setAttribute('data-user-pic-id', userKey);
    document.getElementById('profileNameHeader').innerHTML = `${user.username || user.name} ${rankIconFor(user.username || userKey, user.rank)}`;
    document.getElementById('userName').innerHTML = `${user.name} ${rankIconFor(user.username || userKey, user.rank)}`;
    document.getElementById('userUsername').textContent = `@${user.username}`;
    updateProfilePictures(userKey);
    fetchAndRenderResume(userKey);
    bioElement.textContent = 'Loading...';
    schoolElement.textContent = 'School: Loading...';
    emailElement.textContent = 'Email: Loading...';
    gradeElement.textContent = '';

    const endpoint = isMe ? `${API_BASE_URL}/api/me` : `${API_BASE_URL}/api/user/${username}`;
    fetch(endpoint, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(response => response.json())
    .then(fullProfile => {
        // Store full profile data locally
        profileData[userKey] = { ...user, ...fullProfile };
        profileData[userKey].profilePicUrl = fullProfile.profile_pic;
        // The API calls it fullName; the rest of the app (DM list, etc.) reads
        // .name -- without this the "Loading..." skeleton name sticks around.
        if (fullProfile.fullName) profileData[userKey].name = fullProfile.fullName;
        updateProfilePictures(userKey);

        // Loaded here rather than above, because 'me' is a local alias and the
        // posts endpoint needs a real handle -- on a hard reload at /users/me
        // profileData.me.username isn't populated until this response lands.
        if (fullProfile.username) loadProfilePosts(fullProfile.username, isMe);

        // Update Name, Bio, School, Email, etc.
        const tagHtml = getAccountTypeTag(fullProfile.account_type);
        document.getElementById('userName').innerHTML = `${fullProfile.fullName} ${rankIconFor(fullProfile.username, fullProfile.rank)} ${tagHtml}`;
        setPageTitle(fullProfile.fullName);

        // "Follows you", and a Follow button that offers to follow back.
        const handleEl = document.getElementById('userUsername');
        handleEl.textContent = `@${fullProfile.username}`;
        if (!isMe && fullProfile.follows_you) {
            const chip = document.createElement('span');
            chip.className = 'fl-follows-you';
            chip.textContent = 'Follows you';
            handleEl.appendChild(chip);
        }
        const profileFollowBtn = document.querySelector('#profile-page .profile-buttons .follow-btn');
        if (profileFollowBtn) {
            profileFollowBtn.dataset.followsYou = fullProfile.follows_you ? '1' : '';
            profileFollowBtn.textContent = followButtonLabel(followingList.includes(userKey), fullProfile.follows_you);
        }
        let bioText = fullProfile.bio || '';
        if (bioText.trim().startsWith('//rainbow ')) {
            const rainbowContent = bioText.substring(10);
            bioElement.innerHTML = linkifyUsernames(rainbowContent);
            bioElement.classList.add('rainbow-text');
        } else {
            bioElement.innerHTML = linkifyUsernames(bioText);
            bioElement.classList.remove('rainbow-text');
        }
        bioElement.style.display = bioText.trim() ? 'block' : 'none';

        schoolElement.textContent = `School: ${fullProfile.school || 'Not specified'}`;
        emailElement.textContent = `Email: ${fullProfile.email}`;

        if (fullProfile.account_type === 'student') {
            gradeElement.textContent = `Grade: ${fullProfile.grade || 'N/A'}`;
            gradeElement.style.display = 'block';
        } else if (fullProfile.account_type === 'teacher') {
            gradeElement.textContent = `Subject: ${fullProfile.subject || 'N/A'}`;
            gradeElement.style.display = 'block';
        } else {
            gradeElement.style.display = 'none';
        }

        // --- NEW: Birthday Icon Privacy Check ---
        // Check both if it's their birthday AND if they allow it to be shown
        if (fullProfile.is_birthday && fullProfile.show_birthday) {
            mainPic.classList.add('birthday-user');
        } else {
            mainPic.classList.remove('birthday-user');
        }

        // --- NEW: Stats Bar Privacy Check ---
        if (fullProfile.show_social_stats) {
            statsBar.style.display = 'flex'; // Show the bar now that we have data
            document.getElementById('post-count').textContent = fullProfile.post_count || 0;
            document.getElementById('follower-count').textContent = fullProfile.follower_count || 0;
            const followingCount = isMe ? followingList.length : (fullProfile.following_count || 0);
            document.getElementById('following-count').textContent = followingCount;

            // Both lists open for anyone, unless the owner has turned that off.
            // Your own always open.
            const listsOpen = isMe || fullProfile.show_follow_lists !== false;
            const counts = { followers: fullProfile.follower_count || 0, following: followingCount };
            [['follower-stat', 'followers'], ['following-stat', 'following']].forEach(([id, kind]) => {
                const stat = document.getElementById(id);
                stat.classList.toggle('clickable', listsOpen);
                stat.classList.toggle('is-private', !listsOpen);
                stat.title = listsOpen ? '' : 'Only visible to this account';
                stat.onclick = listsOpen ? () => openFollowListModal(fullProfile.username, kind, counts) : null;
            });
        } else {
            // If they've hidden their stats, hide the whole bar
            statsBar.style.display = 'none';
            verifyMentions();
        }
    })
    .catch(err => console.error("Failed to fetch full profile:", err));

    // Logic for buttons and menus
    const headerRight = document.querySelector('#profile-page .header-right');
    headerRight.innerHTML = ''; // Clear old buttons/menu

    if (isMe) {
        const menuButton = document.createElement('div');
        menuButton.className = 'profile-menu-button';
        menuButton.innerHTML = `<i class="fas fa-ellipsis-v"></i>`;

        const menuDropdown = document.createElement('div');
        menuDropdown.className = 'profile-menu-dropdown hidden';
        menuDropdown.id = 'profile-menu-dropdown';
        menuDropdown.innerHTML = `
            <a href="/users/me/edit" class="profile-menu-item" onclick="event.preventDefault(); navigateTo('/users/me/edit')">Edit Profile</a>
            <hr class="context-menu-divider">
            <a href="/my-activity" class="profile-menu-item" onclick="event.preventDefault(); navigateTo('/my-activity')">My Activity</a>
            <a href="/my-lounges" class="profile-menu-item" onclick="event.preventDefault(); navigateTo('/my-lounges')">My Lounges</a>
        `;

        headerRight.appendChild(menuButton);
        headerRight.appendChild(menuDropdown);

        menuButton.onclick = (event) => {
            event.stopPropagation();
            menuDropdown.classList.toggle('hidden');
        };

    } else {
        // (menuButton and menuDropdown creation is the same)
        const menuButton = document.createElement('div');
        menuButton.className = 'profile-menu-button';
        menuButton.innerHTML = `<i class="fas fa-ellipsis-v"></i>`;
        const menuDropdown = document.createElement('div');
        menuDropdown.className = 'profile-menu-dropdown hidden';
        menuDropdown.id = 'profile-menu-dropdown';

        // --- THIS IS THE NEW LOGIC ---
        const isBlocked = isUserBlocked(userKey);
        // event.preventDefault() is NOT optional here: without it the href="#"
        // runs, the router sees the URL change and bounces you to the home page.
        // Every other .profile-menu-item in this file already does this.
        const blockHtml = isBlocked
            ? `<a href="#" class="profile-menu-item" onclick="event.preventDefault(); unblockUser('${userKey}')">Unblock User</a>`
            : `<a href="#" class="profile-menu-item" onclick="event.preventDefault(); blockUser('${userKey}')">Block User</a>`;

        menuDropdown.innerHTML = `
            <a href="#" class="profile-menu-item" onclick="event.preventDefault(); openReportModal({ type: 'user', id: '${userKey}' })">Report User</a>
            ${blockHtml}`;

        // Add moderation tools for mods AND admins
        if (hasPerm('user.avatar.reset')) {
            menuDropdown.innerHTML += `<hr style="margin: 5px 0; border-color: #eee;">`;
            menuDropdown.innerHTML += `<a href="#" class="profile-menu-item danger" onclick="event.preventDefault(); handleResetAvatar('${userKey}')">Reset Avatar</a>`;
            
        }
        

        // Each of these is its own permission, so an admin can be given the
        // ability to appoint moderators without the ability to appoint admins.
        let adminTools = '';
        if (hasPerm('rank.set.admin')) {
            adminTools += `<a href="#" class="profile-menu-item admin-option" onclick="handleRankChange('${userKey}', 'admin')">Make Admin</a>`;
        }
        if (hasPerm('rank.set.moderator')) {
            adminTools += `<a href="#" class="profile-menu-item admin-option" onclick="handleRankChange('${userKey}', 'moderator')">Make Moderator</a>`;
        }
        if (hasPerm('rank.set.user')) {
            adminTools += `<a href="#" class="profile-menu-item admin-option" onclick="handleRankChange('${userKey}', 'user')">Make User</a>`;
        }
        if (hasPerm('user.password.reset')) {
            adminTools += `<a href="#" class="profile-menu-item admin-option" style="color: #d35400;" onclick="handleAdminPasswordReset('${userKey}')">Reset Password</a>`;
        }
        if (adminTools) menuDropdown.innerHTML += adminTools;
        // --- END OF NEW LOGIC ---

        headerRight.appendChild(menuButton);
        headerRight.appendChild(menuDropdown);
        menuButton.onclick = (event) => {
            event.stopPropagation();
            menuDropdown.classList.toggle('hidden');
        };
    }

    const card = document.querySelector('#profile-page .profile-card');
    const oldButtons = card.querySelector('.profile-buttons');
    if (oldButtons) oldButtons.remove();
    if (!isMe) {
        const isFollowing = followingList.includes(userKey);
        const buttonText = isFollowing ? 'Following' : 'Follow';
        const buttonClass = isFollowing ? 'follow-btn following' : 'follow-btn';
        const buttonsHTML = `<div class="profile-buttons"><button onclick="openChat('${userKey}')">Message</button><button class="${buttonClass}" onclick="toggleFollow(this, '${userKey}')">${buttonText}</button></div>`;
        card.insertAdjacentHTML('beforeend', buttonsHTML);
    } else {
        // Editing your own profile used to live only behind the ⋮ menu, where people
        // did not think to look. Same destination as the menu item -- this is just
        // the obvious way in, sitting where Message/Follow sit on everyone else.
        const buttonsHTML = `<div class="profile-buttons"><button class="edit-profile-btn" onclick="navigateTo('/users/me/edit')"><i class="fas fa-cog"></i> Edit Profile</button><button class="share-profile-btn" onclick="openShareProfileModal('${profileData.me.username}', ${profileData.me.id})"><i class="fas fa-share-alt"></i> Share Profile</button></div>`;
        card.insertAdjacentHTML('beforeend', buttonsHTML);
    }
}

function showResumeModal() {
    // Reset form for "Add" mode
    currentEditingResumeItemId = null;
    const modal = document.getElementById('resume-modal');
    const form = document.getElementById('resume-form');
    
    modal.querySelector('h2').textContent = 'Add Experience';
    form.reset();
    form.onsubmit = (event) => {
        event.preventDefault();
        handleAddResumeItem(form);
    };
    form.querySelector('button[type="submit"]').textContent = 'Save';

    // Show the modal
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
}

function closeResumeModal() {
    document.getElementById('resume-modal').classList.add('hidden');
    document.body.classList.remove('modal-open');
    
    // Reset the form and clear editing state
    const form = document.getElementById('resume-form');
    form.reset();
    currentEditingResumeItemId = null;
    
    // Reset modal text/buttons to default "Add" state
    document.getElementById('resume-modal').querySelector('h2').textContent = 'Add Experience';
    form.querySelector('button[type="submit"]').textContent = 'Save';
    form.onsubmit = (event) => {
        event.preventDefault();
        handleAddResumeItem(form);
    };
}

function showEditResumeModal(itemId) {
    const itemEl = document.getElementById(`resume-item-${itemId}`);
    if (!itemEl) return;

    // Get the data we stored on the <li> element
    const { category, title, description } = itemEl.dataset;

    // Set the global editing ID
    currentEditingResumeItemId = itemId;
    
    const modal = document.getElementById('resume-modal');
    const form = document.getElementById('resume-form');
    
    // Populate the form fields
    form.category.value = category;
    form.title.value = title;
    form.description.value = description;

    // Change modal title and button
    modal.querySelector('h2').textContent = 'Edit Experience';
    form.querySelector('button[type="submit"]').textContent = 'Save Changes';
    
    // Change the form's submit action
    form.onsubmit = (event) => {
        event.preventDefault();
        handleEditResumeItem(form);
    };

    // Show the modal
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
}

/**
    * Handles the submission of the "Edit" form.
    */
function handleEditResumeItem(form) {
    if (!currentEditingResumeItemId) return;

    const button = form.querySelector('button[type="submit"]');
    button.disabled = true;
    button.textContent = 'Saving...';

    const payload = {
        // Captured before closeResumeModal() clears currentEditingResumeItemId --
        // an appeal sent afterwards still has to know which item it edits.
        item_id: currentEditingResumeItemId,
        category: form.category.value,
        title: form.title.value,
        description: form.description.value
    };

    fetch(`${API_BASE_URL}/api/me/resume/${currentEditingResumeItemId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(payload)
    })
    .then(response => response.json().then(data => ({ ok: response.ok, body: data })))
    .then(({ ok, body }) => {
        if (ok) {
            showToast('Item updated!', 'success');
            closeResumeModal();
            
            // Update the backing item and repaint. The old version patched the
            // <li> field by field, which meant every change to the card markup had
            // to be made twice -- here and in createResumeItemElement.
            const idx = resumeState.items.findIndex(i => i.id === body.item.id);
            if (idx !== -1) resumeState.items[idx] = body.item;
            renderResumePage();
        } else if (isModerationError(body.error)) {
            closeResumeModal();
            showModerationErrorModal(body.error, 'edit_resume', payload);
        } else {
            showToast(body.error || 'Could not save item.', 'error');
        }
    })
    .finally(() => {
        button.disabled = false;
        button.textContent = 'Save Changes';
    });
}

/**
    * Prompts for and handles the deletion of a resume item.
    */
function handleDeleteResumeItem(itemId) {
    showConfirmationModal({
        title: 'Delete Item?',
        text: 'Are you sure you want to permanently delete this item?',
        onConfirm: () => {                    
            fetch(`${API_BASE_URL}/api/me/resume/${itemId}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${apiToken}` }
            })
            .then(response => response.json().then(data => ({ ok: response.ok, body: data })))
            .then(({ ok, body }) => {
                if (ok) {
                    showToast('Item deleted.', 'success');
                    // Drop it from the backing list and repaint: removing the <li>
                    // on its own left a four-item page with the sixth item still
                    // stranded on page two.
                    resumeState.items = resumeState.items.filter(i => i.id !== itemId);
                    renderResumePage();
                } else {
                    showToast(body.error || 'Could not delete item.', 'error');
                }
            })
            .catch(err => {
                showToast('An error occurred.', 'error');
                console.error(err);
            });
        }
    });
}

function handleAddResumeItem(form) {
    const button = form.querySelector('button[type="submit"]');
    button.disabled = true;
    button.textContent = 'Saving...';

    const payload = {
        category: form.category.value,
        title: form.title.value,
        description: form.description.value
    };

    fetch(`${API_BASE_URL}/api/me/resume`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(payload)
    })
    .then(response => response.json().then(data => ({ ok: response.ok, body: data })))
    .then(({ ok, body }) => {
        if (ok) {
            showToast('Profile updated!', 'success');
            closeResumeModal();
            // Newest goes on top, so show the first page -- otherwise you add an
            // item while sitting on page 3 and nothing appears to happen.
            resumeState.items.unshift(body.item);
            resumeState.page = 0;
            renderResumePage();
        } else if (isModerationError(body.error)) {
            // The form modal has to go first: the appeal modal is a separate
            // overlay, and two stacked sheets is what "confusing" looks like.
            closeResumeModal();
            showModerationErrorModal(body.error, 'resume', payload);
        } else {
            showToast(body.error || 'Could not save item.', 'error');
        }
    })
    .finally(() => {
        button.disabled = false;
        button.textContent = 'Save';
    });
}

// ===========================================================================
// Resume / experience list
// ===========================================================================
// Five items at a time, paged in place with arrow buttons -- an embedded pager,
// not a route. A resume with twenty entries used to run the full height of the
// profile and push the posts section off the bottom of the screen.
//
// The whole list arrives in one request (it is short, and the endpoint has no
// paging), so the arrows only re-slice what is already in memory: no request, no
// spinner, instant. Everything renders from resumeState, which is also what makes
// add/edit/delete correct -- they used to patch the DOM directly, so deleting an
// item left a four-item page instead of pulling one up from the next.
const RESUME_PAGE_SIZE = 5;

let resumeState = {
    items: [],
    page: 0,
    isMe: false,
    isAdmin: false,
    requestId: 0,   // a slow response for a profile you have already left is dropped
};

function resumePageCount() {
    return Math.max(1, Math.ceil(resumeState.items.length / RESUME_PAGE_SIZE));
}

function fetchAndRenderResume(username) {
    const list = document.getElementById('resume-list');
    const addButton = document.getElementById('resume-add-btn');
    if (!list || !addButton) return; // Stop if the HTML isn't on the page

    list.innerHTML = '<p style="text-align: center; color: #999;">Loading...</p>';

    const isMe = (username === 'me' || username === profileData.me.username);
    addButton.style.display = isMe ? 'flex' : 'none';

    const myRequest = resumeState.requestId + 1;
    resumeState = {
        items: [], page: 0, isMe,
        isAdmin: hasPerm('content.resume.delete'),
        requestId: myRequest,
    };
    const pager = document.getElementById('resume-pager');
    if (pager) pager.style.display = 'none';

    fetch(`${API_BASE_URL}/api/user/${username}/resume`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json())
    .then(items => {
        if (myRequest !== resumeState.requestId) return;
        resumeState.items = Array.isArray(items) ? items : [];
        renderResumePage();
    })
    .catch(err => {
        if (myRequest !== resumeState.requestId) return;
        list.innerHTML = '<p style="text-align: center; color: red;">Could not load items.</p>';
    });
}

function renderResumePage() {
    const list = document.getElementById('resume-list');
    const pager = document.getElementById('resume-pager');
    if (!list) return;

    const pages = resumePageCount();
    // Deleting the last item on the last page has to walk the page back.
    resumeState.page = Math.min(Math.max(0, resumeState.page), pages - 1);

    const start = resumeState.page * RESUME_PAGE_SIZE;
    const slice = resumeState.items.slice(start, start + RESUME_PAGE_SIZE);

    // replaceChildren, not innerHTML='': leaves the list genuinely empty so the
    // "#resume-list:empty::after" message still fires when there is nothing.
    list.replaceChildren(
        ...slice.map(item => createResumeItemElement(item, resumeState.isMe, resumeState.isAdmin))
    );

    if (!pager) return;
    // One page needs no arrows.
    if (resumeState.items.length <= RESUME_PAGE_SIZE) {
        pager.style.display = 'none';
        return;
    }
    pager.style.display = '';
    document.getElementById('resume-pager-status').textContent =
        `${resumeState.page + 1} / ${pages}`;
    document.getElementById('resume-prev').disabled = resumeState.page === 0;
    document.getElementById('resume-next').disabled = resumeState.page >= pages - 1;
}

function stepResumePage(delta) {
    const target = resumeState.page + delta;
    if (target < 0 || target >= resumePageCount()) return;
    resumeState.page = target;
    renderResumePage();
}

function createResumeItemElement(item, isMe, isAdmin) {
    const li = document.createElement('li');
    li.className = 'resume-item';
    li.id = `resume-item-${item.id}`; 
    
    // Store data on the element for editing
    li.dataset.itemId = item.id;
    li.dataset.category = item.category;
    li.dataset.title = item.title;
    li.dataset.description = item.description || '';

    const descHtml = item.description 
        ? `<p>${item.description.replace(/\n/g, '<br>')}</p>` 
        : '';

    let buttonsHtml = '';
    // Show edit/delete buttons if it's "me" or user is an "admin"
    if (isMe || isAdmin) {
        buttonsHtml += `<div class="resume-item-actions">`;
        // Only "me" can edit
        if (isMe) {
            buttonsHtml += `<button class="resume-item-btn" onclick="showEditResumeModal(${item.id})"><i class="fas fa-pencil-alt"></i></button>`;
        }
        // "me" or "admin" can delete
        buttonsHtml += `<button class="resume-item-btn delete" onclick="handleDeleteResumeItem(${item.id})"><i class="fas fa-trash"></i></button>`;
        buttonsHtml += `</div>`;
    }

    li.innerHTML = `
        <strong>${item.title}</strong>
        <span>${item.category}</span>
        ${descHtml}
        ${buttonsHtml}
    `;
    return li;
}


function formatTimestamp(date) {
    // Ensure we're working with a valid Date object
    if (!(date instanceof Date) || isNaN(date)) {
        return '';
    }

    const now = new Date();
    const diffSeconds = Math.floor((now - date) / 1000);
    const diffMinutes = Math.floor(diffSeconds / 60);
    const diffHours = Math.floor(diffMinutes / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMinutes < 3) {
        return 'Just now';
    }
    if (diffHours < 1) {
        return `${diffMinutes} minute(s) ago`;
    }
    if (diffDays < 1) {
        return `${diffHours} hour(s) ago`;
    }
    if (diffDays < 7) {
        return `${diffDays} day(s) ago`;
    }

    // If it's 7 days or more, show the date like "on Sep 12"
    return date.toLocaleDateString([], {
        month: 'short',
        day: 'numeric'
    });
}

function handleRankChange(username, newRank) {
    // Hide the menu first
    document.getElementById('profile-menu-dropdown').classList.add('hidden');

    // Confirm the action with the admin
    if (!confirm(`Are you sure you want to change ${username}'s rank to ${newRank}?`)) {
        return;
    }

    fetch(`${API_BASE_URL}/api/user/${username}/rank`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${apiToken}`
        },
        body: JSON.stringify({ rank: newRank })
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 200 && body.ok) {
            alert(body.message);
            // Update the local data to match
            if (profileData[username]) {
                profileData[username].rank = newRank;
            }
            if (staffRanks) {
                if (newRank === 'admin' || newRank === 'moderator') staffRanks.set(username.toLowerCase(), newRank);
                else staffRanks.delete(username.toLowerCase());
                paintRankSlots();
            }
            // Reload the profile to show the new rank and halo instantly
            showProfile(username);
        } else {
            alert('Error: ' + (body.error || 'Could not change rank.'));
        }
    })
    .catch(error => {
        console.error("Rank change error:", error);
        alert("An error occurred. Please try again.");
    });
}

