    const mainHeader = document.getElementById('mainHeaderTitle'); // Assumes this ID exists in index-page header
    const isAuthPage = ['login-page', 'signup-page', 'account-type-selection-page', 'guardian-consent-page', 'verify-page', 'tos-page', 'privacy-page', 'guidelines-page', 'password-reset-page'].includes(pageId);

