// Place the 3-dot dropdown against the button that opened it.
//
// The dropdown used to sit at `position: absolute; top: 40px; right: 10px` inside the
// card, which needed nothing from JS. It is fixed now because the card is a
// multi-column item and carries `overflow: hidden` -- the only thing that reliably
// stops a browser splitting a card across a column break, and the fix for posts that
// were invisible on iPads (see .circuit-posts-grid .circuit-post in style.css). An
// absolutely positioned child would be clipped by that; a fixed one is not.
//
// offsetWidth/offsetHeight, NOT getBoundingClientRect(): the dropdown carries a zoomIn
// animation, and a rect measured while that is running is the SCALED box, which would
// place a menu that then grew out from the wrong corner. The offset properties are
// layout metrics and ignore the transform.
//
// Anchored to the card's 3-dot button when it is on screen; on a touchscreen,
// where the button is hidden, to the point the card was long-pressed.
// What a post menu can hang off. A grid tile, or the post's own page -- the
// page had no menu at all, so report/edit/delete were reachable from a card in
// a feed but not from the post itself.
const POST_MENU_HOST = '.circuit-post, .single-post-panel';

function positionPostMenu(menu, card) {
    if (!menu || !card) return;
    const w = menu.offsetWidth;
    const h = menu.offsetHeight;
    const margin = 8;
    const gap = 6;

    const btnEl = card.querySelector('.circuit-post-menu-button');
    let button, left;
    if (btnEl && btnEl.offsetWidth) {
        button = btnEl.getBoundingClientRect();
        // Right edge against the button's, the way the old `right: 10px` read.
        left = button.right - w;
    } else {
        const c = card.getBoundingClientRect();
        const p = card._menuPoint || { x: c.width / 2, y: 0 };
        const x = c.left + p.x;
        const y = c.top + p.y;
        button = { top: y, bottom: y, left: x, right: x };
        left = x - w / 2;
    }
    let top = button.bottom + gap;

    // Flip above the button rather than run off the bottom of the screen -- a card near
    // the end of a column is exactly where this menu opens, and it is the one place the
    // old absolute positioning got away with overflowing.
    if (top + h > window.innerHeight - margin) {
        top = Math.max(margin, button.top - h - gap);
    }
    left = Math.min(Math.max(margin, left), Math.max(margin, window.innerWidth - w - margin));

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
}

function toggleCircuitPostMenu(event, postId, authorId) {
    console.log(`[Debug] toggleCircuitPostMenu called for postId: ${postId}, authorId: ${authorId}`);
    event.stopPropagation(); 

    // From the card that was acted on when there is one: the same post can have a
    // card in a circuit grid still in the DOM and another on a profile, both with
    // this id, and getElementById would hand back whichever comes first.
    const sourceCard = event.target && event.target.closest && event.target.closest(POST_MENU_HOST);
    let menu = (sourceCard && sourceCard.querySelector('.circuit-post-menu-dropdown'))
        || document.getElementById(`circuit-post-menu-${postId}`);
    if (!menu) {
        console.error(`[Debug] Initial find failed: Menu element not found: circuit-post-menu-${postId}`);
        closeAllPostMenus();
        return;
    }

    const isCurrentlyVisible = !menu.classList.contains('hidden');

    if (isCurrentlyVisible) {
        console.log(`[Debug] Menu ${postId} was visible. Hiding it.`);
        menu.classList.add('hidden');
    } else {
        console.log(`[Debug] Closing other menus.`);
        document.querySelectorAll('.circuit-post-menu-dropdown').forEach(m => {
            if (m !== menu) {
                m.classList.add('hidden');
            }
        });

        console.log(`[Debug] Building menu content for ${postId}.`);
        menu.innerHTML = '';
        
        // --- FIX 1: Report Post Link ---
        menu.innerHTML += `<a href="#" class="context-menu-item" onclick="event.preventDefault(); showReportPostModal(${postId}, event)">Report Post</a>`;
        
        // FIX: Ensure type-safe ID comparison and add moderator access
        const isMyPost = profileData.me && Number(profileData.me.id) === Number(authorId);
        const isModOrAdmin = hasPerm('content.circuitpost.delete');

        if (isMyPost || isModOrAdmin) {
            menu.innerHTML += `<hr class="context-menu-divider">`;
            
            // Only the author can EDIT the post
            // A profile card names its own circuit; a circuit card is in the one open.
            const button = menu.closest(POST_MENU_HOST)?.querySelector('.circuit-post-menu-button');
            // A card that carries the data attribute has spoken, even when it is
            // empty: that is a profile post, and falling back to whatever circuit
            // was opened last would send its Edit to an unrelated circuit.
            const circuitCode = button && button.hasAttribute('data-circuit-code')
                ? button.dataset.circuitCode
                : currentCircuitDetails?.code;
            if (isMyPost) {
                const editPath = circuitCode ? `/circuits/${circuitCode}/post/${postId}/edit` : `/posts/${postId}/edit`;
                menu.innerHTML += `<a href="#" class="context-menu-item" onclick="event.preventDefault(); navigateTo('${editPath}')">Edit Post</a>`;
            }
            
            // Author, Admin, and Mod can DELETE the post
            menu.innerHTML += `<a href="#" class="context-menu-item danger" onclick="event.preventDefault(); handleDeletePost(${postId}, event)">Delete Post</a>`;
        }

        menu.classList.remove('hidden');

        // Found from the menu rather than the event: the long-press path calls this
        // with a stub event that has no target at all.
        positionPostMenu(menu, menu.closest(POST_MENU_HOST));
        anyPostMenuOpen = true;
        console.log(`[Debug] Menu ${postId} shown.`);
    }
}

// A fixed menu does not travel with the card it is anchored to, which an absolutely
// positioned one did for free. So follow it: reposition on any scroll or resize while
// one is open.
//
// Repositioning rather than closing, deliberately. Closing on scroll is the usual
// shortcut and it is wrong here -- the long press that opens this menu on a touch
// screen ends with a finger resting on a scrollable feed, and the few pixels of drift
// that follow would shut the menu before it had been read.
let anyPostMenuOpen = false;
let postMenuFollowQueued = false;

function followOpenPostMenus() {
    if (!anyPostMenuOpen || postMenuFollowQueued) return;
    postMenuFollowQueued = true;
    requestAnimationFrame(() => {
        postMenuFollowQueued = false;
        const open = document.querySelectorAll('.circuit-post-menu-dropdown:not(.hidden)');
        if (!open.length) { anyPostMenuOpen = false; return; }
        open.forEach(menu => positionPostMenu(menu, menu.closest(POST_MENU_HOST)));
    });
}

// Capture, so a scroll inside any container is seen and not just the window's.
document.addEventListener('scroll', followOpenPostMenus, { capture: true, passive: true });
window.addEventListener('resize', followOpenPostMenus, { passive: true });

// You already have this function, keep it as is for the global listener
function closeAllPostMenus() {
    anyPostMenuOpen = false;
    // --- DEBUG LOG ADDED ---
    console.log("[Debug] closeAllPostMenus EXECUTING. Hiding all .circuit-post-menu-dropdown elements.");
    // --- END DEBUG ---
    document.querySelectorAll('.circuit-post-menu-dropdown').forEach(menu => {
        menu.classList.add('hidden');
    });
}

