const LIKE_SPARK_COLORS = ['#e74c3c', '#ff8fa3', '#ffc75f', '#ff5e7e', '#f9748f', '#ffd6a5'];

// Throws a ring and a scatter of sparks out of the heart. Purely decorative:
// the nodes are absolutely positioned inside the button and removed once the
// keyframes have run, so nothing is left behind for the grid to trip over.
function playLikeBurst(button) {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const burst = document.createElement('span');
    burst.className = 'like-burst';

    for (let i = 0; i < LIKE_SPARK_COLORS.length; i++) {
        const spark = document.createElement('i');
        spark.className = 'like-spark';
        // Evenly spaced spokes, jittered so repeated likes don't look stamped.
        spark.style.setProperty('--a', `${i * 60 + (Math.random() * 26 - 13)}deg`);
        spark.style.setProperty('--spark-color', LIKE_SPARK_COLORS[i]);
        spark.style.animationDelay = `${Math.round(Math.random() * 40)}ms`;
        burst.appendChild(spark);
    }

    button.appendChild(burst);
    setTimeout(() => burst.remove(), 700);
}

// Paints every copy of a post's like control (the grid tile and the open modal
// can both be showing the same post). `animate` is off for server confirmations
// and rollbacks, which shouldn't re-fire the celebration.
function renderLikeState(postId, liked, likes, animate) {
    document.querySelectorAll(`[data-like-container-id="${postId}"]`).forEach(container => {
        const button = container.querySelector('.like-button');
        const count = container.querySelector('.like-count');

        if (count) {
            count.textContent = likes;
            if (animate) {
                count.classList.remove('bump');
                void count.offsetWidth;   // restart the keyframes on a repeat tap
                count.classList.add('bump');
            }
        }
        if (!button) return;

        button.classList.toggle('liked', liked);
        if (!animate) return;

        button.classList.remove('pop', 'unpop');
        void button.offsetWidth;
        button.classList.add(liked ? 'pop' : 'unpop');
        if (liked) playLikeBurst(button);
    });
}

function toggleLike(event, postId) {
    event.stopPropagation();

    // The grid passes this straight out of a dataset, so it arrives as a string;
    // the modal passes a number. Everything below compares against post.id.
    const id = Number(postId);
    const container = document.querySelector(`[data-like-container-id="${postId}"]`);
    if (!container) return;

    const button = container.querySelector('.like-button');
    const countEl = container.querySelector('.like-count');
    if (!button) return;

    const wasLiked = button.classList.contains('liked');
    const previousLikes = parseInt(countEl && countEl.textContent, 10) || 0;
    const optimisticLikes = Math.max(0, previousLikes + (wasLiked ? -1 : 1));
    const endpoint = wasLiked ? 'unlike' : 'like';

    // Paint the new state before the request leaves. Waiting on the round trip
    // is most of what made this button feel dead -- the response now only
    // confirms the count, or puts the old one back if the call failed.
    renderLikeState(postId, !wasLiked, optimisticLikes, true);
    if (!wasLiked && navigator.vibrate) navigator.vibrate(18);

    // Every array that might be holding this post, not just the circuit feed.
    // The heart on screen is repainted by renderLikeState above and looks
    // right either way -- but the moment anything re-renders a card FROM one of
    // these objects (reopening the modal is the easy one to hit), it draws the
    // state it still has. Liking from a profile grid and reopening the post
    // showed an empty heart over a like the server had already recorded.
    const posts = [currentCircuitPosts, profilePostsState.posts, taggedPostsState.posts]
        .map(list => (list || []).find(p => p && p.id === id))
        .filter(Boolean);
    // The single-post page keeps its one post outside any list.
    if (currentSinglePost && currentSinglePost.id === id) posts.push(currentSinglePost);

    posts.forEach(post => {
        post.likes = optimisticLikes;
        post.is_liked_by_me = !wasLiked;
    });

    const rollBack = () => {
        posts.forEach(post => {
            post.likes = previousLikes;
            post.is_liked_by_me = wasLiked;
        });
        renderLikeState(postId, wasLiked, previousLikes, false);
    };

    fetch(`${API_BASE_URL}/api/posts/${postId}/${endpoint}`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(response => response.json().then(data => ({ status: response.status, body: data })))
    .then(({ status, body }) => {
        if (status === 200 && body.ok) {
            posts.forEach(post => { post.likes = body.likes; });
            renderLikeState(postId, !wasLiked, body.likes, false);
        } else {
            rollBack();
            showToast(body.error || 'Action failed', 'error');
        }
    })
    .catch(err => {
        console.error("Like error:", err);
        rollBack();
    });
}

function updateNotificationBadge() {
    // Both halves of Messages, because both live behind this one nav item
    // now. The switch inside Messages is what splits the number back out.
    const count = unreadSenders.size + unreadLoungeCount;
    
    // 1. Sidebar Badge (Desktop)
    const sidebarBadge = document.getElementById('message-notification-badge');
    if (sidebarBadge) {
        sidebarBadge.style.display = count > 0 ? 'block' : 'none';
        sidebarBadge.textContent = count > 99 ? '99+' : count;
    }

    // 2. Mobile Header Badges (ALL Pages)
    const headerBadges = document.querySelectorAll('[id="header-message-badge"]');
    
    headerBadges.forEach(badge => {
        if (count > 0) {
            badge.style.display = 'block';
            badge.textContent = count > 99 ? '99+' : count;
        } else {
            badge.style.display = 'none';
        }
    });

    updateMessagesModeBadges();
    updateHomeNavBadge();
}

function showPostModal(postIndex, list) {
    // `list` is only passed by the caller that opens the modal; swipe/prev/next
    // re-enter without it and keep paging whatever list is already open.
    if (list) modalPostList = list;
    const posts = getModalPosts();

    if (postIndex < 0 || postIndex >= posts.length) {
        console.error(`[Debug] Invalid postIndex: ${postIndex}, list length: ${posts.length}`);
        return;
    }

    const post = posts[postIndex];
    if (!post) {
            console.error(`[Debug] Post data not found for index: ${postIndex}`); // <-- ADDED LOG
        return;
    }

        if (!post.author) {
            console.error(`[Debug] Post data for index ${postIndex} is missing author details!`, post); // <-- ADDED LOG
            // Decide how to handle this - maybe show a placeholder or return?
            // For now, let's try to continue but log the issue.
            post.author = { username: 'unknown', fullName: 'Unknown Author', rank: 'user' }; // Placeholder
        }


    currentPostIndexInModal = postIndex; // Keep track of the current index

    const modal = document.getElementById('post-modal');
    const modalContent = document.getElementById('modal-content');
    if (!modal || !modalContent) {
        console.error("[Debug] Modal elements (#post-modal or #modal-content) not found!"); // <-- ADDED LOG
        return;
    }

    const timestamp = formatPostTimestamp(new Date(post.timestamp));
    // The magnified view shows the whole picture, so a gallery here is set to
    // contain rather than the crop the grid card uses.
    const modalImages = postImagesOf(post);
    const imageHTML = !post.image ? ''
        : modalImages.length > 1 ? postGalleryHTML(post, modalImages)
        : `<img src="${post.image}" class="modal-post-image" alt="Post image">`;

    // Use optional chaining just in case author is still missing somehow
    const authorUsername = post.author?.username || 'unknown';
    const authorFullName = post.author?.fullName || 'Unknown Author';

    const authorHTML = `
        <a href="#" class="circuit-post-author-link"
        onclick="event.stopPropagation(); closePostModal(); showProfile('${authorUsername}'); return false;">
            <span title="${authorFullName}">- ${authorFullName}${rankIconFor(authorUsername, post.author?.rank)}</span>
            <div class="profile-pic" data-user-pic-id="${authorUsername}"></div>
        </a>
    `;
    // --- ▲▲▲ END ADDITION ▲▲▲ ---

    // Only outside the circuit itself: inside it, the chip would link to where you are.
    const showCircuitLink = post.circuit?.code && getModalPosts() !== currentCircuitPosts;
    const circuitHTML = showCircuitLink
        ? `<a href="#" class="circuit-post-circuit-link"
              onclick="event.preventDefault(); event.stopPropagation(); openPostInCircuit(this, '${post.circuit.code}', ${post.id})">
             <i class="fas fa-layer-group"></i> <span></span>
           </a>` : '';

    modalContent.innerHTML = `
        <p class="modal-post-timestamp">${timestamp}</p>
        <div class="modal-post-details">
            ${imageHTML}
            ${post.text ? `<p class="circuit-post-text">${linkifyUsernames(post.text)}</p>` : ''}
            ${circuitHTML}
            <div class="circuit-post-author"> ${authorHTML} </div>
            ${postActionsHTML(post, true)}
        </div>
    `;

    if (showCircuitLink) {
        modalContent.querySelector('.circuit-post-circuit-link span').textContent = post.circuit.title;
    }

    if (post.poll) {
        const details = modalContent.querySelector('.modal-post-details');
        details.insertBefore(buildPollCard(post.poll, 'circuit'),
                             details.querySelector('.circuit-post-author'));
    }

    console.log("[Debug] Modal content set. Attempting to remove 'hidden' class..."); // <-- ADDED LOG
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
    // No-op when paging with < / > or a swipe -- those re-enter this function
    // and must not stack an entry per post.
    pushModalHistory('post-modal', closePostModal);
    // A thread docked beside the lightbox follows it to this post.
    syncDockedCommentsToPost(post.id);
    console.log("[Debug] 'hidden' class removed from modal. Modal hidden status:", modal.classList.contains('hidden')); // <-- ADDED LOG

    if (authorUsername !== 'unknown') {
        updateProfilePictures(authorUsername);
    }

    // Navigation buttons
    // Ensure button elements exist before trying to modify them
    const prevBtn = document.getElementById('modal-prev-btn');
    const nextBtn = document.getElementById('modal-next-btn');
    if(prevBtn && nextBtn) {
        prevBtn.style.display = postIndex > 0 ? 'block' : 'none';
        nextBtn.style.display = postIndex < posts.length - 1 ? 'block' : 'none';
        prevBtn.onclick = () => showPostModal(postIndex - 1);
        nextBtn.onclick = () => showPostModal(postIndex + 1);
        verifyMentions();
    } else {
        console.error("[Debug] Modal navigation buttons not found!"); // <-- ADDED LOG
    }
}



// Open the composer for the circuit being viewed. Goes through the router rather
// than calling showCreatePostPage directly: showing the page without pushing a
// history entry left the URL on /circuits/<code>, so Back stepped straight over
// the circuit and landed on whatever preceded it -- usually Home.
function openCircuitComposer() {
    const code = currentCircuitDetails && currentCircuitDetails.code;
    if (!code) {
        showToast('Error: No circuit selected.', 'error');
        return;
    }
    navigateTo(`/circuits/${code}/post/new`);
}

// A post that goes on your profile and nowhere else. /post/new is its address,
// so Back from the composer returns to wherever you opened it.
function openProfileComposer() {
    navigateTo('/post/new');
}

// The line at the top of the composer that says where this post will live. A
// post opened from a circuit can be taken out of it (the x) and posted to your
// profile alone instead; there is no way to lose a circuit you did not choose.
function syncPostDestination() {
    const el = document.getElementById('post-destination');
    if (!el) return;
    const ctx = postCreationContext || {};
    if (ctx.type === 'edit') {
        el.hidden = true;
        return;
    }
    el.hidden = false;
    if (ctx.type === 'circuit' && ctx.id) {
        el.innerHTML = `
            <i class="fas fa-layer-group"></i>
            <span>Posting to <b></b></span>
            <button type="button" class="post-destination-clear" title="Post to your profile only"
                    aria-label="Don't post in this circuit"><i class="fas fa-xmark"></i></button>`;
        el.querySelector('b').textContent = ctx.title || 'this circuit';
        el.querySelector('.post-destination-clear').onclick = () => {
            postCreationContext = { type: 'profile', id: null };
            syncPostDestination();
        };
    } else {
        el.innerHTML = `
            <i class="fas fa-user"></i>
            <span>Posting to <b>your profile</b></span>`;
    }
}

