// --- Mobile Account Switcher Logic ---

// Helper to get all saved accounts from localStorage
function getSavedAccounts() {
    const saved = localStorage.getItem('apex_saved_accounts');
    return saved ? JSON.parse(saved) : {};
}

// Helper to save an account
function saveAccountToDevice(token, user) {
    const accounts = getSavedAccounts();
    accounts[user.username] = {
        token: token,
        username: user.username,
        name: user.fullName || user.name,
        profilePic: user.profile_pic || user.profilePicUrl
    };
    localStorage.setItem('apex_saved_accounts', JSON.stringify(accounts));
}

function toggleMobileAccountMenu(event) {
    event.stopPropagation(); // Stop global click listener
    if (!isPhoneLayout()) return; // The desktop layout has no mobile account menu

    const dropdown = document.getElementById('mobile-account-dropdown');
    const switcher = document.querySelector('.mobile-account-switcher');
    
    // Close other menus
    closeAllPopups(event);

    const isOpening = dropdown.classList.contains('hidden');
    
    if (isOpening) {
        renderSavedAccountsMenu();
        dropdown.classList.remove('hidden');
        switcher.classList.add('open');
    } else {
        dropdown.classList.add('hidden');
        switcher.classList.remove('open');
    }
}

function renderSavedAccountsMenu() {
    const listContainer = document.getElementById('mobile-saved-accounts-list');
    const accounts = getSavedAccounts();
    const currentUsername = profileData.me.username;

    listContainer.innerHTML = '';

    Object.values(accounts).forEach(acc => {
        const isActive = acc.username === currentUsername;
        const a = document.createElement('a');
        a.className = `profile-menu-item mobile-account-item ${isActive ? 'active-account' : ''}`;
        a.href = "#";
        
        // When clicked, switch to this account
        a.onclick = (e) => {
            e.preventDefault();
            if (!isActive) switchAccount(acc.token);
        };

        const bgImage = acc.profilePic ? `url(${acc.profilePic})` : "url('/api/asset/default_avatar')";

        a.innerHTML = `
            <div class="profile-pic nav-user-pic" style="--avatar-image: ${bgImage};"></div>
            <div style="display:flex; flex-direction:column; line-height:1.2;">
                <span>${acc.name}${rankIconFor(acc.username, acc.rank)}</span>
                <span style="font-size:0.8em; color:#888; font-weight:normal;">@${acc.username}</span>
            </div>
            ${isActive ? '<i class="fas fa-check" style="margin-left:auto; color:var(--primary-solid);"></i>' : ''}
        `;
        listContainer.appendChild(a);
    });
}

// nextPath: where to land once the new account is verified. checkForSavedSession()
// finishes by calling handleRouting(), which reads the address bar -- so the
// destination is set on the URL before the switch rather than navigated to after
// it, which would have routed under the OLD account and then again under the new.
function switchAccount(newToken, nextPath) {
    // We do NOT call the server /logout here because we want to keep the old token alive on the device

    // Clean up current session
    if (socket) {
        socket.disconnect();
        socket = null;
    }
    
    // Set the new token
    localStorage.setItem('apiToken', newToken);
    apiToken = newToken;
    loggedIn = false; // Force the app to re-fetch
    profileData.me = {}; 
    
    // Trigger the standard login verification flow
    document.getElementById('mobile-account-dropdown').classList.add('hidden');
    document.querySelector('.mobile-account-switcher').classList.remove('open');
    
    // Show a loader while we fetch the new user data
    const loader = document.getElementById('loader');
    if (loader) {
        loader.style.display = 'flex';
        loader.style.opacity = '1';
    }
    
    if (nextPath) {
        previousPath = window.location.pathname;
        history.pushState(null, '', nextPath);
    }

    checkForSavedSession(); // This will log them in and hide the loader

    // Register this phone for the account just switched to (no prompt: the
    // permission is the device's, already granted). Each account now has its own
    // push row, so this adds one rather than taking the phone from the last.
    syncPushSubscription();
}

// Route to `url` as `username`, switching accounts first if we are somebody else.
//
// This is what a tapped push notification goes through. A phone commonly has two
// or three accounts saved, and every one of them pushes to the same device
// endpoints -- so the notification you tap is frequently not for the account that
// is currently signed in. Opening its URL as-is landed you on a DM thread that
// account has no part in, which looked like the message had vanished.
function openAsAccount(username, url) {
    const target = url || '/';

    // No account on the payload (an older service worker, or a push queued before
    // this shipped) or it is already us: behave exactly as before.
    if (!username || (profileData.me && profileData.me.username === username)) {
        navigateTo(target);
        return;
    }

    const account = getSavedAccounts()[username];
    if (!account || !account.token) {
        // Not signed in on this device. Routing anyway would open a page the
        // current account cannot see, so say what happened and stay put -- the
        // notification itself is already dismissed either way.
        showToast(`That notification was for @${username}, which isn't signed in on this device.`, 'error');
        return;
    }

    switchAccount(account.token, target);
}

// Cold start from a notification. client.navigate()/openWindow() can only carry a
// URL, so the worker appends ?apex_acct=<username>; pick that account's token up
// before the session check runs, then take the parameter back off the address bar
// so a later reload of this entry does not re-apply it.
//
// Runs BEFORE checkForSavedSession() on purpose: switching after the session is
// verified would boot the whole app twice.
function adoptAccountFromUrl() {
    const params = new URLSearchParams(window.location.search);
    const wanted = params.get('apex_acct');
    if (!wanted) return;

    params.delete('apex_acct');
    const query = params.toString();
    history.replaceState(null, '',
        window.location.pathname + (query ? `?${query}` : '') + window.location.hash);

    const account = getSavedAccounts()[wanted];
    // Not saved here, or already the active token: nothing to do. Either way the
    // normal boot path takes it from here.
    if (!account || !account.token) return;
    if (localStorage.getItem('apiToken') === account.token) return;

    localStorage.setItem('apiToken', account.token);
}

function handleAddNewAccount(event) {
    event.preventDefault();
    // To add a new account, we simply log out of the current one, 
    // but we leave the local storage list intact.
    
    if (socket) {
        socket.disconnect();
        socket = null;
    }
    
    localStorage.removeItem('apiToken'); // Clear active token
    apiToken = null;
    loggedIn = false;
    profileData.me = {}; 
    
    navigateTo('/login');
}

