function initializeScrollAnimations() {
    const scroller = document.getElementById('login-scroller');
    if (!scroller) return;

    const slides = Array.from(scroller.querySelectorAll('.login-slide'));
    let currentSlideIndex = 0;
    let isScrolling = false;

    // 1. The Custom Cinematic Scroll Hijacker
    scroller.addEventListener('wheel', (e) => {
        e.preventDefault(); // Stop normal fast scrolling

        if (isScrolling) return; // Ignore wheel spins while an animation is happening

        // THE FIX: Dynamically recalculate our true position before moving!
        // This solves the "Back to Top" desync bug instantly.
        const slideHeight = scroller.clientHeight;
        currentSlideIndex = Math.round(scroller.scrollTop / slideHeight);

        // Determine direction
        const direction = e.deltaY > 0 ? 1 : -1;
        const nextIndex = currentSlideIndex + direction;

        // Ensure we don't scroll past the first or last slide
        if (nextIndex >= 0 && nextIndex < slides.length) {
            isScrolling = true;
            currentSlideIndex = nextIndex;

            // Trigger the smooth scroll
            const targetScrollPosition = slides[currentSlideIndex].offsetTop;
            scroller.scrollTo({
                top: targetScrollPosition,
                behavior: 'smooth'
            });

            // Cooldown: Lock the scroll wheel for 1.2 seconds to ensure a steady, slow pace
            setTimeout(() => {
                isScrolling = false;
            }, 1200); 
        }
    }, { passive: false });

    // 2. The Intersection Observer (Triggers the visual effects)
    const observerOptions = {
        root: scroller,
        rootMargin: '0px',
        threshold: 0.5 // Trigger when slide is 50% in view
    };

    const slideObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('slide-visible');
                
                if (entry.target.id === 'login-slide-4') {
                    startCounters(entry.target);
                }
            } else {
                entry.target.classList.remove('slide-visible');
            }
        });
    }, observerOptions);

    slides.forEach(slide => slideObserver.observe(slide));
}

// 3. The Number Counting Logic
function startCounters(slideElement) {
    const counters = slideElement.querySelectorAll('.count-up');
    const frames = 60;

    counters.forEach(counter => {
        if (counter.classList.contains('counted')) return; 

        const target = +counter.getAttribute('data-target');
        let current = 0;
        const increment = target / frames;

        const updateCount = () => {
            current += increment;
            if (current < target) {
                counter.innerText = Math.ceil(current).toLocaleString();
                requestAnimationFrame(updateCount); 
            } else {
                counter.innerText = target.toLocaleString();
                counter.classList.add('counted'); 
            }
        };
        updateCount();
    });
}

// --- Mobile Long Press + Swipe-to-Reply Logic ---
let longPressTimer = null;
const LONG_PRESS_DURATION = 500; // 500ms

// Instagram-style swipe-to-reply. Drag a bubble toward the centre of the thread
// (sent bubbles slide left, received slide right); the bubble follows the finger
// with a rubber-band resistance and springs back on release. Cross the threshold
// and let go to reply. Everything below is mobile-only and lives alongside the
// long-press timer above.
const SWIPE_MAX = 82;        // px the bubble can travel (rubber-band asymptote)
const SWIPE_TRIGGER = 52;    // px of finger travel that arms the reply
const SWIPE_LOCK_SLOP = 8;   // px before we commit to horizontal vs vertical
let swipeState = null;

function handleMessageTouchStart(event, messageId, type, isAuthor, authorId, textContext, authorNameContext, timestamp) {
    if (!isTouchUi()) return; // Only apply to a finger

    longPressTimer = setTimeout(() => {
        openMobileMessageOptions(messageId, type, isAuthor, authorId, textContext, authorNameContext, timestamp);
    }, LONG_PRESS_DURATION);

    const touch = event.touches ? event.touches[0] : event;
    swipeState = {
        el: event.currentTarget,
        startX: touch.clientX,
        startY: touch.clientY,
        dir: isAuthor ? -1 : 1, // my messages slide left, others slide right (toward centre)
        messageId, type,
        text: textContext,
        author: authorNameContext,
        locked: false,
        swiping: false,
        triggered: false,
        indicator: null
    };
}

function handleMessageTouchMove(event) {
    if (!isTouchUi()) return;
    if (longPressTimer) clearTimeout(longPressTimer); // any drag cancels the long-press
    if (!swipeState) return;

    const touch = event.touches ? event.touches[0] : event;
    const dx = touch.clientX - swipeState.startX;
    const dy = touch.clientY - swipeState.startY;

    if (!swipeState.locked) {
        if (Math.abs(dx) < SWIPE_LOCK_SLOP && Math.abs(dy) < SWIPE_LOCK_SLOP) return;
        // Vertical intent, or a drag away from centre -> let the list scroll, abandon swipe.
        if (Math.abs(dy) > Math.abs(dx) || Math.sign(dx) !== swipeState.dir) {
            swipeState = null;
            return;
        }
        swipeState.locked = true;
        swipeState.swiping = true;
        const el = swipeState.el;
        el.style.transition = 'none';
        el.style.willChange = 'transform';
        el.style.position = 'relative';
        el.style.zIndex = '1'; // sit above the reply indicator revealed behind it
        createSwipeIndicator(swipeState);
    }

    // We own this gesture now: stop the thread from scrolling under the drag.
    if (event.cancelable) event.preventDefault();

    const toward = Math.max(0, dx * swipeState.dir);           // finger distance toward centre
    const eff = SWIPE_MAX * Math.tanh(toward / SWIPE_MAX);      // rubber-band ease to the cap
    swipeState.el.style.transform = `translateX(${swipeState.dir * eff}px)`;

    const armed = toward >= SWIPE_TRIGGER;
    if (armed !== swipeState.triggered) {
        swipeState.triggered = armed;
        if (armed && navigator.vibrate) navigator.vibrate(12); // tick when the reply arms
    }
    updateSwipeIndicator(swipeState, toward);
}

function handleMessageTouchEnd() {
    if (!isTouchUi()) return;
    if (longPressTimer) clearTimeout(longPressTimer);

    const s = swipeState;
    swipeState = null;
    if (!s || !s.swiping) return;

    // Spring the bubble back to rest, Instagram-style.
    const el = s.el;
    el.style.transition = 'transform 0.34s cubic-bezier(0.22, 1.2, 0.36, 1)';
    el.style.transform = 'translateX(0)';
    const cleanup = () => {
        el.style.transition = '';
        el.style.willChange = '';
        el.style.position = '';
        el.style.zIndex = '';
        el.removeEventListener('transitionend', cleanup);
    };
    el.addEventListener('transitionend', cleanup);
    setTimeout(cleanup, 400); // fallback if transitionend never fires

    removeSwipeIndicator(s);

    if (s.triggered) {
        if (navigator.vibrate) navigator.vibrate(18);
        showReplyUI(s.messageId, s.type, s.text, s.author);
    }
}

// The reply arrow revealed in the gutter as the bubble slides away from it.
function createSwipeIndicator(s) {
    const parent = s.el.parentElement;
    if (!parent) return;
    if (getComputedStyle(parent).position === 'static') parent.style.position = 'relative';
    const icon = document.createElement('div');
    icon.className = 'swipe-reply-indicator ' + (s.dir === -1 ? 'on-right' : 'on-left');
    icon.innerHTML = '<i class="fas fa-reply"></i>';
    parent.appendChild(icon);
    s.indicator = icon;
}

function updateSwipeIndicator(s, toward) {
    if (!s.indicator) return;
    const p = Math.min(1, toward / SWIPE_TRIGGER);
    s.indicator.style.opacity = p;
    s.indicator.style.transform = `translateY(-50%) scale(${(0.55 + p * 0.45).toFixed(3)})`;
    s.indicator.classList.toggle('armed', s.triggered);
}

function removeSwipeIndicator(s) {
    if (!s.indicator) return;
    const icon = s.indicator;
    s.indicator = null;
    icon.style.transition = 'opacity 0.2s ease, transform 0.2s ease';
    icon.style.opacity = '0';
    setTimeout(() => icon.remove(), 220);
}

function openMobileMessageOptions(messageId, type, isAuthor, authorId, textContext, authorNameContext, timestamp) {
    // Provide tactile feedback if supported
    if (navigator.vibrate) navigator.vibrate(50);

    const modal = document.getElementById('mobile-message-options-modal');
    const reactionsContainer = document.getElementById('mobile-quick-reactions');
    const actionList = document.getElementById('mobile-action-list');

    // Exact send time (to the second), matching the desktop 3-dot menu.
    const timeEl = document.getElementById('mobile-message-time');
    if (timeEl) {
        const timeLabel = formatExactTimestamp(timestamp);
        timeEl.textContent = timeLabel;
        timeEl.style.display = timeLabel ? '' : 'none';
    }

    // 1. Populate Reactions
    const commonReactions = ['👍', '❤️', '😂', '😮', '😢', '🙏'];
    reactionsContainer.innerHTML = '';
    commonReactions.forEach(emoji => {
        const span = document.createElement('span');
        span.textContent = emoji;
        span.onclick = () => {
            if (type === 'dm') sendReaction(messageId, emoji);
            else sendLoungeReaction(messageId, emoji);
            closeMobileMessageOptions();
        };
        reactionsContainer.appendChild(span);
    });

    // 2. Populate Actions
    //
    // These are built as real elements with real handlers, NOT by interpolating the
    // message into an inline onclick="..." string. That old approach silently broke
    // Reply -- the only action that carries the message text -- whenever the text
    // could not survive being pasted into a JS string literal:
    //   * a newline  -> literal newline inside the string  -> SyntaxError
    //   * an apostrophe in a DM -> renderChatMessages already escaped ' to \', and
    //     this function escaped it AGAIN to \\' -> the quote closed early -> SyntaxError
    // A broken onclick throws at parse time, so the tap did nothing at all, with no
    // error to see. Closures capture the values directly, so nothing needs escaping
    // and no message text can be "unrepliable". This matches how the desktop hover
    // buttons (and the quick reactions above) have always worked.
    const isMod = (currentUserLoungeRole === 'owner' || currentUserLoungeRole === 'moderator' || hasPerm('content.message.delete'));

    actionList.innerHTML = '';

    const addAction = (iconHtml, label, onActivate, extraClass) => {
        const btn = document.createElement('button');
        btn.className = 'mobile-action-btn' + (extraClass ? ' ' + extraClass : '');
        btn.innerHTML = iconHtml;
        btn.appendChild(document.createTextNode(' ' + label));
        btn.onclick = () => {
            // finally, not a plain sequence: an action that throws must never be able
            // to strand the sheet on screen with the page locked behind it.
            try {
                onActivate();
            } finally {
                closeMobileMessageOptions();
            }
        };
        actionList.appendChild(btn);
        return btn;
    };

    // Reply
    addAction('<i class="fas fa-reply"></i>', 'Reply',
        () => showReplyUI(messageId, type, textContext, authorNameContext || 'User'));

    // Copy
    addAction('<i class="fas fa-copy"></i>', 'Copy Text',
        () => copyMessageText(messageId, type));

    // Edit (Only Author)
    if (isAuthor) {
        addAction('<i class="fas fa-edit"></i>', 'Edit',
            () => showEditMessageUI(messageId, type));
    }

    // Delete (Author OR Mod in Lounge)
    if (isAuthor || (type === 'lounge' && isMod)) {
        addAction('<i class="fas fa-trash"></i>', 'Delete',
            () => handleDeleteMessage(messageId, type), 'danger');
    }

    // 3. Show Modal
    modal.classList.add('visible');
    document.body.style.overflow = 'hidden'; // Prevent background scrolling
}

function closeMobileMessageOptions(event) {
    if (event && event.target.id !== 'mobile-message-options-modal') return;

    const modal = document.getElementById('mobile-message-options-modal');
    if (modal) {
        modal.classList.remove('visible');
        document.body.style.overflow = ''; // Restore scrolling
    }
}

// --- Long-press a reaction pill to see who reacted ---
// Same gesture and duration as long-pressing a message; desktop keeps its hover
// tooltip, which is fed by the very same endpoint.
let reactionLongPressTimer = null;
// A long press still emits a click on touchend, which would toggle the reaction off
// behind the sheet. This swallows that one synthetic click.
let suppressNextReactionClick = false;

function createMobileReactionUsersModal() {
    if (document.getElementById('mobile-reaction-users-modal')) return;

    const modalHtml = `
        <div id="mobile-reaction-users-modal" onclick="closeMobileReactionUsers(event)">
            <div class="mobile-message-sheet" onclick="event.stopPropagation()">
                <div class="mobile-sheet-handle"></div>
                <div class="reaction-users-header">
                    <span class="reaction-users-emoji" id="reaction-users-emoji"></span>
                    <span class="reaction-users-title" id="reaction-users-title"></span>
                </div>
                <div class="reaction-users-list" id="reaction-users-list"></div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
}

function handleReactionTouchStart(event, messageId, emoji, type) {
    if (!isTouchUi()) return; // Only apply to a finger
    // A fresh touch: whatever the last one did, this one starts clean.
    suppressNextReactionClick = false;
    clearTimeout(reactionLongPressTimer);
    reactionLongPressTimer = setTimeout(() => {
        suppressNextReactionClick = true;
        openMobileReactionUsers(messageId, emoji, type);
    }, LONG_PRESS_DURATION);
}

function handleReactionTouchEnd() {
    if (!isTouchUi()) return;
    if (reactionLongPressTimer) clearTimeout(reactionLongPressTimer);
}

function handleReactionTouchMove() {
    if (!isTouchUi()) return;
    // Scrolling the chat must not count as a long press
    if (reactionLongPressTimer) clearTimeout(reactionLongPressTimer);
}

function openMobileReactionUsers(messageId, emoji, type) {
    if (navigator.vibrate) navigator.vibrate(50); // Match the message long-press

    createMobileReactionUsersModal();
    hideReactionTooltip(); // Kill any hover tooltip a tap may have queued

    const modal = document.getElementById('mobile-reaction-users-modal');
    const list = document.getElementById('reaction-users-list');
    const title = document.getElementById('reaction-users-title');

    document.getElementById('reaction-users-emoji').textContent = emoji;
    title.textContent = 'Loading...';
    list.innerHTML = '';

    modal.classList.add('visible');
    document.body.style.overflow = 'hidden'; // Prevent background scrolling

    const url = type === 'dm'
        ? `${API_BASE_URL}/api/dm/message/${messageId}/reaction/${encodeURIComponent(emoji)}`
        : `${API_BASE_URL}/api/lounge/message/${messageId}/reaction/${encodeURIComponent(emoji)}`;

    fetch(url, { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(response => response.json())
        .then(names => {
            if (!Array.isArray(names)) names = [];
            title.textContent = names.length === 1 ? '1 reaction' : `${names.length} reactions`;

            if (names.length === 0) {
                const empty = document.createElement('p');
                empty.className = 'reaction-users-empty';
                empty.textContent = 'No one has reacted with this yet.';
                list.appendChild(empty);
                return;
            }

            names.forEach(name => {
                const row = document.createElement('div');
                row.className = 'reaction-user-row';
                row.textContent = name; // textContent, so names can't inject markup
                list.appendChild(row);
            });
        })
        .catch(() => {
            title.textContent = '';
            const err = document.createElement('p');
            err.className = 'reaction-users-empty';
            err.textContent = 'Could not load reactions.';
            list.appendChild(err);
        });
}

function closeMobileReactionUsers(event) {
    if (event && event.target.id !== 'mobile-reaction-users-modal') return;

    const modal = document.getElementById('mobile-reaction-users-modal');
    if (modal) {
        modal.classList.remove('visible');
        document.body.style.overflow = '';
    }
}

// --- Drag a bottom sheet to dismiss it ---------------------------------------
//
// Every long-press sheet (message options, who reacted, DM options, channel
// options) draws a grab handle, and a grab handle is a promise: it says the
// sheet can be pulled. Until now it could only be dismissed by tapping the
// backdrop, so the handle was decoration.
//
// Delegated from the document rather than bound per sheet, so the four sheets
// -- all built lazily, on first open -- get it without each create function
// having to remember to wire it.
//
// The drag follows the finger down, and resists going up: these sheets are sized
// to their content, so there is nothing above to reveal, and a sheet that
// refuses to move at all feels broken where a little give feels physical. On
// release it closes if it was pulled far enough or flicked fast enough, and
// otherwise springs back.
const SHEET_DRAG_START_PX = 6;        // below this it is still a tap on a row
const SHEET_DISMISS_FRACTION = 0.3;   // of the sheet's height
const SHEET_DISMISS_VELOCITY = 0.5;   // px/ms, a downward flick
const SHEET_BACKDROP_ALPHA = 0.5;     // matches the modal's rgba(0,0,0,0.5)

function initSheetDragToDismiss() {
    let drag = null;

    const sheetFromTarget = (target) => {
        if (!(target instanceof Element)) return null;
        const sheet = target.closest('.mobile-message-sheet');
        if (!sheet) return null;
        const modal = sheet.parentElement;
        return modal && modal.classList.contains('visible') ? { sheet, modal } : null;
    };

    const setOffset = (d, dy) => {
        // Down: 1:1 with the finger. Up: a damped fraction, capped.
        const offset = dy >= 0 ? dy : -Math.min(24, Math.sqrt(-dy) * 2);
        d.sheet.style.transform = `translateY(${offset}px)`;
        const progress = Math.max(0, Math.min(1, offset / d.height));
        d.modal.style.backgroundColor = `rgba(0, 0, 0, ${SHEET_BACKDROP_ALPHA * (1 - progress)})`;
    };

    const release = (d, dismiss) => {
        // Hand the motion back to the stylesheet's transition. Clearing the inline
        // transform in the same frame as re-enabling the transition animates from
        // wherever the finger left it -- down to closed, or back up to open.
        d.sheet.style.transition = '';
        d.modal.style.transition = '';
        d.sheet.style.transform = '';
        d.modal.style.backgroundColor = '';

        if (!dismiss) return;
        // Through the modal's own close handler, which is what a backdrop tap
        // calls, so anything a sheet does on close still happens.
        d.modal.click();
        // Its guard against the long-press's own click can refuse a very quick
        // drag; the sheet is already on its way down, so finish the job.
        if (d.modal.classList.contains('visible')) {
            d.modal.classList.remove('visible');
            document.body.style.overflow = '';
        }
    };

    document.addEventListener('pointerdown', (e) => {
        if (e.button !== 0 || drag) return;
        const hit = sheetFromTarget(e.target);
        if (!hit) return;
        // A list that scrolls keeps its own vertical gesture; the handle and the
        // header around it still drag the sheet.
        const scroller = e.target.closest('.reaction-users-list');
        if (scroller && scroller.scrollHeight > scroller.clientHeight) return;

        drag = {
            ...hit,
            pointerId: e.pointerId,
            startY: e.clientY,
            lastY: e.clientY,
            lastT: e.timeStamp,
            velocity: 0,
            height: hit.sheet.offsetHeight || 1,
            active: false,
        };
    }, true);

    document.addEventListener('pointermove', (e) => {
        const d = drag;
        if (!d || e.pointerId !== d.pointerId) return;
        const dy = e.clientY - d.startY;

        if (!d.active) {
            if (Math.abs(dy) < SHEET_DRAG_START_PX) return;
            d.active = true;
            d.sheet.style.transition = 'none';
            d.modal.style.transition = 'none';
            try { d.sheet.setPointerCapture(e.pointerId); } catch (err) { /* already gone */ }
        }

        const dt = e.timeStamp - d.lastT;
        if (dt > 0) d.velocity = (e.clientY - d.lastY) / dt;
        d.lastY = e.clientY;
        d.lastT = e.timeStamp;
        setOffset(d, dy);
        e.preventDefault();
    }, { capture: true, passive: false });

    const end = (e, cancelled) => {
        const d = drag;
        if (!d || e.pointerId !== d.pointerId) return;
        drag = null;
        if (!d.active) return; // a tap: leave it to the row's own click

        const dy = e.clientY - d.startY;
        const dismiss = !cancelled && dy > 0
            && (dy > d.height * SHEET_DISMISS_FRACTION || d.velocity > SHEET_DISMISS_VELOCITY);
        release(d, dismiss);

        // A drag that started on a row still ends in a click on it. Swallow that
        // one click, so pulling the sheet down from "Delete" never deletes.
        const swallow = (ev) => { ev.stopPropagation(); ev.preventDefault(); };
        document.addEventListener('click', swallow, { capture: true, once: true });
        setTimeout(() => document.removeEventListener('click', swallow, true), 350);
    };

    document.addEventListener('pointerup', (e) => end(e, false), true);
    document.addEventListener('pointercancel', (e) => end(e, true), true);
}



let fakeProgressInterval;

function showActionProgress(title, desc) {
    document.getElementById('action-progress-title').textContent = title;
    document.getElementById('action-progress-desc').textContent = desc;
    
    const overlay = document.getElementById('action-progress-overlay');
    const fill = document.getElementById('action-progress-fill');
    
    // Saves run from inside modals (lounge settings is one), and those sit at the
    // max z-index. The overlay matches it in CSS; being last in <body> wins the tie.
    document.body.appendChild(overlay);
    overlay.classList.remove('hidden');
    // Slight delay to allow display:block to apply before animating opacity
    setTimeout(() => overlay.classList.add('visible'), 10);
    
    fill.style.width = '0%';
    let progress = 0;
    
    // Asymptotic progress: slows down as it gets closer to 90%
    fakeProgressInterval = setInterval(() => {
        progress += (90 - progress) * 0.05; 
        fill.style.width = `${progress}%`;
    }, 200);
}

function completeActionProgress(onHidden) {
    clearInterval(fakeProgressInterval);
    const fill = document.getElementById('action-progress-fill');
    const overlay = document.getElementById('action-progress-overlay');
    
    fill.style.width = '100%'; // Snap to end
    
    setTimeout(() => {
        overlay.classList.remove('visible');
        setTimeout(() => {
            overlay.classList.add('hidden');
            // Callers that navigate away on success wait for this: leaving while the
            // overlay is still fading looks like the page changed under the modal.
            if (typeof onHidden === 'function') onHidden();
        }, 300); // wait for fade out
    }, 400); // give user 400ms to see it hit 100%
}

function hideActionProgress() {
    clearInterval(fakeProgressInterval);
    const overlay = document.getElementById('action-progress-overlay');
    overlay.classList.remove('visible');
    setTimeout(() => overlay.classList.add('hidden'), 300);
}

// --- Bulletproof Mobile Scroll & Rubber-Band Fix ---
/**
 * Checks the server config and locks out mobile/tablet devices if the block is active.
 */
function enforceMobileBlock() {
    // Detects Android, iOS, iPads, and other touch devices under 1024px width
    const isMobileOrTablet = window.innerWidth <= 1024 && (('ontouchstart' in window) || navigator.maxTouchPoints > 0);
    
    if (isMobileOrTablet) {
        fetch(`${API_BASE_URL}/api/system/config`)
        .then(response => response.json())
        .then(data => {
            if (data.mobile_block_enabled) {
                const blockModal = document.getElementById('mobile-block-modal');
                if (blockModal) {
                    blockModal.classList.remove('hidden');
                    // Completely lock the background from scrolling
                    document.body.style.overflow = 'hidden'; 
                }
            }
        })
        .catch(err => console.error("Could not check mobile block config:", err));
    }
}



// --- Custom Date of Birth Modal Logic ---
let selectedDob = { month: null, day: null, year: null };
let dobModalInitialized = false;

function initDobModal() {
    if (dobModalInitialized) return;

    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const monthList = document.getElementById('dob-month-list');
    const dayList = document.getElementById('dob-day-list');
    const yearList = document.getElementById('dob-year-list');

    // Populate Months
    months.forEach((m, index) => {
        let div = document.createElement('div');
        div.className = 'dob-item';
        div.innerText = m;
        div.onclick = () => selectDobItem('month', index + 1, div);
        monthList.appendChild(div);
    });

    // Populate Days
    for (let i = 1; i <= 31; i++) {
        let div = document.createElement('div');
        div.className = 'dob-item';
        div.innerText = i;
        div.onclick = () => selectDobItem('day', i, div);
        dayList.appendChild(div);
    }

    // Populate Years (Current Year down to 1950)
    const currentYear = new Date().getFullYear();
    for (let i = currentYear; i >= 1950; i--) {
        let div = document.createElement('div');
        div.className = 'dob-item';
        div.innerText = i;
        div.onclick = () => selectDobItem('year', i, div);
        yearList.appendChild(div);
    }
    
    dobModalInitialized = true;
}

function selectDobItem(type, value, element) {
    selectedDob[type] = value;
    
    // Remove 'selected' class from siblings
    let siblings = element.parentElement.children;
    for (let el of siblings) {
        el.classList.remove('selected');
    }
    
    // Add to clicked element
    element.classList.add('selected');
    
    // Smoothly center the selected item in the scroll view
    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function openDobModal() {
    // Hide keyboard if user was typing in another input
    document.activeElement.blur(); 
    initDobModal();
    document.getElementById('dob-modal').classList.remove('hidden');
}

function closeDobModal() {
    document.getElementById('dob-modal').classList.add('hidden');
}

function confirmDob() {
    if (!selectedDob.month || !selectedDob.day || !selectedDob.year) {
        showToast("Please select your full date of birth.", "error");
        return;
    }

    // Format for backend: YYYY-MM-DD
    let m = selectedDob.month.toString().padStart(2, '0');
    let d = selectedDob.day.toString().padStart(2, '0');
    let formattedDate = `${selectedDob.year}-${m}-${d}`;
    
    // Set the hidden input value
    document.getElementById('signupDOB').value = formattedDate;
    
    // Update the visible button
    const dobBtn = document.getElementById('dob-display-btn');
    dobBtn.innerHTML = `<i class="fas fa-check-circle"></i> ${m}/${d}/${selectedDob.year}`;

    // Clear any previous validation errors that were attached to the hidden input
    hideValidationError('signupDOB');
    dobBtn.closest('.signup-field')?.classList.add('is-valid');
    hideSignupErrorSummary();
    
    closeDobModal();
}

// --- Mobile keyboard / visual viewport fix -------------------------------------
//
// One path for both platforms now. The viewport meta asks for resizes-visual (see
// index.html), so on Android and iOS alike the keyboard shrinks only the VISUAL
// viewport: the layout viewport keeps its full height, 100dvh keeps resolving to the
// whole screen, and left alone the composer ends up behind the keyboard while the app
// reads as "pushed up and now scrollable at the same resolution".
//
// So do the shrink by hand: measure the keyboard, ease the measurement (see the tween
// below), publish the surviving height as --app-vh, and let CSS resize the
// height-locked pages to it -- see "KEYBOARD VIEWPORT SHRINK" at the bottom of
// css/style.css.
//
// Android used to get this free from interactive-widget=resizes-content and is now
// routed through the same code as iOS, which is what makes the slide animatable at
// all: a resize Chrome performs is a resize we cannot ease.
//
// Deliberately NOT gated on a user-agent test or a width breakpoint. The gate is the
// measurement: where a browser still shrinks the layout viewport itself, the inset
// computes to ~0, .kb-open is never set and this is inert. A width gate is what kept
// every bit of this away from iPads before: an iPad reports 810-1180px wide, so
// `innerWidth > 768` in adjustViewport() below disabled the whole keyboard fix on the
// one device that needed it most.

// The pages CSS locks to the viewport height. Only these get force-shrunk; ordinary
// scrolling forms (signup, edit profile) must stay scrollable so the user can still
// reach the fields the keyboard covers.
const KEYBOARD_SHELL_PAGES = [
    'messages-page',
    'lounge-page',
    'terminal-page',
    'login-page',
    'mobile-search-page'
];

// ...and the pages that, in the SIDE-BY-SIDE layout, have exactly one region that
// should make room for the keyboard while the rest of the app stays put.
//
// This is the third mechanism, and it exists because the second one was wrong on an
// iPad in landscape. There, shrinking the shell shrinks EVERYTHING inside it: the
// side nav rail, the conversation list, the page header. Opening the keyboard folded
// the whole app into the strip above it -- a 300px chat list showing three rows, a
// nav rail with its icons bunched together, and a conversation with about two
// messages left in it. Nothing was broken, exactly; it was just all still there, at
// half size.
//
// A phone does not do that (the keyboard is an overlay and only the thread and
// composer translate), which is why this only ever looked right on Android. The
// side-by-side equivalent of that overlay is: hold the app at full height, let the
// keyboard cover whatever it covers, and make room in the ONE column that has a
// composer in it. The list beside it and the rail beside that are lists -- running
// them behind the keyboard is what a keyboard is supposed to do to a list.
//
// Named for the column it shrinks, and deliberately NOT .kb-pane: this file
// already has a .kb-panel (the emoji/sticker slot), and two classes one letter
// apart on the same element is a bug waiting to be typed.
//
// Not login-page: it has no nav, no list and no second column, so there is nothing
// for the shell shrink to crush and a centred form is better re-centred in what is
// left than pinned to the top of it. Not mobile-search-page either -- it only exists
// in the phone layout, where this never applies.
const KEYBOARD_PANE_PAGES = ['messages-page', 'lounge-page', 'terminal-page'];

// An iPad keyboard is 250-400px tall; the bare accessory bar shown with a hardware
// keyboard is ~55px. Above this we treat the gap as a keyboard, below it as browser
// chrome that the layout is already accounting for.
const KEYBOARD_MIN_INSET = 90;

// ...but with a hardware keyboard attached that bar is the ONLY thing that ever
// appears, and treating it as chrome is what leaves it sitting on top of the
// composer -- the black strip along the bottom that the app knows nothing about.
// So when we know the keys are physical, and only while a field is actually focused
// (which is the only time iOS draws the bar at all), the gate drops to just above
// the noise floor and the shell makes room for it like any other keyboard.
const KEYBOARD_ACCESSORY_MIN_INSET = 16;


// The height the app is LAID OUT at, keyboard or no keyboard -- i.e. whatever 100dvh
// currently resolves to, read from a real element rather than assumed.
//
// This is the reference the keyboard is measured against, and it has to be dvh
// specifically. Per spec the virtual keyboard does not affect viewport units, and the
// one thing that changes that -- interactive-widget=resizes-content -- is exactly what
// index.html no longer asks for. So under resizes-visual dvh stays at full screen on
// every platform and `probe - visible` is the keyboard, measured rather than assumed.
//
// It also keeps working as its own gate: on a browser that ignores the hint and
// shrinks the layout viewport anyway, dvh shrinks with it, the difference computes to
// ~0, and every rule below stays switched off. No user agent is named either way.
//
// window.innerHeight -- what this used to measure against -- cannot do that job. iPad
// Safari shrinks innerHeight when the keyboard opens (iPhone historically did not),
// so innerHeight and visualViewport.height both drop by the keyboard's height, their
// difference is ~0, and every rule below stayed switched off on the one device that
// needed it. Meanwhile 100dvh did NOT drop, so the app stayed a full screen tall
// inside a viewport that no longer was -- which is precisely the reported symptom:
// nothing shrinks, the app is scrolled upwards, and the header and the composer can
// never be on screen at the same time.
//
// 100vh is the fallback for browsers without dvh; on those the two are the same thing.
let keyboardViewportProbe = null;
function laidOutViewportHeight() {
    if (!keyboardViewportProbe || !keyboardViewportProbe.isConnected) {
        const host = document.body || document.documentElement;
        if (!host) return window.innerHeight;
        keyboardViewportProbe = document.createElement('div');
        keyboardViewportProbe.setAttribute('aria-hidden', 'true');
        // position:fixed so the probe measures the viewport and not the shell we are
        // about to shrink around it, and zero-width/hidden so it can never be seen,
        // hit-tested, or found by a text search.
        keyboardViewportProbe.style.cssText =
            'position:fixed;top:0;left:0;width:0;height:100vh;height:100dvh;' +
            'visibility:hidden;pointer-events:none;z-index:-1;';
        host.appendChild(keyboardViewportProbe);
    }
    const h = keyboardViewportProbe.getBoundingClientRect().height;
    return h > 0 ? h : window.innerHeight;
}

// --- Following the keyboard instead of jumping to it ---------------------------
//
// Two things have to be true for this to read as a native chat, and the first attempt
// at it got neither.
//
// 1. THE SLIDE HAS TO START WHEN THE KEYBOARD DOES, NOT WHEN THE BROWSER SAYS SO.
//
//    A native app is told the keyboard is coming the instant the field is focused --
//    that is what WindowInsetsAnimation.Callback hands it, height included, before a
//    frame has been drawn. A page is told nothing until the browser reports a new
//    viewport, and Chrome reports it when the IME has FINISHED arriving. Animating
//    from there means the app starts moving as the keyboard stops, which does not read
//    as a late animation -- it reads as no animation at all. The way OUT is reported at
//    the start of the hide, so that direction animates properly. An app that only
//    animates when the keyboard leaves is exactly that bug.
//
//    So the trigger is the tap, not the report. A keyboard is the same height every
//    time for a given device and orientation, so it gets measured once, remembered
//    (localStorage, keyed by orientation), and reused to start the slide on focus. The
//    report, when it does arrive, is a correction and is usually a no-op.
//
// 2. THE SLIDE MUST NOT TOUCH LAYOUT.
//
//    Animating the pane's height meant relaying out the entire message list on every
//    frame, on a phone, against whatever else the app was doing. That is the
//    jaggedness, and no amount of curve-fitting was ever going to fix it.
//
//    So nothing resizes. The pane stays a full screen tall and the two parts that have
//    to move -- the thread and the composer -- are translated up by the keyboard's
//    height. It is a compositor transform driven by the Web Animations API, so it runs
//    off the main thread and a message arriving mid-slide cannot jank it.
//
//    The geometry the transform stands in for is applied ONCE, at the start, and is a
//    visual no-op when it lands: the thread gains the keyboard's height as top padding
//    and its scrollTop gains the same amount, and those cancel exactly (see
//    applyKeyboardGeometry). One layout per keyboard instead of one per frame.
//
// The scroll then falls out for free, with nothing re-anchoring anything. The thread is
// translated as a whole, so whatever was against its bottom edge stays against its
// bottom edge and rides up with the composer: the newest message if you were at the
// bottom, the message you were reading if you were not. The padding is what stops the
// top of the conversation from being swallowed by the header on the way up.

// android.view.InsetsController's own constants -- ANIMATION_DURATION_SYNC_IME_MS and
// the PathInterpolator either direction uses. Kept as raw control points rather than a
// name so they can be checked against the platform source.
const KEYBOARD_SHOW_MS = 200;
const KEYBOARD_HIDE_MS = 180;
const KEYBOARD_SHOW_EASE = [0.2, 0, 0, 1];

// The one deliberate departure from the platform's own numbers. InsetsController hides
// on a symmetric ease-in-out (0.4, 0, 0.6, 1), which spends its first third barely
// moving -- and a third of 200ms of not moving, while the keyboard is already on its
// way out, is long enough to read as the app waiting for the keyboard and then catching
// up. This is the platform's decelerate interpolator instead: all of the travel is
// front-loaded, roughly nine tenths of it inside the first 100ms, so the app is home
// before the keyboard has finished leaving.
//
// Leading is only safe in this direction, and that asymmetry is why the show curve is
// untouched. The keyboard is an OS surface drawn OVER the page, so an app that arrives
// early on the way DOWN is simply hidden behind a keyboard that is still there. Arriving
// early on the way UP is the opposite: it uncovers a strip the keyboard has not reached
// yet, which is the flash publishKeyboardUnderlay() exists to paint over.
const KEYBOARD_HIDE_EASE = [0, 0, 0.2, 1];
// Below this a retarget is a correction, not a slide, and giving it a full-length
// animation is what would leave us visibly trailing the keyboard.
const KEYBOARD_MIN_TWEEN_MS = 60;
// How long a prediction is allowed to go unconfirmed before it is taken back. Focusing
// a field does not guarantee a keyboard: a hardware keyboard raises nothing, and so
// does a field that is focused programmatically. Long enough to cover an IME being
// started for the first time, which is much slower than every open after it.
const KEYBOARD_PREDICTION_GRACE_MS = 1200;
const KEYBOARD_MEMORY_KEY = 'apex.keyboardInset';

// Bisection on x rather than Newton: 12 iterations is well under a pixel of error at
// keyboard heights, and this only runs when a slide is retargeted, not per frame.
function cubicBezierEase(p1x, p1y, p2x, p2y, t) {
    const axis = (a, b, u) => {
        const v = 1 - u;
        return 3 * v * v * u * a + 3 * v * u * u * b + u * u * u;
    };
    let lo = 0, hi = 1, u = t;
    for (let i = 0; i < 12; i++) {
        if (axis(p1x, p2x, u) < t) lo = u; else hi = u;
        u = (lo + hi) / 2;
    }
    return axis(p1y, p2y, u);
}

// The height the app is laid out at, as of the last measurement. Refreshed by
// syncKeyboardViewport() rather than frozen for the length of a slide: rotating with
// the keyboard up changes the screen under us.
let kbLaidOutCache = 0;

// --- The screen the app is drawn on --------------------------------------------
//
// The keyboard is an OVERLAY. It sits on top of the app; it does not take a slice of
// the screen away from it. So every height below is measured against the SCREEN, and
// never against whatever is left of the viewport once a keyboard is up -- because on
// some engines those are the same number, on some they are not, and the ones where
// they are not are exactly where this used to come apart.
//
// Under resizes-visual the two agree: dvh stays at full screen with a keyboard up, so
// laidOutViewportHeight() already IS the screen. But an engine that ignores the hint --
// an Android WebView with adjustResize under it, anything still behaving as
// resizes-content -- shrinks the LAYOUT viewport instead, and then dvh is the top half.
// Measured against itself, `laidOut - visible` comes out ~0, nothing here switches on,
// and the app is simply laid out into the half of the screen that is left. That is the
// reported bug exactly: the app stops covering the screen, and the part it stopped
// covering is scrollable emptiness above the keyboard.
//
// So stop trusting the live value while a keyboard could be up, and keep the last one
// measured when a keyboard certainly was not. Keyed by width, which is the only thing
// that separates one orientation from the other -- and the one dimension a keyboard
// never touches.
// Persisted, and that is a fix rather than an optimisation.
//
// This is what --app-screen-h is built from, and --app-screen-h is what .kb-column
// pins the chat pane to. When a slot has no reading yet, screenHeight() falls back to
// the LIVE viewport height -- and if the first thing that ever asks is a keyboard
// already on its way up, the live height is the shrunken one. The pane then gets
// pinned to half the screen, which is the failure the .kb-column rules in style.css
// describe, arrived at from the other direction.
//
// In memory only, that hole was reachable in ordinary use: the cache starts empty on
// every load and is keyed per orientation (see screenHeightSlot), so rotating the
// device and going straight to a text field asks for a slot nothing has written yet.
//
// Reading a stale value back is safe. screenHeight() takes Math.max(remembered, live),
// so a record that is too small cannot shrink anything, and one can only ever BE too
// small -- refreshScreenHeight refuses to write while a field is focused or a keyboard
// is up, so nothing bigger than the real screen can get in.
const KB_SCREEN_HEIGHTS_KEY = 'apex.screenHeights';

const kbScreenHeights = (() => {
    try {
        const raw = localStorage.getItem(KB_SCREEN_HEIGHTS_KEY);
        if (!raw) return Object.create(null);
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return Object.create(null);
        const out = Object.create(null);
        // Copied key by key rather than used as-is: JSON.parse returns an object with
        // Object.prototype on it, and this is looked up by a computed key.
        Object.keys(parsed).forEach(k => {
            const v = parsed[k];
            if (typeof v === 'number' && isFinite(v) && v > 0) out[k] = v;
        });
        return out;
    } catch (e) { return Object.create(null); }
})();

function persistScreenHeights() {
    try {
        localStorage.setItem(KB_SCREEN_HEIGHTS_KEY, JSON.stringify(kbScreenHeights));
    } catch (e) { /* private mode; the cache is still good for this session */ }
}

function screenHeightSlot() {
    return String(Math.round(window.innerWidth));
}

// A focused text field is the disqualifier here, NOT the measured inset. On the very
// engines this exists for, the inset reads as 0 with the keyboard fully up -- so
// gating on the inset would record the shrunken height as the screen and bake the bug
// in permanently, with no way back out of it for the rest of the session.
function refreshScreenHeight() {
    if (kbInsetTarget > 0 || kbPredictionTimer) return;
    // A keyboard on its way OUT has already zeroed kbInsetTarget while it is still
    // physically on screen, and on an engine that shrinks the layout viewport the dvh
    // it leaves behind is still the shrunken one for those few frames.
    const cls = document.documentElement.classList;
    if (cls.contains('kb-sliding') || cls.contains('kb-arming')) return;
    if (isTextEntryElement(document.activeElement)) return;
    const h = Math.round(laidOutViewportHeight());
    if (h <= 0) return;
    const slot = screenHeightSlot();
    // Guarded on a CHANGE: this runs on the per-frame keyboard tracking path, and
    // JSON.stringify + a localStorage write per frame is not something to do casually.
    if (kbScreenHeights[slot] === h) return;
    kbScreenHeights[slot] = h;
    persistScreenHeights();
}

// The remembered height is only ever preferred to the live one on a device that has a
// soft keyboard to hide behind in the first place. On a desktop pointer the live value
// is used exactly as before, so nothing here can misread a window being dragged
// smaller -- which, with a text field focused, is indistinguishable from a keyboard by
// measurement alone and would otherwise slide the app for no reason.
function hasSoftKeyboard() {
    // An iPad with a keyboard attached still reports a coarse pointer -- it has a
    // touchscreen -- but it no longer has a software keyboard, and everything gated
    // on this exists to get in front of one arriving. armKeyboardOverlay() pinning
    // the app to the screen, and screenHeight() preferring a remembered height over
    // the live one, are both defences against a keyboard that is never coming.
    if (hasHardwareKeyboard()) return false;
    try {
        return window.matchMedia('(pointer: coarse)').matches || window.innerWidth <= 768;
    } catch (e) {
        return window.innerWidth <= 768;
    }
}

function screenHeight() {
    const live = Math.round(laidOutViewportHeight());
    if (!hasSoftKeyboard()) return live;
    const remembered = kbScreenHeights[screenHeightSlot()];
    // Never smaller than what is on screen right now: a stale record can only ever be
    // too small (a keyboard was up when it was taken), and a screen that has genuinely
    // grown is the live value, not the memory of a smaller one.
    return remembered ? Math.max(remembered, live) : live;
}

// Published to CSS so the panes can be pinned to the screen rather than to dvh, which
// is the same thing right up until the moment it is not. Written only when it changes:
// this is on the per-frame tracking path, and a style write that changes nothing is
// still a style invalidation.
let kbPublishedScreenH = 0;
function publishScreenHeight(px) {
    if (px === kbPublishedScreenH) return;
    kbPublishedScreenH = px;
    document.documentElement.style.setProperty('--app-screen-h', `${px}px`);
}

let kbInsetTarget = 0;    // how tall the keyboard is
let kbShiftTarget = 0;    // how far the app actually has to move, which is not the same
let kbGeometryInset = 0;  // the shift the layout is currently built for
let kbSlideFrom = 0;      // the transform state, tracked so a retarget can start from
let kbSlideTo = 0;        // wherever the running animation had actually got to
let kbSlideStart = 0;
let kbSlideMs = 0;
let kbSlideEase = KEYBOARD_SHOW_EASE;
let kbSlideAnims = [];
let kbSlideToken = 0;
let kbPredictionTimer = 0;

// --- Remembering the keyboard --------------------------------------------------
// Keyed by the laid-out height, which already encodes both the device and the
// orientation -- the only two things a keyboard's height depends on. A phone that has
// been rotated therefore has two entries and predicts correctly in both.
function keyboardMemorySlot() {
    return String(Math.round(kbLaidOutCache || laidOutViewportHeight()));
}

function recallKeyboardInset() {
    try {
        const all = JSON.parse(localStorage.getItem(KEYBOARD_MEMORY_KEY) || '{}');
        const px = all[keyboardMemorySlot()];
        return typeof px === 'number' && px > KEYBOARD_MIN_INSET ? px : 0;
    } catch (e) {
        return 0;
    }
}

function rememberKeyboardInset(px) {
    try {
        const all = JSON.parse(localStorage.getItem(KEYBOARD_MEMORY_KEY) || '{}');
        if (all[keyboardMemorySlot()] === px) return;
        all[keyboardMemorySlot()] = px;
        localStorage.setItem(KEYBOARD_MEMORY_KEY, JSON.stringify(all));
    } catch (e) {
        // Private mode, or the quota is full. The prediction just stays cold and the
        // keyboard behaves the way it did before it was ever measured.
    }
}

// --- WHICH chat is on screen ---------------------------------------------------
//
// Every measurement in this section is taken against the composer and the thread, so
// finding the WRONG ones is not a slightly-off result -- it is a measurement of a box
// that is display:none, which reads as zero and settles on "the app does not have to
// move anywhere".
//
// .mobile-chat-active is left behind on .messages-container when you navigate away
// from a DM: routing does not clear it (see the note in the /messages handler, which
// clears it by hand for exactly this reason), and #messages-page comes BEFORE
// #lounge-page in the markup. So a query that asks only for .mobile-chat-active finds
// the hidden DM composer while the LOUNGE is the thing on screen, measures a zero-sized
// box, and concludes the lounge needs no room for the keyboard. That is the lounge
// bug. Requiring the page to be .active is what makes the answer the chat the user is
// actually looking at.
// The lounge pane can now be inside #messages-page as well, and BOTH panes are
// children of the same .mobile-chat-active container there. That is the trap:
// querySelector returns the first match in DOCUMENT order, not in selector
// order, and .active-chat-pane comes before #msg-lounge-content in the markup.
// So in lounge mode a selector that merely listed both panes handed back the DM
// pane -- display:none, and therefore zero-sized -- and everything downstream
// measured that: keyboardSlideParts() got #chat-body and the DM composer,
// measureKeyboardShift() read a composer with no height, the gap to the top of
// the keyboard came out as nothing to close, and the lounge did not move.
// Exactly the failure described in the note above, one level in.
//
// display:none is not enough to disambiguate, because a selector matches a
// hidden element just as happily as a shown one. So the MODE is named instead:
// #messages-page carries .is-lounge-mode for precisely as long as the lounge is
// the thing in it, which makes the three branches mutually exclusive by
// construction rather than by hoping one of them is hidden.
const KB_PANE_SELECTOR =
    '#messages-page.active:not(.is-lounge-mode) .mobile-chat-active .active-chat-pane, ' +
    '#messages-page.active.is-lounge-mode .mobile-chat-active .active-lounge-pane, ' +
    '#lounge-page.active .mobile-chat-active .active-lounge-pane';

const KB_COMPOSER_SELECTOR =
    '#messages-page.active:not(.is-lounge-mode) .mobile-chat-active .active-chat-pane .chat-input, ' +
    '#messages-page.active.is-lounge-mode .mobile-chat-active .active-lounge-pane #lounge-input, ' +
    '#lounge-page.active .mobile-chat-active .active-lounge-pane #lounge-input';

// Does THIS layout make room by sliding, or by shrinking?
//
// The slide exists only under the phone stylesheet's `@media (max-width: 768px)`
// block: that is where the panes are pinned to a full screen and the thread and
// composer are translated inside them. Above 768px -- an iPad, or a phone turned on
// its side, which reports 844-932px wide -- the panes are ordinary flex children of a
// page that is itself height-locked, and the mechanism is .kb-shell shrinking that
// page instead.
//
// Without this gate the queries above still match in landscape (the class is on the
// container whatever the width), so applyKeyboardGeometry() was told a slide was
// running, suppressed the shrink on that basis -- and then nothing made room at all,
// because the slide rules it was deferring to are not in effect at that width. That is
// the landscape bug, on DMs and lounges alike.
function keyboardSlidesHere() {
    // ...and never on an iPad, whatever the layout. See isIpadOS() for why the
    // platform is the right question here, and keyboardShrinksColumn() below for what
    // runs instead.
    //
    // The failure this prevents is worth stating, because the end state always looked
    // correct and only the transition was wrong -- which makes it easy to "fix" by
    // staring at the wrong frame. iPadOS moves the visual viewport itself as the
    // keyboard comes up. Our slide translates the thread and the composer at the same
    // time, over the same 285ms, and the two compose: the app jumps up, overshoots,
    // shows a band of empty page above the header where it has been dragged off the
    // top, and then snaps back as the measurement lands. Android does not do this,
    // because Chrome leaves the visual viewport alone and the slide is the only thing
    // moving.
    return isPhoneLayout() && !isIpadOS();
}

// The other mechanism: the app holds still and ONE region gets shorter. The exact
// counterpart to keyboardSlidesHere(), and mutually exclusive with it -- between them
// they decide, for every combination of device and layout, which of the two ways of
// making room for a keyboard is in use.
//
// It covers two cases that look different and are the same thing:
//
//   - The SIDE-BY-SIDE layout (iPad landscape, and a desktop if one ever raised a
//     software keyboard). There is a second column on screen -- the conversation list,
//     the nav rail -- and it must not move. Only the column with a composer in it
//     gets shorter.
//
//   - An iPad in the PHONE layout, i.e. portrait. There is no second column here, so
//     the slide would be structurally fine; it is iPadOS that makes it wrong. Shrinking
//     the conversation is the same end state the slide was reaching for, arrived at
//     without asking the OS to hold still while we animate over the top of it.
//
// Recomputed on every call rather than cached at navigation time, for the same reason
// keyboardSlidesHere() is: leaving the page while the keyboard is still up is exactly
// what a one-shot value would miss.
function keyboardShrinksColumn() {
    if (isPhoneLayout() && !isIpadOS()) return false;
    return KEYBOARD_PANE_PAGES.some(id => {
        const page = document.getElementById(id);
        return page && page.classList.contains('active');
    });
}

// The colour of the strip the app stops covering if our slide runs even slightly ahead
// of the keyboard. Read off the composer itself rather than hard-coded, because every
// chat theme paints its own bar, and read once per keyboard: it cannot change while the
// keyboard is up, and getComputedStyle mid-slide is a forced style resolution.
function publishKeyboardUnderlay() {
    const bar = document.querySelector(KB_COMPOSER_SELECTOR)
        || document.querySelector('#messages-page.active:not(.is-lounge-mode) .chat-input');
    if (!bar) return;
    const fill = getComputedStyle(bar).backgroundColor;
    // A transparent composer would publish "transparent" and put us back to showing
    // whatever is behind it, which is the bug. Leave the default in place instead.
    if (!fill || fill === 'transparent' || /,\s*0\)$/.test(fill)) return;
    document.documentElement.style.setProperty('--kb-underlay', fill);
}

// The two things that move. Everything else in the pane -- the header, the wallpaper,
// the pane itself -- holds still, which is why the theme background no longer rescales:
// the box it is painted into never changes size.
function keyboardSlideParts() {
    if (!keyboardSlidesHere()) return [];
    const pane = document.querySelector(KB_PANE_SELECTOR);
    if (!pane) return [];
    return [
        pane.querySelector('#chat-body, #lounge-body'),
        pane.querySelector('.chat-input, #lounge-input')
    ].filter(Boolean);
}

// The one layout change per keyboard, and it is invisible when it happens.
//
// The thread gains the keyboard's height as top padding, so that once it is translated
// up by that same amount the top of the conversation is still reachable instead of
// being swallowed by the header. On its own that would shove the whole thread down by
// the height of a keyboard; adding the same amount to scrollTop cancels it exactly, and
// the browser clamps that write for us in the one case where it should not apply in
// full -- a thread too short to scroll, where the padding has nowhere to push anything.
// Returns how far the app actually has to move, which is NOT the same thing as how
// tall the keyboard is, and every previous version of this got broken by assuming it
// was.
//
// The composer has to end up sitting on top of the keyboard. How far it has to travel
// to get there depends on where it is NOW -- and that depends on the whole cascade
// above it: four nested boxes, a dozen rules across this stylesheet setting heights on
// them, and a couple more that fire only when a keyboard is up. Predict that from a
// reading of the CSS and you will be wrong somewhere, and being wrong here does not
// degrade gracefully: if something else already moved the composer up by the keyboard's
// height, translating it by the keyboard's height AGAIN lands it near the top of the
// screen with the thread crushed to a sliver above it and the pane's wallpaper filling
// the gap. Which is exactly the reported bug, twice over.
//
// So stop predicting it. Measure where the composer is, measure where the keyboard is,
// and move it by the difference. If nothing else shrank, that difference IS the
// keyboard's height and this behaves as designed. If something else already shrank the
// app, the difference is zero and this does nothing rather than doubling it. It cannot
// double-apply, because it is not applying a number -- it is closing a gap.
function measureKeyboardShift(inset) {
    // Queried directly rather than taken by index out of keyboardSlideParts(): that
    // list drops anything missing, so an absent thread would silently make parts[1]
    // the composer's slot hold nothing, or worse, the thread.
    if (!keyboardSlidesHere()) return 0;
    const composer = document.querySelector(KB_COMPOSER_SELECTOR);
    if (!composer) return 0;

    const laidOut = kbLaidOutCache || laidOutViewportHeight();
    let keyboardTop = laidOut - inset;

    // laidOut and inset are both whole pixels, rounded independently, and the real top
    // of the keys is not -- so `laidOut - inset` can sit up to a pixel below it, and the
    // composer stopped that far short: a hairline of thread showing between the bar and
    // the keys. When the live visual viewport is the measurement this inset came from
    // (not a prediction, not a panel holding the slot with the keys down), its bottom
    // edge IS the top of the keyboard, to the sub-pixel, so use that.
    let exact = false;
    const vv = window.visualViewport;
    if (vv) {
        const visible = Math.min(vv.height, window.innerHeight);
        if (Math.abs((laidOut - visible) - inset) <= 1.5) {
            keyboardTop = visible;
            exact = true;
        }
    }

    // Where the composer would be with no slide applied. The running animation is
    // holding it somewhere, so add back whatever it is holding. Read off the
    // element's own computed transform (which reflects a running Web Animation)
    // rather than keyboardSlideNow()'s re-evaluation of the curve: that estimate
    // runs on the main-thread clock, and on iOS it was the suspect for the
    // composer landing ~45px short -- behind Safari's form bar -- while every
    // keyboard number read correct. keyboardSlideNow() stays as the fallback.
    let holding = keyboardSlideNow();
    try {
        const t = getComputedStyle(composer).transform;
        holding = t && t !== 'none' ? -new DOMMatrixReadOnly(t).m42 : 0;
    } catch (e) { /* no DOMMatrix: keep the estimate */ }
    // ...and add back the DOCUMENT scroll too. iOS scrolls the whole page to bring a
    // focused field above the keys (see unscrollChatShell), and when this measurement
    // landed inside that scroll the composer already read as sitting on the keyboard:
    // shift 0, then the page was put back and the composer fell behind the keys. The
    // overlay caught it exactly -- tgt 403, shift 0. unscrollChatShell() is about to
    // undo that scroll, so the resting position is the one without it.
    const scroller = document.scrollingElement || document.documentElement;
    const docScroll = Math.max(0, (scroller && scroller.scrollTop) || 0, window.scrollY || 0);
    const restingBottom = composer.getBoundingClientRect().bottom + holding + docScroll;
    const raw = restingBottom - keyboardTop;

    // Snapped DOWN to a device pixel when exact: a sliver of the bar tucked under the
    // keys is invisible, a sliver of gap above them is the bug.
    const dpr = window.devicePixelRatio || 1;
    const shift = exact ? Math.floor(raw * dpr) / dpr : Math.round(raw);

    // Never negative -- pulling the composer DOWN into the keyboard is never the answer.
    // Capped at the keyboard's height, PLUS however far the composer's resting bottom
    // sits below the screen's: a pane laid out a little taller than the screen (a
    // stale 100dvh, a 55px header offset counted twice) rests its composer partly off
    // the bottom, and a flat `inset` cap then stopped it exactly that far short of the
    // keys. The +1 is inset's own rounding: capping at exactly inset would put back the
    // very gap the exact measurement removed.
    const overhang = Math.max(0, Math.min(restingBottom - laidOut, laidOut * 0.25));
    return Math.max(0, Math.min(inset + overhang + 1, shift));
}

function applyKeyboardGeometry(inset) {
    const root = document.documentElement;

    // How far each thread is standing off its own bottom edge, captured HERE -- before
    // a single class or custom property below is touched.
    //
    // The placement is the whole point. The top padding this function exists to
    // compensate for is applied by `html.kb-open`, so the teardown branch dropping
    // .kb-open removes the padding, which shortens the scroll range, which makes the
    // browser clamp scrollTop -- all of it before the old code got anywhere near
    // reading it. It then read that already-corrected position and subtracted the shift
    // from it a second time, which is the thread coming back higher than it started.
    //
    // Distance-from-the-bottom rather than scrollTop, for the same reason: it is the
    // invariant this design is actually stated in terms of -- whatever was against the
    // bottom edge stays against it -- and it is the one that survives the scroll range
    // changing underneath it. Restoring a raw scrollTop cannot, because the number it
    // wants to restore may no longer be reachable.
    const threads = [];
    if (keyboardSlidesHere() || keyboardShrinksColumn()) {
        document
            .querySelectorAll(
                '#messages-page.active:not(.is-lounge-mode) .active-chat-pane #chat-body, ' +
                // The lounge thread, in EITHER host. Named for #messages-page as
                // well because the pane moves there with the switch, and a thread
                // this does not find is a thread whose scroll position is not put
                // back after the keyboard closes. Mode-scoped like the selectors
                // above, so the hidden pane's zero-sized thread is never collected.
                '#messages-page.active.is-lounge-mode .active-lounge-pane #lounge-body, ' +
                '#lounge-page.active .active-lounge-pane #lounge-body'
            )
            .forEach(el => threads.push([
                el,
                el.scrollHeight - el.scrollTop - el.clientHeight
            ]));
    }

    if (inset > 0) {
        root.style.setProperty('--keyboard-inset', `${inset}px`);
        root.style.setProperty(
            '--app-vh',
            `${Math.round((kbLaidOutCache || laidOutViewportHeight()) - inset)}px`
        );
        root.classList.add('kb-open');

        // .kb-shell resizes the shell, which is the OTHER way of making room for a
        // keyboard and belongs only to pages that have nothing to slide -- login,
        // terminal, search, and the iPad's side-by-side layout. The discriminator is
        // the slide itself: if this page has a thread and a composer to translate, that
        // is the mechanism, and resizing underneath it as well is the double-apply.
        //
        // measureKeyboardShift() would absorb it even if this were wrong. Both are here
        // because one of them being right is not worth relying on.
        const sliding = keyboardSlideParts().length > 0;

        // Recomputed here rather than at navigation time: leaving the chat while the
        // keyboard is still up is the exact case a one-shot update would miss.
        const onShell = KEYBOARD_SHELL_PAGES.some(id => {
            const page = document.getElementById(id);
            return page && page.classList.contains('active');
        });

        // ...with one carve-out. The phone's messages and lounge pages are never
        // shrunk, whether or not a thread happens to be open on them. Searching the
        // chat list, or the lounge's channel list, is the case where `sliding` is false
        // because there is no composer -- and shrinking there is what put the list into
        // the top half of the screen and left the rest of it as empty space you could
        // scroll to. The list is a list: leaving it full height simply runs it behind
        // the keyboard, which is what a keyboard is supposed to do to a list.
        const phoneOverlay = isPhoneLayout() && ['messages-page', 'lounge-page']
            .some(id => {
                const page = document.getElementById(id);
                return page && page.classList.contains('active');
            });

        // The side-by-side layout's answer to the same question, and it is the same
        // answer: hold the app still, make room in one region. See
        // KEYBOARD_PANE_PAGES for why the shell shrink was the wrong tool here.
        //
        // Gated on the LAYOUT, not on the device: this is about there being a second
        // column on screen that must not move, which is exactly what isPhoneLayout()
        // being false means. An iPad in portrait is running the phone layout and takes
        // the phone's path above, keyboard hardware or not.
        const paneShrink = keyboardShrinksColumn();

        root.classList.toggle('kb-column', paneShrink);
        // Mutually exclusive with the above. Two mechanisms making room for the same
        // keyboard is the double-apply that leaves the composer a keyboard's height
        // above where it belongs.
        root.classList.toggle('kb-shell', onShell && !sliding && !phoneOverlay && !paneShrink);
    } else {
        root.classList.remove('kb-open', 'kb-shell', 'kb-column');
        root.style.removeProperty('--keyboard-inset');
        root.style.removeProperty('--app-vh');
    }

    // Measured AFTER the classes above, because they are part of what decides where the
    // composer is. This forces a layout; it happens once per keyboard, not per frame.
    const shift = inset > 0 ? measureKeyboardShift(inset) : 0;
    if (shift === kbGeometryInset) {
        kbShiftTarget = shift;
        return shift;
    }

    if (shift > 0) {
        root.style.setProperty('--kb-shift', `${shift}px`);
    } else {
        root.style.removeProperty('--kb-shift');
    }

    // Put each thread back the same distance off its bottom edge. With the padding now
    // taller (or shorter) by exactly the change in shift, this lands on the same
    // scrollTop the old arithmetic aimed for -- and where the browser has clamped the
    // range, on the nearest position that actually exists instead of past the end of it.
    threads.forEach(([el, fromBottom]) => {
        el.scrollTop = el.scrollHeight - el.clientHeight - fromBottom;
    });
    kbGeometryInset = shift;
    kbShiftTarget = shift;
    return shift;
}

// Where the transform actually is right now. The animation owns the real value on the
// compositor, so rather than ask for it back across that boundary -- which means a
// forced style resolution mid-slide -- the same curve is evaluated against the same
// clock. A retarget then starts from where the eye currently is, not from where the
// last animation was headed.
function keyboardSlideNow() {
    if (!kbSlideMs) return kbSlideTo;
    const t = Math.min(1, (performance.now() - kbSlideStart) / kbSlideMs);
    if (t >= 1) return kbSlideTo;
    return kbSlideFrom + (kbSlideTo - kbSlideFrom) * cubicBezierEase(
        kbSlideEase[0], kbSlideEase[1], kbSlideEase[2], kbSlideEase[3], t
    );
}

// The last word on whether the composer is actually on the keys. Once a slide has
// landed, compare where the composer's bottom edge IS with the top of the keyboard
// the visual viewport reports, and if they disagree by more than a couple of pixels
// re-measure and slide the difference. Everything upstream predicts; this looks.
// Bounded to two corrections per keyboard so a measurement that keeps disagreeing
// can never turn into an animation loop.
let kbLandingCorrections = 0;
function verifyKeyboardLanding() {
    if (kbLandingCorrections >= 2 || kbInsetTarget <= 0 || !keyboardSlidesHere()) return;
    const vv = window.visualViewport;
    const composer = document.querySelector(KB_COMPOSER_SELECTOR);
    if (!vv || !composer) return;

    // Only against a live reading: while the estimate or a panel is holding the
    // slot, the viewport is not where the keys are and has nothing to say.
    const laidOut = kbLaidOutCache || laidOutViewportHeight();
    const visible = Math.min(vv.height, window.innerHeight);
    if (Math.abs((laidOut - visible) - kbMeasuredInset) > 1.5) return;

    const gap = composer.getBoundingClientRect().bottom - visible;
    if (Math.abs(gap) <= 2) return;

    kbLandingCorrections++;
    const shift = applyKeyboardGeometry(kbInsetTarget);
    if (shift !== kbSlideTo) runKeyboardSlide(shift, true);
}

function runKeyboardSlide(to, opening) {
    const from = keyboardSlideNow();
    kbSlideAnims.forEach(a => { try { a.cancel(); } catch (e) { /* already gone */ } });
    kbSlideAnims = [];

    // Scaled by how far is actually left to travel, so a correction three quarters of
    // the way through a slide is a correction and not a second full-length animation.
    //
    // Except with a hardware keyboard, where there is no slide to follow: the
    // shortcuts bar is simply there on focus and gone on blur, in one frame. Easing a
    // 55px step over most of a third of a second only adds a lag the user can see --
    // and the thing this exists to match is exactly what a PC does not do.
    const span = Math.max(1, Math.max(from, to));
    const ms = hasHardwareKeyboard() ? 1 : Math.max(
        KEYBOARD_MIN_TWEEN_MS,
        (opening ? KEYBOARD_SHOW_MS : KEYBOARD_HIDE_MS) * (Math.abs(to - from) / span)
    );
    const ease = opening ? KEYBOARD_SHOW_EASE : KEYBOARD_HIDE_EASE;

    kbSlideFrom = from;
    kbSlideTo = to;
    kbSlideStart = performance.now();
    kbSlideMs = ms;
    kbSlideEase = ease;

    const root = document.documentElement;
    root.classList.add('kb-sliding');
    const token = ++kbSlideToken;

    keyboardSlideParts().forEach(el => {
        kbSlideAnims.push(el.animate(
            [
                { transform: `translate3d(0, ${-from}px, 0)` },
                { transform: `translate3d(0, ${-to}px, 0)` }
            ],
            // fill: forwards, because the transform has to HOLD for as long as the
            // keyboard is up -- this animates the change, it does not describe a
            // temporary effect that should snap back when it finishes.
            { duration: ms, easing: `cubic-bezier(${ease.join(', ')})`, fill: 'forwards' }
        ));
    });

    setTimeout(() => {
        if (token !== kbSlideToken) return;   // a newer slide owns these elements now
        if (kbSlideTo !== 0) {                // still holding the app above a keyboard
            verifyKeyboardLanding();
            return;
        }
        // A slide to 0 while a keyboard IS up is the failure itself (tgt 403, shift 0),
        // not a keyboard going away -- check it rather than filing it as "at rest".
        if (kbInsetTarget > 0) {
            verifyKeyboardLanding();
            if (kbSlideTo !== 0) return;
        }
        kbLandingCorrections = 0;
        // Back at rest: drop the fills so these go back to having no transform at all,
        // rather than each keeping a compositor layer for the rest of the session.
        kbSlideAnims.forEach(a => { try { a.cancel(); } catch (e) { /* already gone */ } });
        kbSlideAnims = [];
        kbSlideMs = 0;
        root.classList.remove('kb-sliding');
    }, ms + 30);
}

function setKeyboardInsetTarget(target) {
    if (Math.abs(target - kbInsetTarget) < 1) return;
    const opening = target > kbInsetTarget;
    if (kbInsetTarget <= 0 && target > 0) publishKeyboardUnderlay();
    kbInsetTarget = target;

    // Order matters: the geometry has to be in place before the transform that hides it
    // starts, or the padding lands a frame late and the thread visibly jumps.
    //
    // And the slide is driven by what applyKeyboardGeometry MEASURED, not by the
    // keyboard's height -- that is the whole point of measuring it. Where something
    // else has already made room, the measured shift is smaller (or zero) and the slide
    // shrinks to match instead of stacking on top.
    const shift = applyKeyboardGeometry(target);
    runKeyboardSlide(shift, opening);
}

// Start the slide on the tap, using what this device's keyboard measured last time.
// Nothing is guessed: with no measurement on record this does nothing at all and the
// keyboard behaves exactly as it did before, which is what happens once, on the very
// first keyboard a device ever opens.
function predictKeyboardOpen() {
    if (!isPhoneLayout()) return;
    // Measured, not the combined target: with a panel open the target is already up,
    // and that must not read as "the keyboard is up" -- swapping the panel back for the
    // keyboard is exactly the case this has to predict.
    if (kbMeasuredInset > 0) return;
    const remembered = recallKeyboardInset();
    if (!remembered) return;

    clearTimeout(kbPredictionTimer);
    kbPredictionTimer = setTimeout(() => {
        kbPredictionTimer = 0;
        syncKeyboardViewport();   // no keyboard ever appeared -- put it back
    }, KEYBOARD_PREDICTION_GRACE_MS);

    kbMeasuredInset = remembered;
    applyKeyboardInsets();
}

// Pin the app to the screen BEFORE the browser has a chance to shrink anything.
//
// interactive-widget=resizes-content means Chrome shrinks the layout viewport, and it
// does so whole, on the first frame of the IME slide. Everything that would follow it
// down is pinned to --app-screen-h -- but only while .kb-open, .kb-sliding or this
// class is set, and the first two are set from a MEASUREMENT, which by definition
// arrives after the resize we are trying to get in front of.
//
// This is the one that does not wait to be told. It goes on at the tap, unconditionally
// -- no remembered inset required, so it covers the very first keyboard a device ever
// opens, which is exactly the case predictKeyboardOpen() cannot help with. If no
// keyboard turns up, it costs a height that was already the height it had.
function armKeyboardOverlay() {
    if (!hasSoftKeyboard()) return;
    document.documentElement.classList.add('kb-arming');
}

function disarmKeyboardOverlay() {
    document.documentElement.classList.remove('kb-arming');
}

// --- One slot, shared by the keyboard and the composer's panels -----------------
//
// The emoji and sticker panels are not overlays that happen to live near the
// composer. They ARE the keyboard's slot with different contents -- which is what
// every native messenger does, and the only arrangement in which swapping between
// them does not throw the conversation up and down the screen.
//
// So an open panel holds the app up by exactly what the keyboard was holding it up
// by. Opening one takes the real keyboard down, but the TARGET never changes, so no
// slide runs at all: the keyboard's pixels are replaced by the panel's, in place.
// Closing it, or tapping the text field to bring the keyboard back, is the same
// exchange in reverse.
//
// Two inputs, one target. kbMeasuredInset is what the browser reports; kbPanelInset
// is what an open panel is asking for; the app is lifted by whichever is larger.
// Nothing else may call setKeyboardInsetTarget directly -- going around the max() is
// how one of the two ends up cancelling the other.
const COMPOSER_PANELS = [
    '#emoji-panel',
    '#lounge-emoji-panel',
    '#notice-emoji-panel',
    '#dm-sticker-popup',
    '#lounge-sticker-popup',
    '#notice-sticker-popup'
];

// Each panel and the button that opens it. A click inside either is not an
// "outside" click -- without the button in this list, the tap that opens a panel
// would immediately close it again on the way back up.
const COMPOSER_PANEL_TRIGGERS = {
    '#emoji-panel': '#emoji-btn',
    '#lounge-emoji-panel': '#lounge-emoji-btn',
    '#notice-emoji-panel': '#notice-emoji-btn',
    '#dm-sticker-popup': '#dm-stickers-btn',
    '#lounge-sticker-popup': '#lounge-stickers-btn',
    '#notice-sticker-popup': '#notice-sticker-btn',
};

function closeComposerPanelsOnOutsideClick(clickedElement) {
    if (!clickedElement) return;
    for (const [panelSel, triggerSel] of Object.entries(COMPOSER_PANEL_TRIGGERS)) {
        const panel = document.querySelector(panelSel);
        if (!panel || panel.classList.contains('hidden')) continue;
        if (clickedElement.closest(panelSel) || clickedElement.closest(triggerSel)) continue;
        hideComposerPanelEl(panel);
    }
    syncComposerPanelInset();
}

// Used only until this device has measured a keyboard once, which is the single
// occasion there is nothing better to match. Every open after that is the real height,
// so the panel and the keyboard are the same size and the swap is invisible.
const COMPOSER_PANEL_FALLBACK_H = 280;

let kbMeasuredInset = 0;
let kbPanelInset = 0;

const COMPOSER_PANEL_SELECTOR = COMPOSER_PANELS.join(', ');

// The one place the two insets become a number.
//
// Normally they are alternatives -- keyboard OR panel, whichever is asking for more --
// because they are two things wanting the same strip. The exception is a field INSIDE a
// panel: the emoji and sticker search boxes. There the keyboard is not replacing the
// panel, it is arriving on top of it, and a max() would put the keyboard exactly over
// the panel it is meant to be filtering. So they stack, and the panel rides up to sit
// directly above the keys.
//
// Capped, because two of them is most of a phone. Whatever happens, the composer stays
// far enough down the screen to leave the header and a line of conversation visible;
// past that the panel is better off partly covered than the chat being gone entirely.
function applyKeyboardInsets() {
    const focused = document.activeElement;
    const inPanel = kbPanelInset > 0 && kbMeasuredInset > 0 &&
        isTextEntryElement(focused) && focused.closest(COMPOSER_PANEL_SELECTOR);

    let target = inPanel
        ? kbMeasuredInset + kbPanelInset
        : Math.max(kbMeasuredInset, kbPanelInset);

    // Capped so the composer stays far enough down the screen to leave the header and a
    // line of conversation visible. Proportional, not a flat 160px: in landscape the
    // whole screen is only ~390-430px tall, and reserving 160 of it clamps a perfectly
    // ordinary keyboard down to less than its own height -- which lands the composer
    // back underneath the keys, the exact failure the cap is nowhere near important
    // enough to cause. A quarter of the screen is the same reservation in portrait and
    // a proportionate one on its side.
    const screen = kbLaidOutCache || laidOutViewportHeight();
    if (screen > 0) {
        const reserve = Math.min(160, Math.round(screen * 0.25));
        target = Math.min(target, Math.max(0, screen - reserve));
    }

    setKeyboardInsetTarget(target);
}

function openComposerPanelEl() {
    return document.querySelector(COMPOSER_PANELS.map(sel => `${sel}:not(.hidden)`).join(', '));
}

// Called after anything that might have shown or hidden a panel, and it READS the DOM
// rather than being told which happened. These panels are opened and closed from half
// a dozen places -- their own buttons, the outside-click handler, focusing the field,
// leaving the chat -- and a rule that has to be remembered at every one of them is a
// rule that will be forgotten at one of them.
function syncComposerPanelInset() {
    const root = document.documentElement;
    // Phone only. On a desktop or an iPad's side-by-side layout the panels are
    // floating popovers next to a composer nothing is lifting, and there is no slot.
    const panel = isPhoneLayout() ? openComposerPanelEl() : null;

    // Before the early return below, not after: swapping one panel for the other leaves
    // the inset identical, and that is exactly the case where the entry has to be
    // re-pointed at the new occupant.
    syncComposerPanelHistory(panel);

    const next = panel ? (recallKeyboardInset() || COMPOSER_PANEL_FALLBACK_H) : 0;
    if (next === kbPanelInset) return;

    kbPanelInset = next;
    if (next > 0) {
        root.style.setProperty('--kb-panel-h', `${next}px`);
        root.classList.add('kb-panel');
    } else {
        root.classList.remove('kb-panel');
        root.style.removeProperty('--kb-panel-h');
    }
    applyKeyboardInsets();
}

// What the panel took the slot FROM, remembered at the moment it took it. Back has to
// put the previous surface back, and by the time back is pressed there is nothing left
// on screen to work it out from -- the field has been blurred and the keyboard is
// already gone.
let kbPanelReturnField = null;

function hideComposerPanelEl(el) {
    if (!el || el.classList.contains('hidden')) return false;
    el.classList.add('hidden');
    return true;
}

// A panel covering the bottom third of the screen is something the back button should
// get you out of, not something it should navigate past. It takes the same throwaway
// history entry the image and post modals already use, so back spends itself on closing
// the panel and the conversation underneath stays put.
//
// ONE entry for the SLOT, though, not one per panel. Swapping stickers for emoji is not
// a navigation -- the same strip stays open with different contents, and back should
// still close it once rather than twice. It also must not pop one entry while pushing
// another: popModalHistory ends in history.go(), pushState lands immediately, and the
// two racing each other is how the recorded depth drifts away from the real one.
//
// So the entry is found by its close function (unique to the slot) and re-pointed at
// whichever panel now occupies it. The id has to keep up, because the popstate handler
// validates the top entry by looking its element up and checking it is still on screen:
// an entry still naming the panel that just closed reads as stale and is thrown away,
// quietly eating the back press it was supposed to answer.
function syncComposerPanelHistory(panel) {
    const entry = modalHistoryStack.find(e => e.close === dismissComposerPanel);
    if (panel && panel.id) {
        if (entry) entry.id = panel.id;
        else pushModalHistory(panel.id, dismissComposerPanel);
    } else if (entry) {
        popModalHistory(entry.id);
    }
}

// Opening a panel has to take the keyboard down -- the panel is drawn in the strip the
// keyboard is physically sitting on, so leaving it up would draw the panel underneath
// it. Blurring is what does that, and it happens AFTER the panel has claimed the slot,
// never before: claim first and the target never dips, so the slide never starts.
// Do it the other way round and you get the drop-then-rise this replaced.
function showComposerPanel(panelEl) {
    // Captured before the blur below, which is the last moment either of these is still
    // true. Two signals rather than one: the field is what focus will be handed back
    // to, and the inset is what says a keyboard was actually up rather than a field
    // merely being focused with a hardware keyboard attached.
    const focused = document.activeElement;
    kbPanelReturnField = (kbMeasuredInset > 0 && isTextEntryElement(focused)) ? focused : null;

    syncComposerPanelInset();
    if (isTextEntryElement(focused)) focused.blur();
}

// The back button's own close. Not just "hide it" -- put back whatever the panel
// displaced, which is the entire difference between this and closeComposerPanels().
//
// Focus first, close second, and for the same reason as everywhere else in here:
// focusing the field runs the focusin handler, which raises the keyboard's target
// BEFORE the panel gives up its own. Close first and the target hits zero in between,
// which is a slide down immediately followed by a slide back up.
//
// Whether the browser actually raises the IME from here is its call, not ours -- a
// hardware back press carries no user activation, and a page cannot force a keyboard
// up without one. If it declines, the prediction's grace timer notices no keyboard
// arrived and settles the app full screen with the caret in the field, which is the
// same place the other branch lands. There is no third outcome to design for.
function dismissComposerPanel() {
    const restore = kbPanelReturnField;
    kbPanelReturnField = null;

    if (restore && restore.isConnected) {
        restore.focus();
        closeComposerPanels();   // no-op if focusin already did it
        return;
    }
    closeComposerPanels();
}

// Focus that must NOT be read as "the user left the panel".
//
// The focusin handler's job is to close a panel when focus moves to a field outside it,
// because that means the keyboard is being asked for and the two share one slot. But an
// emoji tap also puts focus back in the composer, and that is the panel doing its job,
// not the user leaving it. focus() dispatches focusin synchronously, so a counter held
// across the call is enough to tell the two apart.
let composerPanelFocusGuard = 0;
function focusKeepingComposerPanel(el) {
    if (!el) return;
    composerPanelFocusGuard++;
    try { el.focus(); } finally { composerPanelFocusGuard--; }
}

function closeComposerPanels() {
    let changed = false;
    COMPOSER_PANELS.forEach(sel => {
        if (hideComposerPanelEl(document.querySelector(sel))) changed = true;
    });
    if (changed) {
        kbPanelReturnField = null;
        syncComposerPanelInset();
    }
    return changed;
}

function predictKeyboardClose() {
    clearTimeout(kbPredictionTimer);
    kbPredictionTimer = 0;
    // Disarmed AFTER, never before. Tearing the geometry down drops .kb-open and reads
    // every thread's scrollTop back, and that read forces a layout -- so if the pin
    // came off first, that layout would be taken against a pane the browser had already
    // shrunk to the keyboard, and the scroll compensation would be computed against a
    // thread that is briefly the wrong height. By the time this line runs the closing
    // slide owns .kb-sliding, which pins the same boxes.
    kbMeasuredInset = 0;
    applyKeyboardInsets();
    disarmKeyboardOverlay();
}

// The keyboard usually opens on a PREDICTION: the remembered inset, before the browser
// has shrunk anything, so measureKeyboardShift() has no live edge to read and falls
// back to whole-pixel arithmetic. When the real measurement lands it is almost always
// the same whole number, and setKeyboardInsetTarget() rightly ignores a change of
// nothing -- which would leave that rounded shift in place for as long as the keyboard
// is up. So once a live edge exists, re-measure against it. Keyed on the visible
// height, so this forces a layout when the keyboard actually moves, not every frame
// of the tracking loop.
let kbRefinedVisible = 0;
// Whether the keyboard now on screen was confirmed by a real measurement, rather than
// only predicted. See the dismissal check in syncKeyboardViewport().
let kbKeyboardConfirmed = false;
function refineKeyboardShift(inset) {
    const vv = window.visualViewport;
    if (!vv || inset <= 0 || kbInsetTarget <= 0) {
        kbRefinedVisible = 0;
        return;
    }
    const visible = Math.min(vv.height, window.innerHeight);
    if (Math.abs(visible - kbRefinedVisible) < 0.05) return;
    kbRefinedVisible = visible;

    const before = kbGeometryInset;
    const shift = applyKeyboardGeometry(kbInsetTarget);
    if (shift !== before) runKeyboardSlide(shift, true);
}

// --- iOS: a keyboard nobody reports ----------------------------------------------
// Everything above measures the keyboard as the gap between the screen and the
// visual viewport. Some iPhones (reported on iOS 26) put the keyboard up without
// the visual viewport shrinking at all, so that gap reads 0 and the chat never
// moves: the composer and the newest messages stay behind the keys.
//
// When a chat composer is focused on an iPhone and a second of per-frame tracking
// has found no keyboard, this lifts the chat by an ESTIMATE of the keyboard's
// height instead -- proportion of the screen, including iOS's form bar above the
// keys. Not exact, but a composer a little high is usable and one behind the
// keyboard is not. It lasts until the field loses focus (the keyboard's check mark
// blurs it), and the device remembers that it needed it, so the next open lifts at
// once instead of after the wait. The first real measurement cancels all of it.
const IOS_KB_FALLBACK_KEY = 'apex_ios_kb_fallback';
const IOS_KB_PORTRAIT = 0.46;
const IOS_KB_LANDSCAPE = 0.62;
let kbIosFallbackInset = 0;
let kbIosFallbackTimer = 0;

function iosKeyboardFallbackEstimate() {
    const screen = screenHeight();
    const portrait = window.innerWidth < screen;
    return Math.round(screen * (portrait ? IOS_KB_PORTRAIT : IOS_KB_LANDSCAPE));
}

function iosKeyboardFallbackKnown() {
    try { return localStorage.getItem(IOS_KB_FALLBACK_KEY) === '1'; } catch (e) { return false; }
}

function forgetIosKeyboardFallback() {
    try { localStorage.removeItem(IOS_KB_FALLBACK_KEY); } catch (e) { /* fine */ }
}

function iosKeyboardFallback(field) {
    clearTimeout(kbIosFallbackTimer);
    if (!/iPhone|iPod/.test(navigator.userAgent || '')) return;
    if (!isPhoneLayout() || !hasSoftKeyboard()) return;
    // Only the chat composers: those are the pages built around lifting for the
    // keyboard. Ordinary forms scroll the field into view on their own.
    const onChat = KEYBOARD_PANE_PAGES.some(id =>
        document.getElementById(id)?.classList.contains('active'));
    if (!onChat) return;

    const engage = () => {
        if (document.activeElement !== field || kbMeasuredInset > 0) return;
        kbIosFallbackInset = iosKeyboardFallbackEstimate();
        try { localStorage.setItem(IOS_KB_FALLBACK_KEY, '1'); } catch (e) { /* fine */ }
        syncKeyboardViewport();
    };
    if (iosKeyboardFallbackKnown()) engage();
    else kbIosFallbackTimer = setTimeout(engage, 1100);
}

// Shown under the build badge (five taps on the corner logo) so a screenshot from
// a phone nobody here owns says what the keyboard measurement actually saw.
let kbDiag = null;
function noteKeyboardDiagnostics(d) {
    kbDiag = d;
    if (!buildBadgeVisible) {
        document.getElementById('apex-kb-diag')?.remove();
        return;
    }
    let el = document.getElementById('apex-kb-diag');
    if (!el) {
        el = document.createElement('div');
        el.id = 'apex-kb-diag';
        el.style.cssText = 'position:fixed;top:calc(env(safe-area-inset-top,0px) + 34px);left:8px;' +
            'z-index:2147483647;padding:4px 8px;border-radius:8px;background:rgba(0,0,0,.72);' +
            'color:#fff;font:11px/1.35 ui-monospace,Menlo,monospace;pointer-events:none;white-space:pre;';
        document.body.appendChild(el);
    }
    paintKeyboardDiagnostics();
    // The shift is decided after this call and the slide runs for ~300ms, so a
    // one-shot paint would always show the frame before. Kept live while shown.
    if (!kbDiagTimer) kbDiagTimer = setInterval(paintKeyboardDiagnostics, 250);
}

let kbDiagTimer = 0;
function paintKeyboardDiagnostics() {
    const el = document.getElementById('apex-kb-diag');
    if (!el || !kbDiag || !buildBadgeVisible) {
        clearInterval(kbDiagTimer);
        kbDiagTimer = 0;
        return;
    }
    const d = kbDiag;
    const vv = window.visualViewport || d.vv;
    const r = n => Math.round(n || 0);

    // What the composer and its pane actually did -- the half of the story the
    // first three lines cannot tell. `cb` is where the composer's bottom edge is
    // on screen now, and it should equal vvH once the slide has landed; `rest` is
    // where it would be with no slide, and rest - vvH is the shift it needed.
    const composer = document.querySelector(KB_COMPOSER_SELECTOR);
    const pane = document.querySelector(KB_PANE_SELECTOR);
    const cRect = composer ? composer.getBoundingClientRect() : null;
    const pRect = pane ? pane.getBoundingClientRect() : null;
    const ty = composer ? (new DOMMatrixReadOnly(getComputedStyle(composer).transform).m42 || 0) : 0;
    const where = document.querySelector('#messages-page.active.is-lounge-mode') ? 'msg-lounge'
        : document.querySelector('#messages-page.active') ? 'msg-dm'
        : document.querySelector('#lounge-page.active') ? 'lounge-page' : 'other';
    const cls = ['kb-open', 'kb-sliding', 'kb-arming', 'kb-shell', 'kb-column']
        .filter(c => document.documentElement.classList.contains(c)).join(',') || '-';

    el.textContent =
        `kb vvH ${r(vv.height)} vvTop ${r(vv.offsetTop)} inH ${r(window.innerHeight)}\n` +
        `laid ${r(d.laidOut)} dvh ${r(laidOutViewportHeight())} raw ${r(d.raw)}\n` +
        `inset ${r(d.inset)}${d.fallback ? ' (est)' : ''} hw ${hasHardwareKeyboard() ? 1 : 0} ` +
        `phone ${isPhoneLayout() ? 1 : 0} focus ${isTextEntryElement(document.activeElement) ? 1 : 0}\n` +
        `tgt ${r(kbInsetTarget)} shift ${r(kbGeometryInset)} now ${r(keyboardSlideNow())} ty ${r(ty)}\n` +
        (cRect ? `cb ${r(cRect.bottom)} ch ${r(cRect.height)} rest ${r(cRect.bottom - ty)}` : 'composer none') +
        (pRect ? ` pane ${r(pRect.top)}-${r(pRect.bottom)}` : ' pane none') + `\n` +
        `${where} ${cls} sa ${getComputedStyle(document.documentElement).getPropertyValue('--app-screen-h').trim() || '-'}`;
}

function syncKeyboardViewport() {
    const vv = window.visualViewport;
    if (!vv) return;

    // What is actually left to draw in. Both terms matter: Safari on iPhone keeps
    // innerHeight at full height and only shrinks the visual viewport, iPad Safari
    // shrinks both, and taking the smaller covers either without asking which is which.
    const visible = Math.min(vv.height, window.innerHeight);

    // Must NOT be documentElement.clientHeight: for the root element that returns the
    // viewport height only while the root can scroll, and the rules this switches on set
    // `overflow: hidden` on <html>. It would then report the height we just shrank to,
    // the measured inset would collapse to 0, and the whole thing would oscillate.
    //
    // offsetTop is deliberately not part of it either. It says where the visual viewport
    // currently sits, not how tall the keyboard is. The keyboard is simply the height
    // the layout has that the visible area does not.
    refreshScreenHeight();
    const laidOut = screenHeight();
    kbLaidOutCache = laidOut;
    publishScreenHeight(laidOut);
    const raw = Math.max(0, Math.round(laidOut - visible));

    // A reading this large is not a keyboard, it is the viewport caught
    // mid-reconfiguration -- which is exactly what an IME being started for the first
    // time produces. The next measurement is along in ~16ms; this one is not worth
    // acting on.
    //
    // The bar used to be 60%, on the reasoning that nothing on a phone takes more than
    // that. In PORTRAIT nothing does. Turn the same phone on its side and the screen is
    // ~390-430px tall while the keyboard is still a keyboard -- 250-280px of it, which
    // is 65-70% -- so every landscape keyboard was thrown away as garbage and the app
    // never made room for one. That is the "horizontal" half of the reported bug. A
    // genuine mid-reconfiguration reading is the whole screen or near enough, so the
    // bar only has to sit below that.
    const measured = raw > laidOut * 0.88 ? kbMeasuredInset : raw;

    // What KIND of gap this is, asked before anything is decided about what to do
    // with it: a keyboard-sized one says the keys are on screen, a bar-sized one
    // held while a field is focused says they are physical. See hasHardwareKeyboard().
    noteKeyboardInsetEvidence(measured);

    // Hysteresis. The bar was only ever a gate -- keyboard, or browser chrome -- asked
    // once against a settled measurement. Applied to a keyboard that is already up it
    // would also swallow the last stretch of any slide that reports its progress, so the
    // full bar is for a keyboard that is DOWN; one already up stays up on much less.
    const gate = hasHardwareKeyboard() && isTextEntryElement(document.activeElement)
        ? KEYBOARD_ACCESSORY_MIN_INSET
        : KEYBOARD_MIN_INSET;
    const floor = kbMeasuredInset > 0 ? gate / 3 : gate;
    let inset = measured > floor ? measured : 0;

    // A real reading always wins over the iOS estimate, and ends it for good on
    // this device (see iosKeyboardFallback below).
    if (inset > KEYBOARD_MIN_INSET && kbIosFallbackInset) {
        kbIosFallbackInset = 0;
        forgetIosKeyboardFallback();
    }
    const usingFallback = inset === 0 && kbIosFallbackInset > 0
        && isTextEntryElement(document.activeElement);
    if (usingFallback) inset = kbIosFallbackInset;
    noteKeyboardDiagnostics({ vv, visible, laidOut, raw, inset, fallback: usingFallback });

    if (inset > KEYBOARD_MIN_INSET && !usingFallback) {
        // The report finally arrived. It confirms the prediction, and it is the number
        // the next open will be predicted from.
        clearTimeout(kbPredictionTimer);
        kbPredictionTimer = 0;
        rememberKeyboardInset(inset);
        kbKeyboardConfirmed = true;
    } else if (kbPredictionTimer) {
        // Predicted, and the keyboard has not been reported yet. This is the normal case
        // for most of a slide -- Chrome says nothing until the IME has finished arriving
        // -- and acting on it would cancel the very animation the prediction exists to
        // start. The grace timer is what ends this wait if no keyboard ever shows up.
        return;
    }

    // The keyboard went away while the field kept focus. That is Android's back
    // button (and iOS's keyboard-hide key): it takes the IME down without blurring
    // anything, so the pickers' blur listeners never hear about it and the @mention
    // or //command panel was left floating over a thread with nothing under it to
    // type into. Tapping the field again re-reads the caret and reopens it.
    //
    // It also left the caret in the field, which is worse than it sounds: anything
    // that later hands focus back to "the field that has focus" -- removing a reply,
    // closing a panel -- brought the keyboard straight back up, when the last thing
    // the user did was put it away. So a dismissed keyboard takes the focus with it.
    // Only for a keyboard that was actually REPORTED on screen: a prediction that
    // never came true (a slow IME, a first open) must not blur a field the user has
    // just tapped into.
    if (kbMeasuredInset > 0 && inset === 0 && !hasHardwareKeyboard()
        && !usingFallback && isTextEntryElement(document.activeElement)) {
        closeMentionPicker();
        closeCommandPicker();
        if (kbKeyboardConfirmed) document.activeElement.blur();
    }
    if (inset === 0) kbKeyboardConfirmed = false;

    kbMeasuredInset = inset;
    applyKeyboardInsets();
    refineKeyboardShift(inset);
    unscrollChatShell();
}

// iOS scrolls the DOCUMENT to bring a focused field above the keyboard, and it does it
// whether or not the page is supposed to be scrollable: `position: fixed` on <body>
// and `overflow: hidden` on <html> stop a finger from scrolling it, they do not stop
// Safari from doing it. On the chat and lounge -- the two pages that are a fixed,
// full-screen shell with their own composer already being lifted -- the result is the
// app sitting a keyboard's height too high, with the header off the top of the screen
// and the composer somewhere in the middle, which reads as the screen having failed to
// make room rather than having made it twice.
//
// Chrome does not do this, which is why this has only ever been an iOS symptom, and it
// is not user-agent gated for the same reason it does not need to be: on a browser that
// never scrolls these pages, the offset is already 0 and this does nothing.
//
// Deliberately NOT applied to the other height-locked pages. Login, signup and the
// terminal are ordinary scrolling forms, and there Safari scrolling a field into view
// is the behaviour, not the bug.
function unscrollChatShell() {
    const onChat = ['messages-page', 'lounge-page'].some(id => {
        const page = document.getElementById(id);
        return page && page.classList.contains('active');
    });
    if (!onChat) return;
    const scroller = document.scrollingElement || document.documentElement;
    const wasScrolled = !!((scroller && scroller.scrollTop) || window.scrollY);
    if (scroller && scroller.scrollTop) scroller.scrollTop = 0;
    if (window.scrollY) window.scrollTo(0, 0);

    // Undoing Safari's scroll moves the composer back down by the same amount, so a
    // shift measured while it was scrolled is now wrong. Measure again, from the page
    // as it really is, and slide the difference.
    if (wasScrolled && kbInsetTarget > 0 && keyboardSlidesHere()) {
        const shift = applyKeyboardGeometry(kbInsetTarget);
        if (shift !== kbSlideTo) runKeyboardSlide(shift, true);
    }
}

// Safari does that scroll on its own schedule -- often AFTER the visual viewport has
// finished resizing, so no viewport event is left to call unscrollChatShell() for it.
// The document's own scroll event is the one signal that always arrives.
window.addEventListener('scroll', () => {
    if (kbInsetTarget > 0 || document.documentElement.classList.contains('kb-arming')) {
        unscrollChatShell();
    }
}, { passive: true });

// The immediate, un-animated teardown. Used on navigation, where there is no keyboard
// slide left to follow and the next page must not inherit a shifted thread.
function clearKeyboardViewport() {
    clearTimeout(kbPredictionTimer);
    kbPredictionTimer = 0;
    kbSlideToken++;
    kbSlideAnims.forEach(a => { try { a.cancel(); } catch (e) { /* already gone */ } });
    kbSlideAnims = [];
    kbSlideFrom = 0;
    kbSlideTo = 0;
    kbSlideMs = 0;
    kbInsetTarget = 0;
    kbMeasuredInset = 0;
    // Close the pickers as well as forgetting their inset. Leaving a chat with the
    // sticker panel open and coming back to find it still open -- but no longer owning
    // the slot, so drawn as the floating popover it used to be -- is the kind of state
    // that only exists because two things were torn down separately.
    // Through closeComposerPanels() rather than hiding them by hand, so the slot's
    // history entry goes with them instead of being left behind to eat a back press.
    closeComposerPanels();
    kbPanelInset = 0;
    applyKeyboardGeometry(0);
    const root = document.documentElement;
    root.classList.remove('kb-sliding', 'kb-arming', 'kb-panel');
    root.style.removeProperty('--kb-panel-h');
    // Re-read on the next open rather than carried across: the chat opened next may
    // well be on a different theme, with a different composer colour.
    root.style.removeProperty('--kb-underlay');
}

// The lock is written as inline !important, so anything left behind outlives the
// navigation and reopens the pane at keyboard height -- the "only the top half is
// there" bug. Always clear BOTH panes rather than the active one: leaving a chat
// with the keyboard still up is precisely the case where the pane has already
// stopped matching the .mobile-chat-active selector by the time we get here.
function clearKeyboardViewportLock() {
    document.querySelectorAll('.active-chat-pane, .active-lounge-pane').forEach(pane => {
        pane.style.removeProperty('height');
        pane.style.removeProperty('top');
    });
}

// --- Returning the soft keyboard to its letter layer ----------------------------
//
// A phone keyboard remembers which PAGE it is on -- letters, numbers, symbols --
// for as long as one field keeps focus. Send a message from the symbols page and
// the next message starts on the symbols page too, which is almost never what was
// wanted: that message is finished, and the next one starts with words.
//
// There is no web API for "reset the keyboard" -- a page cannot read the layer,
// let alone set it. What it CAN do is tell the browser that the field's input
// expectations changed, which makes the browser restart the IME, and a restarted
// IME comes back on its default page.
//
// Deliberately not blur() then focus(), which is the other way to force a restart.
// Blurring drops the keyboard, and everything in this section exists to animate
// that slide: the user would get the whole keyboard closing and reopening just to
// change which page it is on. Changing an attribute keeps focus, so nothing moves
// and none of the prediction machinery above ever hears about it.
//
// The language is untouched, and that is the point. English or Korean is the
// IME's own setting, not the field's, so a restart comes back in whichever one
// was last being typed in.
const keyboardLayerResetting = new WeakSet();
function resetSoftKeyboardLayer(field) {
    // Only while this field still holds focus. If the keyboard is already down
    // there is no layer to reset, and the next focus starts on letters anyway.
    if (!field || document.activeElement !== field) return;
    // Nothing to reset without a soft keyboard: a desktop, or a tablet with a
    // real one attached.
    if (!isTouchUi() || hasHardwareKeyboard()) return;

    // A reset still in flight owns the attribute. Without this, a second send
    // before the frame lands would read the temporary value as the original and
    // "restore" the field to it permanently -- and a frame can be a long time,
    // because requestAnimationFrame does not run at all while the tab is hidden.
    if (keyboardLayerResetting.has(field)) return;

    const original = field.getAttribute('inputmode');
    keyboardLayerResetting.add(field);
    // 'search' rather than 'none'. Both are ordinary text keyboards, so the
    // browser is never asked to hide anything -- 'none' means "no keyboard at
    // all", and asking for that even for one frame invites a dismiss animation.
    field.setAttribute('inputmode', original === 'search' ? 'text' : 'search');

    // Put back a frame later, not immediately. The browser syncs a field's state
    // to the IME once per frame, so a change and its undo inside the same frame
    // is no change at all and nothing restarts.
    requestAnimationFrame(() => {
        keyboardLayerResetting.delete(field);
        if (!field.isConnected) return;
        if (original === null) field.removeAttribute('inputmode');
        else field.setAttribute('inputmode', original);
    });
}

// --- Tap outside to dismiss the keyboard ---------------------------------------
//
// Safari keeps a field focused when the tap lands on something that isn't focusable,
// so on iPad the on-screen keyboard has no way out: it sits over the app until the
// field is blurred, and the only thing in the UI that does that is our own back
// button. Desktop browsers blur on any mousedown over a non-focusable element and
// Chrome on Android drops the keyboard the same way, which is why this only ever
// looked broken on iOS.
//
// So do it by hand: a tap that lands on inert chrome blurs whatever is focused.
// Gated on pointerType === 'touch' -- the mouse path already behaves this way and
// re-implementing it could only add ways to get it wrong.

// Containers whose taps belong to the focused field: the composer and its buttons,
// the emoji and sticker panels, the search bar's own clear/history UI, the mention
// picker. Every one of these acts ON the field and several re-focus it, so blurring
// there would fight the control the user just pressed.
const KEYBOARD_KEEP_SELECTOR = [
    '.chat-input',
    '.apex-search',
    '.emoji-panel',
    '.sticker-popup',
    '.mention-picker',
    '[data-keep-keyboard]'
].join(', ');

// Anything the tap could plausibly activate. The blur happens before the click is
// dispatched, and on iOS the keyboard leaving reflows the page out from under the
// finger -- enough to send that click to a different element or drop it entirely.
// Skipping controls costs nothing: tapping one is not "tapping elsewhere".
const KEYBOARD_INTERACTIVE_SELECTOR =
    'a, button, input, textarea, select, label, summary, [contenteditable], [onclick], ' +
    '[role="button"], [role="option"], [role="tab"], [role="menuitem"], [tabindex]';

const TAP_DISMISS_MOVE_TOLERANCE = 12; // px; above this the finger scrolled, not tapped
const TAP_DISMISS_MAX_MS = 600;        // above this it is a long press, not a tap

function isTextEntryElement(el) {
    if (!el || el === document.body) return false;
    if (el.tagName === 'TEXTAREA') return true;
    if (el.tagName === 'INPUT') {
        return !/^(button|submit|reset|checkbox|radio|file|image|range|color)$/i.test(el.type);
    }
    return el.isContentEditable === true;
}

// Catches the rows, tiles and bubbles that are only clickable through an attached
// listener: nothing in the markup says so, but the stylesheet always does.
function hasPointerCursor(el) {
    for (let node = el; node && node !== document.body; node = node.parentElement) {
        if (getComputedStyle(node).cursor === 'pointer') return true;
    }
    return false;
}

// A tap on a composer control must not move focus.
//
// The browser blurs the focused text field on pointerdown over a button, before the
// button's own handler has run -- which is why sending from the mobile Send button
// used to take the keyboard down with it, and why every panel had to put the keyboard
// back afterwards. preventDefault on pointerdown suppresses the focus change and the
// compatibility mouse events; the click still fires (verified, not assumed).
//
// The two controls that genuinely need the keyboard gone -- emoji and stickers -- take
// it down themselves, deliberately, once their panel already owns the slot.
function initComposerFocusGuard() {
    document.addEventListener('pointerdown', (e) => {
        const target = e.target;
        if (!(target instanceof Element)) return;
        if (!target.closest('.chat-input button, .chat-input .emoji-btn')) return;
        e.preventDefault();
    }, true);
}

function initTapToDismissKeyboard() {
    // Measured at pointerdown, not pointerup: the element under the finger when the
    // gesture STARTED is the one the user meant, and it is the only one still
    // guaranteed to be there.
    let tapStart = null;

    document.addEventListener('pointerdown', (e) => {
        tapStart = e.pointerType === 'touch'
            ? { x: e.clientX, y: e.clientY, at: Date.now(), target: e.target }
            : null;
    }, true);

    // A scroll that steals the gesture cancels the pointer; that is not a tap.
    document.addEventListener('pointercancel', () => { tapStart = null; }, true);

    document.addEventListener('pointerup', (e) => {
        const start = tapStart;
        tapStart = null;
        if (!start || e.pointerType !== 'touch') return;
        // Nothing to dismiss, and blurring would be a regression: with a hardware
        // keyboard the field is where the user is typing, and a stray tap on the
        // conversation must not take that away. A desktop does not do this either --
        // it only looks like it does, because there the browser blurs on mousedown
        // and this handler never runs.
        if (hasHardwareKeyboard()) return;
        if (Date.now() - start.at > TAP_DISMISS_MAX_MS) return;
        if (Math.abs(e.clientX - start.x) > TAP_DISMISS_MOVE_TOLERANCE) return;
        if (Math.abs(e.clientY - start.y) > TAP_DISMISS_MOVE_TOLERANCE) return;

        const focused = document.activeElement;
        if (!isTextEntryElement(focused)) return;

        const target = start.target;
        if (!(target instanceof Element)) return;
        if (target === focused || focused.contains(target)) return;
        if (target.closest(KEYBOARD_KEEP_SELECTOR)) return;
        if (target.closest(KEYBOARD_INTERACTIVE_SELECTOR)) return;
        if (hasPointerCursor(target)) return;

        focused.blur();
    }, true);
}

// --- Wiring ---------------------------------------------------------------------
//
// What used to live here as well -- an inline height/top lock written onto the active
// pane, and a scroll anchor that re-pinned the thread every frame -- has gone. Both
// existed to repair a pane that was being resized under the thread. Nothing is resized
// any more, so there is nothing to repair: the thread and the composer are translated
// as they are, and whatever was against the bottom edge stays against it.
function lockVisualViewport() {
    if (!window.visualViewport) return;

    // A per-frame poll of the measurement. Not because the browser reports the slide
    // frame by frame -- Chrome does not -- but because it is unpredictable WHEN it
    // reports at all, and the sooner a prediction is either confirmed or corrected the
    // less of the animation is spent on a number that might be stale. Nothing here
    // draws; it only feeds setKeyboardInsetTarget(), which does nothing when the
    // measurement matches what is already on screen -- the usual case.
    let trackUntil = 0;
    let tracking = false;
    const trackKeyboardViewport = (ms) => {
        trackUntil = Math.max(trackUntil, Date.now() + ms);
        if (tracking) return;
        tracking = true;
        const step = () => {
            syncKeyboardViewport();
            if (Date.now() < trackUntil) {
                requestAnimationFrame(step);
            } else {
                tracking = false;
            }
        };
        requestAnimationFrame(step);
    };

    window.visualViewport.addEventListener('resize', syncKeyboardViewport);
    window.visualViewport.addEventListener('scroll', syncKeyboardViewport);

    // The tap is the trigger, not the browser's eventual report -- this is the whole
    // point of the section above. predictKeyboardOpen() starts the slide immediately at
    // the height this device's keyboard measured last time; the poll behind it is what
    // corrects that height if it was wrong, and what takes it back entirely if no
    // keyboard ever appears.
    document.addEventListener('focusin', (e) => {
        if (e.target.tagName !== 'TEXTAREA' && e.target.tagName !== 'INPUT') return;
        armKeyboardOverlay();
        // Claim the slot for the keyboard BEFORE releasing it from the panel. Closing
        // the panel first would drop the target to zero for one turn of this function,
        // start a slide down, and then start a slide back up -- the flicker this whole
        // arrangement exists to avoid. In this order the max() never changes and the
        // panel is simply replaced by the keyboard where it stood.
        predictKeyboardOpen();
        // ...unless the field being focused is the panel's OWN search box. Closing the
        // panel because someone tapped the search box inside it is the panel eating its
        // own feature. applyKeyboardInsets() handles that case by stacking instead.
        if (composerPanelFocusGuard) applyKeyboardInsets();
        else if (!e.target.closest(COMPOSER_PANEL_SELECTOR)) closeComposerPanels();
        else applyKeyboardInsets();
        // Long enough to cover an IME being started for the first time, and an iPad's
        // slower slide plus a split or undocked keyboard settling after it.
        trackKeyboardViewport(1000);
        iosKeyboardFallback(e.target);
    });

    // Deferred by a tick because focusout also fires on the way BETWEEN two fields, and
    // on the composer's own emoji and sticker buttons, which hand focus straight back.
    // Closing on the raw event would tear the keyboard down and rebuild it every time
    // the user reached for a sticker.
    document.addEventListener('focusout', () => {
        setTimeout(() => {
            if (isTextEntryElement(document.activeElement)) return;
            kbIosFallbackInset = 0;
            predictKeyboardClose();
            trackKeyboardViewport(700);
        }, 0);
    });

    // Rotating changes the keyboard's height without any focus change, and the event
    // lands before the new geometry is readable.
    window.addEventListener('orientationchange', () => trackKeyboardViewport(900));
    window.addEventListener('resize', () => trackKeyboardViewport(250));

    // Take the screen's height once, now, while nothing can be covering it. Without
    // this the first field focused in a session would be predicted against a screen
    // nobody had measured yet -- and on an engine that shrinks the layout viewport,
    // the first thing measured after that focus is already the shrunken one.
    syncKeyboardViewport();
}

window.addEventListener('message', (event) => {
    if (event.data.type === 'resize-ad') {
        // Find all ad iframes and match their height to the content
        const iframes = document.querySelectorAll('iframe[src="/adsterra.html"]');
        iframes.forEach(iframe => {
            // We only update if the height is significant (prevents flickering)
            if (event.data.height > 50) {
                iframe.style.height = event.data.height + 'px';
                // Also force the parent card to accommodate the new height
                if (iframe.parentElement) {
                    iframe.parentElement.style.height = 'auto';
                }
            }
        });
    }
});

// Last resort, driven by tapping the App version row in settings: throw away every
// service worker and every cache this origin owns, then reload from the network.
//
// This exists because there was no way out from the device itself. A phone serving
// its own stale copy of script.js cannot be fixed by anything on the server -- it
// never asks the server for anything -- so the only remedies were "clear storage in
// Android settings" or "reinstall the app", neither of which is something you can
// talk someone through while they are already furious. Deliberately defined OUTSIDE
// the serviceWorker guard below, or the button would throw on a browser without it.
window.forceAppUpdate = async function forceAppUpdate() {
    const label = document.getElementById('buildInfoValue');
    if (label) label.textContent = 'updating…';
    try {
        if ('serviceWorker' in navigator) {
            const regs = await navigator.serviceWorker.getRegistrations();
            await Promise.all(regs.map(r => r.unregister()));
        }
        if (window.caches) {
            const names = await caches.keys();
            await Promise.all(names.map(n => caches.delete(n)));
        }
    } catch (e) {
        console.error('forceAppUpdate:', e);
    }
    // Cache-bust the navigation itself: without this the reload can be answered from
    // the HTTP cache, which is the thing we are trying to escape.
    location.replace(location.pathname + '?fresh=' + Date.now());
};

// --- Pick up a deploy on the launch that first sees it -----------------------
// sw.js answers the app shell from cache so the splash paints at once, and only
// refreshes that copy behind the page. So the launch after a deploy boots the OLD
// build, and the switch then waited for the new worker to install, claim the page,
// and for the app to be hidden. A phone that is resumed rather than reopened took
// two or three trips out of the app to get there, so in practice nobody got new
// code without a force update -- and a chat set to a theme newer than their build
// drew the gray image-theme fallback instead.
//
// So ask directly: fetch the shell (which also refreshes the worker's copy of it)
// and read the build it points at. If that is not the build running here, reload
// straight away when nobody has touched the app since it opened or came back;
// otherwise offer a refresh, and take it the next time the app is hidden.
let appUpdateReady = false;
let appUpdateCheck = null;
let appUpdateCheckedAt = 0;
let appShownAt = Date.now();
let appTouchedSinceShown = false;
// How long after opening/resuming an untouched app a reload still counts as part
// of starting up rather than something yanked out from under the user.
const APP_UPDATE_SILENT_WINDOW_MS = 8000;
const APP_UPDATE_RELOAD_KEY = 'apex-update-reload';

['pointerdown', 'keydown'].forEach(type => document.addEventListener(type, () => {
    appTouchedSinceShown = true;
}, { capture: true, passive: true }));

function reloadForAppUpdate(build) {
    // One automatic reload per build per tab. If the reload still came back on the
    // old build (the worker had not stored the new shell yet), a second tap goes
    // through forceAppUpdate, which cannot miss -- rather than reloading in a loop.
    let alreadyTried = false;
    try {
        alreadyTried = sessionStorage.getItem(APP_UPDATE_RELOAD_KEY) === build;
        sessionStorage.setItem(APP_UPDATE_RELOAD_KEY, build);
    } catch (e) { /* storage blocked: the reload below is still right */ }
    if (alreadyTried) {
        forceAppUpdate();
        return;
    }
    // A beat for the worker to finish storing the shell this check just fetched.
    setTimeout(() => location.reload(), 300);
}

function offerAppUpdate(build) {
    if (document.getElementById('apex-update-toast')) return;
    const container = document.getElementById('notification-toast-container');
    if (!container) return;
    const toast = document.createElement('div');
    toast.id = 'apex-update-toast';
    toast.className = 'notification-toast';
    toast.textContent = 'APEX has been updated. Tap to refresh.';
    toast.addEventListener('click', () => reloadForAppUpdate(build));
    container.appendChild(toast);
}

// Resolves to the build the server's shell points at, or null if it could not tell.
function checkForAppUpdate(force) {
    if (appUpdateCheck) return appUpdateCheck;
    if (!force && Date.now() - appUpdateCheckedAt < 30000) return Promise.resolve(null);
    appUpdateCheckedAt = Date.now();
    appUpdateCheck = fetch('/', { cache: 'no-cache', credentials: 'same-origin' })
        .then(r => (r.ok ? r.text() : ''))
        .then(html => {
            const match = html.match(/js\/script\.js\?v=([\w-]+)/);
            const build = match && match[1];
            if (!build || build === APP_BUILD) return build || null;

            appUpdateReady = true;
            const untouched = !appTouchedSinceShown &&
                Date.now() - appShownAt < APP_UPDATE_SILENT_WINDOW_MS;
            let alreadyTried = false;
            try { alreadyTried = sessionStorage.getItem(APP_UPDATE_RELOAD_KEY) === build; } catch (e) {}
            if (untouched && !alreadyTried) reloadForAppUpdate(build);
            else offerAppUpdate(build);
            return build;
        })
        .catch(() => null)   // offline: nothing to say, try again next resume
        .finally(() => { appUpdateCheck = null; });
    return appUpdateCheck;
}
window.checkForAppUpdate = checkForAppUpdate;

window.addEventListener('load', () => checkForAppUpdate(true));

document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') {
        // Leaving with an update waiting is the moment nobody is looking.
        if (appUpdateReady) {
            appUpdateReady = false;
            location.reload();
        }
        return;
    }
    appShownAt = Date.now();
    appTouchedSinceShown = false;
    checkForAppUpdate(false);
});

// Register the Service Worker for caching and push notifications
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js')
      .then(registration => {
        console.log('[Service Worker] Registered successfully with scope:', registration.scope);
      })
      .catch(error => {
        console.error('[Service Worker] Registration failed:', error);
      });
  });

  // --- Keep installed PWAs on current code ---------------------------------
  // This was removed once, on the grounds that boot reports showed every device
  // already current so the problem did not exist. Those reports were misleading:
  // index.html asked for an unversioned /js/script.js, so a device could report a
  // build it was not running. With the ?v= in place the truth showed up
  // immediately -- phones sat on 26w31b for hours while the server served 26w32g.
  //
  // The reason it was removed is real too, though: reloading the instant a worker
  // claims the page lands mid-navigation and throws the user back to the screen
  // they were leaving. So the reload now waits until they are not looking.
  let pendingWorkerReload = false;

  function applyWorkerUpdateWhenUnwatched() {
      if (!pendingWorkerReload) return;
      // Never reload under someone's hands. A phone backgrounds constantly, so
      // this lands within seconds in practice, and they come back to new code.
      if (document.visibilityState === 'visible') return;
      pendingWorkerReload = false;
      location.reload();
  }

  navigator.serviceWorker.addEventListener('controllerchange', () => {
      // A new worker took over: whatever this page is running is now stale.
      pendingWorkerReload = true;
      applyWorkerUpdateWhenUnwatched();
  });

  document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') {
          applyWorkerUpdateWhenUnwatched();
          return;
      }
      // Coming back to the app. THIS is the piece that was missing entirely: an
      // installed PWA that is only ever suspended and resumed never performs a
      // navigation, and without a navigation the browser has no reason to re-fetch
      // sw.js -- so it can sit on an old worker indefinitely, which is exactly what
      // yours did. Ask it to check explicitly.
      navigator.serviceWorker.getRegistration()
          .then(reg => reg && reg.update())
          .catch(() => { /* offline, or no registration yet -- try again next resume */ });
  });

  // Tapping a notification asks the worker to focus this tab; when the worker
  // cannot drive navigation itself it hands the destination back to us.
  navigator.serviceWorker.addEventListener('message', (event) => {
    const msg = event.data || {};
    if (msg.type === 'navigate' && msg.url) {
      // Answer FIRST. The worker waits a moment for this ack and reloads the whole
      // page if it never comes, so the reply is what buys us the in-app route
      // instead of a cold boot. Sent before navigateTo() so a slow render can't
      // push us past the worker's deadline.
      if (event.ports && event.ports[0]) {
        try { event.ports[0].postMessage({ ok: true }); } catch (e) { /* port closed */ }
      }
      // msg.account is the account the notification was sent TO. Tapping a
      // notification for a different saved account used to route this one to a
      // DM it cannot see; put us in that account first and route afterwards.
      openAsAccount(msg.account, msg.url);
      return;
    }

    // A push landed. On a phone this is routinely the only signal that gets
    // through -- a suspended PWA's socket is gone, so nothing else tells the app
    // there is something new -- and it is what makes the red dot appear at the
    // same moment as the system notification rather than after the next reload.
    if (msg.type === 'push-received') {
      refreshUnreadBadges();
    }
  });
}

// Re-pull both unread counters and repaint every badge that reads from them.
// Cheap enough to call on any "something might have changed" signal.
function refreshUnreadBadges() {
    if (!loggedIn || !apiToken) return;
    fetchNotifications(document.getElementById('notifications-page')?.classList.contains('active'));
    fetchConversations();
}

// ==========================================
// DEVELOPER CONSOLE LOGIC
// ==========================================

// --- Developer console: capped, lazily-loaded lists ---
// These two lists used to fetch EVERY report / review at once and render the lot.
// Reports carry a full description plus an evidence transcript, and each AI review
// carries a JSON blob of flagged incidents, so the page grew without limit. Now
// they pull one page at a time and only fetch the next when you scroll for it.
// Each list now has a tab to itself rather than a third of one column, so more
// of it fits before the inner scroll starts.
const DEV_VISIBLE_ITEMS = 5;   // cards visible before the list starts scrolling

// The daily AI review is one card per day, so its useful unit is a fortnight
// rather than a handful: a run of 14 is what makes "Tuesdays are bad" visible
// at all. Reports have no such rhythm -- they are read newest-first and closed
// -- so they keep the smaller page.
const DEV_REVIEW_PAGE_SIZE = 14;
const DEV_REVIEW_VISIBLE_ITEMS = 14;
const DEV_PAGE_SIZE = 5;       // cards fetched per request

let devReportsState = { offset: 0, hasMore: true, loading: false };
let devReviewsState = { offset: 0, hasMore: true, loading: false };

// --- Console tabs ----------------------------------------------------------
// Reports, the daily AI review and telemetry are three separate jobs, not three
// steps of one, so only one is on screen at a time. Switching is purely local:
// no fetch, no history entry -- everything was already pulled by
// refreshDeveloperConsole() when the console opened.
const DEV_TABS = ['reports', 'review', 'telemetry'];

let currentDevTab = 'reports';

function switchDevTab(tab) {
    if (!DEV_TABS.includes(tab)) return;
    currentDevTab = tab;

    DEV_TABS.forEach(name => {
        const btn = document.getElementById(`dev-tab-${name}`);
        const panel = document.getElementById(`dev-panel-${name}`);
        const on = name === tab;
        if (btn) {
            btn.classList.toggle('active', on);
            btn.setAttribute('aria-selected', on ? 'true' : 'false');
        }
        if (panel) panel.classList.toggle('hidden', !on);
    });

    // Chart.js measures its container when it draws, and the telemetry panel is
    // display:none for the first paint after a sync -- so the graph is laid out
    // at zero width unless it is told to re-measure once the panel is visible.
    if (tab === 'telemetry' && devChartInstance) {
        requestAnimationFrame(() => devChartInstance.resize());
    }

    // The capped lists measure rendered cards, and a hidden container reports
    // zero-height ones, so a list first drawn behind another tab is left
    // uncapped until its own tab is opened.
    if (tab === 'reports') {
        capDevListHeight(document.getElementById('developer-reports-list'), '.report-card');
    }
    if (tab === 'review') {
        capDevListHeight(document.getElementById('daily-review-container'), '.dev-review-card');
    }
}

// The console always opens on Reports -- the one thing here with people waiting
// on it -- rather than on whichever tab was left open last visit.
function resetDevTabs() {
    switchDevTab('reports');
}

// Which reports the list is asking the server for. 'all' keeps the previous
// behaviour; the other two let a moderator work the open cases without the
// resolved ones padding every page.
let devReportFilter = 'all';

function setReportFilter(filter) {
    if (!['all', 'pending', 'resolved'].includes(filter)) return;
    devReportFilter = filter;
    ['all', 'pending', 'resolved'].forEach(name => {
        const btn = document.getElementById(`dev-report-filter-${name}`);
        if (btn) btn.classList.toggle('active', name === filter);
    });
    fetchReports();
}

// Sizes a list to exactly DEV_VISIBLE_ITEMS cards, then lets it scroll. Measured
// from the rendered cards rather than a hardcoded height, because report and review
// cards vary a lot in height depending on their content.
function capDevListHeight(container, itemSelector, visible = DEV_VISIBLE_ITEMS) {
    const items = container.querySelectorAll(itemSelector);
    if (items.length <= visible) {
        container.style.maxHeight = '';
        container.style.overflowY = '';
        return;
    }
    const first = items[0];
    const last = items[visible - 1];
    // offsetTop is relative to a shared offsetParent, so the difference is the
    // true stacked height of the first N cards, gaps included.
    const height = (last.offsetTop + last.offsetHeight) - first.offsetTop;
    container.style.maxHeight = `${Math.round(height)}px`;
    container.style.overflowY = 'auto';
}

// Pull the next page once the user scrolls near the bottom of the list.
function attachDevLazyScroll(container, loadMore) {
    container.onscroll = () => {
        if (container.scrollTop + container.clientHeight >= container.scrollHeight - 40) {
            loadMore();
        }
    };
}

function buildReportCard(report) {
    const isResolved = report.status === 'resolved';
    const card = document.createElement('div');
    // Add the 'resolved' class to trigger the CSS minimization
    card.className = `report-card ${isResolved ? 'resolved' : ''}`;

    const safeDesc = report.description.replace(/</g, "&lt;").replace(/>/g, "&gt;");

    // Toggle Button Logic
    const actionBtn = isResolved
        ? `<button class="confirm-btn-cancel" onclick="updateReportStatus(${report.id}, 'pending')"><i class="fas fa-undo"></i> Unresolve</button>`
        : `<button class="confirm-btn-confirm" onclick="updateReportStatus(${report.id}, 'resolved')"><i class="fas fa-check"></i> Resolve</button>`;

    // Wrapped in .report-body so the CSS can hide it when resolved
    card.innerHTML = `
        <div class="report-main-info">
            <div class="report-header">
                <span class="report-type"><i class="fas fa-exclamation-triangle"></i> ${report.issue_type}</span>
                <span class="report-date">${formatTimestamp(new Date(report.created_at))}</span>
            </div>
            <div class="report-body">
                <div class="report-meta-row">
                    <p class="report-meta"><span class="report-meta-key">Reporter</span> @${report.reporter_username}</p>
                    <p class="report-meta"><span class="report-meta-key">Target</span> ${report.reported_users || 'N/A'}</p>
                </div>
                <div class="report-desc">${safeDesc}</div>
            </div>
        </div>
        <div class="report-actions">
            ${actionBtn}
        </div>
    `;
    return card;
}

// The open-case count shows up twice -- on the Reports tab and in the vitals
// strip -- because it is the one number you want whichever tab you are on.
function setDevPendingCount(count) {
    const n = Number(count) || 0;
    const chip = document.getElementById('report-count-badge');
    if (chip) {
        chip.textContent = n;
        chip.classList.toggle('empty', n === 0);
    }
    const vital = document.getElementById('dev-pending-vital');
    if (vital) vital.textContent = n;
}

function fetchReports(loadMore = false) {
    const container = document.getElementById('developer-reports-list');

    if (!loadMore) {
        // Fresh load: reset paging and clear whatever is on screen.
        devReportsState = { offset: 0, hasMore: true, loading: false };
        container.onscroll = null;
        container.style.maxHeight = '';
        container.style.overflowY = '';
        container.innerHTML = '<div class="dev-empty"><p>Loading reports...</p></div>';
    }

    if (devReportsState.loading || !devReportsState.hasMore) return;
    devReportsState.loading = true;

    const url = `${API_BASE_URL}/api/reports?status=${devReportFilter}&limit=${DEV_PAGE_SIZE}&offset=${devReportsState.offset}`;
    fetch(url, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(response => response.json())
    .then(data => {
        devReportsState.loading = false;

        if (data.error) {
            container.innerHTML = `<p class="dev-error">${data.error}</p>`;
            return;
        }

        const reports = data.reports || [];
        // The pending count is the whole queue, not this page and not this
        // filter, so it stays honest while you read the resolved list.
        setDevPendingCount(data.total_pending);
        if (!loadMore) container.innerHTML = '';

        if (reports.length === 0 && devReportsState.offset === 0) {
            const blank = devReportFilter === 'resolved'
                ? 'Nothing has been resolved yet.'
                : 'All clear! No reports right now.';
            container.innerHTML = `
                <div class="dev-empty">
                    <i class="fas fa-shield-alt"></i>
                    <p>${blank}</p>
                </div>
            `;
            return;
        }

        reports.forEach(report => container.appendChild(buildReportCard(report)));
        devReportsState.offset += reports.length;
        devReportsState.hasMore = !!data.has_more;

        capDevListHeight(container, '.report-card');
        attachDevLazyScroll(container, () => fetchReports(true));
    })
    .catch(err => {
        devReportsState.loading = false;
        console.error("Failed to fetch reports:", err);
        if (!loadMore) {
            container.innerHTML = '<p class="dev-error">Network error while fetching reports.</p>';
        }
    });
}

function updateReportStatus(reportId, newStatus) {
    // No confirmation prompt, just execute it instantly for a fluid feel
    fetch(`${API_BASE_URL}/api/reports/${reportId}/status`, {
        method: 'PUT',
        headers: { 
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${apiToken}` 
        },
        body: JSON.stringify({ status: newStatus })
    })
    .then(res => res.json())
    .then(data => {
        if (data.ok) {
            fetchReports(); // Refresh the grid instantly to snap it shut
        } else {
            showToast(data.error || 'Failed to update report.', 'error');
        }
    })
    .catch(err => showToast('Network error while updating report.', 'error'));
}

// ==========================================================================
// TELEMETRY ENGINE & MONITOR RUNTIME CONFIG
// ==========================================================================

let devChartInstance = null;

function refreshDeveloperConsole() {
    fetchDeveloperMetrics();
    fetchReports(); // Assuming this function is still defined below this
    fetchDailyReviews();
}

function fetchDeveloperMetrics() {
    const rangeSelect = document.getElementById('dev-time-range');
    const rangeVal = rangeSelect ? rangeSelect.value : '7d';
    const rangeText = rangeSelect.options[rangeSelect.selectedIndex].text;
    
    const title = document.getElementById('dynamic-metrics-title');
    if (title) title.textContent = `Metrics for ${rangeText}`;

    fetch(`${API_BASE_URL}/api/developer/stats?range=${rangeVal}`, {
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(res => {
        if (!res.ok) throw new Error(`HTTP Telemetry Fault Status: ${res.status}`);
        return res.json();
    })
    .then(data => {
        // Realtime Data
        document.getElementById('metric-active-now').textContent = data.realtime.active_now;
        document.getElementById('metric-active-hour').textContent = data.realtime.active_hour;
        
        // Range Metrics
        document.getElementById('metric-new-users').textContent = data.metrics.users;
        document.getElementById('metric-new-posts').textContent = data.metrics.posts;
        document.getElementById('metric-new-dms').textContent = data.metrics.dms;
        document.getElementById('metric-new-lounges').textContent = data.metrics.lounges;

        // All Time Totals
        document.getElementById('total-stat-users').textContent = data.totals.total_users;
        document.getElementById('total-stat-posts').textContent = data.totals.total_posts;
        document.getElementById('total-stat-dms').textContent = data.totals.total_dms;
        document.getElementById('total-stat-lounges').textContent = data.totals.total_lounges;

        // Render Graph
        renderDevChart(data.chart.labels, data.chart.posts, data.chart.dms);
    })
    .catch(err => {
        console.error("[Telemetry Engine Fault Alert]", err);
        showToast("Metrics runtime synchronization failed.", "error");
    });
}

// Chart.js (~200KB) is used by this one graph on the developer console, so it's
// fetched the first time that console renders rather than on every app launch.
async function renderDevChart(labels, postData, dmData) {
    const canvas = document.getElementById('devActivityChart');
    if (!canvas) return;

    try {
        await loadScriptOnce(CHARTJS_SRC);
    } catch (e) {
        console.error('Chart.js failed to load:', e);
        return;
    }

    const ctx = canvas.getContext('2d');

    // Destroy old chart to prevent "hover glitching" over old data
    if (devChartInstance) {
        devChartInstance.destroy();
    }

    devChartInstance = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [
                {
                    label: 'Posts Published',
                    data: postData,
                    borderColor: '#0066ff',
                    backgroundColor: 'rgba(0, 102, 255, 0.1)',
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4, // Adds the sleek curve
                    pointRadius: 3
                },
                {
                    label: 'DMs Sent',
                    data: dmData,
                    borderColor: '#2ecc71',
                    backgroundColor: 'rgba(46, 204, 113, 0.1)',
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4,
                    pointRadius: 3
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false, // Ensures it fits our CSS height
            plugins: {
                legend: { 
                    position: 'top',
                    labels: { font: { family: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif" } }
                }
            },
            scales: {
                y: { 
                    beginAtZero: true,
                    ticks: { precision: 0 } // Don't show decimal users/posts
                }
            },
            interaction: {
                mode: 'index',
                intersect: false,
            }
        }
    });
}

function buildReviewCard(review) {
    const card = document.createElement('div');
    card.className = 'dev-review-card';

    const data = review.flagged; // This is the full JSON object from Gemini
    const incidents = data.flagged_incidents || [];

    let flaggedHtml = '';
    if (incidents.length > 0) {
        flaggedHtml = `
            <h4 class="dev-incident-title">
                <i class="fas fa-exclamation-triangle"></i> Severe violations detected (${incidents.length})
            </h4>`;

        incidents.forEach(inc => {
            const other = (inc.participants || []).filter(p => p !== inc.offending_user)[0] || 'unknown';
            flaggedHtml += `
                <div class="dev-incident">
                    <div class="dev-incident-head">
                        <span class="dev-incident-user">@${inc.offending_user}</span>
                        <span class="dev-incident-id">ID: ${inc.message_id}</span>
                    </div>
                    <dl class="dev-incident-facts">
                        <dt>Context</dt><dd>Chat with @${other}</dd>
                        <dt>Mood</dt><dd>${inc.interchange_mood}</dd>
                        <dt>Reason</dt><dd>${inc.reason}</dd>
                    </dl>
                    <div class="dev-incident-quote">"${inc.quote}"</div>
                </div>
            `;
        });
    } else {
        flaggedHtml = `
            <p class="dev-review-clear">
                <i class="fas fa-check-circle"></i> No severe violations detected. Network is healthy.
            </p>`;
    }

    card.innerHTML = `
        <div class="dev-review-head">
            <span class="dev-review-date">Review for ${review.date}</span>
            <span class="dev-review-chip">${data.conversations_reviewed} chats analyzed</span>
        </div>
        <p class="dev-review-summary"><strong>Daily vibe:</strong> ${review.summary}</p>
        ${flaggedHtml}
    `;
    return card;
}

function fetchDailyReviews(loadMore = false) {
    const container = document.getElementById('daily-review-container');

    if (!loadMore) {
        devReviewsState = { offset: 0, hasMore: true, loading: false };
        container.onscroll = null;
        container.style.maxHeight = '';
        container.style.overflowY = '';
    }

    if (devReviewsState.loading || !devReviewsState.hasMore) return;
    devReviewsState.loading = true;

    const url = `${API_BASE_URL}/api/admin/daily-reviews?limit=${DEV_REVIEW_PAGE_SIZE}&offset=${devReviewsState.offset}`;
    fetch(url, { headers: { 'Authorization': `Bearer ${apiToken}` } })
    .then(r => r.json())
    .then(data => {
        devReviewsState.loading = false;

        if (data.error) {
            container.innerHTML = `<p class="dev-error">${data.error}</p>`;
            return;
        }

        const reviews = data.reviews || [];
        if (!loadMore) container.innerHTML = '';

        if (reviews.length === 0 && devReviewsState.offset === 0) {
            container.innerHTML = `
                <div class="dev-empty">
                    <i class="fas fa-robot"></i>
                    <p>No daily reviews have been generated yet.</p>
                </div>`;
            return;
        }

        reviews.forEach(review => container.appendChild(buildReviewCard(review)));
        devReviewsState.offset += reviews.length;
        devReviewsState.hasMore = !!data.has_more;

        capDevListHeight(container, '.dev-review-card', DEV_REVIEW_VISIBLE_ITEMS);
        attachDevLazyScroll(container, () => fetchDailyReviews(true));
    })
    .catch(err => {
        devReviewsState.loading = false;
        console.error("Failed to fetch daily reviews:", err);
        if (!loadMore) {
            container.innerHTML = '<p class="dev-error">Network error while fetching reviews.</p>';
        }
    });
}

function triggerManualDailyReview() {
    showToast("Triggering background AI review. This may take a minute.", "success");
    
    fetch(`${API_BASE_URL}/api/admin/trigger-review`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` }
    })
    .then(r => r.json())
    .then(data => {
        if (data.ok) {
            // Check back in 15 seconds to see if it finished
            setTimeout(fetchDailyReviews, 15000); 
        } else {
            showToast(data.error, "error");
        }
    });
}

// ===========================================================================
// POLLS
// ===========================================================================
// A poll is an attachment on a message or a post, not a page of its own: you
// build one from the composer's + menu, it rides along with whatever you were
// sending anyway, and it draws inside that bubble or card. Everything below is
// that one card and the composer that produces it, shared by DMs, lounges and
// circuit posts -- the three surfaces differ only in which composer opens it
// and which payload carries it.
//
// The server is the authority on what this viewer may see: a hidden tally is
// simply absent from the payload (no `count` on the options), so there is
// nothing here to reveal by deleting a class. See polls.py.

const POLL_KINDS = {
    single:   { icon: 'fa-circle-dot',      label: 'Choose one',   blurb: 'One answer only.' },
    multi:    { icon: 'fa-list-check',      label: 'Choose many',  blurb: 'Choose multiple options.' },
    ranked:   { icon: 'fa-arrow-down-1-9',  label: 'Ranked',       blurb: 'Rank options in order.' },
    scale:    { icon: 'fa-sliders',         label: 'Scale',        blurb: 'Rate options from 1 to 5.' },
    quiz:     { icon: 'fa-graduation-cap',  label: 'Quiz',         blurb: 'One right answer, revealed after you try.' },
    open:     { icon: 'fa-pen',             label: 'Open answer',  blurb: 'Everyone writes a short answer.' },
    schedule: { icon: 'fa-calendar-check',  label: 'Find a time',  blurb: 'Mark which times work for you.' },
};

// Kinds whose author writes a list of options.
const POLL_OPTION_KINDS = ['single', 'multi', 'ranked', 'quiz', 'schedule'];

const POLL_OPTION_MAX = 12;
const POLL_QUESTION_MAX = 200;
const POLL_OPTION_LABEL_MAX = 80;
const POLL_OPEN_ANSWER_MAX = 280;
// Enough to answer "who picked this?" in a bubble without the row becoming a
// paragraph. The rest stay in the title attribute.
const POLL_VOTERS_SHOWN = 6;

// Every poll payload this session has seen, by id. The card is a pure function
// of this, so a vote, a socket signal and a re-render all go through the same
// path: update the store, redraw every card showing that poll.
const pollStore = new Map();

// Which polls have already played their entrance. A feed re-renders itself two
// or three times as a post settles (the list paints, then the post modal or a
// live update rebuilds it), and each pass builds a brand new card element for
// the same poll -- without this the animation ran again on every one of them.
// The entrance is meant to mark a poll arriving, not a list redrawing.
const pollEntrancePlayed = new Set();
// Selections a voter has made but not submitted. Kept outside the DOM because
// both message renderers rebuild every bubble from scratch on any event -- an
// arriving message must not wipe a half-made choice.
const pollDrafts = new Map();
// The poll waiting to be sent with the next message/post, per surface.
const pendingPolls = { dm: null, lounge: null, circuit: null };

function pollKindMeta(kind) {
    return POLL_KINDS[kind] || POLL_KINDS.single;
}

function pollTakesOptions(kind) {
    return POLL_OPTION_KINDS.includes(kind);
}

function storePoll(poll) {
    if (poll && poll.id) pollStore.set(String(poll.id), poll);
    return poll;
}

function pollDraft(poll) {
    const key = String(poll.id);
    if (!pollDrafts.has(key)) pollDrafts.set(key, seedPollDraft(poll));
    return pollDrafts.get(key);
}

// A draft starts as whatever this person already answered, so "change my
// answer" opens on their existing choice rather than on an empty card.
function seedPollDraft(poll) {
    const mine = poll.myVote || {};
    if (poll.kind === 'ranked') {
        return { order: (mine.order && mine.order.slice()) || poll.options.map(o => o.id) };
    }
    if (poll.kind === 'schedule') {
        return { slots: Object.assign({}, mine.slots || {}) };
    }
    if (poll.kind === 'scale') {
        return { value: mine.value == null ? null : mine.value };
    }
    if (poll.kind === 'open') {
        return { text: mine.text || '' };
    }
    return { optionIds: (mine.optionIds && mine.optionIds.slice()) || [] };
}

function resetPollDraft(pollId) {
    pollDrafts.delete(String(pollId));
}

// ---------------------------------------------------------------------------
// Card
// ---------------------------------------------------------------------------

function buildPollCard(poll, context) {
    storePoll(poll);
    const card = document.createElement('div');
    card.className = 'poll-card';
    card.dataset.pollId = poll.id;
    if (context) card.dataset.pollContext = context;
    if (poll.pending) card.classList.add('poll-pending');
    paintPollCard(card, poll);
    // The entrance plays once per poll. The class also has to come off again,
    // otherwise the next repaint -- and a card repaints on every pick -- would
    // restage the rows it just animated in.
    if (!pollEntrancePlayed.has(String(poll.id))) {
        pollEntrancePlayed.add(String(poll.id));
        card.classList.add('poll-card-in');
        setTimeout(() => card.classList.remove('poll-card-in'), 700);
    }
    // A card that is rebuilt for a poll that already played -- a re-render of
    // the feed it sits in, or the post modal opening over the grid -- starts
    // from the finished state rather than replaying the arrival.
    return card;
}

// Redraw every card on screen for this poll. The same poll can be in two
// places at once (a circuit grid card and the post modal over it), and both
// have to agree.
function refreshPollCards(pollId, options) {
    const poll = pollStore.get(String(pollId));
    if (!poll) return;
    document.querySelectorAll(`.poll-card[data-poll-id="${pollId}"]`).forEach(card => {
        paintPollCard(card, poll, options);
    });
}

// options.grow: this repaint is carrying numbers that just changed, so the
// result bars count up from zero instead of appearing at their new width.
// Every other repaint (a pick, an edit) leaves them where they are.
function paintPollCard(card, poll, options) {
    card.classList.toggle('poll-closed', !!poll.isClosed);
    // The entrance animation belongs to the rows this is about to throw away.
    // Leaving the class on means the replacements come in staged all over again
    // -- a socket update or a tally refresh arriving inside the entrance's own
    // 700ms window replayed it, which is what made a poll animate itself in two
    // or three times on open.
    card.classList.remove('poll-card-in');
    card.innerHTML = pollCardMarkup(poll);
    if (options && options.grow) {
        card.querySelectorAll('.poll-bar').forEach(bar => bar.classList.add('poll-bar-grow'));
    }
    wirePollCard(card, poll);
}

function pollCardMarkup(poll) {
    const meta = pollKindMeta(poll.kind);
    const parts = [];

    parts.push(`
        <div class="poll-head">
            <span class="poll-kind"><i class="fas ${meta.icon}"></i>${escapeHtmlText(meta.label)}</span>
            ${poll.isClosed ? '<span class="poll-state poll-state-closed">Closed</span>'
                            : pollDeadlineChip(poll)}
        </div>
        <div class="poll-question">${escapeHtmlText(poll.question)}</div>`);

    if (poll.pending) {
        parts.push('<div class="poll-note">Sending…</div>');
        parts.push(pollPreviewBody(poll));
        return parts.join('');
    }

    parts.push(pollBodyMarkup(poll));
    parts.push(pollFooterMarkup(poll));
    return parts.join('');
}

function pollDeadlineChip(poll) {
    if (!poll.closesAt) return '';
    const left = new Date(poll.closesAt) - new Date();
    if (left <= 0) return '<span class="poll-state poll-state-closed">Closed</span>';
    return `<span class="poll-state">Closes in ${escapeHtmlText(shortDuration(left))}</span>`;
}

// Rounded DOWN, always: "closes in 1 hr" with 90 minutes left is a promise the
// clock keeps, "closes in 2 hr" is not.
function shortDuration(ms) {
    const mins = Math.floor(ms / 60000);
    if (mins < 60) return `${Math.max(1, mins)} min`;
    const hours = Math.floor(mins / 60);
    if (hours < 48) return `${hours} hr`;
    return `${Math.floor(hours / 24)} days`;
}

// The card as it looks before the server has ever seen it -- drawn from the
// draft the composer produced, so an optimistic bubble is not a blank space.
function pollPreviewBody(poll) {
    const rows = (poll.options || []).map(o =>
        `<div class="poll-row poll-row-static"><span class="poll-label">${escapeHtmlText(o.label)}</span></div>`);
    return `<div class="poll-body">${rows.join('')}</div>`;
}

function pollBodyMarkup(poll) {
    switch (poll.kind) {
        case 'scale':    return pollScaleBody(poll);
        case 'open':     return pollOpenBody(poll);
        case 'ranked':   return pollRankedBody(poll);
        case 'schedule': return pollScheduleBody(poll);
        default:         return pollChoiceBody(poll);
    }
}

// Results are only worth drawing once there is something to draw: a poll with
// no answers yet is showing its results, and they are empty.
function pollShowsTally(poll) {
    return !!poll.resultsVisible && (poll.voterCount || 0) > 0;
}

// single / multi / quiz. One row per option: a bar when results are showing, a
// plain button when they are not.
function pollChoiceBody(poll) {
    const draft = pollDraft(poll);
    const chosen = new Set(draft.optionIds || []);
    const mine = new Set((poll.myVote && poll.myVote.optionIds) || []);
    const total = poll.options.reduce((sum, o) => sum + (o.count || 0), 0);
    const leader = Math.max(0, ...poll.options.map(o => o.count || 0));
    const showTally = pollShowsTally(poll);
    const live = pollIsInteractive(poll);

    const rows = poll.options.map(option => {
        const picked = live ? chosen.has(option.id) : mine.has(option.id);
        const share = (showTally && total) ? Math.round((option.count || 0) / total * 100) : 0;
        const classes = ['poll-row', 'poll-row-choice'];
        if (picked) classes.push('is-picked');
        if (showTally && (option.count || 0) === leader && leader > 0) classes.push('is-leader');
        if (option.isCorrect === true) classes.push('is-correct');
        if (option.isCorrect === false && mine.has(option.id)) classes.push('is-wrong');

        return `
            <button type="button" class="${classes.join(' ')}"
                    data-poll-action="${live ? 'pick' : 'noop'}" data-option-id="${option.id}"
                    ${live ? '' : 'disabled'}>
                ${showTally ? `<span class="poll-bar" style="--poll-share:${share}%;width:${share}%"></span>` : ''}
                <span class="poll-mark"><i class="fas ${pollPickIcon(poll.kind, picked)}"></i></span>
                <span class="poll-label">
                    ${escapeHtmlText(option.label)}
                    ${showTally ? pollVotersLine(option) : ''}
                </span>
                ${showTally ? `<span class="poll-count">${share}%</span>` : ''}
            </button>`;
    });

    return `<div class="poll-body">${rows.join('')}</div>${pollQuizNote(poll)}`;
}

// "Names shown" has to actually show names. The server already sends a voter
// list per option whenever the poll is not anonymous and this viewer may see
// results (_serialize in polls.py) -- drawing it here is what makes the
// footer note true rather than a claim. Rides inside .poll-label as a second
// block line, the same slot the schedule kind uses for its date.
function pollVotersLine(option) {
    const names = (option.voters || []).map(p => p.fullName || p.username);
    if (!names.length) return '';
    const shown = names.slice(0, POLL_VOTERS_SHOWN);
    const rest = names.length - shown.length;
    const line = shown.join(', ') + (rest > 0 ? ` +${rest} more` : '');
    return `<em class="poll-voters" title="${escapeHtmlText(names.join(', '))}">${escapeHtmlText(line)}</em>`;
}

function pollPickIcon(kind, picked) {
    if (kind === 'multi') return picked ? 'fa-square-check' : 'fa-square';
    return picked ? 'fa-circle-dot' : 'fa-circle';
}

function pollQuizNote(poll) {
    if (poll.kind !== 'quiz' || !poll.hasVoted) return '';
    const correct = poll.options.filter(o => o.isCorrect).map(o => o.label);
    const mine = new Set((poll.myVote && poll.myVote.optionIds) || []);
    const gotIt = poll.options.some(o => o.isCorrect && mine.has(o.id));
    return `
        <div class="poll-note ${gotIt ? 'poll-note-right' : 'poll-note-wrong'}">
            <i class="fas ${gotIt ? 'fa-circle-check' : 'fa-circle-xmark'}"></i>
            ${gotIt ? 'Correct.' : `The answer is ${escapeHtmlText(correct.join(', '))}.`}
        </div>`;
}

// A scale is a number line, not a grid of buttons: one straight line from 1 to
// the top, a thumb you drag (or tap anywhere on the line to jump), and -- once
// the tally is showing -- a small histogram of the answers standing on it, with
// the average marked where it falls. It never wraps, so 1..10 reads as one
// continuous range instead of two rows that look like separate choices.
// Dragging is wired in wirePollScale(); a committed pick goes through the same
// 'scale' action a tap on the old buttons did.
function pollScalePct(n, top) {
    return top <= 1 ? 50 : ((n - 1) / (top - 1)) * 100;
}

function pollScaleBody(poll) {
    const top = (poll.settings || {}).scaleMax || 5;
    const draft = pollDraft(poll);
    const live = pollIsInteractive(poll);
    const showTally = pollShowsTally(poll);
    const current = live ? draft.value : (poll.myVote ? poll.myVote.value : null);

    const counts = [];
    for (let n = 1; n <= top; n++) {
        counts.push((poll.distribution && poll.distribution[String(n)]) || 0);
    }
    const most = Math.max(1, ...counts);

    const ticks = [];
    const nums = [];
    const bars = [];
    for (let n = 1; n <= top; n++) {
        const pos = pollScalePct(n, top);
        const on = current === n;
        const passed = current != null && n <= current;
        ticks.push(`<span class="poll-line-tick ${passed ? 'is-passed' : ''}" style="left:${pos}%"></span>`);
        nums.push(`<span class="poll-line-num ${on ? 'is-picked' : ''}" style="left:${pos}%">${n}</span>`);
        if (showTally) {
            const count = counts[n - 1];
            const h = count ? Math.max(12, Math.round((count / most) * 100)) : 0;
            bars.push(`
                <span class="poll-line-bar ${on ? 'is-picked' : ''}" style="left:${pos}%; --h:${h}%"
                      title="${count} ${count === 1 ? 'vote' : 'votes'}">
                    ${count ? `<b>${count}</b>` : ''}
                </span>`);
        }
    }

    const avg = (showTally && poll.average != null) ? Number(poll.average) : null;
    const avgMark = avg != null
        ? `<span class="poll-line-avg" style="left:${pollScalePct(avg, top)}%" title="Average ${avg}"></span>` : '';
    const fill = current != null ? pollScalePct(current, top) : 0;
    // A plain knob: the number it sits on is already lit up beneath it.
    const thumb = current != null
        ? `<span class="poll-line-thumb" style="left:${pollScalePct(current, top)}%"></span>` : '';

    const average = avg != null
        ? `<div class="poll-note">Average ${poll.average} out of ${top}</div>` : '';
    const hint = live && current == null
        ? '<div class="poll-line-hint">Slide or tap to answer</div>' : '';

    return `
        <div class="poll-body poll-scale">
            <div class="poll-line ${live ? 'is-live' : ''} ${current == null ? 'is-empty' : ''}"
                 ${live ? 'role="slider" tabindex="0"' : 'role="img"'}
                 aria-label="Scale from 1 to ${top}"
                 aria-valuemin="1" aria-valuemax="${top}" ${current != null ? `aria-valuenow="${current}"` : ''}
                 data-top="${top}">
                ${showTally ? `<div class="poll-line-hist">${bars.join('')}</div>` : ''}
                <div class="poll-line-rail">
                    <span class="poll-line-fill" style="width:${fill}%"></span>
                    ${ticks.join('')}
                    ${avgMark}
                    ${thumb}
                </div>
                <div class="poll-line-nums">${nums.join('')}</div>
            </div>
            ${hint}
        </div>${average}`;
}

// Drag the thumb along the line. Nothing repaints while the finger is down --
// a repaint would throw the line away mid-gesture -- so the thumb, the fill and
// the numbers are moved by hand, snapped to the nearest whole value, and the
// pick is committed once, on release.
function wirePollScale(card, poll) {
    const line = card.querySelector('.poll-line.is-live');
    if (!line) return;
    const rail = line.querySelector('.poll-line-rail');
    const top = Number(line.dataset.top) || 5;
    let dragging = false;
    let value = pollDraft(poll).value;

    const valueAt = (clientX) => {
        const r = rail.getBoundingClientRect();
        const f = r.width ? (clientX - r.left) / r.width : 0;
        return Math.min(top, Math.max(1, Math.round(1 + Math.min(1, Math.max(0, f)) * (top - 1))));
    };

    const show = (n) => {
        if (n === value && line.querySelector('.poll-line-thumb')) return;
        value = n;
        const pos = pollScalePct(n, top);
        let thumb = rail.querySelector('.poll-line-thumb');
        if (!thumb) {
            thumb = document.createElement('span');
            thumb.className = 'poll-line-thumb';
            rail.appendChild(thumb);
            line.classList.remove('is-empty');
            card.querySelector('.poll-line-hint')?.remove();
        }
        thumb.style.left = `${pos}%`;
        rail.querySelector('.poll-line-fill').style.width = `${pos}%`;
        line.querySelectorAll('.poll-line-num').forEach((el, i) => el.classList.toggle('is-picked', i + 1 === n));
        line.querySelectorAll('.poll-line-tick').forEach((el, i) => el.classList.toggle('is-passed', i + 1 <= n));
        line.setAttribute('aria-valuenow', n);
        if (navigator.vibrate && dragging) navigator.vibrate(4);
    };

    const commit = () => handlePollAction(card, poll, 'scale', { value: String(value) });

    line.addEventListener('pointerdown', (e) => {
        if (e.button !== 0) return;
        e.preventDefault();
        e.stopPropagation();
        dragging = true;
        line.classList.add('is-dragging');
        try { line.setPointerCapture(e.pointerId); } catch (err) { /* already gone */ }
        show(valueAt(e.clientX));
    });
    line.addEventListener('pointermove', (e) => {
        if (!dragging) return;
        e.stopPropagation();
        show(valueAt(e.clientX));
    });
    const end = (e) => {
        if (!dragging) return;
        dragging = false;
        line.classList.remove('is-dragging');
        e.stopPropagation();
        if (value != null) commit();
    };
    line.addEventListener('pointerup', end);
    line.addEventListener('pointercancel', end);

    // The bubble around the card, the post lightbox and the page all answer a
    // sideways drag of their own (swipe-to-reply, next post, next page). A drag
    // that starts on the line is the line's.
    ['touchstart', 'touchmove'].forEach(type =>
        line.addEventListener(type, (e) => e.stopPropagation(), { passive: true }));

    line.addEventListener('keydown', (e) => {
        const step = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 }[e.key];
        let next = null;
        if (step) next = Math.min(top, Math.max(1, (value || (step > 0 ? 0 : top + 1)) + step));
        else if (e.key === 'Home') next = 1;
        else if (e.key === 'End') next = top;
        if (next == null) return;
        e.preventDefault();
        e.stopPropagation();
        show(next);
        commit();
        card.querySelector('.poll-line.is-live')?.focus({ preventScroll: true });
    });
}

function pollOpenBody(poll) {
    const draft = pollDraft(poll);
    const live = pollIsInteractive(poll);
    const answers = (poll.answers || []).map(answer => `
        <div class="poll-answer ${answer.isMine ? 'is-mine' : ''}">
            <div class="poll-answer-text">${escapeHtmlText(answer.text)}</div>
            <span>${answer.author ? escapeHtmlText(answer.author.fullName || answer.author.username)
                                    + rankIconFor(answer.author.username, answer.author.rank)
                                  : 'Anonymous'}</span>
        </div>`);

    const field = live ? `
        <textarea class="poll-open-input" rows="2" maxlength="${POLL_OPEN_ANSWER_MAX}"
                  data-poll-action="open-input"
                  autocomplete="off" autocorrect="off" spellcheck="false"
                  placeholder="Your answer…">${escapeHtmlText(draft.text || '')}</textarea>` : '';

    // Only when the answer list itself is withheld -- otherwise this viewer's
    // own answer is already in it and would be printed twice.
    const mine = (!live && !poll.answers && poll.myVote && poll.myVote.text)
        ? `<div class="poll-answer is-mine"><div class="poll-answer-text">${escapeHtmlText(poll.myVote.text)}</div><span>You</span></div>` : '';

    return `<div class="poll-body poll-open">${field}${mine}${answers.join('')}</div>`;
}

// Ranked uses up/down buttons rather than drag: the card lives inside a
// scrolling message thread on a phone, where a drag gesture is already spoken
// for by the scroll and by swipe-to-reply.
function pollRankedBody(poll) {
    const draft = pollDraft(poll);
    const live = pollIsInteractive(poll);
    const showTally = pollShowsTally(poll);
    const byId = new Map(poll.options.map(o => [o.id, o]));
    const order = (draft.order || []).filter(id => byId.has(id));
    poll.options.forEach(o => { if (!order.includes(o.id)) order.push(o.id); });
    draft.order = order;

    // Once it is a result rather than a ballot, the winner belongs at the top.
    const shown = (!live && showTally)
        ? poll.options.slice().sort((a, b) => (b.score || 0) - (a.score || 0)).map(o => o.id)
        : order;

    const rows = shown.map((id, index) => {
        const option = byId.get(id);
        return `
            <div class="poll-row poll-row-rank">
                <span class="poll-rank-num">${index + 1}</span>
                <span class="poll-label">
                    ${escapeHtmlText(option.label)}
                    ${showTally ? pollVotersLine(option) : ''}
                </span>
                ${live ? `
                    <span class="poll-rank-moves">
                        <button type="button" data-poll-action="rank-up" data-option-id="${id}"
                                ${index === 0 ? 'disabled' : ''} aria-label="Move up">
                            <i class="fas fa-chevron-up"></i></button>
                        <button type="button" data-poll-action="rank-down" data-option-id="${id}"
                                ${index === shown.length - 1 ? 'disabled' : ''} aria-label="Move down">
                            <i class="fas fa-chevron-down"></i></button>
                    </span>` : ''}
            </div>`;
    });

    return `<div class="poll-body poll-ranked">${rows.join('')}</div>`;
}

function pollScheduleBody(poll) {
    const draft = pollDraft(poll);
    const live = pollIsInteractive(poll);
    const showTally = pollShowsTally(poll);
    const source = live ? (draft.slots || {}) : ((poll.myVote && poll.myVote.slots) || {});

    const rows = poll.options.map(option => {
        const state = Number(source[String(option.id)] || 0);
        const when = option.meta ? formatPollSlot(option.meta) : null;
        return `
            <div class="poll-row poll-row-slot ${state === 2 ? 'is-yes' : state === 1 ? 'is-maybe' : ''}">
                <span class="poll-label">
                    ${escapeHtmlText(option.label)}
                    ${when ? `<em>${escapeHtmlText(when)}</em>` : ''}
                    ${showTally ? pollVotersLine(option) : ''}
                </span>
                ${showTally ? `
                    <span class="poll-count" title="Free / maybe">
                        ${option.yes || 0} free${(option.maybe || 0) ? ` · ${option.maybe}?` : ''}
                    </span>` : ''}
                ${live ? `
                    <span class="poll-slot-picks">
                        <button type="button" class="${state === 2 ? 'is-picked' : ''}"
                                data-poll-action="slot" data-option-id="${option.id}" data-value="2"
                                aria-label="Works">
                            <i class="fas fa-check"></i></button>
                        <button type="button" class="${state === 1 ? 'is-picked' : ''}"
                                data-poll-action="slot" data-option-id="${option.id}" data-value="1"
                                aria-label="Maybe">
                            <i class="fas fa-question"></i></button>
                    </span>` : ''}
            </div>`;
    });
    return `<div class="poll-body poll-schedule">${rows.join('')}</div>`;
}

function formatPollSlot(iso) {
    const date = new Date(iso);
    if (isNaN(date)) return '';
    return date.toLocaleString([], {
        weekday: 'short', month: 'short', day: 'numeric',
        hour: 'numeric', minute: '2-digit',
    });
}

// "Interactive" means this viewer is about to answer: the poll is open, they
// may vote, and either they haven't yet or they've asked to change it.
function pollIsInteractive(poll) {
    if (!poll.canVote) return false;
    if (!poll.hasVoted) return true;
    return !!poll.editing;
}

function pollFooterMarkup(poll) {
    const bits = [];

    if (pollIsInteractive(poll)) {
        bits.push(`<button type="button" class="poll-btn poll-btn-primary" data-poll-action="submit">
                       ${poll.hasVoted ? 'Save' : 'Vote'}</button>`);
        if (poll.hasVoted) {
            bits.push('<button type="button" class="poll-btn" data-poll-action="cancel-edit">Cancel</button>');
        }
    } else if (poll.hasVoted && !poll.isClosed && poll.canVote) {
        bits.push('<button type="button" class="poll-btn" data-poll-action="edit">Change answer</button>');
    }

    if (poll.canClose) {
        bits.push('<button type="button" class="poll-btn poll-btn-quiet" data-poll-action="close">Close poll</button>');
    }

    const notes = [`${poll.voterCount} ${poll.voterCount === 1 ? 'vote' : 'votes'}`];
    if (!poll.settings.anonymous) notes.push('Names shown');
    if (!poll.resultsVisible) notes.push('Results when it closes');

    return `
        <div class="poll-foot">
            <div class="poll-actions">${bits.join('')}</div>
            <div class="poll-meta">${escapeHtmlText(notes.join(' · '))}</div>
        </div>`;
}

// ---------------------------------------------------------------------------
// Card interaction
// ---------------------------------------------------------------------------

function wirePollCard(card, poll) {
    // One delegated listener per repaint, on the card itself. stopPropagation
    // throughout: the card sits inside a message bubble that answers clicks,
    // double clicks and swipes of its own.
    card.onclick = (event) => {
        const target = event.target.closest('[data-poll-action]');
        if (!target || !card.contains(target)) return;
        event.preventDefault();
        event.stopPropagation();
        handlePollAction(card, poll, target.dataset.pollAction, target.dataset);
    };
    card.ondblclick = (event) => event.stopPropagation();

    wirePollScale(card, poll);

    const field = card.querySelector('.poll-open-input');
    if (field) {
        field.oninput = () => { pollDraft(poll).text = field.value; };
        field.onclick = (event) => event.stopPropagation();
    }
}

// A pick repaints the whole card, so the button that was pressed is gone by
// the time the click finishes. Find its replacement and pop that one instead.
function popPollControl(card, action, data) {
    const bits = [`[data-poll-action="${action}"]`];
    if (data.optionId != null) bits.push(`[data-option-id="${data.optionId}"]`);
    if (data.value != null) bits.push(`[data-value="${data.value}"]`);
    const el = card.querySelector(bits.join(''));
    if (!el) return;
    el.classList.add('poll-pop');
    setTimeout(() => el.classList.remove('poll-pop'), 220);
}

function handlePollAction(card, poll, action, data) {
    const draft = pollDraft(poll);

    switch (action) {
        case 'pick': {
            const id = Number(data.optionId);
            if (poll.kind === 'multi') {
                const at = draft.optionIds.indexOf(id);
                if (at > -1) draft.optionIds.splice(at, 1);
                else draft.optionIds.push(id);
            } else {
                draft.optionIds = [id];
            }
            paintPollCard(card, poll);
            popPollControl(card, action, data);
            return;
        }
        case 'scale':
            draft.value = Number(data.value);
            paintPollCard(card, poll);
            popPollControl(card, action, data);
            return;
        case 'slot': {
            const key = String(data.optionId);
            const value = Number(data.value);
            draft.slots = draft.slots || {};
            if (Number(draft.slots[key]) === value) delete draft.slots[key];
            else draft.slots[key] = value;
            paintPollCard(card, poll);
            popPollControl(card, action, data);
            return;
        }
        case 'rank-up':
        case 'rank-down': {
            const id = Number(data.optionId);
            const at = draft.order.indexOf(id);
            const to = action === 'rank-up' ? at - 1 : at + 1;
            if (at < 0 || to < 0 || to >= draft.order.length) return;
            draft.order.splice(at, 1);
            draft.order.splice(to, 0, id);
            paintPollCard(card, poll);
            return;
        }
        case 'edit':
            poll.editing = true;
            pollDrafts.set(String(poll.id), seedPollDraft(poll));
            paintPollCard(card, poll);
            return;
        case 'cancel-edit':
            poll.editing = false;
            resetPollDraft(poll.id);
            paintPollCard(card, poll);
            return;
        case 'submit':
            submitPollVote(poll);
            return;
        case 'close':
            closePollFromCard(poll);
            return;
        default:
            return;
    }
}

function pollVoteBody(poll) {
    const draft = pollDraft(poll);
    switch (poll.kind) {
        case 'scale':    return { value: draft.value };
        case 'open':     return { text: (draft.text || '').trim() };
        case 'ranked':   return { order: draft.order };
        case 'schedule': return { slots: draft.slots || {} };
        default:         return { optionIds: draft.optionIds || [] };
    }
}

function submitPollVote(poll) {
    const body = pollVoteBody(poll);

    // Cheap client-side guards for the cases where the server's message would
    // arrive as a toast for something the card can see straight away.
    if (poll.kind === 'open' && !body.text) return showToast('Write an answer first.', 'error');
    if (poll.kind === 'scale' && body.value == null) return showToast('Pick a point on the scale.', 'error');
    if (poll.kind === 'schedule' && !Object.keys(body.slots).length) {
        return showToast('Mark at least one time that works.', 'error');
    }
    if (['single', 'multi', 'quiz'].includes(poll.kind) && !body.optionIds.length) {
        return showToast('Pick an option first.', 'error');
    }

    const cards = () => document.querySelectorAll(`.poll-card[data-poll-id="${poll.id}"]`);
    const setBusy = (on) => cards().forEach(card => card.classList.toggle('poll-busy', on));
    setBusy(true);

    fetch(`${API_BASE_URL}/api/polls/${poll.id}/vote`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify(body),
    })
    .then(r => r.json().then(data => ({ ok: r.ok, data })))
    .then(({ ok, data }) => {
        setBusy(false);
        if (!ok || !data.ok) {
            showToast((data && data.error) || 'Could not record your vote.', 'error');
            return;
        }
        resetPollDraft(poll.id);
        data.poll.editing = false;
        applyPollUpdate(data.poll);
        cards().forEach(card => {
            card.classList.add('poll-flash');
            setTimeout(() => card.classList.remove('poll-flash'), 520);
        });
    })
    .catch(() => {
        setBusy(false);
        showToast('Could not reach the server.', 'error');
    });
}

function closePollFromCard(poll) {
    fetch(`${API_BASE_URL}/api/polls/${poll.id}/close`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiToken}` },
    })
    .then(r => r.json().then(data => ({ ok: r.ok, data })))
    .then(({ ok, data }) => {
        if (!ok || !data.ok) return showToast((data && data.error) || 'Could not close this poll.', 'error');
        applyPollUpdate(data.poll);
        showToast('Poll closed.', 'success');
    })
    .catch(() => showToast('Could not reach the server.', 'error'));
}

// One place where a new poll payload lands: the store, the cached copies inside
// whatever list is on screen, and every card drawn from it.
function applyPollUpdate(poll) {
    if (!poll || !poll.id) return;
    const previous = pollStore.get(String(poll.id));
    if (previous && previous.editing && poll.editing === undefined) poll.editing = previous.editing;
    storePoll(poll);
    syncPollIntoCollections(poll);
    refreshPollCards(poll.id, { grow: true });
}

// The renderers read their poll from the message/post object they were handed,
// so a poll that changed has to be written back into those lists too --
// otherwise the next full re-render would paint the stale copy over the fresh
// card.
function syncPollIntoCollections(poll) {
    const id = poll.contextId;
    if (poll.contextType === 'dm') {
        Object.keys(messageHistory).forEach(name => {
            const msg = (messageHistory[name] || []).find(m => String(m.id) === String(id));
            if (msg) msg.poll = poll;
        });
    } else if (poll.contextType === 'lounge') {
        const msg = (currentLoungeMessages || []).find(m => String(m.id) === String(id));
        if (msg) msg.poll = poll;
    } else if (poll.contextType === 'circuit') {
        [currentCircuitBasePosts, currentCircuitPosts].forEach(list => {
            const post = (list || []).find(p => String(p.id) === String(id));
            if (post) post.poll = poll;
        });
        if (currentSinglePost && String(currentSinglePost.id) === String(id)) {
            currentSinglePost.poll = poll;
        }
    }
}

// The socket signal deliberately carries no tally -- what each viewer may see
// depends on whether THEY have voted -- so it means "ask again", not "here it
// is". Only asked for when this session actually has the poll on screen.
function handlePollUpdateSignal(signal) {
    const id = String(signal.poll_id);
    if (!pollStore.has(id) && !document.querySelector(`.poll-card[data-poll-id="${id}"]`)) return;
    fetch(`${API_BASE_URL}/api/polls/${id}`, { headers: { 'Authorization': `Bearer ${apiToken}` } })
        .then(r => (r.ok ? r.json() : null))
        .then(poll => { if (poll && poll.id) applyPollUpdate(poll); })
        .catch(() => { /* the next render or reload picks it up */ });
}

// ---------------------------------------------------------------------------
// Attaching a card to each surface
// ---------------------------------------------------------------------------

// Called by the DM and lounge renderers. The card goes NEXT TO the bubble
// rather than inside it: the bubble owns double-tap-to-react and
// swipe-to-reply, and a voting control inside those gestures is unusable.
function appendPollToMessage(wrapper, msg, context) {
    if (!msg || !msg.poll || msg.is_deleted) return;
    wrapper.appendChild(buildPollCard(msg.poll, context));
}

// Part of the DM renderer's bubble-reuse signature: a bubble whose poll moved
// has to be rebuilt, and nothing else about the message changed to say so.
function pollSignature(poll) {
    if (!poll) return '';
    return [
        poll.id, poll.isClosed ? 1 : 0, poll.voterCount, poll.hasVoted ? 1 : 0,
        poll.resultsVisible ? 1 : 0, poll.editing ? 1 : 0,
        poll.options.length,
        poll.options.map(o => `${o.id}:${o.count == null ? '' : o.count}`).join(','),
    ].join('|');
}

// ---------------------------------------------------------------------------
// The composer's + menu
// ---------------------------------------------------------------------------
// One button where the paperclip used to be. A composer that grows a new icon
// per attachment type ends up as a row of glyphs nobody can read; a single +
// that opens a named list stays legible however many things we can attach.

const POLL_TOOL_MENUS = { dm: 'dm-tool-menu', lounge: 'lounge-tool-menu' };
const POLL_TOOL_INPUTS = { dm: 'image-upload-input', lounge: 'lounge-image-upload-input' };

function toggleComposerTools(surface, event) {
    if (event) event.stopPropagation();
    const menu = document.getElementById(POLL_TOOL_MENUS[surface]);
    if (!menu) return;
    if (!menu.classList.contains('hidden')) return closeComposerTools();

    closeComposerTools();
    // The emoji/sticker strip and this menu both want the space above the
    // composer, and only one of them can have it.
    if (typeof closeComposerPanels === 'function') closeComposerPanels();

    menu.classList.remove('hidden');
    const button = document.getElementById(`${surface}-tool-btn`);
    if (button) button.setAttribute('aria-expanded', 'true');
    // Capture phase, so a click on any other control closes this first.
    document.addEventListener('click', composerToolsAutoClose, true);
    document.addEventListener('keydown', composerToolsEscape, true);
}

function closeComposerTools() {
    let closed = false;
    Object.keys(POLL_TOOL_MENUS).forEach(surface => {
        const menu = document.getElementById(POLL_TOOL_MENUS[surface]);
        if (menu && !menu.classList.contains('hidden')) {
            menu.classList.add('hidden');
            closed = true;
        }
        const button = document.getElementById(`${surface}-tool-btn`);
        if (button) button.setAttribute('aria-expanded', 'false');
    });
    if (closed) {
        document.removeEventListener('click', composerToolsAutoClose, true);
        document.removeEventListener('keydown', composerToolsEscape, true);
    }
    return closed;
}

function composerToolsAutoClose(event) {
    if (event.target.closest('.composer-tool-menu, .composer-tool-btn')) return;
    closeComposerTools();
}

function composerToolsEscape(event) {
    if (event.key === 'Escape') {
        event.stopPropagation();
        closeComposerTools();
    }
}

function pickComposerTool(surface, tool) {
    closeComposerTools();
    if (tool === 'photo') {
        const input = document.getElementById(POLL_TOOL_INPUTS[surface]);
        if (input) input.click();
        return;
    }
    if (tool === 'poll') openPollComposer(surface);
}

// ---------------------------------------------------------------------------
// Composer
// ---------------------------------------------------------------------------
// Two steps on purpose. Everything on one screen meant seven type chips, a
// question, an option list and eight settings all competing at once, and the
// thing being asked for -- "make a poll" -- was the smallest part of it. Step
// one is the only decision that changes the rest of the form; step two is the
// question, the options, and the three settings that are actually worth a
// choice. Nothing else is configurable, which is the point.

let pollComposerSurface = null;
let pollComposerState = null;
let pollComposerStep = 'kind';   // 'kind' | 'build'

function newPollComposerState() {
    return {
        kind: 'single',
        question: '',
        options: [{ label: '', meta: null, isCorrect: false },
                  { label: '', meta: null, isCorrect: false }],
        settings: {
            anonymous: true,
            hideResultsUntilClose: false,
            scaleMax: 5,
        },
        closesInMinutes: 0,
    };
}

// A published poll -> the composer's own shape, so the edit form opens on the
// poll as it actually stands rather than on a blank one. `closesInMinutes: -1`
// is the "leave the deadline alone" sentinel update_poll reads: an edit is
// usually about the wording, and re-picking "in 1 day" would restart the clock.
function pollStateFromPoll(poll) {
    return {
        pollId: poll.id,
        // Nobody has answered yet -> the type is still a free choice, and the
        // warning below has nothing to warn about.
        answered: (poll.voterCount || 0) > 0,
        kind: poll.kind,
        question: poll.question || '',
        options: (poll.options || []).map(option => ({
            id: option.id,
            label: option.label || '',
            meta: option.meta || null,
            isCorrect: !!option.isCorrect,
        })),
        settings: {
            anonymous: !!(poll.settings || {}).anonymous,
            hideResultsUntilClose: !!(poll.settings || {}).hideResultsUntilClose,
            scaleMax: (poll.settings || {}).scaleMax || 5,
        },
        closesInMinutes: -1,
    };
}

// Hang an already-published poll on a composer surface, as if the author had
// just built it there. Used by the edit-post page, which is the create page
// wearing a different hat.
function attachExistingPoll(surface, poll) {
    if (!poll) return clearPendingPoll(surface);
    const state = pollStateFromPoll(poll);
    state.payload = pollStateToPayload(state);
    pendingPolls[surface] = state;
    renderPollAttachment(surface);
}

function openPollComposer(surface) {
    pollComposerSurface = surface;
    const editing = !!pendingPolls[surface];
    pollComposerState = editing
        ? clonePollState(pendingPolls[surface])
        : newPollComposerState();
    // Coming back to a poll you already built opens on the poll, not on the
    // type picker you already answered.
    pollComposerStep = editing ? 'build' : 'kind';

    let modal = document.getElementById('poll-composer');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'poll-composer';
        modal.className = 'poll-composer-modal hidden';
        modal.innerHTML = `
            <div class="poll-composer-sheet" role="dialog" aria-label="Create a poll">
                <div class="poll-composer-head">
                    <h3 id="poll-composer-title">New poll</h3>
                    <button type="button" class="poll-composer-close" aria-label="Close">&times;</button>
                </div>
                <div class="poll-composer-body"></div>
                <div class="poll-composer-foot">
                    <button type="button" class="poll-btn" data-poll-composer="cancel">Cancel</button>
                    <button type="button" class="poll-btn poll-btn-primary hidden"
                            data-poll-composer="attach">Attach poll</button>
                </div>
            </div>`;
        document.body.appendChild(modal);
        modal.querySelector('.poll-composer-close').onclick = closePollComposer;
        modal.addEventListener('click', (event) => {
            if (event.target === modal) return closePollComposer();
            const action = event.target.closest('[data-poll-composer]');
            if (!action) return;
            if (action.dataset.pollComposer === 'cancel') closePollComposer();
            if (action.dataset.pollComposer === 'attach') confirmPollComposer();
        });
    }

    renderPollComposer();
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open', 'poll-composer-open');
    pushModalHistory('poll-composer', closePollComposer);
}

function closePollComposer() {
    const modal = document.getElementById('poll-composer');
    if (!modal || modal.classList.contains('hidden')) return;
    modal.classList.add('hidden');
    document.body.classList.remove('modal-open', 'poll-composer-open');
    popModalHistory('poll-composer');
}

function clonePollState(state) {
    return JSON.parse(JSON.stringify(state));
}

function renderPollComposer() {
    const body = document.querySelector('#poll-composer .poll-composer-body');
    if (!body) return;
    const attach = document.querySelector('#poll-composer [data-poll-composer="attach"]');
    const title = document.getElementById('poll-composer-title');

    if (pollComposerStep === 'kind') {
        if (attach) attach.classList.add('hidden');
        if (title) title.textContent = 'New poll';
        body.innerHTML = `<div class="poll-kind-list">${
            Object.keys(POLL_KINDS).map(kind => {
                const meta = POLL_KINDS[kind];
                return `
                    <button type="button" class="poll-kind-row" data-composer-kind="${kind}">
                        <i class="fas ${meta.icon}"></i>
                        <span class="poll-kind-text">
                            <strong>${escapeHtmlText(meta.label)}</strong>
                            <em>${escapeHtmlText(meta.blurb)}</em>
                        </span>
                        <i class="fas fa-chevron-right poll-kind-go"></i>
                    </button>`;
            }).join('')}</div>`;
        body.querySelectorAll('[data-composer-kind]').forEach(row => {
            row.onclick = () => {
                const kind = row.dataset.composerKind;
                if (kind !== pollComposerState.kind) {
                    // Changing type resets the answer shape but keeps the
                    // question -- that part is the same whatever the type.
                    const question = pollComposerState.question;
                    // The poll being edited is still the same poll, so its id
                    // survives the reshape -- only its answer shape changed.
                    const pollId = pollComposerState.pollId;
                    pollComposerState = newPollComposerState();
                    pollComposerState.kind = kind;
                    pollComposerState.question = question;
                    if (pollId) pollComposerState.pollId = pollId;
                    if (kind === 'quiz') pollComposerState.options[0].isCorrect = true;
                }
                pollComposerStep = 'build';
                renderPollComposer();
            };
        });
        return;
    }

    const state = pollComposerState;
    const meta = pollKindMeta(state.kind);
    if (attach) {
        attach.classList.remove('hidden');
        // "Attach" is wrong for a poll that is already on a published post:
        // nothing is being attached, the poll is being rewritten.
        attach.textContent = state.pollId ? 'Save poll' : 'Attach poll';
    }
    if (title) title.textContent = meta.label;

    const options = state.options.map((option, index) => `
        <div class="poll-compose-option">
            ${state.kind === 'quiz' ? `
                <button type="button" class="poll-correct-toggle ${option.isCorrect ? 'is-picked' : ''}"
                        data-composer-correct="${index}" title="This is the right answer">
                    <i class="fas ${option.isCorrect ? 'fa-circle-check' : 'fa-circle'}"></i>
                </button>` : `<span class="poll-compose-index">${index + 1}</span>`}
            ${state.kind === 'schedule' ? `
                <input type="datetime-local" data-composer-meta="${index}"
                       autocomplete="off"
                       value="${escapeHtmlText(option.meta || '')}">`
              : `<input type="text" maxlength="${POLL_OPTION_LABEL_MAX}"
                       data-composer-option="${index}" value="${escapeHtmlText(option.label)}"
                       autocomplete="off" autocorrect="off" spellcheck="false"
                       placeholder="Option ${index + 1}">`}
            <button type="button" class="poll-compose-remove" data-composer-remove="${index}"
                    ${state.options.length <= 2 ? 'disabled' : ''} aria-label="Remove">
                <i class="fas fa-xmark"></i>
            </button>
        </div>`).join('');

    // Changing the type of a poll people have answered would leave their answers
    // meaning something else, so that row stops being a button and just says what
    // the poll is. The server refuses the change too -- this only avoids offering
    // it. Note the count: what the author loses by deleting an option is the one
    // consequence of editing that the form cannot show.
    const locked = !!(state.pollId && state.answered);
    body.innerHTML = `
        ${locked ? `
        <div class="poll-kind-back is-locked">
            <i class="fas ${meta.icon}"></i>
            <span>${escapeHtmlText(meta.label)}</span>
        </div>` : `
        <button type="button" class="poll-kind-back" data-composer-back="1">
            <i class="fas fa-chevron-left"></i>
            <i class="fas ${meta.icon}"></i>
            <span>${escapeHtmlText(meta.label)}</span>
            <em>Change</em>
        </button>`}

        <input type="text" id="poll-compose-question" class="poll-compose-question"
               maxlength="${POLL_QUESTION_MAX}" value="${escapeHtmlText(state.question)}"
               autocomplete="off" autocorrect="off" spellcheck="false"
               placeholder="Ask a question…">

        ${pollTakesOptions(state.kind) ? `
            <div class="poll-compose-options">${options}</div>
            <button type="button" class="poll-btn poll-btn-ghost" data-composer-add="1"
                    ${state.options.length >= POLL_OPTION_MAX ? 'disabled' : ''}>
                <i class="fas fa-plus"></i> Add option
            </button>` : ''}

        ${state.kind === 'scale' ? `
            <label class="poll-compose-row">
                <span>Highest number</span>
                <select data-composer-setting="scaleMax">
                    ${[3, 5, 7, 10].map(n => `<option value="${n}"
                        ${state.settings.scaleMax === n ? 'selected' : ''}>1 to ${n}</option>`).join('')}
                </select>
            </label>` : ''}

        <div class="poll-compose-settings">
            <label class="poll-compose-row">
                <span>Closes</span>
                <select data-composer-closes="1">
                    ${(state.pollId
                        ? [[-1, 'Leave as it is'], [0, 'When I close it'], [60, 'In 1 hour'],
                           [360, 'In 6 hours'], [1440, 'In 1 day'], [10080, 'In 1 week']]
                        : [[0, 'When I close it'], [60, 'In 1 hour'], [360, 'In 6 hours'],
                           [1440, 'In 1 day'], [10080, 'In 1 week']]).map(([value, text]) => `
                        <option value="${value}" ${state.closesInMinutes === value ? 'selected' : ''}>${text}</option>`).join('')}
                </select>
            </label>
            <label class="poll-compose-check">
                <input type="checkbox" data-composer-setting="anonymous"
                       ${state.settings.anonymous ? 'checked' : ''}>
                <span>Keep votes anonymous</span>
            </label>
            <label class="poll-compose-check">
                <input type="checkbox" data-composer-setting="hideResultsUntilClose"
                       ${state.settings.hideResultsUntilClose ? 'checked' : ''}>
                <span>Hide results until it closes</span>
            </label>
        </div>

        ${locked ? `
            <p class="poll-compose-note"><i class="fas fa-triangle-exclamation"></i>
               People have already answered this poll. An option you delete takes
               its answers with it; the ones you keep, keep theirs.</p>` : ''}

        ${pollComposerSurface === 'circuit' ? `
            <p class="poll-compose-note"><i class="fas fa-shield-halved"></i>
               Polls on a circuit go through the same safety check as the post itself.</p>` : ''}`;

    wirePollComposer(body);
}

function wirePollComposer(body) {
    const state = pollComposerState;

    const back = body.querySelector('[data-composer-back]');
    if (back) back.onclick = () => { pollComposerStep = 'kind'; renderPollComposer(); };

    const question = body.querySelector('#poll-compose-question');
    if (question) question.oninput = () => { state.question = question.value; };

    body.querySelectorAll('[data-composer-option]').forEach(input => {
        input.oninput = () => { state.options[Number(input.dataset.composerOption)].label = input.value; };
    });
    body.querySelectorAll('[data-composer-meta]').forEach(input => {
        input.onchange = () => {
            const index = Number(input.dataset.composerMeta);
            state.options[index].meta = input.value || null;
            // A time slot names itself: there is no second thing to type.
            state.options[index].label = input.value ? (formatPollSlot(input.value) || input.value) : '';
        };
    });
    body.querySelectorAll('[data-composer-correct]').forEach(button => {
        button.onclick = () => {
            const index = Number(button.dataset.composerCorrect);
            // Exactly one right answer: a quiz card reveals "the answer".
            state.options.forEach((option, i) => { option.isCorrect = i === index; });
            renderPollComposer();
        };
    });
    body.querySelectorAll('[data-composer-remove]').forEach(button => {
        button.onclick = () => {
            if (state.options.length <= 2) return;
            state.options.splice(Number(button.dataset.composerRemove), 1);
            renderPollComposer();
        };
    });
    const add = body.querySelector('[data-composer-add]');
    if (add) add.onclick = () => {
        if (state.options.length >= POLL_OPTION_MAX) return;
        state.options.push({ label: '', meta: null, isCorrect: false });
        renderPollComposer();
    };

    body.querySelectorAll('[data-composer-setting]').forEach(input => {
        const key = input.dataset.composerSetting;
        input.onchange = () => {
            state.settings[key] = input.type === 'checkbox' ? input.checked : Number(input.value);
        };
    });

    const closes = body.querySelector('[data-composer-closes]');
    if (closes) closes.onchange = () => { state.closesInMinutes = Number(closes.value); };
}

// The composer's own shape -> the payload polls.py validates. Kept separate so
// the editing UI can hold a half-finished poll (blank options, options left
// over from another type) without that shape ever reaching the server.
function pollStateToPayload(state) {
    return {
        // Set only when editing a published poll. Its absence on a post that
        // already has one is what tells the server this is a REPLACEMENT --
        // the author took the old poll off and built another.
        id: state.pollId || undefined,
        kind: state.kind,
        question: (state.question || '').trim(),
        options: pollTakesOptions(state.kind)
            ? state.options
                .filter(option => (option.label || '').trim())
                .map(option => ({
                    // Present only when this option is already a row on a
                    // published poll. It is what lets the server tell an edited
                    // option from a replaced one, and so keep the answers on it.
                    id: option.id || undefined,
                    label: option.label.trim(),
                    // Both belong to one kind only, and must not be stored on a
                    // poll that has no use for them.
                    meta: state.kind === 'schedule' ? (option.meta || null) : null,
                    isCorrect: state.kind === 'quiz' && !!option.isCorrect,
                }))
            : [],
        settings: {
            anonymous: state.settings.anonymous,
            hideResultsUntilClose: state.settings.hideResultsUntilClose,
            scaleMax: state.settings.scaleMax,
        },
        closesInMinutes: state.closesInMinutes,
    };
}

// The same rules polls.py enforces, said here so the author hears about a
// missing option while they are still looking at the form. The server is still
// the one that decides.
function pollPayloadProblem(payload) {
    if (!payload.question) return 'A poll needs a question.';
    if (pollTakesOptions(payload.kind)) {
        if (payload.options.length < 2) {
            return payload.kind === 'schedule' ? 'Add at least 2 times.' : 'Add at least 2 options.';
        }
        const seen = new Set(payload.options.map(o => o.label.toLowerCase()));
        if (seen.size !== payload.options.length) return 'Two options say the same thing.';
    }
    if (payload.kind === 'quiz' && !payload.options.some(o => o.isCorrect)) {
        return 'Mark which answer is correct.';
    }
    return null;
}

function confirmPollComposer() {
    const payload = pollStateToPayload(pollComposerState);
    const problem = pollPayloadProblem(payload);
    if (problem) return showToast(problem, 'error');

    pendingPolls[pollComposerSurface] = clonePollState(pollComposerState);
    pendingPolls[pollComposerSurface].payload = payload;
    renderPollAttachment(pollComposerSurface);
    closePollComposer();
}

// The chip that says a poll is riding along with this message or post.
function renderPollAttachment(surface) {
    const host = document.getElementById(`poll-attachment-${surface}`);
    if (!host) return;
    const pending = pendingPolls[surface];

    // The new-post page has room to show the poll itself, and does -- see
    // renderCircuitPollWell. A DM or lounge composer is one strip tall, so
    // those keep the one-line chip.
    if (surface === 'circuit') return renderCircuitPollWell(host, pending);

    if (!pending) {
        host.classList.add('hidden');
        host.innerHTML = '';
    } else {
        const meta = pollKindMeta(pending.kind);
        host.classList.remove('hidden');
        host.innerHTML = `
            <div class="poll-chip">
                <i class="fas ${meta.icon}"></i>
                <span>${escapeHtmlText(pending.payload.question)}</span>
                <button type="button" class="poll-chip-edit" aria-label="Edit poll"><i class="fas fa-pen"></i></button>
                <button type="button" class="poll-chip-remove" aria-label="Remove poll"><i class="fas fa-xmark"></i></button>
            </div>`;
        host.querySelector('.poll-chip-edit').onclick = () => openPollComposer(surface);
        host.querySelector('.poll-chip-remove').onclick = () => clearPendingPoll(surface);
    }
}

/**
 * The new-post page's poll slot, which is deliberately shaped like the picture
 * well above it: a dashed empty rectangle you click, and once it holds
 * something, the thing it holds. A poll is the only attachment that cannot be
 * seen -- a picture previews itself -- so an unopened poll used to be a button
 * reading "Add a poll" and an attached one a chip reading its question back.
 * Drawing the poll instead means the author reviews what they are posting in
 * the place the poll will occupy, and the two attachments read as one idea.
 */
function renderCircuitPollWell(host, pending) {
    host.classList.remove('hidden');

    if (!pending) {
        host.innerHTML = `
            <button type="button" class="poll-well is-empty">
                <span class="poll-well-ghost" aria-hidden="true">
                    <span class="poll-well-ghost-line is-question"></span>
                    <span class="poll-well-ghost-line"></span>
                    <span class="poll-well-ghost-line is-short"></span>
                </span>
                <span class="poll-well-cta">+ Add Poll</span>
            </button>`;
        host.querySelector('.poll-well').onclick = () => openPollComposer('circuit');
        return;
    }

    const meta = pollKindMeta(pending.kind);
    host.innerHTML = `
        <div class="poll-well is-set" role="group" aria-label="Attached poll">
            <button type="button" class="remove-preview-btn" aria-label="Remove poll" title="Remove poll">
                <i class="fas fa-xmark"></i>
            </button>
            <div class="poll-well-kind"><i class="fas ${meta.icon}"></i>${escapeHtmlText(meta.label)}</div>
            <div class="poll-well-question">${escapeHtmlText(pending.payload.question)}</div>
            ${circuitPollWellBody(pending.payload)}
            <div class="poll-well-hint"><i class="fas fa-pen"></i>Tap to edit</div>
        </div>`;
    host.querySelector('.poll-well').onclick = (e) => {
        if (e.target.closest('.remove-preview-btn')) {
            e.stopPropagation();
            clearPendingPoll('circuit');
            return;
        }
        openPollComposer('circuit');
    };
}

// The rows the posted card will show, minus everything that only exists after
// people have voted. Read-only on purpose: this is a preview, not a card you
// can answer before it has been posted.
function circuitPollWellBody(payload) {
    if (payload.kind === 'scale') {
        const top = (payload.settings || {}).scaleMax || 5;
        let dots = '';
        for (let n = 1; n <= top; n++) dots += `<span class="poll-well-dot">${n}</span>`;
        return `<div class="poll-well-rows is-dots">${dots}</div>`;
    }
    if (payload.kind === 'open') {
        return `<div class="poll-well-rows"><span class="poll-well-open">Everyone writes a short reply.</span></div>`;
    }

    // Four is what fits before the well is taller than the picture well; the
    // rest are counted rather than listed.
    const shown = payload.options.slice(0, 4);
    const rest = payload.options.length - shown.length;
    const rows = shown.map((option, i) => {
        const icon = option.isCorrect ? 'fa-circle-check is-correct'
                                     : pollPickIcon(payload.kind, false);
        const mark = payload.kind === 'ranked'
            ? `<span class="poll-well-rank">${i + 1}</span>`
            : `<i class="fas ${icon}"></i>`;
        return `
            <span class="poll-well-row">
                ${mark}<span class="poll-well-label">${escapeHtmlText(option.label)}</span>
            </span>`;
    }).join('');
    const more = rest > 0 ? `<span class="poll-well-more">+${rest} more</span>` : '';
    return `<div class="poll-well-rows">${rows}${more}</div>`;
}

function clearPendingPoll(surface) {
    pendingPolls[surface] = null;
    renderPollAttachment(surface);
}

// What the send functions ask for: the payload to put on the request, or null.
function takePendingPoll(surface) {
    return pendingPolls[surface] ? pendingPolls[surface].payload : null;
}

/* =====================================================================
   Mascot -- the link-headed kid from mascot.png, cut into layers
   (icons/mascot/*.webp) so every part moves on its own.

   Two halves:
   - Mascot: one rig. Talks (bubble), holds a pose (data-pose), does a move
     (data-act), faces a way, looks toward a point and -- for roaming rigs --
     walks, hops or falls to a spot in its stage. The motion itself is CSS
     ("Mascot" in style.css); this only flips attributes and sets variables.
   - Scenes, one per place he appears:
       LoginMascotScene   a talking bot. Says the admin's lines in order; a tap
                          makes him jump and moves to the next one. Every few
                          seconds he does something of his own on top of the
                          card: strolls, hops along, dances, sits, trips, plays
                          peekaboo behind it, falls off the end and climbs back.
       HomeMascotScene    the same lines and the same kind of fidgeting, beside
                          the logo.
       AccountTypeMascotScene, SignupMascotScene
                          a guide. No admin lines, no tapping: walks and hops
                          to each step, keeps its instruction up until it's
                          done, and cheers people on as they go.

   On/off per spot, the login/home lines and their timing come from
   Admin Panel -> Mascot (/api/mascot/lines).
   ===================================================================== */

// Bump when the art in icons/mascot/ changes; the files are cached by URL.
const MASCOT_ASSET_V = '3';
// Back to front: the arms and feet tuck under the body, the body under the head.
// head/body also have a back view, shown when he turns around.
const MASCOT_PARTS = ['foot-l', 'foot-r', 'arm-l', 'arm-r', 'body', 'head'];
const MASCOT_BACK_PARTS = ['body', 'head'];
const MASCOT_SPOTS = ['login', 'register', 'home'];
const MASCOT_ON_KEY = 'apexMascotSpots';
const MASCOT_DEFAULT_INTERVAL_S = 6;
// Where his feet are, as a fraction of the figure's height from the top.
const MASCOT_FOOT = 0.975;
// Used only when the admin hasn't written any lines for a spot.
const MASCOT_DEFAULT_LINES = {
    login: [
        "Welcome, Student Council! 👋",
        "Log in and say hi!",
        "Lounges, circuits, DMs. It's all in here.",
    ],
    home: [
        "Hi {name}! 👋",
        "Welcome to APEX, Student Council!",
        "Check out what's trending today.",
    ],
};

let mascotConfig = { enabled: {}, lines: {}, intervals: {} };
const mascotScenes = [];
let mascotTicker = null;
let mascotLastActivity = Date.now();

const mascotReducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const mascotRand = (a, b) => a + Math.random() * (b - a);
const mascotClamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const mascotShort = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
const mascotSleepMs = (ms) => new Promise(r => setTimeout(r, ms));

function mascotLinesFor(spot) {
    const custom = mascotConfig.lines && mascotConfig.lines[spot];
    return (Array.isArray(custom) && custom.length) ? custom : (MASCOT_DEFAULT_LINES[spot] || []);
}

// Milliseconds between lines for a spot, or null: stay on a line until tapped.
function mascotIntervalMs(spot) {
    const intervals = mascotConfig.intervals || {};
    if (spot in intervals && intervals[spot] === null) return null;
    const s = Number(intervals[spot]);
    return (Number.isFinite(s) && s >= 3 ? s : MASCOT_DEFAULT_INTERVAL_S) * 1000;
}

function mascotFillLine(line) {
    const me = (typeof profileData !== 'undefined' && profileData.me) || {};
    const first = String(me.name || '').trim().split(/\s+/)[0] || me.username || 'there';
    return line.replace(/\{name\}/g, first);
}

// An element's box in a stage's coordinates -- the space an absolutely positioned
// child of that stage is laid out in, scroll included.
function mascotRel(el, stage) {
    const r = el.getBoundingClientRect();
    const s = stage.getBoundingClientRect();
    const ox = s.left + stage.clientLeft - stage.scrollLeft;
    const oy = s.top + stage.clientTop - stage.scrollTop;
    return {
        left: r.left - ox, right: r.right - ox, top: r.top - oy, bottom: r.bottom - oy,
        width: r.width, height: r.height,
        cx: r.left - ox + r.width / 2, cy: r.top - oy + r.height / 2,
    };
}

/* ------------------------------------------------------------------ */
/* One rig                                                             */
/* ------------------------------------------------------------------ */
class Mascot {
    constructor(root) {
        this.root = root;
        this.spot = root.dataset.mascot;
        this.roaming = root.classList.contains('is-roaming');
        this.face = 1;
        this.x = null;
        this.y = null;
        this.moving = false;
        this.inTravel = false;
        this.timers = {};
        this.build();
    }

    build() {
        const el = (tag, cls) => { const e = document.createElement(tag); e.className = cls; return e; };
        this.bubble = el('div', 'mascot-bubble');
        this.stepEl = el('span', 'mascot-step');
        this.stepEl.hidden = true;
        this.text = el('span', 'mascot-bubble-text');
        this.bubble.append(this.stepEl, this.text);
        this.fx = el('div', 'mascot-fx');

        // A div, not a button: handleLogin() finds its button as the first <button>
        // on the login page, and this sits in front of the form.
        this.figure = el('div', 'mascot-figure');
        const facing = el('div', 'mascot-facing');
        const shadow = el('span', 'mascot-shadow');
        const act = el('div', 'mascot-act');
        const rig = el('div', 'mascot-rig');
        const img = (file, cls) => {
            const i = document.createElement('img');
            i.className = cls;
            i.src = `/icons/mascot/${file}.webp?v=${MASCOT_ASSET_V}`;
            i.alt = '';
            i.draggable = false;
            i.decoding = 'async';
            rig.appendChild(i);
        };
        MASCOT_PARTS.forEach(part => {
            const file = part.replace('-', '_');
            const hasBack = MASCOT_BACK_PARTS.includes(part);
            img(file, `mascot-part mascot-${part}${hasBack ? ' has-back' : ''}`);
            if (hasBack) img(`${file}_back`, `mascot-part mascot-${part} is-back`);
        });
        act.appendChild(rig);
        facing.append(shadow, act);
        this.figure.appendChild(facing);
        this.root.append(this.bubble, this.fx, this.figure);
        // Decoration: nothing for a screen reader to repeat, no Tab stop.
        this.root.setAttribute('aria-hidden', 'true');
        this.root.dataset.mounted = '1';
    }

    get w() { return this.figure.offsetWidth || 80; }
    get h() { return this.figure.offsetHeight || 110; }
    get pose() { return this.root.dataset.pose || null; }
    get traveling() { return this.moving || this.inTravel; }
    showing() { return this.root.getClientRects().length > 0; }

    // ---- speech -------------------------------------------------------
    say(text, { step = '', mood = '' } = {}) {
        clearTimeout(this.timers.say);
        const root = this.root;
        const same = root.classList.contains('has-line')
            && this.text.textContent === (text || '') && this.stepEl.textContent === step;
        const setMood = () => { if (mood) this.bubble.dataset.mood = mood; else delete this.bubble.dataset.mood; };
        if (same) { setMood(); return; }
        const apply = () => {
            this.text.textContent = text || '';
            this.stepEl.textContent = step;
            this.stepEl.hidden = !step;
            setMood();
            root.classList.toggle('has-line', !!text);
            root.classList.remove('is-swapping');
            this.fitBubble();
        };
        if (root.classList.contains('has-line')) {
            root.classList.add('is-swapping');
            this.timers.say = setTimeout(apply, 180);
        } else {
            apply();
        }
    }

    hush() {
        clearTimeout(this.timers.say);
        this.root.classList.remove('has-line', 'is-swapping');
    }

    // Keep the bubble on screen: slide it sideways, the tail stays over his head.
    fitBubble() {
        if (!this.roaming) return;
        const root = this.root.getBoundingClientRect();
        const half = this.bubble.offsetWidth / 2;
        const center = root.left + root.width / 2;
        const vw = document.documentElement.clientWidth;
        const margin = 10;
        let dx = 0;
        if (center - half < margin) dx = margin - (center - half);
        else if (center + half > vw - margin) dx = (vw - margin) - (center + half);
        this.root.style.setProperty('--bubble-dx', `${Math.round(dx)}px`);
    }

    // ---- body ---------------------------------------------------------
    setPose(name) {
        // Poses where he's (partly) behind the login card.
        const behind = (p) => p === 'hide' || p === 'hang' || p === 'pullup';
        const wasHidden = behind(this.pose);
        if (name) this.root.dataset.pose = name; else delete this.root.dataset.pose;
        clearTimeout(this.timers.behind);
        if (behind(name)) {
            this.root.classList.add('is-behind');
        } else if (wasHidden) {
            // Still under the card while he climbs back up over its edge (the rig's
            // 0.9s translate), or he'd pop in front of it for the whole climb.
            this.timers.behind = setTimeout(() => this.root.classList.remove('is-behind'), 950);
        } else {
            this.root.classList.remove('is-behind');
        }
    }

    act(name, ms = 1200) {
        clearTimeout(this.timers.act);
        delete this.root.dataset.act;
        void this.root.offsetWidth;          // restart it if it's the same move again
        this.root.dataset.act = name;
        this.timers.act = setTimeout(() => {
            if (this.root.dataset.act === name) delete this.root.dataset.act;
        }, ms);
    }

    // Turning around (or back): the head and body swap views halfway through.
    turn(away) {
        if ((this.pose === 'away') === away) return;
        this.act('turn', 500);
        this.setPose(away ? 'away' : null);
    }

    look(deg) {
        this.root.style.setProperty('--look', `${mascotClamp(deg, -6, 6).toFixed(1)}deg`);
    }

    facing(dir) {
        if (!dir) return;
        this.face = dir > 0 ? 1 : -1;
        this.root.style.setProperty('--face', this.face);
    }

    zzz() {
        if (mascotReducedMotion()) return;
        [0, 1, 2].forEach(i => {
            const z = document.createElement('span');
            z.className = 'mfx-z';
            z.textContent = 'z';
            z.style.setProperty('--s', `${13 + i * 4}px`);
            z.style.setProperty('--dx', `${12 + i * 8}`);
            z.style.setProperty('--delay', `${i * 0.7}s`);
            this.fx.appendChild(z);
            setTimeout(() => z.remove(), 3200 + i * 700);
        });
    }

    // ---- getting around (roaming rigs) ---------------------------------
    // (x, y) is where his feet go, in stage pixels. Resolves true when he arrives,
    // false if another move replaced this one first.
    place(x, y, { mode = 'teleport', turn = true } = {}) {
        if (!this.roaming) return Promise.resolve(true);
        const tx = Math.round(x - this.w / 2);
        const ty = Math.round(y - this.h * MASCOT_FOOT);
        const first = this.x === null;
        const dist = first ? 0 : Math.hypot(tx - this.x, ty - this.y);

        clearTimeout(this.timers.move);
        if (this.arrive) { const a = this.arrive; this.arrive = null; a(false); }
        this.root.classList.remove('is-walking', 'is-hopping');

        const set = () => {
            this.root.style.setProperty('--mx', `${tx}px`);
            this.root.style.setProperty('--my', `${ty}px`);
            this.x = tx;
            this.y = ty;
        };
        if (first || mode === 'teleport' || dist < 3 || mascotReducedMotion()) {
            this.root.style.setProperty('--move-ms', '0ms');
            set();
            this.moving = false;
            this.root.classList.add('is-placed');
            requestAnimationFrame(() => this.fitBubble());
            return Promise.resolve(true);
        }

        if (turn && mode !== 'fall' && Math.abs(tx - this.x) > 8) this.facing(tx > this.x ? 1 : -1);
        let ms;
        let ease;
        if (mode === 'walk') { ms = mascotClamp(dist / 150 * 1000, 400, 3000); ease = 'linear'; }
        else if (mode === 'fall') { ms = mascotClamp(300 + dist * 0.9, 500, 1000); ease = 'cubic-bezier(.5,0,.9,.4)'; }
        else { ms = mascotClamp(320 + dist * 0.8, 420, 650); ease = 'cubic-bezier(.45,.05,.55,.95)'; }
        this.root.style.setProperty('--move-ms', `${Math.round(ms)}ms`);
        this.root.style.setProperty('--move-ease', ease);
        if (mode === 'walk') this.root.classList.add('is-walking');
        if (mode === 'hop') this.root.classList.add('is-hopping');
        set();
        this.moving = true;

        return new Promise(resolve => {
            this.arrive = resolve;
            this.timers.move = setTimeout(() => {
                this.root.classList.remove('is-walking', 'is-hopping');
                this.moving = false;
                this.arrive = null;
                this.fitBubble();
                resolve(true);
            }, ms);
        });
    }

    // Get somewhere on foot: walk if it's roughly level, otherwise hop there in
    // hops of up to ~140px, like going down steps. Resolves false if interrupted.
    async travel(x, y, { turn = true } = {}) {
        const token = (this.travelToken = (this.travelToken || 0) + 1);
        if (this.x === null) return this.place(x, y);
        const fx = this.x + this.w / 2;
        const fy = this.y + this.h * MASCOT_FOOT;
        const dx = x - fx;
        const dy = y - fy;
        if (Math.abs(dy) < 40) return this.place(x, y, { mode: 'walk', turn });
        if (turn && Math.abs(dx) > 8) this.facing(dx > 0 ? 1 : -1);
        const hops = Math.max(1, Math.ceil(Math.abs(dy) / 140));
        this.inTravel = true;
        try {
            for (let i = 1; i <= hops; i++) {
                const ok = await this.place(fx + dx * i / hops, fy + dy * i / hops, { mode: 'hop', turn: false });
                if (!ok || token !== this.travelToken) return false;
                if (i < hops) await mascotSleepMs(70);
            }
            return true;
        } finally {
            if (token === this.travelToken) this.inTravel = false;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Scenes                                                              */
/* ------------------------------------------------------------------ */
class MascotScene {
    constructor(m) {
        this.m = m;
        this.active = false;
        this.asleep = false;
        this.busy = false;          // in the middle of one of his own actions
        this.lastAction = '';
        this.nextActionAt = 0;
        this.timers = {};
    }

    get stage() { return this.m.root.offsetParent || this.m.root.parentElement; }

    // Active = his page is the one on screen. Another window or tab being in front
    // just pauses him; it doesn't count as leaving, so nothing restarts.
    tick(now) {
        if (document.hidden) return;
        const showing = this.m.showing();
        if (showing && !this.active) { this.active = true; this.nextActionAt = now + mascotRand(2500, 4500); this.onShow(); }
        else if (!showing && this.active) { this.active = false; this.onHide(); }
        if (!this.active) return;
        if (!this.asleep && !this.busy && !this.m.traveling && this.canSleep() && now - mascotLastActivity > this.sleepAfter()) {
            this.sleep();
        }
        if (this.asleep) return;
        this.update(now);
        if (!this.busy && !this.m.traveling && now >= this.nextActionAt) {
            this.nextActionAt = now + this.actionGap();
            if (this.canAct()) this.doSomething(this.actions());
        }
    }

    onShow() { this.layout(); }
    onHide() { this.wake(true); }
    update() {}
    layout() {}
    canSleep() { return true; }
    sleepAfter() { return 60000; }
    restPose() { return null; }
    afterWake() {}
    actions() { return {}; }
    canAct() { return true; }
    actionGap() { return mascotRand(4000, 7500); }

    // Pick something to do (weighted, never the same thing twice in a row) and do it.
    async doSomething(actions) {
        const entries = Object.entries(actions).filter(([name]) => name !== this.lastAction);
        if (!entries.length) return;
        let r = Math.random() * entries.reduce((sum, [, a]) => sum + a.weight, 0);
        const [name, action] = entries.find(([, a]) => (r -= a.weight) < 0) || entries[0];
        this.lastAction = name;
        this.busy = true;
        try { await action.run(); } finally {
            this.busy = false;
            if (this.active && !this.asleep) this.settle();
        }
    }

    // Back to whatever pose fits the moment, after an action.
    settle() { this.m.setPose(this.restPose()); }

    // Moves most scenes can use.
    commonActions() {
        const m = this.m;
        const wait = mascotSleepMs;
        return {
            jump:     { weight: 2,   run: async () => { m.act('jump', 650); await wait(900); } },
            bigJump:  { weight: 1,   run: async () => { m.act('big-jump', 900); await wait(1200); } },
            wave:     { weight: 2,   run: async () => { m.act('wave', 1400); await wait(1600); } },
            dance:    { weight: 1.5, run: async () => { m.setPose('dance'); await wait(mascotRand(2400, 3600)); m.setPose(null); await wait(300); } },
            sit:      { weight: 1,   run: async () => { m.setPose('sit'); await wait(mascotRand(3500, 5500)); m.setPose(null); await wait(400); m.act('jump', 650); await wait(800); } },
            stretch:  { weight: 1,   run: async () => { m.act('stretch', 2000); await wait(2200); } },
            look:     { weight: 2,   run: async () => { const f = m.face; m.facing(-f); await wait(1000); m.facing(f); await wait(800); m.act('nod', 1200); await wait(1200); } },
            behind:   { weight: 1,   run: async () => { m.turn(true); await wait(mascotRand(1800, 2800)); m.turn(false); await wait(700); } },
        };
    }

    sleep() {
        this.asleep = true;
        this.m.hush();
        this.m.look(0);
        this.m.act('stretch', 2000);
        this.timers.doze = setTimeout(() => {
            if (!this.asleep) return;
            this.m.setPose('sleep');
            this.m.zzz();
            this.timers.zzz = setInterval(() => this.m.zzz(), 3600);
        }, 1900);
    }

    wake(quiet = false) {
        if (!this.asleep) return;
        this.asleep = false;
        clearTimeout(this.timers.doze);
        clearInterval(this.timers.zzz);
        this.m.setPose(this.restPose());
        this.nextActionAt = Date.now() + 2500;
        if (quiet) return;
        this.m.act('jump', 650);
        this.afterWake();
    }
}

/* ---------------- Talking bot: admin lines; a tap jumps and moves to the next ---------------- */
class ChattyMascotScene extends MascotScene {
    constructor(m) {
        super(m);
        this.lineIndex = -1;
        this.nextLineAt = 0;
        this.chatterStale = false;
        m.figure.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            mascotActivity();
            if (!this.active || this.asleep || !this.canTalk()) return;
            this.m.act('jump', 650);
            this.nextLine(false);
        });
    }

    canTalk() { return true; }

    showLine(wave) {
        const lines = mascotLinesFor(this.m.spot);
        if (!lines.length) { this.m.hush(); return; }
        this.lineIndex = mascotClamp(this.lineIndex, 0, lines.length - 1);
        this.m.say(mascotFillLine(lines[this.lineIndex]));
        const interval = mascotIntervalMs(this.m.spot);
        this.nextLineAt = interval === null ? Infinity : Date.now() + interval;
        if (wave && !this.busy && !this.m.pose && !this.m.traveling) this.m.act('wave', 1400);
    }

    nextLine(wave = true) {
        const lines = mascotLinesFor(this.m.spot);
        if (!lines.length) return;
        this.lineIndex = (this.lineIndex + 1) % lines.length;
        this.showLine(wave);
    }

    onShow() {
        this.layout();
        if (this.lineIndex < 0) this.lineIndex = 0;
        this.showLine(false);
    }

    afterWake() { this.showLine(false); }

    update(now) {
        if (!this.canTalk()) return;
        if (this.chatterStale) { this.chatterStale = false; this.lineIndex = 0; this.showLine(false); return; }
        if (now >= this.nextLineAt) this.nextLine();
    }
}

/* ---------------- Home header: lines, and always up to something ---------------- */
class HomeMascotScene extends ChattyMascotScene {
    canSleep() { return false; }
    actions() {
        const a = this.commonActions();
        a.nod = { weight: 1, run: async () => { this.m.act('nod', 1200); await mascotSleepMs(1300); } };
        return a;
    }
}

/* ---------------- Login: lines, plus a life of his own on top of the card ---------------- */
class LoginMascotScene extends ChattyMascotScene {
    constructor(m) {
        super(m);
        this.slide = m.root.closest('.login-slide');
        this.card = this.slide.querySelector('.auth-form');
        this.user = document.getElementById('loginIdentifier');
        this.pass = document.getElementById('loginPassword');
        this.u = 1;                  // where he stands along the card's top edge, 0..1
        this.falling = false;        // off the card or ducked behind it: no bubble until he's back
        this.wire();
    }

    canTalk() { return !this.falling; }
    canSleep() { return this.m.pose !== 'away' && !this.typing(); }
    typing() { return document.activeElement === this.user || document.activeElement === this.pass; }
    canAct() { return !this.typing(); }
    actionGap() { return mascotRand(3500, 7000); }

    // The card's top edge, in stage px, and his feet's height on it.
    ledge() {
        const c = mascotRel(this.card, this.stage);
        // Short screen: shrink him to fit the space above the card.
        this.m.root.style.removeProperty('--mascot-h');
        const room = c.top - 70;
        if (room < this.m.h + 4) this.m.root.style.setProperty('--mascot-h', `${Math.max(56, Math.floor(room))}px`);
        const inset = 22 + this.m.w / 2;
        return { c, y: c.top + this.m.h * 0.07, from: c.left + inset, to: c.right - inset };
    }

    xAt(u) { const l = this.ledge(); return l.from + (l.to - l.from) * u; }

    layout() {
        if (this.busy || this.m.traveling) return;
        this.m.place(this.xAt(this.u), this.ledge().y);
    }

    onShow() {
        super.onShow();
        requestAnimationFrame(() => this.layout());
        this.m.facing(this.u > 0.5 ? 1 : -1);
    }

    restPose() {
        if (document.activeElement === this.pass) return 'away';
        if (document.activeElement === this.user) return 'watch';
        return null;
    }

    settle() {
        const want = this.restPose();
        if (want === 'away') { if (this.m.pose !== 'away') this.m.turn(true); }
        else if (this.m.pose === 'away') this.m.turn(false);
        else this.m.setPose(want);
    }

    wire() {
        this.user.addEventListener('focus', () => { if (this.active) { this.wake(true); if (!this.busy) this.settle(); } });
        this.user.addEventListener('input', () => {
            if (!this.active || this.busy || this.timers.tick) return;
            this.m.act('tick', 220);
            this.timers.tick = setTimeout(() => { this.timers.tick = null; }, 200);
        });
        // Turning around for a password can't wait for whatever he's in the middle of.
        this.pass.addEventListener('focus', () => { if (this.active) { this.wake(true); this.m.look(0); this.settle(); } });
        // Blur from switching windows doesn't count -- the box still has focus in the page.
        [this.user, this.pass].forEach(el => el.addEventListener('blur', () => {
            if (!this.active || !document.hasFocus()) return;
            setTimeout(() => { if (!this.busy) this.settle(); }, 0);
        }));

        // His head follows the pointer, a little.
        document.addEventListener('pointermove', (e) => {
            if (!this.active || this.asleep || this.busy || e.pointerType !== 'mouse' || this.timers.lookFrame) return;
            this.timers.lookFrame = requestAnimationFrame(() => {
                this.timers.lookFrame = null;
                if (this.m.pose) { this.m.look(0); return; }
                const r = this.m.figure.getBoundingClientRect();
                const dx = e.clientX - (r.left + r.width / 2);
                const dy = e.clientY - (r.top + r.height * 0.3);
                this.m.look((dx / 60 + dy / 160) * this.m.face);
            });
        }, { passive: true });

        if ('ResizeObserver' in window) new ResizeObserver(() => { if (this.active) this.layout(); }).observe(this.card);
    }

    // Somewhere else along the card, not too close to where he is now.
    elsewhere() {
        let u;
        do { u = Math.random(); } while (Math.abs(u - this.u) < 0.3);
        return u;
    }

    actions() {
        const m = this.m;
        const wait = mascotSleepMs;
        const a = this.commonActions();
        a.stroll = { weight: 3, run: async () => {
            m.look(0);
            this.u = this.elsewhere();
            if (await m.place(this.xAt(this.u), this.ledge().y, { mode: 'walk' })) await wait(400);
        } };
        a.hopAlong = { weight: 2, run: async () => {
            m.look(0);
            const target = this.elsewhere();
            const from = this.u;
            const n = 3;
            for (let i = 1; i <= n; i++) {
                this.u = from + (target - from) * (i / n);
                if (!await m.place(this.xAt(this.u), this.ledge().y, { mode: 'hop' })) return;
                await wait(120);
            }
        } };
        a.trip = { weight: 1, run: async () => {
            m.look(0);
            const dir = this.u > 0.5 ? -1 : 1;
            this.u = mascotClamp(this.u + dir * 0.25, 0, 1);
            const walking = m.place(this.xAt(this.u), this.ledge().y, { mode: 'walk' });
            await wait(450);
            m.act('stumble', 800);
            await walking;
            await wait(900);
            m.act('nod', 1200);
            await wait(1000);
        } };
        a.peekaboo = { weight: 1.5, run: async () => {
            m.look(0);
            // The bubble goes down with him and only comes back once he's up again;
            // left up, it would hang in the air and then jump to the new spot.
            const line = m.root.classList.contains('has-line');
            this.falling = true;
            m.hush();
            m.setPose('hide');                     // duck behind the card
            await wait(1400);
            this.u = this.elsewhere();
            m.place(this.xAt(this.u), this.ledge().y);
            m.facing(Math.random() < 0.5 ? 1 : -1);
            await wait(700);
            m.setPose(null);                       // climb up somewhere else
            await wait(1000);
            m.act('jump', 650);
            await wait(700);
            this.falling = false;
            if (line) this.showLine(false);
        } };
        // Going over the edge is a flat 10% of everything he does, not a weight
        // that shifts as the other moves change.
        if (this.lastAction !== 'fallOff' && Math.random() < 0.1) {
            return { fallOff: { weight: 1, run: () => this.fallOff() } };
        }
        return a;
    }

    rumble() {
        const page = this.m.root.closest('.page');
        if (!page || mascotReducedMotion()) return;
        page.classList.remove('is-rumbling');
        void page.offsetWidth;
        page.classList.add('is-rumbling');
        clearTimeout(this.timers.rumble);
        this.timers.rumble = setTimeout(() => page.classList.remove('is-rumbling'), 800);
    }

    async fallOff() {
        const m = this.m;
        const wait = mascotSleepMs;
        m.look(0);
        const side = this.u > 0.5 ? 1 : -1;
        const l = this.ledge();
        const edgeX = side > 0 ? l.c.right + m.w * 0.12 : l.c.left - m.w * 0.12;
        if (!await m.place(edgeX, l.y, { mode: 'walk' })) return;
        m.facing(side);
        m.setPose('teeter');
        await wait(1700);
        this.falling = true;
        const line = m.root.classList.contains('has-line');
        m.hush();
        m.setPose('fall');                          // tumbling (see mascot-tumble)
        await m.place(edgeX + side * m.w * 0.9, this.slide.clientHeight + m.h * 1.2, { mode: 'fall', turn: false });
        // He's hit the bottom somewhere out of sight: the whole page shakes.
        this.rumble();
        await wait(1500);

        // Round behind the card, under the end he fell from...
        this.u = side > 0 ? 1 : 0;
        m.setPose('hide');
        m.place(this.xAt(this.u), this.ledge().y);
        m.facing(-side);
        await wait(1000);
        // ...hands over the edge first...
        m.setPose('hang');
        await wait(1300);
        // ...then haul up, elbows on the card...
        m.setPose('pullup');
        await wait(1200);
        // ...and a hop up onto it.
        m.setPose(null);
        m.act('jump', 650);
        await wait(1000);
        m.act('shake-off', 900);
        await wait(800);
        this.falling = false;
        if (line) this.showLine(false);
    }
}

/* ---------------- Guide scenes (register) ---------------- */
class GuideMascotScene extends MascotScene {
    constructor(m) {
        super(m);
        this.message = null;   // { text, step, mood } -- stays up until replaced
    }

    actionGap() { return mascotRand(7000, 11000); }
    canAct() { return !this.m.traveling && this.m.pose !== 'away'; }

    // Show an instruction and keep it. When he's on his way somewhere, it waits
    // until he gets there.
    guide(text, opts = {}) {
        this.message = { text, ...opts };
        if (!this.m.traveling && !this.asleep) this.m.say(text, opts);
    }

    // Go somewhere (walking, or hopping for a change of height) with the bubble
    // down, then say what's pending.
    async go(x, y, { face, pose } = {}) {
        const m = this.m;
        const far = m.x !== null && Math.hypot(x - m.w / 2 - m.x, y - m.h * MASCOT_FOOT - m.y) > 30;
        if (far) m.hush();
        if (m.pose !== 'away') m.setPose(null);
        const ok = await m.travel(x, y, { turn: true });
        if (!ok) return false;
        if (face !== undefined) m.facing(face);
        if (pose !== undefined && m.pose !== 'away') m.setPose(pose);
        if (this.message && !this.asleep) m.say(this.message.text, this.message);
        return true;
    }

    afterWake() {
        if (this.message) this.m.say(this.message.text, this.message);
    }

    // While waiting on someone: fidget, then face the job again.
    actions() {
        const m = this.m;
        const wait = mascotSleepMs;
        const c = this.commonActions();
        return {
            tapFoot: { weight: 2, run: async () => { m.setPose('tap-foot'); await wait(2600); } },
            jump: c.jump,
            wave: c.wave,
            stretch: c.stretch,
            look: c.look,
            nod: { weight: 1.5, run: async () => { m.act('nod', 1200); await wait(1300); } },
        };
    }

    settle() {
        const face = this.restFace ? this.restFace() : undefined;
        if (face !== undefined) this.m.facing(face);
        this.m.setPose(this.restPose());
    }
}

/* ---------------- Register, step 1: choosing an account type ---------------- */
const MASCOT_TYPE_TIPS = {
    student: "Student! 🎒 Perfect if you go to a school on APEX. You'll pick your school next.",
    teacher: "Teacher! 📚 For educators. We'll also ask what subject you teach.",
    team: 'Team! 🏆 For clubs and groups, like Student Council 😉',
};
const MASCOT_TYPE_INTRO = "Hey there! 👋 I'm here to help you make your account. First up: what kind of account are you?";

class AccountTypeMascotScene extends GuideMascotScene {
    constructor(m) {
        super(m);
        this.page = m.root.closest('.page');
        this.box = this.page.querySelector('.account-type-selection-container');
        this.buttons = [...this.box.querySelectorAll('.account-type-btn')];
        this.hovered = null;
        this.wire();
    }

    typeOf(btn) {
        const m = /prepareSignupForm\('(\w+)'\)/.exec(btn.getAttribute('onclick') || '');
        return m ? m[1] : '';
    }

    stacked() {
        return this.buttons.length > 1 && Math.abs(this.buttons[0].getBoundingClientRect().top - this.buttons[1].getBoundingClientRect().top) > 20;
    }

    home() {
        const b = mascotRel(this.box, this.stage);
        const first = mascotRel(this.buttons[0], this.stage);
        return { x: b.cx, y: first.top - 6 };
    }

    over(btn) {
        const r = mascotRel(btn, this.stage);
        return { x: r.cx, y: r.top - 6 };
    }

    layout() {
        if (this.m.traveling || this.busy) return;
        const p = this.hovered && !this.stacked() ? this.over(this.hovered) : this.home();
        this.m.place(p.x, p.y);
    }

    restPose() { return 'point-down'; }

    onShow() {
        this.hovered = null;
        this.m.setPose(null);
        this.m.facing(1);
        this.layout();
        requestAnimationFrame(() => this.layout());
        this.m.act('wave', 1400);
        this.guide(MASCOT_TYPE_INTRO, { step: 'Step 1' });
        setTimeout(() => { if (this.active && !this.hovered && !this.m.traveling && !this.busy) this.m.setPose('point-down'); }, 1500);
    }

    wire() {
        this.buttons.forEach(btn => {
            const enter = () => { if (this.active) this.explain(btn); };
            btn.addEventListener('pointerenter', enter);
            btn.addEventListener('focus', enter);
            btn.addEventListener('click', () => {
                if (!this.active) return;
                this.m.act('big-jump', 900);
                this.guide('Awesome choice! ✨', { step: 'Step 1', mood: 'good' });
            });
        });
        const leave = () => {
            clearTimeout(this.timers.leave);
            this.timers.leave = setTimeout(() => {
                if (!this.active || !this.hovered || this.box.matches(':hover') || this.box.contains(document.activeElement)) return;
                this.hovered = null;
                this.guide(MASCOT_TYPE_INTRO, { step: 'Step 1' });
                const p = this.home();
                this.go(p.x, p.y, { face: 1, pose: 'point-down' });
            }, 500);
        };
        this.box.addEventListener('pointerleave', leave);
        this.box.addEventListener('focusout', leave);
        if ('ResizeObserver' in window) new ResizeObserver(() => { if (this.active) this.layout(); }).observe(this.box);
    }

    explain(btn) {
        this.wake(true);
        clearTimeout(this.timers.leave);
        if (this.hovered === btn) return;
        this.hovered = btn;
        this.guide(`${MASCOT_TYPE_TIPS[this.typeOf(btn)] || ''} Tap it if that's you!`, { step: 'Step 1' });
        if (this.stacked()) {
            this.m.setPose('point-down');
            this.m.act('nod', 1200);
            return;
        }
        const p = this.over(btn);
        this.go(p.x, p.y, { pose: 'point-down' }).then(ok => { if (ok) this.m.act('nod', 1200); });
    }
}

/* ---------------- Register, step 2: the form ---------------- */
const MASCOT_FIELD_TIPS = {
    'signup-fullname-field': (team) => team
        ? "What's your team called? 🏆 Something like Student Council."
        : "What's your name? 😊 Type it the way your school knows it.",
    'signup-username-field': () => 'Now pick a cool @username! ✨ 4–20 lowercase letters, numbers, or . _ - * !',
    'signup-dob-field': () => "When's your birthday? 🎂 Tap the button to pick it.",
    'signup-subject-field': () => 'What do you teach? 📚',
    'signup-school-field': () => 'Which school do you go to? 🏫 Pick it from the list.',
    'signup-email-field': () => "Your school email, please! 📬 We'll send a code there, so use one you can open right now.",
    'signup-password-field': () => "Password time! 🙈 I'm turning around. Make it at least 5 characters.",
    'signup-confirm-field': () => 'One more time, just to be sure! Still not peeking 🙈',
};

class SignupMascotScene extends GuideMascotScene {
    constructor(m) {
        super(m);
        this.page = document.getElementById('signup-page');
        this.card = this.page.querySelector('.signup-form');
        this.agreements = this.card.querySelector('.agreements-card');
        this.registerBtn = this.card.querySelector('button[onclick^="handleSignup"]');
        this.target = null;
        this.wire();
    }

    sleepAfter() { return 90000; }
    isTeam() { return typeof currentSignupType !== 'undefined' && currentSignupType === 'team'; }

    fields() {
        return [...this.card.querySelectorAll('.signup-field')].filter(f => f.style.display !== 'none');
    }

    labelOf(field) {
        const label = field.querySelector('label');
        return label ? label.textContent.replace('*', '').trim() : '';
    }

    stepFor(target) {
        const list = this.fields();
        const total = list.length + 1;       // + the agreements
        if (!target) return '';
        if (target === this.agreements || target === this.registerBtn) return `Step ${total} of ${total}`;
        const i = list.indexOf(target);
        return i >= 0 ? `Step ${i + 1} of ${total}` : '';
    }

    nextAfter(field) {
        const list = this.fields();
        const next = list[list.indexOf(field) + 1];
        return next ? this.labelOf(next) : 'tick the three boxes below';
    }

    isSecret(target) {
        return !!target && (target.id === 'signup-password-field' || target.id === 'signup-confirm-field');
    }

    // Room beside the card for him (desktop), or does he stand on the fields?
    wide() {
        const c = mascotRel(this.card, this.stage);
        return this.stage.clientWidth - c.right >= this.m.w + 30;
    }

    spotFor(target) {
        const c = mascotRel(this.card, this.stage);
        if (!target) return { x: c.right - 34 - this.m.w / 2, y: c.top + this.m.h * 0.07, face: 1, pose: 'point-down' };
        const anchor = target === this.agreements || target === this.registerBtn
            ? target
            : (target.querySelector('.input-shell, .custom-dob-trigger') || target);
        const a = mascotRel(anchor, this.stage);
        if (this.wide()) {
            return { x: c.right + 20 + this.m.w / 2, y: a.top + Math.min(a.height, 60) - 2, face: -1, pose: 'point' };
        }
        return { x: a.right - 8 - this.m.w / 2, y: a.top + 3, face: 1, pose: 'point-down' };
    }

    restPose() {
        if (this.isSecret(this.target)) return 'away';
        return this.spotFor(this.target).pose;
    }

    restFace() { return this.spotFor(this.target).face; }

    layout() {
        if (this.m.traveling || this.busy) return;
        const p = this.spotFor(this.target);
        this.m.place(p.x, p.y);
        this.m.facing(p.face);
    }

    onShow() {
        this.target = null;
        this.m.setPose(null);
        this.layout();
        requestAnimationFrame(() => this.layout());
        this.m.act('wave', 1400);
        const first = this.fields()[0];
        this.guide(`Yay, let's make your account! 🎉 I'll walk you through it. Tap ${first ? this.labelOf(first) : 'the first box'} to start 👇`);
        setTimeout(() => { if (this.active && !this.target && !this.m.traveling && !this.busy) this.m.setPose('point-down'); }, 1500);
    }

    // Go and stand by a field (or the agreements, or the Register button).
    moveTo(target, text, opts = {}) {
        const wasAway = this.m.pose === 'away';
        this.target = target;
        this.guide(text, { step: this.stepFor(target), ...opts });
        const p = this.spotFor(target);
        const secret = this.isSecret(target);
        if (wasAway && !secret) this.m.turn(false);
        return this.go(p.x, p.y, { face: p.face, pose: secret ? undefined : p.pose }).then(ok => {
            if (ok && this.target === target && secret) this.m.turn(true);
            return ok;
        });
    }

    tipFor(target) {
        if (target === this.agreements) {
            const n = this.agreements.querySelectorAll('input[type="checkbox"]:checked').length;
            return `Almost done! 🎉 Read these and tick all three boxes. (${n} of 3)`;
        }
        if (target === this.registerBtn) return 'All set! 🚀 Tap Register to make your account!';
        const tip = MASCOT_FIELD_TIPS[target.id];
        return tip ? tip(this.isTeam()) : '';
    }

    wire() {
        const card = this.card;

        card.addEventListener('focusin', (e) => {
            if (!this.active) return;
            this.wake(true);
            const t = e.target === this.registerBtn ? this.registerBtn
                : e.target.closest('.signup-field, .agreements-card');
            if (!t || t === this.target) return;
            const input = t.querySelector('input:not([type="hidden"]), select');
            this.moveTo(t, this.tipFor(t));
            // Coming back to a field that's already filled in: say where it stands.
            if (input && input.value && t !== this.agreements) this.check(input, { cheer: false });
        });

        card.addEventListener('input', (e) => {
            if (!this.active || !(e.target instanceof HTMLInputElement)) return;
            const input = e.target;
            const secret = input.id === 'signupPassword' || input.id === 'signupConfirmPassword';
            if (!secret && !this.busy && !this.m.traveling && !this.timers.tick) {
                this.m.act('tick', 220);
                this.timers.tick = setTimeout(() => { this.timers.tick = null; }, 200);
            }
            clearTimeout(this.timers.check);
            this.timers.check = setTimeout(() => this.check(input), 700);
        });

        card.addEventListener('change', (e) => {
            if (!this.active) return;
            const t = e.target;
            if (t.tagName === 'SELECT') this.check(t);
            if (t.type === 'checkbox' && this.agreements.contains(t)) this.agreementChanged(t);
        });

        // The date of birth comes back from a modal as the button's label.
        const dobBtn = document.getElementById('dob-display-btn');
        if (dobBtn) new MutationObserver(() => {
            if (!this.active || !dobBtn.querySelector('.fa-check-circle')) return;
            const field = dobBtn.closest('.signup-field');
            const text = `Got it! 🎂 Next up: ${this.nextAfter(field)}.`;
            const cheer = () => this.m.act('big-jump', 900);
            if (this.target !== field) this.moveTo(field, text, { mood: 'good' }).then(ok => { if (ok) cheer(); });
            else { this.guide(text, { step: this.stepFor(field), mood: 'good' }); cheer(); }
        }).observe(dobBtn, { childList: true, subtree: true, characterData: true });

        // handleSignup found problems: go to the first one and stay until it's fixed.
        const summary = document.getElementById('signup-error-summary');
        if (summary) new MutationObserver(() => {
            if (!this.active || summary.hidden) return;
            const first = this.fields().find(f => f.classList.contains('has-error'))
                || (this.agreements.querySelector('.form-error-message') ? this.agreements : null);
            if (!first) return;
            const msg = first.querySelector('.form-error-message');
            this.m.act('stumble', 800);
            this.target = null;       // so the move always happens, even to the current field
            this.moveTo(first, `Oops! 😅 ${msg ? msg.textContent : this.tipFor(first)}`, { mood: 'error' }).then(ok => {
                if (ok && this.target === first && !this.isSecret(first)) this.m.setPose('think');
            });
        }).observe(summary, { attributes: true, attributeFilter: ['hidden'] });

        if ('ResizeObserver' in window) new ResizeObserver(() => { if (this.active) this.layout(); }).observe(card);
    }

    check(input, { cheer = true } = {}) {
        if (!this.active) return;
        const field = input.closest('.signup-field');
        if (!field || field !== this.target) return;
        const step = this.stepFor(field);
        const v = input.value;
        const secret = this.isSecret(field);
        const point = () => { if (!secret && !this.m.traveling && !this.busy) this.m.setPose(this.spotFor(field).pose); };
        const yay = () => { if (cheer && !this.m.traveling) this.m.act('jump', 650); };

        if (!v || !String(v).trim()) { point(); this.guide(this.tipFor(field), { step }); return; }

        if (input.id === 'signupPassword') {
            const label = (document.querySelector('#signup-pw-meter .pw-meter-label') || {}).textContent || '';
            const next = this.nextAfter(field);
            const lines = {
                'Too short': ['A little longer! It needs at least 5 characters 💪', 'warn'],
                'Weak': [`That works, but it's a bit weak. Try adding numbers or symbols! 💪 Or head to ${next}.`, ''],
                'Okay': [`Getting there! 👍 Next up: ${next}.`, 'good'],
                'Good': [`Nice password! 🔒 Next up: ${next}.`, 'good'],
                'Strong': [`Super strong password! 🔒✨ Next up: ${next}.`, 'good'],
            };
            const [line, mood] = lines[label] || lines['Okay'];
            this.guide(line, { step, mood });
            return;
        }
        if (input.id === 'signupConfirmPassword') {
            const pw = document.getElementById('signupPassword').value;
            if (v === pw) { this.guide(`They match! ✅ Next up: ${this.nextAfter(field)}.`, { step, mood: 'good' }); yay(); }
            else if (v.length >= pw.length) this.guide("Hmm, those don't match yet 🤔 Try again!", { step, mood: 'warn' });
            else this.guide(this.tipFor(field), { step });
            return;
        }

        const rule = typeof SIGNUP_FIELD_RULES !== 'undefined' ? SIGNUP_FIELD_RULES[input.id] : null;
        const problem = rule ? rule(v) : null;
        if (problem) {
            if (!this.m.traveling && !this.busy) this.m.setPose('think');
            this.guide(`Hmm 🤔 ${problem}`, { step, mood: 'warn' });
            return;
        }
        point();
        const val = String(v).trim();
        const next = this.nextAfter(field);
        let done;
        if (input.id === 'signupFullName') done = this.isTeam() ? 'Great team name! 🏆' : `Nice to meet you, ${mascotShort(val.split(/\s+/)[0], 16)}! 👋`;
        else if (input.id === 'signupUsername') done = `@${mascotShort(val, 20)} looks awesome! ✨`;
        else if (input.id === 'signupEmail') done = 'Perfect! 📧';
        else if (input.id === 'signupSubject') done = `${mascotShort(val, 20)}, cool! 😎`;
        else if (input.id === 'signupSchool') {
            const name = input.options && input.options[input.selectedIndex] ? input.options[input.selectedIndex].text : val;
            done = `${mascotShort(name, 34)}! Nice 🏫`;
        } else done = 'Looks good! 👍';
        this.guide(`${done} Next up: ${next}.`, { step, mood: 'good' });
        yay();
    }

    async agreementChanged(box) {
        const n = this.agreements.querySelectorAll('input[type="checkbox"]:checked').length;
        if (n < 3) {
            if (this.target !== this.agreements) this.moveTo(this.agreements, this.tipFor(this.agreements));
            else {
                this.guide(this.tipFor(this.agreements), { step: this.stepFor(this.agreements) });
                if (box.checked && !this.m.traveling) this.m.act('nod', 1200);
            }
            return;
        }
        // All three: a little dance, then over to the Register button.
        this.guide('All three! 🎉', { step: this.stepFor(this.agreements), mood: 'good' });
        this.busy = true;
        if (this.m.pose !== 'away') this.m.setPose('dance');
        await mascotSleepMs(2200);
        this.busy = false;
        if (!this.active) return;
        this.moveTo(this.registerBtn, this.tipFor(this.registerBtn), { mood: 'good' });
    }
}

/* ------------------------------------------------------------------ */
/* Wiring                                                              */
/* ------------------------------------------------------------------ */
const MASCOT_SCENE_TYPES = {
    login: LoginMascotScene,
    'account-type': AccountTypeMascotScene,
    signup: SignupMascotScene,
    home: HomeMascotScene,
};

function mascotActivity() {
    mascotLastActivity = Date.now();
    mascotScenes.forEach(s => { if (s.active && s.asleep) s.wake(); });
}

function applyMascotConfig(config) {
    if (!config || typeof config !== 'object') return;
    mascotConfig = {
        enabled: (config.enabled && typeof config.enabled === 'object') ? config.enabled : {},
        lines: (config.lines && typeof config.lines === 'object') ? config.lines : {},
        intervals: (config.intervals && typeof config.intervals === 'object') ? config.intervals : {},
    };
    mascotScenes.forEach(s => { s.chatterStale = true; });
}

// The last answer is remembered so a returning visitor's page doesn't wait on the
// fetch before he appears.
function setMascotSpots(enabled) {
    const on = MASCOT_SPOTS.filter(spot => enabled && enabled[spot] === true);
    MASCOT_SPOTS.forEach(spot =>
        document.documentElement.classList.toggle(`mascot-${spot}`, on.includes(spot)));
    try { localStorage.setItem(MASCOT_ON_KEY, JSON.stringify(on)); } catch (e) { /* private mode */ }
    if (on.length) startMascots(on);
}

function mountMascots() {
    try {
        const remembered = JSON.parse(localStorage.getItem(MASCOT_ON_KEY) || '[]');
        if (Array.isArray(remembered) && remembered.length) {
            setMascotSpots(Object.fromEntries(remembered.map(spot => [spot, true])));
        }
    } catch (e) { /* private mode or junk: wait for the server */ }

    fetch(`${API_BASE_URL}/api/mascot/lines`)
        .then(r => (r.ok ? r.json() : null))
        .then(config => {
            if (!config) return;
            applyMascotConfig(config);
            setMascotSpots(config.enabled);
        })
        .catch(() => { /* offline: keep whatever was remembered */ });
}

// Builds a spot's rigs (and so first loads the art) only once that spot is on.
function startMascots(spots) {
    document.querySelectorAll('.apex-mascot[data-mascot]').forEach(root => {
        if (root.dataset.mounted || !spots.includes(root.dataset.mascot)) return;
        const Scene = MASCOT_SCENE_TYPES[root.dataset.scene] || HomeMascotScene;
        mascotScenes.push(new Scene(new Mascot(root)));
    });
    if (mascotTicker) return;
    mascotTicker = setInterval(() => {
        const now = Date.now();
        mascotScenes.forEach(s => s.tick(now));
    }, 250);

    let lastMove = 0;
    const activity = () => mascotActivity();
    ['pointerdown', 'keydown', 'wheel', 'scroll'].forEach(type =>
        document.addEventListener(type, activity, { passive: true, capture: true }));
    document.addEventListener('pointermove', () => {
        const now = Date.now();
        if (now - lastMove > 300) { lastMove = now; activity(); }
    }, { passive: true, capture: true });
    // Coming back from another window isn't "idle for ages": don't fall asleep on arrival.
    const back = () => { mascotLastActivity = Date.now(); };
    document.addEventListener('visibilitychange', () => { if (!document.hidden) back(); });
    window.addEventListener('focus', back);

    let resizeFrame = null;
    window.addEventListener('resize', () => {
        cancelAnimationFrame(resizeFrame);
        resizeFrame = requestAnimationFrame(() => mascotScenes.forEach(s => { if (s.active) s.layout(); }));
    });
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mountMascots);
else mountMascots();

/* ------------------------------------------------------------------ */
/* Admin Panel -> Mascot                                               */
/* ------------------------------------------------------------------ */
// The register guide writes its own words, so only these two take lines.
const MASCOT_LINE_SPOTS = ['login', 'home'];

function loadMascotLinesAdmin() {
    if (!document.getElementById('admin-mascot-editor')) return;
    fetch(`${API_BASE_URL}/api/mascot/lines`)
        .then(r => r.json())
        .then(renderMascotAdmin)
        .catch(() => showToast('Could not load the mascot settings', 'error'));
}

function renderMascotAdmin(config) {
    applyMascotConfig(config);
    setMascotSpots(config.enabled);
    MASCOT_SPOTS.forEach(spot => {
        document.getElementById(`admin-mascot-${spot}-on`).checked = !!(config.enabled && config.enabled[spot]);
    });
    MASCOT_LINE_SPOTS.forEach(spot => {
        const custom = config.lines && config.lines[spot];
        document.getElementById(`admin-mascot-${spot}`).value = (Array.isArray(custom) ? custom : []).join('\n');
        const interval = config.intervals ? config.intervals[spot] : MASCOT_DEFAULT_INTERVAL_S;
        document.getElementById(`admin-mascot-${spot}-interval`).value = interval === null || interval === undefined ? '' : interval;
    });
}

// A toggle saves on its own, straight away, without touching unsaved line edits.
function adminToggleMascotSpot(spot, checkbox) {
    checkbox.disabled = true;
    fetch(`${API_BASE_URL}/api/admin/mascot/lines`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ enabled: { [spot]: checkbox.checked } })
    })
    .then(r => r.json())
    .then(d => {
        if (!d.ok) throw new Error(d.error);
        setMascotSpots(d.enabled);
        const where = { login: 'the login page', register: 'the register pages', home: 'the home header' }[spot];
        showToast(`Mascot ${d.enabled[spot] ? 'shown on' : 'hidden from'} ${where}`, 'success');
    })
    .catch(err => {
        checkbox.checked = !checkbox.checked;
        showToast((err && err.message) || 'Failed to save', 'error');
    })
    .finally(() => { checkbox.disabled = false; });
}

function adminSaveMascotLines(button) {
    const lines = {};
    const intervals = {};
    MASCOT_LINE_SPOTS.forEach(spot => {
        lines[spot] = document.getElementById(`admin-mascot-${spot}`).value
            .split('\n').map(s => s.trim()).filter(Boolean);
        const raw = document.getElementById(`admin-mascot-${spot}-interval`).value.trim();
        intervals[spot] = raw === '' ? null : raw;
    });

    button.disabled = true;
    const label = button.textContent;
    button.textContent = 'Saving...';
    fetch(`${API_BASE_URL}/api/admin/mascot/lines`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiToken}` },
        body: JSON.stringify({ lines, intervals })
    })
    .then(r => r.json())
    .then(d => {
        if (!d.ok) { showToast(d.error || 'Failed to save', 'error'); return; }
        renderMascotAdmin(d);
        showToast('Mascot lines saved', 'success');
    })
    .catch(() => showToast('Failed to save', 'error'))
    .finally(() => { button.disabled = false; button.textContent = label; });
}


// --- Sheets close the way they opened ----------------------------------------
// On a phone these dialogs rise from the bottom edge, so dismissing one should
// send it back down rather than blink it out of existence. Rather than rewrite
// every close function (they are called from inline onclick, the backdrop
// handler, the back button and each other), each one is wrapped: the wrapper
// plays the slide-down, then hands over to the original, which does the real
// work. Desktop and reduced-motion callers go straight through.
const SHEET_MODAL_CLOSERS = [
    ['lounge-details-modal', 'closeLoungeDetailsModal'],
    ['lounge-members-modal', 'closeLoungeMembersModal'],
    ['create-channel-modal', 'closeCreateChannelModal'],
    ['edit-channel-modal', 'closeEditChannelModal'],
    ['channel-privacy-modal', 'closeChannelPrivacyModal'],
    ['member-title-modal', 'closeMemberTitleModal'],
    ['invite-lounge-member-modal', 'closeInviteUserModal'],
    ['quick-lounge-modal', 'closeQuickCreateLounge'],
    ['following-modal', 'closeFollowingModal'],
];
const SHEET_CLOSE_MS = 240;

function sheetAnimationsOn() {
    return document.documentElement.classList.contains('ui-phone') &&
        !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

SHEET_MODAL_CLOSERS.forEach(([id, fnName]) => {
    const original = window[fnName];
    if (typeof original !== 'function') return;
    window[fnName] = function (...args) {
        const el = document.getElementById(id);
        // Already dismissing: the timeout below will finish the job. A second
        // call must not short-circuit it -- a backdrop tap reaches both the
        // dialog's own onclick and the document-wide handler, and letting the
        // second one through hid the sheet instantly, animation and all.
        if (el && el.dataset.sheetClosing) return;
        // Already gone, or not a sheet right now: nothing to play.
        if (!el || el.classList.contains('hidden') || !sheetAnimationsOn()) {
            return original.apply(this, args);
        }
        el.dataset.sheetClosing = '1';
        el.classList.add('is-closing');
        setTimeout(() => {
            el.classList.remove('is-closing');
            delete el.dataset.sheetClosing;
            original.apply(this, args);
        }, SHEET_CLOSE_MS);
    };
});

// Download page: the iPhone install walkthrough (#dl-install). The drawing is all
// CSS keyed off .ios-guide[data-step]; this only moves that number. The step
// buttons jump straight to a step, Back/Next walk it, and tapping the marked spot
// on the phone does what the step says -- goes on to the next one.
function setIosGuideStep(guide, step) {
    const total = Number(guide.dataset.steps);
    guide.dataset.step = String(step);
    guide.querySelectorAll('[data-ios-step]').forEach((btn) => {
        if (Number(btn.dataset.iosStep) === step) btn.setAttribute('aria-current', 'step');
        else btn.removeAttribute('aria-current');
    });
    guide.querySelector('[data-ios-nav="prev"]').disabled = step === 1;
    guide.querySelector('[data-ios-nav="next"]').textContent = step === total ? 'Start over' : 'Next';
    guide.querySelector('.ios-count').textContent = `Step ${step} of ${total}`;
}

document.addEventListener('click', (e) => {
    const guide = e.target.closest('.ios-guide');
    if (!guide) return;
    const total = Number(guide.dataset.steps);
    const current = Number(guide.dataset.step);
    const pick = e.target.closest('[data-ios-step]');
    const nav = e.target.closest('[data-ios-nav]');
    const target = e.target.closest('.iph [data-target]');
    let step;
    if (pick) step = Number(pick.dataset.iosStep);
    else if (nav && nav.dataset.iosNav === 'prev') step = Math.max(1, current - 1);
    else if (nav) step = current === total ? 1 : current + 1;
    else if (target && Number(target.dataset.target) === current) step = current === total ? 1 : current + 1;
    else return;
    if (step !== current) setIosGuideStep(guide, step);
});

// Updates for installed apps that can't update themselves. The site asks for
// them, since it's what they load:
//
//   Android  The APK is a thin shell around this site (a Trusted Web Activity).
//            Each APK opens /?apk=<its version>; the very first one opened plain
//            "/", which counts as 1. Android marks a launch from the app with the
//            android-app:// referrer. Offered when /api/app-release is ahead.
//   Windows  Desktop apps from before the self-updater (desktop/src-tauri/src/
//            updater.rs). Every Tauri build exposes __TAURI_INTERNALS__ to the
//            pages it loads -- no browser does -- and builds with the updater
//            also set window.apexDesktop. Tauri without that marker is an old
//            build that will never hear about updates any other way.
//
// Both are read right now, as the script loads: the router rewrites the address
// during boot and the ?apk= would be gone by the time anything else looked.
const ANDROID_APP_VERSION = (() => {
    try {
        if (!document.referrer.startsWith('android-app://net.apexsns.app')) {
            return Number(sessionStorage.getItem('apex-android-app')) || 0;
        }
        const version = Number(new URLSearchParams(location.search).get('apk')) || 1;
        sessionStorage.setItem('apex-android-app', String(version));
        return version;
    } catch {
        return 0; // storage blocked: just don't offer updates
    }
})();
const IN_LEGACY_DESKTOP_APP = !!window.__TAURI_INTERNALS__ && !window.apexDesktop;
const APP_UPDATE_SNOOZE_KEY = 'apex-app-update-snooze';
const APP_UPDATE_SNOOZE_MS = 3 * 24 * 60 * 60 * 1000;

async function checkAppUpdate() {
    let offer = null;
    if (IN_LEGACY_DESKTOP_APP) {
        offer = {
            release: 'desktop-updater',
            url: '/download/windows',
            text: 'A new version of the APEX app is ready, and from now on it keeps itself up to date. ' +
                'Click <strong>Update</strong> to download it, open it from your Downloads, then delete this old copy.',
        };
    } else if (ANDROID_APP_VERSION) {
        try {
            const res = await fetch(`${API_BASE_URL}/api/app-release`, { cache: 'no-store' });
            const latest = (await res.json()).android;
            if (latest && latest.version > ANDROID_APP_VERSION) {
                offer = {
                    release: `android-${latest.version}`,
                    url: '/download/android',
                    text: 'A new version of the APEX app is ready. Tap <strong>Update</strong>, open the file when it ' +
                        'finishes downloading, then tap <strong>Update</strong> when Android asks.',
                };
            }
        } catch { /* offline: try again next launch */ }
    }
    if (!offer) return;

    // "Later" holds this release off for a few days, then reminds again.
    try {
        const snooze = JSON.parse(localStorage.getItem(APP_UPDATE_SNOOZE_KEY) || 'null');
        if (snooze && snooze.release === offer.release && Date.now() < snooze.until) return;
    } catch { /* storage blocked: just ask */ }

    const modal = document.getElementById('app-update-modal');
    modal.dataset.release = offer.release;
    modal.dataset.url = offer.url;
    document.getElementById('app-update-text').innerHTML = offer.text;
    modal.classList.remove('hidden');
}

function dismissAppUpdate() {
    const modal = document.getElementById('app-update-modal');
    modal.classList.add('hidden');
    try {
        localStorage.setItem(APP_UPDATE_SNOOZE_KEY, JSON.stringify({
            release: modal.dataset.release,
            until: Date.now() + APP_UPDATE_SNOOZE_MS,
        }));
    } catch { /* private mode */ }
}

// Neither can replace itself: Android won't let an app from outside the Play
// Store do it silently (its installer asks to update over the top, keeping
// everything, because the APK is signed with the same key), and an old desktop
// build has no code to. So this downloads the new one and the person opens it.
function startAppUpdate() {
    const modal = document.getElementById('app-update-modal');
    modal.classList.add('hidden');
    window.location.href = modal.dataset.url;
}

// A little after boot, so it never competes with the app's own first paint.
document.addEventListener('DOMContentLoaded', () => setTimeout(checkAppUpdate, 4000));
